// Secrets/runtime bindings MUST come from the Worker environment.
// No credential is stored in source code.
const TELEGRAM_CONFIG = Object.freeze({
    tokenEnvKeys: ['TELEGRAM_TOKEN', 'BOT_TOKEN'],
    defaultToken: '',
    apiBaseUrl: 'https://api.telegram.org',
    fileBaseUrl: 'https://api.telegram.org/file'
});
const DATABASE_CONFIG = Object.freeze({ bindingName: 'DB' });
const KV_CONFIG = Object.freeze({ bindingName: 'B' });
const ADMIN_CONFIG = Object.freeze({ envKey: 'ADMIN_IDS', defaultIds: ['YOUR_ADMIN_TELEGRAM_ID'] });
const USAGE_LIMIT_CONFIG = Object.freeze({ enabled: false, perUser: {}, perFeature: {} });
const FEATURE_COST_CONFIG = Object.freeze({});

const TELEGRAM_TOKEN = TELEGRAM_CONFIG.defaultToken;
let RUNTIME_TELEGRAM_TOKEN = '';
let RUNTIME_ENV = null;

// Token bot bersifat sama untuk seluruh request pada satu Worker deployment.
// Diset dari binding runtime agar helper lama yang tidak menerima env tetap aman.
function setRuntimeTelegramToken(env) {
    RUNTIME_ENV = env || null;
    RUNTIME_TELEGRAM_TOKEN = String(env?.TELEGRAM_TOKEN || env?.BOT_TOKEN || TELEGRAM_TOKEN || '').trim();
}
const KV_BINDING_NAME = KV_CONFIG.bindingName;

function getTelegramToken(env) {
    const runtime = env || null;
    return String(runtime?.[TELEGRAM_CONFIG.tokenEnvKeys[0]] || runtime?.[TELEGRAM_CONFIG.tokenEnvKeys[1]] || RUNTIME_TELEGRAM_TOKEN || TELEGRAM_CONFIG.defaultToken || '').trim();
}

function telegramApiUrl(method, env = null) {
    const token = getTelegramToken(env);
    return `${TELEGRAM_CONFIG.apiBaseUrl}/bot${token}/${method}`;
}

function telegramFileUrl(path, env = null) {
    const token = getTelegramToken(env);
    return `${TELEGRAM_CONFIG.fileBaseUrl}/bot${token}/${path}`;
}

function getAdminIds(env) {
    const raw = env?.[ADMIN_CONFIG.envKey];
    if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
        return String(raw).split(/[,;\s]+/).map(v => v.trim()).filter(Boolean);
    }
    return ADMIN_CONFIG.defaultIds.map(String);
}

