// ============================================================
// Lokasi: Setelah HYBRID_CONFIG, sebelum AUTO-CLASSIFY SECTION




// ============================================================
// 🆕 FALLBACK STATISTICS TRACKER
// ============================================================
// Untuk tracking seberapa sering fallback dipakai

const fallbackStats = {
    totalSoal: 0,
    totalFallback: 0,
    totalAutoCreated: 0,
    totalMissing: 0,
    lastReset: Date.now()
};

function trackFallback(masterIds) {
    fallbackStats.totalSoal++;
    fallbackStats.totalFallback += (masterIds.fallbackItems || []).length;
    fallbackStats.totalAutoCreated += (masterIds.createdItems || []).length;
    fallbackStats.totalMissing += (masterIds.missingItems || []).length;
}

// ============================================================
// 🆕 GLOBAL CALLBACK CONTEXT
// Menyimpan context callback per-request
// Lokasi: Setelah trackFallback()
// ============================================================

// Variabel global untuk menyimpan callback context sementara
let CURRENT_CALLBACK_CONTEXT = null;

// Simpan callback context (dipanggil saat callback masuk)
function setCallbackContext(context) {
    CURRENT_CALLBACK_CONTEXT = context;
}

// Ambil message_id dari callback (untuk edit pesan)
function getCallbackMessageId() {
    return CURRENT_CALLBACK_CONTEXT?.message?.message_id || null;
}

// Ambil chat_id dari callback
function getCallbackChatId() {
    return CURRENT_CALLBACK_CONTEXT?.message?.chat?.id || null;
}

