function constantTimeEqual(a,b){const x=String(a||''),y=String(b||'');if(x.length!==y.length)return false;let diff=0;for(let i=0;i<x.length;i++)diff|=x.charCodeAt(i)^y.charCodeAt(i);return diff===0;}
const SYSTEM_PERMISSION_DEFAULTS = Object.freeze({
    admin:['*'],
    teacher:['question.create','question.update','materi.create','materi.update','learning.use'],
    user:['learning.use','question.answer','materi.read']
});

function normalizePlan(value){const v=String(value||'FREE').trim().toUpperCase();return ['FREE','PREMIUM'].includes(v)?v:'FREE';}
function normalizeFeatureCost(value){return Math.max(0,Math.floor(Number(value)||0));}
function getFeatureCost(feature, fallback=0){
    const key=String(feature||'').trim().toUpperCase();
    const cfg=FEATURE_COST_CONFIG?.[key] ?? FEATURE_COST_CONFIG?.[feature];
    return normalizeFeatureCost(cfg ?? fallback);
}
async function getFeatureCostFromDB(db,feature,fallback=0){try{const r=await db.prepare(`SELECT token_cost FROM system_feature_costs WHERE feature=? AND enabled=1 LIMIT 1`).bind(String(feature||'').toUpperCase()).first();return normalizeFeatureCost(r?.token_cost ?? getFeatureCost(feature,fallback));}catch(e){return getFeatureCost(feature,fallback);}}
async function upsertFeatureCost(db,data={}){const feature=String(data.feature||'').trim().toUpperCase(),cost=normalizeFeatureCost(data.tokenCost);if(!feature)return{success:false,error:'feature wajib'};try{const now=new Date().toISOString();await db.prepare(`INSERT INTO system_feature_costs (feature,token_cost,free_daily_limit,premium_enabled,enabled,updated_at) VALUES (?,?,?,?,?,?) ON CONFLICT(feature) DO UPDATE SET token_cost=excluded.token_cost,free_daily_limit=excluded.free_daily_limit,premium_enabled=excluded.premium_enabled,enabled=excluded.enabled,updated_at=excluded.updated_at`).bind(feature,cost,Math.max(0,Number(data.freeDailyLimit)||0),data.premiumEnabled===false?0:1,data.enabled===false?0:1,now).run();return{success:true,feature,tokenCost:cost};}catch(e){return{success:false,error:e.message};}}
function getUsageWindowKey(now=new Date()){const d=new Date(now);return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;}
function hasPermission(role, permission){
    const r=String(role||'user').toLowerCase(), p=String(permission||'').trim().toLowerCase();
    if(!SYSTEM_ROLES.includes(r)||!p)return false;
    const list=SYSTEM_PERMISSION_DEFAULTS[r]||[]; return list.includes('*')||list.includes(p);
}
function validateAdminAction(role,permission){return hasPermission(role,permission);}

async function ensureTokenWallet(db,userId,plan='FREE'){
    const uid=String(userId||'').trim();if(!uid)return{success:false,error:'userId wajib'};
    try{const now=new Date().toISOString(),p=normalizePlan(plan);
        await db.prepare(`INSERT INTO system_token_wallets (user_id,balance,plan,status,monthly_used,monthly_reset_at,created_at,updated_at) VALUES (?,0,?,'ACTIVE',0,?, ?,?) ON CONFLICT(user_id) DO NOTHING`).bind(uid,p,now,now,now).run();
        const row=await db.prepare(`SELECT * FROM system_token_wallets WHERE user_id=? LIMIT 1`).bind(uid).first();
        return{success:true,wallet:row};
    }catch(e){return{success:false,error:e.message};}
}
async function setTokenBalance(db,userId,balance,plan='FREE',actorUserId=null){
    const uid=String(userId||'').trim(), amount=Math.max(0,Math.floor(Number(balance)||0)); if(!uid)return{success:false,error:'userId wajib'};
    try{await ensureTokenWallet(db,uid,plan);const now=new Date().toISOString();const r=await db.prepare(`UPDATE system_token_wallets SET balance=?,plan=?,updated_at=? WHERE user_id=?`).bind(amount,normalizePlan(plan),now,uid).run();await recordSystemAuditLog(db,{actorUserId,action:'TOKEN_BALANCE_SET',entityType:'user',entityId:uid,details:{balance:amount,plan},success:true});return{success:true,changes:r.meta?.changes??0,balance:amount};}catch(e){return{success:false,error:e.message};}
}
async function getEffectiveTokenBalance(db,userId){
    const uid=String(userId||'').trim();if(!uid)return{success:false,error:'userId wajib'};
    try{const w=await ensureTokenWallet(db,uid);if(!w.success)return w;return{success:true,balance:Number(w.wallet?.balance||0),plan:normalizePlan(w.wallet?.plan)}}catch(e){return{success:false,error:e.message};}
}
async function debitTokenAtomic(db,data={}){
    const uid=String(data.userId||'').trim(), amount=normalizeFeatureCost(data.amount), feature=String(data.feature||'UNKNOWN');
    if(!uid||amount<=0)return{success:false,error:'userId dan amount wajib valid'};
    try{
        await ensureTokenWallet(db,uid); const now=new Date().toISOString();
        const beforeRow=await db.prepare(`SELECT balance FROM system_token_wallets WHERE user_id=? AND status='ACTIVE'`).bind(uid).first();
        const before=Number(beforeRow?.balance||0);
        const r=await db.prepare(`UPDATE system_token_wallets SET balance=balance-?,monthly_used=monthly_used+?,updated_at=? WHERE user_id=? AND status='ACTIVE' AND balance>=?`).bind(amount,amount,now,uid,amount).run();
        if(!(r.meta?.changes>0))return{success:false,error:'Saldo token tidak cukup atau wallet tidak aktif',balance:before};
        const after=before-amount,id=await generateId(db,'TOK','system_token_ledger');
        try{await db.prepare(`INSERT INTO system_token_ledger (id,user_id,feature,amount,balance_before,balance_after,transaction_type,reference_id,metadata,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)`).bind(id,uid,feature,amount,before,after,'DEBIT',data.referenceId||null,data.metadata?JSON.stringify(data.metadata):null,now).run();}
        catch(e){await db.prepare(`UPDATE system_token_wallets SET balance=balance+?,monthly_used=CASE WHEN monthly_used>=? THEN monthly_used-? ELSE 0 END,updated_at=? WHERE user_id=?`).bind(amount,amount,amount,new Date().toISOString(),uid).run();throw e;}
        await recordSystemAuditLog(db,{actorUserId:data.actorUserId||uid,action:'TOKEN_DEBIT',entityType:'token',entityId:id,details:{feature,amount,balance:after},success:true});
        return{success:true,id,balance:after};
    }catch(e){return{success:false,error:e.message};}
}
async function creditTokenAtomic(db,data={}){
    const uid=String(data.userId||'').trim(), amount=normalizeFeatureCost(data.amount), feature=String(data.feature||'TOPUP');
    if(!uid||amount<=0)return{success:false,error:'userId dan amount wajib valid'};
    try{
        await ensureTokenWallet(db,uid); const now=new Date().toISOString();
        const beforeRow=await db.prepare(`SELECT balance FROM system_token_wallets WHERE user_id=? AND status='ACTIVE'`).bind(uid).first();
        const before=Number(beforeRow?.balance||0);
        const r=await db.prepare(`UPDATE system_token_wallets SET balance=balance+?,updated_at=? WHERE user_id=? AND status='ACTIVE'`).bind(amount,now,uid).run();
        if(!(r.meta?.changes>0))return{success:false,error:'Wallet tidak aktif'};
        const after=before+amount,id=await generateId(db,'TOK','system_token_ledger');
        try{await db.prepare(`INSERT INTO system_token_ledger (id,user_id,feature,amount,balance_before,balance_after,transaction_type,reference_id,metadata,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)`).bind(id,uid,feature,amount,before,after,'CREDIT',data.referenceId||null,data.metadata?JSON.stringify(data.metadata):null,now).run();}
        catch(e){await db.prepare(`UPDATE system_token_wallets SET balance=balance-?,updated_at=? WHERE user_id=? AND status='ACTIVE' AND balance>=?`).bind(amount,new Date().toISOString(),uid,amount).run();throw e;}
        await recordSystemAuditLog(db,{actorUserId:data.actorUserId||uid,action:'TOKEN_CREDIT',entityType:'token',entityId:id,details:{feature,amount,balance:after},success:true});
        return{success:true,id,balance:after};
    }catch(e){return{success:false,error:e.message};}
}
async function checkAndConsumeUsageLimit(db,data={}){
    const uid=String(data.userId||'').trim(),feature=String(data.feature||'').trim().toUpperCase(),limit=Math.max(0,Math.floor(Number(data.limit)||0));if(!uid||!feature)return{allowed:false,error:'userId dan feature wajib'};
    if(limit===0)return{allowed:true,unlimited:true};
    try{const key=getUsageWindowKey(),id=await generateId(db,'USE','system_usage_limits');const now=new Date().toISOString();await db.prepare(`INSERT INTO system_usage_limits (id,user_id,feature,window_key,used_count,limit_count,created_at,updated_at) VALUES (?,?,?,?,0,?,?,?) ON CONFLICT(id) DO NOTHING`).bind(id,uid,feature,key,limit,now,now).run();
        let row=await db.prepare(`SELECT * FROM system_usage_limits WHERE user_id=? AND feature=? AND window_key=? LIMIT 1`).bind(uid,feature,key).first();
        if(!row){await db.prepare(`INSERT INTO system_usage_limits (id,user_id,feature,window_key,used_count,limit_count,created_at,updated_at) VALUES (?,?,?,?,1,?,?,?)`).bind(id,uid,feature,key,limit,now,now).run();return{allowed:true,used:1,limit};}
        if(Number(row.used_count)>=Number(row.limit_count||limit))return{allowed:false,used:Number(row.used_count),limit:Number(row.limit_count||limit),error:'Batas penggunaan tercapai'};
        const r=await db.prepare(`UPDATE system_usage_limits SET used_count=used_count+1,updated_at=? WHERE id=? AND used_count<limit_count`).bind(now,row.id).run();return r.meta?.changes>0?{allowed:true,used:Number(row.used_count)+1,limit:Number(row.limit_count||limit)}:{allowed:false,error:'Batas penggunaan tercapai'};
    }catch(e){return{allowed:false,error:e.message};}
}
async function recordSystemAuditLog(db,data={}){try{const id=await generateId(db,'AUD','system_audit_log'),now=new Date().toISOString();await db.prepare(`INSERT INTO system_audit_log (id,actor_user_id,actor_role,action,entity_type,entity_id,success,details,created_at) VALUES (?,?,?,?,?,?,?,?,?)`).bind(id,data.actorUserId||null,data.actorRole||null,String(data.action||'UNKNOWN'),data.entityType||null,data.entityId||null,data.success===false?0:1,data.details?JSON.stringify(data.details):null,now).run();return{success:true,id};}catch(e){return{success:false,error:e.message};}}
async function getBotConfig(db,role){try{return await db.prepare(`SELECT * FROM system_bot_config WHERE bot_role=? LIMIT 1`).bind(String(role||'ADMIN').toUpperCase()).first();}catch(e){return null;}}
async function upsertBotConfig(db,data={}){const role=String(data.botRole||'ADMIN').toUpperCase();if(!['ADMIN','USER'].includes(role))return{success:false,error:'botRole tidak valid'};try{const now=new Date().toISOString();const envKey=String(data.botTokenEnv||`TELEGRAM_${role}_BOT_TOKEN`).trim();await db.prepare(`INSERT INTO system_bot_config (id,bot_role,bot_token_env,enabled,shared_db,created_at,updated_at) VALUES (?,?,?,?,?,?,?) ON CONFLICT(bot_role) DO UPDATE SET bot_token_env=excluded.bot_token_env,enabled=excluded.enabled,shared_db=excluded.shared_db,updated_at=excluded.updated_at`).bind(data.id||await generateId(db,'BOT','system_bot_config'),role,envKey,data.enabled===false?0:1,data.sharedDb===false?0:1,now,now).run();return{success:true,role};}catch(e){return{success:false,error:e.message};}}
async function isBotAuthorized(env,requiredRole){return authorizeBotRole(env,requiredRole);}
function buildSecurityPolicy(){return Object.freeze({sqlParameterized:true,secretPolicy:'ENV_ONLY',credentialPlaceholderPrefix:'YOUR_',selfRoleChangeBlocked:true,externalWebhookSignatureRequired:true});}
function buildProductionReadiness(env){const c=getCredentialReadiness(env||{});return{credentials:c,allRequiredConfigured:Object.values(c).every(Boolean),releaseGate:'BLOCKED_UNTIL_EXTERNAL_TESTS_PASS',security:buildSecurityPolicy()};}

