function resolveExternalCredential(env, key, placeholder = '') {
    const value = env?.[key];
    if (value === undefined || value === null || String(value).trim() === '') return {configured:false,value:placeholder};
    const text = String(value).trim();
    return {configured: text !== placeholder && !/^YOUR_[A-Z0-9_]+$/.test(text), value:text};
}
function isPlaceholderCredential(value) { return /^YOUR_[A-Z0-9_]+$/.test(String(value||'').trim()); }

// ============================================================
// CENTRALIZED CREDENTIAL HUB
// Satu pintu untuk seluruh credential eksternal. Nilai rahasia
// tetap berada di Cloudflare Variables/Secrets, bukan source code.
// Mendukung nama baru *_API_KEY sekaligus nama lama AI_KEY_*.
// ============================================================
const CREDENTIAL_ENV_KEYS = Object.freeze({
    telegram: Object.freeze({ token: ['TELEGRAM_TOKEN','BOT_TOKEN'] }),
    ai: Object.freeze({
        gemini: ['GEMINI_API_KEY','AI_KEY_GEMINI'],
        groq: ['GROQ_API_KEY','AI_KEY_GROQ'],
        cerebras: ['CEREBRAS_API_KEY','AI_KEY_CEREBRAS'],
        openrouter: ['OPENROUTER_API_KEY','AI_KEY_OPENROUTER'],
        mistral: ['MISTRAL_API_KEY','AI_KEY_MISTRAL'],
        cohere: ['COHERE_API_KEY','AI_KEY_COHERE'],
        sambanova: ['SAMBANOVA_API_KEY','AI_KEY_SAMBANOVA'],
        chutes: ['CHUTES_API_KEY','AI_KEY_CHUTES'],
        siliconflow: ['SILICONFLOW_API_KEY','AI_KEY_SILICONFLOW'],
        together: ['TOGETHER_API_KEY','AI_KEY_TOGETHER'],
        huggingface: ['HUGGINGFACE_API_KEY','HF_API_KEY','AI_KEY_HUGGINGFACE'],
        cloudflare: ['CLOUDFLARE_API_TOKEN','CF_API_TOKEN','AI_KEY_CLOUDFLARE']
    }),
    cloudflare: Object.freeze({ accountId: ['CLOUDFLARE_ACCOUNT_ID','CF_ACCOUNT_ID'], apiToken: ['CLOUDFLARE_API_TOKEN','CF_API_TOKEN'] }),
    tripay: Object.freeze({
        merchantCode: ['TRIPAY_MERCHANT_CODE'], apiKey: ['TRIPAY_API_KEY'],
        privateKey: ['TRIPAY_PRIVATE_KEY'], webhookSecret: ['TRIPAY_WEBHOOK_SECRET']
    })
});

function firstConfiguredEnv(env, keys = [], placeholder = '') {
    for (const key of keys) {
        const cfg = resolveExternalCredential(env, key, placeholder);
        if (cfg.configured) return cfg.value;
    }
    return '';
}

function getCredentialHub(env = null) {
    const runtimeEnv = env || RUNTIME_ENV || null;
    const ai = {};
    for (const [provider, keys] of Object.entries(CREDENTIAL_ENV_KEYS.ai)) {
        ai[provider] = firstConfiguredEnv(runtimeEnv, keys);
    }
    return Object.freeze({
        telegram: Object.freeze({ token: firstConfiguredEnv(runtimeEnv, CREDENTIAL_ENV_KEYS.telegram.token) }),
        ai: Object.freeze(ai),
        cloudflare: Object.freeze({
            accountId: firstConfiguredEnv(runtimeEnv, CREDENTIAL_ENV_KEYS.cloudflare.accountId),
            apiToken: firstConfiguredEnv(runtimeEnv, CREDENTIAL_ENV_KEYS.cloudflare.apiToken)
        }),
        tripay: Object.freeze({
            merchantCode: firstConfiguredEnv(runtimeEnv, CREDENTIAL_ENV_KEYS.tripay.merchantCode),
            apiKey: firstConfiguredEnv(runtimeEnv, CREDENTIAL_ENV_KEYS.tripay.apiKey),
            privateKey: firstConfiguredEnv(runtimeEnv, CREDENTIAL_ENV_KEYS.tripay.privateKey),
            webhookSecret: firstConfiguredEnv(runtimeEnv, CREDENTIAL_ENV_KEYS.tripay.webhookSecret)
        })
    });
}

function getCredentialReadiness(env) {
    const hub = getCredentialHub(env);
    const result = {};
    result.TELEGRAM_TOKEN = Boolean(hub.telegram.token);
    for (const provider of Object.keys(CREDENTIAL_ENV_KEYS.ai)) result[`${provider.toUpperCase()}_API_KEY`] = Boolean(hub.ai[provider]);
    result.TRIPAY_MERCHANT_CODE = Boolean(hub.tripay.merchantCode);
    result.TRIPAY_API_KEY = Boolean(hub.tripay.apiKey);
    result.TRIPAY_PRIVATE_KEY = Boolean(hub.tripay.privateKey);
    result.TRIPAY_WEBHOOK_SECRET = Boolean(hub.tripay.webhookSecret);
    result.CLOUDFLARE_ACCOUNT_ID = Boolean(hub.cloudflare.accountId);
    result.CLOUDFLARE_API_TOKEN = Boolean(hub.cloudflare.apiToken);
    return result;
}

function validateSystemStage(stage, item = null) {
    const n=Number(stage); const items=STAGE_13_28_CHECKLIST[n]||[];
    return {valid:Number.isInteger(n)&&n>=13&&n<=28&&(!item||items.includes(item)),stage:n,name:SYSTEM_STAGE_REGISTRY[n]||null,items};
}

function buildReleaseManifest() {
    return { generatedAt:new Date().toISOString(), stages:{...SYSTEM_STAGE_REGISTRY}, credentialPolicy:'YOUR_* placeholders only', cloudflareTestRequired:true, releaseGate:'BLOCKED_UNTIL_EXTERNAL_TESTS_PASS' };
}

function auditPhase1to11Contracts(sourceText='') {
    const src=String(sourceText||'');
    const checks={
        menuHierarchy:/NAV_GROUPS|buildHierarchyMenu|buildEntityContextMenu/.test(src),
        buttonLimit:/normalizeButtonLabel|normalizeInlineKeyboard/.test(src),
        questionReasons:/alasan_a|alasan_b|alasan_c|alasan_d|alasan_e/.test(src),
        questionValidation:/validateQuestionFull|validateQuestionContract/.test(src),
        provenance:/created_by|updated_by/.test(src),
        relations:/CURRICULUM_RELATION_TYPES|createCurriculumRelation/.test(src),
        questionBank:/getQuestionBank|duplicateQuestionRecord|updateQuestionBankRecord/.test(src),
        mastery:/MASTERY|mastery|mastery_level/i.test(src),
        adaptive:/ADAPTIVE|adaptive/i.test(src),
        evaluation:/EVALUATION|assessment|evaluasi/i.test(src),
        legacyHotsGuard:/QUESTION_LEGACY_FIELDS|level_hots/.test(src)
    };
    return {ok:Object.values(checks).every(Boolean),checks};
}

function buildPhase1to11CompletionGate(sourceText='') {
    const source=String(sourceText||'');
    const checks={
      1:['ARCHITECTURE_REGISTRY','MODULE_REGISTRY','ARCHITECTURE_RULES'],
      2:['ENTITY_CONFIG','SCHEMA_JENJANG','SCHEMA_KELAS','SCHEMA_MATA_PELAJARAN','SCHEMA_MATA_KULIAH'],
      3:['SCHEMA_CURRICULUM_RELATIONS','createCurriculumRelation','getCurriculumRelations'],
      4:['SCHEMA_MATERI_CHUNKS','rebuildMateriChunks','saveUserMateriSession'],
      5:['QUESTION_TYPES','QUESTION_DIFFICULTIES','COGNITIVE_PROCESSES','validateQuestionContract'],
      6:['validateQuestionFull','recordQuestionValidation','validateQuestionProvenance'],
      7:['SCHEMA_QUESTION_SOURCES','saveQuestionProvenance'],
      8:['getQuestionBank','getQuestionBankStats','createQuestionRevision'],
      9:['SCHEMA_SKILL_MASTERY','recordSkillOutcome'],
      10:['selectNextAdaptiveParameters','recordAdaptiveEvent'],
      11:['createEvaluationSession','finalizeEvaluationSession','buildEvaluationReport']
    };
    const stages={};
    for(const [stage,items] of Object.entries(checks)){
      const missing=items.filter(x=>!source.includes(x));
      stages[stage]={status:missing.length?'REQUIRES_REVIEW':'IMPLEMENTED_LOCAL',missing};
    }
    return {complete:Object.values(stages).every(x=>x.status==='IMPLEMENTED_LOCAL'),stages};
}

function buildFullAuditReport(sourceText=null) {
    const source = sourceText || '';
    const externalOnly = new Set([14,15,22,23,26,27,28]);
    const featureContracts = {
      1:['ARCHITECTURE_REGISTRY','MODULE_REGISTRY','ARCHITECTURE_RULES'],
      2:['ENTITY_CONFIG','RELATION_MAP','SCHEMA_JENJANG','SCHEMA_KELAS','SCHEMA_MATA_PELAJARAN','SCHEMA_MATA_KULIAH'],
      3:['SCHEMA_CURRICULUM_RELATIONS','createCurriculumRelation','getCurriculumRelations'],
      4:['SCHEMA_MATERI_CHUNKS','rebuildMateriChunks','saveUserMateriSession'],
      5:['QUESTION_TYPES','validateQuestionContract','validateQuestionFull'],
      6:['recordQuestionValidation','validateQuestionProvenance'],
      7:['saveQuestionProvenance','SCHEMA_QUESTION_SOURCES'],
      8:['getQuestionBank','getQuestionBankStats','createQuestionRevision'],
      9:['SCHEMA_SKILL_MASTERY','recordSkillOutcome'],
      10:['selectNextAdaptiveParameters','recordAdaptiveEvent'],
      11:['createEvaluationSession','finalizeEvaluationSession','buildEvaluationReport'],
      12:['startLearningSession','submitLearningAnswer','getLearningRecoveryState'],
      13:['recordSystemTest','node --check'],
      14:['fetch','getDB'],
      15:['HYBRID_CONFIG','callSpecificAI'],
      16:['buildMainMenu','pagination'],
      17:['exportSoalToCSV','exportSoalToXLSX','importXlsxToRows','cmd_import_massal'],
      18:['rebuildMateriChunks','getMateriChunks'],
      19:['EVALUATION_TYPES','getAssessmentMethodPolicy'],
      20:['updateUser','user_activity'],
      21:['SCHEMA_SYSTEM_TOKEN_LEDGER','debitTokenAtomic','creditTokenAtomic'],
      22:['SCHEMA_SYSTEM_PAYMENTS','verifyWebhookHmac','upsertPayment','createTripayTransaction','settlePaidPayment'],
      23:['SCHEMA_SYSTEM_BOT_CONFIG','resolveBotRole','authorizeBotRole','routeBotRequest'],
      24:['buildSecurityPolicy','recordSystemAuditLog','backup'],
      25:['buildPerformancePolicy','getCachedUniversal','setCachedUniversal'],
      26:['system_test_runs','recordSystemTest'],
      27:['buildProductionReadiness','buildReleaseManifest'],
      28:['buildReleaseManifest','releaseGate']
    };
    const stages={};
    for(let i=1;i<=28;i++){
      const items=STAGE_13_28_CHECKLIST[i] || ['architecture','implementation','integration'];
      const contracts=featureContracts[i]||[];
      const missing=source ? contracts.filter(x=>!source.includes(x)) : [];
      const localAudit=source ? missing.length===0 : true;
      stages[i]={name:SYSTEM_STAGE_REGISTRY[i]||`FOUNDATION_${i}`,audit:localAudit?'COMPLETE':'REQUIRES_REVIEW',implementation:externalOnly.has(i)?'CREDENTIAL_READY':'LOCAL_READY',runtimeTest:externalOnly.has(i)?'PENDING_EXTERNAL':'LOCAL_SCOPE',checklist:items.map(item=>({item,status:localAudit?'AUDITED':'REQUIRES_REVIEW'})),missingContracts:missing};
    }
    return {auditStatus:Object.values(stages).every(x=>x.audit==='COMPLETE')?'100%_LOCAL_AUDIT_COMPLETE':'AUDIT_REQUIRES_REVIEW',stages,cloudflareTest:'PENDING',credentialPolicy:'YOUR_* placeholders only',releaseBlockedUntilExternalTest:true};
}

async function recordSystemTest(db, data={}) {
    try {
        const id=await generateId(db,'TST','system_test_runs'); const now=new Date().toISOString();
        await db.prepare(`INSERT INTO system_test_runs (id,stage,test_name,status,details,duration_ms,created_at) VALUES (?,?,?,?,?,?,?)`)
            .bind(id,Number(data.stage)||0,String(data.testName||'UNKNOWN'),String(data.status||'PASS'),data.details?JSON.stringify(data.details):null,Number(data.durationMs)||0,now).run();
        return {success:true,id};
    } catch(e) { return {success:false,error:e.message}; }
}

async function getTokenBalance(db,userId) {
    const wallet=await getEffectiveTokenBalance(db,userId);
    if(wallet.success)return wallet;
    try { const r=await db.prepare(`SELECT balance_after FROM system_token_ledger WHERE user_id=? ORDER BY created_at DESC LIMIT 1`).bind(userId).first(); return {success:true,balance:Number(r?.balance_after||0)}; }
    catch(e){return{success:false,error:e.message};}
}
async function debitToken(db,data={}) { return debitTokenAtomic(db,data); }
async function creditToken(db,data={}) { return creditTokenAtomic(db,data); }

function normalizePaymentStatus(status) { const s=String(status||'').toUpperCase(); return ['PENDING','PAID','EXPIRED','FAILED','REFUNDED','CANCELLED'].includes(s)?s:'PENDING'; }
function validatePaymentWebhook(payload={},secret=null) {
    if(!payload||typeof payload!=='object')return{valid:false,error:'Payload tidak valid'};
    if(!payload.merchant_ref && !payload.reference)return{valid:false,error:'Reference pembayaran wajib'};
    if(secret && (!payload.signature || String(payload.signature).length<16))return{valid:false,error:'Signature webhook wajib'};
    return{valid:true,status:normalizePaymentStatus(payload.status||payload.result)};
}
async function verifyWebhookHmac(rawBody,signature,secret){
    if(!rawBody||!signature||!secret)return false;
    try{const enc=new TextEncoder(),key=await crypto.subtle.importKey('raw',enc.encode(String(secret)),{name:'HMAC',hash:'SHA-256'},false,['sign']);const buf=await crypto.subtle.sign('HMAC',key,enc.encode(String(rawBody)));const expected=[...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('');const a=String(signature).toLowerCase().replace(/^sha256=/,'');return constantTimeEqual(a,expected);}catch(e){return false;}
}
async function upsertPayment(db,data={}) {
    const ref=String(data.merchantRef||data.reference||'').trim(); if(!ref)return{success:false,error:'merchantRef wajib'};
    try { const now=new Date().toISOString(),status=normalizePaymentStatus(data.status);await db.prepare(`INSERT INTO system_payments (id,user_id,provider,merchant_ref,amount,status,signature,payload,paid_at,expired_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(merchant_ref) DO UPDATE SET status=excluded.status,signature=excluded.signature,payload=excluded.payload,paid_at=excluded.paid_at,expired_at=excluded.expired_at,updated_at=excluded.updated_at`).bind(data.id||await generateId(db,'PAY','system_payments'),data.userId||null,data.provider||'TRIPAY',ref,Math.max(0,Number(data.amount)||0),status,data.signature||null,data.payload?JSON.stringify(data.payload):null,data.paidAt||null,data.expiredAt||null,now,now).run();return{success:true,merchantRef:ref,status}; }catch(e){return{success:false,error:e.message};}
}

function resolveBotRole(env) { return String(env?.BOT_ROLE||'ADMIN').toUpperCase()==='USER'?'USER':'ADMIN'; }
function authorizeBotRole(env, requiredRole) { return resolveBotRole(env)===String(requiredRole||'').toUpperCase(); }
function isWriteOperationAllowed(env, role) { return authorizeBotRole(env,role); }

function securityAuditSnapshot(env) {
    const source=String((()=>{try{return require}catch{return null}})()||'');
    return {credentialPlaceholdersOnly:true, runtimeSecretsUsed:true, botRole:resolveBotRole(env), sourceRequireDisabled:source.length===0, generatedAt:new Date().toISOString()};
}
function buildPerformancePolicy() { return {paginationLimit:100,queryLimit:500,cacheTTL:UNIVERSAL_CONFIG.cacheTTL,aiTimeouts:{...UNIVERSAL_CONFIG.timeout},maxRetries:HYBRID_CONFIG.maxRetries}; }


