async function unzipEntries(bytes){const b=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes),dec=new TextDecoder();let eocd=-1;for(let i=b.length-22;i>=Math.max(0,b.length-65558);i--)if(readU32(b,i)===0x06054b50){eocd=i;break;}if(eocd<0)throw new Error('XLSX ZIP end record tidak ditemukan');const count=readU16(b,eocd+10),cdSize=readU32(b,eocd+12),cdOffset=readU32(b,eocd+16);let p=cdOffset,out={};for(let i=0;i<count;i++){if(readU32(b,p)!==0x02014b50)throw new Error('Central directory XLSX tidak valid');const method=readU16(b,p+10),cs=readU32(b,p+20),us=readU32(b,p+24),nl=readU16(b,p+28),el=readU16(b,p+30),cl=readU16(b,p+32),off=readU32(b,p+42),name=dec.decode(b.slice(p+46,p+46+nl));const lh=46+nl+el+cl;const lnl=readU16(b,off+26),lel=readU16(b,off+28),start=off+30+lnl+lel;let raw=b.slice(start,start+cs);if(method===8){const ds=new DecompressionStream('deflate-raw');raw=new Uint8Array(await new Response(new Blob([raw]).stream().pipeThrough(ds)).arrayBuffer());}else if(method!==0)throw new Error('Metode kompresi XLSX tidak didukung: '+method);if(us&&raw.length!==us)throw new Error('Ukuran entry XLSX tidak cocok');out[name]=raw;p+=lh;}return out;}
async function xlsxBytesToRows(bytes){const entries=await unzipEntries(bytes);const dec=new TextDecoder(),xml=dec.decode(entries['xl/worksheets/sheet1.xml']||new Uint8Array());if(!xml)throw new Error('Worksheet XLSX tidak ditemukan');const rows=[];for(const rm of xml.matchAll(/<row\b[^>]*>([\s\S]*?)<\/row>/g)){const cells=[];for(const cm of rm[1].matchAll(/<c\b([^>]*)>([\s\S]*?)<\/c>/g)){const attrs=cm[1],body=cm[2];const ref=(attrs.match(/\br="([A-Z]+)\d+"/)||[])[1];let idx=0;if(ref){idx=0;for(const ch of ref)idx=idx*26+(ch.charCodeAt(0)-64);idx--;}const num=(body.match(/<v>([\s\S]*?)<\/v>/)||[])[1];const txt=(body.match(/<t[^>]*>([\s\S]*?)<\/t>/)||[])[1];let val=txt!==undefined?txt.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'"):num!==undefined?Number(num):'';cells[idx]=val;}rows.push(cells.map(v=>v??''));}return rows;}
