async function exportSoalToXLSX(db,filters={}){const csvResult=await exportSoalToCSV(db,filters);if(!csvResult?.success)return csvResult;const lines=String(csvResult.csv||'').split(/\r?\n/).filter(Boolean);const parse=line=>{const out=[];let cur='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'){cur+='"';i++;continue;}if(c==='"'){q=!q;continue;}if(c===','&&!q){out.push(cur);cur='';}else cur+=c;}out.push(cur);return out;};const bytes=rowsToXlsxBytes(lines.map(parse));return{success:true,bytes,filename:`soal_${Date.now()}.xlsx`,contentType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'};}

async function createTripayTransaction(env,data={}){const base=String(data.endpoint||'https://tripay.co.id/api/transaction/create').trim(),key=resolveExternalCredential(env,'TRIPAY_API_KEY','YOUR_TRIPAY_API_KEY');if(!key.configured)return{success:false,error:'TRIPAY_API_KEY belum dikonfigurasi'};const body={method:data.method||'BRIVA',merchant_ref:data.merchantRef,amount:Number(data.amount)||0,customer_name:data.customerName||'Customer',customer_email:data.customerEmail||'no-reply@example.invalid',order_items:data.orderItems||[],return_url:data.returnUrl||null,expired_time:data.expiredTime||null};try{const r=await fetch(base,{method:'POST',headers:{Authorization:`Bearer ${key.value}`,'Content-Type':'application/json'},body:JSON.stringify(body)});const text=await r.text();let json;try{json=JSON.parse(text);}catch{json={raw:text};}return{success:r.ok&&json?.success!==false,httpStatus:r.status,data:json};}catch(e){return{success:false,error:e.message};}}
async function settlePaidPayment(db,data={}){const ref=String(data.merchantRef||data.reference||'').trim();if(!ref)return{success:false,error:'merchantRef wajib'};try{const p=await db.prepare(`SELECT * FROM system_payments WHERE merchant_ref=? LIMIT 1`).bind(ref).first();if(!p)return{success:false,error:'Pembayaran tidak ditemukan'};if(String(p.status).toUpperCase()!=='PAID')return{success:false,error:'Status pembayaran belum PAID'};let meta={};try{meta=JSON.parse(p.payload||'{}')}catch{}if(meta.token_credited_at)return{success:true,id:p.id,alreadyCredited:true};const tokenAmount=Math.max(0,Number(data.tokenAmount||meta.token_amount||meta.tokenAmount||0));if(!p.user_id||tokenAmount<=0)return{success:false,error:'Pembayaran PAID tetapi tokenAmount/user_id tidak valid; token tidak diberikan'};const credit=await creditTokenAtomic(db,{userId:p.user_id,amount:tokenAmount,feature:'PAYMENT_TOPUP',referenceId:p.id,metadata:{merchantRef:ref}});if(!credit.success)return credit;meta.token_credited_at=new Date().toISOString();await db.prepare(`UPDATE system_payments SET payload=?,updated_at=? WHERE id=?`).bind(JSON.stringify(meta),new Date().toISOString(),p.id).run();return{success:true,id:p.id,credited:credit.balance};}catch(e){return{success:false,error:e.message};}}
async function routeBotRequest(env,requiredRole='ADMIN'){const role=resolveBotRole(env);return{allowed:role===String(requiredRole).toUpperCase(),role,sharedDatabase:true};}


