function botAdminCommandGroup(cmd){return BOT_ADMIN_COMMAND_GROUP[String(cmd||'').toLowerCase()]||null;}
function normalizeAdminRole(role){const r=String(role||'').trim().toUpperCase().replace(/[_-]+/g,' ');if(r==='SUPERADMIN')return 'SUPER ADMIN';if(['SUPER ADMIN','ADMIN','MODERATOR','VIEWER'].includes(r))return r;return null;}
async function getAdminRole(db,userId,env=null){try{const r=await db.prepare(`SELECT role,status FROM users WHERE telegram_id=? OR id=? LIMIT 1`).bind(String(userId),String(userId)).first();if(r?.status && String(r.status).toUpperCase()!=='AKTIF')return null;const role=normalizeAdminRole(r?.role);if(role)return role;return isAdmin(userId,env)?'SUPER ADMIN':null;}catch{return isAdmin(userId,env)?'SUPER ADMIN':null;}}
function adminPermissionForCommand(cmd,role){
  const c=String(cmd||'').toLowerCase(), g=botAdminCommandGroup(c), r=normalizeAdminRole(role);
  if(!g)return true;
  if(r==='SUPER ADMIN')return true;
  if(r==='ADMIN'){ const ownerOnly=new Set(['/admin_list','/admin_add','/admin_remove','/restore_db','/restore_db_cancel','/reset_database','/maintenance_on','/maintenance_off','/config_reset','/webhook_set','/webhook_delete','/migrate']); return !ownerOnly.has(c); }
  if(r==='MODERATOR'){
    const review=['/review','/review_soal','/review_stats','/review_pending','/approve','/approve_all','/approve_batch','/reject','/reject_batch','/revisi','/revisi_list','/validasi_auto','/validasi_duplikat','/validasi_format'];
    const question=['/pertanyaan','/pertanyaan_pending','/pertanyaan_dijawab','/pertanyaan_detail','/jawab','/jawab_template','/jawab_batch','/pertanyaan_kategori','/pertanyaan_user','/pertanyaan_trending'];
    return review.includes(c)||question.includes(c);
  }
  if(r==='VIEWER')return ['/start','/help','/dashboard','/dashboard_today','/dashboard_weekly','/dashboard_monthly','/dashboard_yearly','/stats_soal','/stats_soal_penyajian','/stats_soal_tipe','/stats_soal_tahap','/stats_soal_hots','/stats_soal_status','/stats_user','/stats_user_aktif','/stats_user_progres','/stats_user_token','/stats_user_terbaik','/stats_ai','/stats_ai_provider','/stats_ai_cost','/stats_ai_limit','/analytics','/analytics_trending','/analytics_heatmap','/monitor','/monitor_api','/monitor_db','/monitor_cache','/monitor_performance'].includes(c);
  return false;
}
function safeJson(value,fallback=null){try{return typeof value==='string'?JSON.parse(value):value}catch{return fallback;}}
function csvEscape(v){const s=String(v??'');return /[",\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}
async function adminLog(db,actorId,command,args,result='OK'){try{await recordSystemAuditLog(db,{actorUserId:actorId,action:`BOT_ADMIN:${command}`,entityType:'command',entityId:command,details:{args,result},success:result==='OK'});const id=await generateId(db,'ALOG','admin_log');await db.prepare(`INSERT INTO admin_log (id,actor_id,command,args,result,created_at) VALUES (?,?,?,?,?,?)`).bind(id,String(actorId),command,JSON.stringify(args||[]),String(result).slice(0,500),new Date().toISOString()).run();}catch(e){console.warn('adminLog:',e.message);}}
async function ensureAdminFeatureTables(db){for(const [name,schema] of Object.entries({admin_commands:SCHEMA_ADMIN_COMMANDS,admin_review:SCHEMA_ADMIN_REVIEW,question_templates:SCHEMA_QUESTION_TEMPLATES,user_questions:SCHEMA_USER_QUESTIONS,ai_settings:SCHEMA_AI_SETTINGS,webhooks:SCHEMA_WEBHOOKS,exams:SCHEMA_EXAMS,exam_results:SCHEMA_EXAM_RESULTS,certificate_templates:SCHEMA_CERTIFICATE_TEMPLATES,certificates:SCHEMA_CERTIFICATES,vouchers:SCHEMA_VOUCHERS,voucher_redemptions:SCHEMA_VOUCHER_REDEMPTIONS,broadcasts:SCHEMA_BROADCASTS,notifications:SCHEMA_NOTIFICATIONS,user_learning_reminders:SCHEMA_USER_LEARNING_REMINDERS,system_config:SCHEMA_SYSTEM_CONFIG,admin_log:SCHEMA_ADMIN_LOG,batch_jobs:SCHEMA_BATCH_JOBS,analytics_events:SCHEMA_ANALYTICS_EVENTS,monitor_snapshots:SCHEMA_MONITOR_SNAPSHOTS}))try{await autoMigrateTable(db,name,schema)}catch(e){console.warn('feature table',name,e.message)} try{await db.prepare(`CREATE INDEX IF NOT EXISTS idx_user_learning_reminders_due ON user_learning_reminders(status,next_run_at)`).run();await db.prepare(`CREATE INDEX IF NOT EXISTS idx_user_learning_reminders_user ON user_learning_reminders(user_id,status)`).run()}catch(e){console.warn('reminder indexes',e.message)} }
async function adminListRows(db,table,limit=50){const allowed={admin_review:1,question_templates:1,user_questions:1,webhooks:1,exams:1,certificate_templates:1,certificates:1,vouchers:1,broadcasts:1,batch_jobs:1,analytics_events:1,monitor_snapshots:1};if(!allowed[table])throw new Error('Table tidak diizinkan');const n=Math.min(200,Math.max(1,Number(limit)||50));return (await db.prepare(`SELECT * FROM ${table} ORDER BY created_at DESC LIMIT ?`).bind(n).all()).results||[];}
function formatRows(title,rows,fields=['id','status']){let m=`📋 *${title}*\n\n`;if(!rows.length)return m+'Tidak ada data.';for(const r of rows)m+=`• ${r.id||'-'}${r.status?` — ${r.status}`:''}${r.name?` — ${r.name}`:''}${r.code?` — ${r.code}`:''}\n`;return m.slice(0,4000);}

