// ============================================================
// BATCH 2 — UNIVERSAL EXPORT / IMPORT CONTRACT
// Semua tabel memakai schema aktual D1 sebagai sumber kebenaran.
// Export tidak menghilangkan kolom. Import selalu PREVIEW dulu.
// ============================================================
const DATA_TRANSFER_VERSION = '2.0';
const DATA_TRANSFER_MAX_ROWS = 50000;

function dataTransferTableName(table) {
    const name = String(table || '').trim();
    if (!name || !Object.prototype.hasOwnProperty.call(ALL_SCHEMAS, name)) {
        throw new Error(`Tabel tidak diizinkan: ${name || '-'}`);
    }
    return name;
}

function schemaColumns(table) {
    const schema = ALL_SCHEMAS[dataTransferTableName(table)] || {};
    return Object.keys(schema);
}

function schemaPrimaryKey(table) {
    const schema = ALL_SCHEMAS[dataTransferTableName(table)] || {};
    for (const [name, def] of Object.entries(schema)) {
        if (/\bPRIMARY\s+KEY\b/i.test(String(def))) return name;
    }
    return 'id';
}

function normalizeTransferValue(value) {
    if (value === undefined) return null;
    if (value === null) return null;
    if (typeof value === 'bigint') return Number(value);
    if (typeof value === 'object') return JSON.stringify(value);
    return value;
}

function rowsToCSVByColumns(rows, columns) {
    const out = [columns.map(csvEscape).join(',')];
    for (const row of rows || []) {
        out.push(columns.map(c => csvEscape(normalizeTransferValue(row?.[c]))).join(','));
    }
    return out.join('\n') + '\n';
}

function parseCSVTransfer(text) {
    const input = String(text ?? '').replace(/^\uFEFF/, '');
    const rows = [];
    let row = [], cell = '', quoted = false;
    for (let i = 0; i < input.length; i++) {
        const c = input[i];
        if (c === '"') {
            if (quoted && input[i + 1] === '"') { cell += '"'; i++; }
            else quoted = !quoted;
        } else if (c === ',' && !quoted) {
            row.push(cell); cell = '';
        } else if ((c === '\n' || c === '\r') && !quoted) {
            if (c === '\r' && input[i + 1] === '\n') i++;
            row.push(cell); cell = '';
            if (row.some(v => String(v).length > 0)) rows.push(row);
            row = [];
        } else cell += c;
    }
    if (cell.length || row.length) {
        row.push(cell);
        if (row.some(v => String(v).length > 0)) rows.push(row);
    }
    if (!rows.length) return { columns: [], rows: [] };
    const columns = rows.shift().map(v => String(v).trim());
    return { columns, rows: rows.map(r => {
        const o = {};
        columns.forEach((c, i) => { o[c] = r[i] ?? ''; });
        return o;
    }) };
}

async function inspectTransferTable(db, table) {
    const safe = dataTransferTableName(table);
    const info = await db.prepare(`PRAGMA table_info(${safe})`).all();
    const columns = (info.results || []).map(c => ({
        name: c.name, type: c.type, notnull: Number(c.notnull) === 1,
        default: c.dflt_value, pk: Number(c.pk) > 0
    }));
    const schemaCols = schemaColumns(safe);
    const missingFromSchema = columns.filter(c => !schemaCols.includes(c.name)).map(c => c.name);
    const missingFromDb = schemaCols.filter(c => !columns.some(c => c.name === c)).map(c => c);
    return {
        table: safe,
        primaryKeys: columns.filter(c => c.pk).sort((a,b)=>Number(a.pk)-Number(b.pk)).map(c=>c.name),
        primaryKey: columns.find(c => c.pk)?.name || schemaPrimaryKey(safe),
        columns,
        missingFromSchema,
        missingFromDb,
        schemaColumnCount: schemaCols.length,
        actualColumnCount: columns.length,
        schemaMatch: missingFromSchema.length === 0 && missingFromDb.length === 0
    };
}

async function exportTableData(db, table, options = {}) {
    const safe = dataTransferTableName(table);
    const limit = Math.min(DATA_TRANSFER_MAX_ROWS, Math.max(1, Number(options.limit) || DATA_TRANSFER_MAX_ROWS));
    const schemaCols = schemaColumns(safe);
    const order = schemaPrimaryKey(safe);
    const result = await db.prepare(`SELECT * FROM ${safe} ORDER BY ${order} LIMIT ?`).bind(limit).all();
    const rows = result.results || [];
    const csv = rowsToCSVByColumns(rows, schemaCols);
    return {
        success: true,
        version: DATA_TRANSFER_VERSION,
        table: safe,
        columns: schemaCols,
        primaryKey: order,
        total: rows.length,
        truncated: rows.length >= limit,
        filename: `${safe}_${new Date().toISOString().slice(0,10)}.csv`,
        content: csv
    };
}

async function inspectTransferConstraints(db, table) {
    const safe = dataTransferTableName(table);
    const fkRows = (await db.prepare(`PRAGMA foreign_key_list(${safe})`).all()).results || [];
    const idxRows = (await db.prepare(`PRAGMA index_list(${safe})`).all()).results || [];
    const foreignKeys = fkRows.map(r => ({
        id: Number(r.id), seq: Number(r.seq), table: String(r.table || ''),
        from: String(r.from || ''), to: String(r.to || 'id'), on_update: String(r.on_update || ''), on_delete: String(r.on_delete || '')
    }));
    const uniqueIndexes = [];
    for (const idx of idxRows) {
        if (Number(idx.unique) !== 1) continue;
        const name = String(idx.name || '');
        const cols = (await db.prepare(`PRAGMA index_info(${name.replace(/"/g,'""')})`).all()).results || [];
        uniqueIndexes.push({ name, columns: cols.sort((a,b)=>Number(a.seqno)-Number(b.seqno)).map(c=>String(c.name||'')) });
    }
    return { table: safe, foreignKeys, uniqueIndexes };
}

async function validateImportConstraints(db, table, rows, options = {}) {
    const safe = dataTransferTableName(table);
    const constraints = options.constraints || await inspectTransferConstraints(db, safe);
    const inspection = options.inspection || await inspectTransferTable(db, safe);
    const pkCols = inspection.primaryKeys?.length ? inspection.primaryKeys : [inspection.primaryKey];
    const errors = [], warnings = [];
    const columnMeta = new Map((inspection.columns || []).map(c=>[c.name,c]));
    const chunk = (arr, size) => { const out=[]; for(let i=0;i<arr.length;i+=size) out.push(arr.slice(i,i+size)); return out; };
    const nonEmpty = (row, col) => row?.[col] !== undefined && row?.[col] !== null && String(row[col]).trim() !== '';
    const keyOf = (row, cols) => cols.map(c=>String(row?.[c] ?? '').trim()).join('\u001f');

    // FK: fetch all referenced IDs for the current import in batches instead of N+1 queries.
    for (const fk of constraints.foreignKeys) {
        const parent = dataTransferTableName(fk.table);
        const values = [...new Set(rows.filter(r=>nonEmpty(r,fk.from)).map(r=>String(r[fk.from]).trim()))];
        const found = new Set();
        for (const group of chunk(values, 200)) {
            if (!group.length) continue;
            const marks = group.map(()=>'?').join(',');
            try {
                const result = await db.prepare(`SELECT ${fk.to} FROM ${parent} WHERE ${fk.to} IN (${marks})`).bind(...group).all();
                for (const r of result.results || []) found.add(String(r[fk.to] ?? '').trim());
            } catch(e) {
                errors.push(`FK ${fk.from}: gagal mengambil referensi ${parent}.${fk.to}: ${e.message}`);
            }
        }
        for (let i=0;i<rows.length;i++) {
            const row=rows[i]||{};
            if (!nonEmpty(row,fk.from)) {
                if (columnMeta.get(fk.from)?.notnull) errors.push(`Baris ${i+2}: FK ${fk.from} wajib diisi.`);
                continue;
            }
            if (!found.has(String(row[fk.from]).trim())) errors.push(`Baris ${i+2}: FK ${fk.from}=${row[fk.from]} tidak ditemukan di ${parent}.${fk.to}.`);
        }
    }

    // UNIQUE / composite UNIQUE: detect duplicates inside file, then query only candidate tuples from DB.
    for (const uq of constraints.uniqueIndexes) {
        const cols=uq.columns.filter(Boolean);
        if(!cols.length) continue;
        const seen=new Map();
        const candidates=[];
        for(let i=0;i<rows.length;i++){
            const row=rows[i]||{};
            // SQLite UNIQUE permits multiple NULLs; skip tuples with blank nullable values.
            if(cols.some(c=>!nonEmpty(row,c))) continue;
            const key=keyOf(row,cols);
            if(seen.has(key)) errors.push(`Baris ${i+2}: duplikat UNIQUE ${uq.name} (${cols.join(', ')}) dengan baris ${seen.get(key)+2}.`);
            else { seen.set(key,i); candidates.push({row,i}); }
        }
        const existingMap = new Map();
        for (const group of chunk(candidates, 40)) {
            if (!group.length) continue;
            const where = group.map(({row}) => `(${cols.map(c=>`${c}=?`).join(' AND ')})`).join(' OR ');
            const bind=[];
            for (const {row} of group) for (const c of cols) bind.push(row[c]);
            try {
                const result=await db.prepare(`SELECT ${pkCols.join(',')},${cols.join(',')} FROM ${safe} WHERE ${where}`).bind(...bind).all();
                for (const existing of result.results || []) existingMap.set(keyOf(existing,cols),existing);
            } catch(e) { errors.push(`UNIQUE ${uq.name}: gagal cek database: ${e.message}`); }
        }
        for (const {row,i} of candidates) {
            const existing=existingMap.get(keyOf(row,cols));
            if (!existing) continue;
            const samePk=pkCols.length && pkCols.every(c=>String(existing[c]??'').trim()===String(row[c]??'').trim());
            if(!samePk) errors.push(`Baris ${i+2}: konflik UNIQUE ${uq.name} (${cols.join(', ')}).`);
        }
    }
    return {success:errors.length===0,errors:[...new Set(errors)].slice(0,200),warnings,constraints};
}

async function buildTableDependencyGraph(db, tables = Object.keys(ALL_SCHEMAS)) {
    const graph = Object.fromEntries(tables.map(t=>[dataTransferTableName(t), new Set()]));
    for (const table of Object.keys(graph)) {
        const c=await inspectTransferConstraints(db,table);
        for(const fk of c.foreignKeys) if(graph[fk.table]) graph[table].add(fk.table);
    }
    return graph;
}

function sortTablesByDependency(graph) {
    const nodes=Object.keys(graph), out=[], temp=new Set(), done=new Set();
    const visit=n=>{ if(done.has(n)) return; if(temp.has(n)) throw new Error(`Siklus dependency tabel terdeteksi pada ${n}.`); temp.add(n); for(const dep of graph[n]||[]) visit(dep); temp.delete(n); done.add(n); out.push(n); };
    nodes.forEach(visit); return out;
}

async function exportAllTablesData(db, options = {}) {
    const graph=await buildTableDependencyGraph(db, options.tables?.length ? options.tables : Object.keys(ALL_SCHEMAS));
    const tables=sortTablesByDependency(graph);
    const files=[], manifest={format:'D1_DATA_EXPORT',version:DATA_TRANSFER_VERSION,created_at:new Date().toISOString(),table_count:tables.length,tables:[]};
    for(const table of tables){
        try{const r=await exportTableData(db,table,options);files.push({table,filename:r.filename,content:r.content});manifest.tables.push({table,columns:r.columns,primaryKey:r.primaryKey,total:r.total,truncated:r.truncated,dependencies:[...(graph[table]||[])]});}
        catch(e){manifest.tables.push({table,error:e.message,dependencies:[...(graph[table]||[])]});}
    }
    return {success:true,manifest,files};
}

function validateTransferColumns(table, inputColumns) {
    const expected = schemaColumns(table);
    const actual = [...new Set((inputColumns || []).map(c => String(c).trim()).filter(Boolean))];
    const unknown = actual.filter(c => !expected.includes(c));
    const missing = expected.filter(c => !actual.includes(c));
    return { valid: unknown.length === 0, expected, actual, unknown, missing };
}

async function validateImportRows(db, table, rows, options = {}) {
    const safe = dataTransferTableName(table);
    const contract = validateTransferColumns(safe, options.columns || Object.keys(rows?.[0] || {}));
    const inspection = await inspectTransferTable(db, safe);
    const constraints = await inspectTransferConstraints(db, safe);
    const pkCols = inspection.primaryKeys?.length ? inspection.primaryKeys : [inspection.primaryKey];
    const errors = [], warnings = [], seen = new Set(), duplicateIds = [], existingIds = [], existingKeys = [];
    const maxRows = Math.min(DATA_TRANSFER_MAX_ROWS, rows.length);
    if (rows.length > DATA_TRANSFER_MAX_ROWS) errors.push(`Maksimal ${DATA_TRANSFER_MAX_ROWS} baris per import; file harus dipecah dan setiap bagian diverifikasi.`);
    if (!contract.valid) errors.push(`Kolom tidak dikenal: ${contract.unknown.join(', ')}`);
    if (!inspection.schemaMatch) errors.push('Schema D1 dan ALL_SCHEMAS belum identik. Perbaiki migrasi/schema sebelum import.');
    const inputColumnSet = new Set(contract.actual);
    const requiredColumns = (inspection.columns || []).filter(c=>c.notnull && !c.pk && c.default === null).map(c=>c.name);
    for (const c of requiredColumns) if (!inputColumnSet.has(c)) errors.push(`Kolom wajib ${c} tidak ada pada file import.`);
    for(let i=0;i<maxRows;i++){
        const row=rows[i]||{};
        const missingRequired = requiredColumns.filter(c=>!String(row[c]??'').trim());
        if (missingRequired.length) errors.push(`Baris ${i+2}: kolom wajib kosong (${missingRequired.join(', ')}).`);
        const missingPk=pkCols.filter(c=>!String(row[c]??'').trim());
        if(missingPk.length){errors.push(`Baris ${i+2}: Primary Key kosong (${missingPk.join(', ')}).`);continue;}
        const idKey=pkCols.map(c=>String(row[c]??'')).join('\\u001f');
        if(seen.has(idKey)) duplicateIds.push(idKey); else seen.add(idKey);
        try{
            const where=pkCols.map(c=>`${c}=?`).join(' AND ');
            const existing=await db.prepare(`SELECT ${pkCols.join(',')} FROM ${safe} WHERE ${where} LIMIT 1`).bind(...pkCols.map(c=>row[c])).first();
            if(existing){const key=pkCols.map(c=>String(row[c])).join('\u001f');existingKeys.push(key);if(pkCols.length===1)existingIds.push(String(row[pkCols[0]]));}
        } catch(e){errors.push(`Baris ${i+2}: gagal cek Primary Key: ${e.message}`);}
    }
    if(duplicateIds.length) errors.push(`Primary Key duplikat dalam file: ${[...new Set(duplicateIds)].slice(0,20).join(', ')}`);
    const constraintValidation=await validateImportConstraints(db,safe,rows.slice(0,maxRows),{constraints,inspection});
    errors.push(...constraintValidation.errors);
    return {success:errors.length===0,table:safe,primaryKey:inspection.primaryKey,primaryKeys:pkCols,totalRows:rows.length,validRows:maxRows,duplicateIds:[...new Set(duplicateIds)],existingIds:[...new Set(existingIds)],existingKeys:[...new Set(existingKeys)],errors:[...new Set(errors)].slice(0,200),warnings:[...warnings,...constraintValidation.warnings],columns:contract,inspection,constraints};
}

async function prepareImportPreview(db, table, input, options = {}) {
    const safe = dataTransferTableName(table);
    const parsed = Array.isArray(input) ? { columns: Object.keys(input[0] || {}), rows: input } : parseCSVTransfer(input);
    const validation = await validateImportRows(db, safe, parsed.rows, { ...options, columns: parsed.columns });
    const pk = validation.primaryKey;
    const pkCols = validation.primaryKeys?.length ? validation.primaryKeys : [pk];
    const mode = ['insert','update','upsert'].includes(options.mode) ? options.mode : 'upsert';
    const existing = new Set(validation.existingKeys || validation.existingIds);
    const actions = parsed.rows.map((row, index) => {
        const id = pkCols.map(c=>String(row?.[c] ?? '').trim()).join('\u001f');
        const exists = existing.has(id);
        const action = mode === 'insert' ? (exists ? 'CONFLICT' : 'INSERT') : mode === 'update' ? (exists ? 'UPDATE' : 'MISSING') : (exists ? 'UPDATE' : 'INSERT');
        return { row: index + 2, id, action };
    });
    return { success: validation.success, table: safe, mode, columns: parsed.columns, rows: parsed.rows, validation, actions, preview: actions.slice(0,50) };
}

async function buildImportStatements(db, preview) {
    if (!preview?.success) throw new Error('Import belum lolos validasi.');
    const table = dataTransferTableName(preview.table);
    const columns = schemaColumns(table);
    const inspection = preview.validation.inspection || await inspectTransferTable(db, table);
    const columnMeta = new Map((inspection.columns || []).map(c => [c.name, c]));
    const pk = preview.validation.primaryKey;
    const pkCols = preview.validation.primaryKeys?.length ? preview.validation.primaryKeys : [pk];
    const existingKeys = new Set(preview.validation.existingKeys || preview.validation.existingIds);
    const protectedAudit = new Set(['created_at','created_by','created_by_id','updated_at','updated_by','updated_by_id']);
    const statements = [];
    for (const item of preview.rows) {
        const row = {};
        for (const c of columns) {
            const meta = columnMeta.get(c);
            const raw = item?.[c];
            // Excel/CSV empty cell means SQL NULL only for nullable columns.
            row[c] = (raw === '' && meta && !meta.notnull && !meta.pk) ? null : normalizeTransferValue(raw);
        }
        const key = pkCols.map(c=>String(item?.[c] ?? '').trim()).join('\u001f');
        const action = preview.mode === 'insert' ? 'INSERT' : preview.mode === 'update' ? 'UPDATE' : (key ? (existingKeys.has(key) ? 'UPDATE' : 'INSERT') : 'CONFLICT');
        if (action === 'INSERT') {
            const inputColumns = new Set(preview.columns || columns);
            const insertCols = columns.filter(c => inputColumns.has(c) || (columnMeta.get(c)?.notnull && columnMeta.get(c)?.default === null));
            const placeholders = insertCols.map(() => '?').join(',');
            statements.push(db.prepare(`INSERT INTO ${table} (${insertCols.join(',')}) VALUES (${placeholders})`).bind(...insertCols.map(c => row[c])));
        } else if (action === 'UPDATE') {
            const inputColumns = new Set(preview.columns || columns);
            const updateCols = columns.filter(c => inputColumns.has(c) && !pkCols.includes(c) && !protectedAudit.has(c));
            if (!updateCols.length) continue;
            const where = pkCols.map(c=>`${c} = ?`).join(' AND ');
            statements.push(db.prepare(`UPDATE ${table} SET ${updateCols.map(c => `${c} = ?`).join(', ')} WHERE ${where}`).bind(...updateCols.map(c => row[c]), ...pkCols.map(c=>row[c])));
        } else if (action === 'CONFLICT') throw new Error(`Konflik ID: ${row[pk] || '-'}`);
        else throw new Error(`ID tidak ditemukan untuk UPDATE: ${row[pk] || '-'}`);
    }
    return statements;
}

async function commitImportPreview(db, preview) {
    const statements = await buildImportStatements(db, preview);
    if (!statements.length) return { success: true, applied: 0 };
    const table=dataTransferTableName(preview.table);
    const cols=schemaColumns(table);
    const safeStatementsPerBatch=Math.max(1,Math.min(500,Math.floor(5000/Math.max(1,cols.length))));
    if (statements.length > safeStatementsPerBatch) throw new Error(`Import ${statements.length} baris melebihi kapasitas satu batch aman untuk tabel ${table} (${safeStatementsPerBatch} baris). Pecah file menjadi beberapa bagian.`);
    const result = await db.batch(statements);
    return { success: true, applied: statements.length, result };
}



