// ============================================================
// 🆕 RELATION_MAP — Peta Relasi LENGKAP untuk Reorder (Patch #15)
// Mencakup SEMUA tabel yang punya FK ke hierarki:
// - Anak langsung (bidang→program, dst.)
// - Referensi FK (soal, materi)
// - Junction (topik_jenjang, topik_kelas, topik_relations)
// ============================================================
// Optional relation.where is a STATIC SQL predicate used to scope polymorphic references
// such as curriculum_relations.source_id/target_id by their *_type discriminator.
const RELATION_MAP = {
    // ============================================================
    // KATEGORI — Anak langsung + soal + materi
    // ============================================================
    kategori: [
        { table: 'bidang_studi', field: 'kategori_id' },
        { table: 'soal', field: 'kategori_id' },
        { table: 'materi', field: 'kategori_id' },
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'kategori'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'kategori'" }
    ],
    
    // ============================================================
    // BIDANG — Anak langsung + soal + materi
    // ============================================================
    bidang: [
        { table: 'program_studi', field: 'bidang_studi_id' },
        { table: 'mata_pelajaran', field: 'bidang_studi_id' },
        { table: 'soal', field: 'bidang_studi_id' },
        { table: 'materi', field: 'bidang_studi_id' },
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'bidang_studi'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'bidang_studi'" }
    ],
    
    // ============================================================
    // MATA PELAJARAN — Anak topik + soal + materi
    // ============================================================
    mata_pelajaran: [
        { table: 'topik', field: 'mata_pelajaran_id' },
        { table: 'soal', field: 'mata_pelajaran_id' },
        { table: 'materi', field: 'mata_pelajaran_id' },
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'mata_pelajaran'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'mata_pelajaran'" }
    ],

    // ============================================================
    // PROGRAM — Anak langsung + soal + materi
    // ============================================================
    program: [
        { table: 'mata_kuliah', field: 'program_studi_id' },
        { table: 'topik', field: 'program_studi_id' },
        { table: 'soal', field: 'program_studi_id' },
        { table: 'materi', field: 'program_studi_id' },
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'program_studi'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'program_studi'" }
    ],

    // ============================================================
    // 🆕 MATA KULIAH — Anak topik + soal + materi
    // ============================================================
    mata_kuliah: [
        { table: 'topik', field: 'mata_kuliah_id' },
        { table: 'soal', field: 'mata_kuliah_id' },
        { table: 'materi', field: 'mata_kuliah_id' },
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'mata_kuliah'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'mata_kuliah'" }
    ],

    // ============================================================
    // 🆕 JENJANG — Anak langsung (kelas) + junction (topik_jenjang) + soal
    // ⚠️ TIDAK ADA relasi ke materi (materi tidak punya jenjang_id)
    // ============================================================
    jenjang: [
        { table: 'kelas', field: 'jenjang_id' },
        { table: 'mata_kuliah', field: 'jenjang_id' },
        { table: 'topik_jenjang', field: 'jenjang_id' },
        { table: 'soal', field: 'jenjang_id' },
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'jenjang'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'jenjang'" }
        // ❌ materi: DIHAPUS (tidak ada kolom jenjang_id)
    ],

    // ============================================================
    // 🆕 KELAS — Junction (topik_kelas) + soal
    // ⚠️ TIDAK ADA relasi ke materi (materi tidak punya kelas)
    // ============================================================
    kelas: [
        { table: 'topik_kelas', field: 'kelas_id' },
        { table: 'mata_pelajaran', field: 'kelas_id' },
        { table: 'soal', field: 'kelas' },        // ← soal pakai 'kelas'
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'kelas'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'kelas'" }
        // ❌ materi: DIHAPUS (tidak ada kolom kelas)
    ],
    
    // ============================================================
    // TOPIK — Anak langsung + junction + soal + materi
    // (Topik punya paling banyak relasi!)
    // ============================================================
    topik: [
        { table: 'sub_topik', field: 'topik_id' },
        { table: 'topik_jenjang', field: 'topik_id' },
        { table: 'topik_kelas', field: 'topik_id' },
        { table: 'topik_relations', field: 'topik_id' },
        { table: 'topik_relations', field: 'related_topik_id' },
        { table: 'soal', field: 'topik_id' },
        { table: 'materi', field: 'topik_id' },
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'topik'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'topik'" }
    ],
    
    // ============================================================
    // SUB-TOPIK — Anak langsung + soal + materi
    // ============================================================
    subtopik: [
        { table: 'kisi_kisi', field: 'sub_topik_id' },
        { table: 'soal', field: 'sub_topik_id' },
        { table: 'materi', field: 'sub_topik_id' }
   ,
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'sub_topik'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'sub_topik'" }
    ],
    
    // ============================================================
    // KISI-KISI — Anak langsung + soal + materi
    // ============================================================
    kisi: [
        { table: 'kemampuan_diuji', field: 'kisi_kisi_id' },
        { table: 'soal', field: 'kisi_kisi_id' },
        { table: 'materi', field: 'kisi_kisi_id' }
   ,
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'kisi_kisi'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'kisi_kisi'" }
    ],
    
    // ============================================================
    // KEMAMPUAN — Anak langsung + soal + materi
    // ============================================================
    kemampuan: [
        { table: 'sub_kemampuan', field: 'kemampuan_id' },
        { table: 'soal', field: 'kemampuan_id' },
        { table: 'materi', field: 'kemampuan_id' }
   ,
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'kemampuan_diuji'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'kemampuan_diuji'" }
    ],
    
    // ============================================================
    // SUB-KEMAMPUAN — Anak langsung (soal + materi)
    // ============================================================
    subkemampuan: [
        { table: 'soal', field: 'sub_kemampuan_id' },
        { table: 'materi', field: 'sub_kemampuan_id' },
        { table: 'curriculum_relations', field: 'source_id', where: "source_type = 'sub_kemampuan'" },
        { table: 'curriculum_relations', field: 'target_id', where: "target_type = 'sub_kemampuan'" }
    ]
};

