// ============================================================
// FASE 1 — CONTRACT VALIDATION
// Memastikan konfigurasi, entitas, parent dan FK konsisten.
// ============================================================
const CONFIG_SCHEMA = {
    ai: ['activeAI', 'models', 'maxTokens', 'apiKeys'],
    universal: ['parallelBatches', 'maxBatchSize', 'parallelChunks', 'timeout', 'providers'],
    hybrid: ['parallelProviders', 'serialFallback', 'parallelTimeout', 'serialDelay', 'maxRetries']
};

function validateArchitectureContracts() {
    const errors = [];
    const warnings = [];
    const schemas = typeof ALL_SCHEMAS === 'object' && ALL_SCHEMAS ? ALL_SCHEMAS : {};
    const entityKeys = Object.keys(ENTITY_CONFIG);
    const relationKeys = Object.keys(RELATION_MAP);
    const missingRelationMap = entityKeys.filter(entity => !Object.prototype.hasOwnProperty.call(RELATION_MAP, entity));
    const orphanRelationMap = relationKeys.filter(entity => !Object.prototype.hasOwnProperty.call(ENTITY_CONFIG, entity));
    if (missingRelationMap.length) errors.push(`RELATION_MAP tidak memiliki entitas: ${missingRelationMap.join(', ')}`);
    if (orphanRelationMap.length) errors.push(`RELATION_MAP memiliki entitas tanpa ENTITY_CONFIG: ${orphanRelationMap.join(', ')}`);
    for (const [entity, config] of Object.entries(ENTITY_CONFIG)) {
        if (!schemas[config.table]) { errors.push(`ENTITY_CONFIG.${entity}: schema ${config.table} tidak ditemukan`); continue; }
        if (config.parentTable) {
            if (!schemas[config.parentTable]) errors.push(`ENTITY_CONFIG.${entity}: parent schema ${config.parentTable} tidak ditemukan`);
            if (!config.parentField || !schemas[config.table][config.parentField]) errors.push(`ENTITY_CONFIG.${entity}: parentField ${config.parentField || '-'} tidak ada pada schema ${config.table}`);
        }
    }
    for (const [entity, relations] of Object.entries(RELATION_MAP)) {
        if (!Array.isArray(relations)) { errors.push(`RELATION_MAP.${entity} harus berupa array`); continue; }
        const seen = new Set();
        for (const relation of relations) {
            if (!relation || !relation.table || !relation.field) { errors.push(`RELATION_MAP.${entity}: relasi tidak lengkap`); continue; }
            const relationKey = `${relation.table}.${relation.field}`;
            if (seen.has(relationKey)) warnings.push(`RELATION_MAP.${entity}: relasi duplikat ${relationKey}`);
            seen.add(relationKey);
            if (!schemas[relation.table]) { errors.push(`RELATION_MAP.${entity}: tabel ${relation.table} tidak ditemukan`); continue; }
            if (!schemas[relation.table][relation.field]) errors.push(`RELATION_MAP.${entity}: ${relation.table}.${relation.field} tidak ada pada schema`);
            if (relation.where !== undefined && (typeof relation.where !== 'string' || !relation.where.trim())) errors.push(`RELATION_MAP.${entity}: where harus berupa string non-kosong jika digunakan`);
        }
    }
    return { valid: errors.length === 0, errors, warnings };
}

function validateConfigurationContract(env = null) {
    const errors = [];
    const warnings = [];
    for (const key of CONFIG_SCHEMA.ai) if (AI_CONFIG[key] === undefined || AI_CONFIG[key] === null) errors.push(`AI_CONFIG.${key} tidak tersedia`);
    for (const key of CONFIG_SCHEMA.universal) if (UNIVERSAL_CONFIG[key] === undefined || UNIVERSAL_CONFIG[key] === null) errors.push(`UNIVERSAL_CONFIG.${key} tidak tersedia`);
    for (const key of CONFIG_SCHEMA.hybrid) if (HYBRID_CONFIG[key] === undefined || HYBRID_CONFIG[key] === null) errors.push(`HYBRID_CONFIG.${key} tidak tersedia`);
    if (!Number.isFinite(Number(AI_CONFIG.maxTokens?.generate_soal)) || Number(AI_CONFIG.maxTokens.generate_soal) <= 0) errors.push('AI_CONFIG.maxTokens.generate_soal harus > 0');
    if (!Number.isFinite(Number(UNIVERSAL_CONFIG.timeout?.default)) || Number(UNIVERSAL_CONFIG.timeout.default) <= 0) errors.push('UNIVERSAL_CONFIG.timeout.default harus > 0');
    if (!Array.isArray(HYBRID_CONFIG.serialFallback) || HYBRID_CONFIG.serialFallback.length === 0) errors.push('HYBRID_CONFIG.serialFallback harus berisi provider');
    if (Object.keys(AI_CONFIG.apiKeys || {}).length > 0) errors.push('AI_CONFIG.apiKeys tidak boleh berisi credential hardcoded');
    if (!getTelegramToken(env)) warnings.push('Telegram token belum tersedia pada runtime environment');
    if (!getAdminIds(env).length) warnings.push('ADMIN_IDS belum tersedia pada runtime environment');
    return { valid: errors.length === 0, errors, warnings };
}


// ============================================================
// FASE 1 — HIERARCHY VALIDATION CONTRACT
// ============================================================
const ARCHITECTURE_RULES = Object.freeze({
    categories: ['Pekerjaan', 'Mata Pelajaran', 'Mata Kuliah', 'Keterampilan'],
    schoolHierarchy: ['kategori', 'bidang_studi', 'jenjang', 'kelas', 'mata_pelajaran', 'topik', 'sub_topik', 'kisi_kisi', 'kemampuan_diuji', 'sub_kemampuan'],
    higherEducationHierarchy: ['kategori', 'bidang_studi', 'program_studi', 'jenjang', 'mata_kuliah', 'topik', 'sub_topik', 'kisi_kisi', 'kemampuan_diuji', 'sub_kemampuan'],
    higherEducationLevels: ['D3', 'D4', 'S1', 'S2', 'S3'],
    schoolLevels: ['SD', 'SMP', 'SMA', 'SMK'],
    semesterRange: [1, 14]
});

function validateLearningClassification(classification = {}) {
    const errors = [];
    const category = String(classification.kategori || '').trim();
    if (category && !ARCHITECTURE_RULES.categories.includes(category)) {
        errors.push(`Kategori tidak dikenal: ${category}`);
    }
    const difficulty = String(classification.tingkatKesulitan || classification.tingkat_kesulitan || '').trim().toLowerCase();
    if (difficulty && !['mudah', 'sedang', 'sulit', 'kompleks'].includes(difficulty)) {
        errors.push(`Tingkat kesulitan tidak dikenal: ${difficulty}`);
    }
    const cognitive = normalizeCognitiveProcess(classification.prosesKognitif || classification.proses_kognitif || classification.tipeHots || classification.tipe_hots, classification.levelHots || classification.level_hots);
    if ((classification.prosesKognitif || classification.proses_kognitif || classification.tipeHots || classification.tipe_hots || classification.levelHots || classification.level_hots) && !cognitive) {
        errors.push(`Proses kognitif tidak dikenal: ${classification.prosesKognitif || classification.proses_kognitif || classification.tipeHots || classification.tipe_hots}`);
    }
    const semester = classification.semester;
    if (semester !== undefined && semester !== null && semester !== '' && (!Number.isInteger(Number(semester)) || Number(semester) < 1 || Number(semester) > 14)) {
        errors.push('Semester harus 1-14');
    }
    return { valid: errors.length === 0, errors };
}

function validateArchitectureRegistry() {
    const contract = validateArchitectureContracts();
    const errors = [...contract.errors];
    if (!Array.isArray(ARCHITECTURE_RULES.categories) || ARCHITECTURE_RULES.categories.length !== 4) errors.push('ARCHITECTURE_RULES.categories tidak lengkap');
    if (ARCHITECTURE_RULES.higherEducationLevels.join(',') !== 'D3,D4,S1,S2,S3') errors.push('Level pendidikan tinggi tidak sesuai kontrak');
    return { valid: errors.length === 0, errors, warnings: contract.warnings };
}

async function validateHierarchyContext(db, context = {}) {
    const errors = [];
    const category = String(context.kategoriNama || '').trim();
    try {
        if (context.bidangId) {
            const b = await db.prepare(`SELECT id, kategori_id FROM bidang_studi WHERE id = ? LIMIT 1`).bind(context.bidangId).first();
            if (!b) errors.push('Bidang Studi tidak ditemukan.');
            else if (context.kategoriId && b.kategori_id !== context.kategoriId) errors.push('Bidang Studi tidak berada pada Kategori yang dipilih.');
        }
        if (category === 'Mata Pelajaran') {
            if (context.programId) errors.push('Mata Pelajaran tidak boleh memiliki Program Studi pada hierarchy utama.');
            if (context.jenjang) {
                const j = await db.prepare(`SELECT id, jenis FROM jenjang WHERE id = ? LIMIT 1`).bind(context.jenjang).first();
                if (!j || !ARCHITECTURE_RULES.schoolLevels.includes(String(j.jenis || '').toUpperCase())) errors.push('Jenjang Mata Pelajaran harus SD/SMP/SMA/SMK.');
            }
            if (context.kelas) {
                const k = await db.prepare(`SELECT k.id, k.jenjang_id FROM kelas k WHERE k.id = ? LIMIT 1`).bind(context.kelas).first();
                if (!k) errors.push('Kelas tidak ditemukan.');
                else if (context.jenjang && k.jenjang_id !== context.jenjang) errors.push('Kelas tidak sesuai dengan Jenjang.');
            }
            if (context.mataPelajaranId) {
                const mp = await db.prepare(`SELECT id, bidang_studi_id, kelas_id FROM mata_pelajaran WHERE id = ? LIMIT 1`).bind(context.mataPelajaranId).first();
                if (!mp) errors.push('Mata Pelajaran tidak ditemukan.');
                else {
                    if (context.bidangId && mp.bidang_studi_id !== context.bidangId) errors.push('Mata Pelajaran tidak sesuai dengan Bidang Studi.');
                    if (context.kelas && mp.kelas_id !== context.kelas) errors.push('Mata Pelajaran tidak sesuai dengan Kelas.');
                }
            }
        }
        if (category === 'Mata Kuliah') {
            if (!context.programId) errors.push('Mata Kuliah wajib memiliki Program Studi.');
            if (context.programId) {
                const pr = await db.prepare(`SELECT id, bidang_studi_id FROM program_studi WHERE id = ? LIMIT 1`).bind(context.programId).first();
                if (!pr) errors.push('Program Studi tidak ditemukan.');
                else if (context.bidangId && pr.bidang_studi_id !== context.bidangId) errors.push('Program Studi tidak sesuai dengan Bidang Studi.');
            }
            if (context.jenjang) {
                const j = await db.prepare(`SELECT id, jenis FROM jenjang WHERE id = ? LIMIT 1`).bind(context.jenjang).first();
                if (!j || !ARCHITECTURE_RULES.higherEducationLevels.includes(String(j.jenis || '').toUpperCase())) errors.push('Jenjang Mata Kuliah harus D3/D4/S1/S2/S3.');
            }
            if (context.mataKuliahId) {
                const mk = await db.prepare(`SELECT id, program_studi_id, jenjang_id FROM mata_kuliah WHERE id = ? LIMIT 1`).bind(context.mataKuliahId).first();
                if (!mk) errors.push('Mata Kuliah tidak ditemukan.');
                else {
                    if (context.programId && mk.program_studi_id !== context.programId) errors.push('Mata Kuliah tidak sesuai dengan Program Studi.');
                    if (context.jenjang && mk.jenjang_id !== context.jenjang) errors.push('Mata Kuliah tidak sesuai dengan Jenjang.');
                }
            }
        }
    } catch (e) {
        errors.push(`Validasi hierarchy gagal: ${safeErrorMessage(e)}`);
    }
    return { valid: errors.length === 0, errors };
}

const ARCHITECTURE_REGISTRY_RESULT = validateArchitectureRegistry();
if (!ARCHITECTURE_REGISTRY_RESULT.valid) console.error('❌ [ARCHITECTURE REGISTRY]', ARCHITECTURE_REGISTRY_RESULT.errors);
else console.log('✅ [ARCHITECTURE REGISTRY] valid');



