// FASE 1 — MODUL REGISTRY & ERROR CONTRACT
// Struktur logis final dalam satu file; boundary dipakai untuk
// audit dependensi dan menjaga penambahan fitur tetap terarah.
// ============================================================
const MODULE_REGISTRY = {
    configuration: { responsibility: 'runtime config, AI, Telegram, limits, admin' },
    schema: { responsibility: 'ALL_SCHEMAS dan migrasi database' },
    architecture: { responsibility: 'ENTITY_CONFIG, RELATION_MAP, hierarchy validation' },
    persistence: { responsibility: 'query, CRUD, cascade, repository helpers' },
    ai: { responsibility: 'provider routing, fallback, generation, classification' },
    hierarchy: { responsibility: 'kategori, bidang, program, jenjang, kelas, MP, MK, topik' },
    learning_content: { responsibility: 'sub-topik, kisi-kisi, kemampuan, sub-kemampuan, materi' },
    question_engine: { responsibility: 'generator, validator, bank soal, metadata' },
    admin: { responsibility: 'admin menus, CRUD, review, import/export' },
    session_user: { responsibility: 'session, context, user state, recovery' },
    worker: { responsibility: 'HTTP/Telegram entry point dan response lifecycle' }
};

function validateModuleRegistry() {
    const errors = [];
    for (const [name, module] of Object.entries(MODULE_REGISTRY)) {
        if (!module.responsibility) errors.push(`MODULE_REGISTRY.${name} tidak memiliki responsibility`);
    }
    return { valid: errors.length === 0, errors };
}

function createAppError(message, code = 'APP_ERROR', cause = null) {
    const error = new Error(String(message || 'Terjadi kesalahan aplikasi.'));
    error.code = code;
    if (cause) error.cause = cause;
    return error;
}

function safeErrorMessage(error, fallback = 'Terjadi kesalahan. Silakan coba lagi.') {
    const message = String(error?.message || '').trim();
    if (!message) return fallback;
    return message.length > 500 ? `${message.slice(0, 497)}...` : message;
}

function logAppError(scope, error, extra = {}) {
    console.error(`[APP_ERROR] ${scope}`, {
        code: error?.code || 'UNKNOWN',
        message: safeErrorMessage(error),
        ...extra
    });
}

async function withErrorBoundary(scope, handler, options = {}) {
    try {
        return await handler();
    } catch (error) {
        logAppError(scope, error, options.context || {});
        if (typeof options.onError === 'function') return await options.onError(error);
        throw error;
    }
}

const MODULE_CONTRACT_RESULT = validateModuleRegistry();
if (!MODULE_CONTRACT_RESULT.valid) console.error('❌ [MODULE CONTRACT]', MODULE_CONTRACT_RESULT.errors);
else console.log(`✅ [MODULE CONTRACT] valid (${Object.keys(MODULE_REGISTRY).length} modul logis)`);

const ARCHITECTURE_CONTRACT_RESULT = validateArchitectureContracts();
