// ============================================================
// HELPER: Ambil daftar master dari DB berdasarkan key
// ============================================================
async function getMasterKeterangan(db, key, page = 1) {
    const cfg = MASTER_KETERANGAN_CONFIG[key];
    if (!cfg) return null;
    
    const perPage = cfg.perPage || 5;
    const offset = (page - 1) * perPage;
    
    // Hitung total
    const countRow = await db.prepare(
        `SELECT COUNT(*) AS total FROM ${cfg.table}`
    ).first();
    const total = countRow?.total || 0;
    const totalPages = Math.max(1, Math.ceil(total / perPage));
    
    // Ambil data
    const rows = await db.prepare(
        `SELECT * FROM ${cfg.table} 
         ORDER BY ${cfg.codeField} ASC 
         LIMIT ? OFFSET ?`
    ).bind(perPage, offset).all();
    
    return {
        cfg,
        page,
        totalPages,
        total,
        items: rows.results || []
    };
}

// ============================================================
// HELPER: Format 1 baris master → [ KODE ] — Nama
// ============================================================
function formatMasterKeteranganRow(item, cfg) {
    const kode = item[cfg.codeField] || item.id || '-';
    const nama = item[cfg.nameField] || '-';
    const desc = item[cfg.descField];
    
    let line = `[ ${kode} ] — ${nama}`;
    if (desc && String(desc).trim().length > 0) {
        const shortDesc = String(desc).length > 80 
            ? String(desc).substring(0, 80) + '...' 
            : String(desc);
        line += `\n     _${shortDesc}_`;
    }
    return line;
}

