// ============================================================
// 🆕 HELPER: PARSE DINAMIS NAMA + DESKRIPSI
// Dukung format:
// - "Nama : X"  /  "Nama: X"  /  "nama : X"
// - "Judul : X" (untuk kisi)
// - "Deskripsi : X"  /  "Desc: X"
// - "X\nDeskripsi Y" (baris 1 = nama)
// - "X;Y"  /  "X,Y"  /  "X | Y"
// ============================================================
function parseDynamicNamaDesc(part) {
    const result = { nama: null, deskripsi: null };
    if (!part) return result;
    
    const lines = part.split('\n').map(l => l.trim()).filter(Boolean);
    if (lines.length === 0) return result;
    
    // Try format dengan kunci
    let foundNama = false;
    let foundDesc = false;
    
    for (const line of lines) {
        // Cek Nama/Judul
        const namaMatch = line.match(/^(?:nama|judul)\s*[:=]\s*(.+)$/i);
        if (namaMatch && !foundNama) {
            result.nama = namaMatch[1].trim();
            foundNama = true;
            continue;
        }
        
        // Cek Deskripsi
        const descMatch = line.match(/^(?:desc|deskripsi)\s*[:=]\s*(.+)$/i);
        if (descMatch && !foundDesc) {
            result.deskripsi = descMatch[1].trim();
            foundDesc = true;
            continue;
        }
    }
    
    // Kalau tidak ada format kunci, coba split dengan pemisah
    if (!foundNama) {
        // Coba ; atau , atau |
        const sepMatch = lines[0].match(/^(.+?)\s*[;,|]\s*(.+)$/);
        if (sepMatch) {
            result.nama = sepMatch[1].trim();
            result.deskripsi = sepMatch[2].trim();
            return result;
        }
        
        // Format bebas: baris 1 = nama, baris 2+ = deskripsi
        result.nama = lines[0];
        if (lines.length > 1) {
            result.deskripsi = lines.slice(1).join(' ');
        }
    }
    
    // Kalau ada nama tapi tidak ada deskripsi
    if (result.nama && !result.deskripsi) {
        const remainingLines = lines.filter(l => {
            const namaM = l.match(/^(?:nama|judul)\s*[:=]/i);
            return !namaM;
        });
        if (remainingLines.length > 0) {
            result.deskripsi = remainingLines.join(' ');
        }
    }
    
    return result;
}

