// 🆕 FUNGSI: HANDLE ENTITY LIST (HALAMAN 1 = LIST LANGSUNG)
// ============================================================
const ENTITY_PAGE_SIZE=Object.freeze({kategori:5,bidang:5,program:5,mata_pelajaran:5,mata_kuliah:5,jenjang:5,kelas:5,topik:5,subtopik:5,kisi:5,kemampuan:5,subkemampuan:5,soal:5,user:5});
function getEntityPageSize(entity){return Number(ENTITY_PAGE_SIZE[String(entity||'').toLowerCase()])||10;}

async function handleEntityList(env, userId, chatId, entity, page = 1, editMode = false, explicitMessageId = null) {
    const db = await getDatabase(env);
    const config = getEntityConfig(entity);
    
    if (!config) {
        await sendMessage(chatId, `❌ Entitas "${entity}" tidak dikenal.`);
        return;
    }
    
    const nameField = config.nameField || 'nama';
    const perPage = getEntityPageSize(entity);
    
    const count = await db.prepare(`SELECT COUNT(*) AS total FROM ${config.table}`).first();
    const totalItems = count?.total || 0;
    const totalPages = Math.ceil(totalItems / perPage) || 1;
    const currentPage = Math.min(Math.max(page, 1), totalPages);
    const currentOffset = (currentPage - 1) * perPage;
    
    // ============================================================
    // QUERY LIST
    // ============================================================
    const r = await db.prepare(`
        SELECT * FROM ${config.table} 
        ORDER BY urutan ASC, id ASC 
        LIMIT ? OFFSET ?
    `).bind(perPage, currentOffset).all();
    
    const hasil = (r && r.results) ? r.results : [];
    
    // ============================================================
    // BUILD MESSAGE (PERSIS KODE LAMA KATEGORI)
    // ============================================================
    let msg = `${config.icon} *DAFTAR ${config.labelPlural.toUpperCase()}*\n${DIVIDER}\n\n`;
    
    if (hasil.length === 0) {
        msg += `_(Belum ada ${config.label})_\n`;
    } else {
        msg += `📊 Total : ${totalItems} item • Hal ${currentPage}/${totalPages}\n\n`;
        
        const items = hasil.map(k => ({
            nama: k[nameField],
            id: k.id,
            deskripsi: k.deskripsi || 'Tidak ada deskripsi',
            extraLines: []
        }));
        
        if (typeof buildListView === 'function') {
            msg += buildListView(items, { startNumber: currentOffset });
        } else {
            hasil.forEach((k, i) => {
                msg += `${i + currentOffset + 1}. ${k[nameField]}\n`;
                msg += `   🆔 ID : ${k.id}\n`;
                msg += `   📝 Deskripsi : ${k.deskripsi || 'Tidak ada deskripsi'}\n\n`;
            });
        }
        msg += `\n`;
    }
    
    // ============================================================
    // BUILD KEYBOARD (PERSIS KODE LAMA KATEGORI)
    // ============================================================
    const keyboard = [];
    
    // Pagination
    if (totalPages > 1) {
        const navButtons = [];
        if (currentPage > 1) navButtons.push({ 
            text: "⬅️ Prev", 
            callback_data: `ent_list_${entity}_page_${currentPage - 1}` 
        });
        navButtons.push({ 
            text: `📄 ${currentPage}/${totalPages}`, 
            callback_data: `ent_list_${entity}_jump` 
        });
        if (currentPage < totalPages) navButtons.push({ 
            text: "Next ➡️", 
            callback_data: `ent_list_${entity}_page_${currentPage + 1}` 
        });
        keyboard.push(navButtons);
    }
    
    const idButtons=hasil.map(k=>({text:`🆔 ${k.id}`,callback_data:`ent_view_${entity}_${k.id}`}));
    for(let i=0;i<idButtons.length;i+=5) keyboard.push(idButtons.slice(i,i+5));
    keyboard.push([{text:`🔙 Kembali ke Menu ${config.label}`,callback_data:config.menuCallback}]);
    
    // ============================================================
    // KIRIM
    // ============================================================
    // ✅ Pakai explicitMessageId jika ada, fallback ke callback context
    const messageId = explicitMessageId || getCallbackMessageId();
    await smartResponseUniversal(chatId, msg, {
        keyboard,
        mode: editMode ? 'edit' : 'auto',
        messageId
    });
}


