const autoClassifyCache = new Map();

function buildAutoClassifyCacheKey(soalText, pilihanJawaban = null, options = {}) {
    const stable = (value) => {
        if (value === null || value === undefined) return null;
        if (Array.isArray(value)) return value.map(stable);
        if (typeof value === 'object') {
            return Object.keys(value).sort().reduce((out, key) => {
                out[key] = stable(value[key]);
                return out;
            }, {});
        }
        return value;
    };
    return JSON.stringify({
        soal: String(soalText || '').trim(),
        pilihanJawaban: String(pilihanJawaban || '').trim(),
        fillOnly: stable(options.fillOnly || null),
        adminContext: stable(options.adminContext || null)
    });
}

function getCachedAutoClassify(soalText, pilihanJawaban = null, options = {}) {
    const key = buildAutoClassifyCacheKey(soalText, pilihanJawaban, options);
    if (autoClassifyCache.has(key)) {
        const cached = autoClassifyCache.get(key);
        if (Date.now() - cached.timestamp < 86400000) {
            return cached.data;
        }
        autoClassifyCache.delete(key);
    }
    return null;
}

function setCachedAutoClassify(soalText, pilihanJawaban = null, data, options = {}) {
    const key = buildAutoClassifyCacheKey(soalText, pilihanJawaban, options);
    autoClassifyCache.set(key, {
        data: data,
        timestamp: Date.now()
    });
    if (autoClassifyCache.size > 500) {
        const oldest = [...autoClassifyCache.entries()]
            .sort((a, b) => a[1].timestamp - b[1].timestamp)[0];
        autoClassifyCache.delete(oldest[0]);
    }
}



// ============================================================
// AUTO-CLASSIFY WITH AI
// VERSI FINAL: Support jenjang & kelas
// ============================================================
async function autoClassifyWithAI(soalText, pilihanJawaban = null, options = {}) {
    const { fillOnly = null, adminContext = null, env = null } = options;
    
    const prompt = buildAutoClassifyPromptDynamic(
        soalText, 
        pilihanJawaban, 
        fillOnly, 
        adminContext
    );
    
    try {
        const result = await callAIHybrid(prompt, 'classify_soal', env);
        
        if (!result.success) {
            return ruleBasedClassifyComplete(soalText);
        }
        
        const jsonMatch = result.response.match(/\{[\s\S]*\}/);
        if (jsonMatch) {
            const data = JSON.parse(jsonMatch[0]);
            
            const tahapId = data.tahap || 'T1';
            const prosesKognitif = getProsesKognitif(data.prosesKognitif || data.proses_kognitif || data.tipeHots || data.tipe_hots) || 'LOTS';
            const kompleksitas = getKompleksitasFromTahap(tahapId);
            const tipeHots = prosesKognitif;
            const tingkatKesulitan = getDefaultDifficulty(data.tingkatKesulitan || data.tingkat_kesulitan);
            const lapisan = getLapisanFromTahap(tahapId);
            
            return {
                kategori: data.kategori || null,
                bidang: data.bidang || null,
                program: data.program || null,
                topik: data.topik || null,
                subtopik: data.subtopik || null,
                kisi: data.kisi || null,
                kemampuan: data.kemampuan || null,
                subKemampuan: data.subKemampuan || null,
                
                // 🆕 JENJANG & KELAS
                jenjang: data.jenjang || null,
                kelas: data.kelas || null,
                
                caraPenyajian: data.caraPenyajian || null,
                tipeIsi: data.tipeIsi || null,
                kompleksitas: kompleksitas,
                tahap: tahapId,
                tipeHots: tipeHots,
                levelHots: null,
                prosesKognitif: prosesKognitif,
                tingkatKesulitan: tingkatKesulitan,
                lapisan: lapisan,
                
                sumber: data.sumber || null,
                link: data.link || null,
                keabsahan: data.keabsahan || 'mandiri',
                
                confidence: data.confidence || 0.7,
                provider: result.provider,
                timestamp: Date.now()
            };
        }
        
        return ruleBasedClassifyComplete(soalText);
        
    } catch (e) {
        console.error('Auto-classify AI error:', e);
        return ruleBasedClassifyComplete(soalText);
    }
}

function buildRegenerateSoalPrompt(soalAsli, pilihanAsli, jawabanAsli, variation = 'serupa') {
    const varLabels = {
        'serupa': 'Serupa (angka/konteks berbeda)',
        'konteks': 'Konteks berbeda',
        'sulit': 'Lebih Sulit',
        'mudah': 'Lebih Mudah'
    };

    // ============================================================
    // 🆕 DETEKSI JENJANG
    // ============================================================
    const jenjang = REGEN_RULES.detectJenjang(soalAsli);
    const jenjangRules = REGEN_RULES.perJenjang[jenjang] || REGEN_RULES.perJenjang['Umum'];

    return `
${REGEN_RULES.peran || 'Anda adalah guru ahli yang membuat variasi soal.'}

${RULE_GLOBAL}

${jenjangRules}

TUGAS: Buat variasi soal berikut.

SOAL ASLI:
${soalAsli}

PILIHAN ASLI:
${pilihanAsli}

JAWABAN ASLI: ${jawabanAsli}

TUJUAN VARIASI: ${varLabels[variation] || variation}

${REGEN_RULES.format}

${REGEN_RULES.larangan}

⚠️ PENTING: Sesuaikan tingkat kesulitan dan bahasa dengan JENJANG ${jenjang}.

Mulai buat variasi soal:
`;
}

// ============================================================
// 🔴 RULE-BASED FALLBACK - VERSI FINAL DENGAN DEFAULT LENGKAP
// Lokasi: Ganti fungsi ruleBasedClassifyComplete() yang lama
// ============================================================

function ruleBasedClassifyComplete(soalText) {
    const text = (soalText || '').toLowerCase();
    
    // ============================================================
    // NILAI AWAL KOSONG — TIDAK BOLEH MENGARANG MASTER DEFAULT
    // ============================================================
    let caraPenyajian = null;
    let tipeIsi = null;
    let tahap = null;
    let legacyLevelHots = null;
    let keabsahan = null;
    
    // ============================================================
    // DETEKSI CARA PENYAJIAN
    // ============================================================
    if (/cerita|narasi|kisah|dongeng/.test(text)) caraPenyajian = 'P03';
    else if (/kasus|studi kasus/.test(text)) caraPenyajian = 'P05';
    else if (/dialog|percakapan|wawancara/.test(text)) caraPenyajian = 'P06';
    else if (/urutkan|langkah|prosedur|tahapan/.test(text)) caraPenyajian = 'P07';
    else if (/tabel|data|statistik|dataset/.test(text)) caraPenyajian = 'P08';
    else if (/grafik|diagram|chart/.test(text)) caraPenyajian = 'P09';
    else if (/gambar|ilustrasi|foto/.test(text)) caraPenyajian = 'P11';
    else if (/peta|lokasi|wilayah/.test(text)) caraPenyajian = 'P12';
    else if (/infografis/.test(text)) caraPenyajian = 'P13';
    else if (/audio|rekaman|suara/.test(text)) caraPenyajian = 'P14';
    else if (/video|tonton|putar/.test(text)) caraPenyajian = 'P15';
    else if (/percobaan|eksperimen|simulasi/.test(text)) caraPenyajian = 'P16';
    
    // ============================================================
    // DETEKSI TIPE ISI
    // ============================================================
    if (/definisi|pengertian|istilah|tokoh|tahun/.test(text)) tipeIsi = 'TI01';
    else if (/konsep|prinsip|karakteristik|hubungan/.test(text)) tipeIsi = 'TI02';
    else if (/rumus|langkah|metode|prosedur|algoritma/.test(text)) tipeIsi = 'TI03';
    else if (/hitung|jumlah|operasi|perhitungan/.test(text)) tipeIsi = 'TI04';
    else if (/terapkan|gunakan|aplikasi|penerapan/.test(text)) tipeIsi = 'TI05';
    else if (/analisis|analisa|hubungan|pola/.test(text)) tipeIsi = 'TI06';
    else if (/evaluasi|nilai|kriteria|penilaian/.test(text)) tipeIsi = 'TI07';
    else if (/pecahkan|solusi|strategi|keputusan/.test(text)) tipeIsi = 'TI08';
    else if (/rancang|desain|kembangkan|kreatif/.test(text)) tipeIsi = 'TI09';
    else if (/eksperimen|hipotesis|variabel/.test(text)) tipeIsi = 'TI10';
    else if (/bahasa|makna|argumentasi|bacaan/.test(text)) tipeIsi = 'TI11';
    
    // ============================================================
    // DETEKSI TAHAP
    // ============================================================
    if (/definisi|pengertian|ciri-ciri|unsur/.test(text)) tahap = 'T1';
    else if (/tujuan|fungsi|manfaat|prinsip|hubungan/.test(text)) tahap = 'T2';
    else if (/rumus|metode|prosedur|mekanisme/.test(text)) tahap = 'T3';
    else if (/terapkan|aplikasi|penerapan|contoh/.test(text)) tahap = 'T4';
    else if (/kombinasi|gabungan|multi konsep/.test(text)) tahap = 'T5';
    else if (/analisis|sebab-akibat|hubungan/.test(text)) tahap = 'T6';
    else if (/studi kasus|kasus nyata|kompleks/.test(text)) tahap = 'T7';
    else if (/hots|evaluasi|kreasi|tingkat tinggi/.test(text)) tahap = 'T8';
    else if (/komprehensif|menyeluruh|integrasi/.test(text)) tahap = 'T9';
    
    // ============================================================
    // DETEKSI PROSES KOGNITIF — LOTS / MOTS / HOTS
    // ============================================================
    const prosesKognitif = /analisis|evaluasi|kritik|justifikasi|rekomendasi|desain|ciptakan|formulasikan|rancang|strategi|keputusan|studi kasus/.test(text)
        ? 'HOTS'
        : /hitung|selesaikan|terapkan|gunakan|bandingkan|pecahkan|kontraskan|kategorikan|solusi/.test(text)
            ? 'MOTS'
            : 'LOTS';
    
    // ============================================================
    // DETEKSI KEABSAHAN
    // ============================================================
    if (/resmi|pemerintah|kemendikbud|kemdikbud|buku teks|kurikulum/.test(text)) {
        keabsahan = 'resmi';
    } else if (/adaptasi|modifikasi|sumber lain/.test(text)) {
        keabsahan = 'adaptasi';
    }
    
    // ============================================================
    // AUTO-MAPPING
    // ============================================================
    const kompleksitas = tahap ? getKompleksitasFromTahap(tahap) : null;
    const tipeHots = prosesKognitif;
    const tingkatKesulitan = getDefaultDifficulty(
        /rancang|desain|kembangkan|evaluasi|kritik|justifikasi|strategi|keputusan|studi kasus|kompleks/.test(text) ? 'KOMPLEKS' :
        /analisis|kontraskan|kategorikan|pecahkan|solusi/.test(text) ? 'SULIT' :
        /hitung|terapkan|gunakan|bandingkan/.test(text) ? 'SEDANG' : 'MUDAH'
    );
    const lapisan = tahap ? getLapisanFromTahap(tahap) : null;
    
    // ============================================================
    // RETURN DENGAN DEFAULT LENGKAP
    // ============================================================
    return {
        // HIERARKI: jangan mengarang entity default. Jika tidak dapat ditentukan,
        // hasil harus masuk validation gate dan meminta klasifikasi yang benar.
        kategori: null,
        bidang: null,
        program: null,
        topik: null,
        subtopik: null,
        kisi: null,
        kemampuan: null,
        subKemampuan: null,
        
        // MASTER DATA
        caraPenyajian: caraPenyajian,
        tipeIsi: tipeIsi,
        kompleksitas: kompleksitas,
        tahap: tahap,
        tipeHots: tipeHots,
        levelHots: null,
        prosesKognitif: tipeHots,
        tingkatKesulitan: tingkatKesulitan,
        lapisan: lapisan,
        
        // SUMBER (boleh NULL karena opsional)
        sumber: null,
        link: null,
        
        // KEABSAHAN
        keabsahan: keabsahan,
        
        // METADATA
        confidence: 0.5,
        fallbackUsed: false,
        provider: 'rule-based',
        timestamp: Date.now()
    };
}


// ============================================================
// 🔴 GET MASTER IDS - LENGKAP DENGAN FALLBACK
// VERSI FINAL: Support jenjang & kelas
// ============================================================
function normalizeTopicName(value) {
    return String(value || '')
        .normalize('NFKC')
        .toLowerCase()
        .replace(/[\u0000-\u001f\u007f]/g, ' ')
        .replace(/[^\p{L}\p{N}\s]+/gu, ' ')
        .replace(/\s+/g, ' ')
        .trim();
}

async function findDuplicateTopic(db, { name, excludeId = null } = {}) {
    const normalized = normalizeTopicName(name);
    if (!normalized) return null;
    // CANONICAL ANTI-DUPLICATE: satu konsep = satu Topik lintas jenjang, kelas,
    // program studi, mata pelajaran, dan mata kuliah. Konteks disimpan terpisah.
    const clauses = ['(normalized_nama = ? OR (normalized_nama IS NULL AND LOWER(TRIM(nama)) = LOWER(TRIM(?))))'];
    const binds = [normalized, String(name || '').trim()];
    if (excludeId) { clauses.push('id <> ?'); binds.push(excludeId); }
    return await db.prepare(`SELECT id, nama, normalized_nama FROM topik WHERE ${clauses.join(' AND ')} LIMIT 1`).bind(...binds).first();
}

async function getOrCreateTopicStrict(db, { name, programId = null, mataPelajaranId = null, mataKuliahId = null, autoCreate = true, prefix = 'T' } = {}) {
    const clean = String(name || '').trim();
    const normalized = normalizeTopicName(clean);
    if (!clean || !normalized) return { id: null, created: false, error: 'Nama Topik wajib diisi.' };
    const existing = await findDuplicateTopic(db, { name: clean, programId, mataPelajaranId, mataKuliahId });
    if (existing) return { id: existing.id, created: false, existing };
    if (!autoCreate) return { id: null, created: false, error: `Topik "${clean}" tidak ditemukan.` };
    const id = await generateId(db, prefix, 'topik');
    await db.prepare(`
        INSERT INTO topik (id, program_studi_id, mata_pelajaran_id, mata_kuliah_id, nama, normalized_nama, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?)
    `).bind(id, programId, mataPelajaranId, mataKuliahId, clean, normalized, new Date().toISOString()).run();
    return { id, created: true };
}

async function getMasterIdsComplete(db, classification, autoCreate = true) {
    const result = {
        // HIERARKI IDs
        kategoriId: null,
        bidangId: null,
        programId: null,
        jenjangId: null,
        kelas: null,
        mataPelajaranId: null,
        mataKuliahId: null,
        topikId: null,
        subtopikId: null,
        kisiId: null,
        kemampuanId: null,
        subKemampuanId: null,
        
        // MASTER IDs
        penyajianId: null,
        tipeIsiId: null,
        tahapId: null,
        lapisanId: null,
        sumberId: null,
        
        // TRACKING
        createdItems: [],
        missingItems: [],
        foundItems: [],
        fallbackItems: [],
        warnings: []
    };
    
    // ============================================================
    // HELPER: Get or Create Generic
    // ============================================================
    async function getOrCreate(table, nameField, nameValue, prefix, parentField = null, parentId = null) {
        // INTEGRITY GATE: nama kosong tidak boleh menghasilkan data default/palsu.
        if (!nameValue || String(nameValue).trim() === '') {
            result.missingItems.push(`❌ ${table}: nama wajib diisi`);
            return null;
        }
        
        const cleanValue = String(nameValue).trim();
        
        try {
            // INTEGRITY GATE: child tanpa parent eksplisit tidak boleh dipindahkan
            // diam-diam ke parent pertama/default.
            if (parentField && !parentId) {
                result.missingItems.push(`❌ ${table}: parent ${parentField} wajib ditentukan`);
                return null;
            }
            
            // Build query
            let query = `SELECT id FROM ${table} WHERE LOWER(TRIM(${nameField})) = LOWER(TRIM(?))`;
            let bind = [cleanValue];
            
            if (parentField && parentId) {
                query += ` AND ${parentField} = ?`;
                bind.push(parentId);
            }
            query += ` LIMIT 1`;
            
            let row = await db.prepare(query).bind(...bind).first();
            
            if (row) {
                result.foundItems.push(`✅ ${table}: ${cleanValue} [${row.id}]`);
                return row.id;
            }
            
            // Parent wajib tersedia sebelum child dibuat. Jangan pernah membuat
            // child tanpa FK parent hanya karena parent gagal di-resolve.
            if (parentField && !parentId) {
                result.missingItems.push(`❌ ${table}: parent ${parentField} tidak valid/tidak ditemukan`);
                return null;
            }

            // Auto-create jika diizinkan
            if (!autoCreate) {
                result.missingItems.push(`❌ ${table}: ${cleanValue} (tidak ditemukan)`);
                return null;
            }
            
            // TOPIK wajib memakai normalized_nama agar semua jalur konsisten.
            if (table === 'topik') {
                const topic = await getOrCreateTopicStrict(db, {
                    name: cleanValue,
                    programId: parentField === 'program_studi_id' ? parentId : null,
                    autoCreate
                });
                if (topic.id && topic.created) result.createdItems.push(`🆕 topik: ${cleanValue} [${topic.id}]`);
                else if (topic.id) result.foundItems.push(`✅ topik: ${cleanValue} [${topic.id}]`);
                else result.missingItems.push(`❌ topik: ${cleanValue}`);
                return topic.id;
            }

            // Generate ID baru
            let newId;
            if (table === 'kemampuan_diuji') {
                newId = await generateKemampuanId(db);
            } else if (table === 'sub_kemampuan') {
                newId = await generateSubKemampuanId(db);
            } else {
                newId = await generateId(db, prefix, table);
            }
            
            // Build INSERT
            const insertFields = ['id', nameField];
            const insertValues = [newId, cleanValue];
            
            if (parentField && parentId) {
                insertFields.push(parentField);
                insertValues.push(parentId);
            }
            
            insertFields.push('created_at');
            insertValues.push(new Date().toISOString());
            
            const placeholders = insertFields.map(() => '?').join(', ');
            await db.prepare(`
                INSERT INTO ${table} (${insertFields.join(', ')}) 
                VALUES (${placeholders})
            `).bind(...insertValues).run();
            
            result.createdItems.push(`🆕 ${table}: ${cleanValue} [${newId}]`);
            return newId;
            
        } catch (e) {
            result.warnings.push(`⚠️ Gagal buat ${table} "${cleanValue}": ${e.message}`);
            console.error(`getOrCreate error for ${table}:`, e);
            return null;
        }
    }
    
    // ============================================================
    // HELPER: Get Master dengan Fallback
    // ============================================================
    async function getMasterExact(table, codeField, codeValue, idField = 'id') {
        // INTEGRITY GATE: nama/kode master harus cocok persis. Tidak ada fallback
        // diam-diam ke P01/TI01/T1/dll karena itu dapat mengubah klasifikasi soal.
        const cleanCode = String(codeValue || '').trim().toUpperCase();
        if (!cleanCode) {
            result.missingItems.push(`❌ ${table}: kode master kosong`);
            return null;
        }
        try {
            const row = await db.prepare(`SELECT ${idField} FROM ${table} WHERE ${codeField} = ? OR ${idField} = ? LIMIT 1`).bind(cleanCode, cleanCode).first();
            if (row) {
                result.foundItems.push(`✅ ${table}: ${cleanCode} [${row[idField]}]`);
                return row[idField];
            }
            result.missingItems.push(`❌ ${table}: ${cleanCode} tidak ditemukan`);
            return null;
        } catch (e) {
            result.missingItems.push(`❌ ${table}: ${cleanCode} gagal divalidasi`);
            return null;
        }
    }

    // ============================================================
    // 🆕 HELPER: Resolve Jenjang (dari nama/kode)
    // ============================================================
    async function resolveJenjang(jenjangValue) {
        if (!jenjangValue) return null;
        
        const cleanValue = String(jenjangValue).trim();
        if (!cleanValue) return null;
        
        try {
            // Coba cari by ID dulu
            let row = await db.prepare(
                `SELECT id FROM jenjang WHERE id = ? LIMIT 1`
            ).bind(cleanValue.toUpperCase()).first();
            
            if (row) {
                result.foundItems.push(`✅ jenjang: ${cleanValue} [${row.id}]`);
                return row.id;
            }
            
            // Coba cari by nama (case insensitive)
            row = await db.prepare(
                `SELECT id FROM jenjang WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) LIMIT 1`
            ).bind(cleanValue).first();
            
            if (row) {
                result.foundItems.push(`✅ jenjang: ${cleanValue} [${row.id}]`);
                return row.id;
            }
            
            // Tidak ditemukan
            result.missingItems.push(`❌ jenjang: "${cleanValue}" tidak ditemukan`);
            return null;
            
        } catch (e) {
            result.warnings.push(`⚠️ Error resolve jenjang: ${e.message}`);
            return null;
        }
    }
    
    // ============================================================
    // 🆕 HELPER: Resolve Mata Pelajaran (nama/kode + Bidang + Kelas)
    // ============================================================
    async function resolveMataPelajaran(db, value, bidangId, kelasId) {
        if (!value || !bidangId || !kelasId) return null;
        const clean = String(value).trim();
        if (!clean) return null;
        try {
            const row = await db.prepare(`
                SELECT id FROM mata_pelajaran
                WHERE bidang_studi_id = ? AND kelas_id = ?
                  AND (LOWER(TRIM(nama)) = LOWER(TRIM(?)) OR LOWER(TRIM(COALESCE(kode,''))) = LOWER(TRIM(?)))
                LIMIT 1
            `).bind(bidangId, kelasId, clean, clean).first();
            if (row) { result.foundItems.push(`✅ mata_pelajaran: ${clean} [${row.id}]`); return row.id; }
            result.missingItems.push(`⚠️ mata_pelajaran: "${clean}" tidak ditemukan pada Bidang + Kelas tersebut`);
            return null;
        } catch (e) {
            result.warnings.push(`⚠️ Error resolve mata_pelajaran: ${e.message}`);
            return null;
        }
    }

    // ============================================================
    // 🆕 HELPER: Resolve Mata Kuliah (nama/kode + Program + Jenjang)
    // ============================================================
    async function resolveMataKuliah(db, value, programId, jenjangId) {
        if (!value || !programId || !jenjangId || jenjangId === 'all') return null;
        const clean = String(value).trim();
        if (!clean) return null;
        try {
            const row = await db.prepare(`
                SELECT id FROM mata_kuliah
                WHERE program_studi_id = ? AND jenjang_id = ?
                  AND (LOWER(TRIM(nama)) = LOWER(TRIM(?)) OR LOWER(TRIM(COALESCE(kode,''))) = LOWER(TRIM(?)))
                LIMIT 1
            `).bind(programId, jenjangId, clean, clean).first();
            if (row) { result.foundItems.push(`✅ mata_kuliah: ${clean} [${row.id}]`); return row.id; }
            result.missingItems.push(`⚠️ mata_kuliah: "${clean}" tidak ditemukan pada Program + Jenjang tersebut`);
            return null;
        } catch (e) {
            result.warnings.push(`⚠️ Error resolve mata_kuliah: ${e.message}`);
            return null;
        }
    }

    // ============================================================
    // 🆕 HELPER: Resolve Kelas (dari nama/kode/angka)
    // ============================================================
    async function resolveKelas(kelasValue) {
        if (!kelasValue) return null;
        
        const cleanValue = String(kelasValue).trim();
        if (!cleanValue) return null;
        
        try {
            // Coba cari by ID langsung
            let row = await db.prepare(
                `SELECT id FROM kelas WHERE id = ? LIMIT 1`
            ).bind(cleanValue.toUpperCase()).first();
            
            if (row) {
                result.foundItems.push(`✅ kelas: ${cleanValue} [${row.id}]`);
                return row.id;
            }
            
            // Coba cari by nama (case insensitive)
            row = await db.prepare(
                `SELECT id FROM kelas WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) LIMIT 1`
            ).bind(cleanValue).first();
            
            if (row) {
                result.foundItems.push(`✅ kelas: ${cleanValue} [${row.id}]`);
                return row.id;
            }
            
            // Kalau angka, coba format "Kelas X"
            if (/^\d+$/.test(cleanValue)) {
                row = await db.prepare(
                    `SELECT id FROM kelas WHERE LOWER(nama) = LOWER(?) OR LOWER(nama) = LOWER(?) LIMIT 1`
                ).bind(`kelas ${cleanValue}`, `kelas ${cleanValue.padStart(2, '0')}`).first();
                
                if (row) {
                    result.foundItems.push(`✅ kelas: ${cleanValue} → [${row.id}] (format "Kelas X")`);
                    return row.id;
                }
            }
            
            // Tidak ditemukan
            result.missingItems.push(`❌ kelas: "${cleanValue}" tidak ditemukan`);
            return null;
            
        } catch (e) {
            result.warnings.push(`⚠️ Error resolve kelas: ${e.message}`);
            return null;
        }
    }
    
    try {
        // ============================================================
        // 1-8. HIERARKI (Kategori → Sub-Kemampuan)
        // ============================================================
        
        // 1. KATEGORI
        result.kategoriId = await getOrCreate(
            'kategori', 'nama', 
            classification.kategori || '', 
            'K'
        );
        
        // 2. BIDANG STUDI
        result.bidangId = await getOrCreate(
            'bidang_studi', 'nama', 
            classification.bidang || '', 
            'B', 'kategori_id', result.kategoriId
        );
        
        // 3. PROGRAM STUDI
        // Mata Pelajaran berhenti di Bidang → Jenjang → Kelas → Mata Pelajaran.
        // Mata Kuliah tetap memakai Bidang → Program → Jenjang → Mata Kuliah.
        const isMataPelajaran = String(classification.kategori || '').trim() === 'Mata Pelajaran';
        if (!isMataPelajaran) {
            result.programId = await getOrCreate(
                'program_studi', 'nama',
                classification.program || '',
                'P', 'bidang_studi_id', result.bidangId
            );
        } else {
            result.programId = null;
        }
        
        // 🆕 3.5. JENJANG & KELAS (sebelum topik)
        result.jenjangId = await resolveJenjang(classification.jenjang);
        result.kelas = await resolveKelas(classification.kelas);
        result.mataPelajaranId = await resolveMataPelajaran(
            db,
            classification.mata_pelajaran || classification.mataPelajaran,
            result.bidangId,
            result.kelas
        );
        result.mataKuliahId = await resolveMataKuliah(db, classification.mata_kuliah || classification.mataKuliah, result.programId, result.jenjangId);
        
        // 4. TOPIK
        const topikName = classification.topik || '';
        if (result.mataPelajaranId) {
            try {
                const existingTopik = await db.prepare(`
                    SELECT id FROM topik
                    WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?))
                      AND mata_pelajaran_id = ? LIMIT 1
                `).bind(topikName, result.mataPelajaranId).first();
                if (existingTopik) {
                    result.topikId = existingTopik.id;
                    result.foundItems.push(`✅ topik: ${topikName} [${existingTopik.id}] dalam Mata Pelajaran [${result.mataPelajaranId}]`);
                } else if (autoCreate) {
                    const created = await getOrCreateTopicStrict(db, {
                        name: topikName, mataPelajaranId: result.mataPelajaranId, autoCreate: true
                    });
                    if (created.error) throw new Error(created.error);
                    result.topikId = created.id;
                    result.createdItems.push(`🆕 topik: ${topikName} [${created.id}] dalam Mata Pelajaran [${result.mataPelajaranId}]`);
                } else {
                    result.missingItems.push(`❌ topik: ${topikName} tidak ditemukan dalam Mata Pelajaran [${result.mataPelajaranId}]`);
                }
            } catch (e) {
                result.warnings.push(`⚠️ Error resolve topik dalam Mata Pelajaran: ${e.message}`);
                result.topikId = null;
            }
        } else if (result.mataKuliahId) {
            try {
                const existingTopik = await db.prepare(`
                    SELECT id FROM topik
                    WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?))
                      AND program_studi_id = ? AND mata_kuliah_id = ? LIMIT 1
                `).bind(topikName, result.programId, result.mataKuliahId).first();
                if (existingTopik) {
                    result.topikId = existingTopik.id;
                    result.foundItems.push(`✅ topik: ${topikName} [${existingTopik.id}] dalam Mata Kuliah [${result.mataKuliahId}]`);
                } else if (autoCreate) {
                    const created = await getOrCreateTopicStrict(db, {
                        name: topikName, programId: result.programId, mataKuliahId: result.mataKuliahId, autoCreate: true
                    });
                    if (created.error) throw new Error(created.error);
                    result.topikId = created.id;
                    result.createdItems.push(`🆕 topik: ${topikName} [${created.id}] dalam Mata Kuliah [${result.mataKuliahId}]`);
                } else {
                    result.missingItems.push(`❌ topik: ${topikName} tidak ditemukan dalam Mata Kuliah [${result.mataKuliahId}]`);
                }
            } catch (e) {
                result.warnings.push(`⚠️ Error resolve topik dalam Mata Kuliah: ${e.message}`);
                result.topikId = null;
            }
        } else {
            result.topikId = await getOrCreate(
                'topik', 'nama', topikName, 'T', 'program_studi_id', result.programId
            );
        }
        
        // 5. SUB-TOPIK
        result.subtopikId = await getOrCreate(
            'sub_topik', 'nama', 
            classification.subtopik || '', 
            'S', 'topik_id', result.topikId
        );
        
        // 6. KISI-KISI (pakai judul)
        result.kisiId = await getOrCreate(
            'kisi_kisi', 'judul', 
            classification.kisi || '', 
            'I', 'sub_topik_id', result.subtopikId
        );
        
        // 7. KEMAMPUAN
        result.kemampuanId = await getOrCreate(
            'kemampuan_diuji', 'nama', 
            classification.kemampuan || '', 
            'KM', 'kisi_kisi_id', result.kisiId
        );
        
        // 8. SUB-KEMAMPUAN
        result.subKemampuanId = await getOrCreate(
            'sub_kemampuan', 'nama', 
            classification.subKemampuan || '', 
            'SK', 'kemampuan_id', result.kemampuanId
        );
        
        // ============================================================
        // 9. CARA PENYAJIAN (dengan fallback P01)
        // ============================================================
        result.penyajianId = await getMasterExact(
            'cara_penyajian',
            'kode_utama',
            classification.caraPenyajian,
            'id'
        );
        
        // ============================================================
        // 10. TIPE ISI (dengan fallback TI01)
        // ============================================================
        result.tipeIsiId = await getMasterExact(
            'tipe_isi_soal',
            'kode_utama',
            classification.tipeIsi,
            'id'
        );
        
        // ============================================================
        // 11. TAHAP (dengan fallback T1)
        // ============================================================
        result.tahapId = await getMasterExact(
            'tahap_pembelajaran',
            'kode_utama',
            classification.tahap,
            'id'
        );
        
        // ============================================================
        // 12. LAPISAN (ditentukan dari Tahap Pembelajaran)
        // ============================================================
        let lapisanLevel = classification.lapisan;
        
        // Jika tidak ada, hitung dari Tahap Pembelajaran
        if (!lapisanLevel) {
            lapisanLevel = classification.tahap ? getLapisanFromTahap(classification.tahap) : null;
            result.fallbackItems.push(`⚠️ Lapisan (kosong) → dihitung dari Tahap Pembelajaran = ${lapisanLevel}`);
        }
        
        try {
            const level = parseInt(lapisanLevel);
            if (!isNaN(level) && level >= 1 && level <= 7) {
                const row = await db.prepare(
                    `SELECT id FROM lapisan_pembelajaran WHERE level = ? LIMIT 1`
                ).bind(level).first();
                
                if (row) {
                    result.lapisanId = row.id;
                    result.foundItems.push(`✅ Lapisan: ${level} [${row.id}]`);
                } else {
                    result.missingItems.push(`❌ Lapisan: ${level} tidak ditemukan`);
                }
            } else {
                result.missingItems.push(`❌ Lapisan: ${lapisanLevel || '(kosong)'} tidak valid`);
            }
        } catch (e) {
            result.warnings.push(`⚠️ Error lapisan: ${e.message}`);
        }
        
        // ============================================================
        // 13. SUMBER BELAJAR (dengan fallback SB010)
        // ============================================================
        if (classification.sumber) {
            try {
                const row = await db.prepare(
                    `SELECT id FROM sumber_belajar WHERE LOWER(TRIM(nama)) LIKE LOWER(TRIM(?)) LIMIT 1`
                ).bind(`%${classification.sumber}%`).first();
                
                if (row) {
                    result.sumberId = row.id;
                    result.foundItems.push(`✅ Sumber: ${classification.sumber} [${row.id}]`);
                } else {
                    result.sumberId = null;
                    result.missingItems.push(`❌ Sumber: ${classification.sumber} tidak ditemukan`);
                }
            } catch (e) {
                result.sumberId = null;
                result.warnings.push(`⚠️ Error sumber: ${e.message}`);
            }
        }
        // Jika tidak ada sumber → biarkan NULL (opsional)
        
        // ============================================================
        // 14. VALIDASI KEABSAHAN dengan FALLBACK
        // ============================================================
        const validKeabsahan = ['resmi', 'adaptasi', 'mandiri'];
        const keabsahanLower = (classification.keabsahan || '').toLowerCase();
        
        if (!validKeabsahan.includes(keabsahanLower)) {
            result.missingItems.push(`❌ Keabsahan "${classification.keabsahan || ''}" tidak valid`);
            classification.keabsahan = null;
        } else {
            classification.keabsahan = keabsahanLower;
        }
        
        // ============================================================
        // 15. VALIDASI PROSES KOGNITIF + TINGKAT KESULITAN
        // ============================================================
        classification.prosesKognitif = getProsesKognitif(classification.prosesKognitif || classification.tipeHots, classification.levelHots);
        if (!classification.prosesKognitif) {
            result.missingItems.push(`❌ Proses kognitif harus LOTS, MOTS, atau HOTS`);
        }
        classification.tipeHots = classification.prosesKognitif;
        classification.levelHots = null;
        classification.tingkatKesulitan = getDefaultDifficulty(classification.tingkatKesulitan);
        
        // ============================================================
        // 16. UPDATE CLASSIFICATION DENGAN NILAI FINAL
        // ============================================================
        classification.kompleksitas = classification.tahap ? getKompleksitasFromTahap(classification.tahap) : null;
        classification.lapisan = classification.tahap ? getLapisanFromTahap(classification.tahap) : null;
        
        // Track statistics
        trackFallback(result);
        
    } catch (e) {
        console.error('Error getMasterIdsComplete:', e);
        result.warnings.push(`❌ Fatal error: ${e.message}`);
    }
    
    return result;
}

// ============================================================
// 🆕 VALIDATE CLASSIFICATION COMPLETE
// Lokasi: Setelah getMasterIdsComplete()
// ============================================================

function validateClassificationComplete(classification, masterIds) {
    const missingFields = [];
    const fallbackFields = [];
    const createdFields = [];
    
    // ============================================================
    // CEK HIERARKI (WAJIB)
    // ============================================================
    const isMataPelajaran = String(classification?.kategori || '').trim() === 'Mata Pelajaran';
    const hierarkiFields = [
        { key: 'kategori', id: masterIds.kategoriId, label: 'Kategori' },
        { key: 'bidang', id: masterIds.bidangId, label: 'Bidang Studi' },
        ...(isMataPelajaran
            ? [
                { key: 'jenjang', id: masterIds.jenjangId, label: 'Jenjang' },
                { key: 'kelas', id: masterIds.kelas, label: 'Kelas' },
                { key: 'mataPelajaran', id: masterIds.mataPelajaranId, label: 'Mata Pelajaran' }
              ]
            : [{ key: 'program', id: masterIds.programId, label: 'Program Studi' }]),
        { key: 'topik', id: masterIds.topikId, label: 'Topik' }
    ];
    
    for (const field of hierarkiFields) {
        if (!field.id) {
            missingFields.push(field.label);
        }
    }
    
    // ============================================================
    // CEK MASTER (OPSIONAL TAPI DIREKOMENDASIKAN)
    // ============================================================
    const masterFields = [
        { id: masterIds.penyajianId, label: 'Cara Penyajian' },
        { id: masterIds.tipeIsiId, label: 'Tipe Isi' },
        { id: masterIds.tahapId, label: 'Tahap Pembelajaran' },
        { id: masterIds.lapisanId, label: 'Lapisan Pembelajaran' }
    ];
    
    for (const field of masterFields) {
        if (!field.id) {
            missingFields.push(field.label);
        }
    }
    
    // ============================================================
    // CATAT FALLBACK YANG DIGUNAKAN
    // ============================================================
    if (masterIds.fallbackItems && masterIds.fallbackItems.length > 0) {
        fallbackFields.push(...masterIds.fallbackItems);
    }
    
    // ============================================================
    // CATAT YANG DIBUAT OTOMATIS
    // ============================================================
    if (masterIds.createdItems && masterIds.createdItems.length > 0) {
        createdFields.push(...masterIds.createdItems);
    }
    
    // ============================================================
    // HITUNG STATUS
    // ============================================================
    const isComplete = missingFields.length === 0;
    const hasFallback = fallbackFields.length > 0;
    const hasCreated = createdFields.length > 0;
    
    // Status rekomendasi
    let status;
    if (!isComplete) {
        status = 'DRAFT';
    } else if (hasFallback) {
        status = 'AKTIF_DENGAN_FALLBACK';
    } else {
        status = 'AKTIF';
    }
    
    return {
        isComplete,
        missingFields,
        fallbackFields,
        createdFields,
        hasFallback,
        hasCreated,
        status
    };
}

// ============================================================
// SAVE SOAL DENGAN AUTO-CLASSIFY DAN VALIDASI
// VERSI FINAL: Support jenjang_id & kelas
// ============================================================
async function saveSoalWithAutoClassify(db, soalData, options = {}) {
    const {
        soalText,
        pilihanA = '',
        pilihanB = '',
        pilihanC = '',
        pilihanD = '',
        pilihanE = '',
        jawabanBenar = '',
        pembahasan = '',
        alasanA = '', alasanB = '', alasanC = '', alasanD = '', alasanE = '',
        kisiKisiId = null,
        subKemampuanId = null,
        userId = null,
        sumberBelajarId = null,
        namaSumber = null,
        sumberLink = null,
        tahun = null,
        // 🆕 FIELD BARU: Jenjang & Kelas
        jenjangId = null,
        kelas = null,
        mataPelajaranId = null,
        mataKuliahId = null
    } = soalData;
    
    if (!soalText || !jawabanBenar || !['A','B','C','D','E'].includes(jawabanBenar.toUpperCase())) {
        return { success: false, error: 'Soal atau jawaban tidak valid' };
    }
    
    try {
        const questionContract = validateQuestionContract({ soalText, pilihanA, pilihanB, pilihanC, pilihanD, pilihanE, jawabanBenar, alasanA, alasanB, alasanC, alasanD, alasanE, jenisSoal: soalData.jenisSoal || soalData.jenis_soal || soalData.questionType, tingkatKesulitan: soalData.tingkatKesulitan || soalData.tingkat_kesulitan || 'SEDANG' });
        if (!questionContract.valid) return { success: false, error: questionContract.errors.join(' ') };

        // TAHAP 6–8: validasi penuh dan duplikasi harus diselesaikan SEBELUM INSERT.
        // Soal invalid/duplikat tidak boleh masuk ke question bank lalu baru ditandai.
        const normalizedSourceStatus = String(soalData.statusKeabsahan || soalData.status_keabsahan || '').trim().toUpperCase() || 'MANDIRI';
        const preValidation = validateQuestionFull({
            soal: soalText, pilihanA, pilihanB, pilihanC, pilihanD, pilihanE, jawabanBenar,
            alasanA, alasanB, alasanC, alasanD, alasanE,
            jenisSoal: questionContract.jenis_soal, tingkatKesulitan: questionContract.tingkat_kesulitan,
            statusKeabsahan: normalizedSourceStatus, sumberBelajarId, namaSumber, sumberLink, tahun,
            multipleCorrect: soalData.multipleCorrect || soalData.multiple_correct
        });
        if (!preValidation.valid) return { success: false, error: `Validasi soal gagal: ${preValidation.errors.join(' ')}` };
        const duplicates = await findDuplicateQuestions(db, { soal: soalText, pilihanA, pilihanB, pilihanC, pilihanD, pilihanE, jawabanBenar });
        if (duplicates.length) return { success: false, error: `Soal terindikasi duplikat: ${duplicateSummary(duplicates)}.`, duplicates };

        const pilihanJawaban = `A. ${pilihanA}\nB. ${pilihanB}\nC. ${pilihanC}\nD. ${pilihanD}\nE. ${pilihanE}`;
        const classification = await autoClassifyComplete(soalText, pilihanJawaban, db);
        const classificationValidation = validateLearningClassification(classification);
        if (!classificationValidation.valid) {
            return { success: false, error: classificationValidation.errors.join(' ') };
        }
        const masterIds = classification.masterIds || {};
        const requiredMasterIds = [
            ['caraPenyajian','Cara Penyajian'],['tipeIsi','Tipe Isi'],['tahap','Tahap Pembelajaran'],['lapisan','Lapisan Pembelajaran']
        ];
        const missingRequiredMaster = requiredMasterIds.filter(([k])=>!masterIds[`${k}Id`]).map(([,label])=>label);
        if (missingRequiredMaster.length) return { success:false, error:`Master data wajib tidak lengkap: ${missingRequiredMaster.join(', ')}.` };
        
        // ============================================================
        // VALIDASI HIERARKI — tanpa fallback parent/master diam-diam
        // ============================================================
        
        // Fallback 1: KATEGORI
        let finalKategoriId = masterIds.kategoriId;
        if (!finalKategoriId) {
            return { success: false, error: 'Kategori tidak dapat ditentukan secara valid; proses dibatalkan agar soal tidak masuk ke kategori default yang salah.' };
        }
        
        // Fallback 2: BIDANG STUDI
        let finalBidangId = masterIds.bidangId;
        if (!finalBidangId && finalKategoriId) {
            return { success: false, error: 'Bidang Studi tidak dapat ditentukan secara valid; proses dibatalkan.' };
        }
        
        // Fallback 3/4: PROGRAM/JENJANG-SPECIFIC BRANCH
        // Mata Pelajaran tidak memakai Program Studi pada hierarchy utama.
        const kategoriRow = finalKategoriId
            ? await db.prepare(`SELECT nama FROM kategori WHERE id = ? LIMIT 1`).bind(finalKategoriId).first()
            : null;
        const kategoriNama = String(kategoriRow?.nama || classification.kategori || '').trim();

        let finalProgramId = kategoriNama === 'Mata Pelajaran' ? null : (masterIds.programId || null);
        if (kategoriNama !== 'Mata Pelajaran' && !finalProgramId && finalBidangId) {
            return { success: false, error: 'Program Studi tidak dapat ditentukan secara valid; proses dibatalkan.' };
        }

        // Jenjang, Kelas, dan entitas pendidikan harus diselesaikan sebelum Topik.
        let finalJenjangId = jenjangId || masterIds.jenjangId || null;
        let finalKelas = kelas || masterIds.kelas || null;
        let finalMataPelajaranId = mataPelajaranId || masterIds.mataPelajaranId || null;
        let finalMataKuliahId = mataKuliahId || masterIds.mataKuliahId || null;

        if (finalJenjangId) {
            const checkJenjang = await db.prepare(`SELECT id, jenis FROM jenjang WHERE id = ? LIMIT 1`).bind(finalJenjangId).first();
            if (!checkJenjang) return { success:false, error:`Jenjang ${finalJenjangId} tidak ditemukan.` };
            else if (kategoriNama === 'Mata Pelajaran' && !ARCHITECTURE_RULES.schoolLevels.includes(String(checkJenjang.jenis || '').toUpperCase())) return { success:false, error:`Jenjang ${finalJenjangId} tidak sesuai untuk Mata Pelajaran.` };
            else if (kategoriNama === 'Mata Kuliah' && !ARCHITECTURE_RULES.higherEducationLevels.includes(String(checkJenjang.jenis || '').toUpperCase())) return { success:false, error:`Jenjang ${finalJenjangId} tidak sesuai untuk Mata Kuliah.` };
        }
        if (finalKelas) {
            const checkKelas = await db.prepare(`SELECT id, jenjang_id FROM kelas WHERE id = ? LIMIT 1`).bind(finalKelas).first();
            if (!checkKelas) return { success:false, error:`Kelas ${finalKelas} tidak ditemukan.` };
            if (finalJenjangId && checkKelas.jenjang_id !== finalJenjangId) return { success:false, error:`Kelas ${finalKelas} tidak sesuai dengan Jenjang ${finalJenjangId}.` };
        }
        if (finalMataPelajaranId) {
            const checkMP = await db.prepare(`SELECT id, bidang_studi_id, kelas_id FROM mata_pelajaran WHERE id = ? LIMIT 1`).bind(finalMataPelajaranId).first();
            if (!checkMP) return { success:false, error:`Mata Pelajaran ${finalMataPelajaranId} tidak ditemukan.` };
            if (finalBidangId && checkMP.bidang_studi_id !== finalBidangId) return { success:false, error:`Mata Pelajaran ${finalMataPelajaranId} tidak sesuai dengan Bidang Studi.` };
            if (finalKelas && checkMP.kelas_id !== finalKelas) return { success:false, error:`Mata Pelajaran ${finalMataPelajaranId} tidak sesuai dengan Kelas.` };
        }
        if (finalMataKuliahId) {
            const checkMK = await db.prepare(`SELECT id, program_studi_id, jenjang_id FROM mata_kuliah WHERE id = ? LIMIT 1`).bind(finalMataKuliahId).first();
            if (!checkMK) return { success:false, error:`Mata Kuliah ${finalMataKuliahId} tidak ditemukan.` };
            if (finalProgramId && checkMK.program_studi_id !== finalProgramId) return { success:false, error:`Mata Kuliah ${finalMataKuliahId} tidak sesuai dengan Program Studi.` };
            if (finalJenjangId && checkMK.jenjang_id !== finalJenjangId) return { success:false, error:`Mata Kuliah ${finalMataKuliahId} tidak sesuai dengan Jenjang.` };
        }

        const autoCreate = options.autoCreate !== false;
        let finalTopikId = masterIds.topikId;
        if (finalTopikId) {
            const topikCheck = await db.prepare(`SELECT id, program_studi_id, mata_pelajaran_id, mata_kuliah_id FROM topik WHERE id = ? LIMIT 1`).bind(finalTopikId).first();
            const validForMP = kategoriNama === 'Mata Pelajaran' && topikCheck?.mata_pelajaran_id === finalMataPelajaranId;
            const validForMK = kategoriNama === 'Mata Kuliah' && topikCheck?.mata_kuliah_id === finalMataKuliahId;
            const validGeneral = !['Mata Pelajaran', 'Mata Kuliah'].includes(kategoriNama) && topikCheck?.program_studi_id === finalProgramId && !topikCheck?.mata_pelajaran_id && !topikCheck?.mata_kuliah_id;
            if (!validForMP && !validForMK && !validGeneral) finalTopikId = null;
        }
        if (!finalTopikId && autoCreate) {
            const topicName = String(classification.topik || '').trim();
            if (!topicName) return { success:false, error:'Topik tidak dapat ditentukan secara valid; proses dibatalkan.' };
            const topic = await getOrCreateTopicStrict(db, {
                name: topicName,
                programId: finalProgramId,
                mataPelajaranId: kategoriNama === 'Mata Pelajaran' ? finalMataPelajaranId : null,
                mataKuliahId: kategoriNama === 'Mata Kuliah' ? finalMataKuliahId : null,
                autoCreate: true
            });
            if (topic.error) return { success:false, error:topic.error };
            finalTopikId = topic.id;
        }

        // ============================================================
        // DEBUG LOG
        // ============================================================
        console.log('🔍 [SAVE SOAL] Final IDs:');
        console.log('   kategori_id:', finalKategoriId);
        console.log('   bidang_studi_id:', finalBidangId);
        console.log('   program_studi_id:', finalProgramId);
        console.log('   topik_id:', finalTopikId);
        console.log('   sub_topik_id:', masterIds.subtopikId);
        console.log('   jenjang_id:', finalJenjangId);
        console.log('   kelas:', finalKelas);
        console.log('   mata_kuliah_id:', finalMataKuliahId);
        console.log('   kisi_kisi_id:', kisiKisiId || masterIds.kisiId);
        console.log('   nama_sumber:', namaSumber);
        console.log('   user_id:', userId);

        const hierarchyValidation = await validateHierarchyContext(db, {
            kategoriId: finalKategoriId, kategoriNama, bidangId: finalBidangId, programId: finalProgramId,
            jenjang: finalJenjangId, kelas: finalKelas, mataPelajaranId: finalMataPelajaranId, mataKuliahId: finalMataKuliahId
        });
        if (!hierarchyValidation.valid) {
            return { success: false, error: hierarchyValidation.errors.join(' ') };
        }
        
        const id = await generateId(db, 'Q', 'soal');
        const tanggalInput = new Date().toISOString();
        
        // ============================================================
        // INSERT SOAL — 40 KOLOM, 40 PARAMETER (termasuk Mata Pelajaran + Jenjang + Kelas + Mata Kuliah)
        // ============================================================
        await db.prepare(`
            INSERT INTO soal (
                id, soal, pilihan_a, pilihan_b, pilihan_c, pilihan_d, pilihan_e, jawaban_benar, pembahasan,
                alasan_a, alasan_b, alasan_c, alasan_d, alasan_e,
                kategori_id, bidang_studi_id, program_studi_id, mata_pelajaran_id, mata_kuliah_id, topik_id, sub_topik_id,
                jenjang_id, kelas,
                kisi_kisi_id, kemampuan_id, sub_kemampuan_id,
                cara_penyajian_id, tipe_isi_id, kompleksitas, tahap_pembelajaran_id,
                tipe_hots, level_hots, tingkat_kesulitan, lapisan_pembelajaran_id,
                sumber_belajar_id, nama_sumber, sumber_link, tahun, status_keabsahan,
                status, tipe_soal, jenis_soal, tanggal_input,
                created_by, updated_by
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
            id,
            soalText,
            pilihanA || '',
            pilihanB || '',
            pilihanC || '',
            pilihanD || '',
            pilihanE || '',
            jawabanBenar.toUpperCase(),
            pembahasan || null,
            alasanA || null, alasanB || null, alasanC || null, alasanD || null, alasanE || null,
            finalKategoriId,
            finalBidangId,
            finalProgramId,
            finalMataPelajaranId,
            finalMataKuliahId,
            finalTopikId,
            masterIds.subtopikId || null,
            finalJenjangId,
            finalKelas,
            kisiKisiId || masterIds.kisiId || null,
            masterIds.kemampuanId || null,
            subKemampuanId || masterIds.subKemampuanId || null,
            masterIds.penyajianId || null,
            masterIds.tipeIsiId || null,
            classification.kompleksitas || 'menengah',
            masterIds.tahapId || null,
            classification.prosesKognitif || classification.tipeHots || 'LOTS',
            null,
            getDefaultDifficulty(classification.tingkatKesulitan),
            masterIds.lapisanId || null,
            sumberBelajarId || masterIds.sumberId || null,
            namaSumber || null,
            sumberLink || null,
            tahun || null,
            normalizedSourceStatus,
            'AKTIF',
            'PG',
            questionContract.jenis_soal,
            tanggalInput,
            userId || null,
            userId || null
        ).run();
        
        // TAHAP 6–7: audit validation dan provenance disimpan bersama soal.
        const fullValidation = preValidation;
        const validationResult = await recordQuestionValidation(db, id, fullValidation, userId);
        if (!validationResult.success) throw new Error(`Gagal mencatat validasi soal: ${validationResult.error}`);
        const provenance = validateQuestionProvenance({
            statusKeabsahan: normalizedSourceStatus,
            sumberBelajarId: sumberBelajarId || masterIds.sumberId || null,
            namaSumber, sumberLink: sumberLink || null, tahun
        });
        if (!provenance.valid) throw new Error(`Provenance soal tidak valid: ${provenance.error}`);
        if (provenance.status !== 'MANDIRI' || provenance.source_id || provenance.source_name || provenance.source_link) {
            const provenanceResult = await saveQuestionProvenance(db, id, provenance, userId);
            if (!provenanceResult.success) throw new Error(`Gagal mencatat provenance soal: ${provenanceResult.error}`);
        }
        const revisionResult = await createQuestionRevision(db, id, 'CREATE', 'Versi awal soal', userId);
        if (!revisionResult.success) throw new Error(`Gagal mencatat revisi awal: ${revisionResult.error}`);

        // 🆕 TRACKING COUNTER: Auto-increment total_soal
        if (userId) {
            try {
                await incrementUserStats(db, userId, 'total_soal');
            } catch (e) {
                console.warn('Gagal increment total_soal:', e.message);
            }
        }
        
        return {
            success: true,
            id: id,
            classification: classification,
            masterIds: {
                ...masterIds,
                kategoriId: finalKategoriId,
                bidangId: finalBidangId,
                programId: finalProgramId,
                topikId: finalTopikId,
                jenjangId: finalJenjangId,      // 🆕
                kelas: finalKelas               // 🆕
            }
        };
        
    } catch (e) {
        console.error('Save soal error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 8. RE-CLASSIFY SOAL - UPDATE KLASIFIKASI
// ============================================================

// ============================================================
// 📍 TEMPAT 4: REPLACE FUNGSI reclassifySoal()
// Cari: async function reclassifySoal(db, soalId) {
// Ganti seluruh fungsi dengan yang di bawah ini
// ============================================================

async function reclassifySoal(db, soalId, userId = null) {
    try {
        const soal = await db.prepare(`
            SELECT soal, pilihan_a, pilihan_b, pilihan_c, pilihan_d, pilihan_e, jawaban_benar,
                   cara_penyajian_id, tipe_isi_id, tahap_pembelajaran_id, tipe_hots,
                   lapisan_pembelajaran_id, kompleksitas, tingkat_kesulitan
            FROM soal WHERE id = ?
        `).bind(soalId).first();
        if (!soal) return { success: false, error: 'Soal tidak ditemukan' };

        const pilihanJawaban = `A. ${soal.pilihan_a || ''}\nB. ${soal.pilihan_b || ''}\nC. ${soal.pilihan_c || ''}\nD. ${soal.pilihan_d || ''}\nE. ${soal.pilihan_e || ''}`;
        const classification = await autoClassifyComplete(soal.soal, pilihanJawaban, db);
        const masterIds = classification.masterIds || {};
        const kompleksitas = getKompleksitasFromTahap(masterIds.tahapId);
        const tingkatKesulitan = getDefaultDifficulty(classification.tingkatKesulitan);
        // RECLASSIFY hanya mengubah dimensi klasifikasi; provenance dan hierarchy tidak ditimpa.
        const patch = {
            // Jangan menghapus klasifikasi lama jika classifier tidak mengembalikan field tersebut.
            cara_penyajian_id: masterIds.penyajianId ?? soal.cara_penyajian_id ?? null,
            tipe_isi_id: masterIds.tipeIsiId ?? soal.tipe_isi_id ?? null,
            tahap_pembelajaran_id: masterIds.tahapId ?? soal.tahap_pembelajaran_id ?? null,
            level_hots: null,
            tipe_hots: classification.prosesKognitif ?? classification.tipeHots ?? soal.tipe_hots ?? 'LOTS',
            lapisan_pembelajaran_id: masterIds.lapisanId ?? soal.lapisan_pembelajaran_id ?? null,
            kompleksitas: masterIds.tahapId ? kompleksitas : (soal.kompleksitas ?? kompleksitas),
            tingkat_kesulitan: classification.tingkatKesulitan != null ? tingkatKesulitan : (soal.tingkat_kesulitan ?? tingkatKesulitan),
            updated_by: userId
        };

        const updateResult = await updateQuestionBankRecord(
            db, soalId, patch, userId, 'RECLASSIFY: klasifikasi soal diperbarui'
        );
        if (!updateResult.success) {
            return { success: false, error: updateResult.error || 'Gagal memperbarui klasifikasi', classification, masterIds };
        }

        return {
            success: true,
            noOp: !!updateResult.noOp,
            changedFields: updateResult.changedFields || [],
            version: updateResult.version || null,
            classification, masterIds, kompleksitas, tingkatKesulitan
        };
    } catch (e) {
        console.error('Reclassify error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 🔴 BAGIAN 1: AUTO-MAPPING FUNCTIONS - TAMBAHKAN DI SINI
// LETAKKAN: SETELAH KONFIGURASI, SEBELUM HELPER FUNCTIONS
// ============================================================

/**
 * PROSES KOGNITIF — canonical: LOTS / MOTS / HOTS.
 * HOTS bukan tingkat kesulitan; ia merupakan dimensi kognitif terpisah.
 * levelHots hanya dipahami sebagai data legacy untuk kompatibilitas.
 */
function getProsesKognitif(value, legacyLevel=null) {
    return normalizeCognitiveProcess(value, legacyLevel);
}
function getTipeHots(value, legacyLevel=null) {
    return getProsesKognitif(value, legacyLevel);
}
function getStoredCognitive(record={}) {
    return getProsesKognitif(record.proses_kognitif || record.prosesKognitif || record.tipe_hots || record.tipeHots, record.level_hots ?? record.levelHots) || 'LOTS';
}

/**
 * 2. KOMPLEKSITAS (dari Tahap Pembelajaran)
 * T1-T3 → sederhana, T4-T6 → menengah, T7-T9 → kompleks
 */
function getKompleksitasFromTahap(tahapId) {
    const mapping = {
        'T1': 'sederhana',
        'T2': 'sederhana',
        'T3': 'sederhana',
        'T4': 'menengah',
        'T5': 'menengah',
        'T6': 'menengah',
        'T7': 'kompleks',
        'T8': 'kompleks',
        'T9': 'kompleks'
    };
    return mapping[tahapId] || 'menengah';
}

/**
 * 5. LAPISAN DARI TAHAP
 */
function getLapisanFromTahap(tahapId) {
    const mapping = {
        'T1': 1, // Kenali
        'T2': 2, // Pahami
        'T3': 3, // Kuasai Cara Kerja
        'T4': 5, // Terapkan
        'T5': 4, // Bedakan
        'T6': 6, // Analisis
        'T7': 6, // Analisis
        'T8': 7, // Kuasai Menyeluruh
        'T9': 7  // Kuasai Menyeluruh
    };
    return mapping[tahapId] || 1;
}

/**
 * 6. HYBRID LAPISAN - Menggabungkan dari Proses Kognitif dan Tahap
 */
function getHybridLapisan(levelHots, tahapId) {
    // LEGACY SIGNATURE dipertahankan agar caller lama tidak rusak.
    // Lapisan pembelajaran ditentukan oleh tahap, bukan oleh HOTS/kesulitan.
    return getLapisanFromTahap(tahapId);
}

// ============================================================
// 🆕 MATH RENDERER - PATCH 2
// Lokasi: Setelah getHybridLapisan()
// ============================================================

// ============================================================
// 1. KONVERSI KE SUPERSCRIPT
// ============================================================
function toSuperscript(text) {
    if (!text) return '';
    return String(text).split('').map(char => 
        UNICODE_MATH.superscript[char] || char
    ).join('');
}

// ============================================================
// 2. KONVERSI KE SUBSCRIPT
// ============================================================
function toSubscript(text) {
    if (!text) return '';
    return String(text).split('').map(char => 
        UNICODE_MATH.subscript[char] || char
    ).join('');
}

// ============================================================
// 3. KONVERSI LATEX SEDERHANA KE UNICODE
// ============================================================
function latexToUnicode(latex) {
    if (!latex) return '';
    
    let result = String(latex);
    
    // Hapus $...$ atau \(...\) atau \[...\]
    result = result.replace(/\$([^$]+)\$/g, '$1');
    result = result.replace(/\\\(([^)]+)\\\)/g, '$1');
    result = result.replace(/\\\[([^\]]+)\\\]/g, '$1');
    
    // Konversi \frac{a}{b} → (a)/(b)
    result = result.replace(/\\frac\{([^}]+)\}\{([^}]+)\}/g, '($1)/($2)');
    
    // Konversi \sqrt{x} → √(x)
    result = result.replace(/\\sqrt\{([^}]+)\}/g, '√($1)');
    result = result.replace(/\\sqrt\[(\d+)\]\{([^}]+)\}/g, '$1√($2)');
    result = result.replace(/\\sqrt\s+(\w)/g, '√$1');
    
    // Konversi ^{...} → superscript
    result = result.replace(/\^\{([^}]+)\}/g, (_, exp) => toSuperscript(exp));
    // Konversi ^x → superscript
    result = result.replace(/\^(\w)/g, (_, exp) => toSuperscript(exp));
    
    // Konversi _{...} → subscript
    result = result.replace(/_\{([^}]+)\}/g, (_, sub) => toSubscript(sub));
    // Konversi _x → subscript
    result = result.replace(/_(\w)/g, (_, sub) => toSubscript(sub));
    
    // Konversi simbol LaTeX ke unicode
    const symbolMap = {
        '\\times': '×', '\\div': '÷', '\\pm': '±',
        '\\neq': '≠', '\\ne': '≠', '\\leq': '≤', '\\le': '≤',
        '\\geq': '≥', '\\ge': '≥', '\\approx': '≈', '\\equiv': '≡',
        '\\rightarrow': '→', '\\to': '→', '\\leftrightarrow': '↔',
        '\\Rightarrow': '⇒', '\\Leftarrow': '⇐', '\\Leftrightarrow': '⇔',
        '\\in': '∈', '\\notin': '∉', '\\subset': '⊂', '\\supset': '⊃',
        '\\cup': '∪', '\\cap': '∩', '\\emptyset': '∅',
        '\\forall': '∀', '\\exists': '∃', '\\nexists': '∄',
        '\\infty': '∞', '\\partial': '∂', '\\nabla': '∇',
        '\\sum': '∑', '\\prod': '∏', '\\int': '∫', '\\oint': '∮',
        '\\pi': 'π', '\\alpha': 'α', '\\beta': 'β', '\\gamma': 'γ',
        '\\delta': 'δ', '\\epsilon': 'ε', '\\zeta': 'ζ', '\\eta': 'η',
        '\\theta': 'θ', '\\iota': 'ι', '\\kappa': 'κ', '\\lambda': 'λ',
        '\\mu': 'μ', '\\nu': 'ν', '\\xi': 'ξ', '\\rho': 'ρ',
        '\\sigma': 'σ', '\\tau': 'τ', '\\upsilon': 'υ', '\\phi': 'φ',
        '\\chi': 'χ', '\\psi': 'ψ', '\\omega': 'ω',
        '\\Delta': 'Δ', '\\Sigma': 'Σ', '\\Omega': 'Ω',
        '\\angle': '∠', '\\degree': '°', '\\perp': '⊥', '\\parallel': '∥',
        '\\triangle': '△', '\\square': '□', '\\circ': '∘',
        '\\cdot': '·', '\\ast': '∗', '\\star': '⋆'
    };
    
    for (const [latex, unicode] of Object.entries(symbolMap)) {
        const escaped = latex.replace(/\\/g, '\\\\');
        result = result.replace(new RegExp(escaped, 'g'), unicode);
    }
    
    // Bersihkan backslash yang tersisa
    result = result.replace(/\\/g, '');
    
    // Bersihkan spasi berlebih
    result = result.replace(/\s+/g, ' ').trim();
    
    return result;
}

// ============================================================
// 4. DETEKSI RUMUS SEDERHANA VS KOMPLEKS
// ============================================================
function isSimpleFormula(latex) {
    if (!latex) return true;
    
    const text = String(latex);
    
    // Rumus dianggap KOMPLEKS jika mengandung pola berikut:
    const complexPatterns = [
        /\\frac\{[^}]+\}\{[^}]+\}/,       // \frac{a}{b}
        /\\int/,                           // \int
        /\\iint/,                          // \iint
        /\\iiint/,                         // \iiint
        /\\oint/,                          // \oint
        /\\sum/,                           // \sum
        /\\prod/,                          // \prod
        /\\lim/,                           // \lim
        /\\begin\{/,                       // \begin{matrix}
        /\\begin\{pmatrix\}/,              // \begin{pmatrix}
        /\\begin\{bmatrix\}/,              // \begin{bmatrix}
        /\\begin\{vmatrix\}/,              // \begin{vmatrix}
        /\\begin\{align\}/,                // \begin{align}
        /\\sqrt\[/,                        // \sqrt[n]{x}
        /\\over/,                          // \over
        /\^\{[^}]*\\/,                     // Nested ^{}
        /_\{[^}]*\\/,                      // Nested _{}
        /\\overline\{/,                    // \overline{x}
        /\\underline\{/,                   // \underline{x}
        /\\hat\{/,                         // \hat{x}
        /\\vec\{/,                         // \vec{x}
        /\\binom\{/,                       // \binom{n}{k}
        /\\displaystyle/                   // \displaystyle
    ];
    
    for (const pattern of complexPatterns) {
        if (pattern.test(text)) return false;
    }
    
    return true;
}

// ============================================================
// 5. SEND LATEX AS IMAGE (via CodeCogs)
// ============================================================
async function sendLatexAsImage(chatId, latex, caption = '') {
    try {
        if (!latex || !String(latex).trim()) return false;
        
        // Bersihkan LaTeX dari $ dan \
        let cleanLatex = String(latex).trim();
        cleanLatex = cleanLatex.replace(/^\$+|\$+$/g, '');
        cleanLatex = cleanLatex.replace(/^\\\(|\\\)$/g, '');
        
        // Encode untuk URL
        const encodedLatex = encodeURIComponent(cleanLatex);
        
        // CodeCogs URL (dengan background putih, DPI tinggi)
        const imageUrl = `https://latex.codecogs.com/png.image?\\dpi{300}\\bg_white%20${encodedLatex}`;
        
        // Kirim via sendPhoto
        const payload = {
            chat_id: chatId,
            photo: imageUrl,
            parse_mode: 'Markdown'
        };
        
        if (caption) {
            payload.caption = caption.substring(0, 1024); // Limit caption 1024
        }
        
        const response = await fetch(`https://api.telegram.org/bot${getTelegramToken(env)}/sendPhoto`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        
        const result = await response.json();
        
        if (!result.ok) {
            console.warn('⚠️ Send LaTeX image gagal:', result.description);
            return false;
        }
        
        return true;
    } catch (e) {
        console.error('❌ sendLatexAsImage error:', e);
        return false;
    }
}

// ============================================================
// 6. PARSE MATH TEXT - Ekstrak $...$ dan \(...\)
// ============================================================
function parseMathText(text) {
    if (!text) return [];
    
    const parts = [];
    // Regex untuk $...$ atau \(...\) atau \[...\]
    const mathRegex = /\$([^$\n]+)\$|\\\(([^)\n]+)\\\)|\\\[([^\]\n]+)\\\]/g;
    
    let lastIndex = 0;
    let match;
    
    while ((match = mathRegex.exec(text)) !== null) {
        // Text sebelum rumus
        if (match.index > lastIndex) {
            parts.push({
                type: 'text',
                content: text.substring(lastIndex, match.index)
            });
        }
        
        // Rumus
        const latex = match[1] || match[2] || match[3];
        parts.push({
            type: 'math',
            content: latex,
            isSimple: isSimpleFormula(latex),
            unicode: latexToUnicode(latex)
        });
        
        lastIndex = match.index + match[0].length;
    }
    
    // Sisa text setelah rumus terakhir
    if (lastIndex < text.length) {
        parts.push({
            type: 'text',
            content: text.substring(lastIndex)
        });
    }
    
    // Jika tidak ada rumus, return text saja
    if (parts.length === 0) {
        parts.push({ type: 'text', content: text });
    }
    
    return parts;
}

// ============================================================
// 7. RENDER MATH (HYBRID - Fungsi Utama)
// ============================================================
async function renderMath(chatId, text, options = {}) {
    if (!text) return false;
    
    const {
        parseMode = null,       // null = plain text
        forceUnicode = false,   // Paksa unicode (tidak render gambar)
        maxLength = 4000        // Max panjang per pesan
    } = options;
    
    try {
        // Cek apakah ada rumus
        const hasMath = /\$[^$]+\$|\\\([^)]+\\\)|\\\[[^\]]+\\\]/.test(text);
        
        // Jika tidak ada rumus, kirim langsung
        if (!hasMath) {
            return await sendMessage(chatId, text, parseMode);
        }
        
        // Parse text
        const parts = parseMathText(text);
        
        // Gabung text dan konversi math
        let buffer = '';
        const messages = [];
        
        for (const part of parts) {
            if (part.type === 'text') {
                buffer += part.content;
            } else if (part.type === 'math') {
                if (part.isSimple || forceUnicode) {
                    // Simple → Unicode inline
                    buffer += part.unicode || part.content;
                } else {
                    // Complex → Gambar
                    // Flush buffer dulu
                    if (buffer.trim()) {
                        messages.push({ type: 'text', content: buffer });
                        buffer = '';
                    }
                    messages.push({ 
                        type: 'image', 
                        content: part.content,
                        unicode: part.unicode
                    });
                }
            }
        }
        
        // Flush sisa buffer
        if (buffer.trim()) {
            messages.push({ type: 'text', content: buffer });
        }
        
        // Kirim semua messages
        for (const msg of messages) {
            if (msg.type === 'text') {
                // Potong jika terlalu panjang
                if (msg.content.length > maxLength) {
                    const chunks = msg.content.match(new RegExp(`.{1,${maxLength}}`, 'gs')) || [];
                    for (const chunk of chunks) {
                        await sendMessage(chatId, chunk, parseMode);
                    }
                } else {
                    await sendMessage(chatId, msg.content, parseMode);
                }
            } else if (msg.type === 'image') {
                // Kirim sebagai gambar
                const success = await sendLatexAsImage(chatId, msg.content);
                // Fallback ke unicode jika gambar gagal
                if (!success && msg.unicode) {
                    await sendMessage(chatId, msg.unicode, parseMode);
                }
            }
        }
        
        return true;
    } catch (e) {
        console.error('❌ renderMath error:', e);
        // Fallback: kirim text asli
        try {
            await sendMessage(chatId, text, parseMode);
        } catch (e2) {
            console.error('❌ renderMath fallback error:', e2);
        }
        return false;
    }
}

// ============================================================
// 8. FORMAT MATH UNTUK DISPLAY (tanpa kirim)
// ============================================================
function formatMathForDisplay(text, forceUnicode = false) {
    if (!text) return '';
    
    const hasMath = /\$[^$]+\$|\\\([^)]+\\\)|\\\[[^\]]+\\\]/.test(text);
    if (!hasMath) return text;
    
    const parts = parseMathText(text);
    let result = '';
    
    for (const part of parts) {
        if (part.type === 'text') {
            result += part.content;
        } else if (part.type === 'math') {
            if (part.isSimple || forceUnicode) {
                result += part.unicode || part.content;
            } else {
                // Untuk context yang tidak support gambar, pakai unicode
                result += part.unicode || `[${part.content}]`;
            }
        }
    }
    
    return result;
}

// ============================================================
// 9. SIMPAN RUMUS KE DATABASE
// ============================================================
async function saveFormulaToDb(db, materiId, tahapKode, latex) {
    try {
        if (!latex || !materiId) return null;
        
        const cleanLatex = String(latex).trim().replace(/^\$+|\$+$/g, '');
        const unicode = latexToUnicode(cleanLatex);
        const imageUrl = `https://latex.codecogs.com/png.image?\\dpi{300}\\bg_white%20${encodeURIComponent(cleanLatex)}`;
        
        const id = await generateId(db, 'R', 'materi_rumus');
        
        await db.prepare(`
            INSERT INTO materi_rumus (id, materi_id, tahap_kode, latex, unicode, image_url)
            VALUES (?, ?, ?, ?, ?, ?)
        `).bind(id, materiId, tahapKode, cleanLatex, unicode, imageUrl).run();
        
        return id;
    } catch (e) {
        console.error('❌ saveFormulaToDb error:', e);
        return null;
    }
}

