// 🆕 PATCH 7.5: FUNGSI MEDIA MATERI
// ============================================================

// ============================================================
// 1. SIMPAN MEDIA KE MATERI
// ============================================================
// ============================================================
// 1. SIMPAN MEDIA KE MATERI (UPDATE PATCH 7.6)
// ============================================================
async function saveMateriMedia(db, materiId, mediaData) {
    try {
        const {
            tahapKode = null,
            mediaType,
            fileId = null,
            mediaPath = null,
            caption = null,
            anchorMarker = null,
            placement = 'auto'
        } = mediaData;
        
        if (!mediaType || (!fileId && !mediaPath)) {
            return { success: false, error: 'mediaType + (fileId | mediaPath) wajib' };
        }
        
        if (!['image', 'video', 'audio'].includes(mediaType)) {
            return { success: false, error: 'mediaType harus image/video/audio' };
        }
        
        // Ambil position terakhir
        const last = await db.prepare(`
            SELECT MAX(position) as max_pos FROM materi_media 
            WHERE materi_id = ? AND (tahap_kode = ? OR (tahap_kode IS NULL AND ? IS NULL))
        `).bind(materiId, tahapKode, tahapKode).first();
        
        const position = (last?.max_pos || 0) + 1;
        
        const id = await generateId(db, 'MM', 'materi_media');
        
        await db.prepare(`
            INSERT INTO materi_media 
            (id, materi_id, tahap_kode, media_type, file_id, media_path, 
             caption, position, anchor_marker, placement, priority, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
            id, materiId, tahapKode, mediaType, fileId, mediaPath,
            caption, position, anchorMarker, placement, 0,
            new Date().toISOString()
        ).run();
        
        return { success: true, id, position };
    } catch (e) {
        console.error('saveMateriMedia error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 2. AMBIL MEDIA MATERI
// ============================================================
async function getMateriMedia(db, materiId, tahapKode = null) {
    try {
        let query = `SELECT * FROM materi_media WHERE materi_id = ?`;
        let bind = [materiId];
        
        if (tahapKode !== null) {
            query += ` AND tahap_kode = ?`;
            bind.push(tahapKode);
        }
        
        query += ` ORDER BY position ASC`;
        
        const result = await db.prepare(query).bind(...bind).all();
        return result.results || [];
    } catch (e) {
        console.error('getMateriMedia error:', e);
        return [];
    }
}

// ============================================================
