async function deleteMateriMedia(db, mediaId) {
    try {
        await db.prepare(`DELETE FROM materi_media WHERE id = ?`).bind(mediaId).run();
        return { success: true };
    } catch (e) {
        return { success: false, error: e.message };
    }
}

// ============================================================
// 🆕 PATCH 7.6: PROSES MARKER & ANCHOR MEDIA DI KONTEN
// ============================================================
// Alur:
// 1. Ganti {{MEDIA:MM001}} → placeholder internal
// 2. Ganti anchor frasa → placeholder internal
// 3. Split konten berdasarkan placeholder
// 4. Return array { type: 'text' | 'media', content/media }
// ============================================================

async function processMediaMarkers(db, materiId, konten) {
    try {
        // ============================================================
        // 1. AMBIL SEMUA MEDIA
        // ============================================================
        const allMedia = await getMateriMedia(db, materiId);
        
        if (!allMedia || allMedia.length === 0) {
            return [{ type: 'text', content: konten }];
        }
        
        // ============================================================
        // 2. BUILD MAP & LIST
        // ============================================================
        const markerMap = {};       // { "MM001": media }
        const anchorList = [];      // [ { text, media } ]
        
        for (const m of allMedia) {
            // Marker eksplisit: anchor_marker = "MM001" dan placement = 'marker'
            if (m.placement === 'marker' && m.anchor_marker) {
                markerMap[m.anchor_marker.toUpperCase()] = m;
            }
            // Anchor frasa: anchor_marker = "frasa target" dan placement = 'anchor'
            else if (m.placement === 'anchor' && m.anchor_marker) {
                anchorList.push({ 
                    text: m.anchor_marker, 
                    media: m 
                });
            }
        }
        
        // ============================================================
        // 3. GANTI MARKER {{MEDIA:MM001}} → placeholder internal
        // ============================================================
        let processedKonten = konten;
        
        // Regex marker: {{MEDIA:MM001}} atau {{MEDIA:xxx}}
        const markerRegex = /\{\{MEDIA:([A-Z0-9]+)\}\}/gi;
        
        processedKonten = processedKonten.replace(markerRegex, (match, mediaId) => {
            const key = mediaId.toUpperCase();
            const media = markerMap[key] || allMedia.find(m => m.id === key);
            
            if (media) {
                return `\n<!--MEDIA_INSERT:${media.id}-->\n`;
            }
            
            // Media tidak ditemukan → biarkan sebagai teks
            console.warn(`⚠️ Media marker ${mediaId} tidak ditemukan di materi ${materiId}`);
            return match;
        });
        
        // ============================================================
        // 4. GANTI ANCHOR FRASA → placeholder internal
        // ============================================================
        for (const anchor of anchorList) {
            if (!anchor.text || anchor.text.trim() === '') continue;
            
            // Escape regex special chars
            const escapedText = anchor.text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            
            // Cari frasa (case-insensitive), replace pertama saja
            const regex = new RegExp(`(${escapedText})`, 'i');
            
            let found = false;
            processedKonten = processedKonten.replace(regex, (match) => {
                if (found) return match;  // Hanya replace sekali
                found = true;
                return `${match}\n<!--MEDIA_INSERT:${anchor.media.id}-->\n`;
            });
            
            if (!found) {
                console.warn(`⚠️ Anchor frasa "${anchor.text}" tidak ditemukan di materi ${materiId}`);
            }
        }
        
        // ============================================================
        // 5. SPLIT BERDASARKAN PLACEHOLDER
        // ============================================================
        const parts = [];
        const insertRegex = /<!--MEDIA_INSERT:([A-Z0-9]+)-->/g;
        
        let lastIndex = 0;
        let match;
        
        while ((match = insertRegex.exec(processedKonten)) !== null) {
            // Teks sebelum placeholder
            if (match.index > lastIndex) {
                const text = processedKonten.substring(lastIndex, match.index);
                if (text.trim()) {
                    parts.push({ type: 'text', content: text });
                }
            }
            
            // Media
            const mediaId = match[1];
            const media = allMedia.find(m => m.id === mediaId);
            
            if (media) {
                parts.push({ type: 'media', media: media });
            }
            
            lastIndex = match.index + match[0].length;
        }
        
        // Sisa teks setelah placeholder terakhir
        if (lastIndex < processedKonten.length) {
            const text = processedKonten.substring(lastIndex);
            if (text.trim()) {
                parts.push({ type: 'text', content: text });
            }
        }
        
        // Kalau tidak ada placeholder sama sekali, return konten asli
        if (parts.length === 0) {
            parts.push({ type: 'text', content: konten });
        }
        
        console.log(`📄 processMediaMarkers: ${parts.length} parts (${parts.filter(p => p.type === 'media').length} media)`);
        
        return parts;
        
    } catch (e) {
        console.error('processMediaMarkers error:', e);
        return [{ type: 'text', content: konten }];
    }
}

// ============================================================
// 4. RENDER MEDIA (KIRIM KE TELEGRAM)
// ============================================================
async function sendMateriMedia(chatId, mediaList) {
    if (!mediaList || mediaList.length === 0) return;
    
    for (const media of mediaList) {
        try {
            const caption = media.caption || '';
            
            if (media.media_type === 'image') {
                // Prioritas: file_id > path
                const photo = media.file_id || media.media_path;
                if (!photo) continue;
                
                await fetch(`https://api.telegram.org/bot${getTelegramToken(env)}/sendPhoto`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ 
                        chat_id: chatId, 
                        photo: photo,
                        caption: caption.substring(0, 1024),
                        parse_mode: 'Markdown'
                    })
                });
                
            } else if (media.media_type === 'video') {
                const video = media.file_id || media.media_path;
                if (!video) continue;
                
                await fetch(`https://api.telegram.org/bot${getTelegramToken(env)}/sendVideo`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ 
                        chat_id: chatId, 
                        video: video,
                        caption: caption.substring(0, 1024)
                    })
                });
                
            } else if (media.media_type === 'audio') {
                const audio = media.file_id || media.media_path;
                if (!audio) continue;
                
                await fetch(`https://api.telegram.org/bot${getTelegramToken(env)}/sendAudio`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ 
                        chat_id: chatId, 
                        audio: audio,
                        caption: caption.substring(0, 1024)
                    })
                });
            }
            
            // Delay antar media
            await new Promise(r => setTimeout(r, 500));
            
        } catch (e) {
            console.error('sendMateriMedia error:', e);
        }
    }
}

// ============================================================
// 5. RENDER MATERI + MEDIA (LENGKAP)
// ============================================================
async function renderMateriWithMedia(chatId, materiId, konten, db) {
    try {
        // 1. Kirim media GLOBAL dulu
        const globalMedia = await getMateriMedia(db, materiId, null);
        if (globalMedia.length > 0) {
            await sendMessage(chatId, `🖼️ *Media Materi:*`);
            await sendMateriMedia(chatId, globalMedia);
            await new Promise(r => setTimeout(r, 800));
        }
        
        // 2. Split konten by tahap
        const tahapSections = konten.split(/(?=# [📚🔍⚙️💡🔗📊📋🔥🏆]\s*Tahap\s*T\d)/);
        
        for (const section of tahapSections) {
            if (!section.trim()) continue;
            
            // Detect tahap kode
            const match = section.match(/# [📚🔍⚙️💡🔗📊📋🔥🏆]\s*Tahap\s*(T\d)/);
            
            if (match) {
                const tahapKode = match[1];
                
                // Kirim media khusus tahap ini
                const tahapMedia = await getMateriMedia(db, materiId, tahapKode);
                if (tahapMedia.length > 0) {
                    await sendMateriMedia(chatId, tahapMedia);
                    await new Promise(r => setTimeout(r, 500));
                }
            }
            
            // Kirim konten tahap
            await renderMath(chatId, section.trim());
            await new Promise(r => setTimeout(r, 500));
        }
        
        return true;
    } catch (e) {
        console.error('renderMateriWithMedia error:', e);
        // Fallback
        await renderMath(chatId, konten);
        return false;
    }
}

// ============================================================
// 10. EKSTRAK SEMUA RUMUS DARI TEKS
// ============================================================
function extractFormulas(text) {
    if (!text) return [];
    
    const formulas = [];
    const mathRegex = /\$([^$\n]+)\$|\\\(([^)\n]+)\\\)|\\\[([^\]\n]+)\\\]/g;
    let match;
    
    while ((match = mathRegex.exec(text)) !== null) {
        const latex = match[1] || match[2] || match[3];
        if (latex && latex.trim()) {
            formulas.push({
                latex: latex.trim(),
                unicode: latexToUnicode(latex),
                isSimple: isSimpleFormula(latex)
            });
        }
    }
    
    return formulas;
}

// ============================================================
// HELPER: FORMAT MASTER DISPLAY
// Menampilkan master dengan format: [ KODE ] - Nama
// ============================================================
function formatMaster(kode, nama) {
    if (!kode && !nama) return '-';
    if (!kode) return nama;
    if (!nama) return `[ ${kode} ]`;
    return `[ ${kode} ] - ${nama}`;
}

