// ============================================================
// HELPER: CARI MASTER DARI NAMA (PARTIAL MATCH)
// Return: { found, id, nama, ambigu, list }
// ============================================================
async function findMasterByNama(db, table, nama, idField = 'id', nameField = 'nama') {
    try {
        const cleanNama = String(nama || '').trim();
        
        if (!cleanNama) {
            return { found: false, id: null, nama: null, ambigu: false, list: [] };
        }
        
        // Cek apakah input adalah kode (P01, TI01, dll.)
        // Kalau kode, langsung cari by id
        const isKode = /^[A-Z]{1,5}\d{1,4}$/i.test(cleanNama);
        
        if (isKode) {
            // Coba by id dulu
            const byId = await db.prepare(`
                SELECT ${idField} as id, ${nameField} as nama 
                FROM ${table} 
                WHERE ${idField} = ? 
                LIMIT 1
            `).bind(cleanNama.toUpperCase()).first();
            
            if (byId) {
                return { 
                    found: true, 
                    id: byId.id, 
                    nama: byId.nama, 
                    ambigu: false, 
                    list: [] 
                };
            }
            
            // Coba by kode_utama
            try {
                const byKode = await db.prepare(`
                    SELECT ${idField} as id, ${nameField} as nama 
                    FROM ${table} 
                    WHERE kode_utama = ? 
                    LIMIT 1
                `).bind(cleanNama.toUpperCase()).first();
                
                if (byKode) {
                    return { 
                        found: true, 
                        id: byKode.id, 
                        nama: byKode.nama, 
                        ambigu: false, 
                        list: [] 
                    };
                }
            } catch (e) {
                // Kolom kode_utama tidak ada, abaikan
            }
        }
        
        // Cari by nama (partial match)
        const result = await db.prepare(`
            SELECT ${idField} as id, ${nameField} as nama 
            FROM ${table} 
            WHERE LOWER(${nameField}) LIKE LOWER(?) 
            ORDER BY LENGTH(${nameField}) ASC
            LIMIT 20
        `).bind(`%${cleanNama}%`).all();
        
        const list = result.results || [];
        
        if (list.length === 0) {
            return { found: false, id: null, nama: null, ambigu: false, list: [] };
        }
        
        if (list.length === 1) {
            return { 
                found: true, 
                id: list[0].id, 
                nama: list[0].nama, 
                ambigu: false, 
                list: list 
            };
        }
        
        // Cek exact match dulu sebelum dianggap ambigu
        const exact = list.find(item => 
            String(item.nama).toLowerCase().trim() === cleanNama.toLowerCase()
        );
        
        if (exact) {
            return { 
                found: true, 
                id: exact.id, 
                nama: exact.nama, 
                ambigu: false, 
                list: list 
            };
        }
        
        // Ambigu
        return { 
            found: false, 
            id: null, 
            nama: null, 
            ambigu: true, 
            list: list 
        };
        
    } catch (e) {
        console.error('findMasterByNama error:', e);
        return { found: false, id: null, nama: null, ambigu: false, list: [] };
    }
}

