// ===== sendMessage =====
// ============================================================
// SEND MESSAGE DENGAN FALLBACK - PERBAIKAN
// ============================================================

async function sendMessage(chatId, text, parseMode = "Markdown") {
    try {
        // Jika text terlalu panjang, potong
        if (text && text.length > 4096) {
            const parts = text.match(/.{1,4096}/g) || [];
            for (const part of parts) {
                await sendMessage(chatId, part, parseMode);
            }
            return;
        }
        
        // Coba kirim dengan Markdown
        const response = await fetch(`https://api.telegram.org/bot${getTelegramToken()}/sendMessage`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ 
                chat_id: chatId, 
                text: text, 
                parse_mode: parseMode 
            })
        });
        
        const result = await response.json();
        
        // Jika error parse, kirim ulang tanpa Markdown
        if (!result.ok && result.description && result.description.includes('parse')) {
            console.log('⚠️ Markdown parse error, sending without parse mode');
            console.log('❌ Error:', result.description);
            
            // Kirim ulang tanpa parse mode
            const fallbackResponse = await fetch(`https://api.telegram.org/bot${getTelegramToken()}/sendMessage`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ 
                    chat_id: chatId, 
                    text: text
                })
            });
            
            const fallbackResult = await fallbackResponse.json();
            if (!fallbackResult.ok) {
                console.error('Fallback also failed:', fallbackResult.description);
                // Kirim pesan error sederhana
                await fetch(`https://api.telegram.org/bot${getTelegramToken()}/sendMessage`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ 
                        chat_id: chatId, 
                        text: '⚠️ Terjadi error saat menampilkan pesan. Silakan coba lagi.'
                    })
                });
            }
            return fallbackResult;
        }
        
        return result;
    } catch (error) {
        console.error("Send message error:", error);
        // Fallback: kirim tanpa parse mode
        try {
            await fetch(`https://api.telegram.org/bot${getTelegramToken()}/sendMessage`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ 
                    chat_id: chatId, 
                    text: text.substring(0, 4000) + (text.length > 4000 ? '...' : '')
                })
            });
        } catch (e) {
            console.error('Final fallback failed:', e);
        }
        return null;
    }
}

// ============================================================
// 🆕 ESCAPE MARKDOWN TELEGRAM
// ============================================================
// Escape karakter Markdown agar tidak bikin parse error
// ============================================================

function escapeMarkdown(text) {
    if (!text) return '';
    if (typeof text !== 'string') text = String(text);
    
    return text
        .replace(/\\/g, '\\\\')
        .replace(/_/g, '\\_')
        .replace(/\*/g, '\\*')
        .replace(/`/g, '\\`')
        .replace(/\[/g, '\\[')
        .replace(/\]/g, '\\]');
}

// ============================================================
// 🆕 ESCAPE MARKDOWN TEXT — ALIAS dari escapeMarkdown
// Fungsi ini dipanggil di beberapa tempat
// ============================================================

function escapeMarkdownText(text) {
    if (!text) return '';
    if (typeof text !== 'string') text = String(text);
    
    return text
        .replace(/\\/g, '\\\\')
        .replace(/_/g, '\\_')
        .replace(/\*/g, '\\*')
        .replace(/`/g, '\\`')
        .replace(/\[/g, '\\[')
        .replace(/\]/g, '\\]');
}

// ============================================================
// 🆕 SPLIT TEXT SMART — Potong di Akhir Kalimat/Paragraf
// ============================================================
// Ganti split per 3500 char dengan split yang:
// 1. Prioritaskan potong di akhir paragraf (\n\n)
// 2. Kalau tidak ada, potong di akhir kalimat (. ! ?)
// 3. Kalau tidak ada, potong di spasi terakhir
// 4. Kalau tidak ada, potong paksa
// ============================================================

function splitTextSmart(text, maxLength = 3500) {
    if (!text) return [];
    if (text.length <= maxLength) return [text];
    
    const parts = [];
    let remaining = text;
    
    while (remaining.length > maxLength) {
        let cutIndex = maxLength;
        let foundGoodCut = false;
        
        // 1. Prioritas: potong di akhir paragraf (\n\n)
        const paragraphCut = remaining.lastIndexOf('\n\n', maxLength);
        if (paragraphCut > maxLength * 0.5) {
            cutIndex = paragraphCut + 2;
            foundGoodCut = true;
        }
        
        // 2. Kalau tidak ada paragraf, potong di akhir kalimat
        if (!foundGoodCut) {
            const sentenceEnd = Math.max(
                remaining.lastIndexOf('. ', maxLength),
                remaining.lastIndexOf('! ', maxLength),
                remaining.lastIndexOf('? ', maxLength)
            );
            if (sentenceEnd > maxLength * 0.5) {
                cutIndex = sentenceEnd + 2;
                foundGoodCut = true;
            }
        }
        
        // 3. Kalau tidak ada kalimat, potong di spasi terakhir
        if (!foundGoodCut) {
            const spaceCut = remaining.lastIndexOf(' ', maxLength);
            if (spaceCut > maxLength * 0.5) {
                cutIndex = spaceCut + 1;
                foundGoodCut = true;
            }
        }
        
        // 4. Potong paksa
        if (!foundGoodCut) {
            cutIndex = maxLength;
        }
        
        const part = remaining.substring(0, cutIndex).trim();
        if (part.length > 0) {
            parts.push(part);
        }
        remaining = remaining.substring(cutIndex).trim();
    }
    
    if (remaining.length > 0) {
        parts.push(remaining);
    }
    
    return parts;
}

// ============================================================
// GET TELEGRAM FILE LINK — Konversi file_id jadi URL
// ============================================================
async function getTelegramFileLink(fileId) {
    if (!fileId) return null;
    
    try {
        const response = await fetch(
            `https://api.telegram.org/bot${getTelegramToken()}/getFile?file_id=${fileId}`
        );
        const data = await response.json();
        
        if (!data.ok) {
            console.warn('⚠️ getFile error:', data.description);
            return null;
        }
        
        const filePath = data.result.file_path;
        const fileUrl = `https://api.telegram.org/file/bot${getTelegramToken()}/${filePath}`;
        
        return fileUrl;
    } catch (e) {
        console.error('getTelegramFileLink error:', e);
        return null;
    }
}

// ============================================================
// RESOLVE MEDIA LINK — Prioritas: path/URL > file_id Telegram
// ============================================================
async function resolveMediaLink(pathValue, fileId) {
    // 1. Kalau ada path/URL → pakai langsung
    if (pathValue && pathValue.trim()) {
        return pathValue;
    }
    
    // 2. Kalau ada file_id → generate link Telegram
    if (fileId) {
        const link = await getTelegramFileLink(fileId);
        if (link) return link;
        // Fallback: tampilkan file_id dengan prefix telegram:
        return `telegram:${fileId}`;
    }
    
    return '';
}

// ============================================================
// 🆕 SANITIZE AI CONTENT — Konversi Markdown AI ke Telegram
// ============================================================
// AI pakai **bold**, ## heading, - bullet, ```code```
// Telegram hanya support *bold*, _italic_, `code`
// Fungsi ini konversi
// ============================================================

function sanitizeAIContent(text) {
    if (!text) return '';
    if (typeof text !== 'string') text = String(text);
    
    let result = text;
    
    // 1. Bold **teks** → *teks*
    result = result.replace(/\*\*([^*\n]+)\*\*/g, '*$1*');
    
    // 2. Italic __teks__ → _teks_
    result = result.replace(/__([^_\n]+)__/g, '_$1_');
    
    // 3. Heading ### teks → *teks*
    result = result.replace(/^#{1,6}\s*(.+)$/gm, '*$1*');
    
    // 4. Bullet * atau - → •
    result = result.replace(/^[\*\-]\s+/gm, '• ');
    
    // 5. Code ```...``` → hapus
    result = result.replace(/```[\s\S]*?```/g, (match) => {
        return match.replace(/```[a-z]*\n?/g, '').replace(/```/g, '').trim();
    });
    
    // 6. Link [teks](url) → teks (url)
    result = result.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1 ($2)');
    
    // 7. Tabel | ... | → list
    result = convertTableToList(result);
    
    // 8. Cek asterisk tidak berpasangan
    const asteriskCount = (result.match(/(?<!\\)\*/g) || []).length;
    if (asteriskCount % 2 !== 0) {
        // Ada * tidak berpasangan — escape semua
        result = result.replace(/(?<!\\)\*/g, '\\*');
    }
    
    // 9. Cek underscore tidak berpasangan
    const underscoreCount = (result.match(/(?<!\\)_/g) || []).length;
    if (underscoreCount % 2 !== 0) {
        result = result.replace(/(?<!\\)_/g, '\\_');
    }
    
    // 10. Cek backtick tidak berpasangan
    const backtickCount = (result.match(/(?<!\\)`/g) || []).length;
    if (backtickCount % 2 !== 0) {
        result = result.replace(/(?<!\\)`/g, '\\`');
    }
    
    // 11. Bersihkan newline berlebih
    result = result.replace(/\n{3,}/g, '\n\n');
    
    return result;
}

// ============================================================
// 🆕 RENDER MATERI — Kirim Konten dengan Split Cerdas + Math
// ============================================================

async function renderMateri(chatId, content, title = '') {
    if (!content) {
        await sendMessage(chatId, '❌ Materi kosong.');
        return false;
    }
    
    // Sanitize konten dulu
    const sanitized = sanitizeAIContent(content);
    
    // Split dengan cerdas
    const parts = splitTextSmart(sanitized, 3500);
    
    console.log(`📄 Materi di-split jadi ${parts.length} bagian`);
    
    for (let i = 0; i < parts.length; i++) {
        const part = parts[i];
        
        try {
            await renderMath(chatId, part);
        } catch (e) {
            console.error(`❌ Error render bagian ${i+1}:`, e);
            await sendMessage(chatId, part, null);
        }
        
        // Delay antar bagian
        if (i < parts.length - 1) {
            await new Promise(r => setTimeout(r, 800));
        }
    }
    
    return true;
}

// ============================================================
// ═══════════════════════════════════════════════════════════
// 🌐 UNIVERSAL MARKDOWN SYSTEM - FASE 2
// ═══════════════════════════════════════════════════════════
// Konversi output AI (Universal Markdown) ke format platform:
// - Telegram
// - WhatsApp
// - Blog (HTML)
// - Discord
// - Plain text
// ═══════════════════════════════════════════════════════════

// ============================================================
// 1. ATURAN UNIVERSAL (untuk getMarkdownRule)
// ============================================================
const UNIVERSAL_MARKDOWN_RULES = `
═══════════════════════════════════════════
📐 ATURAN FORMAT UNIVERSAL MARKDOWN (WAJIB!)
═══════════════════════════════════════════
✅ Bold: **teks**         (2 asterisk)
✅ Italic: *teks*          (1 asterisk)
✅ Heading: # / ## / ###
✅ List: - item  atau  1. item
✅ Tabel: | kolom | kolom |
✅ Code: \`inline\` atau \`\`\`block\`\`\`
✅ Link: [teks](url)
✅ Pemisah: ---

🚫 LARANGAN KERAS:
❌ JANGAN tulis pembuka apapun
❌ JANGAN tulis penutup apapun
❌ JANGAN gabung bagian jadi 1 paragraf
❌ JANGAN tulis lebih/kurang dari jumlah diminta
❌ JANGAN tambah field di luar yang diminta
═══════════════════════════════════════════
`;

// ============================================================
// 2. CONVERTER: Universal → Telegram
// ============================================================
function convertForTelegram(text) {
    if (!text) return '';
    
    let result = String(text);
    
    // 1. **bold** → *bold*
    result = result.replace(/\*\*([^*\n]+)\*\*/g, '*$1*');
    
    // 2. *italic* → _italic_
    result = result.replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g, '_$1_');
    
    // 3. # Heading → *Heading*
    result = result.replace(/^#{1,6}\s*(.+)$/gm, '*$1*');
    
    // 4. - item → • item
    result = result.replace(/^[-*]\s+/gm, '• ');
    
    // 5. Tabel → list
    result = convertTableToList(result);
    
    // 6. ```code``` → plain
    result = result.replace(/```[a-z]*\n?([\s\S]*?)```/g, (m, code) => {
        return '\n' + code.trim() + '\n';
    });
    
    // 7. > quote → hapus
    result = result.replace(/^>\s*(.+)$/gm, '$1');
    
    // 8. Bersihkan newline berlebih
    result = result.replace(/\n{3,}/g, '\n\n');
    
    return result;
}

// ============================================================
// 3. CONVERTER: Universal → WhatsApp
// ============================================================
function convertForWhatsApp(text) {
    if (!text) return '';
    
    let result = String(text);
    
    result = result.replace(/\*\*([^*\n]+)\*\*/g, '*$1*');
    result = result.replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g, '_$1_');
    result = result.replace(/^#{1,6}\s*(.+)$/gm, '*$1*');
    result = result.replace(/^[-*]\s+/gm, '• ');
    result = convertTableToList(result);
    result = result.replace(/^>\s*(.+)$/gm, '$1');
    result = result.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1 ($2)');
    result = result.replace(/\n{3,}/g, '\n\n');
    
    return result;
}

// ============================================================
// 4. CONVERTER: Universal → Blog (HTML)
// ============================================================
function convertForBlog(text) {
    if (!text) return '';
    
    let result = String(text);
    
    result = result
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
    
    result = result.replace(/```[a-z]*\n?([\s\S]*?)```/g, '<pre><code>$1</code></pre>');
    result = result.replace(/^######\s*(.+)$/gm, '<h6>$1</h6>');
    result = result.replace(/^#####\s*(.+)$/gm, '<h5>$1</h5>');
    result = result.replace(/^####\s*(.+)$/gm, '<h4>$1</h4>');
    result = result.replace(/^###\s*(.+)$/gm, '<h3>$1</h3>');
    result = result.replace(/^##\s*(.+)$/gm, '<h2>$1</h2>');
    result = result.replace(/^#\s*(.+)$/gm, '<h1>$1</h1>');
    result = result.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
    result = result.replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g, '<em>$1</em>');
    result = result.replace(/`([^`\n]+)`/g, '<code>$1</code>');
    result = result.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
    result = convertTableToHTML(result);
    result = result.replace(/^[-*]\s+(.+)$/gm, '<li>$1</li>');
    result = result.replace(/(<li>.*<\/li>\n?)+/g, '<ul>$&</ul>');
    result = result.replace(/^>\s*(.+)$/gm, '<blockquote>$1</blockquote>');
    result = result.replace(/^---$/gm, '<hr>');
    result = result.replace(/^(?!<[a-z])(.+)$/gm, '<p>$1</p>');
    
    return result;
}

// ============================================================
// 5. CONVERTER: Universal → Discord
// ============================================================
function convertForDiscord(text) {
    if (!text) return '';
    
    let result = String(text);
    result = result.replace(/^[-*]\s+/gm, '• ');
    result = result.replace(/\n{3,}/g, '\n\n');
    
    return result;
}

// ============================================================
// 6. CONVERTER: Universal → Plain Text
// ============================================================
function convertToPlain(text) {
    if (!text) return '';
    
    let result = String(text);
    result = result.replace(/\*\*([^*\n]+)\*\*/g, '$1');
    result = result.replace(/\*([^*\n]+)\*/g, '$1');
    result = result.replace(/_([^_\n]+)_/g, '$1');
    result = result.replace(/`([^`\n]+)`/g, '$1');
    result = result.replace(/^#{1,6}\s*(.+)$/gm, '$1');
    result = result.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1');
    result = result.replace(/^[-*]\s+/gm, '• ');
    result = result.replace(/^>\s*/gm, '');
    result = result.replace(/```[a-z]*\n?([\s\S]*?)```/g, '$1');
    result = result.replace(/^---$/gm, '');
    
    return result;
}

// ============================================================
// 7. HELPER: Tabel Markdown → List
// ============================================================
function convertTableToList(text) {
    const lines = text.split('\n');
    const result = [];
    let inTable = false;
    let headers = [];
    
    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        
        if (line.trim().startsWith('|') && line.trim().endsWith('|')) {
            const cells = line.split('|').slice(1, -1).map(c => c.trim());
            
            if (!inTable) {
                headers = cells;
                inTable = true;
                continue;
            }
            
            if (cells.every(c => /^[-:]+$/.test(c))) continue;
            
            const parts = cells.map((c, idx) => {
                const header = headers[idx] || '';
                return header ? `${header}: ${c}` : c;
            });
            result.push('• ' + parts.join(' | '));
        } else {
            inTable = false;
            headers = [];
            result.push(line);
        }
    }
    
    return result.join('\n');
}

// ============================================================
// 8. HELPER: Tabel Markdown → HTML
// ============================================================
function convertTableToHTML(text) {
    const lines = text.split('\n');
    const result = [];
    let inTable = false;
    let isHeaderRow = false;
    
    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        
        if (line.trim().startsWith('|') && line.trim().endsWith('|')) {
            const cells = line.split('|').slice(1, -1).map(c => c.trim());
            
            if (cells.every(c => /^[-:]+$/.test(c))) {
                isHeaderRow = false;
                continue;
            }
            
            if (!inTable) {
                result.push('<table>');
                inTable = true;
                isHeaderRow = true;
            }
            
            const tag = isHeaderRow ? 'th' : 'td';
            result.push('<tr>' + cells.map(c => `<${tag}>${c}</${tag}>`).join('') + '</tr>');
        } else {
            if (inTable) {
                result.push('</table>');
                inTable = false;
            }
            result.push(line);
        }
    }
    
    if (inTable) result.push('</table>');
    
    return result.join('\n');
}

// ============================================================
// 9. MASTER CONVERTER
// ============================================================
function convertMarkdown(text, platform = 'telegram') {
    if (!text) return '';
    
    switch (String(platform).toLowerCase()) {
        case 'telegram': return convertForTelegram(text);
        case 'whatsapp':
        case 'wa': return convertForWhatsApp(text);
        case 'blog':
        case 'html':
        case 'website': return convertForBlog(text);
        case 'discord': return convertForDiscord(text);
        case 'plain':
        case 'text': return convertToPlain(text);
        case 'universal':
        case 'raw': return text;
        default: return convertForTelegram(text);
    }
}

// ============================================================
// 🆕 MARKDOWN RULE — Instruksi Markdown Universal untuk AI
// ============================================================
// Fungsi ini mengembalikan aturan markdown universal (untuk AI).
// Aturan ini akan otomatis dikonversi ke format Telegram di
// sendMessage() melalui convertForTelegram().
// ============================================================

function getMarkdownRule() {
    return UNIVERSAL_MARKDOWN_RULES;
}

// ===== extractAIResponse =====
function extractAIResponse(provider, data) {
    switch (provider) {
        case 'gemini':
            return data.candidates?.[0]?.content?.parts?.[0]?.text || null;
            
        case 'groq':
        case 'mistral':
        case 'openrouter':
        case 'sambanova':
        case 'cerebras':
        case 'chutes':
        case 'siliconflow':
            return data.choices?.[0]?.message?.content || null;
            
        case 'cohere':
            return data.generations?.[0]?.text || null;
            
        case 'cloudflare':
            return data.result?.response || null;
            
        default:
            return null;
    }
}

// ============================================================
// PARSE RANGE NOMOR SOAL - VERSI LENGKAP
// ============================================================

function parseSoalRange(rangeText, totalSoal) {
    // Jika input kosong
    if (!rangeText || rangeText.trim() === '') {
        return [];
    }
    
    const parts = rangeText.split(',').map(p => p.trim());
    const selected = new Set();
    
    for (const part of parts) {
        // Skip jika kosong
        if (!part) continue;
        
        // Cek apakah range (contoh: 1-5)
        if (part.includes('-')) {
            const rangeParts = part.split('-').map(p => p.trim());
            if (rangeParts.length === 2) {
                const start = parseInt(rangeParts[0]);
                const end = parseInt(rangeParts[1]);
                
                if (!isNaN(start) && !isNaN(end) && start >= 1 && end <= totalSoal && start <= end) {
                    for (let i = start; i <= end; i++) {
                        selected.add(i);
                    }
                }
            }
        } else {
            // Single number
            const num = parseInt(part);
            if (!isNaN(num) && num >= 1 && num <= totalSoal) {
                selected.add(num);
            }
        }
    }
    
    return Array.from(selected).sort((a, b) => a - b);
}

