// ===== GET STATUS SOAL =====
// ============================================================
// 📊 FUNGSI GET STATUS SOAL - VERSI GABUNGAN
// LOKASI: Master Data Functions (setelah getLapisanPembelajaran)
// ============================================================

/**
 * Ambil data status soal dari database
 * @param {Object} db - Koneksi database
 * @param {string} type - Tipe status yang ingin diambil: 'all', 'keabsahan', 'ketersediaan'
 * @returns {Promise<Object|Array>} Data status sesuai tipe yang diminta
 */
async function getStatusSoal(db, type = 'all') {
    try {
        // ============================================================
        // 1. AMBIL SEMUA STATUS (type = 'all')
        // ============================================================
        if (type === 'all') {
            const result = await db.prepare(`
                SELECT * FROM status_soal 
                WHERE is_active = 1 
                ORDER BY urutan ASC
            `).all();
            return result.results || [];
        }
        
        // ============================================================
        // 2. AMBIL STATUS KEABSAHAN (type = 'keabsahan')
        // ============================================================
        if (type === 'keabsahan') {
            const result = await db.prepare(`
                SELECT id, nama, deskripsi, warna, icon, urutan
                FROM status_soal 
                WHERE is_active = 1 
                AND id IN ('resmi', 'adaptasi', 'mandiri', 'draft_keabsahan')
                ORDER BY urutan ASC
            `).all();
            return result.results || [];
        }
        
        // ============================================================
        // 3. AMBIL STATUS KETERSEDIAAN (type = 'ketersediaan')
        // ============================================================
        if (type === 'ketersediaan') {
            const result = await db.prepare(`
                SELECT id, nama, deskripsi, warna, icon, urutan
                FROM status_soal 
                WHERE is_active = 1 
                AND id IN ('draft_ketersediaan', 'review', 'publish', 'revisi', 'arsip')
                ORDER BY urutan ASC
            `).all();
            return result.results || [];
        }
        
        // ============================================================
        // 4. AMBIL STATUS TERPISAH (type = 'separated') - untuk backward compatibility
        // ============================================================
        if (type === 'separated') {
            const keabsahan = await db.prepare(`
                SELECT id, nama, deskripsi, warna, icon, urutan
                FROM status_soal 
                WHERE is_active = 1 
                AND id IN ('resmi', 'adaptasi', 'mandiri', 'draft_keabsahan')
                ORDER BY urutan ASC
            `).all();
            
            const ketersediaan = await db.prepare(`
                SELECT id, nama, deskripsi, warna, icon, urutan
                FROM status_soal 
                WHERE is_active = 1 
                AND id IN ('draft_ketersediaan', 'review', 'publish', 'revisi', 'arsip')
                ORDER BY urutan ASC
            `).all();
            
            return {
                keabsahan: keabsahan.results || [],
                ketersediaan: ketersediaan.results || []
            };
        }
        
        // ============================================================
        // 5. DEFAULT: return semua status
        // ============================================================
        const result = await db.prepare(`
            SELECT * FROM status_soal 
            WHERE is_active = 1 
            ORDER BY urutan ASC
        `).all();
        return result.results || [];
        
    } catch (e) {
        console.error('❌ Error getStatusSoal:', e);
        
        // Return sesuai tipe yang diminta
        if (type === 'separated') {
            return { keabsahan: [], ketersediaan: [] };
        }
        return [];
    }
}

