// =========================
// 📝 FUNGSI FORMAT UNIVERSAL - MENANGANI 6 TABEL MASTER
// =========================

// =========================
// 📊 FORMAT MASTER DATA
// =========================

function formatMasterData(data, type) {
    if (!data || data.length === 0) {
        const labels = {
            'cara_penyajian': 'Cara Penyajian',
            'tipe_isi_soal': 'Tipe Isi Soal',
            'tahap_pembelajaran': 'Tahap Pembelajaran',
            'sumber_belajar': 'Sumber Belajar',
            'lapisan_pembelajaran': 'Lapisan Pembelajaran',
            'status_soal': 'Status Soal'
        };
        return `❌ Belum ada data ${labels[type] || type}.`;
    }
    
    const configs = {
		// ===== CARA PENYAJIAN =====
        'cara_penyajian': {
            title: '📋 *CARA PENYAJIAN SOAL*',
            groupBy: 'kategori',
            itemFormat: (item) => {
                let text = `   ${item.icon || '📝'} ${item.nama}`;
                if (item.sub_jenis) text += ` (${item.sub_jenis})`;
                if (item.kode_utama) text += ` [${item.kode_utama}]`;
                return text;
            }
        },
		
		// ===== TIPE ISI SOAL =====
        'tipe_isi_soal': {
            title: '📋 *TIPE ISI SOAL*',
            groupBy: 'kategori',
            itemFormat: (item) => {
                let text = `   📌 ${item.nama}`;
                if (item.sub_tipe) text += ` (${item.sub_tipe})`;
                
                return text;
            }
        },
		
		// ===== TAHAP PEMBELAJARAN =====
        'tahap_pembelajaran': {
            title: '📋 *TAHAP PEMBELAJARAN*',
            groupBy: null,
            itemFormat: (item) => {
                let text = `${item.icon || '📚'} *${item.nama}*\n`;
                text += `   📝 ${item.deskripsi}\n`;
                
                return text;
            }
        },
		
		// ===== SUMBER BELAJAR =====
        'sumber_belajar': {
            title: '📋 *SUMBER BELAJAR*',
            groupBy: 'kategori',
            itemFormat: (item) => {
                let text = `   ${item.icon || '📚'} *${item.nama}*`;
                if (item.kode) text += ` [${item.kode}]`;
                return text;
            }
        },
		
		// ===== LAPISAN PEMBELAJARAN =====
        'lapisan_pembelajaran': {
            title: '📋 *LAPISAN PEMBELAJARAN*',
            groupBy: null,
            itemFormat: (item) => {
                let text = `${item.icon || '📚'} *Level ${item.level}: ${item.nama}*\n`;
                text += `   📝 ${item.deskripsi}\n`;
                text += `   ${item.is_wajib ? '✅ Wajib' : '🔹 Opsional'}`;
                return text;
            }
        },
        'status_soal': {
            title: '📋 *STATUS SOAL*',
            groupBy: null,
            itemFormat: (item) => {
                let text = `${item.icon || '📌'} *${item.nama}*\n`;
                text += `   📝 ${item.deskripsi}\n`;
                if (item.warna) text += `   🎨 Warna: ${item.warna}`;
                return text;
            }
        }
    };
    
    const config = configs[type];
    if (!config) {
        return `❌ Tipe "${type}" tidak dikenal.`;
    }
    
    let output = `${config.title}\n\n`;
    
    if (config.groupBy) {
        let currentGroup = '';
        for (const item of data) {
            const groupValue = item[config.groupBy] || 'Lainnya';
            if (groupValue !== currentGroup) {
                currentGroup = groupValue;
                output += `\n📂 *${currentGroup}*\n`;
            }
            output += config.itemFormat(item) + '\n';
        }
    } else {
        for (const item of data) {
            output += config.itemFormat(item) + '\n\n';
        }
    }
    
    output += `\n📊 Total: ${data.length} data aktif`;
    return output;
}


