// ============================================================
// HELPER: PARSE EDIT ITEM (ID + Nama + Deskripsi)
// ============================================================
function parseItemEdit(part) {
    const idMatch = part.match(/id\s*:\s*(.+?)(?=\s*(?:nama|deskripsi)\s*:|$)/im);
    const namaMatch = part.match(/nama\s*:\s*(.+?)(?=\s*(?:id|deskripsi)\s*:|$)/im);
    const descMatch = part.match(/deskripsi\s*:\s*(.+?)(?=\s*(?:id|nama)\s*:|$)/im);
    
    return {
        id: idMatch ? idMatch[1].trim().toUpperCase() : null,
        nama: namaMatch ? namaMatch[1].trim() : null,
        deskripsi: descMatch ? descMatch[1].trim() : null
    };
}




async function parseDeleteInput(arg1, arg2 = 50, arg3 = null, arg4 = null, arg5 = null) {
    const isModeB = typeof arg1 !== 'string' && arg1 !== null && typeof arg1 === 'object';
    
    let input, maxItems, db, table, idField, nameField;
    
    if (isModeB) {
        db = arg1;
        input = arg2;
        table = arg3;
        idField = arg4 || 'id';
        nameField = arg5 || 'nama';
        maxItems = 50;
    } else {
        input = arg1;
        maxItems = typeof arg2 === 'number' ? arg2 : 50;
    }
    
    if (typeof input !== 'string') {
        return isModeB ? [] : { error: 'Input harus berupa string.' };
    }
    
    const ids = [];
    const lines = input.split('\n').map(l => l.trim()).filter(Boolean);
    
    for (const line of lines) {
        const parts = line.split(',').map(s => s.trim()).filter(Boolean);
        for (const part of parts) {
            if (part.includes('-')) {
                const [start, end] = part.split('-').map(s => s.trim());
                const startNum = parseInt(start.replace(/\D/g, ''));
                const endNum = parseInt(end.replace(/\D/g, ''));
                const prefix = start.replace(/\d/g, '').toUpperCase();
                
                if (!isNaN(startNum) && !isNaN(endNum) && startNum <= endNum) {
                    for (let i = startNum; i <= endNum; i++) {
                        ids.push(`${prefix}${String(i).padStart(3, '0')}`);
                    }
                }
            } else if (part) {
                ids.push(part.toUpperCase());
            }
        }
    }
    
    const uniqueIds = [...new Set(ids)];
    
    if (uniqueIds.length > maxItems) {
        return isModeB ? [] : { error: `Maksimal ${maxItems} ID per input. Anda kirim ${uniqueIds.length}.` };
    }
    
    if (!isModeB) {
        return { ids: uniqueIds };
    }
    
    if (!db || !table) {
        return [];
    }
    
    console.log(`🔍 [parseDeleteInput] table=${table}, ids=[${uniqueIds.join(', ')}]`);
    
    const items = [];
    
    for (const id of uniqueIds) {
        let row = null;
        let found = false;
        let method = '';
        
        // Fallback 1: Exact
        try {
            const result = await db.prepare(
                `SELECT * FROM ${table} WHERE ${idField} = ? LIMIT 1`
            ).bind(id).first();
            
            if (result && typeof result === 'object' && Object.keys(result).length > 0) {
                row = result;
                found = true;
                method = 'exact';
            }
        } catch (e1) {
            console.log(`⚠️ Fallback 1 gagal: ${e1.message}`);
        }
        
        // Fallback 2: Case-insensitive
        if (!found) {
            try {
                const result = await db.prepare(
                    `SELECT * FROM ${table} WHERE LOWER(${idField}) = LOWER(?) LIMIT 1`
                ).bind(id).first();
                
                if (result && typeof result === 'object' && Object.keys(result).length > 0) {
                    row = result;
                    found = true;
                    method = 'case-insensitive';
                }
            } catch (e2) {}
        }
        
        // Fallback 3: Trim
        if (!found) {
            try {
                const result = await db.prepare(
                    `SELECT * FROM ${table} WHERE TRIM(${idField}) = TRIM(?) LIMIT 1`
                ).bind(id).first();
                
                if (result && typeof result === 'object' && Object.keys(result).length > 0) {
                    row = result;
                    found = true;
                    method = 'trim';
                }
            } catch (e3) {}
        }
        
        // Fallback 4: LIKE
        if (!found) {
            try {
                const result = await db.prepare(
                    `SELECT * FROM ${table} WHERE ${idField} LIKE ? LIMIT 1`
                ).bind(`%${id}%`).first();
                
                if (result && typeof result === 'object' && Object.keys(result).length > 0) {
                    row = result;
                    found = true;
                    method = 'like';
                }
            } catch (e4) {}
        }
        
        if (found && row) {
            console.log(`✅ ID "${id}" via ${method}`);
            if (row.id === undefined) row.id = row[idField];
            items.push(row);
        } else {
            console.log(`❌ ID "${id}" tidak ditemukan`);
        }
    }
    
    console.log(`📊 Selesai: ${items.length}/${uniqueIds.length}`);
    return items;
}

