function buildNavGroupMenu(group) {
    const g = NAV_GROUPS[group];
    if (!g) return [[{text:'🔙 Kembali',callback_data:'nav:main'}]];
    const rows=[];
    for(let i=0;i<g.items.length;i+=2) rows.push(g.items.slice(i,i+2).map(([text,key])=>({text,callback_data:`nav:g:${key}`})));
    return rows;
}

