function buildEntityContextMenu(entity) {
    const c=getEntityConfig(entity); if(!c)return [[{text:'🔙 Kembali',callback_data:'nav:h'}]];
    const parent=c.parentTable?Object.entries(ENTITY_CONFIG).find(([,x])=>x.table===c.parentTable)?.[0]:null;
    return [[{text:'📋 Lihat',callback_data:`ent_list_${entity}`},{text:'➕ Tambah',callback_data:`ent_add_${entity}`}],[{text:'✏️ Ubah',callback_data:`ent_edit_${entity}`},{text:'🗑️ Hapus',callback_data:`ent_delete_${entity}`}],[{text:'🔄 Urutkan',callback_data:`ent_reorder_${entity}`}],[{text:'🔙 Kembali',callback_data:parent?`nav:h:${parent}`:'nav:h'}]];
}

