function adminGuideForCommand(cmd){
    const c=String(cmd||'');
    if(c==='/cek_semua') return `ℹ️ *PANDUAN FUNGSI*\n\n🩺 *Cek Semua Sistem*\n\`/cek_semua\`\n\nPemeriksaan cepat terpadu untuk Database, Query D1, Session, Credential AI/API, Alarm User, dan ringkasan Log 24 jam. Fungsi ini bersifat diagnostik dan tidak mengubah data.`;
    const n=c.replace(/^\//,'').replace(/_/g,' ');
    let action='Menjalankan fungsi '+n+'.';
    if(/_list$|^\/daftar|^\/master$/.test(c)) action='Melihat daftar/data yang tersedia.';
    else if(/_add$|^\/soal_add|^\/template_add/.test(c)) action='Menambahkan data baru.';
    else if(/_edit$/.test(c)) action='Mengubah data yang sudah ada.';
    else if(/_delete$|_remove$|_cancel$/.test(c)) action='Menghapus, menonaktifkan, atau membatalkan data.';
    else if(/_stats$|^\/stats|^\/statistik/.test(c)) action='Melihat statistik dan ringkasan data.';
    else if(/^\/upload|^\/import/.test(c)) action='Mengimpor data ke bot.';
    else if(/^\/export|^\/backup/.test(c)) action='Mengekspor atau mencadangkan data.';
    else if(/^\/restore/.test(c)) action='Memulihkan data dari backup yang kompatibel.';
    else if(/^\/test|^\/cek|^\/debug/.test(c)) action='Memeriksa fungsi/kondisi sistem tanpa mengubah data, kecuali dinyatakan lain.';
    else if(/^\/ai_/.test(c)||c==='/ai') action='Menjalankan atau mengatur fitur AI.';
    else if(/^\/alarm_user_/.test(c)) action='Mengelola pengingat belajar user yang tersimpan di D1.';
    const usage=(c.includes('_detail')||c.includes('_edit')||c.includes('_delete')||c.includes('_block')||c.includes('_unblock')||c.includes('_level')||c.includes('_add')||c.includes('_remove')||c.includes('_buat')||c.includes('_ubah')||c.includes('_set')||c.includes('_test')) ? `\nContoh: ${c} [parameter]` : `\nContoh: ${c}`;
    return `ℹ️ *PANDUAN FUNGSI*\n\n*${adminMenuLabel(c)}*\n\`${c}\`\n\n${action}${usage}\n\n⚠️ Untuk fungsi perubahan/penghapusan, pastikan ID dan data sudah benar.`;
}
function buildAdminGroupGuideMenu(groupKey,page=0){
    const group=ADMIN_MENU_GROUPS[groupKey];
    if(!group)return [];
    const size=8,total=Math.max(1,Math.ceil(group.commands.length/size));
    const p=Math.min(Math.max(0,Number(page)||0),total-1);
    const slice=group.commands.slice(p*size,(p+1)*size);
    const rows=slice.map((cmd,i)=>[{text:`ℹ️ ${adminMenuLabel(cmd).replace(/^[^ ]+ /,'')}`,callback_data:`adm_help_${groupKey}_${p}_${i}`}]);
    const nav=[];
    if(p>0)nav.push({text:'⬅️ Sebelumnya',callback_data:`adm_guide_${groupKey}_p${p-1}`});
    if(p<total-1)nav.push({text:'➡️ Berikutnya',callback_data:`adm_guide_${groupKey}_p${p+1}`});
    if(nav.length)rows.push(nav);
    rows.push([{text:'🔙 Kembali ke Fungsi',callback_data:`adm_menu_${groupKey}_p${Math.floor((p*size)/12)}`}]);
    return rows;
}

