function buildDataTransferTableButtons(prefix='dt:t:') {
    const entries=Object.keys(ALL_SCHEMAS);
    const keyboard=[];
    for(let i=0;i<entries.length;i+=2){
        const row=[];
        for(const table of entries.slice(i,i+2)) row.push({text:String(table).slice(0,10),callback_data:`${prefix}${table}`});
        keyboard.push(row);
    }
    if(prefix.includes(':export:')) keyboard.push([{text:'📦 Semua',callback_data:'dt:all'}]);
    keyboard.push([{text:'🔙 Kembali',callback_data:'adm_menu_data'}]);
    return keyboard;
}

async function showDataTransferMenu(chatId,messageId=null){
    const msg=`📦 *DATA — EXPORT / IMPORT*\n${DIVIDER}\n\nPilih operasi:`;
    const kb=[[{text:'📤 Ekspor',callback_data:'dt:export'} ,{text:'📥 Impor',callback_data:'dt:import'}],
              [{text:'📋 Panduan',callback_data:'dt:guide'}],[{text:'🔙 Kembali',callback_data:'menu_back'}]];
    if(messageId) await editInlineKeyboard(chatId,messageId,msg,kb); else await sendInlineKeyboard(chatId,msg,kb);
}

async function showDataTransferTableMenu(chatId,messageId,mode){
    const title=mode==='export'?'📤 PILIH TABEL EXPORT':'📥 PILIH TABEL IMPORT';
    const msg=`${title}\n${DIVIDER}\n\nPilih tabel yang akan diproses:`;
    const kb=buildDataTransferTableButtons('dt:t:'+mode+':');
    if(messageId) await editInlineKeyboard(chatId,messageId,msg,kb); else await sendInlineKeyboard(chatId,msg,kb);
}

async function sendUniversalTableExport(env,userId,chatId,db,table,format='csv'){
    const r=await exportTableData(db,table,{limit:DATA_TRANSFER_MAX_ROWS});
    if(!r.success) throw new Error(r.error||'Export gagal');
    if(r.truncated) throw new Error(`Export ${table} melebihi batas ${DATA_TRANSFER_MAX_ROWS.toLocaleString('id-ID')} baris. Gunakan export bertahap.`);
    let bytes=r.content, filename=r.filename, mime='text/csv';
    if(format==='xlsx'){
        const parsed=parseCSVTransfer(r.content);
        bytes=await exportRowsToXlsx([parsed.columns,...parsed.rows.map(row=>parsed.columns.map(c=>row[c]??''))]);
        filename=filename.replace(/\.csv$/i,'.xlsx'); mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
    }
    const sent=await sendFileToTelegram(chatId,bytes,filename,`📤 Export ${table}\nFormat: ${format.toUpperCase()}\nRows: ${r.total}`);
    if(!sent.success) throw new Error(sent.error||'Gagal mengirim file');
    return r;
}

async function sendUniversalAllExport(chatId,db){
    const r=await exportAllTablesData(db,{limit:DATA_TRANSFER_MAX_ROWS});
    const failed=r.manifest.tables.filter(x=>x.error);
    const truncated=r.manifest.tables.filter(x=>x.truncated);
    if(failed.length) throw new Error(`Export gagal pada ${failed.length} tabel: ${failed.slice(0,5).map(x=>x.table).join(', ')}`);
    if(truncated.length) throw new Error(`Export terpotong pada ${truncated.length} tabel karena batas ${DATA_TRANSFER_MAX_ROWS.toLocaleString('id-ID')} baris.`);
    const entries=[];
    for(const f of r.files) entries.push({name:`tables/${f.filename}`,data:f.content});
    entries.push({name:'manifest.json',data:JSON.stringify(r.manifest,null,2)});
    const zip=zipStore(entries);
    const filename=`d1_export_${new Date().toISOString().replace(/[:.]/g,'-')}.zip`;
    const sent=await sendFileToTelegram(chatId,zip,filename,`📦 Export semua tabel\nTabel: ${r.manifest.table_count}`);
    if(!sent.success) throw new Error(sent.error||'Gagal mengirim ZIP');
    return r;
}

async function downloadTelegramDocumentBytes(env,fileId){
    const token=getTelegramToken(env); if(!token) throw new Error('Telegram token belum tersedia.');
    const fr=await fetch(`https://api.telegram.org/bot${token}/getFile?file_id=${fileId}`); const fd=await fr.json();
    if(!fd.ok) throw new Error(fd.description||'Gagal mengambil file Telegram.');
    const dr=await fetch(`https://api.telegram.org/file/bot${token}/${fd.result.file_path}`);
    if(!dr.ok) throw new Error(`Download file gagal HTTP ${dr.status}`);
    return new Uint8Array(await dr.arrayBuffer());
}

async function readUniversalImportDocument(env,fileName,fileId){
    const bytes=await downloadTelegramDocumentBytes(env,fileId);
    if(/\.xlsx$/i.test(fileName)){
        const rows=await importXlsxToRows(bytes);
        if(!rows.length) throw new Error('XLSX kosong.');
        const columns=rows[0].map(v=>String(v??'').trim());
        return {columns,rows:rows.slice(1).map(r=>Object.fromEntries(columns.map((c,i)=>[c,r[i]??'']))) ,format:'xlsx'};
    }
    if(/\.csv$/i.test(fileName)){
        const parsed=parseCSVTransfer(new TextDecoder().decode(bytes));
        return {...parsed,format:'csv'};
    }
    throw new Error('Format import harus CSV atau XLSX.');
}

async function previewUniversalImportUpload(env,userId,chatId,db,fileName,fileId){
    const session=await getSession(env,userId); const pending=session.universalImport;
    if(!pending?.table) throw new Error('Pilih tabel import terlebih dahulu.');
    const doc=await readUniversalImportDocument(env,fileName,fileId);
    const preview=await prepareImportPreview(db,pending.table,doc.rows,{columns:doc.columns,mode:pending.mode});
    if(!preview.success){
        const errs=preview.validation.errors.slice(0,8).map(e=>`• ${e}`).join('\n');
        await smartMessage(chatId,`❌ *VALIDASI GAGAL*\n\n${errs}\n\nFile belum diubah.`); return false;
    }
    pending.fileId=fileId; pending.fileName=fileName; pending.format=doc.format; pending.preview=preview.preview; pending.totalRows=doc.rows.length;
    await saveSession(env,userId,session);
    const sample=preview.preview.slice(0,10).map(x=>`${x.row}. ${x.id} → ${x.action}`).join('\n')||'—';
    await sendInlineKeyboard(chatId,`📋 *PREVIEW IMPORT*\n${DIVIDER}\n\nTabel: *${pending.table}*\nMode: *${pending.mode.toUpperCase()}*\nRows: *${doc.rows.length}*\nFormat: *${doc.format.toUpperCase()}*\n\n${sample}\n\n⚠️ Belum ada perubahan database.`,[[{text:'✅ Konfirmasi',callback_data:'dt:confirm'}],[{text:'❌ Batal',callback_data:'dt:cancel'}]]);
    return true;
}

function shortCommandLabel(cmd){
    const c=String(cmd||'').replace(/^\//,'');
    const map={
        kategori:'Kat',bidang:'Bid',program:'Prog',jenjang:'Jen',kelas:'Kls',topik:'Top',subtopik:'SubTop',kisi:'Kisi',kemampuan:'Kem',subkemampuan:'SubKem',
        mata_pelajaran:'Mapel',mata_kuliah:'Matkul',soal:'Soal',review:'Review',materi:'Materi',user:'User',token:'Token',ai:'AI',alarm_user:'Alarm',template:'Tpl',
        statistik:'Stat',dashboard:'Dash',stats:'Stat',analytics:'Analitik',voucher:'Voucher',sertifikat:'Sertif',ujian:'Ujian',broadcast:'Notif',notifikasi:'Notif'
    };
    const root=Object.keys(map).find(k=>c===k||c.startsWith(k+'_'));
    const rootLabel=root?map[root]:'';
    let action='Fungsi';
    if(/_list$|^daftar/.test(c)) action='Lihat';
    else if(/_add$|_buat$/.test(c)) action='Tambah';
    else if(/_edit$|_ubah$/.test(c)) action='Ubah';
    else if(/_delete$|_remove$|_cancel$/.test(c)) action='Hapus';
    else if(/_reorder$/.test(c)) action='Urut';
    else if(/_detail$|_view$/.test(c)) action='Detail';
    else if(/_stats$|^stats_|^statistik/.test(c)) action='Stat';
    else if(/_bulk$|_batch$|add_bulk/.test(c)) action='Massal';
    else if(/search|^cari$/.test(c)) action='Cari';
    else if(/upload|import/.test(c)) action='Impor';
    else if(/export/.test(c)) action='Ekspor';
    else if(/backup/.test(c)) action='Backup';
    else if(/restore|rollback/.test(c)) action='Pulih';
    else if(/test|cek|debug/.test(c)) action='Tes';
    else if(/setting|config/.test(c)) action='Setel';
    else if(/generate|gen_/.test(c)) action='Generate';
    else if(/approve/.test(c)) action='Setuju';
    else if(/reject/.test(c)) action='Tolak';
    else if(/fix|reclassify/.test(c)) action='Perbaiki';
    const label=rootLabel?`${rootLabel} ${action}`:action;
    // Kontrak UI baru: maksimal 20 karakter; jangan potong buta.
    return normalizeButtonLabel(label);
}


// ============================================================
// SEMANTIC ADMIN NAVIGATION — GROUP → ENTITY → ACTION → HANDLER
// Tidak menampilkan command mentah pada tombol. Digunakan sebagai
// canonical navigation layer; handler lama tetap dipertahankan.
// ============================================================
function semanticCommandParts(command='') {
    const c=String(command||'').replace(/^\//,'');
    const destructive=/(^|_)(delete|remove)(_|$)/.test(c);
    let action='Lainnya';
    if(/(^|_)(list|view|detail|daftar|search|cari|filter|status)(_|$)/.test(c)) action='Lihat';
    else if(/(^|_)(add|buat|create)(_|$)/.test(c)) action='Tambah';
    else if(/(^|_)(edit|ubah|set|update)(_|$)/.test(c)) action='Ubah';
    else if(/(^|_)(delete|remove)(_|$)/.test(c)) action='Hapus';
    else if(/(^|_)(reorder|urut)(_|$)/.test(c)) action='Urutkan';
    else if(/(^|_)(stats|statistik|stat)(_|$)/.test(c)) action='Statistik';
    else if(/(^|_)(upload|import|massal|bulk|batch)(_|$)/.test(c)) action='Impor';
    else if(/(^|_)(export|download)(_|$)/.test(c)) action='Ekspor';
    else if(/(^|_)(backup)(_|$)/.test(c)) action='Backup';
    else if(/(^|_)(restore|rollback)(_|$)/.test(c)) action='Pulihkan';
    else if(/(^|_)(generate|gen)(_|$)/.test(c)) action='Generate';
    else if(/(^|_)(approve)(_|$)/.test(c)) action='Setujui';
    else if(/(^|_)(reject)(_|$)/.test(c)) action='Tolak';
    else if(/(^|_)(review|validasi|cek)(_|$)/.test(c)) action='Validasi';
    else if(/(^|_)(fix|reclassify|clean)(_|$)/.test(c)) action='Perbaiki';
    else if(/(^|_)(setting|config)(_|$)/.test(c)) action='Setelan';
    if(destructive) action='Hapus';
    const tokens=c.split('_');
    const knownPrefixes=['statistik','stats','dashboard','rollback','upload','export','backup','restore','filter','search','cari','daftar','template','kolom','ai','user','token','report','materi','soal','kategori','bidang','program','jenjang','kelas','topik','subtopik','kisi','kemampuan','subkemampuan','mata','kuliah','pelajaran','pertanyaan','alarm','notifikasi','ujian','reward','voucher','analytics','system','master','ent','review','validasi','reclassify','fix','test','cek','debug'];
    let entity=tokens[0]||'fungsi';
    if(tokens[0]==='mata' && tokens[1]) entity=`mata_${tokens[1]}`;
    else if(tokens[0]==='ai' && tokens[1]) entity=`ai_${tokens[1]}`;
    else if(tokens[0]==='stats' && tokens[1]) entity=tokens[1];
    else if(tokens[0]==='statistik' && tokens[1]) entity=tokens[1];
    else if(tokens[0]==='report' && tokens[1]) entity=`report_${tokens[1]}`;
    else if(tokens[0]==='upload' && tokens[1]) entity=`upload_${tokens[1]}`;
    else if(tokens[0]==='export' && tokens[1]) entity=`export_${tokens[1]}`;
    else if(tokens[0]==='master' && tokens[1]) entity=`master_${tokens[1]}`;
    else if(tokens[0]==='ai' && tokens[1]) entity=`ai_${tokens[1]}`;
    if(!knownPrefixes.includes(tokens[0])) entity=tokens[0]||'fungsi';
    return {command:c,action,entity,destructive};
}

function semanticEntityLabel(entity='fungsi') {
    const labels={
        kategori:'Kategori',bidang:'Bidang',program:'Program',jenjang:'Jenjang',kelas:'Kelas',
        topik:'Topik',subtopik:'Sub-Topik',kisi:'Kisi-Kisi',kemampuan:'Kemampuan',subkemampuan:'Sub-Kemampuan',
        mata_kuliah:'Mata Kuliah',mata_pelajaran:'Mata Pelajaran',soal:'Soal',materi:'Materi',user:'User',
        token:'Token',template:'Template',pertanyaan:'Pertanyaan',alarm:'Alarm',notifikasi:'Notifikasi',
        ujian:'Ujian',reward:'Reward',voucher:'Voucher',ai:'AI',global:'Global',db:'Database',system:'Sistem',
        master:'Master',backup:'Backup',export:'Ekspor',upload:'Impor',search:'Pencarian',filter:'Filter',
        report:'Laporan',review:'Review',validasi:'Validasi',reclassify:'Klasifikasi',fix:'Perbaikan'
    };
    if(labels[entity]) return labels[entity];
    return String(entity||'fungsi').replace(/_/g,' ').replace(/\b\w/g,m=>m.toUpperCase());
}

function semanticActionLabel(command, fallback='Aksi') {
    const p=semanticCommandParts(command);
    const c=p.command;
    if(/_status$/.test(c)) return 'Status';
    if(/_detail$|_view$/.test(c)) return 'Detail';
    if(/_list$|_daftar$/.test(c)) return 'Daftar';
    if(/_bulk$|_batch$|massal/.test(c)) return 'Massal';
    if(/_setting|_config/.test(c)) return 'Setelan';
    if(/_stats$|^stats_|^statistik/.test(c)) return 'Statistik';
    if(/_media/.test(c)) return 'Media';
    if(/_version/.test(c)) return 'Versi';
    if(/_history/.test(c)) return 'Riwayat';
    return p.action||fallback;
}

function buildSemanticAdminMenu(groupKey,page=0) {
    const group=ADMIN_MENU_GROUPS[groupKey];
    if(!group) return [[{text:'🔙 Kembali',callback_data:'nav:main'}]];
    const map=new Map();
    for(const command of group.commands){
        const p=semanticCommandParts(command);
        if(!map.has(p.entity)) map.set(p.entity,[]);
        map.get(p.entity).push(command);
    }
    const entries=[...map.entries()];
    const size=10;
    const total=Math.max(1,Math.ceil(entries.length/size));
    const pageSafe=Math.min(Math.max(0,Number(page)||0),total-1);
    const slice=entries.slice(pageSafe*size,(pageSafe+1)*size);
    const rows=[];
    for(let i=0;i<slice.length;i+=2){
        rows.push(slice.slice(i,i+2).map(([entity])=>({
            text:normalizeButtonLabel(`📂 ${semanticEntityLabel(entity)}`),
            callback_data:`adm_sem:${groupKey}:e:${encodeURIComponent(entity)}`
        })));
    }
    const nav=[];
    if(pageSafe>0) nav.push({text:'⬅️ Sebelumnya',callback_data:`adm_sem:${groupKey}:p:${pageSafe-1}`});
    if(pageSafe<total-1) nav.push({text:'➡️ Berikutnya',callback_data:`adm_sem:${groupKey}:p:${pageSafe+1}`});
    if(nav.length) rows.push(nav);
    rows.push([{text:'🏠 Menu Utama',callback_data:'nav:main'}]);
    return rows;
}

function buildSemanticEntityMenu(groupKey,entity) {
    const group=ADMIN_MENU_GROUPS[groupKey];
    if(!group) return [[{text:'🔙 Kembali',callback_data:`adm_menu_${groupKey}`}]];
    const commands=group.commands.filter(c=>semanticCommandParts(c).entity===entity);
    const seen=new Set(), actions=[];
    for(const command of commands){
        const label=semanticActionLabel(command);
        const key=`${label}|${command}`;
        if(seen.has(key)) continue;
        seen.add(key); actions.push({label,command});
    }
    const rows=[];
    for(let i=0;i<actions.length;i+=2){
        rows.push(actions.slice(i,i+2).map(({label,command})=>({
            text:normalizeButtonLabel(label),
            callback_data:`adm_sem:${groupKey}:a:${encodeURIComponent(command)}`
        })));
    }
    rows.push([{text:'🔙 Kembali',callback_data:`adm_sem:${groupKey}:p:0`}]);
    return rows;
}

function buildAdminFunctionMenu(groupKey,page=0){
    const group=ADMIN_MENU_GROUPS[groupKey];
    if(!group)return [];
    const size=12;
    const total=Math.max(1,Math.ceil(group.commands.length/size));
    const p=Math.min(Math.max(0,Number(page)||0),total-1);
    const slice=group.commands.slice(p*size,(p+1)*size);
    const rows=[];
    for(let i=0;i<slice.length;i+=2){
        rows.push(slice.slice(i,i+2).map(cmd=>({text:shortCommandLabel(cmd),callback_data:`adm_cmd_${cmd}`})));
    }
    const nav=[];
    if(p>0)nav.push({text:'⬅️ Sebelum',callback_data:`adm_menu_${groupKey}_p${p-1}`});
    if(p<total-1)nav.push({text:'➡️ Lanjut',callback_data:`adm_menu_${groupKey}_p${p+1}`});
    if(nav.length)rows.push(nav);
    rows.push([{text:'📖 Panduan',callback_data:`adm_guide_${groupKey}_p0`}]);
    rows.push([{text:'🔙 Kembali',callback_data:'nav:main'}]);
    return rows;
}

