// ============================================================
// LEGACY MENU ADAPTER
// Semua menu entitas lama diarahkan ke Generic Entity Engine.
// Fungsi cmd_* lama tetap dipertahankan untuk backward compatibility
// command/flow lama, tetapi tidak lagi menjadi menu utama.
// ============================================================
function buildUnifiedEntityMenu(entity) {
    const config = getEntityConfig(entity);
    if (!config) return [[{ text: '🔙 Kembali', callback_data: 'menu_back' }]];
    const next = getNextEntityCallback(entity);
    const keyboard = [
        [{ text: '📋 Lihat', callback_data: `ent_list_${entity}` }, { text: '➕ Tambah', callback_data: `ent_add_${entity}` }],
        [{ text: '✏️ Ubah', callback_data: `ent_edit_${entity}` }, { text: '🗑️ Hapus', callback_data: `ent_delete_${entity}` }]
    ];
    if (entity === 'soal') {
        keyboard.push([{ text: '🔄 Urutkan', callback_data: `ent_reorder_${entity}` }, { text: '📤 Data', callback_data: 'adm_menu_data' }]);
        keyboard.push([{ text: '📋 Review', callback_data: 'menu_review' }, { text: '🔙 Kembali', callback_data: 'menu_back' }]);
        return keyboard;
    } else if (next) {
        keyboard.push([{ text: '🔄 Urutkan', callback_data: `ent_reorder_${entity}` }, { text: '➡️ Lanjut', callback_data: next }]);
    } else {
        keyboard.push([{ text: '🔄 Urutkan', callback_data: `ent_reorder_${entity}` }, { text: '🔙 Kembali', callback_data: 'menu_back' }]);
        return keyboard;
    }
    keyboard.push([{ text: '🔙 Kembali', callback_data: 'menu_back' }]);
    return keyboard;
}

