// ============================================================
// 🆕 PATCH 3: UI PEMILIHAN TAHAP
// Lokasi: Setelah buildAIMenu()
// ============================================================

// ============================================================
// 1. FORMAT DAFTAR TAHAP
// ============================================================
function formatTahapList(selectedTahap, showSkipped = false) {
    if (!selectedTahap || selectedTahap.length === 0) {
        return '_Belum ada tahap dipilih_';
    }
    
    const lines = selectedTahap.map(kode => {
        const t = TAHAP_PEMBELAJARAN[kode];
        if (!t) return '';
        return `   ${t.icon} *${kode}* — ${t.nama}`;
    }).filter(Boolean);
    
    return lines.join('\n');
}

// ============================================================
// 2. GET SKIPPED TAHAP
// ============================================================
function getSkippedTahap(selectedTahap) {
    const allTahap = ['T1', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'T8', 'T9'];
    return allTahap.filter(t => !selectedTahap.includes(t));
}

// ============================================================
// 3. CEK DEPENDENSI
// ============================================================
function checkDependencies(selectedTahap) {
    const missing = [];
    
    for (const tahapKode of selectedTahap) {
        const deps = TAHAP_DEPENDENCIES[tahapKode] || [];
        for (const dep of deps) {
            if (!selectedTahap.includes(dep)) {
                missing.push({
                    needed: tahapKode,
                    required: dep,
                    nama_needed: TAHAP_PEMBELAJARAN[tahapKode]?.nama || tahapKode,
                    nama_required: TAHAP_PEMBELAJARAN[dep]?.nama || dep
                });
            }
        }
    }
    
    return missing;
}

// ============================================================
// 4. BUILD MENU TOGGLE TAHAP
// ============================================================
function buildTahapSelectionMenu(selectedTahap = [], skippedReasons = {}) {
    const keyboard = [];
    const tahapList = ['T1', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'T8', 'T9'];
    
    // 3 baris × 3 kolom
    for (let i = 0; i < tahapList.length; i += 3) {
        const row = [];
        for (let j = i; j < i + 3 && j < tahapList.length; j++) {
            const kode = tahapList[j];
            const tahap = TAHAP_PEMBELAJARAN[kode];
            const isSelected = selectedTahap.includes(kode);
            
            row.push({
                text: `${isSelected ? '✅' : '⬜'} ${tahap.icon} ${kode}`,
                callback_data: `tahap_toggle_${kode}`
            });
        }
        keyboard.push(row);
    }
    
    // Tombol aksi
    keyboard.push([
        { text: "✅ Pilih Semua", callback_data: "tahap_select_all" },
        { text: "❌ Kosongkan", callback_data: "tahap_clear_all" }
    ]);
    
    // Tombol skip with reason (jika ada yang kosong)
    const skipped = getSkippedTahap(selectedTahap);
    if (skipped.length > 0 && skipped.length < 9) {
        keyboard.push([
            { text: `⏭️ Alasan Skip (${skipped.length})`, callback_data: "tahap_skip_reason" }
        ]);
    }
    
    // Tombol lanjut
    const lanjutText = selectedTahap.length > 0 
        ? `📝 Lanjut (${selectedTahap.length} tahap)` 
        : `📝 Lanjut (pilih minimal 1)`;
    
    keyboard.push([
        { text: lanjutText, callback_data: "tahap_confirm" }
    ]);
    
    keyboard.push([
        { text: "🔙 Kembali ke Menu AI", callback_data: "ai_menu" }
    ]);
    
    return keyboard;
}

// ============================================================
// 5. BUILD MENU PRESET
// ============================================================
function buildPresetMenu() {
    const keyboard = [];
    
    for (const [key, preset] of Object.entries(TAHAP_PRESETS)) {
        keyboard.push([
            { text: preset.label, callback_data: `tahap_preset_${key}` }
        ]);
    }
    
    keyboard.push([
        { text: "🎨 Custom (Pilih Manual)", callback_data: "tahap_custom" }
    ]);
    
    keyboard.push([
        { text: "🔙 Kembali", callback_data: "ai_menu" }
    ]);
    
    return keyboard;
}

// ============================================================
// 6. BUILD PESAN SELEKSI TAHAP
// ============================================================
function buildTahapSelectionMessage(selectedTahap, skippedReasons = {}) {
    const totalTahap = selectedTahap.length;
    const skipped = getSkippedTahap(selectedTahap);
    
    let msg = `📚 *PILIH TAHAP PEMBELAJARAN*\n\n`;
    msg += `Pilih tahap yang ingin disertakan dalam materi.\n`;
    msg += `Anda bisa memilih **beberapa** atau **semua**.\n\n`;
    
    msg += `📌 *Tahap Dipilih (${totalTahap}/9):*\n`;
    msg += formatTahapList(selectedTahap);
    msg += `\n\n`;
    
    if (skipped.length > 0 && skipped.length < 9) {
        msg += `⏭️ *Tahap Dilewati (${skipped.length}):*\n`;
        msg += skipped.map(k => {
            const t = TAHAP_PEMBELAJARAN[k];
            const reason = skippedReasons[k];
            const reasonText = reason ? ` _(${reason})_` : '';
            return `   ⬜ ${t.icon} ${k} — ${t.nama}${reasonText}`;
        }).join('\n');
        msg += `\n\n`;
    }
    
    msg += `💡 *Tips:*\n`;
    msg += `• Klik tahap untuk toggle pilih/lepas\n`;
    msg += `• Gunakan "Pilih Semua" untuk 9 tahap\n`;
    msg += `• "Alasan Skip" untuk catat alasan\n`;
    
    return msg;
}

// ============================================================
// 7. BUILD KONFIRMASI SEBELUM GENERATE
// ============================================================
function buildTahapConfirmMessage(selectedTahap, skippedReasons = {}, context = {}) {
    const skipped = getSkippedTahap(selectedTahap);
    const dependencies = checkDependencies(selectedTahap);
    
    let msg = `✅ *KONFIRMASI PILIHAN TAHAP*\n\n`;
    
    // Info topik
    if (context.topik) {
        msg += `📖 *Topik:* ${context.topik}\n`;
        if (context.subtopik) msg += `📋 *Sub-Topik:* ${context.subtopik}\n`;
        if (context.kisi) msg += `📌 *Kisi-Kisi:* ${context.kisi}\n`;
        msg += `\n`;
    }
    
    // Tahap dipilih
    msg += `📌 *Tahap Dipilih (${selectedTahap.length}):*\n`;
    msg += formatTahapList(selectedTahap);
    msg += `\n\n`;
    
    // Tahap dilewati
    if (skipped.length > 0) {
        msg += `⏭️ *Tahap Dilewati (${skipped.length}):*\n`;
        msg += skipped.map(k => {
            const t = TAHAP_PEMBELAJARAN[k];
            const reason = skippedReasons[k];
            return `   ⬜ ${t.icon} ${k} — ${t.nama}${reason ? ` _(${reason})_` : ''}`;
        }).join('\n');
        msg += `\n\n`;
    }
    
    // Peringatan dependensi
    if (dependencies.length > 0) {
        msg += `⚠️ *PERINGATAN DEPENDENSI:*\n`;
        const uniqueMissing = [...new Set(dependencies.map(d => d.required))];
        for (const dep of uniqueMissing) {
            const t = TAHAP_PEMBELAJARAN[dep];
            msg += `   ❌ ${t.icon} ${dep} — ${t.nama}\n`;
        }
        msg += `\n💡 Tahap ini tidak dipilih, tapi dibutuhkan oleh tahap lain.\n`;
        msg += `💡 Materi tetap bisa digenerate, namun mungkin kurang lengkap.\n\n`;
    }
    
    msg += `⚠️ *Lanjutkan generate materi?*`;
    
    return msg;
}

