function buildSkipReasonMenu(tahapKode) {
    return [
        [{ text: "🔹 Tidak Relevan dengan Topik", callback_data: `skip_reason_${tahapKode}_tidak_relevan` }],
        [{ text: "🔹 Sudah Dikuasai Siswa", callback_data: `skip_reason_${tahapKode}_sudah_dikuasai` }],
        [{ text: "🔹 Akan Dibuat Manual", callback_data: `skip_reason_${tahapKode}_buat_manual` }],
        [{ text: "🔹 Materi Terlalu Panjang", callback_data: `skip_reason_${tahapKode}_terlalu_panjang` }],
        [{ text: "🔹 Alasan Lain", callback_data: `skip_reason_${tahapKode}_lainnya` }],
        [{ text: "✅ Tanpa Alasan", callback_data: `skip_reason_${tahapKode}_tanpa_alasan` }],
        [{ text: "🔙 Kembali", callback_data: "tahap_skip_reason" }]
    ];
}

// =========================
// CALL SPECIFIC AI - DENGAN TIMEOUT DAN MAX TOKENS
// =========================

async function callSpecificAI(provider, model, apiKey, prompt, maxTokens = 4096, externalSignal = null) {
    if (!apiKey || apiKey === '') {
        throw new Error(`API key untuk ${provider} tidak tersedia`);
    }

    let url, headers, body;

    switch (provider) {
        // ============ GEMINI ============
        case 'gemini':
            url = `https://generativelanguage.googleapis.com/v1beta/models/${model || 'gemini-1.5-flash'}:generateContent?key=${apiKey}`;
            body = { 
                contents: [{ parts: [{ text: prompt }] }],
                generationConfig: {
                    maxOutputTokens: maxTokens,
                    temperature: 0.7
                }
            };
            headers = { 'Content-Type': 'application/json' };
            break;

        // ============ GROQ (TERCEPAT) ============
        case 'groq':
            url = 'https://api.groq.com/openai/v1/chat/completions';
            body = {
                model: model || 'llama-3.1-70b-versatile',
                messages: [{ role: 'user', content: prompt }],
                temperature: 0.7,
                max_tokens: maxTokens
            };
            headers = {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            };
            break;

        // ============ MISTRAL ============
        case 'mistral':
            url = 'https://api.mistral.ai/v1/chat/completions';
            body = {
                model: model || 'mistral-large-latest',
                messages: [{ role: 'user', content: prompt }],
                temperature: 0.7,
                max_tokens: maxTokens
            };
            headers = {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            };
            break;

        // ============ COHERE ============
        case 'cohere':
            url = 'https://api.cohere.ai/v1/generate';
            body = {
                model: model || 'command-r-plus',
                prompt: prompt,
                max_tokens: maxTokens,
                temperature: 0.7
            };
            headers = {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            };
            break;

        // ============ CLOUDFLARE ============
        case 'cloudflare':
            const accountId = getCredentialHub().cloudflare.accountId || 'your_account_id';
            url = `https://api.cloudflare.com/client/v4/accounts/${accountId}/ai/run/${model || '@cf/meta/llama-3.1-8b-instruct'}`;
            body = { 
                messages: [{ role: 'user', content: prompt }],
                max_tokens: maxTokens
            };
            headers = {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            };
            break;

        // ============ OPENROUTER ============
        case 'openrouter':
            url = 'https://openrouter.ai/api/v1/chat/completions';
            body = {
                model: model || 'meta-llama/llama-3.1-8b-instruct',
                messages: [{ role: 'user', content: prompt }],
                temperature: 0.7,
                max_tokens: maxTokens
            };
            headers = {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`,
                'HTTP-Referer': 'https://your-bot.com',
                'X-Title': 'Bot Pembelajaran'
            };
            break;

        // ============ SAMBANOVA ============
        case 'sambanova':
            url = 'https://api.sambanova.ai/v1/chat/completions';
            body = {
                model: model || 'Meta-Llama-3.1-70B-Instruct',
                messages: [{ role: 'user', content: prompt }],
                temperature: 0.7,
                max_tokens: maxTokens
            };
            headers = {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            };
            break;

        // ============ CEREBRAS ============
        case 'cerebras':
            url = 'https://api.cerebras.ai/v1/chat/completions';
            body = {
                model: model || 'llama3.1-70b',
                messages: [{ role: 'user', content: prompt }],
                temperature: 0.7,
                max_tokens: maxTokens
            };
            headers = {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            };
            break;

        // ============ CHUTES ============
        case 'chutes':
            url = 'https://api.chutes.ai/v1/chat/completions';
            body = {
                model: model || 'chutes-1',
                messages: [{ role: 'user', content: prompt }],
                temperature: 0.7,
                max_tokens: maxTokens
            };
            headers = {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            };
            break;

        // ============ SILICONFLOW ============
        case 'siliconflow':
            url = 'https://api.siliconflow.ai/v1/chat/completions';
            body = {
                model: model || 'siliconflow-1',
                messages: [{ role: 'user', content: prompt }],
                temperature: 0.7,
                max_tokens: maxTokens
            };
            headers = {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${apiKey}`
            };
            break;

        default:
            throw new Error(`Provider ${provider} tidak dikenal atau tidak ada API key`);
    }

    // ===== PERBAIKAN: TIMEOUT UNTUK REQUEST =====
    const controller = externalSignal ? null : new AbortController();
    const timeoutId = externalSignal ? null : setTimeout(() => controller.abort(), 60000); // 60 detik timeout

    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: headers,
            body: JSON.stringify(body),
            signal: externalSignal || controller.signal
        });

        if (timeoutId) clearTimeout(timeoutId);

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(`HTTP ${response.status}: ${errorText}`);
        }

        const data = await response.json();
        const result = extractAIResponse(provider, data);
        
        if (!result) {
            throw new Error('Tidak ada response dari AI');
        }

        return result;
    } catch (error) {
        if (timeoutId) clearTimeout(timeoutId);
        if (error.name === 'AbortError') {
            throw new Error(`Timeout: ${provider} tidak merespon dalam 60 detik`);
        }
        throw error;
    }
}

function getModel(provider) {
    return AI_CONFIG.models[provider] || AI_CONFIG.models.gemini;
}

function getApiKey(provider, env = null) {
    const key = String(provider || '').trim().toLowerCase();
    return String(getCredentialHub(env).ai[key] || '').trim();
}

function getMaxTokens(taskType) {
    return AI_CONFIG.maxTokens[taskType] || AI_CONFIG.maxTokens.default || 4096;
}

// =========================
// CALL PARALLEL RACE - DENGAN RACE CONDITION (TERCEPAT MENANG)
// =========================

async function callParallelRace(prompt, providers, taskType = 'default', env = null) {
    const maxTokens = getMaxTokens(taskType);
    const controller = new AbortController();
    
    // ===== PERBAIKAN: GUNAKAN Promise.race untuk kecepatan =====
    const raceResult = new Promise((resolve, reject) => {
        let remaining = providers.length;
        const errors = [];

        if (remaining === 0) {
            reject(new Error('Tidak ada provider parallel yang dikonfigurasi'));
            return;
        }

        for (const provider of providers) {
            (async () => {
                try {
                    const apiKey = getApiKey(provider, env);
                    if (!apiKey || apiKey === '') {
                        throw new Error('No API key');
                    }

                    const startTime = Date.now();
                    const result = await callSpecificAI(
                        provider,
                        getModel(provider),
                        apiKey,
                        prompt,
                        maxTokens,
                        controller.signal
                    );
                    const endTime = Date.now();

                    if (!result || result.length <= 50) {
                        throw new Error('Response terlalu pendek');
                    }

                    resolve({
                        provider,
                        success: true,
                        response: result,
                        time: endTime - startTime,
                        wordCount: result.split(/\s+/).length
                    });
                } catch (e) {
                    errors.push({ provider, error: e.message });
                    remaining -= 1;
                    if (remaining === 0) {
                        reject(new Error(`Semua provider parallel gagal: ${errors.map(e => `${e.provider}: ${e.error}`).join(' | ')}`));
                    }
                }
            })();
        }
    });

    try {
        // ===== PERBAIKAN : RACE SEBENARNYA - SUKSES PERTAMA MENANG =====
        const result = await Promise.race([
            raceResult,
            new Promise((_, reject) =>
                setTimeout(() => reject(new Error('Parallel timeout')), 30000)
            )
        ]);

        controller.abort();
        console.log(`⚡ AI tercepat: ${result.provider} (${result.time}ms, ${result.wordCount} kata)`);
        return result;
    } catch (e) {
        controller.abort();
        return { success: false, error: e.message };
    }
}

// =========================
// CALL SERIAL FALLBACK - DENGAN CACHE DAN PRIORITAS
// =========================

// ===== PERBAIKAN : CACHE UNTUK RESPONSE AI =====
const aiResponseCache = new Map();

async function callSerialFallback(prompt, taskType = 'default', env = null) {
    const maxTokens = getMaxTokens(taskType);
    const providers = HYBRID_CONFIG.serialFallback || [];
    
    // ===== PERBAIKAN : CEK CACHE DULU =====
    const cacheKey = JSON.stringify({
        taskType: String(taskType || 'default'),
        prompt: String(prompt || ''),
        maxTokens,
        providers: providers.map((provider) => ({
            provider: String(provider || ''),
            model: String(getModel(provider) || '')
        }))
    });
    if (aiResponseCache.has(cacheKey)) {
        const cached = aiResponseCache.get(cacheKey);
        if (Date.now() - cached.timestamp < 300000) { // 5 menit cache
            console.log('✅ Menggunakan cache AI');
            return cached.data;
        }
    }
    
    for (const provider of providers) {
        try {
            const apiKey = getApiKey(provider, env);
            if (!apiKey || apiKey === '') continue;

            const startTime = Date.now();
            const result = await callSpecificAI(
                provider,
                getModel(provider),
                apiKey,
                prompt,
                maxTokens
            );
            const endTime = Date.now();
            
            if (result && result.length > 50) {
                const response = { 
                    success: true, 
                    provider, 
                    response: result,
                    time: endTime - startTime
                };
                
                // Simpan cache
                aiResponseCache.set(cacheKey, {
                    timestamp: Date.now(),
                    data: response
                });
                
                // Hapus cache lama (max 50)
                if (aiResponseCache.size > 50) {
                    const oldest = [...aiResponseCache.entries()].sort((a, b) => a[1].timestamp - b[1].timestamp)[0];
                    aiResponseCache.delete(oldest[0]);
                }
                
                return response;
            }
        } catch (e) {
            console.log(`${provider} fallback error:`, e.message);
        }
    }
    
    return { success: false };
}

// =========================
// CALL AI EMERGENCY
// =========================

async function callAIEmergency(prompt, env = null) {
    const emergencyProviders = ['openrouter', 'together', 'huggingface'];
    
    for (const provider of emergencyProviders) {
        try {
            const apiKey = getApiKey(provider, env);
            if (!apiKey || apiKey === '') continue;

            const result = await callSpecificAI(
                provider,
                getModel(provider),
                apiKey,
                prompt
            );
            
            if (result && result.length > 20) {
                return { success: true, provider, response: result };
            }
        } catch (e) {
            console.log(`Emergency ${provider}:`, e.message);
        }
    }
    
    return { success: false };
}

// ============================================================
// CALL AI HYBRID - DITINGKATKAN
// ============================================================

async function callAIHybrid(prompt, taskType = 'default', env = null) {
    
	// ===== PERBAIKAN: DAPATKAN PROVIDER UNTUK TASK =====
    const parallelProviders = HYBRID_CONFIG.parallelProviders[taskType] || 
                             HYBRID_CONFIG.parallelProviders.default;
    
    // ===== PERBAIKAN: COBA PARALLEL DULU =====
    console.log(`🚀 Memulai parallel dengan ${parallelProviders.length} provider untuk ${taskType}`);
    const parallelResult = await callParallelRace(prompt, parallelProviders, taskType, env);
    
    if (parallelResult.success) {
        console.log(`✅ Parallel success: ${parallelResult.provider} (${parallelResult.time}ms)`);
        return {
            success: true,
            provider: parallelResult.provider,
            response: parallelResult.response,
            method: 'parallel',
            time: parallelResult.time
        };
    }

    // ===== PERBAIKAN: FALLBACK SERIAL =====
    console.log(`🔄 Parallel gagal, mencoba serial fallback...`);
    const serialResult = await callSerialFallback(prompt, taskType, env);
    
    if (serialResult.success) {
        console.log(`✅ Serial success: ${serialResult.provider} (${serialResult.time}ms)`);
        return {
            success: true,
            provider: serialResult.provider,
            response: serialResult.response,
            method: 'serial',
            time: serialResult.time
        };
    }

    // ===== PERBAIKAN: EMERGENCY =====
    console.log(`⚠️ Serial gagal, mencoba emergency...`);
    const emergencyResult = await callAIEmergency(prompt, env);
    
    if (emergencyResult.success) {
        console.log(`✅ Emergency success: ${emergencyResult.provider}`);
        return {
            success: true,
            provider: emergencyResult.provider,
            response: emergencyResult.response,
            method: 'emergency'
        };
    }

    console.log(`❌ Semua AI gagal`);
    return {
        success: false,
        error: 'Semua AI gagal'
    };
}

// ============================================================
// CALL AI WITH TIMEOUT
// ============================================================
async function callAIWithTimeout(provider, apiKey, model, prompt, timeout) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout);

    try {
        // Teruskan AbortSignal ke request AI agar timeout benar-benar membatalkan fetch.
        return await callSpecificAI(provider, model, apiKey, prompt, 4096, controller.signal);
    } finally {
        clearTimeout(timer);
    }
}








