// ============================================================
// 🆕 AUTO-MIGRATE TABLE - SINKRONISASI SCHEMA JS → SQL
// Lokasi: Sebelum initDatabase()
// ============================================================

/**
 * Auto-migrate tabel dari schema JS
 * 
 * Cara kerja:
 * 1. Cek apakah tabel ada
 *    - Kalau tidak ada → CREATE TABLE dari schema
 *    - Kalau ada → cek kolom satu per satu
 * 2. Cek setiap kolom di schema
 *    - Kalau kolom tidak ada di SQL → ALTER TABLE ADD COLUMN
 * 3. Log hasil
 */
async function autoMigrateTable(db, tableName, schema) {
    try {
        console.log(`🔧 Auto-migrate: ${tableName}...`);
        
        // ============================================================
        // STEP 1: Cek apakah tabel ada
        // ============================================================
        const tableExists = await db.prepare(`
            SELECT name FROM sqlite_master 
            WHERE type='table' AND name=?
        `).bind(tableName).first();
        
        if (!tableExists) {
            // ========== BUAT TABEL BARU ==========
            const columns = Object.entries(schema)
                .map(([name, type]) => `"${name}" ${type}`)
                .join(', ');
            
            await db.prepare(`CREATE TABLE "${tableName}" (${columns})`).run();
            
            console.log(`   ✅ Tabel ${tableName} dibuat (${Object.keys(schema).length} kolom)`);
            return { success: true, action: 'created', columns: Object.keys(schema).length };
        }
        
        // ============================================================
        // STEP 2: Tabel sudah ada → cek kolom
        // ============================================================
        const tableInfo = await db.prepare(`PRAGMA table_info("${tableName}")`).all();
        const existingCols = (tableInfo.results || []).map(c => c.name);
        
        let addedCount = 0;
        let skippedCount = 0;
        let failedCount = 0;
        const addedColumns = [];
        const failedColumns = [];
        
        for (const [colName, colType] of Object.entries(schema)) {
            if (existingCols.includes(colName)) {
                skippedCount++;
                continue;
            }
            
            // Kolom belum ada → tambahkan
            try {
                await db.prepare(
                    `ALTER TABLE "${tableName}" ADD COLUMN "${colName}" ${colType}`
                ).run();
                
                addedCount++;
                addedColumns.push(colName);
                console.log(`   ✅ Kolom "${colName}" ditambahkan`);
            } catch (e) {
                failedCount++;
                failedColumns.push({ name: colName, error: e.message });
                console.warn(`   ⚠️ Gagal tambah "${colName}": ${e.message}`);
            }
        }
        
        // ============================================================
        // STEP 3: Log hasil
        // ============================================================
        if (addedCount > 0) {
            console.log(`✅ Migrate ${tableName}: ${addedCount} kolom baru ditambahkan`);
        } else {
            console.log(`✅ Tabel ${tableName} sudah up-to-date (${existingCols.length} kolom)`);
        }
        
        return {
            success: failedCount === 0,
            action: addedCount > 0 ? 'migrated' : 'up-to-date',
            existingColumns: existingCols.length,
            addedCount,
            skippedCount,
            failedCount,
            addedColumns,
            failedColumns
        };
        
    } catch (e) {
        console.error(`❌ Auto-migrate ${tableName} error:`, e);
        return { success: false, error: e.message };
    }
}

/**
 * Auto-migrate semua tabel dari ALL_SCHEMAS
 */
async function autoMigrateAllTables(db) {
    try {
        console.log('🔧 Auto-migrate semua tabel...');
        
        const results = {};
        let totalAdded = 0;
        let totalFailed = 0;
        
        for (const [tableName, schema] of Object.entries(ALL_SCHEMAS)) {
            const result = await autoMigrateTable(db, tableName, schema);
            results[tableName] = result;
            
            if (result.addedCount) totalAdded += result.addedCount;
            if (result.failedCount) totalFailed += result.failedCount;
        }
        
        console.log(`\n📊 Auto-migrate selesai:`);
        console.log(`   Total kolom ditambahkan: ${totalAdded}`);
        console.log(`   Total kolom gagal: ${totalFailed}`);
        
        return results;
        
    } catch (e) {
        console.error('❌ autoMigrateAllTables error:', e);
        return { error: e.message };
    }
}

/**
 * Get schema info untuk tabel tertentu
 */
async function getSchemaInfo(db, tableName) {
    try {
        const schema = ALL_SCHEMAS[tableName];
        if (!schema) {
            return { success: false, error: `Schema untuk ${tableName} tidak ditemukan` };
        }
        
        const tableInfo = await db.prepare(`PRAGMA table_info("${tableName}")`).all();
        const existingCols = (tableInfo.results || []).map(c => c.name);
        
        const schemaCols = Object.keys(schema);
        const missingCols = schemaCols.filter(c => !existingCols.includes(c));
        const extraCols = existingCols.filter(c => !schemaCols.includes(c));
        
        return {
            success: true,
            tableName,
            schemaColumns: schemaCols,
            existingColumns: existingCols,
            totalSchema: schemaCols.length,
            totalExisting: existingCols.length,
            missingColumns: missingCols,
            extraColumns: extraCols,
            isSync: missingCols.length === 0
        };
        
    } catch (e) {
        return { success: false, error: e.message };
    }
}

