// ============================================================
// GENERATE MATERI OUTLINE
// ============================================================
async function generateMateriOutline(topic, subtopic, kemampuan, format, env = null) {
    const prompt = `Buat outline materi tentang "${topic}"${subtopic ? ` subtopik ${subtopic}` : ''}${kemampuan ? ` untuk kemampuan ${kemampuan}` : ''}.

Format: 5 bagian utama dengan 3-5 sub-bagian per bagian.

Output:
1. [Judul Bagian 1]
   - [Sub-bagian 1.1]
   - [Sub-bagian 1.2]
2. [Judul Bagian 2]
   ...

Langsung output, tanpa kata pengantar.`;

    const result = await callAIHybrid(prompt, 'generate_materi', env);
    return result.success ? result.response : null;
}

// ============================================================
// PARSE OUTLINE MENJADI CHUNKS
// ============================================================
function parseMateriOutline(outline) {
    const chunks = [];
    const lines = outline.split('\n').filter(l => l.trim());
    
    let currentChunk = { title: '', subtopics: [] };
    let chunkIndex = 0;
    
    for (const line of lines) {
        const trimmed = line.trim();
        const mainMatch = trimmed.match(/^(\d+)[.)]\s*(.+)/);
        if (mainMatch) {
            if (currentChunk.title) {
                chunks.push({ ...currentChunk });
            }
            currentChunk = {
                title: mainMatch[2].trim(),
                subtopics: [],
                index: chunkIndex++
            };
            continue;
        }
        
        const subMatch = trimmed.match(/^[\s-]*[-•*]\s*(.+)/);
        if (subMatch && currentChunk.title) {
            currentChunk.subtopics.push(subMatch[1].trim());
        }
    }
    
    if (currentChunk.title) {
        chunks.push(currentChunk);
    }
    
    return chunks;
}

// ============================================================
// GENERATE CHUNK CONTENT
// ============================================================
async function generateChunkContent(topic, chunk, format, env = null) {
    const { title, subtopics, index } = chunk;
    
    const subtopicText = subtopics.length > 0 
        ? `\nSub-bagian:\n${subtopics.map(s => `- ${s}`).join('\n')}` 
        : '';
    
    const styleMap = {
        'ringkasan': 'ringkasan padat, 200-300 kata',
        'penjelasan': 'penjelasan detail dengan contoh, 400-500 kata',
        'peta_konsep': 'peta konsep hierarkis, 200-300 kata',
        'rangkuman': 'rangkuman lengkap, 300-400 kata',
        'contoh_soal': '5 contoh soal dengan pembahasan, 300-400 kata',
        'materi_lengkap': 'materi lengkap dengan teori dan contoh, 500-600 kata'
    };
    
    const prompt = `Buat ${styleMap[format] || styleMap['materi_lengkap']} untuk bagian "${title}"${subtopicText} dari materi "${topic}".

Gunakan Markdown. Edukatif dan mudah dipahami.
Langsung output, tanpa kata pengantar.`;

    try {
        const result = await callAIHybrid(prompt, 'generate_materi', env);
        if (result.success && result.response.length > 100) {
            return {
                index: index,
                title: title,
                content: result.response,
                provider: result.provider,
                success: true
            };
        }
        return { index, title, content: '', provider: '', success: false };
    } catch (e) {
        return { index, title, content: '', provider: '', success: false };
    }
}

// ============================================================
// GENERATE ALL CHUNKS
// ============================================================
async function generateAllChunksUniversal(topic, chunks, format, env = null) {
    const results = [];
    const batchSize = UNIVERSAL_CONFIG.parallelChunks || 3;
    
    for (let i = 0; i < chunks.length; i += batchSize) {
        const batch = chunks.slice(i, i + batchSize);
        const batchPromises = batch.map(chunk => generateChunkContent(topic, chunk, format, env));
        const batchResults = await Promise.all(batchPromises);
        results.push(...batchResults);
    }
    
    results.sort((a, b) => a.index - b.index);
    
    return {
        chunks: results,
        successCount: results.filter(r => r.success).length
    };
}

// ============================================================
// GENERATE MATERI UNIVERSAL
// ============================================================
async function generateMateriUniversal(topic, subtopic, kemampuan, format, pages = 1, env = null) {
    const startTime = Date.now();
    const cacheKey = getUniversalCacheKey(
        'materi',
        topic,
        subtopic,
        kemampuan,
        format,
        pages
    );
    
    const cached = getCachedUniversal(cacheKey);
    if (cached) {
        return {
            success: true,
            content: cached,
            method: 'cache',
            elapsed: 0.5
        };
    }

    let fullContent = '';
    let providers = [];
    let method = '';
    
    if (pages <= 1) {
        const result = await generateSingleMateri(topic, subtopic, kemampuan, format, env);
        if (result.success) {
            fullContent = result.content;
            providers.push(result.provider);
            method = 'direct';
        }
    } else {
        const outline = await generateMateriOutline(topic, subtopic, kemampuan, format, env);
        if (!outline) {
            return { success: false, error: 'Gagal generate outline' };
        }
        
        const chunks = parseMateriOutline(outline);
        const numChunks = Math.min(chunks.length, pages);
        const selectedChunks = chunks.slice(0, numChunks);
        
        const chunkResults = await generateAllChunksUniversal(topic, selectedChunks, format, env);
        
        let content = `# 📚 MATERI: ${topic}\n\n`;
        content += `## 📖 Pendahuluan\n\nMateri ini membahas tentang **${topic}**${subtopic ? ` dengan fokus pada **${subtopic}**` : ''}.\n\n---\n\n`;
        
        for (const chunk of chunkResults.chunks) {
            if (chunk.success && chunk.content) {
                content += `## ${chunk.title}\n\n${chunk.content}\n\n---\n\n`;
            }
        }
        
        content += `## 📝 Kesimpulan\n\nMateri ini mencakup ${chunkResults.successCount} bagian utama tentang **${topic}**.\n`;
        
        fullContent = content;
        providers = [...new Set(chunkResults.chunks.map(c => c.provider).filter(Boolean))];
        method = 'parallel_chunks';
    }
    
    if (!fullContent) {
        return { success: false, error: 'Gagal generate materi' };
    }
    
    setCachedUniversal(cacheKey, fullContent);
    
    const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
    
    return {
        success: true,
        content: fullContent,
        provider: providers.join(' + '),
        method: method,
        elapsed: elapsed
    };
}

// ============================================================
// GENERATE SINGLE MATERI
// ============================================================
async function generateSingleMateri(topic, subtopic, kemampuan, format, env = null) {
    const formatMap = {
        'ringkasan': 'ringkasan padat, 200-300 kata',
        'penjelasan': 'penjelasan detail dengan contoh, 300-400 kata',
        'peta_konsep': 'peta konsep hierarkis, 200-300 kata',
        'rangkuman': 'rangkuman lengkap, 300-400 kata',
        'contoh_soal': '5 contoh soal dengan pembahasan, 300-400 kata',
        'materi_lengkap': 'materi lengkap dengan teori dan contoh, 400-500 kata'
    };
    
    const prompt = `Buat ${formatMap[format] || formatMap['materi_lengkap']} tentang "${topic}"${subtopic ? ` subtopik ${subtopic}` : ''}${kemampuan ? ` untuk kemampuan ${kemampuan}` : ''}.

Gunakan Markdown. Edukatif dan mudah dipahami.`;

    const providers = UNIVERSAL_CONFIG.providers.materi || ['gemini', 'groq'];
    const timeout = UNIVERSAL_CONFIG.timeout.materi || 15000;
    
    const promises = providers.map(async (provider) => {
        try {
            const apiKey = getApiKey(provider, env);
            if (!apiKey) return { provider, success: false };
            
            const result = await callAIWithTimeout(provider, apiKey, getModel(provider), prompt, timeout);
            if (result && result.length > 100) {
                return { provider, success: true, content: result };
            }
            return { provider, success: false };
        } catch (e) {
            return { provider, success: false };
        }
    });
    
    try {
        const raceResult = await Promise.race(
            promises.map(p => p.then(
                r => r.success ? r : null,
                () => null
            ))
        );
        if (raceResult) {
            return { success: true, content: raceResult.content, provider: raceResult.provider };
        }
    } catch (e) {}
    
    const results = await Promise.all(promises);
    const success = results.find(r => r.success);
    if (success) {
        return { success: true, content: success.content, provider: success.provider };
    }
    
    return { success: false };
}

// ============================================================
// GENERATE PEMBAHASAN UNIVERSAL
// ============================================================
async function generatePembahasanUniversal(soalList, env = null) {
    if (!soalList || soalList.length === 0) {
        return { success: false, error: 'Tidak ada soal' };
    }
    
    const startTime = Date.now();
    let providers = [];
    let method = 'direct';
    let updatedSoalList = [];
    
    for (const soal of soalList) {
        try {
            if (!soal.soal || !soal.jawaban) {
                updatedSoalList.push({
                    ...soal,
                    pembahasan: 'Pembahasan tidak tersedia (soal tidak valid)'
                });
                continue;
            }
            
            // BUILD PROMPT
            const prompt = buildGeneratePembahasanPrompt(
                soal.soal,
                soal.jawaban,
                soal.pilihan_a || '',
                soal.pilihan_b || '',
                soal.pilihan_c || '',
                soal.pilihan_d || '',
                soal.pilihan_e || ''
            );
            
            // CALL AI
            const result = await callAIHybrid(prompt, 'generate_pembahasan', env);
            
            if (result.success && result.response) {
                updatedSoalList.push({
                    ...soal,
                    pembahasan: result.response
                });
                if (result.provider) providers.push(result.provider);
            } else {
                updatedSoalList.push({
                    ...soal,
                    pembahasan: 'Pembahasan tidak tersedia (gagal generate)'
                });
            }
        } catch (e) {
            updatedSoalList.push({
                ...soal,
                pembahasan: `Error: ${e.message}`
            });
        }
    }
    
    const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
    
    return {
        success: true,
        soalList: updatedSoalList,
        provider: [...new Set(providers)].join(' + ') || 'None',
        method: method,
        elapsed: elapsed
    };
}


// ============================================================
// SEND INLINE KEYBOARD DENGAN FALLBACK - PERBAIKAN
// ============================================================

async function sendInlineKeyboardRaw(chatId, text, inlineKeyboard, parseMode = "Markdown") {
    try {
        // Raw/fallback juga wajib melewati kontrak UI global agar jalur lama
        // tidak bisa mengirim label >20 karakter atau callback_data >64 byte.
        inlineKeyboard = normalizeInlineKeyboard(inlineKeyboard);
        for (const row of (inlineKeyboard || [])) {
            for (const btn of (row || [])) {
                if (btn?.callback_data && new TextEncoder().encode(String(btn.callback_data)).length > 64) {
                    console.error(`❌ callback_data >64 byte terdeteksi: ${String(btn.callback_data).slice(0,120)}`);
                    throw new Error('callback_data melebihi batas Telegram 64 byte');
                }
            }
        }
        // Jika text terlalu panjang, potong
        if (text && text.length > 4000) {
            const parts = text.match(/.{1,4000}/g) || [];
            for (let i = 0; i < parts.length; i++) {
                if (i === parts.length - 1) {
                    // Kirim bagian terakhir dengan keyboard
                    return await sendInlineKeyboardRaw(chatId, parts[i], inlineKeyboard, parseMode);
                } else {
                    // Kirim bagian tanpa keyboard
                    await sendMessage(chatId, parts[i], parseMode);
                }
            }
            return;
        }
        
        const payload = {
            chat_id: chatId,
            text: text,
            parse_mode: parseMode,
            reply_markup: { 
                inline_keyboard: inlineKeyboard 
            }
        };
        
        const response = await fetch(`https://api.telegram.org/bot${getTelegramToken()}/sendMessage`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });
        
        const result = await response.json();
        
        if (!result.ok) {
            // Jika error parse, kirim tanpa parse mode
            if (result.description && result.description.includes('parse')) {
                console.log('⚠️ Inline keyboard parse error, retrying without parse mode');
                console.log('❌ Error:', result.description);
                
                const fallbackPayload = {
                    chat_id: chatId,
                    text: text,
                    reply_markup: { 
                        inline_keyboard: inlineKeyboard 
                    }
                };
                
                const fallbackResponse = await fetch(`https://api.telegram.org/bot${getTelegramToken()}/sendMessage`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(fallbackPayload)
                });
                
                const fallbackResult = await fallbackResponse.json();
                if (!fallbackResult.ok) {
                    console.error("Error (fallback):", fallbackResult.description);
                    // Kirim tanpa keyboard
                    await sendMessage(chatId, text);
                }
                return fallbackResult;
            }
            
            console.error("Error:", result.description);
            return result;
        }
        
        return result;
    } catch (error) {
        console.error("Send inline keyboard error:", error);
        // Fallback: kirim tanpa keyboard
        try {
            await sendMessage(chatId, text);
        } catch (e) {
            console.error('Final fallback failed:', e);
        }
        return null;
    }
}

// ============================================================
// 🆕 SMARTSEND GENERIC RESPONSE LAYER
// Semua pemanggilan sendInlineKeyboard() otomatis melewati
// SmartSend. Gunakan sendInlineKeyboardRaw() hanya untuk
// internal fallback yang memang harus SEND baru.
// ============================================================
async function sendInlineKeyboard(chatId, text, inlineKeyboard, parseMode = "Markdown") {
    return await smartSend(chatId, text, inlineKeyboard, parseMode);
}

// ============================================================
// 🆕 EDIT INLINE KEYBOARD - UPDATE PESAN YANG SUDAH ADA
// Lokasi: Setelah sendInlineKeyboard(), sebelum answerCallback()
// ============================================================

async function editInlineKeyboard(chatId, messageId, text, inlineKeyboard, parseMode = "Markdown") {
    try {
        // Semua jalur edit langsung juga wajib mengikuti kontrak UI global.
        inlineKeyboard = normalizeInlineKeyboard(inlineKeyboard);
        for (const row of (inlineKeyboard || [])) {
            for (const btn of (row || [])) {
                if (btn?.callback_data && new TextEncoder().encode(String(btn.callback_data)).length > 64) {
                    console.error(`❌ callback_data >64 byte terdeteksi pada edit: ${String(btn.callback_data).slice(0,120)}`);
                    throw new Error('callback_data melebihi batas Telegram 64 byte');
                }
            }
        }
        // ============================================================
        // 🆕 TOGGLE CHECK: kalau GLOBAL OFF → fallback ke SEND
        // Ini supaya /toggle_edit berlaku untuk SEMUA handler
        // ============================================================
        if (typeof GLOBAL_USE_EDIT_INLINE !== 'undefined' && !GLOBAL_USE_EDIT_INLINE) {
            console.log('📤 [editInlineKeyboard] GLOBAL OFF → fallback SEND');
            return await sendInlineKeyboardRaw(chatId, text, inlineKeyboard, parseMode);
        }
        
        // ============================================================
        // VALIDASI INPUT
        // ============================================================
        if (!chatId) {
            console.error('❌ editInlineKeyboard: chatId kosong');
            return { ok: false, description: 'chatId tidak valid' };
        }
        
        if (!messageId) {
            console.error('❌ editInlineKeyboard: messageId kosong');
            return { ok: false, description: 'messageId tidak valid' };
        }
        
        if (!text) {
            console.warn('⚠️ editInlineKeyboard: text kosong, pakai placeholder');
            text = '_..._';
        }
        
        if (!inlineKeyboard || !Array.isArray(inlineKeyboard)) {
            console.warn('⚠️ editInlineKeyboard: inlineKeyboard tidak valid');
            inlineKeyboard = [];
        }

        // ============================================================
        // POTONG TEKS JIKA TERLALU PANJANG (MAX 4096)
        // ============================================================
        let finalText = text;
        if (finalText.length > 4096) {
            console.warn(`⚠️ editInlineKeyboard: text terlalu panjang (${finalText.length}), dipotong`);
            finalText = finalText.substring(0, 4093) + '...';
        }

        // ============================================================
        // BUILD PAYLOAD
        // ============================================================
        const payload = {
            chat_id: chatId,
            message_id: messageId,
            text: finalText,
            parse_mode: parseMode,
            reply_markup: {
                inline_keyboard: inlineKeyboard
            }
        };

        // ============================================================
        // KIRIM REQUEST KE TELEGRAM
        // ============================================================
        const response = await fetch(`https://api.telegram.org/bot${getTelegramToken()}/editMessageText`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });

        const result = await response.json();

        // ============================================================
        // HANDLE HASIL
        // ============================================================

        // ✅ SUKSES
        if (result.ok) {
            return result;
        }

        // ============================================================
        // 🆕 FALLBACK: message tidak bisa di-edit → SEND baru
        // Kasus: pesan dihapus, terlalu lama, atau tidak bisa di-edit
        // ============================================================
        if (result.description && 
            (result.description.includes('message to edit not found') ||
             result.description.includes("message can't be edited") ||
             result.description.includes('message identifier is not specified'))) {
            
            console.log('⚠️ [editInlineKeyboard] message tidak bisa di-edit → fallback SEND');
            console.log('   Alasan:', result.description);
            return await sendInlineKeyboardRaw(chatId, text, inlineKeyboard, parseMode);
        }

        // ⏭️ "message is not modified" → bukan error (isi sama persis)
        // Ini normal, contoh: user klik tombol yang sama 2x, tidak ada perubahan
        if (result.description && result.description.includes('message is not modified')) {
            return { ok: true, notModified: true };
        }

        // ⚠️ ERROR PARSE MARKDOWN → coba ulang TANPA parse_mode
        if (result.description && 
            (result.description.includes('parse') || 
             result.description.includes('entities') ||
             result.description.includes("can't parse"))) {
            
            console.warn('⚠️ editInlineKeyboard: Markdown parse error, retry tanpa parse_mode');
            console.warn('   Error detail:', result.description);
            
            const fallbackPayload = {
                chat_id: chatId,
                message_id: messageId,
                text: finalText,
                reply_markup: {
                    inline_keyboard: inlineKeyboard
                }
                // ⬅️ TANPA parse_mode
            };

            const fallbackResponse = await fetch(`https://api.telegram.org/bot${getTelegramToken()}/editMessageText`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(fallbackPayload)
            });

            const fallbackResult = await fallbackResponse.json();
            
            if (fallbackResult.ok) {
                console.log('✅ editInlineKeyboard: berhasil dengan fallback (tanpa parse_mode)');
            } else if (fallbackResult.description?.includes('message is not modified')) {
                return { ok: true, notModified: true };
            } else {
                console.error('❌ editInlineKeyboard fallback juga gagal:', fallbackResult.description);
            }
            
            return fallbackResult;
        }

        // ❌ ERROR LAIN (bukan parse, bukan not modified, bukan not found)
        console.error('❌ editInlineKeyboard error:', result.description);
        console.error('   Payload:', JSON.stringify({
            chatId,
            messageId,
            textLength: finalText.length,
            keyboardRows: inlineKeyboard.length
        }));

        return result;

    } catch (error) {
        // ============================================================
        // CATCH ERROR FATAL (network, timeout, dll)
        // ============================================================
        console.error('❌ editInlineKeyboard: FATAL ERROR');
        console.error('   Message:', error.message);
        console.error('   Stack:', error.stack);
        
        return { 
            ok: false, 
            description: error.message,
            fatal: true
        };
    }
}

// ============================================================
// 🆕 FASE 7: SEND OR EDIT DRILLDOWN
// Otomatis pilih edit atau send sesuai konteks
// ============================================================
function ensureHierarchyStepJumpButton(keyboard) {
    const rows = Array.isArray(keyboard)
        ? keyboard.map(row => Array.isArray(row) ? [...row] : [])
        : [];
    const hasCtxRoute = rows.flat().some(btn => String(btn?.callback_data || '').startsWith('ctx_'));
    const alreadyHasJump = rows.flat().some(btn => btn?.callback_data === 'ctx_jump_menu');
    if (hasCtxRoute && !alreadyHasJump) {
        rows.push([{ text: '🔷 Lompat Tahap', callback_data: 'ctx_jump_menu' }]);
    }
    return rows;
}

async function sendOrEditDrilldown(chatId, text, keyboard, parseMode = "Markdown", options = {}) {
    // Semua drilldown/pagination menggunakan satu pintu SmartSend Universal.
    // Jika dipanggil dari callback, messageId otomatis berasal dari callback context.
    // Jika dipanggil dari alur lain, messageId dapat diberikan secara eksplisit.
    const messageId = options?.messageId || getCallbackMessageId();
    const mode = String(options?.mode || 'auto').toLowerCase();
    const finalKeyboard = ensureHierarchyStepJumpButton(keyboard);
    
    console.log(`🔄 sendOrEditDrilldown: mode=${mode}, messageId=${messageId || 'none'}`);
    
    return await smartResponseUniversal(chatId, text, {
        keyboard: finalKeyboard,
        parseMode,
        mode,
        messageId
    });
}

// ============================================================
// 🆕 PATCH 3 — FASE 1: SMART SEND (Hybrid Toggle)
// Toggle global: ubah GLOBAL_USE_EDIT_INLINE
// ============================================================
let GLOBAL_USE_EDIT_INLINE = true;

// UI CONTRACT: label tombol maksimal 20 karakter.
// Pemendekan dilakukan berbasis makna/kata, bukan pemotongan buta.
// Emoji dianggap 1 karakter; tanda baca tidak menambah hitungan.
function normalizeButtonLabel(label) {
    const raw=String(label??'').trim();
    const aliases=[
        [/^⚠️\s*Terjadi error/i,'⚠️ Error'],
        [/^🔙\s*Kembali ke Menu Utama/i,'🔙 Kembali'],
        [/^⬅️\s*Kembali ke Menu Utama/i,'⬅️ Kembali'],
        [/^🔙\s*Kembali ke Menu Kategori/i,'🔙 Kembali'],
        [/^🔙\s*Kembali ke Menu Arsip/i,'🔙 Kembali'],
        [/^🏠\s*Kembali ke Menu Utama/i,'🏠 Utama'],
        [/Generate dari Kemampuan/i,'🎯 Kemampuan'],[/Generate dari Sub-Topik/i,'▶️ Sub-Topik'],
        [/Generate dari Topik/i,'▶️ Topik'],[/Generate dari Kisi/i,'▶️ Kisi'],
        [/Simpan Semua/i,'💾 Simpan Semua'],[/Simpan Berdasarkan Nomor/i,'📝 Berdasarkan Nomor'],
        [/Penjelasan Detail/i,'📖 Penjelasan'],[/Penjelasan \+ Contoh/i,'📖 Penjelasan'],
        [/Dashboard.*Statistik/i,'📊 Dashboard'],[/Statistik Global/i,'📈 Global'],
        [/Statistik AI/i,'🤖 Statistik AI'],[/Statistik Soal/i,'📝 Statistik Soal'],
        [/Upload.*Excel/i,'📤 Upload Excel'],[/Upload.*Soal/i,'📤 Upload Soal'],
        [/Export.*Semua/i,'📤 Export Semua'],[/Export.*Excel/i,'📤 Export Excel'],
        [/Import Massal/i,'📥 Import Massal'],[/Review Draft/i,'📋 Review Draft'],
        [/Urutkan Ulang ID/i,'🔄 Urutkan ID'],[/Kelola Mata Pelajaran/i,'🔷 Kelola Mapel'],
        [/Generate Pembahasan/i,'📖 Pembahasan'],[/Pilih Paket Tahap/i,'📦 Pilih Preset'],
        [/Upload Media \(Global\)/i,'📤 Media Global'],[/Upload Media \(Per-Tahap\)/i,'📤 Media Per-Tahap'],
        [/Export Materi.*MD\/HTML\/JSON/i,'📦 Export Materi'],[/Regenerate Tahap Gagal/i,'🔄 Ulangi Tahap'],
        [/Generate Soal dari Materi/i,'📝 Soal dari Materi'],[/Peta Konsep \(50-100 kata\)/i,'🗺️ Peta Konsep'],
        [/Penjelasan \+ Contoh \(5\.000-15\.000 kata\)/i,'📖 Penjelasan'],
        [/Penjelasan Detail \(5\.000-15\.000 kata\)/i,'📖 Penjelasan'],
        [/Kembali ke Daftar Versi/i,'🔙 Daftar Versi'],[/Hapus Multiple\/Range/i,'📝 Hapus Banyak'],
        [/Tambah Jenjang ke Program Ini/i,'➕ Tambah Jenjang'],[/Langsung Generate dari/i,'▶️ Generate Langsung'],
        [/^🏗️\s*Lapisan Pembelajaran/i,'🏗️ Lapisan'],
        [/^🔷\s*Lompat ke Step Lain/i,'🔷 Lompat Step']
    ];
    for(const [rx,repl] of aliases) if(rx.test(raw)) return repl;

    // Fallback berbasis kata: buang keterangan ekor sampai <=20, tanpa memotong kata.
    let text=raw.replace(/\s*\([^)]*\)\s*/g,' ').replace(/\s+/g,' ').trim();
    const graphemes=[...new Intl.Segmenter('id',{granularity:'grapheme'}).segment(text)].map(x=>x.segment);
    const count=arr=>arr.reduce((n,g)=>/^[\p{P}]+$/u.test(g)?n:(n+1),0);
    if(count(graphemes)<=20) return text;
    const parts=text.split(/\s+/);
    while(parts.length>1 && count([...new Intl.Segmenter('id',{granularity:'grapheme'}).segment(parts.join(' '))].map(x=>x.segment))>20) parts.pop();
    const compact=parts.join(' ').trim();
    return compact || 'Aksi';
}
function normalizeInlineKeyboard(keyboard) {
    if(!Array.isArray(keyboard)) return keyboard;
    return keyboard.map(row=>Array.isArray(row)?row.map(btn=>{
        if(!btn || typeof btn!=='object') return btn;
        return {...btn,text:normalizeButtonLabel(btn.text)};
    }):row);
}

async function smartSend(chatId, text, keyboard, parseMode = "Markdown", options = {}) {
    keyboard = normalizeInlineKeyboard(keyboard);
    const mode = String(options?.mode || 'auto').toLowerCase();
    const messageId = options?.messageId || getCallbackMessageId();
    const allowEdit = options?.allowEdit !== false;
    
    // SEND = selalu membuat pesan baru.
    if (mode === 'send' || !allowEdit || !GLOBAL_USE_EDIT_INLINE || !messageId) {
        return await sendInlineKeyboardRaw(chatId, text, keyboard, parseMode);
    }
    
    // AUTO dan EDIT sama-sama mencoba memperbarui pesan yang tersedia.
    const result = await editInlineKeyboard(chatId, messageId, text, keyboard, parseMode);
    
    // EDIT = tetap fallback ke SEND agar alur tidak macet jika pesan sudah tidak dapat diedit.
    // AUTO = perilaku yang sama: edit bila memungkinkan, send bila tidak.
    if (result && !result.ok && !result.notModified) {
        console.warn(`⚠️ smartSend [${mode}]: edit gagal, fallback ke send`);
        return await sendInlineKeyboardRaw(chatId, text, keyboard, parseMode);
    }
    
    return result;
}

// ============================================================
// 🆕 SMART RESPONSE GENERIC — TANPA KEYBOARD
// Untuk respons teks biasa yang juga perlu mengikuti konteks
// EDIT/SEND. Tidak mengubah sendMessage() mentah yang memang
// sengaja digunakan untuk pesan baru.
// ============================================================
async function smartResponse(chatId, text, parseMode = "Markdown", options = {}) {
    const mode = String(options?.mode || 'auto').toLowerCase();
    const messageId = options?.messageId || getCallbackMessageId();
    const allowEdit = options?.allowEdit !== false;

    // SEND = selalu membuat pesan baru.
    if (mode === 'send' || !allowEdit || !GLOBAL_USE_EDIT_INLINE || !messageId) {
        return await sendMessage(chatId, text, parseMode);
    }

    try {
        const finalText = text && text.length > 4096 ? text.substring(0, 4093) + '...' : text;
        const payload = { chat_id: chatId, message_id: messageId, text: finalText, parse_mode: parseMode };
        const response = await fetch(`https://api.telegram.org/bot${getTelegramToken()}/editMessageText`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });
        const result = await response.json();

        if (result.ok || result.description?.includes('message is not modified')) {
            return result.ok ? result : { ok: true, notModified: true };
        }

        // Markdown/entity error: retry without parse mode before creating a new message.
        if (result.description && (result.description.includes('parse') || result.description.includes('entities') || result.description.includes("can't parse"))) {
            const fallback = await fetch(`https://api.telegram.org/bot${getTelegramToken()}/editMessageText`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ chat_id: chatId, message_id: messageId, text: finalText })
            });
            const fallbackResult = await fallback.json();
            if (fallbackResult.ok || fallbackResult.description?.includes('message is not modified')) {
                return fallbackResult.ok ? fallbackResult : { ok: true, notModified: true };
            }
        }

        console.warn(`⚠️ smartResponse [${mode}]: edit gagal → send baru:`, result.description);
    } catch (error) {
        console.warn(`⚠️ smartResponse [${mode}]: edit error → send baru:`, error.message);
    }

    return await sendMessage(chatId, text, parseMode);
}

// ============================================================
// SMART RESPONSE UNIVERSAL — SATU PINTU UNTUK TEKS + KEYBOARD
// mode: auto | edit | send
// messageId opsional: dipakai ketika sumber pesan bukan callback.
// ============================================================
async function smartResponseUniversal(chatId, text, options = {}) {
    const { keyboard = null, parseMode = 'Markdown', mode = 'auto', messageId = null } = options || {};
    if (keyboard !== null) {
        return await smartSend(chatId, text, keyboard, parseMode, { mode, messageId });
    }
    return await smartResponse(chatId, text, parseMode, { mode, messageId });
}

console.log('✅ [PATCH 3] smartSend loaded — GLOBAL_USE_EDIT_INLINE =', GLOBAL_USE_EDIT_INLINE);

// SmartSend adapter untuk handler lama agar signature sendMessage/sendInlineKeyboard tetap kompatibel.
async function smartMessage(chatId, text, parseMode = 'Markdown') {
    return await smartResponseUniversal(chatId, text, { mode: 'auto', parseMode });
}

async function smartKeyboard(chatId, text, inlineKeyboard, parseMode = 'Markdown') {
    const messageId = (typeof getCallbackMessageId === 'function') ? getCallbackMessageId() : null;
    return await smartResponseUniversal(chatId, text, { keyboard: inlineKeyboard, parseMode, mode: 'auto', messageId });
}


// ============================================================
// 🆕 SETTINGS HELPER
// ============================================================
async function getSetting(db, key, defaultValue = null) {
    try {
        const row = await db.prepare(
            `SELECT value FROM settings WHERE key = ?`
        ).bind(key).first();
        return row?.value ?? defaultValue;
    } catch (e) {
        return defaultValue;
    }
}

async function setSetting(db, key, value, keterangan = null) {
    const now = new Date().toISOString();
    try {
        await db.prepare(`
            INSERT INTO settings (key, value, keterangan, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(key) DO UPDATE SET 
                value = excluded.value,
                updated_at = excluded.updated_at
        `).bind(key, String(value), keterangan, now, now).run();
        return true;
    } catch (e) {
        console.warn(`⚠️ setSetting(${key}) error:`, e.message);
        return false;
    }
}

let SETTINGS_LOADED = false;
async function loadSettings(db) {
    if (SETTINGS_LOADED) return;
    try {
        const val = await getSetting(db, 'use_edit_inline', 'true');
        GLOBAL_USE_EDIT_INLINE = val !== 'false';
        SETTINGS_LOADED = true;
        console.log('✅ [SETTINGS] use_edit_inline =', GLOBAL_USE_EDIT_INLINE);
    } catch (e) {
        console.warn('⚠️ Gagal load settings:', e.message);
    }
}






