// ============================================================
// 1. REGISTER USER BARU (AUTO-REGISTER)
// ============================================================
async function registerUser(db, telegramId, userData = {}) {
    try {
        const tgId = String(telegramId);
        
        // Cek apakah user sudah ada
        const existing = await db.prepare(`
            SELECT * FROM users WHERE telegram_id = ?
        `).bind(tgId).first();
        
        if (existing) {
            return { success: true, user: existing, isNew: false };
        }
        
        // Generate ID unik
        const id = await generateId(db, 'U', 'users');
        
        // Tentukan role: admin kalau ada di ADMIN_IDS
        const role = getAdminIds(RUNTIME_ENV).includes(tgId) ? 'admin' : 'user';
        
        const now = new Date().toISOString();
        
        await db.prepare(`
            INSERT INTO users (
                id, telegram_id, username, nama_lengkap, role, status,
                created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, 'AKTIF', ?, ?)
        `).bind(
            id,
            tgId,
            userData.username || null,
            userData.nama_lengkap || userData.username || `User ${tgId}`,
            role,
            now,
            now
        ).run();
        
        const newUser = await db.prepare(`SELECT * FROM users WHERE id = ?`).bind(id).first();
        
        // Catat aktivitas
        await logUserActivity(db, id, tgId, 'register', 'user', id, {
            role: role,
            source: 'auto_register'
        });
        
        return { success: true, user: newUser, isNew: true };
        
    } catch (e) {
        console.error('registerUser error:', e);
        return { success: false, error: e.message };
    }
}

