// ============================================================
// 4. UPDATE USER
// ============================================================
async function updateUser(db, userId, data, updatedBy = null) {
    try {
        const fields = [];
        const values = [];
        
        const allowedFields = ['nama_lengkap', 'username', 'email', 'no_hp', 'role', 'status'];
        
        for (const field of allowedFields) {
            if (data[field] !== undefined && data[field] !== null && data[field] !== '') {
                fields.push(`${field} = ?`);
                values.push(data[field]);
            }
        }
        
        if (fields.length === 0) {
            return { success: false, error: 'Tidak ada data yang diubah' };
        }
        
        fields.push('updated_at = ?');
        values.push(new Date().toISOString());
        values.push(userId);
        
        await db.prepare(`
            UPDATE users SET ${fields.join(', ')} WHERE id = ?
        `).bind(...values).run();
        
        // Log aktivitas
        const user = await getUserById(db, userId);
        if (user) {
            await logUserActivity(db, updatedBy || userId, user.telegram_id, 
                'update_user', 'user', userId, data);
        }
        
        return { success: true };
        
    } catch (e) {
        console.error('updateUser error:', e);
        return { success: false, error: e.message };
    }
}

