// ============================================================
// 6. LIST USERS (PAGINATION + FILTER)
// ============================================================
async function listUsers(db, page = 1, limit = 10, filter = {}) {
    try {
        const offset = (page - 1) * limit;
        
        let query = `SELECT * FROM users WHERE 1=1`;
        let countQuery = `SELECT COUNT(*) as total FROM users WHERE 1=1`;
        const bind = [];
        
        if (filter.role) {
            query += ` AND role = ?`;
            countQuery += ` AND role = ?`;
            bind.push(filter.role);
        }
        if (filter.status) {
            query += ` AND status = ?`;
            countQuery += ` AND status = ?`;
            bind.push(filter.status);
        }
        if (filter.search) {
            const searchCond = ` AND (LOWER(nama_lengkap) LIKE LOWER(?) OR LOWER(username) LIKE LOWER(?) OR telegram_id LIKE ?)`;
            query += searchCond;
            countQuery += searchCond;
            const s = `%${filter.search}%`;
            bind.push(s, s, `%${filter.search}%`);
        }
        
        query += ` ORDER BY created_at DESC LIMIT ? OFFSET ?`;
        
        const countResult = await db.prepare(countQuery).bind(...bind).first();
        const users = await db.prepare(query).bind(...bind, limit, offset).all();
        
        return {
            success: true,
            users: users.results || [],
            total: countResult?.total || 0,
            totalPages: Math.ceil((countResult?.total || 0) / limit),
            page
        };
        
    } catch (e) {
        console.error('listUsers error:', e);
        return { success: false, error: e.message, users: [], total: 0, totalPages: 0 };
    }
}

