async function deleteUser(db, userId, deletedBy = null) {
    try {
        const user = await getUserById(db, userId);
        if (!user) return { success: false, error: 'User tidak ditemukan' };
        
        await db.prepare(`DELETE FROM users WHERE id = ?`).bind(userId).run();
        
        await logUserActivity(db, deletedBy || userId, user.telegram_id, 
            'delete_user', 'user', userId, {
                nama: user.nama_lengkap,
                telegram_id: user.telegram_id
            });
        
        return { success: true, deletedUser: user };
        
    } catch (e) {
        console.error('deleteUser error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 8. GET USER STATISTICS
// ============================================================
async function getUserStats(db) {
    try {
        const stats = await db.prepare(`
            SELECT 
                COUNT(*) as total,
                SUM(CASE WHEN role = 'admin' THEN 1 ELSE 0 END) as total_admin,
                SUM(CASE WHEN role = 'user' THEN 1 ELSE 0 END) as total_user,
                SUM(CASE WHEN role = 'teacher' THEN 1 ELSE 0 END) as total_teacher,
                SUM(CASE WHEN status = 'AKTIF' THEN 1 ELSE 0 END) as total_aktif,
                SUM(CASE WHEN status = 'BLOKIR' THEN 1 ELSE 0 END) as total_blokir
            FROM users
        `).first();
        
        return {
            success: true,
            total: stats?.total || 0,
            total_admin: stats?.total_admin || 0,
            total_user: stats?.total_user || 0,
            total_teacher: stats?.total_teacher || 0,
            total_aktif: stats?.total_aktif || 0,
            total_blokir: stats?.total_blokir || 0
        };
        
    } catch (e) {
        console.error('getUserStats error:', e);
        return { success: false, error: e.message };
    }
}

