// ============================================================
// ADMIN - REVIEW SOAL DRAFT
// ============================================================

async function adminReviewSoal(env, userId, chatId, db, soalId) {
    try {
        // Ambil detail soal
        const soal = await db.prepare(`
            SELECT 
                s.*,
                cp.nama as penyajian_nama,
                cp.icon as penyajian_icon,
                ti.nama as tipe_isi_nama,
                tp.nama as tahap_nama,
                tp.icon as tahap_icon,
                sk.nama as subkemampuan_nama,
                km.nama as kemampuan_nama
            FROM soal s
            LEFT JOIN cara_penyajian cp ON s.cara_penyajian_id = cp.id
            LEFT JOIN tipe_isi_soal ti ON s.tipe_isi_id = ti.id
            LEFT JOIN tahap_pembelajaran tp ON s.tahap_pembelajaran_id = tp.id
            LEFT JOIN sub_kemampuan sk ON s.sub_kemampuan_id = sk.id
            LEFT JOIN kemampuan_diuji km ON sk.kemampuan_id = km.id
            WHERE s.id = ?
        `).bind(soalId).first();
        
        if (!soal) {
            await smartResponseUniversal(chatId, '❌ Soal tidak ditemukan.');
            return;
        }
        
        // Kirim detail soal
        let msg = `📋 *REVIEW SOAL - ${soal.id}*\n\n`;
        msg += `📌 *Status:* ${soal.status_soal || 'DRAFT'}\n\n`;
        msg += `📝 *SOAL:*\n${soal.soal}\n\n`;
        msg += `📋 *PILIHAN:*\n`;
        msg += `A. ${soal.pilihan_a || '-'}\n`;
        msg += `B. ${soal.pilihan_b || '-'}\n`;
        msg += `C. ${soal.pilihan_c || '-'}\n`;
        msg += `D. ${soal.pilihan_d || '-'}\n`;
        msg += `E. ${soal.pilihan_e || '-'}\n\n`;
        msg += `⭐ *Jawaban:* ${soal.jawaban_benar}\n\n`;
        msg += `🏷️ *KLASIFIKASI:*\n`;
        msg += `├─ Cara Penyajian: ${soal.penyajian_icon || ''} ${soal.penyajian_nama || '-'}\n`;
        msg += `├─ Tipe Isi: ${soal.tipe_isi_nama || '-'}\n`;
        msg += `├─ Tahap: ${soal.tahap_icon || ''} ${soal.tahap_nama || '-'}\n`;
        msg += `└─ Proses Kognitif: ${getStoredCognitive(soal)}\n\n`;
        msg += `📊 *METRIK:*\n`;
        msg += `├─ Kesulitan: ${soal.tingkat_kesulitan || 5}/10\n`;
        msg += `└─ Estimasi: ${soal.estimasi_waktu || 60} detik\n\n`;
        msg += `📌 *AKSI:*\n`;
        msg += `/approve_${soal.id} - Setujui (→ RESMI)\n`;
        msg += `/reject_${soal.id} [alasan] - Tolak (→ REJECT)\n`;
        msg += `/revisi_${soal.id} [catatan] - Minta Revisi\n`;
        msg += `/edit_${soal.id} - Edit Soal\n`;
        msg += `/skip_${soal.id} - Lewati (review nanti)`;
        
        const keyboard = [
            [{ text: "✅ Approve", callback_data: `admin_approve_${soal.id}` }],
            [{ text: "❌ Reject", callback_data: `admin_reject_${soal.id}` }],
            [{ text: "✏️ Edit", callback_data: `admin_edit_${soal.id}` }],
            [{ text: "⏭️ Skip", callback_data: `admin_skip_${soal.id}` }]
        ];
        
        await sendInlineKeyboard(chatId, msg, keyboard);
        
    } catch (e) {
        console.error('Review soal error:', e);
        await smartResponseUniversal(chatId, `❌ Error: ${e.message}`);
    }
}

// ============================================================
// ADMIN - APPROVE SOAL
// ============================================================

async function adminApproveSoal(env, userId, chatId, db, soalId) {
    try {
        const soal = await db.prepare(`
            SELECT id, status_soal FROM soal WHERE id = ?
        `).bind(soalId).first();
        
        if (!soal) {
            await smartResponseUniversal(chatId, '❌ Soal tidak ditemukan.');
            return;
        }
        
        if (soal.status_soal !== 'DRAFT') {
            await smartResponseUniversal(chatId, `⚠️ Soal sudah ${soal.status_soal}, tidak bisa di-approve.`);
            return;
        }
        
        await db.prepare(`
            UPDATE soal SET 
                status_soal = 'RESMI',
                tanggal_validasi = ?,
                validasi_oleh = ?
            WHERE id = ?
        `).bind(
            new Date().toISOString(),
            userId,
            soalId
        ).run();
        
        await db.prepare(`
            INSERT INTO feedback_admin (soal_id, admin_id, aksi, status_sebelum, status_sesudah)
            VALUES (?, ?, 'APPROVE', ?, 'RESMI')
        `).bind(soalId, userId, soal.status_soal).run();
        
        await smartResponseUniversal(chatId, `
✅ *SOAL ${soalId} DISETUJUI!*

📌 Status: DRAFT → RESMI
👤 Oleh: Admin
📅 Tanggal: ${new Date().toLocaleString('id-ID')}

💡 Soal sekarang tersedia untuk semua user.
        `);
        
    } catch (e) {
        console.error('Approve soal error:', e);
        await smartResponseUniversal(chatId, `❌ Error: ${e.message}`);
    }
}

