// ============================================================
// FUNGSI GENERATE ID UNTUK SEMUA TABEL
// ============================================================
async function generateId(db, prefix, table) {
  try {
    const result = await db.prepare(`
      SELECT id FROM ${table} WHERE id LIKE ? ORDER BY id DESC LIMIT 1
    `).bind(`${prefix}%`).first();
    
    if (!result) {
      return `${prefix}001`;
    }
    
    const lastId = result.id;
    const num = parseInt(lastId.substring(prefix.length)) + 1;
    return `${prefix}${String(num).padStart(3, '0')}`;
  } catch (e) {
    return `${prefix}001`;
  }
}

