// ============================================================
// FUNGSI PARSING UNTUK UPLOAD MASSAL HIERARKI
// ============================================================

/**
 * Parse teks untuk upload massal Kategori -> Kisi-Kisi
 * Format:
 * KATEGORI: [Nama Kategori]
 * BIDANG: [Nama Bidang]
 * PROGRAM: [Nama Program]
 * TOPIK: [Nama Topik]
 * SUBTOPIK: [Nama SubTopik]
 * KISI: [Judul Kisi] | [Kode]
 * --- (pemisah antara satu hierarki dengan berikutnya)
 */
function parseHierarkiText(text) {
  const blocks = text.split(/---\s*/).filter(b => b.trim());
  const results = [];
  
  for (const block of blocks) {
    const lines = block.split('\n').map(l => l.trim()).filter(l => l);
    let current = {
      kategori: null,
      bidang: null,
      program: null,
      topik: null,
      subtopik: null,
      kisi: null,
      kode: null
    };
    
    for (const line of lines) {
      // Cek KATEGORI:
      if (line.match(/^KATEGORI\s*:/i)) {
        current.kategori = line.replace(/^KATEGORI\s*:/i, '').trim();
      }
      // Cek BIDANG:
      else if (line.match(/^BIDANG\s*:/i)) {
        current.bidang = line.replace(/^BIDANG\s*:/i, '').trim();
      }
      // Cek PROGRAM:
      else if (line.match(/^PROGRAM\s*:/i)) {
        current.program = line.replace(/^PROGRAM\s*:/i, '').trim();
      }
      // Cek TOPIK:
      else if (line.match(/^TOPIK\s*:/i)) {
        current.topik = line.replace(/^TOPIK\s*:/i, '').trim();
      }
      // Cek SUBTOPIK:
      else if (line.match(/^SUBTOPIK\s*:/i)) {
        current.subtopik = line.replace(/^SUBTOPIK\s*:/i, '').trim();
      }
      // Cek KISI: dengan format "Judul | Kode"
      else if (line.match(/^KISI\s*:/i)) {
        const parts = line.replace(/^KISI\s*:/i, '').trim().split('|');
        current.kisi = parts[0].trim();
        current.kode = parts.length > 1 ? parts[1].trim() : null;
      }
    }
    
    // Validasi minimal harus ada KATEGORI dan KISI
    if (current.kategori && current.kisi) {
      results.push(current);
    }
  }
  
  return results;
}

/**
 * Parse teks untuk upload soal dengan hierarki
 * Format:
 * KATEGORI: [Nama Kategori]
 * BIDANG: [Nama Bidang]
 * PROGRAM: [Nama Program]
 * TOPIK: [Nama Topik]
 * SUBTOPIK: [Nama SubTopik]
 * KISI: [Judul Kisi]
 * KEMAMPUAN: [Nama Kemampuan]
 * SUBKEMAMPUAN: [Nama SubKemampuan]
 * --- (pemisah antara satu kelompok soal dengan berikutnya)
 * SOAL: [Teks Soal]
 * A. [Pilihan A]
 * B. [Pilihan B]
 * C. [Pilihan C]
 * D. [Pilihan D]
 * E. [Pilihan E]
 * JAWABAN: [A/B/C/D/E]
 * --- (pemisah antar soal dalam satu kelompok)
 */

function parseSoalHierarkiText(text) {
    const blocks = text.split(/---\s*/).filter(b => b.trim());
    const results = [];
    let currentContext = {};
    
    for (const block of blocks) {
        const lines = block.split('\n').map(l => l.trim()).filter(l => l);
        let contextData = {};
        let questionData = {};
        
        for (const line of lines) {
            // Cek konteks hierarki
            if (line.match(/^KATEGORI\s*:/i)) {
                contextData.kategori = line.replace(/^KATEGORI\s*:/i, '').trim();
            }
            else if (line.match(/^BIDANG\s*:/i)) {
                contextData.bidang = line.replace(/^BIDANG\s*:/i, '').trim();
            }
            else if (line.match(/^PROGRAM\s*:/i)) {
                contextData.program = line.replace(/^PROGRAM\s*:/i, '').trim();
            }
            else if (line.match(/^TOPIK\s*:/i)) {
                contextData.topik = line.replace(/^TOPIK\s*:/i, '').trim();
            }
            else if (line.match(/^SUBTOPIK\s*:/i)) {
                contextData.subtopik = line.replace(/^SUBTOPIK\s*:/i, '').trim();
            }
            else if (line.match(/^KISI\s*:/i)) {
                contextData.kisi = line.replace(/^KISI\s*:/i, '').trim();
            }
            else if (line.match(/^KEMAMPUAN\s*:/i)) {
                contextData.kemampuan = line.replace(/^KEMAMPUAN\s*:/i, '').trim();
            }
            else if (line.match(/^SUBKEMAMPUAN\s*:/i)) {
                contextData.subkemampuan = line.replace(/^SUBKEMAMPUAN\s*:/i, '').trim();
            }
            // ===== TAMBAHKAN INI UNTUK SUMBER =====
            else if (line.match(/^SUMBER\s*:/i)) {
                contextData.sumber = line.replace(/^SUMBER\s*:/i, '').trim();
            }
            else if (line.match(/^LINK\s*:/i)) {
                contextData.link = line.replace(/^LINK\s*:/i, '').trim();
            }
            else if (line.match(/^TAHUN\s*:/i)) {
            contextData.tahun = line.replace(/^TAHUN\s*:/i, '').trim();
            
            }
            // ===== AKHIR TAMBAHAN =====
            // Cek SOAL:
            else if (line.match(/^SOAL\s*:/i)) {
                questionData = {
                    soal: line.replace(/^SOAL\s*:/i, '').trim(),
                    pilihan_a: '',
                    pilihan_b: '',
                    pilihan_c: '',
                    pilihan_d: '',
                    pilihan_e: '',
                    jawaban: ''
                };
            }
            // Cek pilihan A-E
            else if (line.match(/^[A-E]\.\s*/)) {
                const letter = line[0].toUpperCase();
                const textValue = line.substring(2).trim();
                if (letter === 'A') questionData.pilihan_a = textValue;
                else if (letter === 'B') questionData.pilihan_b = textValue;
                else if (letter === 'C') questionData.pilihan_c = textValue;
                else if (letter === 'D') questionData.pilihan_d = textValue;
                else if (letter === 'E') questionData.pilihan_e = textValue;
            }
            // Cek JAWABAN:
            else if (line.match(/^JAWABAN\s*:/i)) {
                const jawaban = line.replace(/^JAWABAN\s*:/i, '').trim().toUpperCase();
                if (['A','B','C','D','E'].includes(jawaban)) {
                    questionData.jawaban = jawaban;
                }
            }
        }
        
        // Jika ada soal yang valid, simpan dengan konteks
        if (questionData.soal && questionData.jawaban) {
            results.push({
                context: { ...contextData },
                soal: { ...questionData }
            });
        }
        // Jika hanya konteks tanpa soal, simpan konteks untuk digunakan
        else if (Object.keys(contextData).length > 0 && !questionData.soal) {
            currentContext = { ...contextData };
        }
        // Jika ada soal tanpa konteks, gunakan konteks terakhir
        else if (questionData.soal && questionData.jawaban) {
            results.push({
                context: { ...currentContext },
                soal: { ...questionData }
            });
        }
    }
    
    return results;
}

// ============================================================
// FUNGSI PARSER FORMAT UNIVERSAL
// Berlaku untuk: Manual, Hierarki, Batch, AI Generate
// ============================================================

// ============================================================
// PARSE FORMAT UNIVERSAL — VERSI FLEKSIBEL + HIERARKI TETAP
// VERSI FINAL: Support jenjang & kelas
// ============================================================
function parseUniversalFormat(text) {
    console.log('📥 [parseUniversalFormat] DIPANGGIL');
    
    // ============================================================
    // STRUKTUR HASIL — 10 hierarki + master data + metadata
    // ============================================================
    const result = {
        // 🔒 HIERARKI (10 slot tetap — boleh null)
        kategori: null,
        bidang: null,
        program: null,
        jenjang: null,           // 🆕
        kelas: null,             // 🆕
        topik: null,
        subtopik: null,
        kisi: null,
        kemampuan: null,
        subKemampuan: null,
        
        // 📊 MASTER DATA (boleh null)
        caraPenyajian: null,
        tipeIsi: null,
        kompleksitas: null,
        tahap: null,
        tipeHots: null,
        levelHots: null,
        tingkatKesulitan: null,
        lapisan: null,
        sumberReferensi: null,
        linkSumber: null,
        
        // 🆕 MEDIA LOKAL/URL
        imagePath: null,
        videoPath: null,
        audioPath: null,
        
        // 🆕 MEDIA TELEGRAM
        imageFileId: null,
        videoFileId: null,
        audioFileId: null,
        
        // Metadata
        keabsahan: null, tahun: null,
        // Soal
        soalList: []
    };
    
    if (!text || !text.trim()) return result;
    
    // ============================================================
    // 1. DETEKSI JUMLAH SOAL
    // ============================================================
    const hasSeparator = /\n\s*-{2,}\s*\n/.test(text);
    const soalCount = (text.match(/^\s*SOAL\s*[:.]/gim) || []).length;
    
    console.log(`📊 Soal terdeteksi: ${soalCount}, separator: ${hasSeparator}`);
    
    // ============================================================
    // 2. SPLIT MENJADI BLOK
    // ============================================================
    let blocks = [];
    
    if (hasSeparator && soalCount > 1) {
        blocks = text.split(/\n\s*-{2,}\s*\n/).filter(b => b.trim());
    } else if (soalCount > 1) {
        const parts = text.split(/(?=^\s*SOAL\s*[:.])/gim);
        blocks = parts.filter(p => p.trim());
    } else {
        blocks = [text];
    }
    
    console.log(`📦 Total blok: ${blocks.length}`);
    
    // ============================================================
    // 3. PARSE KONTEKS DARI BLOCK PERTAMA (sebelum SOAL pertama)
    // ============================================================
    const firstBlock = blocks[0] || '';
    const firstSoalMatch = firstBlock.match(/^\s*SOAL\s*[:.]/im);
    
    let contextPart = '';
    if (firstSoalMatch && firstSoalMatch.index > 0) {
        contextPart = firstBlock.substring(0, firstSoalMatch.index);
    }
    
    // Parse context dari contextPart
    parseContextIntoResult(contextPart, result);
    
    // ============================================================
    // 4. PARSE SETIAP SOAL
    // ============================================================
    for (const block of blocks) {
        const blockSoalCount = (block.match(/^\s*SOAL\s*[:.]/gim) || []).length;
        
        if (blockSoalCount > 1) {
            const parts = block.split(/(?=^\s*SOAL\s*[:.])/gim);
            for (const part of parts) {
                if (!part.trim()) continue;
                const soal = parseSingleSoalFlexible(part);
                if (soal && soal.soal && soal.jawaban) {
                    result.soalList.push(mergeContext(soal, result));
                }
            }
        } else {
            const soal = parseSingleSoalFlexible(block);
            if (soal && soal.soal && soal.jawaban) {
                const localContext = {};
                parseContextIntoResult(block, localContext);
                const mergedContext = { ...result, ...localContext };
                result.soalList.push(mergeContext(soal, mergedContext));
            }
        }
    }
    
    console.log(`✅ Total soal final: ${result.soalList.length}`);
    console.log(`   Hierarki global: kategori=${result.kategori}, jenjang=${result.jenjang}, kelas=${result.kelas}, topik=${result.topik}`);
    
    return result;
}

// ============================================================
// PARSE CONTEXT — Ekstrak hierarki + master data dari teks
// VERSI FINAL: Support jenjang & kelas
// ============================================================
function parseContextIntoResult(text, target) {
    if (!text || !text.trim()) return;
    
    const lines = text.split('\n');
    
    for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed) continue;
        
        // Skip separator
        if (/^-{2,}$/.test(trimmed)) continue;
        
        // Skip kalau ini bagian soal
        if (/^\s*SOAL\s*[:.]/i.test(trimmed)) continue;
        if (/^\s*JAWABAN\s*[:.]/i.test(trimmed)) continue;
        if (/^\s*PEMBAHASAN\s*[:.]/i.test(trimmed)) continue;
        if (/^[A-Ea-e]\s*[.):\]]\s+/.test(trimmed)) continue;
        
        // Format: "Key : Value" atau "Key: Value" atau "Key = Value"
        const match = trimmed.match(/^([^:=\n]+?)\s*[:=]\s*(.+)$/);
        if (!match) continue;
        
        const key = match[1].trim().toLowerCase().replace(/\s+/g, ' ');
        const value = match[2].trim();
        
        if (!value || value === '-' || value === '' || value === 'null') continue;
        
        // ============================================================
        // MAPPING KEY → FIELD
        // ============================================================
        switch (key) {
            // 🔒 HIERARKI (10 field tetap)
            case 'kategori': 
                target.kategori = value; 
                break;
            case 'bidang studi':
            case 'bidang': 
                target.bidang = value; 
                break;
            case 'program studi':
            case 'program': 
                target.program = value; 
                break;
            case 'jenjang':                          // 🆕
            case 'jenjang pendidikan':               // 🆕
                target.jenjang = value; 
                break;
            case 'kelas':                            // 🆕
            case 'tingkat':                          // 🆕
                target.kelas = value; 
                break;
            case 'topik': 
                target.topik = value; 
                break;
            case 'sub-topik':
            case 'subtopik':
            case 'sub topik': 
                target.subtopik = value; 
                break;
            case 'kisi-kisi':
            case 'kisi kisi':
            case 'kisi': 
                target.kisi = value; 
                break;
            case 'kemampuan': 
                target.kemampuan = value; 
                break;
            case 'sub-kemampuan':
            case 'subkemampuan':
            case 'sub kemampuan': 
                target.subKemampuan = value; 
                break;
            
            // 📊 MASTER DATA
            case 'cara penyajian':
            case 'penyajian': 
                target.caraPenyajian = value; 
                break;
            case 'tipe isi':
            case 'tipeisi': 
                target.tipeIsi = value; 
                break;
            case 'kompleksitas': 
                target.kompleksitas = value; 
                break;
            case 'tahap pembelajaran':
            case 'tahap': 
                target.tahap = value; 
                break;
            case 'tipe hots': 
                target.tipeHots = value; 
                break;
            case 'level hots':
            case 'level':
                // Legacy field: accepted for backward-compatible parsing but no longer drives classification.
                break;
            case 'tingkat kesulitan': 
                target.tingkatKesulitan = value; 
                break;
            case 'lapisan pembelajaran':
            case 'lapisan':
                const lapm = value.match(/\d+/);
                if (lapm) target.lapisan = parseInt(lapm[0]);
                break;
            case 'sumber referensi':
            case 'sumber': 
                target.sumberReferensi = value; 
                break;
            case 'link sumber':
            case 'link': 
                target.linkSumber = value; 
                break;
            
            // 🆕 MEDIA LOKAL/URL
            case 'image':
            case 'gambar':
            case 'image path':
            case 'gambar path':
            case 'image url':
            case 'gambar url':
                target.imagePath = value;
                break;
            case 'video':
            case 'video path':
            case 'video url':
                target.videoPath = value;
                break;
            case 'audio':
            case 'audio path':
            case 'audio url':
            case 'suara':
            case 'suara path':
            case 'suara url':
                target.audioPath = value;
                break;
            
            // 🆕 MEDIA TELEGRAM (File ID)
            case 'image file id':
            case 'image fileid':
            case 'gambar file id':
            case 'image_file_id':
                target.imageFileId = value;
                break;
            case 'video file id':
            case 'video fileid':
            case 'video_file_id':
                target.videoFileId = value;
                break;
            case 'audio file id':
            case 'audio fileid':
            case 'audio_file_id':
                target.audioFileId = value;
                break;
            
            // 📌 METADATA
            case 'keabsahan':
            case 'keabsahan soal': 
                target.keabsahan = value; 
                break;
            case 'tahun': 
                target.tahun = value; 
                break;
        }
    }
}

// ============================================================
// PARSE SATU SOAL — FLEKSIBEL
// ============================================================
function parseSingleSoalFlexible(text) {
    const soal = {
        soal: '',
        pilihan_a: '',
        pilihan_b: '',
        pilihan_c: '',
        pilihan_d: '',
        pilihan_e: '',
        jawaban: '',
        pembahasan: '',
        alasan_a: '', alasan_b: '', alasan_c: '', alasan_d: '', alasan_e: ''
    };
    
    if (!text || !text.trim()) return soal;
    
    const lines = text.split('\n');
    let soalParts = [];
    let pembahasanParts = [];
    let mode = 'soal';
    let foundSoal = false;
    
    for (let line of lines) {
        const trimmed = line.trim();
        if (!trimmed) continue;
        
        // Skip separator
        if (/^-{2,}$/.test(trimmed)) continue;
        
        // SOAL:
        if (/^\s*SOAL\s*[:.]/i.test(trimmed)) {
            const content = trimmed.replace(/^\s*SOAL\s*[:.]\s*/i, '').trim();
            if (content) soalParts.push(content);
            foundSoal = true;
            mode = 'soal';
            continue;
        }
        
        // JAWABAN:
        if (/^\s*JAWABAN\s*[:.]/i.test(trimmed)) {
            const raw = trimmed.replace(/^\s*JAWABAN\s*[:.]\s*/i, '').trim().toUpperCase();
            const match = raw.match(/[A-E]/);
            if (match) soal.jawaban = match[0];
            continue;
        }
        
        // ALASAN A-E:
        const alasanMatch = trimmed.match(/^\s*ALASAN\s*([A-E])\s*[:.]\s*(.*)$/i);
        if (alasanMatch) {
            const letter = alasanMatch[1].toLowerCase();
            soal[`alasan_${letter}`] = alasanMatch[2].trim();
            mode = `alasan_${letter}`;
            continue;
        }

        // PEMBAHASAN:
        if (/^\s*PEMBAHASAN\s*[:.]/i.test(trimmed)) {
            const content = trimmed.replace(/^\s*PEMBAHASAN\s*[:.]\s*/i, '').trim();
            if (content) pembahasanParts.push(content);
            mode = 'pembahasan';
            continue;
        }
        
        // PILIHAN A-E
        const pilihanMatch = trimmed.match(/^([A-Ea-e])\s*[.):\]]\s+(.+)$/);
        if (pilihanMatch) {
            const letter = pilihanMatch[1].toUpperCase();
            const value = pilihanMatch[2].trim();
            
            if (letter === 'A') soal.pilihan_a = value;
            else if (letter === 'B') soal.pilihan_b = value;
            else if (letter === 'C') soal.pilihan_c = value;
            else if (letter === 'D') soal.pilihan_d = value;
            else if (letter === 'E') soal.pilihan_e = value;
            
            mode = 'soal';
            continue;
        }
        
        // Lanjutan
        if (mode === 'soal' && foundSoal) {
            // Skip context di dalam soal (Kategori:, Topik:, dll)
            const isContext = /^[A-Z][a-z\s-]+\s*[:=]/.test(trimmed) && 
                             !trimmed.match(/^[A-Ea-e]\s*[.):\]]/);
            
            if (!isContext) {
                soalParts.push(trimmed);
            }
        } else if (mode === 'pembahasan') {
            pembahasanParts.push(trimmed);
        }
    }
    
    soal.soal = soalParts.join(' ').trim();
    soal.pembahasan = pembahasanParts.join(' ').trim();
    
    return soal;
}

// ============================================================
// MERGE CONTEXT — Gabung context global dengan soal
// VERSI FINAL: Support jenjang & kelas
// ============================================================
function mergeContext(soal, context) {
    return {
        // Hierarki (10 field tetap)
        kategori: context.kategori || null,
        bidang: context.bidang || null,
        program: context.program || null,
        jenjang: context.jenjang || null,        // 🆕
        kelas: context.kelas || null,            // 🆕
        topik: context.topik || null,
        subtopik: context.subtopik || null,
        kisi: context.kisi || null,
        kemampuan: context.kemampuan || null,
        subKemampuan: context.subKemampuan || null,
        
        // Master data
        caraPenyajian: context.caraPenyajian || null,
        tipeIsi: context.tipeIsi || null,
        kompleksitas: context.kompleksitas || null,
        tahap: context.tahap || null,
        tipeHots: context.tipeHots || null,
        levelHots: context.levelHots || null,
        tingkatKesulitan: context.tingkatKesulitan || null,
        lapisan: context.lapisan || null,
        sumberReferensi: context.sumberReferensi || null,
        linkSumber: context.linkSumber || null,
        
        // 🆕 MEDIA LOKAL/URL
        imagePath: context.imagePath || null,
        videoPath: context.videoPath || null,
        audioPath: context.audioPath || null,
        
        // 🆕 MEDIA TELEGRAM
        imageFileId: context.imageFileId || null,
        videoFileId: context.videoFileId || null,
        audioFileId: context.audioFileId || null,
        
        // Metadata
        keabsahan: context.keabsahan || null,
        tahun: context.tahun || null,
        
        // Soal
        soal: soal.soal,
        pilihan_a: soal.pilihan_a,
        pilihan_b: soal.pilihan_b,
        pilihan_c: soal.pilihan_c,
        pilihan_d: soal.pilihan_d,
        pilihan_e: soal.pilihan_e,
        jawaban: soal.jawaban,
        pembahasan: soal.pembahasan || '',
        alasan_a: soal.alasan_a || '',
        alasan_b: soal.alasan_b || '',
        alasan_c: soal.alasan_c || '',
        alasan_d: soal.alasan_d || '',
        alasan_e: soal.alasan_e || ''
    };
}

// ============================================================
// FUNGSI SHOW KONFIRMASI UNIVERSAL
// Tampilkan klasifikasi untuk konfirmasi admin
// ============================================================

/**
 * Tampilkan konfirmasi klasifikasi untuk admin
 * @param {number} chatId - Chat ID
 * @param {Object} data - Data hasil klasifikasi
 * @param {number} currentIndex - Index soal yang ditampilkan (untuk multi soal)
 */
async function showUniversalConfirmation(chatId, data, currentIndex = 0) {
    const soal = data.soalList?.[0] || data.soal || {};
    const sources = data.sources || {};
    const finalData = data.data || data;
    const totalSoal = data.soalList?.length || 1;
    
    const badge = (field) => {
        const src = sources[field];
        if (src === 'manual') return '👤';
        if (src === 'ai') return '🤖';
        if (src === 'default') return '⚙️';
        if (src === 'auto-mapping') return '🔗';
        return '❓';
    };
    
    const val = (field, fallback = '-') => {
        const v = finalData[field];
        return v ? String(v) : fallback;
    };
    
    let msg = `📋 *KONFIRMASI SOAL ${currentIndex + 1}/${totalSoal}*\n\n`;
    
    const manualCount = Object.values(sources).filter(s => s === 'manual').length;
    const aiCount = Object.values(sources).filter(s => s === 'ai').length;
    const defaultCount = Object.values(sources).filter(s => s === 'default' || s === 'auto-mapping').length;
    
    msg += `📊 *Sumber Data:*\n`;
    msg += `👤 Manual (Admin): ${manualCount} field\n`;
    msg += `🤖 AI: ${aiCount} field\n`;
    msg += `⚙️ Default: ${defaultCount} field\n\n`;
    
    msg += `🏷️ *HIERARKI:*\n`;
    msg += `${badge('kategori')} Kategori: ${val('kategori')}\n`;
    msg += `${badge('bidang')} Bidang: ${val('bidang')}\n`;
    msg += `${badge('program')} Program: ${val('program')}\n`;
    msg += `${badge('topik')} Topik: ${val('topik')}\n`;
    msg += `${badge('subtopik')} Sub-Topik: ${val('subtopik')}\n`;
    msg += `${badge('kisi')} Kisi-Kisi: ${val('kisi')}\n`;
    msg += `${badge('kemampuan')} Kemampuan: ${val('kemampuan')}\n`;
    msg += `${badge('subKemampuan')} Sub-Kemampuan: ${val('subKemampuan')}\n\n`;
    
    msg += `📊 *MASTER DATA:*\n`;
    msg += `${badge('caraPenyajian')} Cara Penyajian: ${val('caraPenyajian')}\n`;
    msg += `${badge('tipeIsi')} Tipe Isi: ${val('tipeIsi')}\n`;
    msg += `${badge('tahap')} Tahap: ${val('tahap')}\n`;
    msg += `🔗 Kompleksitas: ${val('kompleksitas')}\n`;
    msg += `🧠 Proses Kognitif: ${getStoredCognitive({levelHots: val('levelHots'), tipeHots: val('tipeHots')})}\n`;
    msg += `🔗 Tipe HOTS: ${val('tipeHots')}\n`;
    msg += `🔗 Tingkat Kesulitan: ${val('tingkatKesulitan')}\n`;
    msg += `${badge('lapisan')} Lapisan: ${val('lapisan')}\n`;
    msg += `${badge('sumberReferensi')} Sumber: ${val('sumberReferensi')}\n`;
    msg += `${badge('linkSumber')} Link: ${val('linkSumber')}\n\n`;
    
    msg += `📌 *METADATA:*\n`;
    msg += `${badge('keabsahan')} Keabsahan: ${val('keabsahan')}\n`;
    msg += `${badge('tahun')} Tahun: ${val('tahun')}\n\n`;
    
    msg += `📝 *SOAL ${currentIndex + 1}/${totalSoal}:*\n`;
    msg += `${soal.soal || '-'}\n\n`;
    msg += `A. ${soal.pilihan_a || '-'}\n`;
    msg += `B. ${soal.pilihan_b || '-'}\n`;
    msg += `C. ${soal.pilihan_c || '-'}\n`;
    msg += `D. ${soal.pilihan_d || '-'}\n`;
    msg += `E. ${soal.pilihan_e || '-'}\n\n`;
    msg += `⭐ Jawaban: ${soal.jawaban || '-'}\n\n`;
    
    msg += `Legend:\n👤 Manual | 🤖 AI | ⚙️ Default | 🔗 Auto`;
    
    const keyboard = [];
    
    if (totalSoal > 1) {
        const navButtons = [];
        if (currentIndex > 0) {
            navButtons.push({ text: '⬅️ Prev', callback_data: `uni_nav_${currentIndex - 1}` });
        }
        navButtons.push({ text: `📄 ${currentIndex + 1}/${totalSoal}`, callback_data: 'uni_noop' });
        if (currentIndex < totalSoal - 1) {
            navButtons.push({ text: 'Next ➡️', callback_data: `uni_nav_${currentIndex + 1}` });
        }
        if (navButtons.length > 0) {
            keyboard.push(navButtons);
        }
    }
    
    keyboard.push([{ text: '✏️ Edit Klasifikasi', callback_data: `uni_edit_${currentIndex}` }]);
    keyboard.push([{ text: '📝 Edit Soal', callback_data: `uni_editsoal_${currentIndex}` }]);
    
    if (totalSoal > 1) {
        keyboard.push([
            { text: '✅ Simpan Semua', callback_data: 'uni_save_all' },
            { text: '❌ Batal', callback_data: 'uni_cancel' }
        ]);
    } else {
        keyboard.push([
            { text: '✅ Simpan', callback_data: 'uni_save_all' },
            { text: '❌ Batal', callback_data: 'uni_cancel' }
        ]);
    }
    
    await sendInlineKeyboard(chatId, msg, keyboard);
}

// ============================================================
// 🆕 HANDLE UPLOAD UNIVERSAL — VERSI UPDATE
// Support input NAMA atau KODE untuk master data
// VERSI FINAL: Support jenjang & kelas
// ============================================================
async function handleUniversalUpload(env, userId, chatId, text, db, mode = 'manual') {
    try {
        const parsed = parseUniversalFormat(text);
        
        if (parsed.soalList.length === 0) {
            await smartMessage(chatId, 
                `❌ *Tidak ada soal valid!*\n\n` +
                `Format minimal:\n` +
                `\`\`\`\n` +
                `SOAL: Siapa presiden pertama Indonesia?\n` +
                `A. Soekarno\n` +
                `B. Soeharto\n` +
                `C. Habibie\n` +
                `D. Gus Dur\n` +
                `E. SBY\n` +
                `JAWABAN: A\n` +
                `\`\`\`\n\n` +
                `💡 Tambahkan hierarki (opsional):\n` +
                `Kategori: CPNS\n` +
                `Topik: Pancasila`
            );
            return false;
        }
        
        // Cek field hierarki yang diisi user
        const manualFields = [];
        if (parsed.kategori) manualFields.push('Kategori');
        if (parsed.bidang) manualFields.push('Bidang');
        if (parsed.program) manualFields.push('Program');
        if (parsed.jenjang) manualFields.push('Jenjang');        // 🆕
        if (parsed.kelas) manualFields.push('Kelas');            // 🆕
        if (parsed.topik) manualFields.push('Topik');
        if (parsed.subtopik) manualFields.push('Sub-Topik');
        if (parsed.kisi) manualFields.push('Kisi-Kisi');
        if (parsed.kemampuan) manualFields.push('Kemampuan');
        if (parsed.subKemampuan) manualFields.push('Sub-Kemampuan');
        if (parsed.caraPenyajian) manualFields.push('Cara Penyajian');
        if (parsed.tipeIsi) manualFields.push('Tipe Isi');
        if (parsed.tahap) manualFields.push('Tahap');
        if (parsed.levelHots) manualFields.push('Proses Kognitif');
        if (parsed.keabsahan) manualFields.push('Keabsahan');
        if (parsed.tahun) manualFields.push('Tahun');
        
        let infoMsg = `📥 *${parsed.soalList.length} soal diterima*\n\n`;
        
        if (manualFields.length > 0) {
            infoMsg += `👤 *Field dari Anda (${manualFields.length}):*\n`;
            infoMsg += manualFields.join(', ') + `\n\n`;
        } else {
            infoMsg += `⚠️ *Tidak ada field manual*\nAI akan mengisi semua.\n\n`;
        }
        
        infoMsg += `⏳ Menganalisis...`;
        await smartMessage(chatId, infoMsg);
        
        // ============================================================
        // ANALISIS SETIAP SOAL
        // ============================================================
        const analyzedSoalList = [];
        
        for (let i = 0; i < parsed.soalList.length; i++) {
            const soal = parsed.soalList[i];
            
            // 🆕 RESOLVE MASTER DATA DARI NAMA (Partial Match)
            const resolved = await resolveMasterFromInput(db, {
                caraPenyajian: soal.caraPenyajian,
                tipeIsi: soal.tipeIsi,
                tahap: soal.tahap,
                sumberReferensi: soal.sumberReferensi,
                lapisan: soal.lapisan
            });
            
            // Kalau ada ambiguitas, tampilkan pilihan
            if (resolved.ambigu && resolved.ambiguList.length > 0) {
                let ambigMsg = `⚠️ *AMBIGU — Ada ${resolved.ambiguList.length} pilihan untuk "${resolved.ambiguField}"*\n\n`;
                ambigMsg += `Field: *${resolved.ambiguField}*\n`;
                ambigMsg += `Input: \`${resolved.ambiguInput}\`\n\n`;
                ambigMsg += `📋 *Pilihan yang ditemukan:*\n\n`;
                
                resolved.ambiguList.forEach((item, idx) => {
                    ambigMsg += `${idx + 1}. *${item.id}* — ${item.nama}\n`;
                });
                
                ambigMsg += `\n💡 *Solusi:*\n`;
                ambigMsg += `Ketik ulang dengan nama yang lebih spesifik,\n`;
                ambigMsg += `atau gunakan kode (mis. \`${resolved.ambiguList[0].id}\`).\n\n`;
                ambigMsg += `Ketik /soal_add untuk mulai lagi.`;
                
                await smartMessage(chatId, ambigMsg);
                return false;
            }
            
            // Gabung hasil resolve ke soal
            if (resolved.caraPenyajian) soal.caraPenyajian = resolved.caraPenyajian;
            if (resolved.tipeIsi) soal.tipeIsi = resolved.tipeIsi;
            if (resolved.tahap) soal.tahap = resolved.tahap;
            if (resolved.sumberReferensi) soal.sumberReferensi = resolved.sumberReferensi;
            if (resolved.lapisan) soal.lapisan = resolved.lapisan;
            
            // Extract admin input dari soal
            const adminInput = {
                kategori: soal.kategori,
                bidang: soal.bidang,
                program: soal.program,
                jenjang: soal.jenjang,        // 🆕
                kelas: soal.kelas,            // 🆕
                topik: soal.topik,
                subtopik: soal.subtopik,
                kisi: soal.kisi,
                kemampuan: soal.kemampuan,
                subKemampuan: soal.subKemampuan,
                caraPenyajian: soal.caraPenyajian,
                tipeIsi: soal.tipeIsi,
                tahap: soal.tahap,
                levelHots: soal.levelHots,
                lapisan: soal.lapisan,
                sumberReferensi: soal.sumberReferensi,
                linkSumber: soal.linkSumber,
                imagePath: soal.imagePath,
                videoPath: soal.videoPath,
                audioPath: soal.audioPath,
                imageFileId: soal.imageFileId,
                videoFileId: soal.videoFileId,
                audioFileId: soal.audioFileId,
                keabsahan: soal.keabsahan,
                tahun: soal.tahun
            };
            
            const analyzed = await analyzeSoalSmart(db, soal, adminInput, { mode });
            
            // Simpan data soal untuk disimpan nanti
            analyzed.soalList = [{
                soal: soal.soal,
                pilihan_a: soal.pilihan_a,
                pilihan_b: soal.pilihan_b,
                pilihan_c: soal.pilihan_c,
                pilihan_d: soal.pilihan_d,
                pilihan_e: soal.pilihan_e,
                jawaban: soal.jawaban,
                pembahasan: soal.pembahasan
            }];
            
            analyzedSoalList.push(analyzed);
            
            if ((i + 1) % 5 === 0) {
                await smartMessage(chatId, `⏳ Progress: ${i + 1}/${parsed.soalList.length}...`);
            }
        }
        
        // Simpan session
        const session = await getSession(env, userId);
        session.universalUpload = {
            soalList: analyzedSoalList,
            currentIndex: 0,
            timestamp: Date.now()
        };
        await saveSession(env, userId, session);
        
        await showUniversalConfirmation(chatId, analyzedSoalList[0], 0);
        return true;
        
    } catch (e) {
        console.error('handleUniversalUpload error:', e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
        return false;
    }
}

// ============================================================
// 🆕 HELPER: RESOLVE MASTER DARI INPUT (NAMA atau KODE)
// ============================================================
async function resolveMasterFromInput(db, input) {
    const result = {
        caraPenyajian: null,
        tipeIsi: null,
        tahap: null,
        sumberReferensi: null,
        lapisan: null,
        ambigu: false,
        ambiguField: null,
        ambiguInput: null,
        ambiguList: []
    };
    
    // Mapping field → tabel
    const masterMap = {
        caraPenyajian: { table: 'cara_penyajian', idField: 'id', nameField: 'nama', label: 'Cara Penyajian' },
        tipeIsi: { table: 'tipe_isi_soal', idField: 'id', nameField: 'nama', label: 'Tipe Isi' },
        tahap: { table: 'tahap_pembelajaran', idField: 'id', nameField: 'nama', label: 'Tahap' },
        sumberReferensi: { table: 'sumber_belajar', idField: 'id', nameField: 'nama', label: 'Sumber' },
        lapisan: { table: 'lapisan_pembelajaran', idField: 'id', nameField: 'nama', label: 'Lapisan' }
    };
    
    for (const [field, config] of Object.entries(masterMap)) {
        const inputValue = input[field];
        
        if (!inputValue || String(inputValue).trim() === '') {
            continue;
        }
        
        const found = await findMasterByNama(
            db, 
            config.table, 
            inputValue, 
            config.idField, 
            config.nameField
        );
        
        if (found.ambigu) {
            result.ambigu = true;
            result.ambiguField = config.label;
            result.ambiguInput = inputValue;
            result.ambiguList = found.list.slice(0, 10);
            return result;
        }
        
        if (found.found) {
            // Simpan ID (bukan nama)
            result[field] = found.id;
        } else {
            // Tidak ditemukan → biarkan kosong (AI fill)
            result[field] = null;
            console.log(`⚠️ ${config.label} "${inputValue}" tidak ditemukan → AI fill`);
        }
    }
    
    return result;
}

console.log('✅ [HELPER] resolveMasterFromInput loaded');



// ============================================================
// AUTO-CLASSIFY COMPLETE — Dengan hint field yang perlu diisi
// ============================================================
async function autoClassifyComplete(soalText, pilihanJawaban = null, db = null, options = {}) {
    const { fillOnly = null, adminContext = null } = options;
    
    const cacheOptions = { fillOnly, adminContext };
    const cached = getCachedAutoClassify(soalText, pilihanJawaban, cacheOptions);
    if (cached && !fillOnly) {
        return cached;
    }

    const classification = await autoClassifyWithAI(
        soalText, 
        pilihanJawaban, 
        { fillOnly, adminContext, env: options.env || RUNTIME_ENV || null }
    );
    
    if (db && classification) {
        classification.masterIds = await getMasterIdsComplete(db, classification);
    }
    
    if (!fillOnly) {
        setCachedAutoClassify(soalText, pilihanJawaban, classification, cacheOptions);
    }
    
    return classification;
}

// ============================================================
// 🆕 GET OR CREATE HIERARKI — Cari/buat hierarki manual
// ============================================================
async function getOrCreateHierarki(db, table, nameField, nameValue, prefix, parentField = null, parentId = null, createdItems = []) {
    const cleanValue = String(nameValue).trim();
    if (!cleanValue) return null;
    
    try {
        if (parentField && !parentId) {
            console.warn(`⚠️ ${table}: parent ${parentField} kosong untuk "${cleanValue}"`);
            return null;
        }
        
        // TOPIK harus selalu melalui resolver terpusat agar normalized_nama
        // dan konteks parent (Program/Mapel/Matkul) tidak terlewat.
        if (table === 'topik') {
            const topic = await getOrCreateTopicStrict(db, {
                name: cleanValue,
                programId: parentField === 'program_studi_id' ? parentId : null,
                mataPelajaranId: parentField === 'mata_pelajaran_id' ? parentId : null,
                mataKuliahId: parentField === 'mata_kuliah_id' ? parentId : null,
                autoCreate: true,
                prefix
            });
            if (topic.id && topic.created) createdItems.push(`🆕 topik: ${cleanValue} [${topic.id}]`);
            return topic.id || null;
        }

        let query = `SELECT id FROM ${table} WHERE LOWER(TRIM(${nameField})) = LOWER(TRIM(?))`;
        let bind = [cleanValue];
        
        if (parentField && parentId) {
            query += ` AND ${parentField} = ?`;
            bind.push(parentId);
        }
        query += ` LIMIT 1`;
        
        const existing = await db.prepare(query).bind(...bind).first();
        
        if (existing) {
            return existing.id;
        }
        
        let newId;
        if (table === 'kemampuan_diuji') {
            newId = await generateKemampuanId(db);
        } else if (table === 'sub_kemampuan') {
            newId = await generateSubKemampuanId(db);
        } else {
            newId = await generateId(db, prefix, table);
        }
        
        const insertFields = ['id', nameField];
        const insertValues = [newId, cleanValue];
        
        if (parentField && parentId) {
            insertFields.push(parentField);
            insertValues.push(parentId);
        }
        
        insertFields.push('created_at');
        insertValues.push(new Date().toISOString());
        
        const placeholders = insertFields.map(() => '?').join(', ');
        await db.prepare(`
            INSERT INTO ${table} (${insertFields.join(', ')}) 
            VALUES (${placeholders})
        `).bind(...insertValues).run();
        
        createdItems.push(`🆕 ${table}: ${cleanValue} [${newId}]`);
        return newId;
        
    } catch (e) {
        console.error(`getOrCreateHierarki error for ${table}:`, e);
        return null;
    }
}

// ============================================================
// 🆕 ANALYZE SOAL SMART — Admin prioritas, AI fallback
// ============================================================
async function analyzeSoalSmart(db, soal, adminInput = {}, options = {}) {
    const { mode = 'manual', showDebug = false } = options;
    
    const ALL_FIELDS = {
        // Hierarki
        kategori: 'Kategori',
        bidang: 'Bidang Studi',
        program: 'Program Studi',
        topik: 'Topik',
        subtopik: 'Sub-Topik',
        kisi: 'Kisi-Kisi',
        kemampuan: 'Kemampuan',
        subKemampuan: 'Sub-Kemampuan',
        
        // Master data
        caraPenyajian: 'Cara Penyajian',
        tipeIsi: 'Tipe Isi',
        tahap: 'Tahap Pembelajaran',
        prosesKognitif: 'Proses Kognitif',
        lapisan: 'Lapisan',
        sumberReferensi: 'Sumber Referensi',
        namaSumber: 'Nama Sumber',
        linkSumber: 'Link Sumber',
        
        // 🆕 Media
        imagePath: 'Image',
        videoPath: 'Video',
        audioPath: 'Audio',
        imageFileId: 'Image File ID',
        videoFileId: 'Video File ID',
        audioFileId: 'Audio File ID',
        
        // Metadata
        keabsahan: 'Keabsahan',
        tahun: 'Tahun'
    };
    
    const adminValues = {};
    const aiValues = {};
    const sources = {};
    const missingFields = [];
    
    // Ekstrak nilai admin
    for (const field of Object.keys(ALL_FIELDS)) {
        const adminVal = adminInput[field];
        
        if (adminVal !== null && adminVal !== undefined && String(adminVal).trim() !== '') {
            adminValues[field] = String(adminVal).trim();
            sources[field] = 'manual';
        } else {
            missingFields.push(field);
        }
    }
    
    if (showDebug) {
        console.log('👤 Admin values:', adminValues);
        console.log('❓ Missing fields:', missingFields);
    }
    
    // Field yang butuh AI (bukan auto-mapping)
    const autoMappingFields = ['kompleksitas', 'tipeHots', 'tingkatKesulitan'];
    const needsAI = missingFields.filter(f => !autoMappingFields.includes(f));
    
    let aiResult = null;
    
    const aiWorthyFields = [
        'kategori', 'bidang', 'program', 'topik', 'subtopik',
        'kisi', 'kemampuan', 'subKemampuan',
        'caraPenyajian', 'tipeIsi', 'tahap', 'prosesKognitif'
    ];
    
    const needAICall = needsAI.some(f => aiWorthyFields.includes(f));
    
    // Panggil AI hanya kalau perlu
    if (needAICall && soal.soal) {
        try {
            const pilihanJawaban = `A. ${soal.pilihan_a || ''}\nB. ${soal.pilihan_b || ''}\nC. ${soal.pilihan_c || ''}\nD. ${soal.pilihan_d || ''}\nE. ${soal.pilihan_e || ''}`;
            
            const emptyFieldsList = needsAI.filter(f => aiWorthyFields.includes(f));
            
            if (showDebug) {
                console.log('🤖 AI dipanggil untuk field:', emptyFieldsList);
            }
            
            aiResult = await autoClassifyComplete(
                soal.soal, 
                pilihanJawaban, 
                db,
                { 
                    fillOnly: emptyFieldsList,
                    adminContext: adminValues
                }
            );
            
            for (const field of emptyFieldsList) {
                const aiVal = aiResult[field];
                if (aiVal !== null && aiVal !== undefined && String(aiVal).trim() !== '') {
                    aiValues[field] = String(aiVal).trim();
                    sources[field] = 'ai';
                }
            }
            
        } catch (e) {
            console.error('AI classify error:', e);
            const ruleResult = ruleBasedClassifyComplete(soal.soal);
            for (const field of needsAI) {
                if (ruleResult[field]) {
                    aiValues[field] = ruleResult[field];
                    sources[field] = 'ai';
                }
            }
        }
    }
    
    // Merge: Admin > AI > Default
    const final = {};
    
    for (const field of Object.keys(ALL_FIELDS)) {
        if (adminValues[field] !== undefined) {
            final[field] = adminValues[field];
            sources[field] = 'manual';
        } else if (aiValues[field] !== undefined) {
            final[field] = aiValues[field];
            sources[field] = 'ai';
        } else {
            final[field] = null;
            sources[field] = 'default';
        }
    }
    
    // Auto-mapping
    const prosesKognitif = getProsesKognitif(final.prosesKognitif || final.tipeHots, final.levelHots) || 'LOTS';
    const tahapId = final.tahap || 'T1';
    
    final.kompleksitas = getKompleksitasFromTahap(tahapId);
    final.tipeHots = prosesKognitif;
    final.tingkatKesulitan = getDefaultDifficulty(final.tingkatKesulitan);
    
    if (!final.lapisan) {
        final.lapisan = getLapisanFromTahap(tahapId);
        if (sources.lapisan === 'default') sources.lapisan = 'auto-mapping';
    }
    
    if (!final.keabsahan) {
        final.keabsahan = 'MANDIRI';
        sources.keabsahan = 'default';
    }
    if (!final.tahun) {
        final.tahun = new Date().getFullYear().toString();
        sources.tahun = 'default';
    }
    
    return {
        soalList: [soal],
        data: final,
        sources: sources,
        usedAI: needAICall,
        aiCalledFor: needAICall ? needsAI.filter(f => aiWorthyFields.includes(f)) : [],
        adminFilledCount: Object.values(sources).filter(s => s === 'manual').length,
        aiFilledCount: Object.values(sources).filter(s => s === 'ai').length,
        defaultCount: Object.values(sources).filter(s => s === 'default').length
    };
}

// ============================================================
// 🆕 SAVE SOAL MANUAL — Simpan dengan data final
// VERSI FIXED: Tambah koma di data.namaSumber
// ============================================================
async function saveSoalManual(db, soalData, options = {}) {
    const {
        soalText,
        pilihanA = '', pilihanB = '', pilihanC = '', pilihanD = '', pilihanE = '',
        jawabanBenar = '',
        pembahasan = '',
        alasanA = '', alasanB = '', alasanC = '', alasanD = '', alasanE = '',
        data = {},
        sources = {},
        userId = null
    } = soalData;
    
    const questionContract = validateQuestionContract({
        soalText, pilihanA, pilihanB, pilihanC, pilihanD, pilihanE, jawabanBenar,
        alasanA, alasanB, alasanC, alasanD, alasanE,
        jenisSoal: data.jenisSoal || data.jenis_soal || data.questionType,
        tingkatKesulitan: data.tingkatKesulitan || data.tingkat_kesulitan || 'SEDANG',
        levelHots: data.levelHots,
        statusKeabsahan: data.keabsahan || data.statusKeabsahan,
        tahun: data.tahun
    });
    if (!questionContract.valid) return { success:false, error:questionContract.errors.join(' ') };
    
    try {
        // ============================================================
        // 1. HIERARKI
        // ============================================================
        const masterIds = {
            kategoriId: null, bidangId: null, programId: null,
            mataPelajaranId: data.mataPelajaranId || data.mata_pelajaran_id || null,
            mataKuliahId: data.mataKuliahId || data.mata_kuliah_id || null,
            jenjangId: data.jenjangId || data.jenjang_id || null,
            kelas: data.kelas || null,
            topikId: null, subtopikId: null, kisiId: null,
            kemampuanId: null, subKemampuanId: null
        };
        
        const createdItems = [];
        
        if (data.kategori) {
            masterIds.kategoriId = await getOrCreateHierarki(
                db, 'kategori', 'nama', data.kategori, 'K', null, null, createdItems
            );
        }
        
        if (data.bidang && masterIds.kategoriId) {
            masterIds.bidangId = await getOrCreateHierarki(
                db, 'bidang_studi', 'nama', data.bidang, 'B',
                'kategori_id', masterIds.kategoriId, createdItems
            );
        }
        
        if (data.program && masterIds.bidangId) {
            masterIds.programId = await getOrCreateHierarki(
                db, 'program_studi', 'nama', data.program, 'P',
                'bidang_studi_id', masterIds.bidangId, createdItems
            );
        }
        
        if (data.topik && masterIds.programId) {
            masterIds.topikId = await getOrCreateHierarki(
                db, 'topik', 'nama', data.topik, 'T',
                'program_studi_id', masterIds.programId, createdItems
            );
        }
        
        if (data.subtopik && masterIds.topikId) {
            masterIds.subtopikId = await getOrCreateHierarki(
                db, 'sub_topik', 'nama', data.subtopik, 'S',
                'topik_id', masterIds.topikId, createdItems
            );
        }
        
        if (data.kisi && masterIds.subtopikId) {
            masterIds.kisiId = await getOrCreateHierarki(
                db, 'kisi_kisi', 'judul', data.kisi, 'I',
                'sub_topik_id', masterIds.subtopikId, createdItems
            );
        }
        
        if (data.kemampuan && masterIds.kisiId) {
            masterIds.kemampuanId = await getOrCreateHierarki(
                db, 'kemampuan_diuji', 'nama', data.kemampuan, 'KM',
                'kisi_kisi_id', masterIds.kisiId, createdItems
            );
        }
        
        if (data.subKemampuan && masterIds.kemampuanId) {
            masterIds.subKemampuanId = await getOrCreateHierarki(
                db, 'sub_kemampuan', 'nama', data.subKemampuan, 'SK',
                'kemampuan_id', masterIds.kemampuanId, createdItems
            );
        }
        
        // ============================================================
        // 2. CARI ID MASTER DATA
        // ============================================================
        let penyajianId = null, tipeIsiId = null, tahapId = null, lapisanId = null;
        
        if (data.caraPenyajian) {
            const kode = data.caraPenyajian.match(/P\d{2}/) ? data.caraPenyajian.match(/P\d{2}/)[0] : data.caraPenyajian;
            const row = await db.prepare(
                `SELECT id FROM cara_penyajian WHERE kode_utama = ? OR id = ? LIMIT 1`
            ).bind(kode, kode).first();
            penyajianId = row?.id || null;
        }
        
        if (data.tipeIsi) {
            const kode = data.tipeIsi.match(/TI\d{2}/) ? data.tipeIsi.match(/TI\d{2}/)[0] : data.tipeIsi;
            const row = await db.prepare(
                `SELECT id FROM tipe_isi_soal WHERE kode_utama = ? OR id = ? LIMIT 1`
            ).bind(kode, kode).first();
            tipeIsiId = row?.id || null;
        }
        
        if (data.tahap) {
            const kode = data.tahap.match(/T\d/) ? data.tahap.match(/T\d/)[0] : data.tahap;
            const row = await db.prepare(
                `SELECT id FROM tahap_pembelajaran WHERE id = ? LIMIT 1`
            ).bind(kode).first();
            tahapId = row?.id || null;
        }
        
        if (data.lapisan) {
            const level = parseInt(data.lapisan);
            if (!isNaN(level)) {
                const row = await db.prepare(
                    `SELECT id FROM lapisan_pembelajaran WHERE level = ? LIMIT 1`
                ).bind(level).first();
                lapisanId = row?.id || null;
            }
        }
        
        // ============================================================
        // 3. CARI SUMBER BELAJAR
        // ============================================================
        let sumberId = null;
        
        if (data.namaSumber) {
            const row = await db.prepare(
                `SELECT id FROM sumber_belajar WHERE LOWER(TRIM(nama)) LIKE LOWER(TRIM(?)) LIMIT 1`
            ).bind(`%${data.namaSumber}%`).first();
            sumberId = row?.id || null;
        }
        
        if (!sumberId && data.sumberReferensi) {
            const row = await db.prepare(
                `SELECT id FROM sumber_belajar WHERE LOWER(TRIM(nama)) LIKE LOWER(TRIM(?)) OR LOWER(TRIM(id)) = LOWER(TRIM(?)) LIMIT 1`
            ).bind(`%${data.sumberReferensi}%`, data.sumberReferensi).first();
            sumberId = row?.id || null;
        }
        
        // ============================================================
        // 4. INSERT KE DATABASE
        // ============================================================
        const prosesKognitif = getProsesKognitif(data.prosesKognitif || data.proses_kognitif || data.tipeHots || data.tipe_hots) || 'LOTS';
        const tahapKode = data.tahap || 'T1';
        
        const preValidation = validateQuestionFull({
            soal: soalText, pilihanA, pilihanB, pilihanC, pilihanD, pilihanE, jawabanBenar,
            jenisSoal: questionContract.jenis_soal, tingkatKesulitan: questionContract.tingkat_kesulitan,
            statusKeabsahan: String(data.keabsahan || 'MANDIRI').toUpperCase(),
            sumberBelajarId: sumberId, namaSumber: data.namaSumber, sumberLink: data.linkSumber, tahun: data.tahun
        });
        if (!preValidation.valid) return { success:false, error:`Validasi soal gagal: ${preValidation.errors.join(' ')}` };
        const duplicateRows = await findDuplicateQuestions(db, {soal:soalText,pilihanA,pilihanB,pilihanC,pilihanD,pilihanE});
        if (duplicateRows.length) return {success:false,error:`Soal duplikat: ${duplicateRows.map(x=>x.id).join(', ')}`};
        const id = await generateId(db, 'Q', 'soal');
        const tanggalInput = new Date().toISOString();
        
        // ============================================================
        // FIX A3: SQL INSERT DIPERBAIKI
        // - Koma ditambah setelah nama_sumber
        // - created_by & updated_by dimasukkan ke .bind()
        // ============================================================
        await db.prepare(`
            INSERT INTO soal (
                id, soal, pilihan_a, pilihan_b, pilihan_c, pilihan_d, pilihan_e, jawaban_benar, pembahasan,
                alasan_a, alasan_b, alasan_c, alasan_d, alasan_e,
                kategori_id, bidang_studi_id, program_studi_id, mata_pelajaran_id, mata_kuliah_id,
                jenjang_id, kelas, topik_id, sub_topik_id,
                kisi_kisi_id, kemampuan_id, sub_kemampuan_id,
                cara_penyajian_id, tipe_isi_id, kompleksitas, tahap_pembelajaran_id,
                tipe_hots, level_hots, tingkat_kesulitan, lapisan_pembelajaran_id,
                sumber_belajar_id, nama_sumber, sumber_link, tahun, status_keabsahan,
                status, tipe_soal, jenis_soal, tanggal_input,
                image_path, video_path, audio_path,
                image_file_id, video_file_id, audio_file_id,
                created_by, updated_by
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
            id, soalText, pilihanA, pilihanB, pilihanC, pilihanD, pilihanE,
            jawabanBenar.toUpperCase(),
            pembahasan || null,
            alasanA || null, alasanB || null, alasanC || null, alasanD || null, alasanE || null,
            masterIds.kategoriId, masterIds.bidangId, masterIds.programId,
            masterIds.mataPelajaranId, masterIds.mataKuliahId,
            masterIds.jenjangId, masterIds.kelas,
            masterIds.topikId, masterIds.subtopikId, masterIds.kisiId,
            masterIds.kemampuanId, masterIds.subKemampuanId,
            penyajianId, tipeIsiId,
            getKompleksitasFromTahap(tahapKode),
            tahapId,
            prosesKognitif,
            null,
            getDefaultDifficulty(data.tingkatKesulitan || data.tingkat_kesulitan),
            lapisanId,
            sumberId,
            data.namaSumber || null,
            data.linkSumber || null,
            data.tahun || null,
            (data.keabsahan || 'mandiri').toLowerCase(),
            'AKTIF', 'PG', questionContract.jenis_soal, tanggalInput,
            // MEDIA
            data.imagePath || null,
            data.videoPath || null,
            data.audioPath || null,
            data.imageFileId || null,
            data.videoFileId || null,
            data.audioFileId || null,
            // USER TRACKING
            userId || null,
            userId || null
        ).run();
        
        return {
            success: true,
            id: id,
            masterIds: masterIds,
            createdItems: createdItems
        };
        
    } catch (e) {
        console.error('saveSoalManual error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 🆕 BUILD PROMPT DINAMIS — Hanya minta field yang kosong
// VERSI FINAL: Support jenjang & kelas
// ============================================================
function buildAutoClassifyPromptDynamic(soalText, pilihanJawaban = null, fillOnly = null, adminContext = null) {
    // Default: minta semua
    const allFields = {
        kategori: 'Kategori (contoh: Matematika, IPA, IPS, Bahasa)',
        bidang: 'Bidang Studi (contoh: Matematika Dasar, Fisika)',
        program: 'Program Studi (contoh: S1 Matematika)',
        jenjang: 'Jenjang Pendidikan (SD, SMP, SMA, SMK, D3, D4, S1, S2, S3)',      // 🆕
        kelas: 'Kelas (1-12 untuk SD/SMP/SMA, kosongkan kalau tidak relevan)',      // 🆕
        topik: 'Topik spesifik (contoh: Aljabar, Kalkulus)',
        subtopik: 'Sub-Topik (contoh: Persamaan Linear)',
        kisi: 'Kisi-Kisi (contoh: UTS Aljabar)',
        kemampuan: 'Kemampuan yang diuji (contoh: Pemahaman Konsep)',
        subKemampuan: 'Sub-Kemampuan (contoh: Operasi Matriks)',
        caraPenyajian: 'Cara Penyajian (P01-P16)',
        tipeIsi: 'Tipe Isi (TI01-TI12)',
        tahap: 'Tahap Pembelajaran (T1-T9)',
        prosesKognitif: 'Proses Kognitif (LOTS, MOTS, atau HOTS)',
        tingkatKesulitan: 'Tingkat Kesulitan (Mudah, Sedang, Sulit, atau Kompleks)',
        sumber: 'Sumber referensi (nama buku/website)',
        link: 'Link sumber (URL)',
        keabsahan: 'Keabsahan (resmi/adaptasi/mandiri)'
    };
    
    // Tentukan field yang diminta
    const fieldsToAsk = fillOnly && fillOnly.length > 0 
        ? fillOnly.filter(f => allFields[f])
        : Object.keys(allFields);
    
    // Build daftar field
    let fieldsList = '';
    let jsonExample = '{\n';
    
    fieldsToAsk.forEach((field, idx) => {
        fieldsList += `\n${idx + 1}. ${field.toUpperCase()}:\n   ${allFields[field]}\n`;
        jsonExample += `    "${field}": "...",\n`;
    });
    
    jsonExample = jsonExample.replace(/,\n$/, '\n}');
    
    // Info konteks dari Admin (kalau ada)
    let adminContextStr = '';
    if (adminContext && Object.keys(adminContext).length > 0) {
        adminContextStr = `\n\nKONTEKS DARI ADMIN (jangan diubah):\n`;
        for (const [key, val] of Object.entries(adminContext)) {
            adminContextStr += `- ${key}: ${val}\n`;
        }
    }
    
    return `
Analisis soal berikut dan tentukan klasifikasinya:

SOAL: "${soalText}"

${pilihanJawaban ? `PILIHAN: ${pilihanJawaban}` : ''}
${adminContextStr}

TUGAS: Isi field berikut:
${fieldsList}

Output HARUS JSON valid (tanpa teks lain):
${jsonExample}

⚠️ PENTING:
- Hanya isi field yang diminta di atas
- JANGAN tambahkan field lain
- Nilai harus SINGKAT dan SPESIFIK
- Kalau tidak yakin, berikan nilai terbaik berdasarkan analisis
- Khusus JENJANG & KELAS: hanya isi kalau soal MEMANG untuk jenjang/kelas tersebut
  (misal: "Soal untuk kelas 5 SD" → jenjang: "SD", kelas: "5")
  Kalau tidak jelas, kosongkan (null)
`;
}

// ============================================================
// FUNGSI SIMPAN UNIVERSAL — VERSI FINAL (FIXED + JENJANG & KELAS)
// Support 36 kolom + auto-resolve jenjang & kelas
// ============================================================
async function saveUniversalAll(env, userId, chatId, db) {
    try {
        const session = await getSession(env, userId);
        
        if (!session.universalUpload || !session.universalUpload.soalList) {
            await smartResponseUniversal(chatId, '❌ Tidak ada data untuk disimpan.');
            return;
        }
        
        const soalList = session.universalUpload.soalList;
        
        await smartResponseUniversal(chatId, `⏳ Menyimpan ${soalList.length} soal...`);
        
        let successCount = 0;
        let errorCount = 0;
        let errors = [];
        let savedIds = [];
        let allCreatedItems = [];
        
        for (let i = 0; i < soalList.length; i++) {
            const data = soalList[i];
            const soal = data.soalList?.[0] || data.soal;
            
            if (!soal) {
                errorCount++;
                errors.push(`Soal ${i+1}: Data soal tidak ditemukan`);
                continue;
            }
            
            try {
                // ============================================================
                // 1. CARI ATAU BUAT MASTER DATA (semua hierarki)
                // Pakai getMasterIdsComplete yang sudah di-patch
                // ============================================================
                const classificationForIds = {
                    // Hierarki
                    kategori: data.kategori || data.data?.kategori,
                    bidang: data.bidang || data.data?.bidang,
                    program: data.program || data.data?.program,
                    jenjang: data.jenjang || data.data?.jenjang,        // 🆕
                    kelas: data.kelas || data.data?.kelas,              // 🆕
                    topik: data.topik || data.data?.topik,
                    subtopik: data.subtopik || data.data?.subtopik,
                    kisi: data.kisi || data.data?.kisi,
                    kemampuan: data.kemampuan || data.data?.kemampuan,
                    subKemampuan: data.subKemampuan || data.data?.subKemampuan,
                    
                    // Master
                    caraPenyajian: data.caraPenyajian || data.data?.caraPenyajian,
                    tipeIsi: data.tipeIsi || data.data?.tipeIsi,
                    tahap: data.tahap || data.data?.tahap,
                    levelHots: null,
                    lapisan: data.lapisan || data.data?.lapisan,
                    sumber: data.sumber || data.data?.sumber,
                    keabsahan: data.keabsahan || data.data?.keabsahan
                };
                
                const masterIds = await getMasterIdsComplete(db, classificationForIds, true);
                
                // Kumpulkan item baru yang dibuat
                if (masterIds.createdItems && masterIds.createdItems.length > 0) {
                    allCreatedItems.push(...masterIds.createdItems);
                }
                
                // ============================================================
                // 2. GENERATE ID SOAL
                // ============================================================
                const soalId = await generateId(db, 'Q', 'soal');
                const tanggalInput = new Date().toISOString();
                
                // ============================================================
                // 3. AMBIL NILAI FINAL (dengan fallback berlapis)
                // ============================================================
                const tahapKode = data.tahap || data.data?.tahap || 'T1';
                
                const kompleksitas = data.kompleksitas 
                    || data.data?.kompleksitas 
                    || getKompleksitasFromTahap(tahapKode);
                
                const tipeHots = getProsesKognitif(
                    data.prosesKognitif || data.proses_kognitif || data.tipeHots || data.data?.tipeHots
                ) || 'LOTS';
                
                const tingkatKesulitan = getDefaultDifficulty(data.tingkatKesulitan || data.data?.tingkatKesulitan);
                
                const keabsahan = (data.keabsahan || data.data?.keabsahan || 'mandiri').toLowerCase();
                const tahun = data.tahun || data.data?.tahun || null;
                
                const namaSumber = data.namaSumber 
                    || data.data?.namaSumber 
                    || null;
                
                const linkSumber = data.linkSumber 
                    || data.data?.linkSumber 
                    || data.sumber_link 
                    || null;
                
                const preValidation = validateQuestionFull({soal:soal.soal, pilihanA:soal.pilihan_a, pilihanB:soal.pilihan_b, pilihanC:soal.pilihan_c, pilihanD:soal.pilihan_d, pilihanE:soal.pilihan_e, jawabanBenar:soal.jawaban, jenisSoal:soal.jenis_soal || 'PEMAHAMAN', tingkatKesulitan:soal.tingkat_kesulitan || 'SEDANG', statusKeabsahan:String(keabsahan || 'MANDIRI').toUpperCase(), sumberBelajarId:masterIds.sumberId, namaSumber, sumberLink:linkSumber, tahun});
                if(!preValidation.valid) throw new Error(`Validasi soal gagal: ${preValidation.errors.join(' ')}`);
                const duplicateRows = await findDuplicateQuestions(db,{soal:soal.soal,pilihanA:soal.pilihan_a,pilihanB:soal.pilihan_b,pilihanC:soal.pilihan_c,pilihanD:soal.pilihan_d,pilihanE:soal.pilihan_e});
                if(duplicateRows.length) throw new Error(`Soal duplikat: ${duplicateRows.map(x=>x.id).join(', ')}`);

                // ============================================================
                // 4. INSERT SOAL — 36 KOLOM, 36 PARAMETER
                // Tambah jenjang_id & kelas
                // ============================================================
                await db.prepare(`
                    INSERT INTO soal (
                        id, soal, pilihan_a, pilihan_b, pilihan_c, pilihan_d, pilihan_e, jawaban_benar, pembahasan,
                        alasan_a, alasan_b, alasan_c, alasan_d, alasan_e,
                        kategori_id, bidang_studi_id, program_studi_id, topik_id, sub_topik_id,
                        jenjang_id, kelas,
                        kisi_kisi_id, kemampuan_id, sub_kemampuan_id,
                        cara_penyajian_id, tipe_isi_id, kompleksitas, tahap_pembelajaran_id,
                        tipe_hots, level_hots, tingkat_kesulitan, lapisan_pembelajaran_id,
                        sumber_belajar_id, nama_sumber, sumber_link, tahun, status_keabsahan,
                        status, tipe_soal, tanggal_input
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                `).bind(
                    soalId,
                    soal.soal || '',
                    soal.pilihan_a || '',
                    soal.pilihan_b || '',
                    soal.pilihan_c || '',
                    soal.pilihan_d || '',
                    soal.pilihan_e || '',
                    (soal.jawaban || '').toUpperCase(),
                    soal.pembahasan || null,
                    soal.alasan_a || soal.alasanA || null,
                    soal.alasan_b || soal.alasanB || null,
                    soal.alasan_c || soal.alasanC || null,
                    soal.alasan_d || soal.alasanD || null,
                    soal.alasan_e || soal.alasanE || null,
                    masterIds.kategoriId,
                    masterIds.bidangId,
                    masterIds.programId,
                    masterIds.topikId,
                    masterIds.subtopikId,
                    masterIds.jenjangId,        // 🆕
                    masterIds.kelas,            // 🆕
                    masterIds.kisiId,
                    masterIds.kemampuanId,
                    masterIds.subKemampuanId,
                    masterIds.penyajianId,
                    masterIds.tipeIsiId,
                    kompleksitas,
                    masterIds.tahapId,
                    tipeHots,
                    null,
                    tingkatKesulitan,
                    masterIds.lapisanId,
                    masterIds.sumberId,
                    namaSumber,
                    linkSumber,
                    tahun,
                    keabsahan,
                    'AKTIF',
                    'PG',
                    tanggalInput
                ).run();
                
                successCount++;
                savedIds.push(soalId);
                
            } catch (e) {
                errorCount++;
                errors.push(`Soal ${i+1}: ${e.message}`);
                console.error(`Save soal ${i+1} error:`, e);
            }
        }
        
        // ============================================================
        // 5. LAPORAN
        // ============================================================
        let response = `✅ *SIMPAN SELESAI*\n\n`;
        response += `📊 *Statistik:*\n`;
        response += `✅ Berhasil: ${successCount} soal\n`;
        response += `❌ Gagal: ${errorCount} soal\n\n`;
        
        if (savedIds.length > 0) {
            response += `🆔 *ID Soal:*\n`;
            savedIds.slice(0, 10).forEach(id => response += `- ${id}\n`);
            if (savedIds.length > 10) {
                response += `- ... dan ${savedIds.length - 10} lainnya\n`;
            }
            response += `\n`;
        }
        
        if (allCreatedItems.length > 0) {
            response += `🆕 *Data Baru Dibuat:*\n`;
            allCreatedItems.slice(0, 10).forEach(item => response += `${item}\n`);
            if (allCreatedItems.length > 10) {
                response += `... dan ${allCreatedItems.length - 10} lainnya\n`;
            }
            response += `\n`;
        }
        
        if (errors.length > 0) {
            response += `⚠️ *Error:*\n`;
            errors.slice(0, 5).forEach(e => response += `- ${e}\n`);
            if (errors.length > 5) {
                response += `- ... dan ${errors.length - 5} error lainnya\n`;
            }
        }
        
        await smartResponseUniversal(chatId, response, { mode: 'send' });
        
        // Clear session
        session.universalUpload = null;
        await saveSession(env, userId, session);
        
    } catch (e) {
        console.error('Save universal error:', e);
        await smartResponseUniversal(chatId, `❌ Error: ${e.message}`);
    }
}

// ============================================================
// CARI ATAU BUAT MASTER DATA — VERSI FINAL (LENGKAP)
// Ambil data dari `data` (flat) atau `data.data` (dari analyzeSoalSmart)
// ============================================================

async function getOrCreateMasterIds(db, data) {
    const result = {
        // Hierarki
        kategoriId: null,
        bidangId: null,
        programId: null,
        topikId: null,
        subtopikId: null,
        kisiId: null,
        kemampuanId: null,
        subKemampuanId: null,
        // Master data
        penyajianId: null,
        tipeIsiId: null,
        tahapId: null,
        lapisanId: null,
        sumberId: null,
        // Tracking
        createdItems: []
    };
    
    // ============================================================
    // HELPER: Normalisasi data — cek di `data` lalu `data.data`
    // ============================================================
    const getVal = (field) => {
        // Cek di data langsung
        if (data[field] !== null && data[field] !== undefined && String(data[field]).trim() !== '') {
            return String(data[field]).trim();
        }
        // Cek di data.data (dari analyzeSoalSmart)
        if (data.data && data.data[field] !== null && data.data[field] !== undefined && String(data.data[field]).trim() !== '') {
            return String(data.data[field]).trim();
        }
        return null;
    };
    
    // Ambil semua nilai (flat)
    const kategoriName = getVal('kategori');
    const bidangName = getVal('bidang');
    const programName = getVal('program');
    const topikName = getVal('topik');
    const subtopikName = getVal('subtopik');
    const kisiName = getVal('kisi');
    const kemampuanName = getVal('kemampuan');
    const subKemampuanName = getVal('subKemampuan');
    const caraPenyajian = getVal('caraPenyajian');
    const tipeIsi = getVal('tipeIsi');
    const tahap = getVal('tahap');
    const lapisan = getVal('lapisan');
    const sumberReferensi = getVal('sumberReferensi');
    
    try {
        // ============================================================
        // HIERARKI
        // ============================================================
        
        // ===== KATEGORI =====
        if (kategoriName) {
            const row = await db.prepare(
                `SELECT id FROM kategori WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) LIMIT 1`
            ).bind(kategoriName).first();
            
            if (row) {
                result.kategoriId = row.id;
            } else {
                const newId = await generateId(db, 'K', 'kategori');
                await db.prepare(
                    `INSERT INTO kategori (id, nama, created_at) VALUES (?, ?, ?)`
                ).bind(newId, kategoriName, new Date().toISOString()).run();
                result.kategoriId = newId;
                result.createdItems.push(`🆕 Kategori: ${kategoriName} [${newId}]`);
            }
        }
        
        // ===== BIDANG STUDI =====
        if (bidangName && result.kategoriId) {
            const row = await db.prepare(
                `SELECT id FROM bidang_studi WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND kategori_id = ? LIMIT 1`
            ).bind(bidangName, result.kategoriId).first();
            
            if (row) {
                result.bidangId = row.id;
            } else {
                const newId = await generateId(db, 'B', 'bidang_studi');
                await db.prepare(
                    `INSERT INTO bidang_studi (id, kategori_id, nama, created_at) VALUES (?, ?, ?, ?)`
                ).bind(newId, result.kategoriId, bidangName, new Date().toISOString()).run();
                result.bidangId = newId;
                result.createdItems.push(`🆕 Bidang: ${bidangName} [${newId}]`);
            }
        }
        
        // ===== PROGRAM STUDI =====
        if (programName && result.bidangId) {
            const row = await db.prepare(
                `SELECT id FROM program_studi WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND bidang_studi_id = ? LIMIT 1`
            ).bind(programName, result.bidangId).first();
            
            if (row) {
                result.programId = row.id;
            } else {
                const newId = await generateId(db, 'P', 'program_studi');
                await db.prepare(
                    `INSERT INTO program_studi (id, bidang_studi_id, nama, created_at) VALUES (?, ?, ?, ?)`
                ).bind(newId, result.bidangId, programName, new Date().toISOString()).run();
                result.programId = newId;
                result.createdItems.push(`🆕 Program: ${programName} [${newId}]`);
            }
        }
        
        // ===== TOPIK =====
        if (topikName && result.programId) {
            const row = await db.prepare(
                `SELECT id FROM topik WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND program_studi_id = ? LIMIT 1`
            ).bind(topikName, result.programId).first();
            
            if (row) {
                result.topikId = row.id;
            } else {
                const newId = await generateId(db, 'T', 'topik');
                await db.prepare(
                    `INSERT INTO topik (id, program_studi_id, nama, normalized_nama, created_at) VALUES (?, ?, ?, ?, ?)`
                ).bind(newId, result.programId, topikName, normalizeTopicName(topikName), new Date().toISOString()).run();
                result.topikId = newId;
                result.createdItems.push(`🆕 Topik: ${topikName} [${newId}]`);
            }
        }
        
        // ===== SUB-TOPIK =====
        if (subtopikName && result.topikId) {
            const row = await db.prepare(
                `SELECT id FROM sub_topik WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND topik_id = ? LIMIT 1`
            ).bind(subtopikName, result.topikId).first();
            
            if (row) {
                result.subtopikId = row.id;
            } else {
                const newId = await generateId(db, 'S', 'sub_topik');
                await db.prepare(
                    `INSERT INTO sub_topik (id, topik_id, nama, created_at) VALUES (?, ?, ?, ?)`
                ).bind(newId, result.topikId, subtopikName, new Date().toISOString()).run();
                result.subtopikId = newId;
                result.createdItems.push(`🆕 Sub-Topik: ${subtopikName} [${newId}]`);
            }
        }
        
        // ===== KISI-KISI =====
        if (kisiName && result.subtopikId) {
            const row = await db.prepare(
                `SELECT id FROM kisi_kisi WHERE LOWER(TRIM(judul)) = LOWER(TRIM(?)) AND sub_topik_id = ? LIMIT 1`
            ).bind(kisiName, result.subtopikId).first();
            
            if (row) {
                result.kisiId = row.id;
            } else {
                const newId = await generateId(db, 'I', 'kisi_kisi');
                await db.prepare(
                    `INSERT INTO kisi_kisi (id, sub_topik_id, judul, status, created_at) VALUES (?, ?, ?, 'RESMI', ?)`
                ).bind(newId, result.subtopikId, kisiName, new Date().toISOString()).run();
                result.kisiId = newId;
                result.createdItems.push(`🆕 Kisi-Kisi: ${kisiName} [${newId}]`);
            }
        }
        
        // ===== KEMAMPUAN =====
        if (kemampuanName && result.kisiId) {
            const row = await db.prepare(
                `SELECT id FROM kemampuan_diuji WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND kisi_kisi_id = ? LIMIT 1`
            ).bind(kemampuanName, result.kisiId).first();
            
            if (row) {
                result.kemampuanId = row.id;
            } else {
                const newId = await generateKemampuanId(db);
                await db.prepare(
                    `INSERT INTO kemampuan_diuji (id, kisi_kisi_id, nama, created_at) VALUES (?, ?, ?, ?)`
                ).bind(newId, result.kisiId, kemampuanName, new Date().toISOString()).run();
                result.kemampuanId = newId;
                result.createdItems.push(`🆕 Kemampuan: ${kemampuanName} [${newId}]`);
            }
        }
        
        // ===== SUB-KEMAMPUAN =====
        if (subKemampuanName && result.kemampuanId) {
            const row = await db.prepare(
                `SELECT id FROM sub_kemampuan WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND kemampuan_id = ? LIMIT 1`
            ).bind(subKemampuanName, result.kemampuanId).first();
            
            if (row) {
                result.subKemampuanId = row.id;
            } else {
                const newId = await generateSubKemampuanId(db);
                await db.prepare(
                    `INSERT INTO sub_kemampuan (id, kemampuan_id, nama, created_at) VALUES (?, ?, ?, ?)`
                ).bind(newId, result.kemampuanId, subKemampuanName, new Date().toISOString()).run();
                result.subKemampuanId = newId;
                result.createdItems.push(`🆕 Sub-Kemampuan: ${subKemampuanName} [${newId}]`);
            }
        }
        
        // ============================================================
        // MASTER DATA
        // ============================================================
        
        // ===== CARA PENYAJIAN =====
        if (caraPenyajian) {
            const kodeMatch = caraPenyajian.match(/P\d{2}/);
            const kode = kodeMatch ? kodeMatch[0] : caraPenyajian;
            const row = await db.prepare(
                `SELECT id FROM cara_penyajian WHERE kode_utama = ? OR id = ? LIMIT 1`
            ).bind(kode, kode).first();
            result.penyajianId = row?.id || null;
        }
        
        // ===== TIPE ISI =====
        if (tipeIsi) {
            const kodeMatch = tipeIsi.match(/TI\d{2}/);
            const kode = kodeMatch ? kodeMatch[0] : tipeIsi;
            const row = await db.prepare(
                `SELECT id FROM tipe_isi_soal WHERE kode_utama = ? OR id = ? LIMIT 1`
            ).bind(kode, kode).first();
            result.tipeIsiId = row?.id || null;
        }
        
        // ===== TAHAP =====
        if (tahap) {
            const kodeMatch = tahap.match(/T\d/);
            const kode = kodeMatch ? kodeMatch[0] : tahap;
            const row = await db.prepare(
                `SELECT id FROM tahap_pembelajaran WHERE kode_utama = ? OR id = ? LIMIT 1`
            ).bind(kode, kode).first();
            result.tahapId = row?.id || null;
        }
        
        // ===== LAPISAN =====
        if (lapisan) {
            const level = parseInt(lapisan);
            if (!isNaN(level)) {
                const row = await db.prepare(
                    `SELECT id FROM lapisan_pembelajaran WHERE level = ? LIMIT 1`
                ).bind(level).first();
                result.lapisanId = row?.id || null;
            }
        }
        
        // ===== SUMBER BELAJAR =====
        if (sumberReferensi) {
            const row = await db.prepare(
                `SELECT id FROM sumber_belajar WHERE LOWER(TRIM(nama)) LIKE LOWER(TRIM(?)) LIMIT 1`
            ).bind(`%${sumberReferensi}%`).first();
            result.sumberId = row?.id || null;
        }
        
    } catch (e) {
        console.error('getOrCreateMasterIds error:', e);
        // Tetap return result dengan sebagian ID yang sudah didapat
    }
    
    return result;
}

