// ============================================================
// FUNGSI 1: PROMPT GENERATE SOAL PG
// ============================================================
function buildGenerateSoalPromptWithKemampuan(
    topic, 
    subtopic, 
    kemampuan, 
    subKemampuan, 
    level = 'sedang', 
    count = 3,
    kisiJudul = null
) {
    const isBatch = count > 10;
    
    let context = `Topik: ${topic}\n`;
    if (subtopic && subtopic !== 'Subtopik') context += `Subtopik: ${subtopic}\n`;
    if (kisiJudul && kisiJudul !== 'Kisi-Kisi') context += `Kisi-Kisi: ${kisiJudul}\n`;
    if (kemampuan && kemampuan !== 'Kemampuan') context += `Kemampuan Yang Diuji: ${kemampuan}\n`;
    if (subKemampuan && subKemampuan !== 'Sub-Kemampuan') context += `Sub-Kemampuan: ${subKemampuan}\n`;
    
    const levelMap = {
        'mudah': 'Mudah (soal dasar, satu konsep)',
        'sedang': 'Sedang (kombinasi konsep, analisis sederhana)',
        'sulit': 'Sulit (analisis mendalam, pemecahan masalah kompleks)'
    };
    
    // Aturan batch (unik fungsi — dinamis berdasarkan count)
    let batchInstructions = '';
    if (isBatch) {
        batchInstructions = `
========================================
INSTRUKSI KHUSUS UNTUK ${count} SOAL:
========================================
1. Buat ${count} soal dengan variasi yang berbeda-beda
2. Pastikan tidak ada soal yang sama persis
3. Gunakan berbagai tipe pertanyaan (aplikasi, analisis, evaluasi)
4. Distribusikan tingkat kesulitan secara merata
5. Setiap soal harus memiliki pembahasan yang edukatif
6. Gunakan format yang konsisten untuk semua soal
7. Pisahkan setiap soal dengan "---" (garis pemisah)

⚠️ PENTING: JANGAN gunakan format tabel atau simbol khusus yang sulit diparse!
`;
    }

    // Pesyaratan dinamis (pakai count)
    const laranganDinamis = `1. Buat PERSIS ${count} soal, tidak kurang, tidak lebih!`;

    return `
${SOAL_RULES.peran}

${RULE_GLOBAL}

BUATKAN ${count} SOAL PILIHAN GANDA berdasarkan konteks berikut:

${context}

Level kesulitan: ${levelMap[level] || levelMap.sedang}
${batchInstructions}
${SOAL_RULES.format}

${SOAL_RULES.laranganStatis.replace(
    '- Setiap soal HARUS punya 5 pilihan: A, B, C, D, E',
    `${laranganDinamis}\n- Setiap soal HARUS punya 5 pilihan: A, B, C, D, E`
)}

${SOAL_RULES.contohBenar}

${SOAL_RULES.contohSalah}

Mulai buat soal sekarang:
`;
}

// ============================================================
// FUNGSI 2: PROMPT GENERATE MATERI (FLEKSIBEL BATCH)
// ============================================================
function buildGenerateMateriPrompt(
    topic,
    subtopic,
    kemampuan,
    subKemampuan,
    kisiJudul,
    format = 'ringkasan',
    batchNumber = 1,
    isLastBatch = false,
    accumulatedWords = 0
) {
    const instruction = MATERI_RULES.formatMap[format] || MATERI_RULES.formatMap['ringkasan'];
    const targetWords = MATERI_RULES.targetWords[format] || MATERI_RULES.targetWords['default'];

    let context = `Topik: ${topic}\n`;
    if (subtopic && subtopic !== 'Subtopik') context += `Subtopik: ${subtopic}\n`;
    if (kisiJudul && kisiJudul !== 'Kisi-Kisi') context += `Kisi-Kisi: ${kisiJudul}\n`;
    if (kemampuan && kemampuan !== 'Kemampuan') context += `Kemampuan: ${kemampuan}\n`;
    if (subKemampuan && subKemampuan !== 'Sub-Kemampuan') context += `Sub-Kemampuan: ${subKemampuan}\n`;

    // Aturan batch PER FORMAT (unik fungsi — dinamis)
    let batchInstruction = '';
    switch (format) {
        case 'ringkasan':
            batchInstruction = `
========================================
INSTRUKSI KHUSUS RINGKASAN:
========================================
- Buat ringkasan yang PADAT dan JELAS
- Target: ${targetWords}
- Fokus pada poin-poin TERPENTING saja
- JANGAN bertele-tele
- Gunakan bullet points untuk memudahkan pembaca
`;
            break;
            
        case 'penjelasan':
            if (batchNumber === 1) {
                batchInstruction = `
========================================
INSTRUKSI BATCH ${batchNumber} (PENDAHULUAN):
========================================
- Buat bagian PENDAHULUAN dari materi
- Sertakan: Latar belakang, tujuan pembelajaran, dan gambaran umum
- Target: 1.500 - 2.500 kata untuk bagian ini
${!isLastBatch ? `- Akhiri dengan "--- BERSAMBUNG ---"` : ''}
`;
            } else if (isLastBatch) {
                batchInstruction = `
========================================
INSTRUKSI BATCH ${batchNumber} (PENUTUP):
========================================
- Buat bagian PENUTUP dari materi
- Sertakan: Rangkuman akhir, kesimpulan, dan daftar pustaka
- Target: 1.000 - 2.000 kata untuk bagian ini
- Materi harus UTUH dan LENGKAP

🎯 TAMBAHAN WAJIB (PALING PENTING!):
Setelah kesimpulan, buat 10 CONTOH SOAL PILIHAN GANDA dengan PEMBAHASAN LENGKAP.

Format setiap soal:
---
Soal N: [teks soal]
A. [pilihan A]
B. [pilihan B]
C. [pilihan C]
D. [pilihan D]
E. [pilihan E]
Jawaban: [A/B/C/D/E]
Pembahasan: [penjelasan detail mengapa jawaban benar dan yang lain salah]
---

Persyaratan soal:
- 10 soal dengan tingkat kesulitan bervariasi (mudah, sedang, sulit)
- Setiap soal punya 5 pilihan (A, B, C, D, E)
- Hanya 1 jawaban benar
- Pembahasan harus edukatif dan jelas
- Distribusi jawaban merata (A/B/C/D/E)
- JANGAN buat pilihan yang duplikat
- JANGAN buat soal yang terlalu mudah
`;
            } else {
                const batchPosition = batchNumber - 1;
                const topics = ['Teori Dasar dan Konsep', 'Aplikasi dan Contoh', 'Analisis Mendalam', 'Studi Kasus'];
                const topicIndex = Math.min(batchPosition - 1, topics.length - 1);
                
                batchInstruction = `
========================================
INSTRUKSI BATCH ${batchNumber} (BAGIAN ${batchPosition}):
========================================
- Lanjutkan materi dari bagian sebelumnya
- Fokus pada: ${topics[topicIndex] || 'Materi Lanjutan'}
- Target: 1.500 - 2.500 kata untuk bagian ini
${!isLastBatch ? `- Akhiri dengan "--- BERSAMBUNG ---"` : ''}
`;
            }
            break;
            
        case 'peta_konsep':
            batchInstruction = `
========================================
INSTRUKSI PETA KONSEP:
========================================
- Buat peta konsep dalam bentuk hierarki
- Gunakan struktur poin-poin yang jelas
- Hubungkan antar konsep dengan tanda panah (→)
- Target: sesuai kebutuhan, minimal 50 poin
- Format: 
  ## Konsep Utama
  - Sub konsep 1
    - Detail 1.1
    - Detail 1.2
  - Sub konsep 2
    - Detail 2.1
`;
            break;
            
        case 'rangkuman':
            batchInstruction = `
========================================
INSTRUKSI KHUSUS RANGKUMAN:
========================================
- Buat rangkuman LENGKAP dan TERSTRUKTUR
- Target: ${targetWords}
- Sertakan: poin penting, rumus (jika ada), dan contoh aplikasi
- Gunakan bullet points dan numbering
- Buat kesimpulan di akhir
`;
            break;
            
        default:
            batchInstruction = `
========================================
INSTRUKSI MATERI:
========================================
- Buat materi sesuai format yang dipilih
- Target: sesuai kebutuhan
- Gunakan struktur yang jelas
`;
    }

    // Pesyaratan dinamis (isLastBatch, format)
    const laranganDinamis = `
3. ${format === 'penjelasan' ? `Pastikan setiap batch memiliki minimal 500 kata` : ''}
4. ${isLastBatch ? 'INI BATCH TERAKHIR - Pastikan semua materi sudah selesai dan utuh' : ''}
5. ${format === 'penjelasan' && isLastBatch ? 'WAJIB: Sertakan 10 contoh soal pilihan ganda dengan pembahasan di akhir materi' : ''}`;

    return `
${instruction} tentang materi berikut:

${RULE_GLOBAL}

${context}

${batchInstruction}

${MATERI_RULES.format}

${MATERI_RULES.laranganStatis}
${laranganDinamis}

Mulai buat materi:
`;
}

// ============================================================
// FUNGSI 3: PROMPT BUILDER PER TAHAP
// ============================================================
function buildTahapMateriPrompt(tahapKode, topicName, context = {}, format = 'penjelasan') {
    const tahap = TAHAP_PEMBELAJARAN[tahapKode];
    
    if (!tahap) {
        console.error(`Tahap ${tahapKode} tidak ditemukan`);
        return null;
    }
    
    let contextStr = '';
    if (context.kategori) contextStr += `Kategori: ${context.kategori}\n`;
    if (context.bidang) contextStr += `Bidang Studi: ${context.bidang}\n`;
    if (context.program) contextStr += `Program Studi: ${context.program}\n`;
    if (context.topik) contextStr += `Topik: ${context.topik}\n`;
    if (context.subtopik) contextStr += `Sub-Topik: ${context.subtopik}\n`;
    if (context.kisi) contextStr += `Kisi-Kisi: ${context.kisi}\n`;
    if (context.kemampuan) contextStr += `Kemampuan: ${context.kemampuan}\n`;
    if (context.subKemampuan) contextStr += `Sub-Kemampuan: ${context.subKemampuan}\n`;
    
    let targetLength = '';
    switch (format) {
        case 'ringkasan': targetLength = '500-1.500 kata'; break;
        case 'penjelasan': targetLength = '1.500-3.000 kata'; break;
        case 'peta_konsep': targetLength = '800-1.500 kata (format hierarkis)'; break;
        case 'rangkuman': targetLength = '1.000-2.000 kata'; break;
        default: targetLength = '1.500-3.000 kata';
    }
    
    // Peringatan khusus per tahap (unik fungsi)
    let peringatanKhusus = '';
    switch (tahapKode) {
        case 'T4':
            peringatanKhusus = '⚠️ FOKUS: PENERAPAN pada situasi nyata, bukan rumus/teori!';
            break;
        case 'T5':
            peringatanKhusus = '⚠️ FOKUS: KOMBINASI minimal 2 konsep/rumus/metode/strategi!';
            break;
        case 'T6':
            peringatanKhusus = '⚠️ FOKUS: ANALISIS (perbandingan, prediksi, evaluasi, kesalahan, variabel, interpretasi data, kesimpulan)!';
            break;
        case 'T7':
            peringatanKhusus = '⚠️ FOKUS: STUDI KASUS nyata (informasi relevan & tidak relevan)!';
            break;
        case 'T8':
            peringatanKhusus = '⚠️ FOKUS: HOTS (penalaran, pemecahan masalah, pengambilan keputusan, asumsi tersembunyi, alternatif)!';
            break;
        case 'T9':
            peringatanKhusus = '⚠️ FOKUS: KOMPREHENSIF (gabungan seluruh tahapan secara menyeluruh)!';
            break;
        case 'T1':
            peringatanKhusus = '⚠️ FOKUS: TEORI & KONSEP DASAR (pengertian, definisi, ciri, fungsi, tujuan, jenis, komponen, prinsip dasar, hubungan konsep)!';
            break;
        case 'T2':
            peringatanKhusus = '⚠️ FOKUS: PEMAHAMAN MENDALAM (mengapa, bagaimana, sebab-akibat, perbedaan, hubungan, konsekuensi, interpretasi)!';
            break;
        case 'T3':
            peringatanKhusus = '⚠️ FOKUS: RUMUS/PRINSIP/METODE (rumus, prinsip, aturan, metode, prosedur, mekanisme, strategi)!';
            break;
    }
    
    return `${MATERI_TAHAP_RULES.peran}

${RULE_GLOBAL}

${MATERI_TAHAP_RULES.peringatanFormat(tahap, peringatanKhusus)}

═══════════════════════════════════════════════════
TAHAP PEMBELAJARAN: ${tahap.icon} ${tahap.kode} — ${tahap.nama}
═══════════════════════════════════════════════════

FOKUS TAHAP INI:
${tahap.deskripsi}

KATA KUNCI YANG HARUS DICAKUP:
${tahap.keywords}

PROSES KOGNITIF: LOTS / MOTS / HOTS (ditentukan terpisah)
TARGET PANJANG: ${targetLength}

═══════════════════════════════════════════════════
KONTEKS MATERI:
═══════════════════════════════════════════════════
${contextStr}
═══════════════════════════════════════════════════

TUGAS:
Buat materi untuk TAHAP ${tahap.kode} — ${tahap.nama} tentang "${context.topik || topicName}".

${MATERI_TAHAP_RULES.aturanWajib(tahap)}

${MATERI_TAHAP_RULES.format(tahap)}

${MATERI_TAHAP_RULES.penutup(tahap)}`;
}

// ============================================================
// FUNGSI 4: PROMPT GLOSARIUM
// ============================================================
function buildGlosariumPrompt(topicName, allContent, tahapList) {
    return `Berdasarkan materi tentang "${topicName}" berikut, buat GLOSARIUM istilah penting.

═══════════════════════════════════════════════════
MATERI (dari ${tahapList.length} tahap):
═══════════════════════════════════════════════════
${allContent.substring(0, 8000)}
═══════════════════════════════════════════════════

${GLOSARIUM_RULES.format}

${GLOSARIUM_RULES.larangan}`;
}

// ============================================================
// FUNGSI 5: PROMPT PETA KONSEP
// ============================================================
function buildPetaKonsepPrompt(topicName, tahapList, context = {}) {
    const tahapStr = tahapList.map(k => {
        const t = TAHAP_PEMBELAJARAN[k];
        return `- ${t.icon} ${k}: ${t.nama}`;
    }).join('\n');
    
    return `Buat PETA KONSEP untuk materi "${topicName}" yang mencakup ${tahapList.length} tahap pembelajaran.

═══════════════════════════════════════════════════
TAHAP YANG DICAKUP:
═══════════════════════════════════════════════════
${tahapStr}
═══════════════════════════════════════════════════

${PETA_RULES.format}

${PETA_RULES.larangan}`;
}

// ============================================================
// FUNGSI 6: PROMPT GENERATE PEMBAHASAN
// ============================================================
function buildGeneratePembahasanPrompt(soal, jawabanBenar, pilihanA, pilihanB, pilihanC, pilihanD, pilihanE) {
    return `
${PEMBAHASAN_RULES.peran}

${RULE_GLOBAL}

========================================
SOAL:
========================================
${soal}

========================================
PILIHAN JAWABAN:
========================================
A. ${pilihanA || '-'}
B. ${pilihanB || '-'}
C. ${pilihanC || '-'}
D. ${pilihanD || '-'}
E. ${pilihanE || '-'}

JAWABAN BENAR: ${jawabanBenar}

${PEMBAHASAN_RULES.instruksiFormat(jawabanBenar)}

${PEMBAHASAN_RULES.laranganStatis}
`;
}

// ============================================================
// 🆕 PATCH 6 (LANJUTAN) - 5 FUNGSI YANG BELUM ADA
// Lokasi: Setelah getMateriStats()
// ⚠️ CATATAN: buildGlosariumPrompt & buildPetaKonsepPrompt
//             SUDAH ADA di file, tidak perlu dipaste ulang.
// ============================================================

// ============================================================
// 1. BUILD PROMPT SOAL DARI MATERI
// ============================================================
function buildSoalFromMateriPrompt(topicName, materiContent, count = 5, level = 'sedang') {
    const levelMap = {
        'mudah': 'Mudah (soal dasar, satu konsep)',
        'sedang': 'Sedang (kombinasi konsep, analisis sederhana)',
        'sulit': 'Sulit (analisis mendalam, pemecahan masalah kompleks)'
    };
    
    return `Berdasarkan materi berikut, buat ${count} SOAL PILIHAN GANDA.

═══════════════════════════════════════════════════
MATERI:
═══════════════════════════════════════════════════
${materiContent.substring(0, 8000)}
═══════════════════════════════════════════════════

LEVEL KESULITAN: ${levelMap[level] || levelMap.sedang}

TUGAS:
Buat ${count} soal pilihan ganda tentang "${topicName}" berdasarkan materi di atas.

FORMAT OUTPUT (WAJIB untuk setiap soal):
--- (pemisah antar soal)

Soal: [Teks soal]
A. [Pilihan A]
B. [Pilihan B]
C. [Pilihan C]
D. [Pilihan D]
E. [Pilihan E]
Jawaban: [A/B/C/D/E]
Pembahasan: [Penjelasan singkat]

Aturan:
1. Soal harus berdasarkan materi di atas
2. Setiap soal harus punya 1 jawaban benar
3. Pembahasan harus edukatif
4. JANGAN gunakan format tabel
5. Bahasa Indonesia yang baik

Mulai buat soal:`;
}

