// 2. GENERATE GLOSARIUM DARI MATERI
// ============================================================
async function generateGlosarium(env, userId, chatId, db, materiId) {
    try {
        const smartSession = await getSession(env, userId);
        const smartMessageId = smartSession?.lastMessageId || null;
        const materi = await db.prepare(`SELECT * FROM materi WHERE id = ?`)
            .bind(materiId).first();
        
        if (!materi) {
            await smartResponseUniversal(chatId, '❌ Materi tidak ditemukan.', { mode: 'auto', messageId: smartMessageId });
            return;
        }
        
        if (!materi.konten) {
            await smartResponseUniversal(chatId, '❌ Materi kosong. Generate materi dulu.', { mode: 'auto', messageId: smartMessageId });
            return;
        }
        
        let tahapList = [];
        try {
            tahapList = JSON.parse(materi.tahap_dipilih || '[]');
        } catch (e) {}
        
        // Ambil nama topik
        let topicName = 'Materi';
        if (materi.topik_id) {
            const t = await db.prepare(`SELECT nama FROM topik WHERE id = ?`)
                .bind(materi.topik_id).first();
            if (t) topicName = t.nama;
        }
        
        await smartResponseUniversal(chatId, 
            `📖 *Generate Glosarium...*\n\n` +
            `📖 Topik: ${topicName}\n` +
            `📊 Tahap: ${tahapList.length} tahap\n\n` +
            `⏳ Mohon tunggu...`, { mode: 'auto', messageId: smartMessageId });
        
        const prompt = buildGlosariumPrompt(topicName, materi.konten, tahapList);
        const result = await callAIHybrid(prompt, 'generate_materi', env);
        
        if (!result.success) {
            await smartResponseUniversal(chatId, `❌ Gagal generate glosarium: ${result.error}`, { mode: 'auto', messageId: smartMessageId });
            return;
        }
        
        // Simpan ke DB (opsional)
        try {
            await db.prepare(`ALTER TABLE materi ADD COLUMN glosarium TEXT`).run();
        } catch (e) {
            // Kolom sudah ada
        }
        
        try {
            await db.prepare(`UPDATE materi SET glosarium = ?, updated_at = ? WHERE id = ?`)
                .bind(result.response, new Date().toISOString(), materiId).run();
        } catch (e) {
            console.warn('⚠️ Gagal simpan glosarium:', e.message);
        }
        
        let output = `✅ *GLOSARIUM SIAP!*\n\n`;
        output += `📖 Topik: ${topicName}\n`;
        output += `🤖 AI: ${result.provider}\n\n`;
        output += `---\n\n`;
        output += result.response;
        
        if (output.length > 4000) {
            const parts = output.match(/[\s\S]{1,4000}/g) || [];
            for (const part of parts) {
                await smartResponseUniversal(chatId, part, { mode: 'send' });
            }
        } else {
            await smartResponseUniversal(chatId, output, { mode: 'send' });
        }
        
        const keyboard = [
            [{ text: "🗺️ Generate Peta Konsep", callback_data: `materi_peta_${materiId}` }],
            [{ text: "📝 Generate Soal", callback_data: `materi_to_soal_${materiId}` }],
            [{ text: "🔙 Kembali ke Materi", callback_data: `materi_view_${materiId}` }]
        ];
        
        await smartResponseUniversal(chatId, `📌 Pilih aksi selanjutnya:`, { keyboard, mode: 'auto', messageId: smartMessageId });
        
    } catch (e) {
        console.error('generateGlosarium error:', e);
        await smartResponseUniversal(chatId, `❌ Error: ${e.message}`, { mode: 'auto', messageId: smartMessageId });
    }
}

