async function generateSoalFromMateri(env, userId, chatId, db, materiId, count = 5, level = 'sedang') {
    try {
        const smartSession = await getSession(env, userId);
        const smartMessageId = smartSession?.lastMessageId || null;
        const materi = await db.prepare(`SELECT * FROM materi WHERE id = ?`)
            .bind(materiId).first();
        
        if (!materi) {
            await smartResponseUniversal(chatId, '❌ Materi tidak ditemukan.', { mode: 'auto', messageId: smartMessageId });
            return;
        }
        
        if (!materi.konten) {
            await smartResponseUniversal(chatId, '❌ Materi kosong. Generate materi dulu.', { mode: 'auto', messageId: smartMessageId });
            return;
        }
        
        // Ambil nama topik
        let topicName = 'Materi';
        if (materi.topik_id) {
            const t = await db.prepare(`SELECT nama FROM topik WHERE id = ?`)
                .bind(materi.topik_id).first();
            if (t) topicName = t.nama;
        }
        
        await smartResponseUniversal(chatId, 
            `📝 *Generate ${count} Soal dari Materi...*\n\n` +
            `📖 Topik: ${topicName}\n` +
            `📊 Level: ${level}\n` +
            `📝 Jumlah: ${count} soal\n\n` +
            `⏳ Mohon tunggu...`, { mode: 'auto', messageId: smartMessageId });
        
        const prompt = buildSoalFromMateriPrompt(topicName, materi.konten, count, level);
        const result = await callAIHybrid(prompt, 'generate_soal', env);
        
        if (!result.success) {
            await smartResponseUniversal(chatId, `❌ Gagal generate soal: ${result.error}`, { mode: 'auto', messageId: smartMessageId });
            return;
        }
        
        const soalList = parseAISoalResponseUniversal(result.response);
        
        if (soalList.length === 0) {
            await smartResponseUniversal(chatId, `⚠️ AI tidak menghasilkan soal valid.\n\nResponse preview:\n\`\`\`\n${result.response.substring(0, 500)}\n\`\`\``, { mode: 'auto', messageId: smartMessageId });
            return;
        }
        
        // Tampilkan hasil
        let output = `✅ *SOAL BERHASIL DIGENERATE!*\n\n`;
        output += `📖 Topik: ${topicName}\n`;
        output += `📊 Level: ${level}\n`;
        output += `📝 Dihasilkan: ${soalList.length} soal\n`;
        output += `🤖 AI: ${result.provider}\n\n`;
        output += `---\n\n`;
        
        for (let i = 0; i < soalList.length; i++) {
            const s = soalList[i];
            output += `*Soal ${i + 1}*\n`;
            output += `📝 ${s.soal}\n\n`;
            output += `A. ${s.pilihan_a || '-'}\n`;
            output += `B. ${s.pilihan_b || '-'}\n`;
            output += `C. ${s.pilihan_c || '-'}\n`;
            output += `D. ${s.pilihan_d || '-'}\n`;
            output += `E. ${s.pilihan_e || '-'}\n\n`;
            output += `⭐ *Jawaban:* ${s.jawaban}\n`;
            if (s.pembahasan) {
                output += `📖 *Pembahasan:* ${s.pembahasan.substring(0, 200)}...\n`;
            }
            output += `\n---\n\n`;
        }
        
        if (output.length > 4000) {
            const parts = output.match(/[\s\S]{1,4000}/g) || [];
            for (const part of parts) {
                await smartResponseUniversal(chatId, part, { mode: 'send' });
            }
        } else {
            await smartResponseUniversal(chatId, output, { mode: 'send' });
        }
        
        // Simpan di session
        const session = await getSession(env, userId);
        session.aiGeneratedSoal = soalList;
        session.aiKisiId = materi.kisi_kisi_id || null;
        session.aiSubKemampuanId = materi.sub_kemampuan_id || null;
        session.aiSourceMateriId = materiId;
        await saveSession(env, userId, session);
        
        const keyboard = [
            [{ text: `💾 Simpan Semua (${soalList.length})`, callback_data: `materi_save_soal_${materiId}` }],
            [{ text: "🔄 Generate Ulang", callback_data: `materi_to_soal_${materiId}` }],
            [{ text: "🔙 Kembali ke Materi", callback_data: `materi_view_${materiId}` }]
        ];
        
        await smartResponseUniversal(chatId, `📌 *${soalList.length} soal berhasil digenerate!*

` + `Pilih aksi:`, { keyboard, mode: 'auto', messageId: smartMessageId });
        
    } catch (e) {
        console.error('generateSoalFromMateri error:', e);
        await smartResponseUniversal(chatId, `❌ Error: ${e.message}`, { mode: 'auto', messageId: smartMessageId });
    }
}

// ============================================================
// 5. SIMPAN SOAL DARI MATERI
// ============================================================
async function saveSoalFromMateri(env, userId, chatId, db, materiId) {
    try {
        const session = await getSession(env, userId);
        const soalList = session.aiGeneratedSoal || [];
        
        if (soalList.length === 0) {
            await smartResponseUniversal(chatId, '❌ Tidak ada soal untuk disimpan.');
            return;
        }
        
        const materi = await db.prepare(`
            SELECT kisi_kisi_id, sub_kemampuan_id, sumber_belajar_id, sumber_link, tahun
            FROM materi WHERE id = ?
        `).bind(materiId).first();
        
        await smartResponseUniversal(chatId, 
            `⏳ *Menyimpan ${soalList.length} soal...*\n\n` +
            `📌 Mengikuti konteks materi ${materiId}`
        );
        
        let successCount = 0;
        let errorCount = 0;
        let errors = [];
        let savedIds = [];
        
        for (const soal of soalList) {
            try {
                const soalText = (soal.soal || '').trim();
                if (!soalText) {
                    errorCount++;
                    continue;
                }
                
                const jawaban = (soal.jawaban || '').toUpperCase().trim();
                if (!['A','B','C','D','E'].includes(jawaban)) {
                    errorCount++;
                    continue;
                }
                
                const result = await saveSoalWithAutoClassify(db, {
                    soalText: soalText,
                    pilihanA: soal.pilihan_a || '',
                    pilihanB: soal.pilihan_b || '',
                    pilihanC: soal.pilihan_c || '',
                    pilihanD: soal.pilihan_d || '',
                    pilihanE: soal.pilihan_e || '',
                    jawabanBenar: jawaban,
                    pembahasan: soal.pembahasan || '',
                    alasanA: soal.alasan_a || '',
                    alasanB: soal.alasan_b || '',
                    alasanC: soal.alasan_c || '',
                    alasanD: soal.alasan_d || '',
                    alasanE: soal.alasan_e || '',
                    kisiKisiId: materi?.kisi_kisi_id || null,
                    subKemampuanId: materi?.sub_kemampuan_id || null,
                    sumberBelajarId: materi?.sumber_belajar_id || null,
                    sumberLink: materi?.sumber_link || null,
                    tahun: materi?.tahun || null,
                    userId: userId
                });
                
                if (result.success) {
                    successCount++;
                    savedIds.push(result.id);
                } else {
                    errorCount++;
                    errors.push(result.error);
                }
            } catch (e) {
                errorCount++;
                errors.push(e.message);
            }
        }
        
        let response = `✅ *SIMPAN SOAL SELESAI*\n\n`;
        response += `📊 Berhasil: ${successCount} soal\n`;
        response += `❌ Gagal: ${errorCount} soal\n\n`;
        
        if (savedIds.length > 0) {
            response += `🆔 *ID Soal:*\n`;
            savedIds.slice(0, 10).forEach(id => response += `   • ${id}\n`);
            if (savedIds.length > 10) {
                response += `   ... dan ${savedIds.length - 10} lainnya\n`;
            }
        }
        
        if (errors.length > 0) {
            response += `\n⚠️ *Error:*\n`;
            errors.slice(0, 3).forEach(e => response += `   • ${e}\n`);
        }
        
        await smartResponseUniversal(chatId, response, { mode: 'send' });
        
        // Clear session
        session.aiGeneratedSoal = [];
        await saveSession(env, userId, session);
        
    } catch (e) {
        console.error('saveSoalFromMateri error:', e);
        await smartResponseUniversal(chatId, `❌ Error: ${e.message}`);
    }
}

// ============================================================
// FUNGSI FALLBACK - HANYA 1 KALI
// ============================================================
function parseAISoalResponseAlt(response) {
    const soalList = [];
    const lines = response.split('\n').map(l => l.trim()).filter(l => l);
    
    let currentSoal = null;
    let soalLines = [];
    let currentSection = 'soal';
    
    for (const line of lines) {
        if (line.match(/^[Ss][Oo][Aa][Ll]\s*[:.]/)) {
            if (currentSoal && currentSoal.soal && currentSoal.jawaban) {
                currentSoal.soal = soalLines.join(' ').trim();
                soalList.push(currentSoal);
            }
            
            currentSoal = {
                soal: '',
                pilihan_a: '',
                pilihan_b: '',
                pilihan_c: '',
                pilihan_d: '',
                pilihan_e: '',
                jawaban: '',
                pembahasan: '',
                alasan_a: '', alasan_b: '', alasan_c: '', alasan_d: '', alasan_e: ''
            };
            soalLines = [];
            currentSection = 'soal';
            
            const content = line.replace(/^[Ss][Oo][Aa][Ll]\s*[:.]\s*/, '');
            if (content) soalLines.push(content);
            continue;
        }
        
        if (!currentSoal) continue;
        
        if (line.match(/^[A-E]\s*[).]\s*/)) {
            const letter = line[0].toUpperCase();
            const content = line.replace(/^[A-E]\s*[).]\s*/, '');
            if (letter === 'A') currentSoal.pilihan_a = content;
            else if (letter === 'B') currentSoal.pilihan_b = content;
            else if (letter === 'C') currentSoal.pilihan_c = content;
            else if (letter === 'D') currentSoal.pilihan_d = content;
            else if (letter === 'E') currentSoal.pilihan_e = content;
            continue;
        }
        
        if (line.match(/^[Jj][Aa][Ww][Aa][Bb][Aa][Nn]\s*[:.]/)) {
            const jawaban = line.replace(/^[Jj][Aa][Ww][Aa][Bb][Aa][Nn]\s*[:.]\s*/, '').trim().toUpperCase();
            if (['A','B','C','D','E'].includes(jawaban)) {
                currentSoal.jawaban = jawaban;
            }
            continue;
        }
        
        const alasan = line.match(/^Alasan\s*([A-E])\s*[:.]\s*(.*)$/i);
        if (alasan) { currentSection = `alasan_${alasan[1].toLowerCase()}`; currentSoal[currentSection] = alasan[2].trim(); continue; }

        if (line.match(/^[Pp][Ee][Mm][Bb][Aa][Hh][Aa][Ss][Aa][Nn]\s*[:.]/)) {
            currentSection = 'pembahasan';
            const content = line.replace(/^[Pp][Ee][Mm][Bb][Aa][Hh][Aa][Ss][Aa][Nn]\s*[:.]\s*/, '');
            if (content) currentSoal.pembahasan += content + ' ';
            continue;
        }
        
        if (currentSection === 'soal') {
            soalLines.push(line);
        } else if (currentSection === 'pembahasan') {
            currentSoal.pembahasan += line + ' ';
        } else if (/^alasan_[a-e]$/.test(currentSection)) {
            currentSoal[currentSection] += ` ${line}`;
        }
    }
    
    if (currentSoal && currentSoal.soal && currentSoal.jawaban) {
        currentSoal.soal = soalLines.join(' ').trim();
        soalList.push(currentSoal);
    }
    
    return soalList;
}

