// PARSER UNIVERSAL - Coba semua parser sampai berhasil
// ============================================================
function parseAISoalResponseUniversal(response) {
    if (!response || typeof response !== 'string') {
        console.warn('🔍 [Universal] Response kosong atau bukan string');
        return [];
    }
    
    // ============================================================
    // DEBUG: Info response
    // ============================================================
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
    console.log('🔍 [Universal] Response length:', response.length);
    console.log('🔍 [Universal] First 300 chars:');
    console.log(response.substring(0, 300));
    console.log('---');
    console.log('🔍 [Universal] Last 300 chars:');
    console.log(response.substring(Math.max(0, response.length - 300)));
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
    
    // ============================================================
    // Coba 1: parseAISoalResponse
    // ============================================================
    try {
        const result1 = parseAISoalResponse(response);
        console.log('🔍 [Universal] parseAISoalResponse hasil:', result1 ? result1.length : 'null');
        if (result1 && result1.length > 0) {
            console.log(`✅ Parser: parseAISoalResponse (${result1.length} soal)`);
            return result1;
        }
    } catch (e) {
        console.warn('⚠️ parseAISoalResponse error:', e.message);
    }
    
    // ============================================================
    // Coba 2: parseAISoalResponseFast
    // ============================================================
    try {
        const result2 = parseAISoalResponseFast(response);
        console.log('🔍 [Universal] parseAISoalResponseFast hasil:', result2 ? result2.length : 'null');
        if (result2 && result2.length > 0) {
            console.log(`✅ Parser: parseAISoalResponseFast (${result2.length} soal)`);
            return result2;
        }
    } catch (e) {
        console.warn('⚠️ parseAISoalResponseFast error:', e.message);
    }
    
    // ============================================================
    // Coba 3: parseAISoalResponseAlt
    // ============================================================
    try {
        const result3 = parseAISoalResponseAlt(response);
        console.log('🔍 [Universal] parseAISoalResponseAlt hasil:', result3 ? result3.length : 'null');
        if (result3 && result3.length > 0) {
            console.log(`✅ Parser: parseAISoalResponseAlt (${result3.length} soal)`);
            return result3;
        }
    } catch (e) {
        console.warn('⚠️ parseAISoalResponseAlt error:', e.message);
    }
    
    console.warn('❌ Semua parser gagal — response tidak bisa diparse');
    return [];
}

