// ============================================================
// SEARCH FUNCTIONS
// ============================================================
async function searchByKeyword(db, keyword) {
  try {
    const query = `
      SELECT 
        k.id as kategori_id,
        k.nama as kategori_nama,
        b.id as bidang_id,
        b.nama as bidang_nama,
        p.id as program_id,
        p.nama as program_nama,
        t.id as topik_id,
        t.nama as topik_nama,
        t.deskripsi as topik_deskripsi,
        st.id as subtopik_id,
        st.nama as subtopik_nama,
        kk.id as kisi_id,
        kk.judul as kisi_judul,
        kk.kode as kisi_kode,
        km.id as kemampuan_id,
        km.nama as kemampuan_nama,
        sk.id as subkemampuan_id,
        sk.nama as subkemampuan_nama,
        s.id as soal_id,
        s.soal as soal_text,
        s.jawaban_benar,
        CASE 
          WHEN LOWER(s.soal) LIKE LOWER(?) THEN 'Soal'
          WHEN LOWER(sk.nama) LIKE LOWER(?) THEN 'Sub-Kemampuan'
          WHEN LOWER(km.nama) LIKE LOWER(?) THEN 'Kemampuan'
          WHEN LOWER(st.nama) LIKE LOWER(?) THEN 'Sub-Topik'
          WHEN LOWER(t.nama) LIKE LOWER(?) THEN 'Topik'
          WHEN LOWER(kk.judul) LIKE LOWER(?) THEN 'Kisi-Kisi'
          WHEN LOWER(p.nama) LIKE LOWER(?) THEN 'Program Studi'
          WHEN LOWER(b.nama) LIKE LOWER(?) THEN 'Bidang Studi'
          WHEN LOWER(k.nama) LIKE LOWER(?) THEN 'Kategori'
        END as match_type
      FROM soal s
      LEFT JOIN sub_kemampuan sk ON s.sub_kemampuan_id = sk.id
      LEFT JOIN kemampuan_diuji km ON sk.kemampuan_id = km.id
      LEFT JOIN kisi_kisi kk ON km.kisi_kisi_id = kk.id
      LEFT JOIN sub_topik st ON kk.sub_topik_id = st.id
      LEFT JOIN topik t ON st.topik_id = t.id
      LEFT JOIN program_studi p ON t.program_studi_id = p.id
      LEFT JOIN bidang_studi b ON p.bidang_studi_id = b.id
      LEFT JOIN kategori k ON b.kategori_id = k.id
      WHERE s.status = 'AKTIF'
        AND (
          LOWER(s.soal) LIKE LOWER(?)
          OR LOWER(sk.nama) LIKE LOWER(?)
          OR LOWER(km.nama) LIKE LOWER(?)
          OR LOWER(st.nama) LIKE LOWER(?)
          OR LOWER(t.nama) LIKE LOWER(?)
          OR LOWER(kk.judul) LIKE LOWER(?)
          OR LOWER(p.nama) LIKE LOWER(?)
          OR LOWER(b.nama) LIKE LOWER(?)
          OR LOWER(k.nama) LIKE LOWER(?)
        )
      ORDER BY k.id, b.id, p.id, t.id, st.id, kk.id, km.id, sk.id
      LIMIT 100
    `;
    
    const result = await db.prepare(query)
      .bind(
        `%${keyword}%`, `%${keyword}%`, `%${keyword}%`, `%${keyword}%`,
        `%${keyword}%`, `%${keyword}%`, `%${keyword}%`, `%${keyword}%`,
        `%${keyword}%`,
        `%${keyword}%`, `%${keyword}%`, `%${keyword}%`, `%${keyword}%`,
        `%${keyword}%`, `%${keyword}%`, `%${keyword}%`, `%${keyword}%`,
        `%${keyword}%`
      )
      .all();
    
    return result.results || [];
  } catch (e) {
    console.error("Search by keyword error:", e);
    return [];
  }
}

// ============================================================
// FORMAT HIERARCHY DENGAN ESCAPE - PERBAIKAN
// ============================================================

function formatHierarchy(data) {
    if (!data || data.length === 0) {
        return '❌ Belum ada data. Silakan tambahkan data terlebih dahulu.';
    }
    
    let output = '📑 *DAFTAR ISI PEMBELAJARAN*\n\n';
    
    const kategoriMap = {};
    data.forEach(row => {
        const kategoriId = row.kategori_id || 'unknown';
        if (!kategoriMap[kategoriId]) {
            kategoriMap[kategoriId] = {
                id: row.kategori_id,
                nama: row.kategori_nama || 'N/A',
                bidang: {}
            };
        }
        
        if (row.bidang_id) {
            const bidangId = row.bidang_id;
            if (!kategoriMap[kategoriId].bidang[bidangId]) {
                kategoriMap[kategoriId].bidang[bidangId] = {
                    id: row.bidang_id,
                    nama: row.bidang_nama || 'N/A',
                    program: {}
                };
            }
            
            if (row.program_id) {
                const programId = row.program_id;
                if (!kategoriMap[kategoriId].bidang[bidangId].program[programId]) {
                    kategoriMap[kategoriId].bidang[bidangId].program[programId] = {
                        id: row.program_id,
                        nama: row.program_nama || 'N/A',
                        topik: {}
                    };
                }
                
                if (row.topik_id) {
                    const topikId = row.topik_id;
                    if (!kategoriMap[kategoriId].bidang[bidangId].program[programId].topik[topikId]) {
                        kategoriMap[kategoriId].bidang[bidangId].program[programId].topik[topikId] = {
                            id: row.topik_id,
                            nama: row.topik_nama || 'N/A',
                            subtopik: []
                        };
                    }
                    
                    if (row.subtopik_id) {
                        kategoriMap[kategoriId].bidang[bidangId].program[programId].topik[topikId].subtopik.push({
                            id: row.subtopik_id,
                            nama: row.subtopik_nama || 'N/A',
                            kisi: row.kisi_id ? {
                                id: row.kisi_id,
                                judul: row.kisi_judul || 'N/A',
                                total_soal: row.total_soal || 0
                            } : null
                        });
                    }
                }
            }
        }
    });
    
    let totalKategori = 0, totalBidang = 0, totalProgram = 0, totalTopik = 0, totalSubtopik = 0, totalKisi = 0;
    
    Object.values(kategoriMap).forEach(kategori => {
        totalKategori++;
        output += `📂 *KATEGORI: ${escapeMarkdownText(kategori.nama.toUpperCase())}* [${escapeMarkdownText(kategori.id || 'N/A')}]\n`;
        
        const bidangValues = Object.values(kategori.bidang);
        if (bidangValues.length === 0) {
            output += '   └── (Belum ada Bidang Studi)\n\n';
            return;
        }
        
        bidangValues.forEach((bidang, bIndex) => {
            totalBidang++;
            const isLastBidang = bIndex === bidangValues.length - 1;
            const prefixBidang = isLastBidang ? '   └──' : '   ├──';
            
            output += `${prefixBidang} 📚 *BIDANG STUDI: ${escapeMarkdownText(bidang.nama)}* [${escapeMarkdownText(bidang.id || 'N/A')}]\n`;
            
            const programValues = Object.values(bidang.program);
            if (programValues.length === 0) {
                output += `   ${isLastBidang ? '    ' : '   │   '}└── (Belum ada Program Studi)\n`;
                return;
            }
            
            programValues.forEach((program, pIndex) => {
                totalProgram++;
                const isLastProgram = pIndex === programValues.length - 1;
                const prefixProgram = isLastBidang ? '    ' : '   │   ';
                const programBranch = isLastProgram ? '└──' : '├──';
                
                output += `${prefixProgram}${programBranch} 🎓 *PROGRAM STUDI: ${escapeMarkdownText(program.nama)}* [${escapeMarkdownText(program.id || 'N/A')}]\n`;
                
                const topikValues = Object.values(program.topik);
                if (topikValues.length === 0) {
                    output += `${prefixProgram}${isLastProgram ? '    ' : '   │   '}└── (Belum ada Topik)\n`;
                    return;
                }
                
                topikValues.forEach((topik, tIndex) => {
                    totalTopik++;
                    const isLastTopik = tIndex === topikValues.length - 1;
                    const prefixTopik = isLastBidang ? '    ' : '   │   ';
                    const prefixTopik2 = isLastProgram ? '    ' : '   │   ';
                    const topikBranch = isLastTopik ? '└──' : '├──';
                    
                    output += `${prefixTopik}${prefixTopik2}${topikBranch} 📖 *TOPIK: ${escapeMarkdownText(topik.nama)}* [${escapeMarkdownText(topik.id || 'N/A')}]\n`;
                    
                    if (topik.subtopik.length === 0) {
                        output += `${prefixTopik}${prefixTopik2}${isLastTopik ? '    ' : '   │   '}└── (Belum ada Sub-Topik)\n`;
                        return;
                    }
                    
                    topik.subtopik.forEach((sub, sIndex) => {
                        totalSubtopik++;
                        const isLastSubtopik = sIndex === topik.subtopik.length - 1;
                        const prefixSubtopik = isLastBidang ? '    ' : '   │   ';
                        const prefixSubtopik2 = isLastProgram ? '    ' : '   │   ';
                        const prefixSubtopik3 = isLastTopik ? '    ' : '   │   ';
                        const subtopikBranch = isLastSubtopik ? '└──' : '├──';
                        
                        output += `${prefixSubtopik}${prefixSubtopik2}${prefixSubtopik3}${subtopikBranch} 📋 *${escapeMarkdownText(sub.nama)}* [${escapeMarkdownText(sub.id || 'N/A')}]\n`;
                        
                        if (sub.kisi) {
                            totalKisi++;
                            output += `${prefixSubtopik}${prefixSubtopik2}${prefixSubtopik3}${isLastSubtopik ? '    ' : '│   '}└── 📌 *${escapeMarkdownText(sub.kisi.judul)}* [${escapeMarkdownText(sub.kisi.id || 'N/A')}] - ${sub.kisi.total_soal || 0} Soal\n`;
                        } else {
                            output += `${prefixSubtopik}${prefixSubtopik2}${prefixSubtopik3}${isLastSubtopik ? '    ' : '│   '}└── (Belum ada Kisi-Kisi)\n`;
                        }
                    });
                });
            });
        });
        output += '\n';
    });
    
    output += '\n📊 *RINGKASAN*\n';
    output += `📂 Kategori: ${totalKategori}\n`;
    output += `📚 Bidang Studi: ${totalBidang}\n`;
    output += `🎓 Program Studi: ${totalProgram}\n`;
    output += `📖 Topik: ${totalTopik}\n`;
    output += `📋 Sub-Topik: ${totalSubtopik}\n`;
    output += `📌 Kisi-Kisi: ${totalKisi}\n`;
    
    return output;
}

// ============================================================
// FORMAT SEARCH RESULT DENGAN ESCAPE - PERBAIKAN
// ============================================================

function formatSearchResult(data, keyword) {
    if (!data || data.length === 0) {
        return `❌ Tidak ditemukan data dengan kata kunci: *${escapeMarkdownText(keyword)}*`;
    }
    
    let output = `🔍 *HASIL PENCARIAN: "${escapeMarkdownText(keyword.toUpperCase())}"*\n`;
    output += `📊 Ditemukan ${data.length} data\n\n`;
    
    const emojiMap = {
        'Kategori': '📂',
        'Bidang Studi': '📚',
        'Program Studi': '🎓',
        'Topik': '📖',
        'Sub-Topik': '📋',
        'Kisi-Kisi': '📌',
        'Soal': '📝'
    };
    
    const kategoriMap = {};
    data.forEach(row => {
        const kategoriId = row.kategori_id || 'unknown';
        if (!kategoriMap[kategoriId]) {
            kategoriMap[kategoriId] = {
                id: row.kategori_id,
                nama: row.kategori_nama || 'N/A',
                items: []
            };
        }
        
        let path = '';
        if (row.kategori_nama) path += `📂 ${escapeMarkdownText(row.kategori_nama)}`;
        if (row.bidang_nama) path += ` → 📚 ${escapeMarkdownText(row.bidang_nama)}`;
        if (row.program_nama) path += ` → 🎓 ${escapeMarkdownText(row.program_nama)}`;
        if (row.topik_nama) path += ` → 📖 ${escapeMarkdownText(row.topik_nama)}`;
        if (row.subtopik_nama) path += ` → 📋 ${escapeMarkdownText(row.subtopik_nama)}`;
        if (row.kisi_judul) path += ` → 📌 ${escapeMarkdownText(row.kisi_judul)}`;
        
        const matchIcon = emojiMap[row.match_type] || '📌';
        
        kategoriMap[kategoriId].items.push({
            path: path,
            matchType: row.match_type || 'Soal',
            matchIcon: matchIcon,
            soal: row.soal_text ? escapeMarkdownText(row.soal_text) : '',
            jawaban: row.jawaban_benar ? escapeMarkdownText(row.jawaban_benar) : '',
            subtopik: row.subtopik_nama ? escapeMarkdownText(row.subtopik_nama) : '',
            kisi: row.kisi_judul ? escapeMarkdownText(row.kisi_judul) : '',
            topik: row.topik_nama ? escapeMarkdownText(row.topik_nama) : ''
        });
    });
    
    Object.values(kategoriMap).forEach(kategori => {
        output += `📂 *KATEGORI: ${escapeMarkdownText(kategori.nama.toUpperCase())}*\n`;
        
        kategori.items.forEach((item, index) => {
            output += `\n${index + 1}. ${item.matchIcon} *Tipe:* ${item.matchType}\n`;
            output += `   📍 *Lokasi:* ${item.path}\n`;
            if (item.soal) {
                output += `   📝 *Soal:* ${item.soal}\n`;
                output += `   ⭐ *Jawaban:* ${item.jawaban || 'N/A'}\n`;
            } else if (item.subtopik) {
                output += `   📋 *Sub-Topik:* ${item.subtopik}\n`;
            } else if (item.kisi) {
                output += `   📌 *Kisi-Kisi:* ${item.kisi}\n`;
            } else if (item.topik) {
                output += `   📖 *Topik:* ${item.topik}\n`;
            }
        });
        output += '\n';
    });
    
    return output;
}

// ============================================================
// DELETE FUNCTIONS
// ============================================================
async function deleteItem(db, table, id) {
  try {
    const check = await db.prepare(`SELECT id FROM ${table} WHERE id = ?`).bind(id).first();
    if (!check) return false;
    
    await db.prepare(`DELETE FROM ${table} WHERE id = ?`).bind(id).run();
    return true;
  } catch (e) {
    console.error(`Delete error for ${table}:`, e);
    return false;
  }
}

// ============================================================
// HELPER: AMBIL SOAL + MASTER DATA (KODE + NAMA)
// ============================================================
async function getSoalWithMasterData(db, soalId) {
    try {
        const result = await db.prepare(`
            SELECT 
                s.*,
                
                -- KATEGORI
                s.kategori_id as kategori_kode,
                k.nama as kategori_nama,
                
                -- BIDANG
                s.bidang_studi_id as bidang_kode,
                b.nama as bidang_nama,
                
                -- PROGRAM
                s.program_studi_id as program_kode,
                p.nama as program_nama,
                
                -- JENJANG
                s.jenjang_id as jenjang_kode,
                j.nama as jenjang_nama,
                
                -- KELAS
                s.kelas as kelas_kode,
                kl.nama as kelas_nama,
                
                -- TOPIK
                s.topik_id as topik_kode,
                t.nama as topik_nama,
                
                -- SUB-TOPIK
                s.sub_topik_id as subtopik_kode,
                st.nama as subtopik_nama,
                
                -- KISI-KISI
                s.kisi_kisi_id as kisi_kode,
                kk.judul as kisi_judul,
                
                -- KEMAMPUAN
                s.kemampuan_id as kemampuan_kode,
                km.nama as kemampuan_nama,
                
                -- SUB-KEMAMPUAN
                s.sub_kemampuan_id as subkemampuan_kode,
                sk.nama as subkemampuan_nama,
                
                -- CARA PENYAJIAN
                s.cara_penyajian_id as penyajian_kode,
                cp.nama as penyajian_nama,
                
                -- TIPE ISI
                s.tipe_isi_id as tipeisi_kode,
                ti.nama as tipeisi_nama,
                
                -- TAHAP
                s.tahap_pembelajaran_id as tahap_kode,
                tp.nama as tahap_nama,
                
                -- LAPISAN
                s.lapisan_pembelajaran_id as lapisan_kode,
                lp.nama as lapisan_nama,
                
                -- SUMBER
                s.sumber_belajar_id as sumber_kode,
                sb.nama as sumber_nama,
                sb.sumber_link as sumber_link_default
                
            FROM soal s
            LEFT JOIN kategori k ON s.kategori_id = k.id
            LEFT JOIN bidang_studi b ON s.bidang_studi_id = b.id
            LEFT JOIN program_studi p ON s.program_studi_id = p.id
            LEFT JOIN jenjang j ON s.jenjang_id = j.id
            LEFT JOIN kelas kl ON s.kelas = kl.id
            LEFT JOIN topik t ON s.topik_id = t.id
            LEFT JOIN sub_topik st ON s.sub_topik_id = st.id
            LEFT JOIN kisi_kisi kk ON s.kisi_kisi_id = kk.id
            LEFT JOIN kemampuan_diuji km ON s.kemampuan_id = km.id
            LEFT JOIN sub_kemampuan sk ON s.sub_kemampuan_id = sk.id
            LEFT JOIN sumber_belajar sb ON s.sumber_belajar_id = sb.id
            LEFT JOIN cara_penyajian cp ON s.cara_penyajian_id = cp.id
            LEFT JOIN tipe_isi_soal ti ON s.tipe_isi_id = ti.id
            LEFT JOIN tahap_pembelajaran tp ON s.tahap_pembelajaran_id = tp.id
            LEFT JOIN lapisan_pembelajaran lp ON s.lapisan_pembelajaran_id = lp.id
            WHERE s.id = ?
        `).bind(soalId).first();
        
        return result;
    } catch (e) {
        console.error('getSoalWithMasterData error:', e);
        return null;
    }
}

