async function getItemById(db, table, id) {
  try {
    return await db.prepare(`SELECT * FROM ${table} WHERE id = ?`).bind(id).first();
  } catch (e) {
    return null;
  }
}

// ============================================================
// CANONICAL CASCADE COUNT / PLANNER
// Sumber aturan: perilaku aktual deleteCascade() di bawah ini.
// Tidak menghapus data; hanya menghitung baris yang benar-benar
// diproses oleh cascade execution.
// ============================================================
const CASCADE_ENTITY_TABLES = Object.freeze({
    kategori: 'kategori',
    bidang: 'bidang_studi',
    bidang_studi: 'bidang_studi',
    program: 'program_studi',
    program_studi: 'program_studi',
    jenjang: 'jenjang',
    kelas: 'kelas',
    mata_pelajaran: 'mata_pelajaran',
    mata_kuliah: 'mata_kuliah',
    topik: 'topik',
    subtopik: 'sub_topik',
    sub_topik: 'sub_topik',
    kisi: 'kisi_kisi',
    kisi_kisi: 'kisi_kisi',
    kemampuan: 'kemampuan_diuji',
    kemampuan_diuji: 'kemampuan_diuji',
    subkemampuan: 'sub_kemampuan',
    sub_kemampuan: 'sub_kemampuan'
});

// ============================================================
// CANONICAL CASCADE RULES
// Sumber tunggal aturan hierarchy untuk consumer cascade.
// L20-15: baru dikonsumsi getChildEntities().
// ARTIFACT/JUNCTION belum diaktifkan di consumer pada tahap ini.
// ============================================================
const CASCADE_RULES = Object.freeze({
    kategori: {
        children: [
            { entity: 'bidang_studi', table: 'bidang_studi', field: 'kategori_id' }
        ]
    },
    bidang_studi: {
        children: [
            { entity: 'mata_pelajaran', table: 'mata_pelajaran', field: 'bidang_studi_id' },
            { entity: 'program_studi', table: 'program_studi', field: 'bidang_studi_id' }
        ]
    },
    jenjang: {
        children: [
            { entity: 'kelas', table: 'kelas', field: 'jenjang_id' },
            { entity: 'mata_kuliah', table: 'mata_kuliah', field: 'jenjang_id' }
        ]
    },
    kelas: {
        children: [
            { entity: 'mata_pelajaran', table: 'mata_pelajaran', field: 'kelas_id' }
        ]
    },
    mata_pelajaran: {
        children: [
            { entity: 'topik', table: 'topik', field: 'mata_pelajaran_id' }
        ]
    },
    mata_kuliah: {
        children: [
            { entity: 'topik', table: 'topik', field: 'mata_kuliah_id' }
        ]
    },
    program_studi: {
        children: [
            { entity: 'mata_kuliah', table: 'mata_kuliah', field: 'program_studi_id' },
            {
                entity: 'topik',
                table: 'topik',
                field: 'program_studi_id',
                extra: 'mata_kuliah_id IS NULL AND mata_pelajaran_id IS NULL'
            }
        ]
    },
    topik: {
        children: [
            { entity: 'sub_topik', table: 'sub_topik', field: 'topik_id' }
        ]
    },
    sub_topik: {
        children: [
            { entity: 'kisi_kisi', table: 'kisi_kisi', field: 'sub_topik_id' }
        ]
    },
    kisi_kisi: {
        children: [
            { entity: 'kemampuan_diuji', table: 'kemampuan_diuji', field: 'kisi_kisi_id' }
        ]
    },
    kemampuan_diuji: {
        children: [
            { entity: 'sub_kemampuan', table: 'sub_kemampuan', field: 'kemampuan_id' }
        ]
    },
    sub_kemampuan: {
        children: []
    }
});

async function getChildEntities(db, tableName, parentId) {
    const table = CASCADE_ENTITY_TABLES[tableName] || tableName;
    const relationRules = CASCADE_RULES[table]?.children || [];
    const output = [];
    for (const rule of relationRules) {
        let query = `SELECT id FROM ${rule.table} WHERE ${rule.field} = ?`;
        if (rule.extra) query += ` AND ${rule.extra}`;
        const result = await db.prepare(query).bind(parentId).all();
        for (const row of (result.results || [])) {
            output.push({
                id: row.id,
                entity: rule.entity,
                table: rule.table,
                parentField: rule.field
            });
        }
    }
    return output;
}

async function countCascadeGeneric(db, entity, id) {
    const rootTable = CASCADE_ENTITY_TABLES[entity] || entity;
    const counts = {
        kategori: 0,
        bidang: 0,
        program: 0,
        jenjang: 0,
        kelas: 0,
        mataPelajaran: 0,
        mataKuliah: 0,
        topik: 0,
        subtopik: 0,
        kisi: 0,
        kemampuan: 0,
        subKemampuan: 0,
        soal: 0,
        materi: 0,
        relasiJenjang: 0,
        relasiKelas: 0,
        total: 0
    };

    const entityKey = {
        kategori: 'kategori',
        bidang_studi: 'bidang',
        program_studi: 'program',
        jenjang: 'jenjang',
        kelas: 'kelas',
        mata_pelajaran: 'mataPelajaran',
        mata_kuliah: 'mataKuliah',
        topik: 'topik',
        sub_topik: 'subtopik',
        kisi_kisi: 'kisi',
        kemampuan_diuji: 'kemampuan',
        sub_kemampuan: 'subKemampuan'
    };

    const visited = new Set();
    const uniqueSoalIds = new Set();
    const uniqueMateriIds = new Set();
    const uniqueRelasiJenjangIds = new Set();
    const uniqueRelasiKelasIds = new Set();
    const queue = [{ table: rootTable, id: String(id) }];

    while (queue.length) {
        const current = queue.shift();
        const visitKey = `${current.table}:${current.id}`;
        if (visited.has(visitKey)) continue;
        visited.add(visitKey);

        if (entityKey[current.table]) counts[entityKey[current.table]]++;

        // Hanya hitung soal/materi yang benar-benar dihapus oleh deleteCascade().
        if (current.table === 'kelas') {
            const [soalRows, relasiRows] = await Promise.all([
                db.prepare(`SELECT id FROM soal WHERE kelas = ?`).bind(current.id).all(),
                db.prepare(`SELECT id FROM topik_kelas WHERE kelas_id = ?`).bind(current.id).all()
            ]);
            for (const row of (soalRows.results || [])) uniqueSoalIds.add(String(row.id));
            // deleteCascade() menghapus seluruh topik_kelas milik Kelas.
            // Simpan ID relasi agar tidak double-count dengan jalur Topik.
            for (const row of (relasiRows.results || [])) uniqueRelasiKelasIds.add(String(row.id));
        }
        if (current.table === 'mata_pelajaran') {
            const [q, m] = await Promise.all([
                db.prepare(`SELECT id FROM soal WHERE mata_pelajaran_id = ?`).bind(current.id).all(),
                db.prepare(`SELECT id FROM materi WHERE mata_pelajaran_id = ?`).bind(current.id).all()
            ]);
            for (const row of (q.results || [])) uniqueSoalIds.add(String(row.id));
            for (const row of (m.results || [])) uniqueMateriIds.add(String(row.id));
        }
        if (current.table === 'mata_kuliah') {
            const [q, m] = await Promise.all([
                db.prepare(`SELECT id FROM soal WHERE mata_kuliah_id = ?`).bind(current.id).all(),
                db.prepare(`SELECT id FROM materi WHERE mata_kuliah_id = ?`).bind(current.id).all()
            ]);
            for (const row of (q.results || [])) uniqueSoalIds.add(String(row.id));
            for (const row of (m.results || [])) uniqueMateriIds.add(String(row.id));
        }
        if (current.table === 'sub_kemampuan') {
            const rows = (await db.prepare(`SELECT id FROM soal WHERE sub_kemampuan_id = ?`).bind(current.id).all()).results || [];
            for (const row of rows) uniqueSoalIds.add(String(row.id));
        }
        if (current.table === 'topik') {
            const [tj, tk] = await Promise.all([
                db.prepare(`SELECT id FROM topik_jenjang WHERE topik_id = ?`).bind(current.id).all(),
                db.prepare(`SELECT id FROM topik_kelas WHERE topik_id = ?`).bind(current.id).all()
            ]);
            // deleteCascade() menghapus junction berdasarkan topik_id.
            // Gunakan Set agar relasi yang sama tidak dihitung dua kali
            // ketika juga ditemukan dari jalur Kelas.
            for (const row of (tj.results || [])) uniqueRelasiJenjangIds.add(String(row.id));
            for (const row of (tk.results || [])) uniqueRelasiKelasIds.add(String(row.id));
        }

        // L20-16: traversal hierarchy langsung membaca CASCADE_RULES.
        // getChildEntities() tetap menjadi consumer terpisah; aturan hierarchy
        // tidak lagi didefinisikan ulang di countCascadeGeneric().
        const relationRules = CASCADE_RULES[current.table]?.children || [];
        for (const rule of relationRules) {
            let query = `SELECT id FROM ${rule.table} WHERE ${rule.field} = ?`;
            if (rule.extra) query += ` AND ${rule.extra}`;
            const result = await db.prepare(query).bind(current.id).all();
            for (const row of (result.results || [])) {
                queue.push({ table: rule.table, id: String(row.id) });
            }
        }
    }

    // Soal/Materi dapat ditemukan dari lebih dari satu jalur FK dalam satu cascade.
    // Gunakan ID unik agar preview tidak double-count data yang hanya dihapus sekali.
    counts.soal = uniqueSoalIds.size;
    counts.materi = uniqueMateriIds.size;
    counts.relasiJenjang = uniqueRelasiJenjangIds.size;
    counts.relasiKelas = uniqueRelasiKelasIds.size;

    // deleteCascade.deletedCount hanya menghitung entitas utama yang dihapus,
    // bukan soal/materi/junction artifacts. Pertahankan arti total untuk UI generic.
    counts.total = Object.values(counts).reduce((sum, value) => sum + (Number(value) || 0), 0)
        - counts.total;
    // Total di atas sengaja dihitung dari seluruh komponen sebelum field total.
    return counts;
}

async function countCascadeKategori(db, id) {
    const counts = await countCascadeGeneric(db, 'kategori', id);
    return counts;
}

async function countCascadeBidang(db, id) {
    const counts = await countCascadeGeneric(db, 'bidang', id);
    return counts;
}

// ============================================================
// DELETE CASCADE - MENGHAPUS DATA BESERTA SEMUA ANAKNYA
// ============================================================

function summarizeCascadeCounts(counts) {
    const entityKeys = [
        'kategori', 'bidang', 'program', 'jenjang', 'kelas',
        'mataPelajaran', 'mataKuliah', 'topik', 'subtopik', 'kisi',
        'kemampuan', 'subKemampuan'
    ];
    const entityTotal = entityKeys.reduce((sum, key) => sum + (Number(counts?.[key]) || 0), 0);
    const soal = Number(counts?.soal) || 0;
    const materi = Number(counts?.materi) || 0;
    const relasiJenjang = Number(counts?.relasiJenjang) || 0;
    const relasiKelas = Number(counts?.relasiKelas) || 0;
    const relationTotal = relasiJenjang + relasiKelas;
    const cascadeEntities = Math.max(0, entityTotal - 1);
    const totalCascadeRecords = cascadeEntities + soal + materi + relationTotal;

    return {
        entityTotal,
        cascadeEntities,
        soal,
        materi,
        relasiJenjang,
        relasiKelas,
        relationTotal,
        totalCascadeRecords
    };
}

async function deleteCascade(db, table, id, userId) {
    try {
        let deletedCount = 0;
        let deletedItems = [];

        // Fungsi rekursif untuk menghapus berdasarkan hierarki
        async function cascadeDelete(tableName, parentId, parentField, level = 0) {
            const prefix = '  '.repeat(level);
            // Bersihkan relasi kurikulum lintas entitas sebelum entitas dihapus.
            await cleanupCurriculumRelationsForEntity(db, tableName, parentId);
            
            // Cari semua anak dari entitas ini
            let children = [];
            switch (tableName) {
                case 'kategori':
                    // Kategori -> Bidang Studi
                    children = await getChildEntities(db, tableName, parentId);
                    for (const child of children) {
                        await cascadeDelete(child.table, child.id, child.parentField, level + 1);
                    }
                    // Hapus kategori setelah semua anak terhapus
                    await db.prepare(`DELETE FROM kategori WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Kategori ${parentId} dihapus`);
                    break;

                case 'bidang_studi':
                    // Bidang Studi -> Mata Pelajaran + Program Studi
                    children = await getChildEntities(db, tableName, parentId);
                    for (const child of children) {
                        await cascadeDelete(child.table, child.id, child.parentField, level + 1);
                    }
                    // Hapus bidang studi
                    await db.prepare(`DELETE FROM bidang_studi WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Bidang Studi ${parentId} dihapus`);
                    break;

                case 'jenjang':
                    // Jenjang sekolah -> Kelas -> Mata Pelajaran; jenjang tinggi -> Mata Kuliah
                    children = await getChildEntities(db, tableName, parentId);
                    for (const child of children) {
                        await cascadeDelete(child.table, child.id, child.parentField, level + 1);
                    }
                    await db.prepare(`DELETE FROM jenjang WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Jenjang ${parentId} dihapus`);
                    break;

                case 'kelas':
                    // Kelas -> Mata Pelajaran + relasi topik_kelas + soal
                    children = await getChildEntities(db, tableName, parentId);
                    for (const child of children) {
                        await cascadeDelete(child.table, child.id, child.parentField, level + 1);
                    }
                    await db.prepare(`DELETE FROM topik_kelas WHERE kelas_id = ?`).bind(parentId).run();
                    const soalRowsKelas = (await db.prepare(`SELECT id FROM soal WHERE kelas = ?`).bind(parentId).all()).results || [];
                    for (const q of soalRowsKelas) await deleteQuestionWithArtifacts(db,q.id,userId,'CASCADE_KELAS');
                    await db.prepare(`DELETE FROM kelas WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Kelas ${parentId} dihapus`);
                    break;

                case 'mata_pelajaran':
                    children = await getChildEntities(db, tableName, parentId);
                    for (const child of children) {
                        await cascadeDelete(child.table, child.id, child.parentField, level + 1);
                    }
                    const soalRowsMP = (await db.prepare(`SELECT id FROM soal WHERE mata_pelajaran_id = ?`).bind(parentId).all()).results || [];
                    for (const q of soalRowsMP) await deleteQuestionWithArtifacts(db,q.id,userId,'CASCADE_MATA_PELAJARAN');
                    const mpMateri = await db.prepare(`SELECT id FROM materi WHERE mata_pelajaran_id = ?`).bind(parentId).all();
                    for (const m of mpMateri.results || []) await deleteMateriArtifacts(db, m.id);
                    await db.prepare(`DELETE FROM materi WHERE mata_pelajaran_id = ?`).bind(parentId).run();
                    await db.prepare(`DELETE FROM mata_pelajaran WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Mata Pelajaran ${parentId} dihapus`);
                    break;

                case 'mata_kuliah':
                    children = await getChildEntities(db, tableName, parentId);
                    for (const child of children) {
                        await cascadeDelete(child.table, child.id, child.parentField, level + 1);
                    }
                    const soalRowsMK = (await db.prepare(`SELECT id FROM soal WHERE mata_kuliah_id = ?`).bind(parentId).all()).results || [];
                    for (const q of soalRowsMK) await deleteQuestionWithArtifacts(db,q.id,userId,'CASCADE_MATA_KULIAH');
                    const mkMateri = await db.prepare(`SELECT id FROM materi WHERE mata_kuliah_id = ?`).bind(parentId).all();
                    for (const m of mkMateri.results || []) await deleteMateriArtifacts(db, m.id);
                    await db.prepare(`DELETE FROM materi WHERE mata_kuliah_id = ?`).bind(parentId).run();
                    await db.prepare(`DELETE FROM mata_kuliah WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Mata Kuliah ${parentId} dihapus`);
                    break;

                case 'program_studi':
                    // Program Studi -> Mata Kuliah + Topik
                    children = await getChildEntities(db, tableName, parentId);
                    for (const child of children) {
                        await cascadeDelete(child.table, child.id, child.parentField, level + 1);
                    }
                    // Hapus program studi
                    await db.prepare(`DELETE FROM program_studi WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Program Studi ${parentId} dihapus`);
                    break;

                case 'topik':
                    // Topik -> Sub Topik
                    children = await getChildEntities(db, tableName, parentId);
                    for (const child of children) {
                        await cascadeDelete(child.table, child.id, child.parentField, level + 1);
                    }
                    
                    // ============================================================
                    // 🆕 HAPUS RELASI JUNCTION (topik_jenjang & topik_kelas)
                    // ============================================================
                    try {
                        await db.prepare(`DELETE FROM topik_jenjang WHERE topik_id = ?`).bind(parentId).run();
                        await db.prepare(`DELETE FROM topik_kelas WHERE topik_id = ?`).bind(parentId).run();
                        deletedItems.push(`${'  '.repeat(level)}🔗 Relasi Jenjang & Kelas topik ${parentId} dihapus`);
                    } catch (relErr) {
                        console.warn(`⚠️ Gagal hapus relasi topik ${parentId}:`, relErr.message);
                    }
                    
                    // Hapus topik
                    await db.prepare(`DELETE FROM topik WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Topik ${parentId} dihapus`);
                    break;

                case 'sub_topik':
                    // Sub Topik -> Kisi Kisi
                    children = await getChildEntities(db, tableName, parentId);
                    for (const child of children) {
                        await cascadeDelete(child.table, child.id, child.parentField, level + 1);
                    }
                    // Hapus sub topik
                    await db.prepare(`DELETE FROM sub_topik WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Sub-Topik ${parentId} dihapus`);
                    break;

                case 'kisi_kisi':
                    // Kisi Kisi -> Kemampuan Diuji
                    children = await getChildEntities(db, tableName, parentId);
                    for (const child of children) {
                        await cascadeDelete(child.table, child.id, child.parentField, level + 1);
                    }
                    // Hapus kisi kisi
                    await db.prepare(`DELETE FROM kisi_kisi WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Kisi-Kisi ${parentId} dihapus`);
                    break;

                case 'kemampuan_diuji':
                    // Kemampuan Diuji -> Sub Kemampuan
                    children = await getChildEntities(db, tableName, parentId);
                    for (const child of children) {
                        await cascadeDelete(child.table, child.id, child.parentField, level + 1);
                    }
                    // Hapus kemampuan diuji
                    await db.prepare(`DELETE FROM kemampuan_diuji WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Kemampuan ${parentId} dihapus`);
                    break;

                case 'sub_kemampuan':
                    // Sub Kemampuan -> Soal (langsung)
                    const soalRowsSub = (await db.prepare(`SELECT id FROM soal WHERE sub_kemampuan_id = ?`).bind(parentId).all()).results || [];
                    for (const q of soalRowsSub) await deleteQuestionWithArtifacts(db,q.id,userId,'CASCADE_SUB_KEMAMPUAN');
                    // Hapus sub kemampuan
                    await db.prepare(`DELETE FROM sub_kemampuan WHERE id = ?`).bind(parentId).run();
                    deletedCount++;
                    deletedItems.push(`${'  '.repeat(level)}🗑️ Sub-Kemampuan ${parentId} dan soal-soalnya dihapus`);
                    break;

                default:
                    break;
            }
        }

        // Mulai cascade dari tabel yang diminta
        await cascadeDelete(table, id);

        return {
            success: true,
            deletedCount: deletedCount,
            items: deletedItems
        };
    } catch (e) {
        console.error(`Cascade delete error for ${table}:`, e);
        return {
            success: false,
            error: e.message,
            deletedCount: 0,
            items: []
        };
    }
}

// ============================================================
// DELETE SINGLE ITEM (TANPA CASCADE) - KHUSUS UNTUK SOAL
// ============================================================

async function deleteItemOnly(db, table, id) {
    try {
        const check = await db.prepare(`SELECT id FROM ${table} WHERE id = ?`).bind(id).first();
        if (!check) return { success: false, error: 'Item tidak ditemukan' };
        
        await db.prepare(`DELETE FROM ${table} WHERE id = ?`).bind(id).run();
        return { success: true, deletedCount: 1 };
    } catch (e) {
        return { success: false, error: e.message };
    }
}

// ============================================================
// FORMAT SOAL LIST (Ringkas — Max 3500 karakter)
// ============================================================
function formatSoalList(soals, page, totalPages, offset = 0) {
    let msg = `📝 *DAFTAR SOAL (Hal ${page}/${totalPages || 1})*\n`;
    msg += `${DIVIDER}\n\n`;
    
    if (!soals || soals.length === 0) {
        msg += '❌ Belum ada soal aktif.\n';
        msg += '\n💡 Tambahkan soal dengan:\n';
        msg += '• /soal_add - Tambah manual\n';
        msg += '• /upload_soal - Upload CSV\n';
        msg += '• /import_massal - Import massal';
        return msg;
    }
    
    const optIndent = '   ';
    
    for (let i = 0; i < soals.length; i++) {
        const s = soals[i];
        const nomor = i + 1 + offset;
        
        // Soal dipotong max 100 karakter
        const soalRaw = s.soal || '-';
        const soalText = escapeMarkdownText(
            soalRaw.length > 100 ? soalRaw.substring(0, 100) + '...' : soalRaw
        );
        const idSafe = escapeMarkdownText(s.id || '');
        
        // Cek kalau sudah mau lewat batas
        if (msg.length > 3000) {
            msg += `\n_... (soal lainnya di halaman berikutnya)_`;
            break;
        }
        
        msg += `${nomor}. *${idSafe}*\n`;
        msg += `${optIndent}${soalText}\n`;
        
        // Pilihan jawaban (potong max 40 karakter, TANPA wrap)
        const maxOptLen = 40;
        const options = [
            { key: 'A', value: s.pilihan_a },
            { key: 'B', value: s.pilihan_b },
            { key: 'C', value: s.pilihan_c },
            { key: 'D', value: s.pilihan_d },
            { key: 'E', value: s.pilihan_e }
        ];
        
        for (const opt of options) {
            if (!opt.value) continue;
            
            let text = escapeMarkdownText(opt.value);
            if (text.length > maxOptLen) {
                text = text.substring(0, maxOptLen - 3) + '...';
            }
            
            msg += `${optIndent}${opt.key}. ${text}\n`;
        }
        
        if (s.jawaban_benar) {
            msg += `${optIndent}⭐ Jawaban: ${escapeMarkdownText(s.jawaban_benar)}\n`;
        }
        
        // Info parent (1 baris saja)
        if (s.subkemampuan_nama) {
            msg += `${optIndent}📎 ${escapeMarkdownText(s.subkemampuan_nama.substring(0, 40))}\n`;
        } else if (s.kemampuan_nama) {
            msg += `${optIndent}🎯 ${escapeMarkdownText(s.kemampuan_nama.substring(0, 40))}\n`;
        }
        
        msg += `\n`;
    }
    
    if (totalPages > 1) {
        msg += `${DIVIDER}\n`;
        msg += `📌 Ketik nomor halaman untuk lompat.`;
    }
    
    return msg;
}

