function formatSoalWithMetrics(soal) {
    const kompleksitasIcon = getKompleksitasIcon(soal.kompleksitas);
    const tingkatIcon = getTingkatKesulitanIcon(soal.tingkat_kesulitan);
    
    let msg = `📝 *${soal.id}*\n`;
    msg += `📌 ${soal.soal}\n\n`;
    
    // Pilihan jawaban
    if (soal.pilihan_a) msg += `A. ${soal.pilihan_a}\n`;
    if (soal.pilihan_b) msg += `B. ${soal.pilihan_b}\n`;
    if (soal.pilihan_c) msg += `C. ${soal.pilihan_c}\n`;
    if (soal.pilihan_d) msg += `D. ${soal.pilihan_d}\n`;
    if (soal.pilihan_e) msg += `E. ${soal.pilihan_e}\n`;
    msg += `⭐ *Jawaban:* ${soal.jawaban_benar}\n\n`;
    
    // METRIK LENGKAP
    msg += `📊 *Metrik Soal:*\n`;
    msg += `├─ 🔴 Kompleksitas: ${kompleksitasIcon} ${getKompleksitasLabel(soal.kompleksitas)}\n`;
    msg += `├─ 🎯 Tingkat: ${tingkatIcon} ${getTingkatKesulitanLabel(soal.tingkat_kesulitan)}\n`;
    msg += `├─ 📚 Tahap: ${soal.tahap_nama || '-'} (${soal.tahap_pembelajaran_id || '-'})\n`;
    msg += `├─ 📊 Proses Kognitif: ${getStoredCognitive(soal)}\n`;
    msg += `└─ 🏗️ Lapisan: ${soal.lapisan_nama || '-'}\n`;
    
    if (soal.sumber_nama) {
        msg += `\n📚 *Sumber:* ${soal.sumber_nama}`;
        if (soal.sumber_link) msg += `\n🔗 ${soal.sumber_link}`;
    }
    
    return msg;
}

/**
 * Get soal berdasarkan kompleksitas
 */
async function getSoalByKompleksitas(db, kompleksitas, limit = 20) {
    try {
        const result = await db.prepare(`
            SELECT 
                s.*,
                tp.nama as tahap_nama,
                lp.nama as lapisan_nama,
                sb.nama as sumber_nama
            FROM soal s
            LEFT JOIN tahap_pembelajaran tp ON s.tahap_pembelajaran_id = tp.id
            LEFT JOIN lapisan_pembelajaran lp ON s.lapisan_pembelajaran_id = lp.id
            LEFT JOIN sumber_belajar sb ON s.sumber_belajar_id = sb.id
            WHERE s.status = 'AKTIF' 
            AND s.kompleksitas = ?
            ORDER BY s.id DESC
            LIMIT ?
        `).bind(kompleksitas, limit).all();
        return result.results || [];
    } catch (e) {
        console.error('Error getSoalByKompleksitas:', e);
        return [];
    }
}

