/**
 * Get soal dengan filter gabungan
 */
async function getSoalWithFilters(db, filters = {}) {
    let query = `
        SELECT 
            s.*,
            tp.nama as tahap_nama,
            lp.nama as lapisan_nama,
            sb.nama as sumber_nama
        FROM soal s
        LEFT JOIN tahap_pembelajaran tp ON s.tahap_pembelajaran_id = tp.id
        LEFT JOIN lapisan_pembelajaran lp ON s.lapisan_pembelajaran_id = lp.id
        LEFT JOIN sumber_belajar sb ON s.sumber_belajar_id = sb.id
        LEFT JOIN mata_pelajaran mpl ON s.mata_pelajaran_id = mpl.id
        LEFT JOIN mata_kuliah mkl ON s.mata_kuliah_id = mkl.id
        WHERE s.status = 'AKTIF'
    `;
    let params = [];
    let conditions = [];

    // Hierarchy filters: MP dan MK tidak boleh dicampur secara implisit.
    if (filters.mataPelajaranId || filters.mata_pelajaran_id) {
        conditions.push('s.mata_pelajaran_id = ?');
        params.push(filters.mataPelajaranId || filters.mata_pelajaran_id);
    }
    if (filters.mataKuliahId || filters.mata_kuliah_id) {
        conditions.push('s.mata_kuliah_id = ?');
        params.push(filters.mataKuliahId || filters.mata_kuliah_id);
    }
    if (filters.bidangStudiId || filters.bidang_studi_id) {
        conditions.push('s.bidang_studi_id = ?');
        params.push(filters.bidangStudiId || filters.bidang_studi_id);
    }
    if (filters.programStudiId || filters.program_studi_id) {
        conditions.push('s.program_studi_id = ?');
        params.push(filters.programStudiId || filters.program_studi_id);
    }
    if (filters.semester !== undefined && filters.semester !== null && filters.semester !== '') {
        conditions.push('mkl.semester = ?');
        params.push(Number(filters.semester));
    }
    if (filters.jenjangId || filters.jenjang_id) {
        conditions.push('s.jenjang_id = ?');
        params.push(filters.jenjangId || filters.jenjang_id);
    }
    if (filters.kelasId || filters.kelas_id) {
        conditions.push('s.kelas = ?');
        params.push(filters.kelasId || filters.kelas_id);
    }
    if (filters.topikId || filters.topik_id) {
        conditions.push('s.topik_id = ?');
        params.push(filters.topikId || filters.topik_id);
    }
    if (filters.subTopikId || filters.sub_topik_id) {
        conditions.push('s.sub_topik_id = ?');
        params.push(filters.subTopikId || filters.sub_topik_id);
    }
    if (filters.kisiKisiId || filters.kisi_kisi_id) {
        conditions.push('s.kisi_kisi_id = ?');
        params.push(filters.kisiKisiId || filters.kisi_kisi_id);
    }
    if (filters.kemampuanId || filters.kemampuan_id) {
        conditions.push('s.kemampuan_id = ?');
        params.push(filters.kemampuanId || filters.kemampuan_id);
    }
    if (filters.tahun) {
        conditions.push('s.tahun = ?');
        params.push(filters.tahun);
    }
    if (filters.statusKeabsahan || filters.status_keabsahan) {
        conditions.push('s.status_keabsahan = ?');
        params.push(filters.statusKeabsahan || filters.status_keabsahan);
    }
    
    if (filters.kompleksitas) {
        conditions.push('s.kompleksitas = ?');
        params.push(filters.kompleksitas);
    }
    
    if (filters.tingkatKesulitan) {
        conditions.push('s.tingkat_kesulitan = ?');
        params.push(filters.tingkatKesulitan);
    }
    
    if (filters.tahapId) {
        conditions.push('s.tahap_pembelajaran_id = ?');
        params.push(filters.tahapId);
    }
    
    // LEGACY levelHots is not filterable as a current learning dimension.
    // Cognitive filtering uses LOTS/MOTS/HOTS through tipeHots/prosesKognitif.
    if (filters.prosesKognitif || filters.proses_kognitif || filters.tipeHots) {
        conditions.push('s.tipe_hots = ?');
        params.push(filters.prosesKognitif || filters.proses_kognitif || filters.tipeHots);
    }
    
    if (conditions.length > 0) {
        query += ' AND ' + conditions.join(' AND ');
    }
    
    query += ' ORDER BY s.id DESC LIMIT ?';
    params.push(filters.limit || 20);
    
    try {
        const result = await db.prepare(query).bind(...params).all();
        return result.results || [];
    } catch (e) {
        console.error('Error getSoalWithFilters:', e);
        return [];
    }
}

/**
 * Tampilkan statistik distribusi soal
 */
async function getSoalStatistics(db, filters = {}) {
    try {
        const where = ["s.status = 'AKTIF'"];
        const params = [];
        const add = (field, value) => {
            if (value !== undefined && value !== null && value !== '') {
                where.push(`s.${field} = ?`);
                params.push(value);
            }
        };
        add('kategori_id', filters.kategori_id || filters.kategoriId);
        add('bidang_studi_id', filters.bidang_studi_id || filters.bidangStudiId);
        add('program_studi_id', filters.program_studi_id || filters.programStudiId);
        if (filters.semester !== undefined && filters.semester !== null && filters.semester !== '') {
            where.push('EXISTS (SELECT 1 FROM mata_kuliah mkf WHERE mkf.id = s.mata_kuliah_id AND mkf.semester = ?)');
            params.push(Number(filters.semester));
        }
        add('jenjang_id', filters.jenjang_id || filters.jenjangId);
        add('kelas', filters.kelas_id || filters.kelasId);
        add('mata_pelajaran_id', filters.mata_pelajaran_id || filters.mataPelajaranId);
        add('mata_kuliah_id', filters.mata_kuliah_id || filters.mataKuliahId);
        add('topik_id', filters.topik_id || filters.topikId);
        add('tahun', filters.tahun);
        add('status_keabsahan', filters.status_keabsahan || filters.statusKeabsahan);

        const whereSql = where.join(' AND ');
        const bind = params.length ? db.prepare(`SELECT 1 WHERE ${params.map(() => '?').join(' AND ')}`).bind(...params) : null;
        // Bind helper above is intentionally not executed; it only keeps parameter order explicit.
        void bind;

        const kompleksitasStats = await db.prepare(`
            SELECT kompleksitas, COUNT(*) as total,
                   ROUND(COUNT(*) * 100.0 / NULLIF((SELECT COUNT(*) FROM soal s WHERE ${whereSql}), 0), 1) as persentase
            FROM soal s
            WHERE ${whereSql} AND kompleksitas IS NOT NULL
            GROUP BY kompleksitas
            ORDER BY CASE kompleksitas WHEN 'sederhana' THEN 1 WHEN 'menengah' THEN 2 WHEN 'kompleks' THEN 3 ELSE 99 END
        `).bind(...params, ...params).all();

        const tingkatStats = await db.prepare(`
            SELECT tingkat_kesulitan, COUNT(*) as total,
                   ROUND(COUNT(*) * 100.0 / NULLIF((SELECT COUNT(*) FROM soal s WHERE ${whereSql}), 0), 1) as persentase
            FROM soal s
            WHERE ${whereSql} AND tingkat_kesulitan IS NOT NULL
            GROUP BY tingkat_kesulitan
            ORDER BY CASE tingkat_kesulitan WHEN 'mudah' THEN 1 WHEN 'sedang' THEN 2 WHEN 'sulit' THEN 3 ELSE 99 END
        `).bind(...params, ...params).all();

        const hierarchyStats = await db.prepare(`
            SELECT
                s.mata_pelajaran_id, mpl.nama AS mata_pelajaran_nama,
                s.mata_kuliah_id, mkl.nama AS mata_kuliah_nama,
                COUNT(*) AS total
            FROM soal s
            LEFT JOIN mata_pelajaran mpl ON s.mata_pelajaran_id = mpl.id
            LEFT JOIN mata_kuliah mkl ON s.mata_kuliah_id = mkl.id
            WHERE ${whereSql}
            GROUP BY s.mata_pelajaran_id, mpl.nama, s.mata_kuliah_id, mkl.nama
            ORDER BY total DESC
        `).bind(...params).all();

        return {
            kompleksitas: kompleksitasStats.results || [],
            tingkatKesulitan: tingkatStats.results || [],
            hierarchy: hierarchyStats.results || []
        };
    } catch (e) {
        console.error('Error getSoalStatistics:', e);
        return { kompleksitas: [], tingkatKesulitan: [], hierarchy: [], error: e.message };
    }
}

// ============================================================
// FASE 2 — HIERARCHY STATISTICS
// Statistik agregat yang mengikuti hierarchy sekolah dan perguruan tinggi.
// ============================================================
async function getHierarchyStatistics(db, filters = {}) {
    const result = {
        kategori: [], bidang: [], program: [], jenjang: [], kelas: [],
        mataPelajaran: [], mataKuliah: [], topik: [], soal: 0
    };
    try {
        // ------------------------------------------------------------
        // KATEGORI
        // ------------------------------------------------------------
        result.kategori = (await db.prepare(`
            SELECT k.id, k.nama,
                   COUNT(DISTINCT b.id) AS total_bidang,
                   COUNT(DISTINCT mp.id) AS total_mata_pelajaran,
                   COUNT(DISTINCT p.id) AS total_program,
                   COUNT(DISTINCT mk.id) AS total_mata_kuliah,
                   COUNT(DISTINCT t.id) AS total_topik,
                   COUNT(DISTINCT s.id) AS total_soal
            FROM kategori k
            LEFT JOIN bidang_studi b ON b.kategori_id = k.id
            LEFT JOIN mata_pelajaran mp ON mp.bidang_studi_id = b.id
            LEFT JOIN program_studi p ON p.bidang_studi_id = b.id
            LEFT JOIN mata_kuliah mk ON mk.program_studi_id = p.id
            LEFT JOIN topik t ON (
                t.mata_pelajaran_id = mp.id OR
                t.mata_kuliah_id = mk.id OR
                (t.program_studi_id = p.id AND t.mata_pelajaran_id IS NULL AND t.mata_kuliah_id IS NULL)
            )
            LEFT JOIN soal s ON s.topik_id = t.id
            ${filters.kategoriId ? 'WHERE k.id = ?' : ''}
            GROUP BY k.id
            ORDER BY k.urutan, k.nama
        `).bind(...(filters.kategoriId ? [filters.kategoriId] : [])).all()).results || [];

        // ------------------------------------------------------------
        // BIDANG STUDI
        // ------------------------------------------------------------
        result.bidang = (await db.prepare(`
            SELECT b.id, b.nama, b.kategori_id,
                   COUNT(DISTINCT mp.id) AS total_mata_pelajaran,
                   COUNT(DISTINCT p.id) AS total_program,
                   COUNT(DISTINCT mk.id) AS total_mata_kuliah,
                   COUNT(DISTINCT t.id) AS total_topik,
                   COUNT(DISTINCT s.id) AS total_soal
            FROM bidang_studi b
            LEFT JOIN mata_pelajaran mp ON mp.bidang_studi_id = b.id
            LEFT JOIN program_studi p ON p.bidang_studi_id = b.id
            LEFT JOIN mata_kuliah mk ON mk.program_studi_id = p.id
            LEFT JOIN topik t ON (
                t.mata_pelajaran_id = mp.id OR
                t.mata_kuliah_id = mk.id OR
                (t.program_studi_id = p.id AND t.mata_pelajaran_id IS NULL AND t.mata_kuliah_id IS NULL)
            )
            LEFT JOIN soal s ON s.topik_id = t.id
            ${filters.bidangId ? 'WHERE b.id = ?' : ''}
            GROUP BY b.id
            ORDER BY b.urutan, b.nama
        `).bind(...(filters.bidangId ? [filters.bidangId] : [])).all()).results || [];

        // ------------------------------------------------------------
        // PROGRAM STUDI — hanya jalur Mata Kuliah
        // ------------------------------------------------------------
        result.program = (await db.prepare(`
            SELECT p.id, p.nama, p.bidang_studi_id,
                   COUNT(DISTINCT mk.id) AS total_mata_kuliah,
                   COUNT(DISTINCT t.id) AS total_topik,
                   COUNT(DISTINCT s.id) AS total_soal
            FROM program_studi p
            LEFT JOIN mata_kuliah mk ON mk.program_studi_id = p.id
            LEFT JOIN topik t ON (
                t.mata_kuliah_id = mk.id OR
                (t.program_studi_id = p.id AND t.mata_pelajaran_id IS NULL AND t.mata_kuliah_id IS NULL)
            )
            LEFT JOIN soal s ON s.topik_id = t.id
            WHERE 1=1
              ${filters.bidangId ? 'AND p.bidang_studi_id = ?' : ''}
              ${filters.programId ? 'AND p.id = ?' : ''}
            GROUP BY p.id
            ORDER BY p.urutan, p.nama
        `).bind(...[filters.bidangId, filters.programId].filter(v => v !== undefined && v !== null && v !== '')).all()).results || [];

        // ------------------------------------------------------------
        // JENJANG — dipisahkan statistik sekolah vs pendidikan tinggi
        // ------------------------------------------------------------
        result.jenjang = (await db.prepare(`
            SELECT j.id, j.nama, j.jenis, j.kategori,
                   COUNT(DISTINCT k.id) AS total_kelas,
                   COUNT(DISTINCT mp.id) AS total_mata_pelajaran,
                   COUNT(DISTINCT mk.id) AS total_mata_kuliah,
                   COUNT(DISTINCT t.id) AS total_topik,
                   COUNT(DISTINCT s.id) AS total_soal
            FROM jenjang j
            LEFT JOIN kelas k ON k.jenjang_id = j.id
            LEFT JOIN mata_pelajaran mp ON mp.kelas_id = k.id
            LEFT JOIN mata_kuliah mk ON mk.jenjang_id = j.id
            LEFT JOIN topik t ON (t.mata_pelajaran_id = mp.id OR t.mata_kuliah_id = mk.id)
            LEFT JOIN soal s ON s.topik_id = t.id
            WHERE 1=1
              ${filters.jenjangId ? 'AND j.id = ?' : ''}
            GROUP BY j.id
            ORDER BY j.urutan, j.nama
        `).bind(...[filters.jenjangId].filter(v => v !== undefined && v !== null && v !== '')).all()).results || [];

        // ------------------------------------------------------------
        // KELAS — hanya jalur Mata Pelajaran
        // ------------------------------------------------------------
        result.kelas = (await db.prepare(`
            SELECT k.id, k.nama, k.jenjang_id,
                   j.nama AS jenjang_nama, j.jenis,
                   COUNT(DISTINCT mp.id) AS total_mata_pelajaran,
                   COUNT(DISTINCT t.id) AS total_topik,
                   COUNT(DISTINCT s.id) AS total_soal
            FROM kelas k
            LEFT JOIN jenjang j ON j.id = k.jenjang_id
            LEFT JOIN mata_pelajaran mp ON mp.kelas_id = k.id
            LEFT JOIN topik t ON t.mata_pelajaran_id = mp.id
            LEFT JOIN soal s ON s.topik_id = t.id
            WHERE 1=1
              ${filters.jenjangId ? 'AND k.jenjang_id = ?' : ''}
              ${filters.kelasId ? 'AND k.id = ?' : ''}
            GROUP BY k.id
            ORDER BY j.urutan, k.urutan, k.nama
        `).bind(...[filters.jenjangId, filters.kelasId].filter(v => v !== undefined && v !== null && v !== '')).all()).results || [];

        // ------------------------------------------------------------
        // MATA PELAJARAN
        // ------------------------------------------------------------
        result.mataPelajaran = (await db.prepare(`
            SELECT mp.id, mp.nama, mp.kode, mp.bidang_studi_id, mp.kelas_id,
                   j.id AS jenjang_id, j.nama AS jenjang_nama, j.jenis,
                   COUNT(DISTINCT t.id) AS total_topik,
                   COUNT(DISTINCT s.id) AS total_soal
            FROM mata_pelajaran mp
            JOIN kelas k ON k.id = mp.kelas_id
            JOIN jenjang j ON j.id = k.jenjang_id
            LEFT JOIN topik t ON t.mata_pelajaran_id = mp.id
            LEFT JOIN soal s ON s.mata_pelajaran_id = mp.id
            WHERE 1=1
              ${filters.bidangId ? 'AND mp.bidang_studi_id = ?' : ''}
              ${filters.jenjangId ? 'AND j.id = ?' : ''}
              ${filters.kelasId ? 'AND mp.kelas_id = ?' : ''}
            GROUP BY mp.id
            ORDER BY j.urutan, k.urutan, mp.urutan, mp.nama
        `).bind(...[filters.bidangId, filters.jenjangId, filters.kelasId].filter(v => v !== undefined && v !== null && v !== '')).all()).results || [];

        // ------------------------------------------------------------
        // MATA KULIAH
        // ------------------------------------------------------------
        result.mataKuliah = (await db.prepare(`
            SELECT mk.id, mk.nama, mk.kode, mk.program_studi_id, mk.jenjang_id, mk.semester,
                   COUNT(DISTINCT t.id) AS total_topik,
                   COUNT(DISTINCT s.id) AS total_soal
            FROM mata_kuliah mk
            LEFT JOIN topik t ON t.mata_kuliah_id = mk.id
            LEFT JOIN soal s ON s.mata_kuliah_id = mk.id
            WHERE 1=1
              ${filters.programId ? 'AND mk.program_studi_id = ?' : ''}
              ${filters.jenjangId ? 'AND mk.jenjang_id = ?' : ''}
              ${filters.semester ? 'AND mk.semester = ?' : ''}
            GROUP BY mk.id
            ORDER BY mk.semester, mk.urutan, mk.nama
        `).bind(...[filters.programId, filters.jenjangId, filters.semester].filter(v => v !== undefined && v !== null && v !== '')).all()).results || [];

        // ------------------------------------------------------------
        // TOPIK — mendukung kedua cabang hierarchy
        // ------------------------------------------------------------
        result.topik = (await db.prepare(`
            SELECT t.id, t.nama, t.program_studi_id, t.mata_pelajaran_id, t.mata_kuliah_id,
                   COUNT(DISTINCT s.id) AS total_soal
            FROM topik t
            LEFT JOIN soal s ON s.topik_id = t.id
            WHERE 1=1
              ${filters.mataPelajaranId ? 'AND t.mata_pelajaran_id = ?' : ''}
              ${filters.mataKuliahId ? 'AND t.mata_kuliah_id = ?' : ''}
              ${filters.programId ? 'AND (t.program_studi_id = ? OR t.mata_kuliah_id IN (SELECT id FROM mata_kuliah WHERE program_studi_id = ?))' : ''}
            GROUP BY t.id
            ORDER BY t.urutan, t.nama
        `).bind(...(
            [filters.mataPelajaranId, filters.mataKuliahId, filters.programId, filters.programId]
                .filter(v => v !== undefined && v !== null && v !== '')
        )).all()).results || [];

        const soalWhere = [];
        const soalParams = [];
        if (filters.kategoriId) { soalWhere.push('kategori_id = ?'); soalParams.push(filters.kategoriId); }
        if (filters.bidangId) { soalWhere.push('bidang_studi_id = ?'); soalParams.push(filters.bidangId); }
        if (filters.programId) { soalWhere.push('program_studi_id = ?'); soalParams.push(filters.programId); }
        if (filters.jenjangId) { soalWhere.push('jenjang_id = ?'); soalParams.push(filters.jenjangId); }
        if (filters.kelasId) { soalWhere.push('kelas = ? OR kelas = ?'); soalParams.push(filters.kelasId, filters.kelasId); }
        if (filters.mataPelajaranId) { soalWhere.push('mata_pelajaran_id = ?'); soalParams.push(filters.mataPelajaranId); }
        if (filters.mataKuliahId) { soalWhere.push('mata_kuliah_id = ?'); soalParams.push(filters.mataKuliahId); }
        const soalSql = `SELECT COUNT(*) AS total FROM soal WHERE status = 'AKTIF'${soalWhere.length ? ` AND (${soalWhere.join(' AND ')})` : ''}`;
        const soalRow = await db.prepare(soalSql).bind(...soalParams).first();
        result.soal = Number(soalRow?.total || 0);
        return result;
    } catch (e) {
        return { ...result, error: safeErrorMessage(e) };
    }
}

// ============================================================
// REORDER IDS - VERSI FINAL (Patch #16)
// ============================================================
// Teknik: "NULL DULU" untuk hindari FK constraint error.
// 
// Hanya bidang_studi yang punya FK ke kategori (dari skema).
// Tabel lain (soal, materi) kolom kategori_id bukan FK.
// ============================================================
async function acquireReorderLock(db, table, idField = 'id') {
    const lockKey = `__system_reorder_lock:${table}:${idField}`;
    const owner = crypto.randomUUID();
    const nowMs = Date.now();
    const nowIso = new Date(nowMs).toISOString();
    const leaseMs = 10 * 60 * 1000;
    const expiresMs = nowMs + leaseMs;
    const expiresIso = new Date(expiresMs).toISOString();
    const value = JSON.stringify({ owner, acquiredAt: nowIso, expiresAt: expiresIso });

    try {
        const existing = await db.prepare(
            `SELECT value FROM settings WHERE key = ? LIMIT 1`
        ).bind(lockKey).first();

        if (!existing) {
            try {
                await db.prepare(
                    `INSERT INTO settings (key, value, keterangan, created_at, updated_at)
                     VALUES (?, ?, ?, ?, ?)`
                ).bind(lockKey, value, 'Internal lock reorder ID', nowIso, nowIso).run();
                return { acquired: true, lockKey, owner, value, expiresMs };
            } catch (e) {
                // Another request may have inserted the lock between SELECT and INSERT.
                return { acquired: false, lockKey, owner, reason: 'busy' };
            }
        }

        let parsed = null;
        try { parsed = JSON.parse(existing.value || ''); } catch (_) {}
        const existingExpiresMs = Date.parse(parsed?.expiresAt || '') || 0;
        if (existingExpiresMs > nowMs) {
            return { acquired: false, lockKey, owner, reason: 'busy' };
        }

        // Stale lease: conditional replacement prevents two contenders from
        // both taking ownership of the same expired lock.
        const replaced = await db.prepare(
            `UPDATE settings
             SET value = ?, keterangan = ?, updated_at = ?
             WHERE key = ? AND value = ?`
        ).bind(value, 'Internal lock reorder ID', nowIso, lockKey, existing.value).run();

        if (Number(replaced?.meta?.changes || 0) !== 1) {
            return { acquired: false, lockKey, owner, reason: 'busy' };
        }
        return { acquired: true, lockKey, owner, value, expiresMs };
    } catch (e) {
        return { acquired: false, lockKey, owner, reason: `lock-error: ${e.message}` };
    }
}

async function releaseReorderLock(db, lock) {
    if (!lock?.acquired || !lock.lockKey || !lock.owner) return;
    try {
        await db.prepare(
            `DELETE FROM settings WHERE key = ? AND value = ?`
        ).bind(lock.lockKey, lock.value).run();
    } catch (e) {
        console.warn(`⚠️ Gagal melepas reorder lock ${lock.lockKey}:`, e.message);
    }
}

// ============================================================
// ATOMIC ID EDIT — LEGACY DIRECT EDIT PATHS
// Menyatukan update relasi + induk dalam satu transaksi D1.
// Lock yang sama dengan REORDER dipakai agar rename ID tidak
// berjalan bersamaan dengan SORT/REORDER pada entitas yang sama.
// ============================================================
const CURRICULUM_ENTITY_TYPE_BY_TABLE = Object.freeze({
    kategori: 'kategori',
    bidang_studi: 'bidang_studi',
    mata_pelajaran: 'mata_pelajaran',
    program_studi: 'program_studi',
    mata_kuliah: 'mata_kuliah',
    jenjang: 'jenjang',
    kelas: 'kelas',
    topik: 'topik',
    sub_topik: 'sub_topik',
    kisi_kisi: 'kisi_kisi',
    kemampuan_diuji: 'kemampuan_diuji',
    sub_kemampuan: 'sub_kemampuan'
});

async function updateEntityIdWithRelationsAtomic(db, { table, idField = 'id', oldId, newId, relationUpdates = [], parentSql, parentParams = [] }) {
    const lock = await acquireReorderLock(db, table, idField);
    if (!lock.acquired) {
        return { success: false, error: 'Data sedang diproses oleh operasi urutan/perubahan ID lain. Silakan coba lagi.' };
    }
    try {
        const statements = [db.prepare('PRAGMA defer_foreign_keys = ON')];
        const seenRelations = new Set();

        for (const rel of relationUpdates) {
            const relationKey = `${rel.table}.${rel.field}.${rel.where || ''}`;
            if (seenRelations.has(relationKey)) continue;
            seenRelations.add(relationKey);
            statements.push(
                db.prepare(
                    `UPDATE ${rel.table} SET ${rel.field} = ? WHERE ${rel.field} = ?${rel.where ? ` AND ${rel.where}` : ''}`
                ).bind(newId, oldId)
            );
        }

        // curriculum_relations is polymorphic: source_id/target_id can contain
        // the same ID value for different entity types. ID changes must therefore
        // update both sides while scoping each update by its discriminator.
        const curriculumType = CURRICULUM_ENTITY_TYPE_BY_TABLE[table];
        if (curriculumType) {
            const sourceKey = `curriculum_relations.source_id.source_type=${curriculumType}`;
            const targetKey = `curriculum_relations.target_id.target_type=${curriculumType}`;

            if (!seenRelations.has(sourceKey)) {
                statements.push(
                    db.prepare(
                        `UPDATE curriculum_relations SET source_id = ? WHERE source_id = ? AND source_type = ?`
                    ).bind(newId, oldId, curriculumType)
                );
            }

            if (!seenRelations.has(targetKey)) {
                statements.push(
                    db.prepare(
                        `UPDATE curriculum_relations SET target_id = ? WHERE target_id = ? AND target_type = ?`
                    ).bind(newId, oldId, curriculumType)
                );
            }
        }

        statements.push(db.prepare(parentSql).bind(...parentParams));
        await db.batch(statements);
        return { success: true };
    } catch (e) {
        return { success: false, error: e?.message || String(e) };
    } finally {
        await releaseReorderLock(db, lock);
    }
}

async function reorderIds(db, table, prefix, idField = 'id', nameField = 'nama', relationFields = []) {
    let reorderLock = null;
    try {
        // Serialize reorder operations for the same entity across Worker
        // invocations. The lease is stored in the existing settings table so
        // no new schema/table is required. A stale lease can be reclaimed.
        reorderLock = await acquireReorderLock(db, table, idField);
        if (!reorderLock.acquired) {
            return {
                success: false,
                error: 'Reorder sedang diproses oleh proses lain. Silakan coba lagi setelah proses selesai.'
            };
        }

        // ============================================================
        // 1. Ambil semua data induk SEKALI
        // ============================================================
        const data = await db.prepare(
            `SELECT * FROM ${table} ORDER BY urutan ASC, ${idField} ASC`
        ).all();

        if (!data.results || data.results.length === 0) {
            return { success: true, totalUpdated: 0, totalRelationsUpdated: 0 };
        }

        const totalItems = data.results.length;
        const padLength = String(totalItems).length > 3 ? String(totalItems).length : 3;

        // ============================================================
        // 2. Build mapping: oldId -> newId
        // ============================================================
        const idMap = [];
        let counter = 1;
        for (const row of data.results) {
            const oldId = row[idField];
            const newId = `${prefix}${String(counter).padStart(padLength, '0')}`;
            idMap.push({ oldId, newId });
            counter++;
        }

        // Tidak perlu snapshot SELECT untuk setiap relasi.
        // Semua perubahan relasi dilakukan langsung secara set-based
        // berdasarkan mapping oldId -> temporaryId -> newId.
        // Ini menghindari puluhan/ratusan query baca pada dataset besar.

        // D1 membatasi maksimal 100 bound parameters per statement.
        // CASE ... WHEN ? THEN ? menghasilkan 2 parameter per mapping,
        // sedangkan WHERE ... IN (...) membutuhkan 1 parameter per mapping.
        // 33 mapping = 99 parameter, sehingga tetap di bawah batas 100.
        const MAP_CHUNK_SIZE = 33;

        function buildCaseUpdate(tableName, fieldName, mappings, valueFactory, extraWhere = '') {
            const whenParts = [];
            const params = [];
            const whereParts = [];

            for (const mapping of mappings) {
                whenParts.push(`WHEN ? THEN ?`);
                params.push(mapping.oldId, valueFactory(mapping));
                whereParts.push('?');
            }

            const sql = `UPDATE ${tableName}
                SET ${fieldName} = CASE ${fieldName}
                    ${whenParts.join('\n                    ')}
                    ELSE ${fieldName}
                END
                WHERE ${fieldName} IN (${whereParts.join(',')})${extraWhere ? ` AND ${extraWhere}` : ''}`;

            for (const mapping of mappings) {
                params.push(mapping.oldId);
            }

            return db.prepare(sql).bind(...params);
        }

        const writeStatements = [];

        // ============================================================
        // 3. Generate temporary namespace yang collision-safe
        // ============================================================
        // Temporary ID tidak boleh berbenturan dengan ID yang sudah ada
        // pada tabel induk maupun nilai relasi yang sedang dipindahkan.
        // UUID membuat namespace praktis unik antar request, sedangkan
        // pengecekan DB memastikan tidak ada collision yang sudah tersimpan.
        let tmpPrefix = null;
        for (let attempt = 0; attempt < 5; attempt++) {
            const candidate = `__REORDER_TMP_${crypto.randomUUID()}_`;
            let collision = false;

            const parentCollision = await db.prepare(
                `SELECT 1 AS hit FROM ${table} WHERE ${idField} LIKE ? LIMIT 1`
            ).bind(`${candidate}%`).first();
            if (parentCollision) collision = true;

            if (!collision) {
                for (const rel of relationFields) {
                    const relCollision = await db.prepare(
                        `SELECT 1 AS hit FROM ${rel.table} WHERE ${rel.field} LIKE ? LIMIT 1`
                    ).bind(`${candidate}%`).first();
                    if (relCollision) {
                        collision = true;
                        break;
                    }
                }
            }

            if (!collision) {
                tmpPrefix = candidate;
                break;
            }
        }

        if (!tmpPrefix) {
            throw new Error('Gagal mendapatkan namespace temporary ID yang aman setelah 5 percobaan.');
        }

        // ============================================================
        // 4. Satu batch D1 atomik
        // ============================================================
        // Jika satu statement gagal, D1 membatalkan/rollback seluruh batch.
        // defer_foreign_keys menjaga FK tetap valid sampai seluruh perpindahan
        // old -> temporary -> new selesai di dalam transaksi yang sama.
        writeStatements.push(db.prepare(`PRAGMA defer_foreign_keys = ON`));

        // Fase A: semua ID induk old -> temporary.
        for (let i = 0; i < idMap.length; i += MAP_CHUNK_SIZE) {
            const chunk = idMap.slice(i, i + MAP_CHUNK_SIZE);
            writeStatements.push(
                buildCaseUpdate(
                    table,
                    idField,
                    chunk,
                    m => `${tmpPrefix}${m.newId}`
                )
            );
        }

        // Fase B: semua FK/referensi old -> temporary.
        // Setiap table.field diproses terpisah agar dua field pada tabel yang
        // sama (contoh topik_relations.topik_id dan related_topik_id) aman.
        for (const rel of relationFields) {
            for (let i = 0; i < idMap.length; i += MAP_CHUNK_SIZE) {
                const chunk = idMap.slice(i, i + MAP_CHUNK_SIZE);
                writeStatements.push(
                    buildCaseUpdate(
                        rel.table,
                        rel.field,
                        chunk,
                        m => `${tmpPrefix}${m.newId}`,
                        rel.where || ''
                    )
                );
            }
        }

        // Fase C: semua ID induk temporary -> final.
        // Untuk fase ini mapping yang dicari adalah temporary ID.
        for (let i = 0; i < idMap.length; i += MAP_CHUNK_SIZE) {
            const chunk = idMap.slice(i, i + MAP_CHUNK_SIZE);
            const whenParts = [];
            const params = [];
            const whereParts = [];

            for (const mapping of chunk) {
                const tempId = `${tmpPrefix}${mapping.newId}`;
                whenParts.push(`WHEN ? THEN ?`);
                params.push(tempId, mapping.newId);
                whereParts.push('?');
            }
            for (const mapping of chunk) {
                params.push(`${tmpPrefix}${mapping.newId}`);
            }

            const sql = `UPDATE ${table}
                SET ${idField} = CASE ${idField}
                    ${whenParts.join('\n                    ')}
                    ELSE ${idField}
                END
                WHERE ${idField} IN (${whereParts.join(',')})`;

            writeStatements.push(db.prepare(sql).bind(...params));
        }

        // Fase D: semua referensi temporary -> final.
        for (const rel of relationFields) {
            for (let i = 0; i < idMap.length; i += MAP_CHUNK_SIZE) {
                const chunk = idMap.slice(i, i + MAP_CHUNK_SIZE);
                const whenParts = [];
                const params = [];
                const whereParts = [];

                for (const mapping of chunk) {
                    const tempId = `${tmpPrefix}${mapping.newId}`;
                    whenParts.push(`WHEN ? THEN ?`);
                    params.push(tempId, mapping.newId);
                    whereParts.push('?');
                }
                for (const mapping of chunk) {
                    params.push(`${tmpPrefix}${mapping.newId}`);
                }

                const sql = `UPDATE ${rel.table}
                    SET ${rel.field} = CASE ${rel.field}
                        ${whenParts.join('\n                        ')}
                        ELSE ${rel.field}
                    END
                    WHERE ${rel.field} IN (${whereParts.join(',')})${rel.where ? ` AND ${rel.where}` : ''}`;

                writeStatements.push(db.prepare(sql).bind(...params));
            }
        }

        console.log(`🧩 Menjalankan ${writeStatements.length} statement dalam 1 D1 batch atomik (chunk ${MAP_CHUNK_SIZE})`);
        const batchResults = await db.batch(writeStatements);

        // D1 mengembalikan meta.changes untuk setiap statement UPDATE.
        // Hitung perubahan relasi dari fase B dan D tanpa SELECT tambahan.
        const chunkCount = Math.ceil(totalItems / MAP_CHUNK_SIZE);
        const phaseBStart = 1 + chunkCount;
        const phaseCStart = phaseBStart + (relationFields.length * chunkCount);
        const phaseDStart = phaseCStart + chunkCount;

        let totalUpdated = 0;
        let totalRelationsUpdated = 0;

        for (let i = 0; i < chunkCount; i++) {
            const result = batchResults[1 + i];
            totalUpdated += Number(result?.meta?.changes || 0);
        }

        for (let relIndex = 0; relIndex < relationFields.length; relIndex++) {
            const relationKey = `${relationFields[relIndex].table}.${relationFields[relIndex].field}`;
            let relationChanges = 0;

            // Fase B mengubah old -> temporary.
            for (let chunkIndex = 0; chunkIndex < chunkCount; chunkIndex++) {
                const result = batchResults[phaseBStart + relIndex * chunkCount + chunkIndex];
                relationChanges += Number(result?.meta?.changes || 0);
            }

            // Fase D mengubah temporary -> final.
            for (let chunkIndex = 0; chunkIndex < chunkCount; chunkIndex++) {
                const result = batchResults[phaseDStart + relIndex * chunkCount + chunkIndex];
                relationChanges += Number(result?.meta?.changes || 0);
            }

            // Setiap referensi yang berhasil dipindahkan mengalami 2 UPDATE,
            // sehingga bagi dua untuk mendapatkan jumlah referensi aktual.
            const restoredCount = relationChanges / 2;
            if (!Number.isInteger(restoredCount)) {
                console.warn(`⚠️ Verifikasi jumlah perubahan ${relationKey} bukan kelipatan 2 (${relationChanges}). Batch sudah committed; nilai relasi dihitung secara konservatif.`);
            }

            totalRelationsUpdated += Math.floor(restoredCount);
            console.log(`   ✅ ${relationKey}: ${restoredCount} referensi dipindahkan`);
        }

        // db.batch() yang sukses berarti seluruh sequence sudah dieksekusi
        // dan transaksi telah selesai. Jangan melempar exception setelah batch
        // sukses: pada titik ini rollback sudah tidak tersedia. Pemeriksaan
        // struktur hasil hanya dicatat sebagai warning agar fungsi tidak
        // melaporkan kegagalan palsu setelah data sudah committed.
        if (batchResults.length !== writeStatements.length) {
            console.warn(`⚠️ Jumlah hasil batch berbeda: ${batchResults.length}/${writeStatements.length}. Data batch tetap sudah committed.`);
        }

        console.log(`✅ Reorder selesai atomik: ${totalItems} ID, ${totalRelationsUpdated} relasi`);
        return {
            success: true,
            totalUpdated: totalItems,
            totalRelationsUpdated
        };
    } catch (e) {
        console.error('❌ reorderIds error:', e);
        return { success: false, error: e.message };
    } finally {
        await releaseReorderLock(db, reorderLock);
    }
}

// ============================================================
// GET CURRENT PREFIX - UNTUK SEMUA TABEL
// ============================================================
async function getCurrentPrefix(db, table) {
    try {
        const data = await db.prepare(`SELECT id FROM ${table} ORDER BY id LIMIT 1`).first();
        if (!data) return null;
        const match = data.id.match(/^([A-Za-z]+)/);
        return match ? match[1] : null;
    } catch (e) {
        console.error(`getCurrentPrefix error for ${table}:`, e);
        return null;
    }
}

// ============================================================
// HANDLER UPLOAD MASSAL KATEGORI -> KISI-KISI (DENGAN CEK DUPLIKAT)
// ============================================================
async function handleMassalHierarki(env, userId, chatId, text, db) {
  const parsed = parseHierarkiText(text);
  
  if (parsed.length === 0) {
    await smartMessage(chatId, 
      `❌ *Format tidak valid!*\n\n` +
      `Format yang benar:\n\n` +
      `KATEGORI: Matematika\n` +
      `BIDANG: Matematika Dasar\n` +
      `PROGRAM: S1 Matematika\n` +
      `TOPIK: Aljabar\n` +
      `SUBTOPIK: Persamaan Linear\n` +
      `KISI: UTS Aljabar | ALJ-001\n` +
      `---\n` +
      `KATEGORI: Fisika\n` +
      `BIDANG: Fisika Dasar\n` +
      `PROGRAM: S1 Fisika\n` +
      `TOPIK: Mekanika\n` +
      `SUBTOPIK: Gerak Lurus\n` +
      `KISI: UTS Mekanika | FIS-001\n\n` +
      `💡 Gunakan "---" sebagai pemisah antar hierarki`
    );
    return true;
  }
  
  await smartMessage(chatId, `⏳ Memproses ${parsed.length} hierarki...`);
  
  let successCount = 0;
  let errorCount = 0;
  let skippedCount = 0;
  let errors = [];
  let results = [];
  
  // Cache untuk mencegah duplikat dalam satu batch
  const cache = {
    kategori: {},
    bidang: {},
    program: {},
    topik: {},
    subtopik: {},
    kisi: {}
  };
  
  for (let i = 0; i < parsed.length; i++) {
    const item = parsed[i];
    try {
      // ============================================================
      // 1. PROSES KATEGORI
      // ============================================================
      let kategoriId = null;
      const kategoriKey = item.kategori.toLowerCase().trim();
      
      // Cek di cache dulu
      if (cache.kategori[kategoriKey]) {
        kategoriId = cache.kategori[kategoriKey];
        results.push(`ℹ️ Kategori "${item.kategori}" sudah ada di cache (${kategoriId})`);
      } else {
        // Cek di database
        let kategori = await db.prepare(
          `SELECT id FROM kategori WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?))`
        ).bind(item.kategori).first();
        
        if (!kategori) {
          const newId = await generateId(db, 'K', 'kategori');
          await db.prepare(
            `INSERT INTO kategori (id, nama) VALUES (?, ?)`
          ).bind(newId, item.kategori.trim()).run();
          kategoriId = newId;
          results.push(`✅ Kategori "${item.kategori}" dibuat (${kategoriId})`);
        } else {
          kategoriId = kategori.id;
          results.push(`ℹ️ Kategori "${item.kategori}" sudah ada (${kategoriId})`);
        }
        cache.kategori[kategoriKey] = kategoriId;
      }
      
      // ============================================================
      // 2. PROSES BIDANG STUDI
      // ============================================================
      let bidangId = null;
      if (item.bidang) {
        const bidangKey = `${kategoriId}|${item.bidang.toLowerCase().trim()}`;
        
        if (cache.bidang[bidangKey]) {
          bidangId = cache.bidang[bidangKey];
          results.push(`ℹ️ Bidang "${item.bidang}" sudah ada di cache (${bidangId})`);
        } else {
          let bidang = await db.prepare(
            `SELECT id FROM bidang_studi WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND kategori_id = ?`
          ).bind(item.bidang, kategoriId).first();
          
          if (!bidang) {
            const newId = await generateId(db, 'B', 'bidang_studi');
            await db.prepare(
              `INSERT INTO bidang_studi (id, kategori_id, nama) VALUES (?, ?, ?)`
            ).bind(newId, kategoriId, item.bidang.trim()).run();
            bidangId = newId;
            results.push(`✅ Bidang "${item.bidang}" dibuat (${bidangId})`);
          } else {
            bidangId = bidang.id;
            results.push(`ℹ️ Bidang "${item.bidang}" sudah ada (${bidangId})`);
          }
          cache.bidang[bidangKey] = bidangId;
        }
      }
      
      // ============================================================
      // 3. PROSES PROGRAM STUDI
      // ============================================================
      let programId = null;
      if (item.program && bidangId) {
        const programKey = `${bidangId}|${item.program.toLowerCase().trim()}`;
        
        if (cache.program[programKey]) {
          programId = cache.program[programKey];
          results.push(`ℹ️ Program "${item.program}" sudah ada di cache (${programId})`);
        } else {
          let program = await db.prepare(
            `SELECT id FROM program_studi WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND bidang_studi_id = ?`
          ).bind(item.program, bidangId).first();
          
          if (!program) {
            const newId = await generateId(db, 'P', 'program_studi');
            await db.prepare(
              `INSERT INTO program_studi (id, bidang_studi_id, nama) VALUES (?, ?, ?)`
            ).bind(newId, bidangId, item.program.trim()).run();
            programId = newId;
            results.push(`✅ Program "${item.program}" dibuat (${programId})`);
          } else {
            programId = program.id;
            results.push(`ℹ️ Program "${item.program}" sudah ada (${programId})`);
          }
          cache.program[programKey] = programId;
        }
      }
      
      // ============================================================
      // 4. PROSES TOPIK
      // ============================================================
      let topikId = null;
      if (item.topik && programId) {
        const topikKey = `${programId}|${item.topik.toLowerCase().trim()}`;
        
        if (cache.topik[topikKey]) {
          topikId = cache.topik[topikKey];
          results.push(`ℹ️ Topik "${item.topik}" sudah ada di cache (${topikId})`);
        } else {
          let topik = await db.prepare(
            `SELECT id FROM topik WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND program_studi_id = ?`
          ).bind(item.topik, programId).first();
          
          if (!topik) {
            const newId = await generateId(db, 'T', 'topik');
            await db.prepare(
              `INSERT INTO topik (id, program_studi_id, nama, normalized_nama) VALUES (?, ?, ?, ?)`
            ).bind(newId, programId, item.topik.trim(), normalizeTopicName(item.topik)).run();
            topikId = newId;
            results.push(`✅ Topik "${item.topik}" dibuat (${topikId})`);
          } else {
            topikId = topik.id;
            results.push(`ℹ️ Topik "${item.topik}" sudah ada (${topikId})`);
          }
          cache.topik[topikKey] = topikId;
        }
      }
      
      // ============================================================
      // 5. PROSES SUB-TOPIK
      // ============================================================
      let subtopikId = null;
      if (item.subtopik && topikId) {
        const subtopikKey = `${topikId}|${item.subtopik.toLowerCase().trim()}`;
        
        if (cache.subtopik[subtopikKey]) {
          subtopikId = cache.subtopik[subtopikKey];
          results.push(`ℹ️ SubTopik "${item.subtopik}" sudah ada di cache (${subtopikId})`);
        } else {
          let subtopik = await db.prepare(
            `SELECT id FROM sub_topik WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND topik_id = ?`
          ).bind(item.subtopik, topikId).first();
          
          if (!subtopik) {
            const newId = await generateId(db, 'S', 'sub_topik');
            await db.prepare(
              `INSERT INTO sub_topik (id, topik_id, nama) VALUES (?, ?, ?)`
            ).bind(newId, topikId, item.subtopik.trim()).run();
            subtopikId = newId;
            results.push(`✅ SubTopik "${item.subtopik}" dibuat (${subtopikId})`);
          } else {
            subtopikId = subtopik.id;
            results.push(`ℹ️ SubTopik "${item.subtopik}" sudah ada (${subtopikId})`);
          }
          cache.subtopik[subtopikKey] = subtopikId;
        }
      }
      
      // ============================================================
      // 6. PROSES KISI-KISI
      // ============================================================
      if (item.kisi && subtopikId) {
        const kisiKey = `${subtopikId}|${item.kisi.toLowerCase().trim()}`;
        
        if (cache.kisi[kisiKey]) {
          const existingId = cache.kisi[kisiKey];
          results.push(`⚠️ Kisi "${item.kisi}" sudah ada di cache (${existingId}), dilewati`);
          skippedCount++;
        } else {
          let kisiExist = await db.prepare(
            `SELECT id FROM kisi_kisi WHERE LOWER(TRIM(judul)) = LOWER(TRIM(?)) AND sub_topik_id = ?`
          ).bind(item.kisi, subtopikId).first();
          
          if (!kisiExist) {
            const kisiId = await generateId(db, 'I', 'kisi_kisi');
            await db.prepare(
              `INSERT INTO kisi_kisi (id, sub_topik_id, judul, kode, status) VALUES (?, ?, ?, ?, 'RESMI')`
            ).bind(kisiId, subtopikId, item.kisi.trim(), item.kode || null).run();
            results.push(`✅ Kisi "${item.kisi}" dibuat (${kisiId})${item.kode ? ` dengan kode ${item.kode}` : ''}`);
            cache.kisi[kisiKey] = kisiId;
          } else {
            results.push(`⚠️ Kisi "${item.kisi}" sudah ada (${kisiExist.id}), dilewati`);
            cache.kisi[kisiKey] = kisiExist.id;
            skippedCount++;
          }
        }
      } else if (item.kisi && !subtopikId) {
        results.push(`⚠️ Kisi "${item.kisi}" dilewati karena SubTopik tidak ditemukan`);
        skippedCount++;
      }
      
      successCount++;
      
    } catch (e) {
      errorCount++;
      errors.push(`Hierarki ${i+1}: ${e.message}`);
    }
  }
  
  // Kirim laporan
  let response = `✅ *UPLOAD HIERARKI SELESAI*\n\n📊 Statistik:\n`;
  response += `✅ Berhasil diproses: ${successCount} hierarki\n`;
  response += `⚠️ Dilewati (duplikat): ${skippedCount} hierarki\n`;
  response += `❌ Gagal: ${errorCount} hierarki\n\n`;
  response += `📋 *Detail:*\n`;
  results.slice(0, 20).forEach(r => response += `- ${r}\n`);
  if (results.length > 20) response += `- ... dan ${results.length - 20} detail lainnya\n\n`;
  
  if (errors.length > 0) {
    response += `⚠️ *Error Details:*\n`;
    errors.slice(0, 5).forEach(err => response += `- ${err}\n`);
    if (errors.length > 5) response += `- ... dan ${errors.length - 5} error lainnya\n`;
  }
  
  await smartMessage(chatId, response);
  return true;
}

// ============================================================
// KONSTANTA GLOBAL
// ============================================================
const MAX_SOAL_PER_GENERATE = 100;
const MAX_SOAL_PER_MESSAGE = 10;
const MAX_MESSAGE_LENGTH = 4000;

// ============================================================
// FUNGSI PARSER - TOP LEVEL
// ============================================================
function parseSingleSoalRobust(block) {
    let soalText = '';
    let pilihan_a = '', pilihan_b = '', pilihan_c = '', pilihan_d = '', pilihan_e = '';
    let jawaban = '';
    let pembahasan = '';
    const alasan = {a:'',b:'',c:'',d:'',e:''};

    const soalMatch = block.match(
        /\*{0,2}Soal\s*(?:Nomor\s*)?\d+\*{0,2}\s*[:.\-]\s*([\s\S]*?)(?=\n\s*\*{0,2}[A-Ea-e]\*{0,2}\s*[.)]\s|\n\s*Jawaban\s*:|\n\s*Pembahasan\s*:|\n\s*---|$)/i
    );
    if (soalMatch) {
        soalText = soalMatch[1].trim();
    } else {
        const fallback = block.match(
            /^\s*\*{0,2}\d+\*{0,2}\s*[.)]\s*([\s\S]*?)(?=\n\s*\*{0,2}[A-Ea-e]\*{0,2}\s*[.)]\s|\n\s*Jawaban\s*:|\n\s*Pembahasan\s*:|\n\s*---|$)/i
        );
        if (fallback) soalText = fallback[1].trim();
    }

    if (!soalText) return null;
    soalText = soalText.replace(/\n\s*-{2,}\s*$/g, '').trim();

    const optRegex = /\*{0,2}([A-Ea-e])\*{0,2}\s*[.)]\s*([^\n]+)/g;
    let m;
    while ((m = optRegex.exec(block)) !== null) {
        const huruf = m[1].toUpperCase();
        const isi = m[2].trim().replace(/\*+/g, '').replace(/\s+$/, '');
        if (huruf === 'A') pilihan_a = isi;
        else if (huruf === 'B') pilihan_b = isi;
        else if (huruf === 'C') pilihan_c = isi;
        else if (huruf === 'D') pilihan_d = isi;
        else if (huruf === 'E') pilihan_e = isi;
    }

    const jwbMatch = block.match(
        /\*{0,2}Jawaban\*{0,2}\s*[:.\-]\s*\*{0,2}([A-Ea-e])\*{0,2}\b/i
    );
    if (jwbMatch) jawaban = jwbMatch[1].toUpperCase();

    for (const huruf of ['A','B','C','D','E']) {
        const re = new RegExp(`\\*{0,2}Alasan\\s*${huruf}\\*{0,2}\\s*[:.\\-]\\s*([\\s\\S]*?)(?=\\n\\s*\\*{0,2}Alasan\\s*[A-E]\\*{0,2}\\s*[:.]|\\n\\s*-{2,}|$)`, 'i');
        const mAlasan = block.match(re);
        if (mAlasan) alasan[huruf.toLowerCase()] = mAlasan[1].trim().replace(/\*+/g, '').trim();
    }

    const pembMatch = block.match(
        /\*{0,2}Pembahasan\*{0,2}\s*[:.\-]\s*([\s\S]*?)(?=\n\s*-{2,}|\n\s*\*{0,2}Soal\s|\n\s*\*{0,2}\d+\*{0,2}\s*[.)]|$)/i
    );
    if (pembMatch) {
        pembahasan = pembMatch[1].trim().replace(/\*+/g, '').replace(/\n\s*-{2,}\s*$/g, '').trim();
    }

    if (!soalText || !pilihan_a || !pilihan_b || !jawaban) return null;

    return {
        soal: soalText,
        pilihan_a,
        pilihan_b,
        pilihan_c,
        pilihan_d,
        pilihan_e,
        jawaban,
        pembahasan,
        alasan_a: alasan.a, alasan_b: alasan.b, alasan_c: alasan.c, alasan_d: alasan.d, alasan_e: alasan.e
    };
}

function parseAISoalResponse(response) {
    if (!response || typeof response !== 'string') return [];

    let text = response;
    const firstSoalMatch = text.match(
        /(?:\*{0,2}Soal\s*(?:Nomor\s*)?\d+\*{0,2}\s*[:.\-]|\*{0,2}1\*{0,2}\s*[.)])/i
    );
    if (firstSoalMatch && firstSoalMatch.index > 0) {
        text = text.substring(firstSoalMatch.index);
    }
    text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

    const soalBlocks = text.split(
        /(?=\*{0,2}Soal\s*(?:Nomor\s*)?\d+\*{0,2}\s*[:.\-]|\n\*{0,2}\d+\*{0,2}\s*[.)]\s)/i
    );

    const hasil = [];
    for (const block of soalBlocks) {
        if (!block || !block.trim()) continue;
        const soalObj = parseSingleSoalRobust(block);
        if (soalObj) hasil.push(soalObj);
    }

    return hasil;
}

// ============================================================
// HANDLER GENERATE SOAL - DITINGKATKAN UNTUK 100 SOAL
// DENGAN AUTO-CLASSIFY LENGKAP
// ============================================================
async function handleAIGenerateSoalFull(
    env,
    userId,
    chatId,
    db,
    params = {}
) {
    const {
        topicId = null,
        subtopicId = null,
        kisiId = null,
        kemampuanId = null,
        subKemampuanId = null,
        level = 'sedang',
        count = 3
    } = params;

    // ===== PERBAIKAN: VALIDASI JUMLAH SOAL =====
    const safeCount = Number.isFinite(Number(count)) ? Number(count) : 3;
    const finalCount = Math.min(Math.max(safeCount, 1), MAX_SOAL_PER_GENERATE);
    const isBatch = finalCount > MAX_SOAL_PER_MESSAGE;

    try {
        // ============================================================
        // 1. AMBIL DATA HIERARKI
        // ============================================================
        let topicName = 'Topik';
        let subtopicName = 'Subtopik';
        let kisiJudul = 'Kisi-Kisi';
        let kemampuanNama = 'Kemampuan';
        let subKemampuanNama = 'Sub-Kemampuan';

        if (subKemampuanId) {
            const sub = await db.prepare(`
                SELECT 
                    sk.nama as sub_kemampuan_nama,
                    km.nama as kemampuan_nama,
                    km.id as kemampuan_id,
                    kk.judul as kisi_judul,
                    st.nama as subtopik_nama,
                    t.nama as topik_nama
                FROM sub_kemampuan sk
                LEFT JOIN kemampuan_diuji km ON sk.kemampuan_id = km.id
                LEFT JOIN kisi_kisi kk ON km.kisi_kisi_id = kk.id
                LEFT JOIN sub_topik st ON kk.sub_topik_id = st.id
                LEFT JOIN topik t ON st.topik_id = t.id
                WHERE sk.id = ?
            `).bind(subKemampuanId).first();

            if (sub) {
                subKemampuanNama = sub.sub_kemampuan_nama || 'Sub-Kemampuan';
                kemampuanNama = sub.kemampuan_nama || 'Kemampuan';
                kisiJudul = sub.kisi_judul || 'Kisi-Kisi';
                subtopicName = sub.subtopik_nama || 'Subtopik';
                topicName = sub.topik_nama || 'Topik';
            }
        }

        if (!subKemampuanId && kemampuanId) {
            const km = await db.prepare(`
                SELECT 
                    km.nama as kemampuan_nama,
                    kk.judul as kisi_judul,
                    st.nama as subtopik_nama,
                    t.nama as topik_nama
                FROM kemampuan_diuji km
                LEFT JOIN kisi_kisi kk ON km.kisi_kisi_id = kk.id
                LEFT JOIN sub_topik st ON kk.sub_topik_id = st.id
                LEFT JOIN topik t ON st.topik_id = t.id
                WHERE km.id = ?
            `).bind(kemampuanId).first();

            if (km) {
                kemampuanNama = km.kemampuan_nama || 'Kemampuan';
                kisiJudul = km.kisi_judul || 'Kisi-Kisi';
                subtopicName = km.subtopik_nama || 'Subtopik';
                topicName = km.topik_nama || 'Topik';
            }
        }

        if (!kemampuanId && !subKemampuanId && kisiId) {
            const kk = await db.prepare(`
                SELECT 
                    kk.judul as kisi_judul,
                    st.nama as subtopik_nama,
                    t.nama as topik_nama
                FROM kisi_kisi kk
                LEFT JOIN sub_topik st ON kk.sub_topik_id = st.id
                LEFT JOIN topik t ON st.topik_id = t.id
                WHERE kk.id = ?
            `).bind(kisiId).first();

            if (kk) {
                kisiJudul = kk.kisi_judul || 'Kisi-Kisi';
                subtopicName = kk.subtopik_nama || 'Subtopik';
                topicName = kk.topik_nama || 'Topik';
            }
        }

        if (!kisiId && !kemampuanId && !subKemampuanId && subtopicId) {
            const st = await db.prepare(`
                SELECT 
                    st.nama as subtopik_nama,
                    t.nama as topik_nama
                FROM sub_topik st
                LEFT JOIN topik t ON st.topik_id = t.id
                WHERE st.id = ?
            `).bind(subtopicId).first();

            if (st) {
                subtopicName = st.subtopik_nama || 'Subtopik';
                topicName = st.topik_nama || 'Topik';
            }
        }

        if (!subtopicId && !kisiId && !kemampuanId && !subKemampuanId && topicId) {
            const t = await db.prepare(`SELECT nama FROM topik WHERE id = ?`).bind(topicId).first();
            if (t) {
                topicName = t.nama;
            }
        }

        // ============================================================
        // 2. TAMPILKAN INFORMASI & PROSES
        // ============================================================
        let infoMsg = `🤖 *GENERATE SOAL DENGAN AI*\n\n`;
        infoMsg += `📖 Topik: ${topicName}\n`;
        if (subtopicName !== 'Subtopik') infoMsg += `📋 Subtopik: ${subtopicName}\n`;
        if (kisiJudul !== 'Kisi-Kisi') infoMsg += `📌 Kisi-Kisi: ${kisiJudul}\n`;
        if (kemampuanNama !== 'Kemampuan') infoMsg += `🎯 Kemampuan: ${kemampuanNama}\n`;
        if (subKemampuanNama !== 'Sub-Kemampuan') infoMsg += `📎 Sub-Kemampuan: ${subKemampuanNama}\n`;
        infoMsg += `\n⚡ Level: ${level}\n`;
        infoMsg += `📊 Jumlah: ${finalCount} soal\n\n`;

        if (isBatch) {
            infoMsg += `⏳ *Memproses ${finalCount} soal...*\n`;
            infoMsg += `⏱️ Estimasi waktu: ${Math.ceil(finalCount / 5)} menit\n`;
            infoMsg += `💡 Mohon tunggu, AI sedang bekerja...\n`;
            infoMsg += `📌 Anda akan mendapat notifikasi saat selesai.`;
        } else {
            infoMsg += `⏳ Mohon tunggu, AI sedang bekerja...\n`;
            infoMsg += `📌 Setelah selesai, soal akan otomatis diklasifikasi.`;
        }

        await smartResponseUniversal(chatId, infoMsg);

        // ============================================================
        // 3. BUILD PROMPT & CALL AI
        // ============================================================
        const prompt = buildGenerateSoalPromptWithKemampuan(
            topicName,
            subtopicName,
            kemampuanNama,
            subKemampuanNama,
            level,
            finalCount,
            kisiJudul
        );

        const taskType = isBatch ? 'batch_generate' : 'generate_soal';
        const result = await callAIHybrid(prompt, taskType, env);

        if (!result || !result.success) {
            await smartResponseUniversal(chatId,
                `❌ *Gagal generate soal!*\n\n` +
                `Error: ${(result && result.error) || 'Unknown error'}\n\n` +
                `💡 Coba lagi atau gunakan command: /ai_gen_soal [topik]\n` +
                `💡 Jika gagal terus, kurangi jumlah soal (maks ${MAX_SOAL_PER_GENERATE})`
            );
            return;
        }

        // ============================================================
        // 4. PARSE RESPONSE
        // ============================================================
        const soalList = parseAISoalResponseUniversal(result.response);

        if (!Array.isArray(soalList) || soalList.length === 0) {
            await smartResponseUniversal(chatId,
                `⚠️ *AI tidak menghasilkan soal yang valid!*\n\n` +
                `📝 Provider: ${escapeMarkdown(result.provider || '-')} (${escapeMarkdown(result.method || '-')})\n` +
                `📊 Target: ${finalCount} soal\n\n` +
                `💡 Coba lagi dengan format yang lebih spesifik.\n\n` +
                `📄 Preview response:\n\`\`\`\n${String(result.response || '').substring(0, 500)}\n\`\`\``
            );
            return;
        }

        // ============================================================
        // 5. TAMPILKAN HASIL (BATCH 10 SOAL)
        // ============================================================
        let output = `🤖 *HASIL GENERATE SOAL*\n\n`;
        output += `📖 *Topik:* ${escapeMarkdown(topicName)}\n`;
        if (subtopicName !== 'Subtopik') output += `📋 *Subtopik:* ${escapeMarkdown(subtopicName)}\n`;
        if (kisiJudul !== 'Kisi-Kisi') output += `📌 *Kisi-Kisi:* ${escapeMarkdown(kisiJudul)}\n`;
        if (kemampuanNama !== 'Kemampuan') output += `🎯 *Kemampuan:* ${escapeMarkdown(kemampuanNama)}\n`;
        if (subKemampuanNama !== 'Sub-Kemampuan') output += `📎 *Sub-Kemampuan:* ${escapeMarkdown(subKemampuanNama)}\n`;
        output += `⚡ *Level:* ${escapeMarkdown(level)}\n`;
        output += `📊 *Diminta:* ${finalCount} soal\n`;
        output += `📊 *Dihasilkan:* ${soalList.length} soal\n`;
        output += `🤖 *AI:* ${escapeMarkdown(result.provider || '-')} (${escapeMarkdown(result.method || '-')})\n`;
        if (result.time) output += `⏱️ *Waktu:* ${(result.time / 1000).toFixed(1)} detik\n`;
        output += `\n💡 *Soal akan otomatis diklasifikasi saat disimpan*\n`;
        output += `\n---\n\n`;

        const totalMessages = Math.ceil(soalList.length / MAX_SOAL_PER_MESSAGE);

        // ============================================================
        // SIMPAN SESSION (HANYA 1 KALI)
        // ============================================================
        const sessionData = (await getSession(env, userId)) || {};
        sessionData.aiGeneratedSoal = soalList;
        sessionData.aiTopicId = topicId;
        sessionData.aiSubtopicId = subtopicId;
        sessionData.aiKisiId = kisiId;
        sessionData.aiKemampuanId = kemampuanId;
        sessionData.aiSubKemampuanId = subKemampuanId;
        sessionData.aiLevel = level;
        sessionData.aiProvider = result.provider;
        sessionData.aiMethod = result.method;
        sessionData.aiTopicName = topicName;
        sessionData.aiSubtopikName = subtopicName;
        sessionData.aiKisiJudul = kisiJudul;
        sessionData.aiKemampuanNama = kemampuanNama;
        sessionData.aiSubKemampuanNama = subKemampuanNama;
        await saveSession(env, userId, sessionData);

        // ============================================================
        // KIRIM HASIL PER BATCH (10 SOAL PER PESAN)
        // ============================================================
        for (let batch = 0; batch < totalMessages; batch++) {
            const start = batch * MAX_SOAL_PER_MESSAGE;
            const end = Math.min(start + MAX_SOAL_PER_MESSAGE, soalList.length);
            let batchOutput = '';

            if (batch === 0) {
                batchOutput = output;
            } else {
                batchOutput = `📝 *Soal ${start + 1} - ${end} dari ${soalList.length}*\n\n`;
            }

            for (let i = start; i < end; i++) {
                const soal = soalList[i] || {};
                const num = i + 1;
                batchOutput += `*Soal ${num}*\n`;
                batchOutput += `📝 ${escapeMarkdown(soal.soal || '-')}\n\n`;
                batchOutput += `A. ${escapeMarkdown(soal.pilihan_a || '-')}\n`;
                batchOutput += `B. ${escapeMarkdown(soal.pilihan_b || '-')}\n`;
                batchOutput += `C. ${escapeMarkdown(soal.pilihan_c || '-')}\n`;
                batchOutput += `D. ${escapeMarkdown(soal.pilihan_d || '-')}\n`;
                batchOutput += `E. ${escapeMarkdown(soal.pilihan_e || '-')}\n\n`;
                batchOutput += `⭐ *Jawaban:* ${escapeMarkdown(soal.jawaban || '-')}\n`;
                if (soal.pembahasan) {
                    batchOutput += `📖 *Pembahasan:* ${escapeMarkdown(soal.pembahasan)}\n`;
                }
                batchOutput += `\n---\n\n`;
            }

            // Kirim batch (split kalau terlalu panjang)
            if (batchOutput.length > MAX_MESSAGE_LENGTH) {
                const parts = (typeof splitTextSmart === 'function')
                    ? splitTextSmart(batchOutput, MAX_MESSAGE_LENGTH)
                    : [batchOutput.substring(0, MAX_MESSAGE_LENGTH)];
                for (const part of parts) {
                    await smartResponseUniversal(chatId, part, { mode: 'send' });
                }
            } else {
                await smartResponseUniversal(chatId, batchOutput, { mode: 'send' });
            }
        }

        // ============================================================
        // 6. TOMBOL AKSI — callback ringkas; konteks disimpan di session
        // agar selalu aman di bawah batas callback Telegram.
        // ============================================================
        {
            const s = await getSession(env, userId);
            s.aiActionContext = {
                topicId: topicId || null, subtopicId: subtopicId || null, kisiId: kisiId || null,
                kemampuanId: kemampuanId || null, subKemampuanId: subKemampuanId || null,
                level: level || 'sedang', count: finalCount || 3
            };
            await saveSession(env, userId, s);
        }
        const keyboard = [
            [{ text: "💾 Simpan Semua (dengan Auto-Classify)", callback_data: `ai_save_all` }],
            [{ text: "📝 Simpan Berdasarkan Nomor", callback_data: `ai_save_by_number` }],
            [{ text: "📝 Generate Ulang", callback_data: `ai:r` }],
            [{ text: "🎯 Pilih Level Lain", callback_data: `ai:l` }],
            [{ text: "📊 Test Auto-Classify", callback_data: `ai_test_classify` }],
            [{ text: "🔙 Kembali", callback_data: "ai_menu" }]
        ];

        await sendInlineKeyboard(chatId,
            `✅ *Selesai!* ${soalList.length} soal berhasil digenerate.\n` +
            `📊 Total soal: ${soalList.length}\n` +
            `🤖 AI: ${escapeMarkdown(result.provider || '-')}\n\n` +
            `🏷️ *Auto-Classify akan menentukan:*\n` +
            `• Hierarki (Kategori → Sub-Kemampuan)\n` +
            `• Cara Penyajian, Tipe Isi, Tahap, Proses Kognitif\n` +
            `• Lapisan Pembelajaran, Sumber, Link\n` +
            `• Status Keabsahan (Resmi/Adaptasi/Mandiri)\n\n` +
            `Pilih aksi penyimpanan:`,
            keyboard
        );

    } catch (e) {
        console.error('AI Generate Soal Error:', e);
        await smartResponseUniversal(chatId, `❌ *Error:*\n\n${escapeMarkdown(e.message)}`);
    }
}

// ============================================================
// CATATAN:
// ============================================================
// 1. Fungsi lain di file worker.js Anda (handleAISaveAll,
//    handleCommand, initDatabase, dll) TIDAK BERUBAH.
//    Biarkan seperti semula.
//
// 2. Yang diganti HANYA:
//    - parseAISoalResponse (versi baru, lebih robust)
//    - parseSingleSoalRobust (fungsi baru)
//    - handleAIGenerateSoalFull (struktur diperbaiki)
//
// 3. Setelah tempel, pastikan:
//    - Tidak ada DUPLIKAT parseSingleSoalRobust
//    - Tidak ada DUPLIKAT handleAIGenerateSoalFull
//    - Tidak ada blok "4. PARSE RESPONSE" di luar fungsi
// ============================================================

// ============================================================
// HANDLER SAVE ALL - SIMPAN SEMUA SOAL DENGAN AUTO-CLASSIFY
// ============================================================

async function handleAISaveAll(env, userId, chatId, db) {
    const session = await getSession(env, userId);
    const soalList = session.aiGeneratedSoal || [];
    
    if (soalList.length === 0) {
        await smartResponseUniversal(chatId, '❌ Tidak ada soal untuk disimpan.');
        return true;
    }
    
    const kisiId = session.aiKisiId || null;
    const subKemampuanId = session.aiSubKemampuanId || null;
    const sumberBelajarId = session.aiSumberBelajarId || null;
    const sumberLink = session.aiSumberLink || null;
    const tahun = session.aiTahun || null;
    
    await smartResponseUniversal(chatId, 
        `⏳ *Menyimpan ${soalList.length} soal dengan Auto-Classify...*\n\n` +
        `🏷️ Auto-Classify akan menentukan:\n` +
        `├─ Hierarki (Kategori → Sub-Kemampuan)\n` +
        `├─ 6 Tabel Master\n` +
        `└─ Status Keabsahan\n\n` +
        `⏳ Mohon tunggu...`
    );
    
    let successCount = 0;
    let errorCount = 0;
    let errors = [];
    let classifications = [];
    
    for (let i = 0; i < soalList.length; i++) {
        const soal = soalList[i];
        try {
            const soalText = (soal.soal || '').trim();
            if (!soalText) {
                errorCount++;
                errors.push(`Soal ${i+1}: Soal kosong`);
                continue;
            }
            
            const jawaban = (soal.jawaban || '').toUpperCase().trim();
            if (!['A','B','C','D','E'].includes(jawaban)) {
                errorCount++;
                errors.push(`Soal ${i+1}: Jawaban tidak valid: "${soal.jawaban}"`);
                continue;
            }
            
            const pilihanA = (soal.pilihan_a || '').trim() || '';
            const pilihanB = (soal.pilihan_b || '').trim() || '';
            const pilihanC = (soal.pilihan_c || '').trim() || '';
            const pilihanD = (soal.pilihan_d || '').trim() || '';
            const pilihanE = (soal.pilihan_e || '').trim() || '';
            
            // ============================================================
            // FIX A4: Ganti kisiKisiId → kisiId
            // ============================================================
            const saveResult = await saveSoalWithAutoClassify(db, {
                soalText: soalText,
                pilihanA: pilihanA,
                pilihanB: pilihanB,
                pilihanC: pilihanC,
                pilihanD: pilihanD,
                pilihanE: pilihanE,
                jawabanBenar: jawaban,
                kisiKisiId: kisiId || null,
                subKemampuanId: subKemampuanId || null,
                sumberBelajarId: sumberBelajarId || null,
                sumberLink: sumberLink || null,
                tahun: tahun || null,
                userId: userId
            });
            
            if (saveResult.success) {
                successCount++;
                classifications.push({
                    index: i + 1,
                    id: saveResult.id,
                    classification: saveResult.classification
                });
            } else {
                errorCount++;
                errors.push(`Soal ${i+1}: ${saveResult.error}`);
            }
            
        } catch (e) {
            errorCount++;
            errors.push(`Soal ${i+1}: ${e.message}`);
        }
    }
    
    // ============================================================
    // TAMPILKAN LAPORAN LENGKAP
    // ============================================================
    
    let response = `✅ *SIMPAN SEMUA SOAL SELESAI*\n\n`;
    response += `📊 *Statistik:*\n`;
    response += `✅ Berhasil: ${successCount} soal\n`;
    response += `❌ Gagal: ${errorCount} soal\n\n`;
    
    // Tampilkan informasi sumber
    if (sumberBelajarId || sumberLink) {
        response += `📚 *Sumber:*\n`;
        if (sumberBelajarId) {
            const sumberInfo = await db.prepare(
                `SELECT nama FROM sumber_belajar WHERE id = ?`
            ).bind(sumberBelajarId).first();
            if (sumberInfo) {
                response += `   📌 Nama: ${sumberInfo.nama}\n`;
            }
            response += `   🆔 ID: ${sumberBelajarId}\n`;
        }
        if (sumberLink) {
            response += `   🔗 Link: ${sumberLink}\n`;
        }
        if (tahun) {
            response += `   📅 Tahun: ${tahun}\n`;
        }
        response += `\n`;
    }
    
    // Tampilkan ringkasan klasifikasi
    if (classifications.length > 0) {
        response += `🏷️ *Ringkasan Klasifikasi:*\n`;
        classifications.slice(0, 10).forEach(c => {
            const cls = c.classification;
            response += `   ${c.index}. ${c.id} → `;
            response += `${cls.kategori || '-'}`;
            response += ` → ${cls.subKemampuan || '-'}`;
            response += ` | ${getStoredCognitive(cls)}`;
            response += ` | ${cls.keabsahan || 'mandiri'}\n`;
        });
        if (classifications.length > 10) {
            response += `   ... dan ${classifications.length - 10} lainnya\n`;
        }
        response += `\n`;
    }
    
    if (errors.length > 0) {
        response += `⚠️ *Error:*\n`;
        errors.slice(0, 5).forEach(err => response += `- ${err}\n`);
        if (errors.length > 5) {
            response += `- ... dan ${errors.length - 5} error lainnya\n`;
        }
        response += `\n`;
    }
    
    response += `💡 *Auto-Classify berhasil menentukan:*\n`;
    response += `   ✅ Hierarki (Kategori → Sub-Kemampuan)\n`;
    response += `   ✅ 6 Tabel Master\n`;
    response += `   ✅ Status Keabsahan\n`;
    
    await smartResponseUniversal(chatId, response, { mode: 'send' });
    
    // Clear session
    session.aiGeneratedSoal = [];
    await saveSession(env, userId, session);
    return true;
}

// ============================================================
// HANDLER SAVE BY NUMBER - DENGAN AUTO-CLASSIFY
// ============================================================

async function handleAISaveByNumber(env, userId, chatId, db, selectedNumbers) {
    const session = await getSession(env, userId);
    const soalList = session.aiGeneratedSoal || [];
    
    if (soalList.length === 0) {
        await smartResponseUniversal(chatId, '❌ Tidak ada soal untuk disimpan.');
        return true;
    }
    
    const kisiId = session.aiKisiId || null;
    const subKemampuanId = session.aiSubKemampuanId || null;
    const sumberBelajarId = session.aiSumberBelajarId || null;
    const sumberLink = session.aiSumberLink || null;
    const tahun = session.aiTahun || null;
    
    let successCount = 0;
    let errorCount = 0;
    let errors = [];
    let classifications = [];
    
    for (const num of selectedNumbers) {
        const index = num - 1;
        if (index >= soalList.length) {
            errorCount++;
            errors.push(`Nomor ${num}: Tidak ada soal`);
            continue;
        }
        
        const soal = soalList[index];
        try {
            const soalText = (soal.soal || '').trim();
            if (!soalText) {
                errorCount++;
                errors.push(`Soal ${num}: Soal kosong`);
                continue;
            }
            
            const jawaban = (soal.jawaban || '').toUpperCase().trim();
            if (!['A','B','C','D','E'].includes(jawaban)) {
                errorCount++;
                errors.push(`Soal ${num}: Jawaban tidak valid`);
                continue;
            }
            
            const pilihanA = (soal.pilihan_a || '').trim() || '';
            const pilihanB = (soal.pilihan_b || '').trim() || '';
            const pilihanC = (soal.pilihan_c || '').trim() || '';
            const pilihanD = (soal.pilihan_d || '').trim() || '';
            const pilihanE = (soal.pilihan_e || '').trim() || '';
            
            // ============================================================
            // SIMPAN DENGAN AUTO-CLASSIFY LENGKAP
            // ============================================================
            const saveResult = await saveSoalWithAutoClassify(db, {
                soalText: soalText,
                pilihanA: pilihanA,
                pilihanB: pilihanB,
                pilihanC: pilihanC,
                pilihanD: pilihanD,
                pilihanE: pilihanE,
                jawabanBenar: jawaban,
                kisiKisiId: kisiId || null,
                subKemampuanId: subKemampuanId || null,
                sumberBelajarId: sumberBelajarId || null,
                sumberLink: sumberLink || null,
                tahun: tahun || null,
                userId: userId
            });
            
            if (saveResult.success) {
                successCount++;
                classifications.push({
                    number: num,
                    id: saveResult.id,
                    classification: saveResult.classification
                });
            } else {
                errorCount++;
                errors.push(`Soal ${num}: ${saveResult.error}`);
            }
            
        } catch (e) {
            errorCount++;
            errors.push(`Soal ${num}: ${e.message}`);
        }
    }
    
    let response = `✅ *SIMPAN SOAL BERDASARKAN NOMOR SELESAI*\n\n`;
    response += `📊 *Statistik:*\n`;
    response += `✅ Berhasil: ${successCount} soal\n`;
    response += `❌ Gagal: ${errorCount} soal\n\n`;
    
    if (classifications.length > 0) {
        response += `🏷️ *Klasifikasi:*\n`;
        classifications.slice(0, 10).forEach(c => {
            const cls = c.classification;
            response += `   ${c.number}. ${c.id} → `;
            response += `${cls.kategori || '-'}`;
            response += ` → ${cls.subKemampuan || '-'}`;
            response += ` | ${getStoredCognitive(cls)}\n`;
        });
        if (classifications.length > 10) {
            response += `   ... dan ${classifications.length - 10} lainnya\n`;
        }
        response += `\n`;
    }
    
    if (errors.length > 0) {
        response += `⚠️ *Error:*\n`;
        errors.slice(0, 5).forEach(err => response += `- ${err}\n`);
        if (errors.length > 5) {
            response += `- ... dan ${errors.length - 5} error lainnya\n`;
        }
    }
    
    await smartResponseUniversal(chatId, response, { mode: 'send' });
    return true;
}

// ============================================================
// HANDLER TEST CLASSIFY — DENGAN FORMAT MASTER [KODE] - NAMA
// ============================================================
async function handleAITestClassify(env, userId, chatId, db) {
    const session = await getSession(env, userId);
    const soalList = session.aiGeneratedSoal || [];
    
    if (soalList.length === 0) {
        await smartResponseUniversal(chatId, '❌ Tidak ada soal untuk di-test.');
        return true;
    }
    
    let msg = `🧪 *TEST AUTO-CLASSIFY*\n\n`;
    msg += `Mengklasifikasi ${Math.min(soalList.length, 5)} soal pertama...\n\n`;
    
    const testCount = Math.min(soalList.length, 5);
    
    for (let i = 0; i < testCount; i++) {
        const soal = soalList[i];
        const num = i + 1;
        
        try {
            const classification = await autoClassifyComplete(soal.soal, null, db);
            const masterIds = classification.masterIds || {};
            
            // Ambil detail nama master dari database
            const details = await getClassificationDetails(db, masterIds);
            
            msg += `📝 *Soal ${num}:*\n`;
            
            // Hierarki
            msg += `🏷️ *HIERARKI:*\n`;
            msg += `├─ ${formatMaster(masterIds.kategoriId, details.kategori)} Kategori\n`;
            msg += `├─ ${formatMaster(masterIds.bidangId, details.bidang)} Bidang\n`;
            msg += `├─ ${formatMaster(masterIds.programId, details.program)} Program\n`;
            msg += `├─ ${formatMaster(masterIds.topikId, details.topik)} Topik\n`;
            msg += `├─ ${formatMaster(masterIds.subtopikId, details.subtopik)} Sub-Topik\n`;
            msg += `├─ ${formatMaster(masterIds.kisiId, details.kisi)} Kisi-Kisi\n`;
            msg += `├─ ${formatMaster(masterIds.kemampuanId, details.kemampuan)} Kemampuan\n`;
            msg += `└─ ${formatMaster(masterIds.subKemampuanId, details.subKemampuan)} Sub-Kemampuan\n\n`;
            
            // Master Data
            msg += `📋 *MASTER DATA:*\n`;
            msg += `├─ ${formatMaster(masterIds.penyajianId, details.penyajian)} Cara Penyajian\n`;
            msg += `├─ ${formatMaster(masterIds.tipeIsiId, details.tipeIsi)} Tipe Isi\n`;
            msg += `├─ ${formatMaster(masterIds.tahapId, details.tahap)} Tahap\n`;
            msg += `├─ Proses Kognitif: ${getStoredCognitive(classification)}\n`;
            msg += `├─ ${formatMaster(masterIds.lapisanId, details.lapisan)} Lapisan\n`;
            msg += `├─ ${formatMaster(masterIds.sumberId, details.sumber)} Sumber\n`;
            msg += `└─ Keabsahan: ${classification.keabsahan || 'mandiri'}\n\n`;
            
            msg += `🎯 Confidence: ${Math.round((classification.confidence || 0.7) * 100)}%\n\n`;
            msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
            
        } catch (e) {
            msg += `❌ Soal ${num}: Error - ${e.message}\n\n`;
        }
    }
    
    msg += `\n💡 Gunakan tombol "Simpan Semua" untuk menyimpan dengan klasifikasi ini.`;
    
    const keyboard = [
        [{ text: "💾 Simpan Semua", callback_data: `ai_save_all` }],
        [{ text: "🔙 Kembali", callback_data: "ai_menu" }]
    ];
    
    await sendInlineKeyboard(chatId, msg, keyboard);
    return true;
}

// ============================================================
// HELPER: AMBIL DETAIL NAMA MASTER DARI IDs
// ============================================================
async function getClassificationDetails(db, masterIds) {
    const details = {
        kategori: null, bidang: null, program: null, topik: null,
        subtopik: null, kisi: null, kemampuan: null, subKemampuan: null,
        penyajian: null, tipeIsi: null, tahap: null, lapisan: null, sumber: null
    };
    
    try {
        if (masterIds.kategoriId) {
            const r = await db.prepare(`SELECT nama FROM kategori WHERE id = ?`).bind(masterIds.kategoriId).first();
            if (r) details.kategori = r.nama;
        }
        if (masterIds.bidangId) {
            const r = await db.prepare(`SELECT nama FROM bidang_studi WHERE id = ?`).bind(masterIds.bidangId).first();
            if (r) details.bidang = r.nama;
        }
        if (masterIds.programId) {
            const r = await db.prepare(`SELECT nama FROM program_studi WHERE id = ?`).bind(masterIds.programId).first();
            if (r) details.program = r.nama;
        }
        if (masterIds.topikId) {
            const r = await db.prepare(`SELECT nama FROM topik WHERE id = ?`).bind(masterIds.topikId).first();
            if (r) details.topik = r.nama;
        }
        if (masterIds.subtopikId) {
            const r = await db.prepare(`SELECT nama FROM sub_topik WHERE id = ?`).bind(masterIds.subtopikId).first();
            if (r) details.subtopik = r.nama;
        }
        if (masterIds.kisiId) {
            const r = await db.prepare(`SELECT judul FROM kisi_kisi WHERE id = ?`).bind(masterIds.kisiId).first();
            if (r) details.kisi = r.judul;
        }
        if (masterIds.kemampuanId) {
            const r = await db.prepare(`SELECT nama FROM kemampuan_diuji WHERE id = ?`).bind(masterIds.kemampuanId).first();
            if (r) details.kemampuan = r.nama;
        }
        if (masterIds.subKemampuanId) {
            const r = await db.prepare(`SELECT nama FROM sub_kemampuan WHERE id = ?`).bind(masterIds.subKemampuanId).first();
            if (r) details.subKemampuan = r.nama;
        }
        if (masterIds.penyajianId) {
            const r = await db.prepare(`SELECT nama FROM cara_penyajian WHERE id = ?`).bind(masterIds.penyajianId).first();
            if (r) details.penyajian = r.nama;
        }
        if (masterIds.tipeIsiId) {
            const r = await db.prepare(`SELECT nama FROM tipe_isi_soal WHERE id = ?`).bind(masterIds.tipeIsiId).first();
            if (r) details.tipeIsi = r.nama;
        }
        if (masterIds.tahapId) {
            const r = await db.prepare(`SELECT nama FROM tahap_pembelajaran WHERE id = ?`).bind(masterIds.tahapId).first();
            if (r) details.tahap = r.nama;
        }
        if (masterIds.lapisanId) {
            const r = await db.prepare(`SELECT nama FROM lapisan_pembelajaran WHERE id = ?`).bind(masterIds.lapisanId).first();
            if (r) details.lapisan = r.nama;
        }
        if (masterIds.sumberId) {
            const r = await db.prepare(`SELECT nama FROM sumber_belajar WHERE id = ?`).bind(masterIds.sumberId).first();
            if (r) details.sumber = r.nama;
        }
    } catch (e) {
        console.error('getClassificationDetails error:', e);
    }
    
    return details;
}

// ============================================================
// FUNGSI BANTU AMBIL DATA HIERARKI (TAMBAHKAN DI BAWAH)
// ============================================================
async function getHierarchyData(db, params) {
    const { topicId, subtopicId, kisiId, kemampuanId, subKemampuanId } = params;
    
    // Default values
    let topikName = 'Topik', subtopikName = 'Subtopik', kisiJudul = 'Kisi-Kisi', 
        kemampuanNama = 'Kemampuan', subKemampuanNama = 'Sub-Kemampuan';
    
    try {
        let query = `
            SELECT 
                t.nama as topik_nama,
                st.nama as subtopik_nama,
                kk.judul as kisi_judul,
                km.nama as kemampuan_nama,
                sk.nama as sub_kemampuan_nama
            FROM topik t
            LEFT JOIN sub_topik st ON st.topik_id = t.id
            LEFT JOIN kisi_kisi kk ON kk.sub_topik_id = st.id
            LEFT JOIN kemampuan_diuji km ON km.kisi_kisi_id = kk.id
            LEFT JOIN sub_kemampuan sk ON sk.kemampuan_id = km.id
            WHERE 1=1
        `;
        let bind = [];
        
        if (subKemampuanId) { 
            query += ` AND sk.id = ?`; 
            bind.push(subKemampuanId); 
        } else if (kemampuanId) { 
            query += ` AND km.id = ?`; 
            bind.push(kemampuanId); 
        } else if (kisiId) { 
            query += ` AND kk.id = ?`; 
            bind.push(kisiId); 
        } else if (subtopicId) { 
            query += ` AND st.id = ?`; 
            bind.push(subtopicId); 
        } else if (topicId) { 
            query += ` AND t.id = ?`; 
            bind.push(topicId); 
        }
        
        query += ` LIMIT 1`;
        
        const data = await db.prepare(query).bind(...bind).first();
        
        if (data) {
            topikName = data.topik_nama || topikName;
            subtopikName = data.subtopik_nama || subtopikName;
            kisiJudul = data.kisi_judul || kisiJudul;
            kemampuanNama = data.kemampuan_nama || kemampuanNama;
            subKemampuanNama = data.sub_kemampuan_nama || subKemampuanNama;
        }
    } catch (e) {
        console.error('Get hierarchy data error:', e);
    }
    
    return { topikName, subtopikName, kisiJudul, kemampuanNama, subKemampuanNama };
}

// ============================================================
// HANDLER REGENERASI SOAL
// ============================================================
async function handleAIRegenerateSoal(env, userId, chatId, db, soalId, variation) {
    try {
        // Ambil soal asli
        const soal = await db.prepare(`SELECT * FROM soal WHERE id = ?`).bind(soalId).first();
        
        if (!soal) {
            await smartResponseUniversal(chatId, '❌ Soal tidak ditemukan.');
            return;
        }
        
        const varLabels = {
            'serupa': 'Serupa (angka/konteks berbeda)',
            'konteks': 'Konteks berbeda',
            'sulit': 'Lebih Sulit',
            'mudah': 'Lebih Mudah'
        };
        
        await smartResponseUniversal(chatId, 
            `⏳ *Meregenerasi soal...*\n\n` +
            `📝 Soal asli: ${soal.soal.substring(0, 100)}...\n` +
            `🔄 Variasi: ${varLabels[variation] || variation}\n\n` +
            `⏳ Mohon tunggu...`
        );
        
        
                // Build prompt dengan format Universal Markdown
        const pilihanAsli = `A. ${soal.pilihan_a || '-'}\nB. ${soal.pilihan_b || '-'}\nC. ${soal.pilihan_c || '-'}\nD. ${soal.pilihan_d || '-'}\nE. ${soal.pilihan_e || '-'}`;
        
        const prompt = buildRegenerateSoalPrompt(
            soal.soal,
            pilihanAsli,
            soal.jawaban_benar,
            variation
        );

        // Panggil AI
        const result = await callAIHybrid(prompt, 'regenerate_soal', env);
        
        if (!result.success) {
            await smartResponseUniversal(chatId, `❌ Gagal regenerate: ${result.error || 'Unknown error'}`);
            return;
        }
        
        // Parse response
        const soalList = parseAISoalResponseUniversal(result.response);
        
        if (soalList.length === 0) {
            await smartResponseUniversal(chatId, `⚠️ AI tidak menghasilkan soal valid.\n\n${result.response.substring(0, 500)}...`);
            return;
        }
        
        const newSoal = soalList[0];
        
        // Tampilkan hasil
        let output = `🔄 *HASIL REGENERASI SOAL*\n\n`;
        output += `📝 *Soal Asli:*\n${soal.soal}\n\n`;
        output += `🔄 *Soal Baru (${varLabels[variation] || variation}):*\n\n`;
        output += `📝 ${newSoal.soal}\n\n`;
        output += `A. ${newSoal.pilihan_a}\n`;
        output += `B. ${newSoal.pilihan_b}\n`;
        output += `C. ${newSoal.pilihan_c}\n`;
        output += `D. ${newSoal.pilihan_d}\n`;
        output += `E. ${newSoal.pilihan_e}\n\n`;
        output += `⭐ *Jawaban:* ${newSoal.jawaban}\n`;
        if (newSoal.pembahasan) {
            output += `📖 *Pembahasan:* ${newSoal.pembahasan}\n`;
        }
        
        const keyboard = [
            [{ text: "💾 Simpan Soal", callback_data: `ai_save_regen_${soalId}` }],
            [{ text: "🔄 Variasi Lain", callback_data: `ai_regen_soal_${soalId}` }],
            [{ text: "🔙 Kembali", callback_data: "ai_menu" }]
        ];
        
        await sendInlineKeyboard(chatId, output, keyboard);
        
        // Simpan di session
        const session = await getSession(env, userId);
        session.aiGeneratedSoal = [newSoal];
        session.aiOriginalSoalId = soalId;
        await saveSession(env, userId, session);
        
    } catch (e) {
        console.error('Regenerate Soal Error:', e);
        await smartResponseUniversal(chatId, `❌ Error: ${e.message}`);
    }
}

// ============================================================
// HANDLER GENERATE PEMBAHASAN - DITINGKATKAN
// ============================================================

async function handleAIGeneratePembahasan(env, userId, chatId, db, soalId) {
    try {
        // ============================================================
        // 1. AMBIL SOAL
        // ============================================================
        const soal = await db.prepare(`SELECT * FROM soal WHERE id = ?`)
            .bind(soalId).first();
        
        if (!soal) {
            await smartResponseUniversal(chatId, '❌ Soal tidak ditemukan.');
            return;
        }
        
        // ============================================================
        // 2. INFORMASI PROSES
        // ============================================================
        await smartResponseUniversal(chatId, 
            `📖 *MENGENERATE PEMBAHASAN*\n\n` +
            `📝 ${escapeMarkdown(soal.soal.substring(0, 100))}...\n\n` +
            `⏳ Estimasi waktu: 30-60 detik\n` +
            `⏳ Mohon tunggu, AI sedang bekerja...`
        );
        
        // ============================================================
        // 3. BUILD PROMPT & CALL AI
        // ============================================================
        const prompt = buildGeneratePembahasanPrompt(
            soal.soal,
            soal.jawaban_benar,
            soal.pilihan_a,
            soal.pilihan_b,
            soal.pilihan_c,
            soal.pilihan_d,
            soal.pilihan_e
        );
        
        const result = await callAIHybrid(prompt, 'generate_pembahasan', env);
        
        if (!result.success) {
            await smartResponseUniversal(chatId, 
                `❌ Gagal generate pembahasan: ${escapeMarkdown(result.error || 'Unknown error')}\n\n` +
                `💡 Coba lagi dengan command: /ai_pembahasan ${escapeMarkdown(soalId)}`
            );
            return;
        }
        
        // ============================================================
        // 4. HITUNG KATA
        // ============================================================
        const wordCount = result.response.split(/\s+/).length;
        
        // ============================================================
        // 5. TAMPILKAN HASIL
        // ============================================================
        let output = `📖 *PEMBAHASAN SOAL*\n\n`;
        output += `📝 *Soal:*\n${escapeMarkdown(soal.soal)}\n\n`;
        output += `⭐ *Jawaban:* ${escapeMarkdown(soal.jawaban_benar)}\n`;
        output += `🤖 *AI:* ${escapeMarkdown(result.provider)} (${escapeMarkdown(result.method)})\n`;
        output += `📊 *Jumlah Kata:* ${wordCount.toLocaleString()} kata\n`;
        if (result.time) output += `⏱️ *Waktu:* ${(result.time/1000).toFixed(1)} detik\n`;
        output += `\n---\n\n`;
        
        // ============================================================
        // 🆕 SANITIZE OUTPUT AI
        // ============================================================
        output += sanitizeAIContent(result.response);
        
        // ============================================================
        // 6. TOMBOL AKSI
        // ============================================================
        const keyboard = [
            [{ text: "💾 Simpan Pembahasan", callback_data: `ai_save_pembahasan_${soalId}` }],
            [{ text: "🔄 Generate Ulang", callback_data: `ai_pembahasan_${soalId}` }],
            [{ text: "🔙 Kembali", callback_data: "ai_menu" }]
        ];
        
        // ============================================================
        // 7. KIRIM OUTPUT (SPLIT CERDAS)
        // ============================================================
        if (output.length > 4000) {
            const parts = splitTextSmart(output, 4000);
            for (let i = 0; i < parts.length; i++) {
                if (i === parts.length - 1) {
                    // Bagian terakhir: kirim dengan keyboard
                    await sendInlineKeyboard(chatId, parts[i], keyboard);
                } else {
                    // Bagian lain: kirim tanpa keyboard
                    await smartResponseUniversal(chatId, parts[i], { mode: 'send' });
                }
            }
        } else {
            await sendInlineKeyboard(chatId, output, keyboard);
        }
        
        // ============================================================
        // 8. SIMPAN SESSION
        // ============================================================
        const session = await getSession(env, userId);
        session.aiGeneratedPembahasan = result.response;
        session.aiPembahasanSoalId = soalId;
        session.aiPembahasanWordCount = wordCount;
        await saveSession(env, userId, session);
        
    } catch (e) {
        console.error('Generate Pembahasan Error:', e);
        await smartResponseUniversal(chatId, `❌ Error:\n\n${escapeMarkdown(e.message)}`);
    }
}

