// ============================================================
// 1. GET MATERI PROGRESS
// ============================================================
async function getMateriProgress(db, materiId) {
    try {
        const progress = await db.prepare(`
            SELECT tahap_kode, status, word_count, provider, error_message,
                   started_at, completed_at
            FROM materi_progress
            WHERE materi_id = ?
            ORDER BY tahap_kode
        `).bind(materiId).all();
        
        return progress.results || [];
    } catch (e) {
        console.error('getMateriProgress error:', e);
        return [];
    }
}

// ============================================================
// 2. FORMAT PROGRESS MESSAGE
// ============================================================
function formatProgressMessage(materi, progressList) {
    let msg = `📊 *PROGRES MATERI*\n\n`;
    msg += `🆔 ID: \`${materi.id}\`\n`;
    msg += `📖 Judul: ${materi.judul || '-'}\n`;
    msg += `📌 Status: ${materi.status || '-'}\n\n`;
    
    const statusIcons = {
        'pending': '⏳',
        'processing': '🔄',
        'done': '✅',
        'failed': '❌'
    };
    
    const statusLabels = {
        'pending': 'Menunggu',
        'processing': 'Sedang Diproses',
        'done': 'Selesai',
        'failed': 'Gagal'
    };
    
    let doneCount = 0;
    let failedCount = 0;
    let pendingCount = 0;
    let totalWords = 0;
    
    msg += `📋 *Progres per Tahap:*\n`;
    for (const p of progressList) {
        const t = TAHAP_PEMBELAJARAN[p.tahap_kode];
        if (!t) continue;
        
        const icon = statusIcons[p.status] || '❓';
        const label = statusLabels[p.status] || p.status;
        
        msg += `${icon} *${p.tahap_kode}* — ${t.nama}\n`;
        msg += `    Status: ${label}`;
        if (p.word_count > 0) msg += ` | ${p.word_count.toLocaleString()} kata`;
        if (p.provider) msg += ` | ${p.provider}`;
        msg += `\n`;
        
        if (p.error_message) {
            msg += `    ❌ Error: ${p.error_message.substring(0, 80)}\n`;
        }
        
        if (p.status === 'done') doneCount++;
        else if (p.status === 'failed') failedCount++;
        else pendingCount++;
        
        totalWords += p.word_count || 0;
    }
    
    msg += `\n📊 *Ringkasan:*\n`;
    msg += `   ✅ Selesai: ${doneCount}\n`;
    msg += `   ❌ Gagal: ${failedCount}\n`;
    msg += `   ⏳ Menunggu: ${pendingCount}\n`;
    msg += `   📝 Total kata: ${totalWords.toLocaleString()}\n`;
    
    return msg;
}

// ============================================================
// 3. FORMAT DAFTAR MATERI
// ============================================================
function formatMateriList(materiList, page = 1, totalPages = 1) {
    let msg = `📚 *DAFTAR MATERI (Hal ${page}/${totalPages || 1})*\n\n`;
    
    if (!materiList || materiList.length === 0) {
        msg += `❌ Belum ada materi.\n\n`;
        msg += `💡 Generate materi dengan:\n`;
        msg += `• /ai → Generate Materi (Multi-Tahap)\n`;
        return msg;
    }
    
    const statusIcons = {
        'DRAFT': '📝',
        'READY': '✅',
        'PARTIAL': '⚠️',
        'PUBLISHED': '🌐',
        'ARCHIVED': '📦'
    };
    
    for (let i = 0; i < materiList.length; i++) {
        const m = materiList[i];
        const icon = statusIcons[m.status] || '📄';
        
        let tahapCount = 0;
        try {
            tahapCount = JSON.parse(m.tahap_dipilih || '[]').length;
        } catch (e) {}
        
        msg += `${(page - 1) * 10 + i + 1}. ${icon} *${m.judul || 'Tanpa Judul'}*\n`;
        msg += `   🆔 \`${m.id}\`\n`;
        msg += `   📊 ${tahapCount} tahap | ${(m.total_kata || 0).toLocaleString()} kata\n`;
        msg += `   📌 Status: ${m.status}\n`;
        if (m.created_at) {
            msg += `   📅 ${new Date(m.created_at).toLocaleDateString('id-ID')}\n`;
        }
        msg += `\n`;
    }
    
    return msg;
}

// ============================================================
// 4. FORMAT DETAIL MATERI
// ============================================================
function formatMateriDetail(materi) {
    let tahapDipilih = [];
    let tahapDilewati = [];
    
    try {
        tahapDipilih = JSON.parse(materi.tahap_dipilih || '[]');
        tahapDilewati = JSON.parse(materi.tahap_dilewati || '[]');
    } catch (e) {}
    
    let msg = `📚 *DETAIL MATERI*\n\n`;
    msg += `🆔 ID: \`${materi.id}\`\n`;
    msg += `📖 Judul: ${materi.judul || '-'}\n`;
    msg += `📌 Status: ${materi.status}\n`;
    msg += `📊 Format: ${materi.format || '-'}\n`;
    msg += `📝 Total kata: ${(materi.total_kata || 0).toLocaleString()}\n`;
    msg += `📅 Dibuat: ${materi.created_at ? new Date(materi.created_at).toLocaleString('id-ID') : '-'}\n\n`;
    
    msg += `📌 *Tahap Dipilih (${tahapDipilih.length}):*\n`;
    for (const tk of tahapDipilih) {
        const t = TAHAP_PEMBELAJARAN[tk];
        if (t) msg += `   ${t.icon} ${tk} — ${t.nama}\n`;
    }
    
    if (tahapDilewati.length > 0) {
        msg += `\n⏭️ *Tahap Dilewati (${tahapDilewati.length}):*\n`;
        for (const tk of tahapDilewati) {
            const t = TAHAP_PEMBELAJARAN[tk];
            if (t) msg += `   ⬜ ${tk} — ${t.nama}\n`;
        }
    }
    
    if (materi.provider) {
        msg += `\n🤖 Provider: ${materi.provider}\n`;
    }
    
    return msg;
}

// ============================================================
// 5. GET CONTEXT DARI MATERI (untuk regen)
// ============================================================
async function getMateriContextFromMateri(db, materi) {
    const context = {
        kategori: null, bidang: null, program: null,
        topik: null, subtopik: null, kisi: null,
        kemampuan: null, subKemampuan: null
    };
    
    try {
        if (materi.kategori_id) {
            const k = await db.prepare(`SELECT nama FROM kategori WHERE id = ?`)
                .bind(materi.kategori_id).first();
            if (k) context.kategori = k.nama;
        }
        if (materi.bidang_studi_id) {
            const b = await db.prepare(`SELECT nama FROM bidang_studi WHERE id = ?`)
                .bind(materi.bidang_studi_id).first();
            if (b) context.bidang = b.nama;
        }
        if (materi.program_studi_id) {
            const p = await db.prepare(`SELECT nama FROM program_studi WHERE id = ?`)
                .bind(materi.program_studi_id).first();
            if (p) context.program = p.nama;
        }
        if (materi.topik_id) {
            const t = await db.prepare(`SELECT nama FROM topik WHERE id = ?`)
                .bind(materi.topik_id).first();
            if (t) context.topik = t.nama;
        }
        if (materi.sub_topik_id) {
            const st = await db.prepare(`SELECT nama FROM sub_topik WHERE id = ?`)
                .bind(materi.sub_topik_id).first();
            if (st) context.subtopik = st.nama;
        }
        if (materi.kisi_kisi_id) {
            const kk = await db.prepare(`SELECT judul FROM kisi_kisi WHERE id = ?`)
                .bind(materi.kisi_kisi_id).first();
            if (kk) context.kisi = kk.judul;
        }
        if (materi.kemampuan_id) {
            const km = await db.prepare(`SELECT nama FROM kemampuan_diuji WHERE id = ?`)
                .bind(materi.kemampuan_id).first();
            if (km) context.kemampuan = km.nama;
        }
        if (materi.sub_kemampuan_id) {
            const sk = await db.prepare(`SELECT nama FROM sub_kemampuan WHERE id = ?`)
                .bind(materi.sub_kemampuan_id).first();
            if (sk) context.subKemampuan = sk.nama;
        }
    } catch (e) {
        console.error('getMateriContextFromMateri error:', e);
    }
    
    return context;
}

// ============================================================
// 6. REBUILD KONTEN MATERI DARI PROGRESS
// ============================================================
async function rebuildMateriContent(db, materiId) {
    try {
        const materi = await db.prepare(`SELECT * FROM materi WHERE id = ?`)
            .bind(materiId).first();
        
        if (!materi) return false;
        
        const progressList = await db.prepare(`
            SELECT tahap_kode, konten, word_count, status
            FROM materi_progress
            WHERE materi_id = ?
            ORDER BY tahap_kode
        `).bind(materiId).all();
        
        let tahapDipilih = [];
        let tahapDilewati = [];
        try {
            tahapDipilih = JSON.parse(materi.tahap_dipilih || '[]');
            tahapDilewati = JSON.parse(materi.tahap_dilewati || '[]');
        } catch (e) {}
        
        let combinedContent = `# 📚 MATERI: ${materi.judul || 'Materi'}\n\n`;
        combinedContent += `## 📋 Informasi Materi\n\n`;
        combinedContent += `- **Tahap Dipilih:** ${tahapDipilih.join(', ')}\n`;
        if (tahapDilewati.length > 0) {
            combinedContent += `- **Tahap Dilewati:** ${tahapDilewati.join(', ')}\n`;
        }
        combinedContent += `\n---\n\n`;
        
        combinedContent += `## 📑 Daftar Isi\n\n`;
        for (const tk of tahapDipilih) {
            const t = TAHAP_PEMBELAJARAN[tk];
            if (t) combinedContent += `- ${t.icon} Tahap ${tk}: ${t.nama}\n`;
        }
        combinedContent += `\n---\n\n`;
        
        let totalWords = 0;
        
        for (const p of progressList.results || []) {
            const t = TAHAP_PEMBELAJARAN[p.tahap_kode];
            if (!t) continue;
            
            // Header baru dari kode
            combinedContent += `# ${t.icon} Tahap ${p.tahap_kode}: ${t.nama}\n\n`;
            combinedContent += `> ${t.deskripsi}\n\n`;
            
            if (p.status === 'done' && p.konten) {
                let content = p.konten;
                
                const lines = content.split('\n');
                const cleanedLines = [];
                let foundFirstContent = false;
                
                for (const line of lines) {
                    const trimmed = line.trim();
                    
                    if (!foundFirstContent && trimmed === '') continue;
                    if (/^Berikut adalah materi untuk/i.test(trimmed)) continue;
                    if (/^#{1,3}\s*[📚🔍⚙️💡🔗📊📋🔥🏆]?\s*Tahap\s*T\d/i.test(trimmed)) continue;
                    
                    foundFirstContent = true;
                    cleanedLines.push(line);
                }
                
                content = cleanedLines.join('\n').trim();
                content = content.replace(/\n{3,}/g, '\n\n');
                
                if (content.length > 50) {
                    combinedContent += content + `\n\n---\n\n`;
                    totalWords += p.word_count || 0;
                } else {
                    combinedContent += `⚠️ *Materi tahap ini belum tersedia.*\n\n---\n\n`;
                }
            } else {
                combinedContent += `⚠️ *Materi tahap ini belum tersedia.*\n\n---\n\n`;
            }
        }
        
        // Update materi
        await db.prepare(`
            UPDATE materi SET konten = ?, total_kata = ?, updated_at = ?
            WHERE id = ?
        `).bind(combinedContent, totalWords, new Date().toISOString(), materiId).run();

        // FASE 4: sinkronkan chunk setiap kali konten utama selesai direbuild.
        const chunkResult = await rebuildMateriChunks(db, materiId);
        if (!chunkResult.success) console.warn('⚠️ Sinkronisasi chunk materi gagal:', chunkResult.error);
        
        console.log(`✅ rebuildMateriContent: ${materiId} - ${totalWords} kata`);
        
        return true;
    } catch (e) {
        console.error('rebuildMateriContent error:', e);
        return false;
    }
}

// ============================================================
// 7. GET MATERI STATS
// ============================================================
async function getMateriStats(db) {
    const stats = {
        totalMateri: 0,
        totalKata: 0,
        rataKata: 0,
        topikPopuler: [],
        tahapPopuler: [],
        tahapSkip: []
    };
    
    try {
        const total = await db.prepare(`SELECT COUNT(*) as c, SUM(total_kata) as t FROM materi`).first();
        stats.totalMateri = total?.c || 0;
        stats.totalKata = total?.t || 0;
        stats.rataKata = stats.totalMateri > 0 ? Math.round(stats.totalKata / stats.totalMateri) : 0;
        
        const topikPopuler = await db.prepare(`
            SELECT t.nama as topik, COUNT(m.id) as jumlah
            FROM materi m
            LEFT JOIN topik t ON m.topik_id = t.id
            WHERE t.nama IS NOT NULL
            GROUP BY t.nama
            ORDER BY jumlah DESC
            LIMIT 5
        `).all();
        stats.topikPopuler = topikPopuler.results || [];
        
        const allMateri = await db.prepare(`SELECT tahap_dipilih, tahap_dilewati FROM materi`).all();
        const totalMateri = allMateri.results?.length || 0;
        
        const tahapCount = {};
        const skipCount = {};
        
        for (const m of allMateri.results || []) {
            try {
                const dipilih = JSON.parse(m.tahap_dipilih || '[]');
                const dilewati = JSON.parse(m.tahap_dilewati || '[]');
                
                for (const t of dipilih) tahapCount[t] = (tahapCount[t] || 0) + 1;
                for (const t of dilewati) skipCount[t] = (skipCount[t] || 0) + 1;
            } catch (e) {}
        }
        
        stats.tahapPopuler = Object.entries(tahapCount)
            .map(([kode, jumlah]) => ({
                kode,
                nama: TAHAP_PEMBELAJARAN[kode]?.nama || kode,
                jumlah,
                persen: totalMateri > 0 ? Math.round((jumlah / totalMateri) * 100) : 0
            }))
            .sort((a, b) => b.jumlah - a.jumlah);
        
        stats.tahapSkip = Object.entries(skipCount)
            .map(([kode, jumlah]) => ({
                kode,
                nama: TAHAP_PEMBELAJARAN[kode]?.nama || kode,
                jumlah,
                persen: totalMateri > 0 ? Math.round((jumlah / totalMateri) * 100) : 0
            }))
            .sort((a, b) => b.jumlah - a.jumlah);
    } catch (e) {
        console.error('getMateriStats error:', e);
    }
    
    return stats;
}

// ============================================================
// 🆕 PATCH 8: FUNGSI VERSIONING
// ============================================================

// ============================================================
// 1. BUAT VERSI BARU (SNAPSHOT)
// ============================================================
async function createMateriVersion(db, materiId, options = {}) {
    try {
        const {
            label = null,
            catatan = null,
            createdBy = null,
            mergeStrategy = 'snapshot',
            mergedFrom = null,
            setActive = false
        } = options;
        
        // ============================================================
        // 1. AMBIL DATA MATERI SAAT INI
        // ============================================================
        const materi = await db.prepare(`SELECT * FROM materi WHERE id = ?`)
            .bind(materiId).first();
        
        if (!materi) {
            return { success: false, error: 'Materi tidak ditemukan' };
        }
        
        // ============================================================
        // 2. CARI VERSI TERAKHIR
        // ============================================================
        const lastVersion = await db.prepare(`
            SELECT MAX(versi) as max_versi FROM materi_versions WHERE materi_id = ?
        `).bind(materiId).first();
        
        const newVersi = (lastVersion?.max_versi || 0) + 1;
        
        // ============================================================
        // 3. GENERATE ID
        // ============================================================
        const id = await generateId(db, 'MV', 'materi_versions');
        
        // ============================================================
        // 4. JIKA setActive = true, MATIKAN VERSI LAIN DULU
        // ============================================================
        if (setActive) {
            await db.prepare(`
                UPDATE materi_versions SET is_active = 0 WHERE materi_id = ?
            `).bind(materiId).run();
        }
        
        // ============================================================
        // 5. INSERT VERSI BARU
        // ============================================================
        await db.prepare(`
            INSERT INTO materi_versions (
                id, materi_id, versi,
                judul, konten, glosarium, peta_konsep,
                tahap_dipilih, tahap_dilewati, jumlah_tahap,
                format, provider, total_kata,
                is_active, status,
                label, catatan, created_by,
                merged_from, merge_strategy,
                created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
            id, materiId, newVersi,
            materi.judul, materi.konten, materi.glosarium, materi.peta_konsep,
            materi.tahap_dipilih, materi.tahap_dilewati, materi.jumlah_tahap,
            materi.format, materi.provider, materi.total_kata,
            setActive ? 1 : 0,
            mergeStrategy === 'rollback' ? 'rollback' : 
            mergeStrategy === 'manual' ? 'merged' : 'snapshot',
            label, catatan, createdBy,
            mergedFrom ? JSON.stringify(mergedFrom) : null,
            mergeStrategy,
            new Date().toISOString()
        ).run();
        
        // ============================================================
        // 6. UPDATE MATERI DENGAN TOTAL_VERSI
        // ============================================================
        await db.prepare(`
            UPDATE materi SET 
                total_versi = ?,
                versi_aktif = CASE WHEN ? = 1 THEN ? ELSE versi_aktif END,
                updated_at = ?
            WHERE id = ?
        `).bind(
            newVersi,
            setActive ? 1 : 0,
            newVersi,
            new Date().toISOString(),
            materiId
        ).run();
        
        console.log(`✅ Versi ${newVersi} dibuat untuk materi ${materiId}`);
        
        return {
            success: true,
            id: id,
            versi: newVersi,
            isActive: setActive
        };
        
    } catch (e) {
        console.error('createMateriVersion error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 2. AMBIL DAFTAR VERSI
// ============================================================
async function getMateriVersions(db, materiId) {
    try {
        const result = await db.prepare(`
            SELECT 
                id, materi_id, versi,
                judul, total_kata, jumlah_tahap,
                is_active, status,
                label, catatan, created_by,
                merged_from, merge_strategy,
                created_at,
                LENGTH(konten) as konten_length
            FROM materi_versions
            WHERE materi_id = ?
            ORDER BY versi DESC
        `).bind(materiId).all();
        
        return result.results || [];
    } catch (e) {
        console.error('getMateriVersions error:', e);
        return [];
    }
}

// ============================================================
// 3. AMBIL VERSI TERTENTU (LENGKAP)
// ============================================================
async function getMateriVersion(db, materiId, versi) {
    try {
        const result = await db.prepare(`
            SELECT * FROM materi_versions
            WHERE materi_id = ? AND versi = ?
        `).bind(materiId, versi).first();
        
        return result;
    } catch (e) {
        console.error('getMateriVersion error:', e);
        return null;
    }
}

// ============================================================
// 4. BANDINGKAN 2 VERSI
// ============================================================
async function compareMateriVersions(db, materiId, versiA, versiB) {
    try {
        const vA = await getMateriVersion(db, materiId, versiA);
        const vB = await getMateriVersion(db, materiId, versiB);
        
        if (!vA) return { success: false, error: `Versi ${versiA} tidak ditemukan` };
        if (!vB) return { success: false, error: `Versi ${versiB} tidak ditemukan` };
        
        // ============================================================
        // PARSE TAHAP
        // ============================================================
        let tahapA = [], tahapB = [];
        try { tahapA = JSON.parse(vA.tahap_dipilih || '[]'); } catch (e) {}
        try { tahapB = JSON.parse(vB.tahap_dipilih || '[]'); } catch (e) {}
        
        // ============================================================
        // HITUNG DIFF
        // ============================================================
        const kontenA = vA.konten || '';
        const kontenB = vB.konten || '';
        
        // Split per baris untuk deteksi perubahan
        const linesA = kontenA.split('\n');
        const linesB = kontenB.split('\n');
        
        // Hitung perubahan sederhana
        const addedLines = linesB.filter(l => !linesA.includes(l) && l.trim());
        const removedLines = linesA.filter(l => !linesB.includes(l) && l.trim());
        
        // Cari tahap yang berbeda
        const onlyInA = tahapA.filter(t => !tahapB.includes(t));
        const onlyInB = tahapB.filter(t => !tahapA.includes(t));
        
        return {
            success: true,
            versiA: {
                versi: vA.versi,
                judul: vA.judul,
                total_kata: vA.total_kata,
                jumlah_tahap: vA.jumlah_tahap,
                tahap: tahapA,
                konten_length: kontenA.length,
                created_at: vA.created_at,
                label: vA.label,
                catatan: vA.catatan
            },
            versiB: {
                versi: vB.versi,
                judul: vB.judul,
                total_kata: vB.total_kata,
                jumlah_tahap: vB.jumlah_tahap,
                tahap: tahapB,
                konten_length: kontenB.length,
                created_at: vB.created_at,
                label: vB.label,
                catatan: vB.catatan
            },
            diff: {
                kataA: vA.total_kata || 0,
                kataB: vB.total_kata || 0,
                selisihKata: (vB.total_kata || 0) - (vA.total_kata || 0),
                
                tahapA: tahapA.length,
                tahapB: tahapB.length,
                tahapHanyaA: onlyInA,
                tahapHanyaB: onlyInB,
                tahapSama: tahapA.filter(t => tahapB.includes(t)),
                
                barisDitambah: addedLines.length,
                barisDihapus: removedLines.length,
                kontenBerubah: kontenA !== kontenB
            },
            addedLines: addedLines.slice(0, 20),
            removedLines: removedLines.slice(0, 20)
        };
        
    } catch (e) {
        console.error('compareMateriVersions error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 5. ROLLBACK KE VERSI LAMA
// ============================================================
async function rollbackMateriVersion(db, materiId, targetVersi, options = {}) {
    try {
        const { createdBy = null, createBackup = true } = options;
        
        // ============================================================
        // 1. AMBIL DATA VERSI LAMA
        // ============================================================
        const version = await getMateriVersion(db, materiId, targetVersi);
        
        if (!version) {
            return { success: false, error: `Versi ${targetVersi} tidak ditemukan` };
        }
        
        // ============================================================
        // 2. AMBIL DATA MATERI SAAT INI
        // ============================================================
        const currentMateri = await db.prepare(`SELECT * FROM materi WHERE id = ?`)
            .bind(materiId).first();
        
        if (!currentMateri) {
            return { success: false, error: 'Materi tidak ditemukan' };
        }
        
        // ============================================================
        // 3. BACKUP VERSI SAAT INI (OPSIONAL)
        // ============================================================
        let backupResult = null;
        
        if (createBackup) {
            backupResult = await createMateriVersion(db, materiId, {
                label: `Backup sebelum rollback ke v${targetVersi}`,
                catatan: `Auto-backup saat rollback ke versi ${targetVersi}`,
                createdBy: createdBy,
                mergeStrategy: 'snapshot',
                setActive: false
            });
            
            if (!backupResult.success) {
                console.warn('⚠️ Gagal buat backup sebelum rollback:', backupResult.error);
            }
        }
        
        // ============================================================
        // 4. ROLLBACK: COPY DATA VERSI LAMA KE MATERI
        // ============================================================
        await db.prepare(`
            UPDATE materi SET
                judul = ?,
                konten = ?,
                glosarium = ?,
                peta_konsep = ?,
                tahap_dipilih = ?,
                tahap_dilewati = ?,
                jumlah_tahap = ?,
                total_kata = ?,
                updated_at = ?
            WHERE id = ?
        `).bind(
            version.judul,
            version.konten,
            version.glosarium,
            version.peta_konsep,
            version.tahap_dipilih,
            version.tahap_dilewati,
            version.jumlah_tahap,
            version.total_kata,
            new Date().toISOString(),
            materiId
        ).run();
        
        // ============================================================
        // 5. BUAT VERSI BARU (ROLLBACK)
        // ============================================================
        const rollbackResult = await createMateriVersion(db, materiId, {
            label: `Rollback dari v${currentMateri.versi_aktif || '?'} ke v${targetVersi}`,
            catatan: `Rollback ke versi ${targetVersi}`,
            createdBy: createdBy,
            mergeStrategy: 'rollback',
            mergedFrom: [targetVersi],
            setActive: true
        });
        
        console.log(`✅ Rollback materi ${materiId} ke versi ${targetVersi} berhasil`);
        
        return {
            success: true,
            targetVersi: targetVersi,
            newVersi: rollbackResult.versi,
            backupVersi: backupResult?.versi || null,
            restored: {
                judul: version.judul,
                total_kata: version.total_kata,
                jumlah_tahap: version.jumlah_tahap
            }
        };
        
    } catch (e) {
        console.error('rollbackMateriVersion error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 6. HAPUS VERSI
// ============================================================
async function deleteMateriVersion(db, materiId, versi) {
    try {
        // Cek apakah versi ada
        const version = await getMateriVersion(db, materiId, versi);
        
        if (!version) {
            return { success: false, error: `Versi ${versi} tidak ditemukan` };
        }
        
        // Cek apakah versi ini aktif
        if (version.is_active === 1) {
            return { 
                success: false, 
                error: `Versi ${versi} sedang aktif. Rollback dulu ke versi lain sebelum hapus.` 
            };
        }
        
        // Cek apakah ini versi terakhir
        const lastVersion = await db.prepare(`
            SELECT MAX(versi) as max_versi FROM materi_versions WHERE materi_id = ?
        `).bind(materiId).first();
        
        if (lastVersion && lastVersion.max_versi === versi) {
            return { 
                success: false, 
                error: `Tidak bisa hapus versi terakhir (v${versi}).` 
            };
        }
        
        // Hapus
        await db.prepare(`
            DELETE FROM materi_versions 
            WHERE materi_id = ? AND versi = ?
        `).bind(materiId, versi).run();
        
        // Update total_versi di materi
        const total = await db.prepare(`
            SELECT COUNT(*) as total FROM materi_versions WHERE materi_id = ?
        `).bind(materiId).first();
        
        await db.prepare(`
            UPDATE materi SET total_versi = ?, updated_at = ? WHERE id = ?
        `).bind(total?.total || 0, new Date().toISOString(), materiId).run();
        
        return {
            success: true,
            deletedVersi: versi,
            remainingVersions: total?.total || 0
        };
        
    } catch (e) {
        console.error('deleteMateriVersion error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 7. MERGE VERSI (GABUNGKAN TAHAP DARI BEBERAPA VERSI)
// ============================================================
async function mergeMateriVersions(db, materiId, versiList, options = {}) {
    try {
        const {
            label = null,
            catatan = null,
            createdBy = null,
            strategy = 'manual',  // 'manual' | 'auto'
            tahapMapping = null   // { T1: versiNumber, T2: versiNumber, ... }
        } = options;
        
        if (!versiList || versiList.length < 2) {
            return { success: false, error: 'Minimal 2 versi untuk merge' };
        }
        
        // ============================================================
        // 1. AMBIL SEMUA VERSI
        // ============================================================
        const versions = [];
        for (const v of versiList) {
            const version = await getMateriVersion(db, materiId, v);
            if (!version) {
                return { success: false, error: `Versi ${v} tidak ditemukan` };
            }
            versions.push(version);
        }
        
        // ============================================================
        // 2. AMBIL DATA MATERI
        // ============================================================
        const materi = await db.prepare(`SELECT * FROM materi WHERE id = ?`)
            .bind(materiId).first();
        
        if (!materi) {
            return { success: false, error: 'Materi tidak ditemukan' };
        }
        
        // ============================================================
        // 3. TENTUKAN TAHAP DARI SETIAP VERSI
        // ============================================================
        let mergedTahapSet = new Set();
        let mergedContent = '';
        const tahapSourceMap = {};  // { T1: versiNumber, ... }
        
        if (tahapMapping) {
            // ========== MODE MANUAL: User tentukan mapping ==========
            for (const [tahapKode, versiNum] of Object.entries(tahapMapping)) {
                const version = versions.find(v => v.versi === versiNum);
                if (!version) {
                    console.warn(`⚠️ Versi ${versiNum} tidak ada untuk tahap ${tahapKode}`);
                    continue;
                }
                
                // Cari konten tahap ini di versi tersebut
                const tahapContent = extractTahapContent(version.konten, tahapKode);
                
                if (tahapContent) {
                    mergedTahapSet.add(tahapKode);
                    tahapSourceMap[tahapKode] = versiNum;
                    mergedContent += tahapContent + '\n\n';
                }
            }
            
        } else {
            // ========== MODE AUTO: Ambil dari versi terbaru ==========
            // Urutkan versi DESC (terbaru dulu)
            const sortedVersions = [...versions].sort((a, b) => b.versi - a.versi);
            
            for (const version of sortedVersions) {
                let tahapList = [];
                try { tahapList = JSON.parse(version.tahap_dipilih || '[]'); } catch (e) {}
                
                for (const tahapKode of tahapList) {
                    // Skip kalau sudah ada dari versi sebelumnya
                    if (mergedTahapSet.has(tahapKode)) continue;
                    
                    const tahapContent = extractTahapContent(version.konten, tahapKode);
                    
                    if (tahapContent) {
                        mergedTahapSet.add(tahapKode);
                        tahapSourceMap[tahapKode] = version.versi;
                        mergedContent += tahapContent + '\n\n';
                    }
                }
            }
        }
        
        if (mergedTahapSet.size === 0) {
            return { success: false, error: 'Tidak ada tahap yang bisa digabungkan' };
        }
        
        // ============================================================
        // 4. BUILD KONTEN FINAL
        // ============================================================
        let finalContent = `# 📚 MATERI: ${materi.judul || 'Materi'}\n\n`;
        finalContent += `## 📋 Informasi Materi\n\n`;
        finalContent += `- **Tahap Digabung:** ${Array.from(mergedTahapSet).sort().join(', ')}\n`;
        finalContent += `- **Sumber Versi:** ${versiList.join(', ')}\n`;
        finalContent += `- **Strategy:** ${strategy}\n`;
        finalContent += `- **Dibuat:** ${new Date().toLocaleString('id-ID')}\n\n`;
        finalContent += `---\n\n`;
        finalContent += mergedContent;
        
        // ============================================================
        // 5. SIMPAN SEBAGAI VERSI BARU
        // ============================================================
        const tahapArray = Array.from(mergedTahapSet).sort();
        
        // Update materi dulu
        await db.prepare(`
            UPDATE materi SET
                konten = ?,
                tahap_dipilih = ?,
                jumlah_tahap = ?,
                total_kata = ?,
                updated_at = ?
            WHERE id = ?
        `).bind(
            finalContent,
            JSON.stringify(tahapArray),
            tahapArray.length,
            finalContent.split(/\s+/).length,
            new Date().toISOString(),
            materiId
        ).run();
        
        // Buat versi baru
        const result = await createMateriVersion(db, materiId, {
            label: label || `Merge dari v${versiList.join(', v')}`,
            catatan: catatan || `Merge ${versiList.length} versi: ${versiList.join(', ')}`,
            createdBy: createdBy,
            mergeStrategy: strategy,
            mergedFrom: versiList,
            setActive: true
        });
        
        return {
            success: true,
            newVersi: result.versi,
            mergedTahap: tahapArray,
            tahapSource: tahapSourceMap,
            totalKata: finalContent.split(/\s+/).length
        };
        
    } catch (e) {
        console.error('mergeMateriVersions error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 8. EKSTRAK KONTEN TAHAP TERTENTU
// ============================================================
function extractTahapContent(konten, tahapKode) {
    if (!konten || !tahapKode) return null;
    
    // Regex untuk match section tahap
    // Format: "# ... Tahap T1 ..." sampai sebelum header tahap berikutnya
    const regex = new RegExp(
        `(#{1,3}\\s*[^\\n]*Tahap\\s*${tahapKode}[^\\n]*\\n[\\s\\S]*?)(?=#{1,3}\\s*[^\\n]*Tahap\\s*T\\d|$)`,
        'i'
    );
    
    const match = konten.match(regex);
    return match ? match[1].trim() : null;
}

// ============================================================
// 9. AUTO-MERGE SETELAH SEMUA TAHAP SELESAI
// ============================================================
async function autoMergeAfterComplete(db, materiId, userId = null) {
    try {
        // Ambil semua versi
        const versions = await getMateriVersions(db, materiId);
        
        if (versions.length < 2) {
            console.log(`⏭️ Auto-merge skip: hanya ${versions.length} versi`);
            return { success: false, error: 'Butuh minimal 2 versi' };
        }
        
        // Cek apakah semua tahap sudah selesai
        const materi = await db.prepare(`SELECT * FROM materi WHERE id = ?`)
            .bind(materiId).first();
        
        if (!materi) {
            return { success: false, error: 'Materi tidak ditemukan' };
        }
        
        let tahapDipilih = [];
        try { tahapDipilih = JSON.parse(materi.tahap_dipilih || '[]'); } catch (e) {}
        
        // Cek progress
        const progress = await db.prepare(`
            SELECT tahap_kode, status FROM materi_progress
            WHERE materi_id = ? AND status = 'done'
        `).bind(materiId).all();
        
        const doneTahap = (progress.results || []).map(p => p.tahap_kode);
        const allDone = tahapDipilih.every(tk => doneTahap.includes(tk));
        
        if (!allDone) {
            console.log(`⏭️ Auto-merge skip: belum semua tahap selesai`);
            return { success: false, error: 'Belum semua tahap selesai' };
        }
        
        // Ambil semua versi (urutkan ASC)
        const versiList = versions.map(v => v.versi).sort((a, b) => a - b);
        
        // Merge semua
        const result = await mergeMateriVersions(db, materiId, versiList, {
            label: `Auto-merge ${versiList.length} versi`,
            catatan: `Auto-merge setelah semua tahap selesai`,
            createdBy: userId,
            strategy: 'auto'
        });
        
        return result;
        
    } catch (e) {
        console.error('autoMergeAfterComplete error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 10. FORMAT DAFTAR VERSI (UNTUK TELEGRAM)
// ============================================================
function formatVersiList(versions, materiId) {
    if (!versions || versions.length === 0) {
        return `📭 *Belum ada versi tersimpan* untuk materi \`${materiId}\`.\n\n` +
               `💡 Versi otomatis dibuat saat generate tahap atau edit materi.`;
    }
    
    let msg = `📚 *DAFTAR VERSI: ${materiId}*\n\n`;
    msg += `📊 Total: *${versions.length} versi*\n\n`;
    
    for (const v of versions) {
        const activeIcon = v.is_active === 1 ? '🟢' : '⚪';
        const statusIcon = v.status === 'merged' ? '🔗' :
                          v.status === 'rollback' ? '⏪' : '📸';
        
        msg += `${activeIcon} *Versi ${v.versi}* ${statusIcon}\n`;
        
        if (v.label) {
            msg += `   🏷️ ${v.label}\n`;
        }
        
        msg += `   📊 ${(v.total_kata || 0).toLocaleString()} kata | ${v.jumlah_tahap || 0} tahap\n`;
        
        if (v.created_at) {
            const date = new Date(v.created_at).toLocaleString('id-ID', {
                day: '2-digit',
                month: 'short',
                year: 'numeric',
                hour: '2-digit',
                minute: '2-digit'
            });
            msg += `   📅 ${date}\n`;
        }
        
        if (v.merge_strategy === 'manual' || v.merge_strategy === 'auto') {
            try {
                const mergedFrom = JSON.parse(v.merged_from || '[]');
                if (mergedFrom.length > 0) {
                    msg += `   🔗 Merge dari: v${mergedFrom.join(', v')}\n`;
                }
            } catch (e) {}
        }
        
        if (v.catatan) {
            msg += `   📝 ${v.catatan.substring(0, 60)}${v.catatan.length > 60 ? '...' : ''}\n`;
        }
        
        msg += `\n`;
    }
    
    msg += `🟢 = Aktif | ⚪ = Lama\n`;
    msg += `📸 = Snapshot | 🔗 = Merge | ⏪ = Rollback`;
    
    return msg;
}

// ============================================================
// 🆕 PATCH 9: FUNGSI STATISTIK
// ============================================================

// ============================================================
// 1. STATISTIK DETAIL MATERI
// ============================================================
async function getStatistikMateri(db, materiId) {
    try {
        // ============================================================
        // 1. AMBIL DATA MATERI
        // ============================================================
        const materi = await db.prepare(`SELECT * FROM materi WHERE id = ?`)
            .bind(materiId).first();
        
        if (!materi) return { success: false, error: 'Materi tidak ditemukan' };
        
        // ============================================================
        // 2. STATISTIK PROGRESS
        // ============================================================
        const progressStats = await db.prepare(`
            SELECT 
                status,
                COUNT(*) as total,
                SUM(word_count) as total_kata,
                AVG(word_count) as avg_kata
            FROM materi_progress
            WHERE materi_id = ?
            GROUP BY status
        `).bind(materiId).all();
        
        const progress = {
            total: 0,
            done: 0,
            processing: 0,
            pending: 0,
            failed: 0,
            total_kata: 0,
            avg_kata: 0
        };
        
        for (const p of progressStats.results || []) {
            progress.total += p.total || 0;
            progress[p.status] = p.total || 0;
            progress.total_kata += p.total_kata || 0;
        }
        progress.avg_kata = progress.done > 0 ? Math.round(progress.total_kata / progress.done) : 0;
        progress.persen_done = progress.total > 0 ? Math.round((progress.done / progress.total) * 100) : 0;
        
        // ============================================================
        // 3. STATISTIK MEDIA
        // ============================================================
        const mediaStats = await db.prepare(`
            SELECT 
                media_type,
                COUNT(*) as total
            FROM materi_media
            WHERE materi_id = ?
            GROUP BY media_type
        `).bind(materiId).all();
        
        const media = {
            total: 0,
            image: 0,
            video: 0,
            audio: 0,
            global: 0,
            per_tahap: 0,
            anchor: 0,
            marker: 0,
            auto: 0
        };
        
        for (const m of mediaStats.results || []) {
            media.total += m.total || 0;
            media[m.media_type] = m.total || 0;
        }
        
        // Statistik media per placement
        const mediaPlacement = await db.prepare(`
            SELECT 
                placement,
                COUNT(*) as total,
                SUM(CASE WHEN tahap_kode IS NULL THEN 1 ELSE 0 END) as total_global,
                SUM(CASE WHEN tahap_kode IS NOT NULL THEN 1 ELSE 0 END) as total_per_tahap
            FROM materi_media
            WHERE materi_id = ?
            GROUP BY placement
        `).bind(materiId).all();
        
        for (const mp of mediaPlacement.results || []) {
            media[mp.placement] = mp.total || 0;
            media.global += mp.total_global || 0;
            media.per_tahap += mp.total_per_tahap || 0;
        }
        
        // ============================================================
        // 4. STATISTIK VERSI
        // ============================================================
        const versionStats = await db.prepare(`
            SELECT 
                COUNT(*) as total,
                SUM(CASE WHEN is_active = 1 THEN 1 ELSE 0 END) as active,
                MAX(versi) as latest,
                MIN(created_at) as first_created,
                MAX(created_at) as last_created
            FROM materi_versions
            WHERE materi_id = ?
        `).bind(materiId).first();
        
        const versions = {
            total: versionStats?.total || 0,
            active: versionStats?.active || 0,
            latest: versionStats?.latest || 0,
            first_created: versionStats?.first_created,
            last_created: versionStats?.last_created
        };
        
        // ============================================================
        // 5. STATISTIK PROVIDER
        // ============================================================
        const providerStats = await db.prepare(`
            SELECT 
                provider,
                COUNT(*) as total,
                SUM(word_count) as total_kata,
                AVG(word_count) as avg_kata
            FROM materi_progress
            WHERE materi_id = ? AND provider IS NOT NULL
            GROUP BY provider
            ORDER BY total DESC
        `).bind(materiId).all();
        
        const providers = (providerStats.results || []).map(p => ({
            provider: p.provider,
            total: p.total || 0,
            total_kata: p.total_kata || 0,
            avg_kata: Math.round(p.avg_kata || 0)
        }));
        
        // ============================================================
        // 6. STATISTIK RUMUS
        // ============================================================
        const rumusStats = await db.prepare(`
            SELECT COUNT(*) as total FROM materi_rumus WHERE materi_id = ?
        `).bind(materiId).first();
        
        const rumus = rumusStats?.total || 0;
        
        // ============================================================
        // 7. TAHAP DIPILIH
        // ============================================================
        let tahapDipilih = [];
        let tahapDilewati = [];
        try {
            tahapDipilih = JSON.parse(materi.tahap_dipilih || '[]');
            tahapDilewati = JSON.parse(materi.tahap_dilewati || '[]');
        } catch (e) {}
        
        return {
            success: true,
            materi: {
                id: materi.id,
                judul: materi.judul,
                status: materi.status,
                format: materi.format,
                total_kata: materi.total_kata,
                created_at: materi.created_at,
                updated_at: materi.updated_at
            },
            progress: progress,
            media: media,
            versions: versions,
            providers: providers,
            rumus: rumus,
            tahap: {
                dipilih: tahapDipilih,
                dilewati: tahapDilewati,
                total_dipilih: tahapDipilih.length,
                total_dilewati: tahapDilewati.length
            }
        };
        
    } catch (e) {
        console.error('getStatistikMateri error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 2. STATISTIK GLOBAL
// ============================================================
async function getStatistikGlobal(db) {
    try {
        // ============================================================
        // 1. STATISTIK MATERI
        // ============================================================
        const materiStats = await db.prepare(`
            SELECT 
                COUNT(*) as total,
                SUM(total_kata) as total_kata,
                AVG(total_kata) as avg_kata,
                SUM(jumlah_tahap) as total_tahap,
                AVG(jumlah_tahap) as avg_tahap,
                SUM(total_versi) as total_versi,
                MAX(created_at) as last_created
            FROM materi
        `).first();
        
        // Statistik per status
        const statusStats = await db.prepare(`
            SELECT status, COUNT(*) as total
            FROM materi
            GROUP BY status
        `).all();
        
        const statusCount = {};
        for (const s of statusStats.results || []) {
            statusCount[s.status] = s.total;
        }
        
        // ============================================================
        // 2. STATISTIK MEDIA
        // ============================================================
        const mediaStats = await db.prepare(`
            SELECT 
                media_type,
                COUNT(*) as total
            FROM materi_media
            GROUP BY media_type
        `).all();
        
        const mediaCount = { total: 0, image: 0, video: 0, audio: 0 };
        for (const m of mediaStats.results || []) {
            mediaCount.total += m.total || 0;
            mediaCount[m.media_type] = m.total || 0;
        }
        
        // ============================================================
        // 3. STATISTIK PROGRESS (SEMUA MATERI)
        // ============================================================
        const progressStats = await db.prepare(`
            SELECT 
                status,
                COUNT(*) as total,
                SUM(word_count) as total_kata
            FROM materi_progress
            GROUP BY status
        `).all();
        
        const progressCount = {
            total: 0, done: 0, processing: 0, pending: 0, failed: 0,
            total_kata: 0
        };
        for (const p of progressStats.results || []) {
            progressCount.total += p.total || 0;
            progressCount[p.status] = p.total || 0;
            progressCount.total_kata += p.total_kata || 0;
        }
        progressCount.persen_success = progressCount.total > 0 
            ? Math.round((progressCount.done / progressCount.total) * 100) 
            : 0;
        
        // ============================================================
        // 4. TOPIK POPULER (Top 10)
        // ============================================================
        const topikPopuler = await db.prepare(`
            SELECT 
                t.id,
                t.nama,
                COUNT(m.id) as total_materi,
                SUM(m.total_kata) as total_kata
            FROM topik t
            LEFT JOIN materi m ON m.topik_id = t.id
            GROUP BY t.id
            HAVING total_materi > 0
            ORDER BY total_materi DESC, total_kata DESC
            LIMIT 10
        `).all();
        
        // ============================================================
        // 5. DISTRIBUSI TAHAP (Tahap populer)
        // ============================================================
        const allMateri = await db.prepare(`SELECT tahap_dipilih, tahap_dilewati FROM materi`).all();
        
        const tahapCount = {};
        const tahapSkipCount = {};
        let totalMateriWithTahap = 0;
        
        for (const m of allMateri.results || []) {
            try {
                const dipilih = JSON.parse(m.tahap_dipilih || '[]');
                const dilewati = JSON.parse(m.tahap_dilewati || '[]');
                
                if (dipilih.length > 0) totalMateriWithTahap++;
                
                for (const tk of dipilih) tahapCount[tk] = (tahapCount[tk] || 0) + 1;
                for (const tk of dilewati) tahapSkipCount[tk] = (tahapSkipCount[tk] || 0) + 1;
            } catch (e) {}
        }
        
        const tahapPopuler = Object.entries(tahapCount)
            .map(([kode, total]) => ({
                kode,
                nama: TAHAP_PEMBELAJARAN[kode]?.nama || kode,
                icon: TAHAP_PEMBELAJARAN[kode]?.icon || '📚',
                total,
                persen: totalMateriWithTahap > 0 
                    ? Math.round((total / totalMateriWithTahap) * 100) 
                    : 0
            }))
            .sort((a, b) => b.total - a.total);
        
        const tahapSkip = Object.entries(tahapSkipCount)
            .map(([kode, total]) => ({
                kode,
                nama: TAHAP_PEMBELAJARAN[kode]?.nama || kode,
                icon: TAHAP_PEMBELAJARAN[kode]?.icon || '📚',
                total,
                persen: totalMateriWithTahap > 0 
                    ? Math.round((total / totalMateriWithTahap) * 100) 
                    : 0
            }))
            .sort((a, b) => b.total - a.total);
        
        // ============================================================
        // 6. DISTRIBUSI PROVIDER
        // ============================================================
        const providerStats = await db.prepare(`
            SELECT 
                provider,
                COUNT(*) as total,
                SUM(word_count) as total_kata,
                AVG(word_count) as avg_kata
            FROM materi_progress
            WHERE provider IS NOT NULL
            GROUP BY provider
            ORDER BY total DESC
        `).all();
        
        // ============================================================
        // 7. STATISTIK SOAL
        // ============================================================
        const soalStats = await db.prepare(`
            SELECT 
                COUNT(*) as total,
                SUM(CASE WHEN status = 'AKTIF' THEN 1 ELSE 0 END) as aktif,
                SUM(CASE WHEN status = 'ARSIP' THEN 1 ELSE 0 END) as arsip
            FROM soal
        `).first();
        
        // Distribusi proses kognitif
        const hotsStats = await db.prepare(`
            SELECT 
                tipe_hots,
                COUNT(*) as total
            FROM soal
            WHERE status = 'AKTIF' AND tipe_hots IS NOT NULL
            GROUP BY tipe_hots
        `).all();
        
        // Distribusi per kategori
        const kategoriStats = await db.prepare(`
            SELECT 
                k.nama as kategori,
                COUNT(s.id) as total
            FROM soal s
            LEFT JOIN kategori k ON s.kategori_id = k.id
            WHERE s.status = 'AKTIF'
            GROUP BY k.nama
            ORDER BY total DESC
            LIMIT 10
        `).all();
        
        // ============================================================
        // 8. STATISTIK MEDIA ANCHOR (PATCH 7.6)
        // ============================================================
        const anchorStats = await db.prepare(`
            SELECT 
                placement,
                COUNT(*) as total
            FROM materi_media
            GROUP BY placement
        `).all();
        
        const anchorCount = { auto: 0, anchor: 0, marker: 0 };
        for (const a of anchorStats.results || []) {
            anchorCount[a.placement] = a.total || 0;
        }
        
        return {
            success: true,
            materi: {
                total: materiStats?.total || 0,
                total_kata: materiStats?.total_kata || 0,
                avg_kata: Math.round(materiStats?.avg_kata || 0),
                total_tahap: materiStats?.total_tahap || 0,
                avg_tahap: Math.round(materiStats?.avg_tahap || 0),
                total_versi: materiStats?.total_versi || 0,
                last_created: materiStats?.last_created,
                by_status: statusCount
            },
            media: mediaCount,
            anchor: anchorCount,
            progress: progressCount,
            topik_populer: topikPopuler.results || [],
            tahap_populer: tahapPopuler,
            tahap_skip: tahapSkip,
            providers: (providerStats.results || []).map(p => ({
                provider: p.provider,
                total: p.total,
                total_kata: p.total_kata || 0,
                avg_kata: Math.round(p.avg_kata || 0)
            })),
            soal: {
                total: soalStats?.total || 0,
                aktif: soalStats?.aktif || 0,
                arsip: soalStats?.arsip || 0,
                by_hots: (hotsStats.results || []).map(h => ({
                    tipe: h.tipe_hots,
                    total: h.total
                })),
                by_kategori: (kategoriStats.results || []).map(k => ({
                    kategori: k.kategori || 'Tanpa Kategori',
                    total: k.total
                }))
            }
        };
        
    } catch (e) {
        console.error('getStatistikGlobal error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 3. STATISTIK AI USAGE
// ============================================================
async function getStatistikAI(db) {
    try {
        // ============================================================
        // 1. PROVIDER USAGE (dari materi_progress)
        // ============================================================
        const providerStats = await db.prepare(`
            SELECT 
                provider,
                COUNT(*) as total,
                SUM(word_count) as total_kata,
                AVG(word_count) as avg_kata,
                MIN(completed_at) as first_used,
                MAX(completed_at) as last_used
            FROM materi_progress
            WHERE provider IS NOT NULL AND status = 'done'
            GROUP BY provider
            ORDER BY total DESC
        `).all();
        
        const providers = (providerStats.results || []).map(p => ({
            provider: p.provider,
            total: p.total || 0,
            total_kata: p.total_kata || 0,
            avg_kata: Math.round(p.avg_kata || 0),
            first_used: p.first_used,
            last_used: p.last_used
        }));
        
        // ============================================================
        // 2. SUCCESS RATE
        // ============================================================
        const successStats = await db.prepare(`
            SELECT 
                COUNT(*) as total,
                SUM(CASE WHEN status = 'done' THEN 1 ELSE 0 END) as done,
                SUM(CASE WHEN status = 'failed' THEN 1 ELSE 0 END) as failed,
                SUM(CASE WHEN status = 'processing' THEN 1 ELSE 0 END) as processing,
                SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END) as pending
            FROM materi_progress
        `).first();
        
        const successRate = {
            total: successStats?.total || 0,
            done: successStats?.done || 0,
            failed: successStats?.failed || 0,
            processing: successStats?.processing || 0,
            pending: successStats?.pending || 0,
            rate: successStats?.total > 0 
                ? Math.round((successStats.done / successStats.total) * 100) 
                : 0
        };
        
        // ============================================================
        // 3. TOTAL KATA YANG DIGENERATE
        // ============================================================
        const totalKata = await db.prepare(`
            SELECT SUM(word_count) as total FROM materi_progress WHERE status = 'done'
        `).first();
        
        // ============================================================
        // 4. GENERATE PER HARI (7 hari terakhir)
        // ============================================================
        const dailyStats = await db.prepare(`
            SELECT 
                DATE(completed_at) as tanggal,
                COUNT(*) as total,
                SUM(word_count) as total_kata
            FROM materi_progress
            WHERE status = 'done' 
                AND completed_at >= datetime('now', '-7 days')
            GROUP BY DATE(completed_at)
            ORDER BY tanggal DESC
        `).all();
        
        // ============================================================
        // 5. PROVIDER TERBAIK (berdasarkan rata-rata kata)
        // ============================================================
        const bestProvider = providers.length > 0 
            ? providers.reduce((best, p) => p.avg_kata > best.avg_kata ? p : best, providers[0])
            : null;
        
        // ============================================================
        // 6. PROVIDER TERCEPAT (estimasi dari word count tertinggi)
        // ============================================================
        const mostUsedProvider = providers.length > 0 ? providers[0] : null;
        
        return {
            success: true,
            providers: providers,
            success_rate: successRate,
            total_kata_generated: totalKata?.total || 0,
            daily_stats: (dailyStats.results || []).map(d => ({
                tanggal: d.tanggal,
                total: d.total,
                total_kata: d.total_kata
            })),
            best_provider: bestProvider,
            most_used_provider: mostUsedProvider
        };
        
    } catch (e) {
        console.error('getStatistikAI error:', e);
        return { success: false, error: e.message };
    }
}

// ============================================================
// 4. FORMAT STATISTIK MATERI (TELEGRAM)
// ============================================================
function formatStatistikMateri(stats) {
    if (!stats.success) {
        return `❌ Error: ${stats.error}`;
    }
    
    const m = stats.materi;
    const p = stats.progress;
    const md = stats.media;
    const v = stats.versions;
    
    let msg = `📊 *STATISTIK MATERI*\n\n`;
    msg += `📖 *${m.judul}*\n`;
    msg += `🆔 \`${m.id}\`\n`;
    msg += `📌 Status: ${m.status}\n`;
    msg += `📅 Dibuat: ${m.created_at ? new Date(m.created_at).toLocaleDateString('id-ID') : '-'}\n\n`;
    
    // ============================================================
    // PROGRESS
    // ============================================================
    msg += `📈 *Progress:*\n`;
    msg += `├─ Total tahap: ${p.total}\n`;
    msg += `├─ ✅ Selesai: ${p.done}\n`;
    if (p.processing > 0) msg += `├─ 🔄 Diproses: ${p.processing}\n`;
    if (p.pending > 0) msg += `├─ ⏳ Pending: ${p.pending}\n`;
    if (p.failed > 0) msg += `├─ ❌ Gagal: ${p.failed}\n`;
    msg += `└─ 📊 Progress: ${p.persen_done}%\n\n`;
    
    // ============================================================
    // KATA
    // ============================================================
    msg += `📝 *Kata:*\n`;
    msg += `├─ Total: ${p.total_kata.toLocaleString()}\n`;
    msg += `└─ Rata-rata: ${p.avg_kata.toLocaleString()}/tahap\n\n`;
    
    // ============================================================
    // MEDIA
    // ============================================================
    if (md.total > 0) {
        msg += `🖼️ *Media (${md.total}):*\n`;
        if (md.image > 0) msg += `├─ 🖼️ Gambar: ${md.image}\n`;
        if (md.video > 0) msg += `├─ 🎬 Video: ${md.video}\n`;
        if (md.audio > 0) msg += `├─ 🎵 Audio: ${md.audio}\n`;
        
        // Placement
        const placementInfo = [];
        if (md.auto > 0) placementInfo.push(`Auto: ${md.auto}`);
        if (md.anchor > 0) placementInfo.push(`Anchor: ${md.anchor}`);
        if (md.marker > 0) placementInfo.push(`Marker: ${md.marker}`);
        if (placementInfo.length > 0) {
            msg += `├─ 📍 ${placementInfo.join(' | ')}\n`;
        }
        
        msg += `└─ 🌐 Global: ${md.global} | 📖 Per-tahap: ${md.per_tahap}\n\n`;
    } else {
        msg += `🖼️ *Media:* Belum ada\n\n`;
    }
    
    // ============================================================
    // VERSI
    // ============================================================
    if (v.total > 0) {
        msg += `📚 *Versi (${v.total}):*\n`;
        msg += `├─ 🟢 Aktif: v${v.latest}\n`;
        msg += `└─ 📅 Terakhir: ${v.last_created ? new Date(v.last_created).toLocaleDateString('id-ID') : '-'}\n\n`;
    } else {
        msg += `📚 *Versi:* Belum ada\n\n`;
    }
    
    // ============================================================
    // TAHAP
    // ============================================================
    if (stats.tahap.total_dipilih > 0) {
        msg += `📚 *Tahap Dipilih (${stats.tahap.total_dipilih}):*\n`;
        for (const tk of stats.tahap.dipilih) {
            const t = TAHAP_PEMBELAJARAN[tk];
            if (t) msg += `├─ ${t.icon} ${tk}: ${t.nama}\n`;
        }
        msg += `\n`;
    }
    
    if (stats.tahap.total_dilewati > 0) {
        msg += `⏭️ *Tahap Dilewati (${stats.tahap.total_dilewati}):*\n`;
        for (const tk of stats.tahap.dilewati) {
            const t = TAHAP_PEMBELAJARAN[tk];
            if (t) msg += `├─ ⬜ ${tk}: ${t.nama}\n`;
        }
        msg += `\n`;
    }
    
    // ============================================================
    // PROVIDER
    // ============================================================
    if (stats.providers.length > 0) {
        msg += `🤖 *Provider AI:*\n`;
        for (const p of stats.providers) {
            msg += `├─ ${p.provider}: ${p.total} tahap (${p.avg_kata} kata/tahap)\n`;
        }
        msg += `\n`;
    }
    
    // ============================================================
    // RUMUS
    // ============================================================
    if (stats.rumus > 0) {
        msg += `🧮 Rumus tersimpan: ${stats.rumus}\n\n`;
    }
    
    return msg;
}

// ============================================================
// 5. FORMAT STATISTIK GLOBAL (TELEGRAM)
// ============================================================
function formatStatistikGlobal(stats) {
    if (!stats.success) {
        return `❌ Error: ${stats.error}`;
    }
    
    const m = stats.materi;
    const p = stats.progress;
    const md = stats.media;
    const a = stats.anchor;
    
    let msg = `📊 *STATISTIK GLOBAL*\n\n`;
    
    // ============================================================
    // MATERI
    // ============================================================
    msg += `📚 *MATERI:*\n`;
    msg += `├─ Total: ${m.total}\n`;
    msg += `├─ Total kata: ${m.total_kata.toLocaleString()}\n`;
    msg += `├─ Rata-rata: ${m.avg_kata.toLocaleString()} kata\n`;
    msg += `├─ Total tahap: ${m.total_tahap}\n`;
    msg += `├─ Rata-rata: ${m.avg_tahap} tahap/materi\n`;
    msg += `└─ Total versi: ${m.total_versi}\n\n`;
    
    // Status
    const statusList = Object.entries(m.by_status || {});
    if (statusList.length > 0) {
        msg += `📌 *Status:*\n`;
        const statusIcon = { DRAFT: '📝', READY: '✅', PARTIAL: '⚠️', PUBLISHED: '🌐', ARCHIVED: '📦' };
        for (const [status, count] of statusList) {
            msg += `├─ ${statusIcon[status] || '📄'} ${status}: ${count}\n`;
        }
        msg += `\n`;
    }
    
    // ============================================================
    // MEDIA
    // ============================================================
    if (md.total > 0) {
        msg += `🖼️ *MEDIA (${md.total}):*\n`;
        if (md.image > 0) msg += `├─ 🖼️ Gambar: ${md.image}\n`;
        if (md.video > 0) msg += `├─ 🎬 Video: ${md.video}\n`;
        if (md.audio > 0) msg += `├─ 🎵 Audio: ${md.audio}\n`;
        
        // Anchor info
        const anchorInfo = [];
        if (a.auto > 0) anchorInfo.push(`Auto: ${a.auto}`);
        if (a.anchor > 0) anchorInfo.push(`Anchor: ${a.anchor}`);
        if (a.marker > 0) anchorInfo.push(`Marker: ${a.marker}`);
        if (anchorInfo.length > 0) {
            msg += `└─ 📍 ${anchorInfo.join(' | ')}\n`;
        }
        msg += `\n`;
    }
    
    // ============================================================
    // PROGRESS
    // ============================================================
    msg += `📈 *Progress Generate:*\n`;
    msg += `├─ Total: ${p.total}\n`;
    msg += `├─ ✅ Selesai: ${p.done} (${p.persen_success}%)\n`;
    if (p.processing > 0) msg += `├─ 🔄 Diproses: ${p.processing}\n`;
    if (p.pending > 0) msg += `├─ ⏳ Pending: ${p.pending}\n`;
    if (p.failed > 0) msg += `├─ ❌ Gagal: ${p.failed}\n`;
    msg += `└─ 📝 Total kata: ${p.total_kata.toLocaleString()}\n\n`;
    
    // ============================================================
    // TOPIK POPULER
    // ============================================================
    if (stats.topik_populer.length > 0) {
        msg += `🔥 *Topik Populer:*\n`;
        stats.topik_populer.slice(0, 5).forEach((t, i) => {
            msg += `${i+1}. ${t.nama} — ${t.total_materi} materi (${(t.total_kata || 0).toLocaleString()} kata)\n`;
        });
        msg += `\n`;
    }
    
    // ============================================================
    // TAHAP POPULER
    // ============================================================
    if (stats.tahap_populer.length > 0) {
        msg += `📚 *Tahap Populer:*\n`;
        stats.tahap_populer.slice(0, 5).forEach((t, i) => {
            msg += `${i+1}. ${t.icon} ${t.kode}: ${t.nama} — ${t.total}x (${t.persen}%)\n`;
        });
        msg += `\n`;
    }
    
    // ============================================================
    // TAHAP SKIP
    // ============================================================
    if (stats.tahap_skip.length > 0) {
        msg += `⏭️ *Tahap Paling Sering Dilewati:*\n`;
        stats.tahap_skip.slice(0, 3).forEach((t, i) => {
            msg += `${i+1}. ${t.icon} ${t.kode}: ${t.nama} — ${t.total}x (${t.persen}%)\n`;
        });
        msg += `\n`;
    }
    
    // ============================================================
    // PROVIDER
    // ============================================================
    if (stats.providers.length > 0) {
        msg += `🤖 *Provider AI:*\n`;
        stats.providers.slice(0, 5).forEach((p, i) => {
            msg += `${i+1}. ${p.provider}: ${p.total} tahap (${p.avg_kata} kata/tahap)\n`;
        });
        msg += `\n`;
    }
    
    // ============================================================
    // SOAL
    // ============================================================
    if (stats.soal.total > 0) {
        msg += `📝 *SOAL:*\n`;
        msg += `├─ Total: ${stats.soal.total}\n`;
        msg += `├─ ✅ Aktif: ${stats.soal.aktif}\n`;
        msg += `└─ 📦 Arsip: ${stats.soal.arsip}\n\n`;
        
        // HOTS
        if (stats.soal.by_hots.length > 0) {
            msg += `🎯 *Distribusi HOTS:*\n`;
            for (const h of stats.soal.by_hots) {
                const icon = h.tipe === 'HOTS' ? '🔴' : h.tipe === 'MOTS' ? '🟡' : '🟢';
                msg += `├─ ${icon} ${h.tipe}: ${h.total}\n`;
            }
            msg += `\n`;
        }
        
        // Kategori
        if (stats.soal.by_kategori.length > 0) {
            msg += `📂 *Top Kategori Soal:*\n`;
            stats.soal.by_kategori.slice(0, 5).forEach((k, i) => {
                msg += `${i+1}. ${k.kategori}: ${k.total} soal\n`;
            });
            msg += `\n`;
        }
    }
    
    return msg;
}

// ============================================================
// 6. FORMAT STATISTIK AI (TELEGRAM)
// ============================================================
function formatStatistikAI(stats) {
    if (!stats.success) {
        return `❌ Error: ${stats.error}`;
    }
    
    const sr = stats.success_rate;
    
    let msg = `🤖 *STATISTIK AI*\n\n`;
    
    // ============================================================
    // SUCCESS RATE
    // ============================================================
    msg += `📊 *Success Rate:*\n`;
    msg += `├─ Total request: ${sr.total}\n`;
    msg += `├─ ✅ Berhasil: ${sr.done}\n`;
    msg += `├─ ❌ Gagal: ${sr.failed}\n`;
    if (sr.processing > 0) msg += `├─ 🔄 Diproses: ${sr.processing}\n`;
    if (sr.pending > 0) msg += `├─ ⏳ Pending: ${sr.pending}\n`;
    msg += `└─ 📈 Success Rate: *${sr.rate}%*\n\n`;
    
    // ============================================================
    // TOTAL KATA
    // ============================================================
    msg += `📝 Total kata digenerate: ${stats.total_kata_generated.toLocaleString()}\n\n`;
    
    // ============================================================
    // PROVIDER USAGE
    // ============================================================
    if (stats.providers.length > 0) {
        msg += `🔧 *Provider Usage:*\n`;
        for (const p of stats.providers) {
            msg += `├─ *${p.provider}*\n`;
            msg += `│  ├─ Requests: ${p.total}\n`;
            msg += `│  ├─ Total kata: ${p.total_kata.toLocaleString()}\n`;
            msg += `│  └─ Rata-rata: ${p.avg_kata} kata\n`;
        }
        msg += `\n`;
    }
    
    // ============================================================
    // BEST PROVIDER
    // ============================================================
    if (stats.best_provider) {
        msg += `🏆 *Provider Terbaik (kata terbanyak):*\n`;
        msg += `├─ ${stats.best_provider.provider}\n`;
        msg += `└─ Rata-rata: ${stats.best_provider.avg_kata} kata/request\n\n`;
    }
    
    if (stats.most_used_provider) {
        msg += `⭐ *Provider Paling Sering Dipakai:*\n`;
        msg += `├─ ${stats.most_used_provider.provider}\n`;
        msg += `└─ Total: ${stats.most_used_provider.total} request\n\n`;
    }
    
    // ============================================================
    // DAILY STATS (7 hari terakhir)
    // ============================================================
    if (stats.daily_stats.length > 0) {
        msg += `📅 *7 Hari Terakhir:*\n`;
        for (const d of stats.daily_stats) {
            msg += `├─ ${d.tanggal}: ${d.total} request (${(d.total_kata || 0).toLocaleString()} kata)\n`;
        }
        msg += `\n`;
    }
    
    return msg;
}

// ============================================================
// 🆕 PATCH 4: HANDLER GENERATE MATERI MULTI-TAHAP
// Lokasi: Setelah handleGenerateMateri()
// ============================================================

async function handleGenerateMateriMultiTahap(env, userId, chatId, db, params) {
    console.log('🔧 [1] handleGenerateMateriMultiTahap DIPANGGIL');
    
    const {
        topicName,
        selectedTahap = [],
        skippedReasons = {},
        context = {},
        format = 'penjelasan'
    } = params;
    
    // ============================================================
    // VALIDASI
    // ============================================================
    if (!selectedTahap || selectedTahap.length === 0) {
        console.log('❌ [2] Tidak ada tahap');
        await smartResponseUniversal(chatId, '❌ Tidak ada tahap yang dipilih.');
        return;
    }
    
    // Urutkan tahap
    selectedTahap.sort((a, b) => 
        parseInt(a.replace('T', '')) - parseInt(b.replace('T', ''))
    );
    
    const skippedTahap = getSkippedTahap(selectedTahap);
    const totalTahap = selectedTahap.length;
    
    // ============================================================
    // INFO PROSES
    // ============================================================
    let infoMsg = `📚 *GENERATE MATERI MULTI-TAHAP*\n\n`;
    infoMsg += `📖 *Topik:* ${topicName}\n`;
    if (context.subtopik) infoMsg += `📋 *Sub-Topik:* ${context.subtopik}\n`;
    if (context.kisi) infoMsg += `📌 *Kisi-Kisi:* ${context.kisi}\n`;
    infoMsg += `📊 *Format:* ${format}\n`;
    infoMsg += `🎯 *Total Tahap:* ${totalTahap}\n\n`;
    
    infoMsg += `⏳ *Memproses ${totalTahap} tahap secara paralel...*\n`;
    infoMsg += `📌 Estimasi: ${Math.ceil(totalTahap / 3) * 2}-${Math.ceil(totalTahap / 3) * 4} menit\n`;
    infoMsg += `💡 Anda akan mendapat notifikasi setiap tahap selesai.`;
    
    await smartResponseUniversal(chatId, infoMsg);
    
    // ============================================================
    // BUAT RECORD MATERI (DRAFT)
    // ============================================================
    let materiId = null;
    try {
        materiId = await generateId(db, 'M', 'materi');
        console.log('🔧 [3] Materi ID:', materiId);
        
        const masterIds = await findMasterIdsFromContext(db, context);
        console.log('🔧 [4] Master IDs:', JSON.stringify(masterIds));
        
        await db.prepare(`
            INSERT INTO materi (
                id, kategori_id, bidang_studi_id, program_studi_id, mata_pelajaran_id, mata_kuliah_id,
                topik_id, sub_topik_id, kisi_kisi_id, kemampuan_id, sub_kemampuan_id,
                judul, format, tahap_dipilih, tahap_dilewati, jumlah_tahap,
                status, created_at,
                created_by, updated_by
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(
            materiId,
            masterIds.kategoriId, masterIds.bidangId, masterIds.programId,
            masterIds.topikId, masterIds.subtopikId, masterIds.kisiId,
            masterIds.kemampuanId, masterIds.subKemampuanId,
            `Materi ${topicName} - ${totalTahap} Tahap`,
            format,
            JSON.stringify(selectedTahap),
            JSON.stringify(skippedTahap),
            totalTahap,
            'DRAFT',
            new Date().toISOString(),
            userId || null,
            userId || null
            ).run();
        
        console.log('✅ [5] Materi berhasil di-INSERT');
    } catch (e) {
        console.error('❌ [5] GAGAL buat materi:', e.message);
        await smartResponseUniversal(chatId, `❌ Gagal membuat materi: ${e.message}`);
        return;
    }

    // ============================================================
    // INIT PROGRESS UNTUK SEMUA TAHAP
    // ============================================================
    for (const tahapKode of selectedTahap) {
        try {
            const progressId = await generateId(db, 'MP', 'materi_progress');
            await db.prepare(`
                INSERT INTO materi_progress (id, materi_id, tahap_kode, status, created_at)
                VALUES (?, ?, ?, 'pending', ?)
            `).bind(progressId, materiId, tahapKode, new Date().toISOString()).run();
        } catch (e) {
            console.error(`❌ Gagal buat progress ${tahapKode}:`, e);
        }
    }
    console.log('✅ [6] Progress initialized untuk', totalTahap, 'tahap');
    
    // ============================================================
    // GENERATE PARALEL PER TAHAP (BATCH 3)
    // ============================================================
    const results = {};
    const batchSize = 3;
    const totalBatch = Math.ceil(selectedTahap.length / batchSize);
    
    for (let i = 0; i < selectedTahap.length; i += batchSize) {
        const batch = selectedTahap.slice(i, i + batchSize);
        const batchNum = Math.floor(i / batchSize) + 1;
        
        await smartResponseUniversal(chatId, 
            `⏳ *Batch ${batchNum}/${totalBatch}*\n` +
            `Memproses: ${batch.join(', ')}...`
        );
        
        for (const tk of batch) {
            try {
                await db.prepare(`
                    UPDATE materi_progress 
                    SET status = 'processing', started_at = ?
                    WHERE materi_id = ? AND tahap_kode = ?
                `).bind(new Date().toISOString(), materiId, tk).run();
            } catch (e) {}
        }
        
        const batchPromises = batch.map(async (tahapKode) => {
            try {
                const prompt = buildTahapMateriPrompt(tahapKode, topicName, context, format);
                
                if (!prompt) {
                    return { tahapKode, success: false, error: 'Prompt tidak valid' };
                }
                
                const result = await callAIHybrid(prompt, 'generate_materi', env);
                
                if (result.success && result.response) {
                    return {
                        tahapKode,
                        success: true,
                        content: result.response,
                        provider: result.provider,
                        method: result.method,
                        wordCount: result.response.split(/\s+/).length
                    };
                }
                
                return { tahapKode, success: false, error: result.error || 'Gagal generate' };
            } catch (e) {
                return { tahapKode, success: false, error: e.message };
            }
        });
        
        const batchResults = await Promise.all(batchPromises);
        
        for (const res of batchResults) {
            results[res.tahapKode] = res;
            
            try {
                if (res.success) {
                    await db.prepare(`
                        UPDATE materi_progress 
                        SET status = 'done', konten = ?, provider = ?, 
                            word_count = ?, completed_at = ?
                        WHERE materi_id = ? AND tahap_kode = ?
                    `).bind(
                        res.content, res.provider, res.wordCount, 
                        new Date().toISOString(), materiId, res.tahapKode
                    ).run();
                } else {
                    await db.prepare(`
                        UPDATE materi_progress 
                        SET status = 'failed', error_message = ?, completed_at = ?
                        WHERE materi_id = ? AND tahap_kode = ?
                    `).bind(res.error, new Date().toISOString(), materiId, res.tahapKode).run();
                }
            } catch (e) {
                console.error(`❌ Update progress ${res.tahapKode}:`, e);
            }
            
            const tahap = TAHAP_PEMBELAJARAN[res.tahapKode];
            if (res.success) {
                await smartResponseUniversal(chatId, 
                    `✅ *${tahap.icon} ${res.tahapKode} — ${tahap.nama}* selesai!\n` +
                    `📊 ${res.wordCount.toLocaleString()} kata | 🤖 ${res.provider}`
                );
            } else {
                await smartResponseUniversal(chatId, 
                    `❌ *${tahap.icon} ${res.tahapKode} gagal:* ${res.error}`
                );
            }
        }
        
        if (i + batchSize < selectedTahap.length) {
            await new Promise(resolve => setTimeout(resolve, 1500));
        }
    }
   
    // ============================================================
    // GENERATE GLOSARIUM & PETA KONSEP (PARALEL)
    // ============================================================
    const successTahap = selectedTahap.filter(tk => results[tk]?.success);
    
    if (successTahap.length > 0) {
        await smartResponseUniversal(chatId, `📖 *Generating glosarium & peta konsep...*`);
        
        const allContent = successTahap
            .map(tk => results[tk].content)
            .join('\n\n---\n\n');
        
        const [glosariumRes, petaRes] = await Promise.all([
            callAIHybrid(
                buildGlosariumPrompt(topicName, allContent, successTahap),
                'generate_materi'
            ),
            callAIHybrid(
                buildPetaKonsepPrompt(topicName, successTahap, context),
                'generate_materi'
            )
        ]);
        
        results._glosarium = glosariumRes.success ? glosariumRes.response : null;
        results._petaKonsep = petaRes.success ? petaRes.response : null;
    }
    
    // ============================================================
    // GABUNGKAN MATERI FINAL
    // ============================================================
    let combinedContent = `# 📚 MATERI: ${topicName}\n\n`;
    
    combinedContent += `## 📋 Informasi Materi\n\n`;
    if (context.kategori) combinedContent += `- **Kategori:** ${context.kategori}\n`;
    if (context.bidang) combinedContent += `- **Bidang Studi:** ${context.bidang}\n`;
    if (context.program) combinedContent += `- **Program Studi:** ${context.program}\n`;
    if (context.topik) combinedContent += `- **Topik:** ${context.topik}\n`;
    if (context.subtopik) combinedContent += `- **Sub-Topik:** ${context.subtopik}\n`;
    if (context.kisi) combinedContent += `- **Kisi-Kisi:** ${context.kisi}\n`;
    if (context.kemampuan) combinedContent += `- **Kemampuan:** ${context.kemampuan}\n`;
    if (context.subKemampuan) combinedContent += `- **Sub-Kemampuan:** ${context.subKemampuan}\n`;
    combinedContent += `- **Format:** ${format}\n`;
    combinedContent += `- **Tahap Dipilih:** ${selectedTahap.join(', ')}\n`;
    if (skippedTahap.length > 0) {
        combinedContent += `- **Tahap Dilewati:** ${skippedTahap.join(', ')}\n`;
    }
    combinedContent += `\n---\n\n`;
    
    combinedContent += `## 📑 Daftar Isi\n\n`;
    for (const tk of selectedTahap) {
        const t = TAHAP_PEMBELAJARAN[tk];
        const status = results[tk]?.success ? '✅' : '❌';
        combinedContent += `- ${status} ${t.icon} Tahap ${tk}: ${t.nama}\n`;
    }
    if (results._glosarium) combinedContent += `- 📖 Glosarium\n`;
    if (results._petaKonsep) combinedContent += `- 🗺️ Peta Konsep\n`;
    combinedContent += `\n---\n\n`;
    
    let totalWords = 0;
    let successCount = 0;
    const failedTahap = [];
    const providers = [];
    
    for (const tk of selectedTahap) {
        const t = TAHAP_PEMBELAJARAN[tk];
        const res = results[tk];
        
        combinedContent += `# ${t.icon} Tahap ${tk}: ${t.nama}\n\n`;
        combinedContent += `> ${t.deskripsi}\n\n`;
        
        if (res?.success) {
            let content = res.content;
            content = content.replace(/^##?\s*[📚🔍⚙️💡🔗📊📋🔥🏆]?\s*Tahap\s*T\d.*$/m, '').trim();
            
            combinedContent += content + `\n\n---\n\n`;
            totalWords += res.wordCount;
            successCount++;
            if (res.provider) providers.push(res.provider);
        } else {
            combinedContent += `⚠️ *Materi tahap ini belum tersedia.*\n`;
            combinedContent += `_Error: ${res?.error || 'Tidak diketahui'}_\n\n---\n\n`;
            failedTahap.push(tk);
        }
    }
    
    if (results._glosarium) {
        combinedContent += `# 📖 Glosarium\n\n`;
        combinedContent += results._glosarium + `\n\n---\n\n`;
    }
    
    if (results._petaKonsep) {
        combinedContent += `# 🗺️ Peta Konsep\n\n`;
        combinedContent += results._petaKonsep + `\n\n---\n\n`;
    }
    
    // ============================================================
// DEBUG: Cek sebelum UPDATE
// ============================================================
console.log('🔍 [DEBUG UPDATE] materiId:', materiId);
console.log('🔍 [DEBUG UPDATE] combinedContent length:', combinedContent.length);
console.log('🔍 [DEBUG UPDATE] totalWords:', totalWords);
console.log('🔍 [DEBUG UPDATE] failedTahap:', failedTahap.length);
console.log('🔍 [DEBUG UPDATE] providers:', [...new Set(providers)].join(' + '));

// ============================================================
// SIMPAN KE DATABASE
// ============================================================
try {
    const updateResult = await db.prepare(`
        UPDATE materi SET
            konten = ?,
            total_kata = ?,
            status = ?,
            provider = ?,
            updated_at = ?
        WHERE id = ?
    `).bind(
        combinedContent,
        totalWords,
        failedTahap.length === 0 ? 'READY' : 'PARTIAL',
        [...new Set(providers)].join(' + '),
        new Date().toISOString(),
        materiId
    ).run();
    
    console.log('✅ [DEBUG UPDATE] Update result:', JSON.stringify(updateResult));

            
        // 🆕 TRACKING COUNTER: Auto-increment total_materi
        if (userId) {
            try {
                await incrementUserStats(db, userId, 'total_materi');
            } catch (e) {
                console.warn('Gagal increment total_materi:', e.message);
            }
        }
    
    // Verifikasi setelah update
    const verify = await db.prepare(`SELECT id, total_kata, LENGTH(konten) as konten_len, status FROM materi WHERE id = ?`).bind(materiId).first();
    console.log('✅ [DEBUG UPDATE] Verify:', JSON.stringify(verify));
    
} catch (e) {
    console.error('❌ [7] Gagal simpan materi:', e);
    console.error('❌ [7] Stack:', e.stack);
}
    
    // ============================================================
    // KIRIM MATERI FINAL (RENDER MATH OTOMATIS)
    // ============================================================
    await smartResponseUniversal(chatId, `\n✅ *Semua tahap selesai! Menampilkan materi final...*\n`);
    
    const maxLen = 4000;
    const sections = combinedContent.split(/\n---\n/);
    
    let currentBuffer = '';
    for (const section of sections) {
        if ((currentBuffer + '\n---\n' + section).length > maxLen) {
            if (currentBuffer) {
                await renderMath(chatId, currentBuffer);
            }
            currentBuffer = section;
        } else {
            currentBuffer += (currentBuffer ? '\n---\n' : '') + section;
        }
    }
    if (currentBuffer) {
        await renderMath(chatId, currentBuffer);
    }
    
    // ============================================================
    // LAPORAN AKHIR + KEYBOARD AKSI
    // ============================================================
    let summary = `\n═══════════════════════════════════════\n`;
    summary += `✅ *GENERATE MATERI SELESAI*\n`;
    summary += `═══════════════════════════════════════\n\n`;
    summary += `📊 *Statistik:*\n`;
    summary += `   ✅ Berhasil: ${successCount}/${totalTahap} tahap\n`;
    summary += `   📝 Total kata: ${totalWords.toLocaleString()}\n`;
    summary += `   🤖 AI: ${[...new Set(providers)].join(' + ') || '-'}\n`;
    summary += `   🆔 Materi ID: \`${materiId}\`\n`;
    summary += `   📌 Status: ${failedTahap.length === 0 ? '✅ READY' : '⚠️ PARTIAL'}\n`;
    
    if (failedTahap.length > 0) {
        summary += `\n⚠️ *Tahap gagal:*\n`;
        failedTahap.forEach(t => {
            summary += `   ❌ ${t} — ${TAHAP_PEMBELAJARAN[t].nama}\n`;
        });
        summary += `\n💡 Coba /materi_regen ${materiId} ${failedTahap.join(',')} untuk regenerate.\n`;
    }
    
    const keyboard = [
        [{ text: "💾 Publish Materi", callback_data: `materi_publish_${materiId}` }],
        [{ text: "📊 Lihat Progres", callback_data: `materi_progress_${materiId}` }],
        [{ text: "👁️ Lihat Isi Materi", callback_data: `materi_content_${materiId}` }],
        [{ text: "📋 Lihat Daftar Materi", callback_data: "materi_list" }],
        [{ text: "🔙 Kembali ke Menu AI", callback_data: "ai_menu" }]
    ];
    
    await sendInlineKeyboard(chatId, summary, keyboard);
    
    try {
        const session = await getSession(env, userId);
        session.selectedTahap = null;
        session.skippedReasons = null;
        session.materiContext = null;
        await saveSession(env, userId, session);
    } catch (e) {}
    
    console.log('✅ [8] handleGenerateMateriMultiTahap selesai');
}

// ============================================================
// 🆕 GET MATERI CONTEXT
// Ambil konteks hierarki lengkap berdasarkan level filter
// ============================================================

async function getMateriContext(db, filterType, filterId) {
    let context = {
        kategori: null, bidang: null, program: null,
        topik: null, subtopik: null, kisi: null,
        kemampuan: null, subKemampuan: null
    };
    
    try {
        switch (filterType) {
            case 'topik': {
                const t = await db.prepare(`
                    SELECT t.nama as topik, p.nama as program, b.nama as bidang, k.nama as kategori
                    FROM topik t
                    LEFT JOIN program_studi p ON t.program_studi_id = p.id
                    LEFT JOIN bidang_studi b ON p.bidang_studi_id = b.id
                    LEFT JOIN kategori k ON b.kategori_id = k.id
                    WHERE t.id = ?
                `).bind(filterId).first();
                
                if (t) {
                    context.topik = t.topik;
                    context.program = t.program;
                    context.bidang = t.bidang;
                    context.kategori = t.kategori;
                }
                break;
            }
            case 'subtopik': {
                const st = await db.prepare(`
                    SELECT st.nama as subtopik, t.nama as topik, p.nama as program, 
                           b.nama as bidang, k.nama as kategori
                    FROM sub_topik st
                    LEFT JOIN topik t ON st.topik_id = t.id
                    LEFT JOIN program_studi p ON t.program_studi_id = p.id
                    LEFT JOIN bidang_studi b ON p.bidang_studi_id = b.id
                    LEFT JOIN kategori k ON b.kategori_id = k.id
                    WHERE st.id = ?
                `).bind(filterId).first();
                
                if (st) {
                    context.subtopik = st.subtopik;
                    context.topik = st.topik;
                    context.program = st.program;
                    context.bidang = st.bidang;
                    context.kategori = st.kategori;
                }
                break;
            }
            case 'kisi': {
                const kk = await db.prepare(`
                    SELECT kk.judul as kisi, st.nama as subtopik, t.nama as topik,
                           p.nama as program, b.nama as bidang, k.nama as kategori
                    FROM kisi_kisi kk
                    LEFT JOIN sub_topik st ON kk.sub_topik_id = st.id
                    LEFT JOIN topik t ON st.topik_id = t.id
                    LEFT JOIN program_studi p ON t.program_studi_id = p.id
                    LEFT JOIN bidang_studi b ON p.bidang_studi_id = b.id
                    LEFT JOIN kategori k ON b.kategori_id = k.id
                    WHERE kk.id = ?
                `).bind(filterId).first();
                
                if (kk) {
                    context.kisi = kk.kisi;
                    context.subtopik = kk.subtopik;
                    context.topik = kk.topik;
                    context.program = kk.program;
                    context.bidang = kk.bidang;
                    context.kategori = kk.kategori;
                }
                break;
            }
            case 'kemampuan': {
                const km = await db.prepare(`
                    SELECT km.nama as kemampuan, kk.judul as kisi, st.nama as subtopik,
                           t.nama as topik, p.nama as program, b.nama as bidang, k.nama as kategori
                    FROM kemampuan_diuji km
                    LEFT JOIN kisi_kisi kk ON km.kisi_kisi_id = kk.id
                    LEFT JOIN sub_topik st ON kk.sub_topik_id = st.id
                    LEFT JOIN topik t ON st.topik_id = t.id
                    LEFT JOIN program_studi p ON t.program_studi_id = p.id
                    LEFT JOIN bidang_studi b ON p.bidang_studi_id = b.id
                    LEFT JOIN kategori k ON b.kategori_id = k.id
                    WHERE km.id = ?
                `).bind(filterId).first();
                
                if (km) {
                    context.kemampuan = km.kemampuan;
                    context.kisi = km.kisi;
                    context.subtopik = km.subtopik;
                    context.topik = km.topik;
                    context.program = km.program;
                    context.bidang = km.bidang;
                    context.kategori = km.kategori;
                }
                break;
            }
            case 'subkemampuan': {
                const sk = await db.prepare(`
                    SELECT sk.nama as subKemampuan, km.nama as kemampuan,
                           kk.judul as kisi, st.nama as subtopik, t.nama as topik,
                           p.nama as program, b.nama as bidang, k.nama as kategori
                    FROM sub_kemampuan sk
                    LEFT JOIN kemampuan_diuji km ON sk.kemampuan_id = km.id
                    LEFT JOIN kisi_kisi kk ON km.kisi_kisi_id = kk.id
                    LEFT JOIN sub_topik st ON kk.sub_topik_id = st.id
                    LEFT JOIN topik t ON st.topik_id = t.id
                    LEFT JOIN program_studi p ON t.program_studi_id = p.id
                    LEFT JOIN bidang_studi b ON p.bidang_studi_id = b.id
                    LEFT JOIN kategori k ON b.kategori_id = k.id
                    WHERE sk.id = ?
                `).bind(filterId).first();
                
                if (sk) {
                    context.subKemampuan = sk.subKemampuan;
                    context.kemampuan = sk.kemampuan;
                    context.kisi = sk.kisi;
                    context.subtopik = sk.subtopik;
                    context.topik = sk.topik;
                    context.program = sk.program;
                    context.bidang = sk.bidang;
                    context.kategori = sk.kategori;
                }
                break;
            }
        }
    } catch (e) {
        console.error('getMateriContext error:', e);
    }
    
    return context;
}

// ============================================================
// 🆕 CARI MASTER IDs DARI KONTEKS
// ============================================================

async function findMasterIdsFromContext(db, context) {
    const result = {
        kategoriId: null, bidangId: null, programId: null, mataPelajaranId: null, mataKuliahId: null,
        topikId: null, subtopikId: null, kisiId: null,
        kemampuanId: null, subKemampuanId: null
    };
    
    try {
        // Resolusi Mata Pelajaran dari ID atau nama + konteks Kelas/Bidang.
        if (context.mataPelajaranId || context.mata_pelajaran_id) {
            const mp = await db.prepare(`SELECT id, bidang_studi_id, kelas_id FROM mata_pelajaran WHERE id = ? LIMIT 1`)
                .bind(context.mataPelajaranId || context.mata_pelajaran_id).first();
            if (mp) {
                result.mataPelajaranId = mp.id;
                result.bidangId = mp.bidang_studi_id || result.bidangId;
                const p = await db.prepare(`SELECT kategori_id FROM bidang_studi WHERE id = ? LIMIT 1`).bind(result.bidangId).first();
                if (p?.kategori_id) result.kategoriId = p.kategori_id;
            }
        } else if (context.mataPelajaran || context.mata_pelajaran) {
            const mp = await db.prepare(`
                SELECT id, bidang_studi_id, kelas_id FROM mata_pelajaran
                WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?))
                LIMIT 1
            `).bind(context.mataPelajaran || context.mata_pelajaran).first();
            if (mp) {
                result.mataPelajaranId = mp.id;
                result.bidangId = mp.bidang_studi_id || result.bidangId;
            }
        }

        if (context.topik) {
            const t = await db.prepare(`
                SELECT id, program_studi_id, mata_pelajaran_id, mata_kuliah_id FROM topik 
                WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?))
                  AND (mata_pelajaran_id = ? OR mata_kuliah_id = ? OR (mata_pelajaran_id IS NULL AND mata_kuliah_id IS NULL))
                LIMIT 1
            `).bind(context.topik, result.mataPelajaranId || null, result.mataKuliahId || null).first();
            
            if (t) {
                result.topikId = t.id;
                
                if (t.program_studi_id) {
                    result.programId = t.program_studi_id;
                    const p = await db.prepare(`SELECT bidang_studi_id FROM program_studi WHERE id = ?`)
                        .bind(result.programId).first();
                    
                    if (p?.bidang_studi_id) {
                        result.bidangId = p.bidang_studi_id;
                        const b = await db.prepare(`SELECT kategori_id FROM bidang_studi WHERE id = ?`)
                            .bind(result.bidangId).first();
                        if (b?.kategori_id) result.kategoriId = b.kategori_id;
                    }
                }
            }
        }
        
        if (context.subtopik && result.topikId) {
            const st = await db.prepare(`
                SELECT id FROM sub_topik 
                WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND topik_id = ?
                LIMIT 1
            `).bind(context.subtopik, result.topikId).first();
            if (st) result.subtopikId = st.id;
        }
        
        if (context.kisi && result.subtopikId) {
            const k = await db.prepare(`
                SELECT id FROM kisi_kisi 
                WHERE LOWER(TRIM(judul)) = LOWER(TRIM(?)) AND sub_topik_id = ?
                LIMIT 1
            `).bind(context.kisi, result.subtopikId).first();
            if (k) result.kisiId = k.id;
        }
        
        if (context.kemampuan && result.kisiId) {
            const km = await db.prepare(`
                SELECT id FROM kemampuan_diuji 
                WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND kisi_kisi_id = ?
                LIMIT 1
            `).bind(context.kemampuan, result.kisiId).first();
            if (km) result.kemampuanId = km.id;
        }
        
        if (context.subKemampuan && result.kemampuanId) {
            const sk = await db.prepare(`
                SELECT id FROM sub_kemampuan 
                WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND kemampuan_id = ?
                LIMIT 1
            `).bind(context.subKemampuan, result.kemampuanId).first();
            if (sk) result.subKemampuanId = sk.id;
        }
    } catch (e) {
        console.error('findMasterIdsFromContext error:', e);
    }
    
    return result;
}

