// ============================================================
// 2. BREADCRUMB BUILDER
// ============================================================
function buildBreadcrumb(context) {
    if (!context) return '🏠 Menu Utama';
    
    const parts = [];
    if (context.kategoriNama) parts.push(`📂 ${context.kategoriNama}`);
    if (context.bidangNama) parts.push(`📚 ${context.bidangNama}`);
    if (context.programNama) parts.push(`🎓 ${context.programNama}`);
    if (context.mataKuliahNama) {
        const mkLabel = context.semester ? `${context.mataKuliahNama} (Semester ${context.semester})` : context.mataKuliahNama;
        parts.push(`📘 ${mkLabel}`);
    }
    if (context.mataPelajaranNama) parts.push(`📖 ${context.mataPelajaranNama}`);
    
    if (context.jenjang) {
        const jenjangLabel = context.kelasNama
            ? `${context.jenjang} ${context.kelasNama}`
            : (context.kelas ? `${context.jenjang} Kelas ${context.kelas}` : context.jenjang);
        parts.push(`🏫 ${jenjangLabel}`);
    }
    
    if (context.topikNama) parts.push(`📖 ${context.topikNama}`);
    if (context.subtopikNama) parts.push(`📋 ${context.subtopikNama}`);
    if (context.kisiJudul) parts.push(`📌 ${context.kisiJudul}`);
    if (context.kemampuanNama) parts.push(`🎯 ${context.kemampuanNama}`);
    if (context.subKemampuanNama) parts.push(`📎 ${context.subKemampuanNama}`);
    
    return parts.length > 0 ? parts.join('\n') : '🏠 Menu Utama';
}

