// ============================================================
// 4. SAVE CONTEXT STEP
// ============================================================
async function saveContextStep(env, userId, step, data) {
    const session = await getSession(env, userId);
    session.context = session.context || getEmptyContext();
    Object.assign(session.context, data);
    session.step = step;
    await saveSession(env, userId, session);
    return session.context;
}

// ============================================================
// 5. RESET CONTEXT
// ============================================================
async function resetContext(env, userId, mode = null) {
    const session = await getSession(env, userId);
    session.context = getEmptyContext();
    session.step = 'kategori';
    session.mode = mode;
    session.drillCurrentPage = 1;   // ← Pagination
    await saveSession(env, userId, session);
    return session.context;
}

// ============================================================
// 6. DETEKSI BUTUH JENJANG
