// ============================================================
// 9. BUILD PAGINATION KEYBOARD
// ============================================================
function buildPaginationKeyboard(currentPage, totalPages, callbackPrefix, navCallbackPrefix = null) {
    const keyboard = [];
    
    if (totalPages <= 1) return keyboard;
    
    const navRow = [];
    
    if (currentPage > 1) {
        navRow.push({ 
            text: "⬅️ Prev", 
            callback_data: `${callbackPrefix}_page_${currentPage - 1}` 
        });
    }
    
    navRow.push({text:'📄 Halaman',callback_data:`${callbackPrefix}_jump`});
    
    if (currentPage < totalPages) {
        navRow.push({ 
            text: "Next ➡️", 
            callback_data: `${callbackPrefix}_page_${currentPage + 1}` 
        });
    }
    
    if (navRow.length > 0) {
        keyboard.push(navRow);
    }
    
    return keyboard;
}

// ============================================================
// 10. PARSE CALLBACK PAGE
// ============================================================
function parsePageCallback(data, prefix) {
    const pattern = new RegExp(`^${prefix}_page_(\\d+)$`);
    const match = data.match(pattern);
    if (match) {
        return parseInt(match[1]);
    }
    return null;
}

// ============================================================
// 11. PAGINATION INFO BUILDER
// ============================================================
function buildPaginationInfo(currentPage, totalPages, totalItems) {
    if (totalPages <= 1) {
        return `📊 Total: ${totalItems} item`;
    }
    return `📊 Hal ${currentPage}/${totalPages} • Total: ${totalItems} item`;
}

// ============================================================
// 12. SHORTEN TEXT (untuk label tombol)
// ============================================================
function shortenText(text, maxLength = 60) {
    if (!text) return '';
    if (text.length <= maxLength) return text;
    return text.substring(0, maxLength - 3) + '...';
}

// ============================================================
// 🆕 FASE 0: DIVIDER (Garis Pemisah 20 Karakter)
// ============================================================
const DIVIDER = '━━━━━━━━━━━━━━━━━━━━';

function divider(length = 20) {
    return '━'.repeat(length);
}

console.log('✅ FASE 0: DIVIDER loaded (20 karakter)');

// ============================================================
// 🆕 FASE 0: HITUNG PANJANG VISUAL TEKS
// Emoji dihitung 2 karakter, teks biasa 1
// ============================================================
function textVisualLength(text) {
    if (!text) return 0;
    let len = 0;
    for (const char of text) {
        const code = char.codePointAt(0);
        if (code > 0x1F000) {
            len += 2;
        } else {
            len += 1;
        }
    }
    return len;
}

console.log('✅ FASE 0: textVisualLength loaded');

// ============================================================
// 🆕 FASE 0: WRAP TEXT
// Wrap teks panjang dengan indent untuk baris lanjutan
// ============================================================
function wrapText(text, maxLength = 35, indent = '') {
    if (!text) return '';
    if (text.length <= maxLength) return text;
    
    const words = text.split(' ');
    const lines = [];
    let currentLine = '';
    
    for (const word of words) {
        const testLine = currentLine ? `${currentLine} ${word}` : word;
        if (testLine.length <= maxLength) {
            currentLine = testLine;
        } else {
            if (currentLine) lines.push(currentLine);
            currentLine = word;
        }
    }
    if (currentLine) lines.push(currentLine);
    
    return lines.join(`\n${indent}`);
}

console.log('✅ FASE 0: wrapText loaded');

// ============================================================
// 🆕 FASE 0: BUILD LIST ITEM
// Format:
//   3. PPPK
//           🆔 ID: B003
//           📝 Pegawai Pemerintah dengan Perjanjian Kerja
//              📂 Kategori : PEKERJAAN
// ============================================================
// ============================================================
// BUILD LIST ITEM (Format : dengan spasi)
// ============================================================
function buildListItem(item, index, options = {}) {
    const {
        showDeskripsi = true,
        wrapDeskripsi = true,
        wrapLength = 35,
        extraLines = []
    } = options;
    
    const nomor = index + 1;
    const nomorStr = `${nomor}. `;
    const digitCount = String(nomor).length;
    const indent = ' '.repeat(4 + (digitCount - 1) * 2);
    const indentWrap = indent + '   ';
    
    const nama = item.nama || item.judul || '-';
    const id = item.id || '-';
    let deskripsi = item.deskripsi || 'Tidak ada deskripsi';
    
    if (wrapDeskripsi && deskripsi.length > wrapLength) {
        deskripsi = wrapText(deskripsi, wrapLength, indentWrap);
    }
    
    let text = `${nomorStr}${nama}\n`;
    text += `${indent}🆔 ID : ${id}\n`;
    text += `${indent}📝 Deskripsi : ${showDeskripsi ? deskripsi : '-'}`;
    
    if (extraLines && extraLines.length > 0) {
        for (const line of extraLines) {
            if (line.value) {
                const icon = line.icon || '📌';
                const label = line.label || '';
                text += `\n${indentWrap}${icon} ${label} : ${line.value}`;
            }
        }
    }
    
    return text;
}

console.log('✅ FASE 0: buildListItem loaded');

// ============================================================
// BUILD LIST VIEW (Support startNumber)
// ============================================================
function buildListView(items, options = {}) {
    if (!items || items.length === 0) {
        return '_(Tidak ada data)_';
    }
    
    const startNumber = options.startNumber || 0;
    
    const parts = [];
    items.forEach((item, i) => {
        const itemOptions = {
            ...options,
            extraLines: item.extraLines || options.extraLines || []
        };
        parts.push(buildListItem(item, i + startNumber, itemOptions));
    });
    
    return parts.join('\n\n');
}

// ============================================================
// 🆕 FASE 0: AUTO LAYOUT TOMBOL
// Max 25 karakter → 2 kolom, > 25 → 1 kolom
// ============================================================
function buildAutoLayout(buttons, maxCharPerColumn = 25) {
    const rows = [];
    let pendingShort = null;
    
    for (const btn of buttons) {
        const visualLen = textVisualLength(btn.text);
        const isShort = visualLen <= maxCharPerColumn;
        
        if (isShort) {
            if (pendingShort) {
                rows.push([pendingShort, btn]);
                pendingShort = null;
            } else {
                pendingShort = btn;
            }
        } else {
            if (pendingShort) {
                rows.push([pendingShort]);
                pendingShort = null;
            }
            rows.push([btn]);
        }
    }
    
    if (pendingShort) {
        rows.push([pendingShort]);
    }
    
    return rows;
}

console.log('✅ FASE 0: buildAutoLayout loaded');

// ============================================================
// 13. BUILD ITEM LABEL (Konsisten untuk semua kategori)
// ============================================================
function buildItemLabel(item, options = {}) {
    const {
        icon = '📌',
        namaField = 'nama',
        countField = null,
        countLabel = 'item',
        showId = false,
        maxLength = 60
    } = options;
    
    let label = `${icon} ${item[namaField] || '-'}`;
    
    if (countField && item[countField] !== undefined && item[countField] !== null) {
        label += ` (${item[countField]} ${countLabel})`;
    }
    
    if (showId && item.id) {
        label += ` [${item.id}]`;
    }
    
    return shortenText(label, maxLength);
}

