// ============================================================
// 15. BUILD JENJANG LIST (String, comma-separated)
// ============================================================
function buildJenjangList(jenjangList) {
    if (!jenjangList || jenjangList.length === 0) return '';
    
    const list = jenjangList.split(',').map(j => j.trim()).filter(Boolean);
    return list.map(j => getJenjangBadge(j)).join(', ');
}

// ============================================================
// 16. FORMAT CONTEXT HEADER (Standard)
// ============================================================
function formatContextHeader(context, stepInfo = null) {
    let msg = '';
    
    if (context && Object.values(context).some(v => v)) {
        msg += `📍 *Lokasi:*\n${buildBreadcrumb(context)}\n\n`;
    }
    
    if (stepInfo) {
        msg += `_${stepInfo}_\n\n`;
    }
    
    return msg;
}

// ============================================================
// 17. RESET CONTEXT STEP AFTER
// ============================================================
async function resetContextAfter(env, userId, currentStep) {
    const session = await getSession(env, userId);
    const context = session.context || getEmptyContext();
    
    const stepOrder = [
        'kategori', 'bidang', 'program', 'jenjang', 
        'topik', 'subtopik', 'kisi', 'kemampuan', 'subkemampuan'
    ];
    
    const currentIdx = stepOrder.indexOf(currentStep);
    
    if (currentIdx === -1) return context;
    
    // Reset semua step setelah currentStep
    for (let i = currentIdx + 1; i < stepOrder.length; i++) {
        const step = stepOrder[i];
        context[`${step}Id`] = null;
        context[`${step}Nama`] = null;
    }
    
    // Khusus untuk kisi
    context.kisiJudul = null;
    
    session.context = context;
    await saveSession(env, userId, session);
    
    return context;
}

