// 🆕 FASE 5: DRILL-DOWN SELECTION FUNCTIONS
// Patch: v2.0 — 5 Step + Sub-Step + Pagination
// Lokasi: Sebelum handleCommand()
// ============================================================

// ============================================================
// 🆕 FASE 7.8: showKategoriSelection (Breadcrumb Teks + Tombol Lompat)
// ============================================================
async function showKategoriSelection(env, userId, chatId, db, mode, page = 1) {
    // Reset context + CLEAR semua action lama
    const session = await getSession(env, userId);
    session.mode = mode;
    session.context = getEmptyContext();
    session.step = 'kategori';
    session.drillCurrentPage = page;
    
    // CLEAR action & tempData
    session.action = null;
    session.tempData = null;
    session.editId = null;
    session.soalId = null;
    session.materiId = null;
    session.tahapKode = null;
    session.deleteItems = null;
    session.deleteConfig = null;
    session.pendingRollback = null;
    
    await saveSession(env, userId, session);
    
    // Ambil semua kategori
    const kategori = await db.prepare(`
        SELECT 
            k.id, 
            k.nama,
            COUNT(DISTINCT t.id) as total_topik
        FROM kategori k
        LEFT JOIN bidang_studi b ON b.kategori_id = k.id
        LEFT JOIN program_studi p ON p.bidang_studi_id = b.id
        LEFT JOIN topik t ON (t.program_studi_id = p.id OR t.mata_pelajaran_id IN (SELECT mp.id FROM mata_pelajaran mp WHERE mp.bidang_studi_id = b.id) OR t.mata_kuliah_id IN (SELECT mk.id FROM mata_kuliah mk WHERE mk.program_studi_id = p.id))
        GROUP BY k.id
        ORDER BY k.nama
    `).all();
    
    const allItems = kategori.results || [];
    
    if (allItems.length === 0) {
        await sendMessage(chatId, 
            `❌ *Belum ada Kategori*\n\n` +
            `💡 Buat kategori terlebih dahulu:\n` +
            `• /kategori_add\n` +
            `• /upload_hierarki\n\n` +
            `🔙 Kembali: /ai`
        );
        return;
    }
    
    // Pagination
    const perPage = PAGINATION.itemsPerPage;
    const totalPages = Math.ceil(allItems.length / perPage);
    const currentPage = Math.min(Math.max(page, 1), totalPages);
    const start = (currentPage - 1) * perPage;
    const items = allItems.slice(start, start + perPage);
    
    // Build message
    let msg = `${MODE_LABELS[mode] || '🤖 Menu'}\n`;
    msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
    msg += `📂 *Langkah 1/6: Pilih Kategori*\n\n`;
    msg += `${buildPaginationInfo(currentPage, totalPages, allItems.length)}\n\n`;
    msg += `_Pilih kategori materi_\n\n`;
    
    // Build keyboard
    const keyboard = [];
    
    // Isi kategori
    for (const k of items) {
        const label = `📂 ${k.nama} (${k.total_topik} topik)`;
        keyboard.push([{
            text: shortenText(label, 60),
            callback_data: `ctx_kat_${k.id}`
        }]);
    }
    
    // Pagination
    const paginationKb = buildPaginationKeyboard(currentPage, totalPages, 'ctx_kat');
    keyboard.push(...paginationKb);
    
    // 🆕 Tombol Lompat ke Step Lain (di step 1, hanya bisa lompat ke Kategori = tetap di sini)
    
    // Navigation
    keyboard.push([{ text: "🔙 Batal", callback_data: "ai_menu" }]);
    
    await sendOrEditDrilldown(chatId, msg, keyboard);
}

