// ============================================================
// SCHOOL HIERARCHY: Kategori → Bidang → Jenjang → Kelas → Mata Pelajaran
// ============================================================
async function showSchoolJenjangSelection(env, userId, chatId, db, bidangId, page = 1) {
    const bidang = await db.prepare(`
        SELECT b.id, b.nama, k.id AS kategori_id, k.nama AS kategori_nama
        FROM bidang_studi b
        LEFT JOIN kategori k ON k.id = b.kategori_id
        WHERE b.id = ? LIMIT 1
    `).bind(bidangId).first();
    if (!bidang) {
        await smartMessage(chatId, '❌ Bidang Studi tidak ditemukan.');
        return;
    }

    const session = await getSession(env, userId);
    session.context.kategoriId = bidang.kategori_id;
    session.context.kategoriNama = bidang.kategori_nama;
    session.context.bidangId = bidang.id;
    session.context.bidangNama = bidang.nama;
    session.context.programId = null;
    session.context.programNama = null;
    session.context.jenjang = null;
    session.context.jenjangNama = null;
    session.context.kelas = null;
    session.context.kelasNama = null;
    session.context.mataPelajaranId = null;
    session.context.mataPelajaranNama = null;
    session.context.mataKuliahId = null;
    session.context.mataKuliahNama = null;
    session.context.semester = null;
    session.step = 'jenjang';
    session.drillCurrentPage = page;
    await saveSession(env, userId, session);

    const r = await db.prepare(`
        SELECT j.id, j.nama, j.jenis, j.icon, j.urutan,
               COUNT(DISTINCT k.id) AS total_kelas,
               COUNT(DISTINCT CASE WHEN mp.is_active = 1 AND mp.bidang_studi_id = ? THEN mp.id END) AS total_mata_pelajaran
        FROM jenjang j
        JOIN kelas k ON k.jenjang_id = j.id AND k.is_active = 1
        LEFT JOIN mata_pelajaran mp ON mp.kelas_id = k.id
        WHERE j.is_active = 1 AND UPPER(j.jenis) IN ('SD','SMP','SMA','SMK')
        GROUP BY j.id
        ORDER BY j.urutan, j.id
    `).bind(bidangId).all();
    const allItems = r.results || [];
    const perPage = PAGINATION.itemsPerPage;
    const totalPages = Math.max(1, Math.ceil(allItems.length / perPage));
    const currentPage = Math.min(Math.max(page, 1), totalPages);
    const items = allItems.slice((currentPage - 1) * perPage, currentPage * perPage);

    let msg = `🏫 *Langkah 3/7: Pilih Jenjang*\n${DIVIDER}\n\n`;
    msg += `📍 *Lokasi:*\n${buildBreadcrumbText(session.context)}\n\n`;
    msg += `${buildPaginationInfo(currentPage, totalPages, allItems.length)}\n\n`;
    const keyboard = [];
    if (!allItems.length) {
        msg += `⚠️ Belum ada Jenjang sekolah yang memiliki Kelas + Mata Pelajaran pada Bidang ini.\n\n`;
        keyboard.push([{ text: '🔷 Kelola Jenjang', callback_data: 'menu_ent_jenjang' }]);
        keyboard.push([{ text: '🔷 Kelola Kelas', callback_data: 'menu_ent_kelas' }]);
    } else {
        for (const j of items) {
            keyboard.push([{ text: shortenText(`${j.icon || '🏫'} ${j.nama} (${j.jenis}) • ${j.total_kelas} kelas • ${j.total_mata_pelajaran} mapel`, 60), callback_data: `ctx_jenj_${j.id}` }]);
        }
        if (totalPages > 1) keyboard.push(...buildPaginationKeyboard(currentPage, totalPages, `ctx_school_jenj_${bidangId}`));
    }
    keyboard.push([{ text: '⬅️ Kembali ke Bidang', callback_data: 'ctx_back_bid' }]);
    keyboard.push([{ text: '🔙 Batal', callback_data: 'ai_menu' }]);
    await sendOrEditDrilldown(chatId, msg, keyboard);
}

// ============================================================
// 🆕 FASE 7.8: showJenjangFilter (Breadcrumb Teks + Selalu Tampil)
// Jenjang SELALU ditampilkan, tidak auto-skip
// ============================================================
async function showJenjangFilter(env, userId, chatId, db, programId, page = 1) {
    // Ambil info program + kategori
    const program = await db.prepare(`
        SELECT p.nama as program_nama, k.nama as kategori_nama, k.id as kategori_id
        FROM program_studi p
        LEFT JOIN bidang_studi b ON p.bidang_studi_id = b.id
        LEFT JOIN kategori k ON b.kategori_id = k.id
        WHERE p.id = ?
    `).bind(programId).first();
    
    if (!program) {
        await sendMessage(chatId, `❌ Program tidak ditemukan.`);
        return;
    }
    
    // Save context
    const session = await getSession(env, userId);
    session.context.programId = programId;
    session.context.programNama = program.program_nama;
    session.context.kategoriNama = program.kategori_nama;
    session.step = 'jenjang';
    session.drillCurrentPage = page;
    await saveSession(env, userId, session);
    
    // Cek apakah kategori butuh jenjang (untuk info saja)
    const kategoriNama = program.kategori_nama || '';
    const butuhJenjang = needsJenjang(kategoriNama);
    
    // Ambil jenjang yang tersedia. Untuk Mata Pelajaran, sumbernya adalah Kelas/Mata Pelajaran,
    // bukan Topik, agar hierarchy tetap bisa berjalan meskipun Topik belum dibuat.
    let jenjangQuery = `
        SELECT DISTINCT 
            j.id, 
            j.nama, 
            j.icon,
            j.jenis, 
            j.urutan,
            (SELECT COUNT(DISTINCT t.id)
             FROM topik t
             JOIN topik_jenjang tj ON t.id = tj.topik_id
             WHERE tj.jenjang_id = j.id AND t.program_studi_id = ?) as total_topik
        FROM jenjang j
        WHERE j.is_active = 1
        AND (`;
    const jenjangBinds = [programId, programId, programId];
    jenjangQuery += `
            EXISTS (
                SELECT 1 FROM topik_jenjang tj
                JOIN topik t ON tj.topik_id = t.id
                WHERE tj.jenjang_id = j.id AND t.program_studi_id = ?
            )
            OR EXISTS (
                SELECT 1 FROM mata_kuliah mk
                WHERE mk.jenjang_id = j.id AND mk.program_studi_id = ? AND mk.is_active = 1
            )`;
    if (kategoriNama === 'Mata Pelajaran') {
        jenjangQuery += `
            OR EXISTS (
                SELECT 1 FROM kelas k
                JOIN mata_pelajaran mp ON mp.kelas_id = k.id
                WHERE k.jenjang_id = j.id AND k.is_active = 1 AND mp.is_active = 1 AND mp.bidang_studi_id = ?
            )`;
        jenjangBinds.push(session.context.bidangId || '');
    }
    jenjangQuery += `
        )
        ORDER BY j.urutan`;
    const jenjangTersedia = await db.prepare(jenjangQuery).bind(...jenjangBinds).all();
    
    const allItems = jenjangTersedia.results || [];
    
    // Pagination
    const perPage = PAGINATION.itemsPerPage;
    const totalPages = Math.max(1, Math.ceil(allItems.length / perPage));
    const currentPage = Math.min(Math.max(page, 1), totalPages);
    const start = (currentPage - 1) * perPage;
    const items = allItems.slice(start, start + perPage);
    
    // Build message
    const sessionFresh = await getSession(env, userId);
    
    let msg = `🏫 *Langkah 4/6: Pilih Jenjang*\n`;
    msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
    msg += `📍 *Lokasi:*\n${buildBreadcrumbText(sessionFresh.context)}\n\n`;
    msg += `${buildPaginationInfo(currentPage, totalPages, allItems.length)}\n\n`;
    
    // Build keyboard
    const keyboard = [];
    
    // ============================================================
    // KASUS 1: ADA JENJANG
    // ============================================================
    if (allItems.length > 0) {
        msg += `_Pilih jenjang atau lihat semua_\n\n`;
        
        keyboard.push([{ text: "🌐 Semua Jenjang", callback_data: `ctx_jenj_all` }]);
        
        for (const j of items) {
            const label = `${j.icon || '🏫'} ${j.nama} (${j.total_topik} topik)`;
            keyboard.push([{
                text: shortenText(label, 60),
                callback_data: `ctx_jenj_${j.id}`
            }]);
        }
        
        // Pagination
        if (totalPages > 1) {
            const paginationKb = buildPaginationKeyboard(currentPage, totalPages, `ctx_jenj_${programId}`);
            keyboard.push(...paginationKb);
        }
    }
    // ============================================================
    // KASUS 2: TIDAK ADA JENJANG
    // ============================================================
    else {
        msg += `⚠️ *Belum ada Jenjang ter-link di program ini.*\n\n`;
        
        if (!butuhJenjang) {
            msg += `💡 Kategori "${kategoriNama}" _tidak butuh jenjang_.\n`;
            msg += `Anda bisa langsung lanjut, atau tambah jenjang kalau perlu.\n\n`;
        } else {
            msg += `💡 Kategori "${kategoriNama}" _sebaiknya pakai jenjang_.\n`;
            msg += `Silakan tambah jenjang terlebih dahulu, atau lanjut tanpa jenjang.\n\n`;
        }
        
        keyboard.push([{ text: "➕ Tambah Jenjang ke Program Ini", callback_data: `ctx_add_jenjang_${programId}` }]);
        keyboard.push([{ text: "▶️ Lanjut Tanpa Jenjang", callback_data: `ctx_jenj_all` }]);
    }
    
    // Navigation
    keyboard.push([{ text: "⬅️ Ganti Program", callback_data: "ctx_back_prog" }]);
    keyboard.push([{ text: "🔙 Batal", callback_data: "ai_menu" }]);
    
    await sendOrEditDrilldown(chatId, msg, keyboard);
}

// ============================================================
// 🆕 FASE MP-1: showKelasSelection
// Mata Pelajaran dipilih SETELAH Jenjang dan Kelas, sebelum Topik.
// ============================================================
async function showKelasSelection(env, userId, chatId, db, programId, jenjangId = 'all', page = 1) {
    const session = await getSession(env, userId);
    session.context.jenjang = jenjangId || 'all';
    session.context.jenjangNama = null;
    session.context.kelas = null;
    session.context.mataPelajaranId = null;
    session.context.mataPelajaranNama = null;
    session.step = 'kelas';
    session.drillCurrentPage = page;

    if (jenjangId && jenjangId !== 'all') {
        const j = await db.prepare(`
            SELECT id, nama, jenis FROM jenjang
            WHERE id = ? AND is_active = 1 LIMIT 1
        `).bind(jenjangId).first();
        if (!j || !['SD','SMP','SMA','SMK'].includes(String(j.jenis || '').toUpperCase())) {
            await smartMessage(chatId, '❌ Jenjang sekolah tidak valid.');
            return;
        }
        session.context.jenjangNama = j.nama;
    }
    await saveSession(env, userId, session);

    let query = `
        SELECT k.id, k.nama, k.jenjang_id,
               j.nama AS jenjang_nama, j.jenis,
               (SELECT COUNT(*) FROM mata_pelajaran mp
                WHERE mp.kelas_id = k.id AND mp.is_active = 1
                  AND mp.bidang_studi_id = ?) AS total_mata_pelajaran
        FROM kelas k
        JOIN jenjang j ON j.id = k.jenjang_id
        WHERE k.is_active = 1
          AND j.is_active = 1
          AND j.jenis IN ('SD','SMP','SMA','SMK')
    `;
    const bind = [session.context.bidangId || ''];
    if (jenjangId && jenjangId !== 'all') {
        query += ` AND k.jenjang_id = ?`;
        bind.push(jenjangId);
    }
    query += ` ORDER BY j.urutan, k.urutan, k.nama`;

    const r = await db.prepare(query).bind(...bind).all();
    const allItems = r.results || [];
    const perPage = PAGINATION.itemsPerPage;
    const totalPages = Math.max(1, Math.ceil(allItems.length / perPage));
    const currentPage = Math.min(Math.max(page, 1), totalPages);
    const items = allItems.slice((currentPage - 1) * perPage, currentPage * perPage);
    const fresh = await getSession(env, userId);

    let msg = `📚 *Langkah 5/7: Pilih Kelas*\n${DIVIDER}\n\n`;
    msg += `📍 *Lokasi:*\n${buildBreadcrumbText(fresh.context)}\n\n`;
    msg += `${buildPaginationInfo(currentPage, totalPages, allItems.length)}\n\n`;

    const keyboard = [];
    if (!allItems.length) {
        msg += `⚠️ Belum ada Kelas untuk Jenjang ini.\n\n`;
        keyboard.push([{ text: '🔷 Kelola Kelas', callback_data: 'menu_ent_kelas' }]);
    } else {
        for (const k of items) {
            const jenjangInfo = jenjangId === 'all' ? ` • ${k.jenjang_nama}` : '';
            const mpInfo = k.total_mata_pelajaran > 0 ? ` • ${k.total_mata_pelajaran} mapel` : '';
            keyboard.push([{
                text: shortenText(`📚 ${k.nama}${jenjangInfo}${mpInfo}`, 60),
                callback_data: `ctx_kelas_${k.id}`
            }]);
        }
        if (totalPages > 1) {
            keyboard.push(...buildPaginationKeyboard(currentPage, totalPages, `ctx_kelaslist_${programId}_${jenjangId || 'all'}`));
        }
    }
    keyboard.push([{ text: '⬅️ Kembali ke Jenjang', callback_data: 'ctx_back_jenj' }]);
    keyboard.push([{ text: '🔙 Batal', callback_data: 'ai_menu' }]);
    await sendOrEditDrilldown(chatId, msg, keyboard);
}

// ============================================================
// 🆕 FASE MP-2: showMataPelajaranSelection
// Mata Pelajaran dipilih SETELAH Kelas dan SEBELUM Topik.
// ============================================================
async function showMataPelajaranSelection(env, userId, chatId, db, programId, kelasId, page = 1) {
    const session = await getSession(env, userId);
    const kelas = await db.prepare(`
        SELECT k.id, k.nama, k.jenjang_id, j.nama AS jenjang_nama, j.jenis
        FROM kelas k JOIN jenjang j ON j.id = k.jenjang_id
        WHERE k.id = ? AND j.jenis IN ('SD','SMP','SMA','SMK') LIMIT 1
    `).bind(kelasId).first();
    if (!kelas) {
        await smartMessage(chatId, '❌ Kelas sekolah tidak ditemukan atau tidak valid.');
        return;
    }

    session.context.kelas = kelas.id;
    session.context.jenjang = kelas.jenjang_id;
    session.context.jenjangNama = kelas.jenjang_nama;
    session.context.kelasNama = kelas.nama;
    session.context.mataPelajaranId = null;
    session.context.mataPelajaranNama = null;
    session.step = 'mata_pelajaran';
    session.drillCurrentPage = page;
    await saveSession(env, userId, session);

    const r = await db.prepare(`
        SELECT mp.id, mp.kode, mp.nama,
               (SELECT COUNT(*) FROM topik t WHERE t.mata_pelajaran_id = mp.id) AS total_topik
        FROM mata_pelajaran mp
        WHERE mp.kelas_id = ? AND mp.is_active = 1
          AND mp.bidang_studi_id = ?
        ORDER BY mp.urutan, mp.nama
    `).bind(kelasId, session.context.bidangId || '').all();
    const allItems = r.results || [];
    const perPage = PAGINATION.itemsPerPage;
    const totalPages = Math.max(1, Math.ceil(allItems.length / perPage));
    const currentPage = Math.min(Math.max(page, 1), totalPages);
    const items = allItems.slice((currentPage - 1) * perPage, currentPage * perPage);
    const fresh = await getSession(env, userId);

    let msg = `📖 *Langkah 6/7: Pilih Mata Pelajaran*\n${DIVIDER}\n\n`;
    msg += `📍 *Lokasi:*\n${buildBreadcrumbText(fresh.context)}\n\n`;
    msg += `${buildPaginationInfo(currentPage, totalPages, allItems.length)}\n\n`;
    const keyboard = [];
    if (!allItems.length) {
        msg += `⚠️ Belum ada Mata Pelajaran untuk kelas ini.\n\n`;
        keyboard.push([{ text: '🔷 Kelola Mata Pelajaran', callback_data: 'menu_ent_mata_pelajaran' }]);
    } else {
        for (const mp of items) {
            const kode = mp.kode ? `${mp.kode} — ` : '';
            keyboard.push([{
                text: shortenText(`📖 ${kode}${mp.nama} (${mp.total_topik} topik)`, 60),
                callback_data: `ctx_mp_${mp.id}`
            }]);
        }
        if (totalPages > 1) {
            keyboard.push(...buildPaginationKeyboard(currentPage, totalPages, `ctx_mplist_${kelasId}`));
        }
    }
    keyboard.push([{ text: '⬅️ Kembali ke Kelas', callback_data: 'ctx_back_kelas' }]);
    keyboard.push([{ text: '🔙 Batal', callback_data: 'ai_menu' }]);
    await sendOrEditDrilldown(chatId, msg, keyboard);
}

// ============================================================
// 🆕 FASE MK-1: showMataKuliahSelection
// Mata Kuliah dipilih SETELAH Jenjang dan SEBELUM Topik.
// Semester hanya atribut Mata Kuliah.
// ============================================================
async function showMataKuliahSelection(env, userId, chatId, db, programId, jenjangId, page = 1) {
    const session = await getSession(env, userId);
    session.context.jenjang = jenjangId || null;
    session.context.jenjangNama = null;
    session.context.mataKuliahId = null;
    session.context.mataKuliahNama = null;
    session.context.semester = null;
    session.step = 'mata_kuliah';
    session.drillCurrentPage = page;

    if (jenjangId) {
        const j = await db.prepare(`SELECT nama FROM jenjang WHERE id = ?`).bind(jenjangId).first();
        session.context.jenjangNama = j?.nama || jenjangId;
    }
    await saveSession(env, userId, session);

    let query = `
        SELECT mk.id, mk.kode, mk.nama, mk.semester,
               (SELECT COUNT(*) FROM topik t WHERE t.mata_kuliah_id = mk.id) AS total_topik
        FROM mata_kuliah mk
        WHERE mk.program_studi_id = ? AND mk.is_active = 1
    `;
    const bind = [programId];
    if (jenjangId && jenjangId !== 'all') {
        query += ` AND mk.jenjang_id = ?`;
        bind.push(jenjangId);
    }
    query += ` ORDER BY COALESCE(mk.semester, 999), mk.urutan, mk.nama`;

    const r = await db.prepare(query).bind(...bind).all();
    const allItems = r.results || [];
    const perPage = PAGINATION.itemsPerPage;
    const totalPages = Math.max(1, Math.ceil(allItems.length / perPage));
    const currentPage = Math.min(Math.max(page, 1), totalPages);
    const items = allItems.slice((currentPage - 1) * perPage, currentPage * perPage);
    const fresh = await getSession(env, userId);

    let msg = `📘 *Langkah 5/6: Pilih Mata Kuliah*\n${DIVIDER}\n\n`;
    msg += `📍 *Lokasi:*\n${buildBreadcrumbText(fresh.context)}\n\n`;
    msg += `${buildPaginationInfo(currentPage, totalPages, allItems.length)}\n\n`;

    const keyboard = [];
    if (!allItems.length) {
        msg += `⚠️ Belum ada Mata Kuliah untuk Program Studi + Jenjang ini.\n\n`;
        keyboard.push([{ text: `➕ Tambah Mata Kuliah`, callback_data: `ctx_add_mk_${programId}_${jenjangId || 'all'}` }]);
    } else {
        for (const mk of items) {
            const sem = mk.semester ? ` • Smt ${mk.semester}` : '';
            const kode = mk.kode ? `${mk.kode} — ` : '';
            keyboard.push([{ text: shortenText(`📘 ${kode}${mk.nama}${sem} (${mk.total_topik} topik)`, 60), callback_data: `ctx_mk_${mk.id}` }]);
        }
        keyboard.push(...buildPaginationKeyboard(currentPage, totalPages, `ctx_mklist_${programId}_${jenjangId || 'all'}`));
    }
    keyboard.push([{ text: `⬅️ Kembali ke Jenjang`, callback_data: `ctx_back_jenj` }]);
    keyboard.push([{ text: `🔙 Batal`, callback_data: `ai_menu` }]);
    await sendOrEditDrilldown(chatId, msg, keyboard);
}

// ============================================================
// 🆕 FASE 7.8: showTopikSelection (Breadcrumb Teks + Tombol Lompat)
// ============================================================
async function showTopikSelection(env, userId, chatId, db, programId, jenjang, kelas = null, page = 1, mataKuliahId = null, mataPelajaranId = null) {
    // Save context
    const session = await getSession(env, userId);
    session.context.jenjang = jenjang;
    session.context.kelas = kelas;
    session.context.mataKuliahId = mataKuliahId || session.context.mataKuliahId || null;
    session.context.mataPelajaranId = mataPelajaranId || session.context.mataPelajaranId || null;
    session.step = 'topik';
    session.drillCurrentPage = page;
    await saveSession(env, userId, session);
    
    // Build query dengan filter
    let query = `
        SELECT DISTINCT
            t.id, 
            t.nama,
            (SELECT COUNT(*) FROM sub_topik WHERE topik_id = t.id) as total_subtopik,
            (SELECT GROUP_CONCAT(DISTINCT jenjang_id) FROM topik_jenjang WHERE topik_id = t.id) as jenjang_list,
            (SELECT COUNT(*) FROM soal s 
             WHERE s.topik_id = t.id AND s.status = 'AKTIF') as total_soal
        FROM topik t
        WHERE (t.program_studi_id = ? OR t.program_studi_id IS NULL)
    `;
    const bind = [programId];
    
    if (mataPelajaranId) {
        query += ` AND t.mata_pelajaran_id = ?`;
        bind.push(mataPelajaranId);
    } else if (mataKuliahId) {
        query += ` AND t.mata_kuliah_id = ?`;
        bind.push(mataKuliahId);
    } else if (jenjang && jenjang !== 'all') {
        query += ` AND EXISTS (
            SELECT 1 FROM topik_jenjang tj 
            WHERE tj.topik_id = t.id AND tj.jenjang_id = ?
        )`;
        bind.push(jenjang);
    }
    
    query += ` ORDER BY t.nama`;
    
    const topics = await db.prepare(query).bind(...bind).all();
    const allItems = topics.results || [];
    
    // ============================================================
    // KASUS KOSONG
    // ============================================================
    if (allItems.length === 0) {
        console.log(`ℹ️ showTopikSelection: tidak ada topik untuk program ${programId}`);
        
        const sessionFresh = await getSession(env, userId);
        
        let msg = `⚠️ *Belum ada Topik*\n`;
        msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
        msg += `📍 *Lokasi:*\n${buildBreadcrumbText(sessionFresh.context)}\n\n`;
        msg += `💡 Tambah topik terlebih dahulu:`;
        
        const errorKeyboard = [
            [{ text: "➕ Buat Topik Baru", callback_data: `ctx_add_topik_${programId}` }],
            [{ text: "⬅️ Ganti Filter", callback_data: "ctx_back_jenj" }],
            [{ text: "🔙 Batal", callback_data: "ai_menu" }]
        ];
        
        await sendInlineKeyboard(chatId, msg, errorKeyboard);
        return;
    }
    
    // Pagination
    const perPage = PAGINATION.itemsPerPage;
    const totalPages = Math.ceil(allItems.length / perPage);
    const currentPage = Math.min(Math.max(page, 1), totalPages);
    const start = (currentPage - 1) * perPage;
    const items = allItems.slice(start, start + perPage);
    
    // Build message
    const sessionFresh = await getSession(env, userId);
    
    const isMataKuliahContext = Boolean(mataKuliahId || sessionFresh.context.mataKuliahId);
    const isMataPelajaranContext = Boolean(mataPelajaranId || sessionFresh.context.mataPelajaranId);
    const stepLabel = isMataPelajaranContext ? '7/7' : (isMataKuliahContext ? '6/6' : '5/6');
    let msg = `📖 *Langkah ${stepLabel}: Pilih Topik*\n`;
    msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
    msg += `📍 *Lokasi:*\n${buildBreadcrumbText(sessionFresh.context)}\n\n`;
    msg += `${buildPaginationInfo(currentPage, totalPages, allItems.length)}\n\n`;
    
    // Build keyboard
    const keyboard = [];
    
    // Isi topik
    for (const t of items) {
        const jenjangInfo = t.jenjang_list ? ` [${t.jenjang_list}]` : '';
        const subInfo = t.total_subtopik > 0 ? `${t.total_subtopik} sub` : '0 sub';
        const soalInfo = t.total_soal > 0 ? ` • ${t.total_soal} soal` : '';
        const label = `📖 ${t.nama}${jenjangInfo} (${subInfo}${soalInfo})`;
        
        keyboard.push([{
            text: shortenText(label, 60),
            callback_data: `ctx_top_${t.id}`
        }]);
    }
    
    // Pagination
    const paginationKb = buildPaginationKeyboard(currentPage, totalPages, `ctx_top_${programId}`);
    keyboard.push(...paginationKb);
    
    // Tombol Tambah Topik
    keyboard.push([{ text: "➕ Buat Topik Baru", callback_data: `ctx_add_topik_${programId}` }]);
    
    // Navigation
    keyboard.push([{ text: "⬅️ Ganti Filter", callback_data: "ctx_back_jenj" }]);
    keyboard.push([{ text: "🔙 Batal", callback_data: "ai_menu" }]);
    
    await sendOrEditDrilldown(chatId, msg, keyboard);
}

