        console.log(`ℹ️ showSubTopikSelection: tidak ada sub-topik untuk ${topikId}`);
        
        const sessionFresh = await getSession(env, userId);
        sessionFresh.context.subtopikId = null;
        sessionFresh.context.subtopikNama = null;
        await saveSession(env, userId, sessionFresh);
        
