// 🆕 FASE 7.8: showKemampuanSelection (Breadcrumb Teks + Tombol Lompat)
// ============================================================
async function showKemampuanSelection(env, userId, chatId, db, kisiId, page = 1) {
    // Save context
    const session = await getSession(env, userId);
    
    const kisi = await db.prepare(`SELECT judul FROM kisi_kisi WHERE id = ?`)
        .bind(kisiId).first();
    
    session.context.kisiId = kisiId;
    session.context.kisiJudul = kisi?.judul || kisiId;
    session.step = 'kemampuan';
    session.drillCurrentPage = page;
    await saveSession(env, userId, session);
    
    // Ambil kemampuan
    const kemampuan = await db.prepare(`
        SELECT 
            km.id, 
            km.nama,
            (SELECT COUNT(*) FROM sub_kemampuan WHERE kemampuan_id = km.id) as total_sub,
            (SELECT COUNT(*) FROM soal WHERE kemampuan_id = km.id AND status = 'AKTIF') as total_soal
        FROM kemampuan_diuji km
        WHERE km.kisi_kisi_id = ?
        ORDER BY km.nama
    `).bind(kisiId).all();
    
    const allItems = kemampuan.results || [];
    
    // ============================================================
    // KASUS KOSONG
    // ============================================================
    if (allItems.length === 0) {
        console.log(`ℹ️ showKemampuanSelection: tidak ada kemampuan untuk ${kisiId}`);
        
        const sessionFresh = await getSession(env, userId);
        sessionFresh.context.kemampuanId = null;
        sessionFresh.context.kemampuanNama = null;
        await saveSession(env, userId, sessionFresh);
        
        let msg = `⚠️ *Belum ada Kemampuan*\n`;
        msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
        msg += `📍 *Lokasi:*\n${buildBreadcrumbText(sessionFresh.context)}\n\n`;
        msg += `Kisi-kisi "${kisi?.judul || kisiId}" belum memiliki kemampuan yang diuji.\n\n`;
        msg += `💡 *Pilihan Anda:*\n`;
        msg += `• Buat kemampuan dulu (lebih terstruktur)\n`;
        msg += `• Langsung generate dari kisi (lebih cepat)\n\n`;
        
        const errorKeyboard = [
            [{ text: "➕ Buat Kemampuan Baru", callback_data: `ctx_add_kemampuan_${kisiId}` }],
            [{ text: "▶️ Langsung Generate dari Kisi", callback_data: "ctx_gen_ready" }],
            [{ text: "⬅️ Ganti Kisi", callback_data: "ctx_back_kisi" }],
            [{ text: "🔙 Batal", callback_data: "ai_menu" }]
        ];
        
        await sendInlineKeyboard(chatId, msg, errorKeyboard);
        return;
    }
    
    // Pagination
    const perPage = PAGINATION.itemsPerPage;
    const totalPages = Math.ceil(allItems.length / perPage);
    const currentPage = Math.min(Math.max(page, 1), totalPages);
    const start = (currentPage - 1) * perPage;
    const items = allItems.slice(start, start + perPage);
    
    // Build message
    const sessionFresh = await getSession(env, userId);
    
    let msg = `🎯 *Langkah 8: Pilih Kemampuan*\n`;
    msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
    msg += `📍 *Lokasi:*\n${buildBreadcrumbText(sessionFresh.context)}\n\n`;
    msg += `${buildPaginationInfo(currentPage, totalPages, allItems.length)}\n\n`;
    msg += `_Pilih kemampuan atau langsung generate dari kisi_\n\n`;
    
    // Build keyboard
    const keyboard = [];
    
    // Isi kemampuan
    for (const km of items) {
        const label = `🎯 ${km.nama} (${km.total_sub} sub)`;
        keyboard.push([{
            text: shortenText(label, 60),
            callback_data: `ctx_kem_${km.id}`
        }]);
    }
    
    // Pagination
    const paginationKb = buildPaginationKeyboard(currentPage, totalPages, `ctx_kem_${kisiId}`);
    keyboard.push(...paginationKb);
    
    // Tombol Tambah Kemampuan
    keyboard.push([{ text: "➕ Buat Kemampuan Baru", callback_data: `ctx_add_kemampuan_${kisiId}` }]);
    
    // Navigation
    keyboard.push([{ text: "▶️ Generate dari Kisi", callback_data: "ctx_gen_ready" }]);
    keyboard.push([{ text: "⬅️ Ganti Kisi", callback_data: "ctx_back_kisi" }]);
    keyboard.push([{ text: "🔙 Batal", callback_data: "ai_menu" }]);
    
    await sendOrEditDrilldown(chatId, msg, keyboard);
}

