async function showSubKemampuanSelection(env, userId, chatId, db, kemampuanId, page = 1) {
    // Save context
    const session = await getSession(env, userId);
    
    const kemampuan = await db.prepare(`SELECT nama FROM kemampuan_diuji WHERE id = ?`)
        .bind(kemampuanId).first();
    
    session.context.kemampuanId = kemampuanId;
    session.context.kemampuanNama = kemampuan?.nama || kemampuanId;
    session.step = 'subkemampuan';
    session.drillCurrentPage = page;
    await saveSession(env, userId, session);
    
    // Ambil sub-kemampuan
    const subKemampuan = await db.prepare(`
        SELECT 
            sk.id, 
            sk.nama,
            (SELECT COUNT(*) FROM soal WHERE sub_kemampuan_id = sk.id AND status = 'AKTIF') as total_soal
        FROM sub_kemampuan sk
        WHERE sk.kemampuan_id = ?
        ORDER BY sk.nama
    `).bind(kemampuanId).all();
    
    const allItems = subKemampuan.results || [];
    
    // ============================================================
    // KASUS KOSONG
    // ============================================================
    if (allItems.length === 0) {
        console.log(`ℹ️ showSubKemampuanSelection: tidak ada sub-kemampuan untuk ${kemampuanId}`);
        
        const sessionFresh = await getSession(env, userId);
        sessionFresh.context.subKemampuanId = null;
        sessionFresh.context.subKemampuanNama = null;
        await saveSession(env, userId, sessionFresh);
        
        let msg = `⚠️ *Belum ada Sub-Kemampuan*\n`;
        msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
        msg += `📍 *Lokasi:*\n${buildBreadcrumbText(sessionFresh.context)}\n\n`;
        msg += `Kemampuan "${kemampuan?.nama || kemampuanId}" belum memiliki sub-kemampuan.\n\n`;
        msg += `💡 *Pilihan Anda:*\n`;
        msg += `• Buat sub-kemampuan dulu (lebih terstruktur)\n`;
        msg += `• Langsung generate dari kemampuan (lebih cepat)\n\n`;
        
        const errorKeyboard = [
            [{ text: "➕ Buat Sub-Kemampuan Baru", callback_data: `ctx_add_subkemampuan_${kemampuanId}` }],
            [{ text: "▶️ Langsung Generate dari Kemampuan", callback_data: "ctx_gen_ready" }],
            [{ text: "⬅️ Ganti Kemampuan", callback_data: "ctx_back_kem" }],
            [{ text: "🔙 Batal", callback_data: "ai_menu" }]
        ];
        
        await sendInlineKeyboard(chatId, msg, errorKeyboard);
        return;
    }
    
    // ============================================================
    // KASUS ADA SUB-KEMAMPUAN
    // ============================================================
    const perPage = PAGINATION.itemsPerPage;
    const totalPages = Math.ceil(allItems.length / perPage);
    const currentPage = Math.min(Math.max(page, 1), totalPages);
    const start = (currentPage - 1) * perPage;
    const items = allItems.slice(start, start + perPage);
    
    // Build message
    const sessionFresh = await getSession(env, userId);
    
    let msg = `📎 *Langkah 9: Pilih Sub-Kemampuan*\n`;
    msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
    msg += `📍 *Lokasi:*\n${buildBreadcrumbText(sessionFresh.context)}\n\n`;
    msg += `${buildPaginationInfo(currentPage, totalPages, allItems.length)}\n\n`;
    msg += `_Pilih sub-kemampuan atau langsung generate dari kemampuan_\n\n`;
    
    // Build keyboard
    const keyboard = [];
    
    // Isi sub-kemampuan
    for (const sk of items) {
        const soalInfo = sk.total_soal > 0 ? ` • ${sk.total_soal} soal` : '';
        const label = `📎 ${sk.nama}${soalInfo}`;
        keyboard.push([{
            text: shortenText(label, 60),
            callback_data: `ctx_subkem_${sk.id}`
        }]);
    }
    
    // Pagination
    const paginationKb = buildPaginationKeyboard(currentPage, totalPages, `ctx_subkem_${kemampuanId}`);
    keyboard.push(...paginationKb);
    
    // Tombol Tambah Sub-Kemampuan
    keyboard.push([{ text: "➕ Buat Sub-Kemampuan Baru", callback_data: `ctx_add_subkemampuan_${kemampuanId}` }]);
    
    // Navigation
    keyboard.push([{ text: "▶️ Generate dari Kemampuan", callback_data: "ctx_gen_ready" }]);
    keyboard.push([{ text: "⬅️ Ganti Kemampuan", callback_data: "ctx_back_kem" }]);
    keyboard.push([{ text: "🔙 Batal", callback_data: "ai_menu" }]);
    
    await sendOrEditDrilldown(chatId, msg, keyboard);
}

// ============================================================
// VALIDATOR SOAL ADMIN — gate sebelum APPROVE
// ============================================================
function validateAdminQuestionRecord(q={}) {
  const errors=[];
  if(!String(q.soal||'').trim()) errors.push('teks soal kosong');
  const opts=['pilihan_a','pilihan_b','pilihan_c','pilihan_d','pilihan_e'].map(k=>String(q[k]||'').trim());
  if(opts.some(v=>!v)) errors.push('pilihan A-E wajib lengkap');
  const answer=String(q.jawaban_benar||'').trim().toUpperCase();
  if(!['A','B','C','D','E'].includes(answer)) errors.push('jawaban_benar harus A-E');
  if(new Set(opts.map(v=>v.toLowerCase())).size<opts.length) errors.push('ada pilihan jawaban duplikat');
  const reasons=['a','b','c','d','e'].map(k=>String(q[`alasan_${k}`]??'').trim());
  if(reasons.some(v=>!v)) errors.push('Alasan A-E wajib lengkap');
  return {valid:errors.length===0,errors};
}
function parseAIJsonObject(text){const raw=String(text||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');try{return JSON.parse(raw)}catch{}const m=raw.match(/\{[\s\S]*\}/);if(m)try{return JSON.parse(m[0])}catch{}return null;}

// ============================================================
// SCHEDULER LIGHT — dipanggil dari Worker request; idempotent per job
// ============================================================
// ============================================================
// SCHEDULER: USER LEARNING REMINDERS / ALARM BELAJAR
// Cron/Worker request memproses jadwal yang jatuh tempo.
// ============================================================
function computeNextReminderRun(row, sentAt=new Date()) {
  const type=String(row?.reminder_type||'ONCE').toUpperCase();
  if(type==='ONCE') return null;
  const base=new Date(sentAt);
  if(Number.isNaN(base.getTime())) return null;
  if(type==='DAILY') { base.setUTCDate(base.getUTCDate()+1); return base.toISOString(); }
  if(type==='WEEKLY') { base.setUTCDate(base.getUTCDate()+7); return base.toISOString(); }
  if(type==='WEEKDAYS') {
    do { base.setUTCDate(base.getUTCDate()+1); } while([0,6].includes(base.getUTCDay()));
    return base.toISOString();
  }
  const days=String(row?.repeat_days||'').split(',').map(Number).filter(n=>Number.isInteger(n)&&n>=0&&n<=6);
  if(type==='CUSTOM' && days.length) {
    for(let i=1;i<=7;i++){const d=new Date(base);d.setUTCDate(d.getUTCDate()+i);if(days.includes(d.getUTCDay()))return d.toISOString();}
  }
  return null;
}
async function processDueUserLearningReminders(env, db) {
  try {
    const now=new Date(), iso=now.toISOString();
    const due=(await db.prepare(`SELECT * FROM user_learning_reminders WHERE status='ACTIVE' AND next_run_at IS NOT NULL AND next_run_at<=? ORDER BY next_run_at ASC LIMIT 50`).bind(iso).all()).results||[];
    let sent=0,failed=0;
    for(const row of due){
      const claim=await db.prepare(`UPDATE user_learning_reminders SET status='PROCESSING',updated_at=? WHERE id=? AND status='ACTIVE'`).bind(iso,row.id).run();
      if(!(claim.meta?.changes>0))continue;
      try{
        const text=`🔔 *${String(row.title||'Pengingat Belajar')}*\n\n${String(row.message||'Saatnya belajar sesuai rencana Anda.')}`;
        const r=await sendMessage(row.telegram_id,text);
        if(r?.ok===false)throw new Error(r.description||'Telegram menolak pesan');
        const next=computeNextReminderRun(row,now);
        if(next){
          await db.prepare(`UPDATE user_learning_reminders SET status='ACTIVE',next_run_at=?,last_sent_at=?,sent_count=COALESCE(sent_count,0)+1,updated_at=? WHERE id=?`).bind(next,iso,iso,row.id).run();
        }else{
          await db.prepare(`UPDATE user_learning_reminders SET status='COMPLETED',next_run_at=NULL,last_sent_at=?,sent_count=COALESCE(sent_count,0)+1,updated_at=? WHERE id=?`).bind(iso,iso,row.id).run();
        }
        sent++;
      }catch(e){
        failed++;
        await db.prepare(`UPDATE user_learning_reminders SET status='ACTIVE',updated_at=? WHERE id=?`).bind(new Date().toISOString(),row.id).run();
        console.warn('learning reminder:',e.message);
      }
    }
    return {due:due.length,sent,failed};
  }catch(e){console.warn('processDueUserLearningReminders:',e.message);return {due:0,sent:0,failed:0,error:e.message};}
}

async function processDueAdminSchedules(env, db) {
  try {
    const now = new Date();
    const iso = now.toISOString();
    const due = (await db.prepare(`SELECT * FROM broadcasts WHERE status='SCHEDULED' AND scheduled_at IS NOT NULL AND scheduled_at<=? ORDER BY scheduled_at ASC LIMIT 5`).bind(iso).all()).results || [];
    for (const job of due) {
      const claim = await db.prepare(`UPDATE broadcasts SET status='PROCESSING',updated_at=? WHERE id=? AND status='SCHEDULED'`).bind(iso,job.id).run();
      if (!(claim.meta?.changes>0)) continue;
      try {
        const filter=safeJson(job.filter_json,null);
        let sql=`SELECT telegram_id FROM users WHERE status='AKTIF' AND telegram_id IS NOT NULL`;
        const binds=[];
        if(filter?.status){sql+=` AND status=?`;binds.push(String(filter.status));}
        const users=(await db.prepare(sql+` LIMIT 1000`).bind(...binds).all()).results||[];
        let sent=0,failed=0;
        for(const u of users){try{const r=await sendMessage(u.telegram_id,String(job.message||''));if(r?.ok!==false)sent++;else failed++;}catch{failed++;}}
        await db.prepare(`UPDATE broadcasts SET status=?,sent_count=?,failed_count=?,updated_at=? WHERE id=?`).bind(failed?'PARTIAL':'SENT',sent,failed,new Date().toISOString(),job.id).run();
      } catch(e) {
        await db.prepare(`UPDATE broadcasts SET status='FAILED',updated_at=? WHERE id=?`).bind(new Date().toISOString(),job.id).run();
        console.warn('scheduled broadcast:',e.message);
      }
    }
  } catch(e){console.warn('processDueAdminSchedules:',e.message);}
}

