// 🆕 FASE 6.26: /delete_subtopik — Hapus Sub-Topik
// Lokasi: handleCommand(), setelah /test_session
// ============================================================

if (cmd === '/delete_subtopik' || cmd === 'delete_subtopik') {
    if (!isAdmin(userId)) {
        await smartMessage(chatId, "⛔ Akses admin diperlukan.");
        return true;
    }
    
    if (args.length === 0) {
        await smartMessage(chatId, 
            `🗑️ *HAPUS SUB-TOPIK*\n\n` +
            `Gunakan: \`/delete_subtopik [ID]\`\n\n` +
            `Contoh: \`/delete_subtopik S001\`\n\n` +
            `💡 Lihat ID: \`/subtopik_list\``
        );
        return true;
    }
    
    const subtopikId = args[0].toUpperCase();
    
    try {
        const subtopik = await db.prepare(`SELECT nama FROM sub_topik WHERE id = ?`)
            .bind(subtopikId).first();
        
        if (!subtopik) {
            await smartMessage(chatId, `❌ Sub-topik \`${subtopikId}\` tidak ditemukan.`);
            return true;
        }
        
        // Cek apakah ada kisi-kisi terkait
        const kisiCount = await db.prepare(`
            SELECT COUNT(*) as c FROM kisi_kisi WHERE sub_topik_id = ?
        `).bind(subtopikId).first();
        
        if (kisiCount && kisiCount.c > 0) {
            await smartMessage(chatId, 
                `⚠️ *TIDAK BISA DIHAPUS!*\n\n` +
                `Sub-topik "${subtopik.nama}" masih memiliki ${kisiCount.c} kisi-kisi.\n\n` +
                `💡 Hapus kisi-kisi terlebih dahulu.`
            );
            return true;
        }
        
        await db.prepare(`DELETE FROM sub_topik WHERE id = ?`).bind(subtopikId).run();
        
        await smartMessage(chatId, 
            `✅ *SUB-TOPIK BERHASIL DIHAPUS!*\n\n` +
            `🆔 ID: \`${subtopikId}\`\n` +
            `📋 Nama: ${subtopik.nama}`
        );
        
    } catch (e) {
        console.error('delete_subtopik error:', e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
    }
    return true;
}

