// ============================================================
// 🆕 FASE 3: BACKUP & ROLLBACK
// Lokasi: handleCommand(), sebelum FASE 2
// ============================================================

// ============================================================
// /backup_db — Backup database ke JSON
// ============================================================
if (cmd === '/backup_db' || cmd === 'backup_db') {
    if (!isAdmin(userId)) { await smartMessage(chatId, "⛔ Akses admin diperlukan."); return true; }
    try {
        await smartMessage(chatId, '⏳ *Membuat backup D1 portable...*\n\nFormat: JSONL + GZIP\nData diproses per chunk agar tidak dibatasi Excel.');
        const result = await sendPortableD1Backup(chatId, db, Object.keys(ALL_SCHEMAS), userId);
        await smartMessage(chatId, `✅ *BACKUP D1 SELESAI*\n\n🆔 ${result.backupId}\n📋 Tabel: ${result.tableCount}\n📊 Rows: ${result.totalRows}\n📦 Parts: ${result.totalParts}\n\n💡 Semua part menggunakan format yang sama dan dapat di-upload kembali dengan /restore_db.`);
    } catch (e) {
        console.error('portable backup_db error:', e);
        await smartMessage(chatId, `❌ Backup D1 gagal: ${e.message}`);
    }
    return true;
}

if (cmd === '/backup_db_schema' || cmd === 'backup_db_schema') {
    if (!isAdmin(userId)) { await smartMessage(chatId, "⛔ Akses admin diperlukan."); return true; }
    try {
        const out = {format:'D1_PORTABLE_SCHEMA_V1',created_at:new Date().toISOString(),tables:{}};
        for (const table of Object.keys(ALL_SCHEMAS)) {
            out.tables[table] = {schema:ALL_SCHEMAS[table], columns:await getTableColumnsPortable(db,table)};
        }
        const sent = await sendFileToTelegram(chatId,new TextEncoder().encode(JSON.stringify(out,null,2)),`d1_schema_${Date.now()}.json`,'📐 D1 schema backup');
        if (!sent.success) await smartMessage(chatId,`❌ Gagal kirim schema: ${sent.error}`);
    } catch(e) { await smartMessage(chatId,`❌ Schema backup gagal: ${e.message}`); }
    return true;
}

if (cmd === '/restore_db' || cmd === 'restore_db') {
    if (!isAdmin(userId)) { await smartMessage(chatId, '⛔ Akses admin diperlukan.'); return true; }
    const session = await getSession(env,userId);
    session.portableRestore = { armed:true, backupId:null, restoredTables:[], parts:0, startedAt:new Date().toISOString() };
    session.pendingPortableRestore = null;
    session.uploadingSoal = false;
    await saveSession(env,userId,session);
    await smartMessage(chatId,
        '📥 *RESTORE D1 PORTABLE AKTIF*\n\n' +
        'Silakan upload file `*.jsonl.gz` yang dibuat oleh `/backup_db`.\n\n' +
        '⚠️ Setiap tabel akan diganti saat part pertamanya dikonfirmasi.\n' +
        '⚠️ Upload semua part dari backup yang sama.\n\n' +
        'Gunakan /restore_db_cancel untuk membatalkan.'
    );
    return true;
}

if (cmd === '/restore_db_cancel' || cmd === 'restore_db_cancel') {
    const session = await getSession(env,userId); session.portableRestore=null; session.pendingPortableRestore=null; await saveSession(env,userId,session);
    await smartMessage(chatId,'❌ Mode restore D1 dibatalkan.'); return true;
}

