// ============================================================
// 🆕 FASE 2: JENJANG MANAGEMENT COMMANDS
// Lokasi: handleCommand(), sebelum /reset_database
// ============================================================

// ============================================================
// /jenjang_list — Lihat semua jenjang
// ============================================================
if (cmd === '/jenjang_list' || cmd === 'jenjang_list') {
    if (!isAdmin(userId)) {
        await smartMessage(chatId, "⛔ Akses admin diperlukan.");
        return true;
    }
    
    try {
        const jenjangList = await db.prepare(`
            SELECT * FROM jenjang 
            WHERE is_active = 1
            ORDER BY jenis, urutan
        `).all();
        
        if (!jenjangList.results || jenjangList.results.length === 0) {
            await smartMessage(chatId, 
                `📭 *Belum ada Jenjang*\n\n` +
                `💡 Tambah jenjang dengan:\n` +
                `\`/jenjang_add [id] [nama] [jenis]\`\n\n` +
                `Atau jalankan reset database:\n` +
                `\`/reset_database\``
            );
            return true;
        }
        
        // Group by jenis
        const byJenis = {
            'pendidikan': [],
            'pekerjaan': [],
            'keterampilan': []
        };
        
        for (const j of jenjangList.results) {
            if (!byJenis[j.jenis]) byJenis[j.jenis] = [];
            byJenis[j.jenis].push(j);
        }
        
        let msg = `🏫 *DAFTAR JENJANG*\n`;
        msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
        msg += `📊 Total: ${jenjangList.results.length} jenjang\n\n`;
        
        const jenisLabels = {
            'pendidikan': '🎓 PENDIDIKAN',
            'pekerjaan': '💼 PEKERJAAN',
            'keterampilan': '🛠️ KETERAMPILAN'
        };
        
        for (const [jenis, items] of Object.entries(byJenis)) {
            if (items.length === 0) continue;
            
            msg += `*${jenisLabels[jenis] || jenis.toUpperCase()}*\n`;
            for (const j of items) {
                msg += `${j.icon || '📌'} *${j.nama}* \`[${j.id}]\`\n`;
                if (j.deskripsi) msg += `   📝 ${j.deskripsi}\n`;
            }
            msg += `\n`;
        }
        
        msg += `${DIVIDER}\n`;                    // ← PAKAI const DIVIDER
        msg += `💡 *Kelola:* /jenjang_add, /jenjang_edit, /jenjang_delete`;
        
        const keyboard = [
            [{ text: "➕ Tambah Jenjang", callback_data: "jenjang_add_menu" }],
            [{ text: "✏️ Edit Jenjang", callback_data: "jenjang_edit_menu" }],
            [{ text: "🗑️ Hapus Jenjang", callback_data: "jenjang_delete_menu" }],
            [{ text: "🔄 Refresh", callback_data: "jenjang_list_refresh" }],
            [{ text: "🔙 Kembali", callback_data: "menu_master" }]
        ];
        
        if (msg.length > 4000) {
            const parts = msg.match(/[\s\S]{1,4000}/g) || [];
            for (let i = 0; i < parts.length; i++) {
                if (i === parts.length - 1) {
                    await sendInlineKeyboard(chatId, parts[i], keyboard);
                } else {
                    await smartMessage(chatId, parts[i]);
                }
            }
        } else {
            await sendInlineKeyboard(chatId, msg, keyboard);
        }
        
    } catch (e) {
        console.error('jenjang_list error:', e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
    }
    return true;
}

