// ============================================================
// /jenjang_delete — Hapus jenjang
// ============================================================
if (cmd === '/jenjang_delete' || cmd === 'jenjang_delete') {
    if (!isAdmin(userId)) {
        await smartMessage(chatId, "⛔ Akses admin diperlukan.");
        return true;
    }
    
    const jenjangList = await db.prepare(`
        SELECT j.id, j.nama, 
            (SELECT COUNT(*) FROM topik_jenjang WHERE jenjang_id = j.id) as total_topik
        FROM jenjang j
        WHERE j.is_active = 1
        ORDER BY j.jenis, j.urutan
    `).all();
    
    if (!jenjangList.results || jenjangList.results.length === 0) {
        await smartMessage(chatId, `📭 Belum ada jenjang.`);
        return true;
    }
    
    let msg = `🗑️ *HAPUS JENJANG*\n`;
    msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
    msg += `⚠️ Jenjang yang masih dipakai topik tidak bisa dihapus.\n\n`;
    msg += `Pilih jenjang:\n\n`;
    
    const keyboard = [];
    for (const j of jenjangList.results) {
        const warn = j.total_topik > 0 ? ` ⚠️ (${j.total_topik} topik)` : '';
        keyboard.push([{
            text: `${j.id} — ${j.nama}${warn}`,
            callback_data: `jenjang_delete_select_${j.id}`
        }]);
    }
    keyboard.push([{ text: "🔙 Kembali", callback_data: "cmd_jenjang_list" }]);
    
    await sendInlineKeyboard(chatId, msg, keyboard);
    return true;
}


