// ============================================================
// 🆕 FASE 1: /cek_tabel — CEK STRUKTUR TABEL
// ============================================================

if (cmd === '/cek_tabel' || cmd === 'cek_tabel') {
    if (!isAdmin(userId)) {
        await smartMessage(chatId, "⛔ Anda tidak memiliki akses admin.");
        return true;
    }
    
    const tableName = args[0] || null;
    
    if (!tableName) {
        // Tampilkan semua tabel
        const tables = await db.prepare(`
            SELECT name FROM sqlite_master 
            WHERE type='table' 
            AND name NOT LIKE 'sqlite_%'
            AND name NOT LIKE '_%'
            ORDER BY name
        `).all();
        
        let msg = `📊 *DAFTAR TABEL DATABASE*\n\n`;
        msg += `Total: ${tables.results?.length || 0} tabel\n\n`;
        
        for (const t of tables.results || []) {
            const count = await db.prepare(`SELECT COUNT(*) as c FROM "${t.name}"`).first();
            msg += `📁 \`${t.name}\` — ${count?.c || 0} baris\n`;
        }
        
        msg += `\n💡 Cek struktur: \`/cek_tabel [nama_tabel]\``;
        
        if (msg.length > 4000) {
            const parts = msg.match(/[\s\S]{1,4000}/g) || [];
            for (const part of parts) {
                await smartMessage(chatId, part);
            }
        } else {
            await smartMessage(chatId, msg);
        }
        return true;
    }
    
    // Detail tabel
    try {
        const info = await db.prepare(`PRAGMA table_info("${tableName}")`).all();
        
        if (!info.results || info.results.length === 0) {
            await smartMessage(chatId, `❌ Tabel \`${tableName}\` tidak ditemukan.`);
            return true;
        }
        
        const count = await db.prepare(`SELECT COUNT(*) as c FROM "${tableName}"`).first();
        
        let msg = `📊 *STRUKTUR TABEL: ${tableName}*\n\n`;
        msg += `📈 Total baris: ${count?.c || 0}\n`;
        msg += `📋 Total kolom: ${info.results.length}\n\n`;
        msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
        
        for (const col of info.results) {
            const pk = col.pk ? ' 🔑' : '';
            const notNull = col.notnull ? ' ⚠️' : '';
            msg += `📌 *${col.name}*${pk}${notNull}\n`;
            msg += `   Type: \`${col.type || 'TEXT'}\`\n`;
            if (col.dflt_value !== null && col.dflt_value !== undefined) {
                msg += `   Default: \`${col.dflt_value}\`\n`;
            }
            msg += `\n`;
        }
        
        msg += `🔑 = Primary Key | ⚠️ = Wajib diisi`;
        
        if (msg.length > 4000) {
            const parts = msg.match(/[\s\S]{1,4000}/g) || [];
            for (const part of parts) {
                await smartMessage(chatId, part);
            }
        } else {
            await smartMessage(chatId, msg);
        }
        
    } catch (e) {
        await smartMessage(chatId, `❌ Error: ${e.message}`);
    }
    return true;
}

// ============================================================
