// ============================================================
// PATCH 8: /materi_versions M001 — Lihat daftar versi
// ============================================================
if (cmd === '/materi_versions' || cmd === 'materi_versions') {
    if (args.length === 0) {
        await smartMessage(chatId, 
            `📚 *DAFTAR VERSI MATERI*\n\n` +
            `Gunakan: \`/materi_versions [ID Materi]\`\n\n` +
            `Contoh: \`/materi_versions M001\`\n\n` +
            `💡 Lihat ID materi di /materi_list`
        );
        return true;
    }
    
    const materiId = args[0].toUpperCase();
    
    try {
        const materi = await db.prepare(`SELECT id, judul FROM materi WHERE id = ?`)
            .bind(materiId).first();
        
        if (!materi) {
            await smartMessage(chatId, `❌ Materi \`${materiId}\` tidak ditemukan.`);
            return true;
        }
        
        const versions = await getMateriVersions(db, materiId);
        
        // Format pesan
        let msg = `📚 *${materi.judul}*\n\n`;
        msg += formatVersiList(versions, materiId);
        
        // Keyboard
        const keyboard = [];
        
        if (versions.length > 0) {
            // Tombol lihat versi terbaru & teraktif
            const activeVersion = versions.find(v => v.is_active === 1);
            const latestVersion = versions[0];
            
            if (latestVersion) {
                keyboard.push([
                    { text: `👁️ Lihat Terbaru (v${latestVersion.versi})`, 
                      callback_data: `version_view_${materiId}_${latestVersion.versi}` }
                ]);
            }
            
            if (activeVersion && (!latestVersion || activeVersion.versi !== latestVersion.versi)) {
                keyboard.push([
                    { text: `🟢 Lihat Aktif (v${activeVersion.versi})`, 
                      callback_data: `version_view_${materiId}_${activeVersion.versi}` }
                ]);
            }
            
            // Tombol diff jika ada >= 2 versi
            if (versions.length >= 2) {
                keyboard.push([
                    { text: "📊 Bandingkan Versi", 
                      callback_data: `version_diff_menu_${materiId}` }
                ]);
            }
            
            // Tombol merge jika ada >= 2 versi
            if (versions.length >= 2) {
                keyboard.push([
                    { text: "🔗 Merge Versi", 
                      callback_data: `version_merge_menu_${materiId}` }
                ]);
            }
        }
        
        keyboard.push([
            { text: "⋯ Lainnya", callback_data: `materi_version_more_${materiId}` }
        ]);
        keyboard.push([
            { text: "🔙 Kembali ke Materi", callback_data: `materi_view_${materiId}` }
        ]);
        
        if (msg.length > 4000) {
            const parts = msg.match(/[\s\S]{1,4000}/g) || [];
            for (let i = 0; i < parts.length; i++) {
                if (i === parts.length - 1) {
                    await sendInlineKeyboard(chatId, parts[i], keyboard);
                } else {
                    await smartMessage(chatId, parts[i]);
                }
            }
        } else {
            await sendInlineKeyboard(chatId, msg, keyboard);
        }
        
    } catch (e) {
        console.error('materi_versions error:', e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
    }
    return true;
}

// ============================================================
// PATCH 8: /materi_version_view M001 3 — Lihat versi tertentu
// ============================================================
if (cmd === '/materi_version_view' || cmd === 'materi_version_view') {
    if (args.length < 2) {
        await smartMessage(chatId, 
            `📖 *LIHAT VERSI MATERI*\n\n` +
            `Gunakan: \`/materi_version_view [ID Materi] [Versi]\`\n\n` +
            `Contoh: \`/materi_version_view M001 3\``
        );
        return true;
    }
    
    const materiId = args[0].toUpperCase();
    const versi = parseInt(args[1]);
    
    if (isNaN(versi)) {
        await smartMessage(chatId, `❌ Versi harus berupa angka.`);
        return true;
    }
    
    try {
        const version = await getMateriVersion(db, materiId, versi);
        
        if (!version) {
            await smartMessage(chatId, `❌ Versi ${versi} tidak ditemukan untuk materi \`${materiId}\`.`);
            return true;
        }
        
        // Info versi
        let msg = `📖 *VERSI ${versi} — ${materiId}*\n\n`;
        msg += `📝 Judul: ${version.judul || '-'}\n`;
        msg += `📊 ${(version.total_kata || 0).toLocaleString()} kata | ${version.jumlah_tahap || 0} tahap\n`;
        msg += `📌 Status: ${version.status}${version.is_active === 1 ? ' 🟢 AKTIF' : ''}\n`;
        
        if (version.label) msg += `🏷️ Label: ${version.label}\n`;
        if (version.catatan) msg += `📝 Catatan: ${version.catatan}\n`;
        
        if (version.created_at) {
            msg += `📅 Dibuat: ${new Date(version.created_at).toLocaleString('id-ID')}\n`;
        }
        
        // Tahap
        let tahapDipilih = [];
        try { tahapDipilih = JSON.parse(version.tahap_dipilih || '[]'); } catch (e) {}
        
        if (tahapDipilih.length > 0) {
            msg += `\n📚 *Tahap:*\n`;
            for (const tk of tahapDipilih) {
                const t = TAHAP_PEMBELAJARAN[tk];
                if (t) msg += `   ${t.icon} ${tk} — ${t.nama}\n`;
            }
        }
        
        // Preview konten (200 char pertama)
        if (version.konten) {
            msg += `\n📄 *Preview Konten:*\n`;
            msg += `\`\`\`\n${version.konten.substring(0, 200)}${version.konten.length > 200 ? '...' : ''}\n\`\`\``;
        }
        
        // Keyboard
        const keyboard = [];
        
        // Tombol aktifkan versi ini
        if (version.is_active !== 1) {
            keyboard.push([
                { text: `⏪ Rollback ke Versi ${versi}`, 
                  callback_data: `version_rollback_confirm_${materiId}_${versi}` }
            ]);
        }
        
        // Tombol lihat full konten
        keyboard.push([
            { text: "👁️ Lihat Full Konten", 
              callback_data: `version_content_${materiId}_${versi}` }
        ]);
        
        // Tombol hapus
        if (version.is_active !== 1) {
            keyboard.push([
                { text: `🗑️ Hapus Versi ${versi}`, 
                  callback_data: `version_delete_confirm_${materiId}_${versi}` }
            ]);
        }
        
        keyboard.push([
            { text: "🔙 Kembali ke Daftar Versi", 
              callback_data: `materi_versions_${materiId}` }
        ]);
        
        await sendInlineKeyboard(chatId, msg, keyboard);
        
    } catch (e) {
        console.error('materi_version_view error:', e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
    }
    return true;
}

// ============================================================
// PATCH 8: /materi_diff M001 2 3 — Bandingkan 2 versi
// ============================================================
if (cmd === '/materi_diff' || cmd === 'materi_diff') {
    if (args.length < 3) {
        await smartMessage(chatId, 
            `📊 *BANDINGKAN VERSI*\n\n` +
            `Gunakan: \`/materi_diff [ID Materi] [Versi A] [Versi B]\`\n\n` +
            `Contoh: \`/materi_diff M001 1 3\`\n\n` +
            `💡 A = versi lama, B = versi baru`
        );
        return true;
    }
    
    const materiId = args[0].toUpperCase();
    const versiA = parseInt(args[1]);
    const versiB = parseInt(args[2]);
    
    if (isNaN(versiA) || isNaN(versiB)) {
        await smartMessage(chatId, `❌ Versi harus berupa angka.`);
        return true;
    }
    
    try {
        const diff = await compareMateriVersions(db, materiId, versiA, versiB);
        
        if (!diff.success) {
            await smartMessage(chatId, `❌ ${diff.error}`);
            return true;
        }
        
        // Build pesan diff
        let msg = `📊 *PERBANDINGAN VERSI*\n\n`;
        msg += `📖 Materi: \`${materiId}\`\n\n`;
        
        msg += `📌 *Versi A: v${diff.versiA.versi}*\n`;
        msg += `   📊 ${diff.versiA.total_kata.toLocaleString()} kata | ${diff.versiA.jumlah_tahap} tahap\n`;
        if (diff.versiA.label) msg += `   🏷️ ${diff.versiA.label}\n`;
        if (diff.versiA.created_at) {
            msg += `   📅 ${new Date(diff.versiA.created_at).toLocaleDateString('id-ID')}\n`;
        }
        msg += `\n`;
        
        msg += `📌 *Versi B: v${diff.versiB.versi}*\n`;
        msg += `   📊 ${diff.versiB.total_kata.toLocaleString()} kata | ${diff.versiB.jumlah_tahap} tahap\n`;
        if (diff.versiB.label) msg += `   🏷️ ${diff.versiB.label}\n`;
        if (diff.versiB.created_at) {
            msg += `   📅 ${new Date(diff.versiB.created_at).toLocaleDateString('id-ID')}\n`;
        }
        msg += `\n---\n\n`;
        
        // Selisih
        const selisih = diff.diff.selisihKata;
        const selisihIcon = selisih > 0 ? '📈' : selisih < 0 ? '📉' : '➡️';
        const selisihText = selisih > 0 ? `+${selisih}` : `${selisih}`;
        
        msg += `📊 *Ringkasan Perubahan:*\n`;
        msg += `${selisihIcon} Kata: ${selisihText}\n`;
        msg += `📚 Tahap A: ${diff.diff.tahapA} → Tahap B: ${diff.diff.tahapB}\n`;
        msg += `➕ Baris ditambah: ${diff.diff.barisDitambah}\n`;
        msg += `➖ Baris dihapus: ${diff.diff.barisDihapus}\n`;
        msg += `🔄 Konten berubah: ${diff.diff.kontenBerubah ? 'Ya' : 'Tidak'}\n\n`;
        
        // Tahap hanya di A/B
        if (diff.diff.tahapHanyaA.length > 0) {
            msg += `🗑️ *Tahap Hanya di A:*\n`;
            for (const tk of diff.diff.tahapHanyaA) {
                const t = TAHAP_PEMBELAJARAN[tk];
                msg += `   ${t?.icon || '📚'} ${tk} — ${t?.nama || tk}\n`;
            }
            msg += `\n`;
        }
        
        if (diff.diff.tahapHanyaB.length > 0) {
            msg += `🆕 *Tahap Hanya di B:*\n`;
            for (const tk of diff.diff.tahapHanyaB) {
                const t = TAHAP_PEMBELAJARAN[tk];
                msg += `   ${t?.icon || '📚'} ${tk} — ${t?.nama || tk}\n`;
            }
            msg += `\n`;
        }
        
        // Keyboard
        const keyboard = [
            [
                { text: `⏪ Rollback ke v${versiA}`, 
                  callback_data: `version_rollback_confirm_${materiId}_${versiA}` },
                { text: `⏪ Rollback ke v${versiB}`, 
                  callback_data: `version_rollback_confirm_${materiId}_${versiB}` }
            ],
            [
                { text: `👁️ Lihat v${versiA}`, 
                  callback_data: `version_view_${materiId}_${versiA}` },
                { text: `👁️ Lihat v${versiB}`, 
                  callback_data: `version_view_${materiId}_${versiB}` }
            ],
            [
                { text: "🔙 Kembali ke Daftar Versi", 
                  callback_data: `materi_versions_${materiId}` }
            ]
        ];
        
        if (msg.length > 4000) {
            const parts = msg.match(/[\s\S]{1,4000}/g) || [];
            for (let i = 0; i < parts.length; i++) {
                if (i === parts.length - 1) {
                    await sendInlineKeyboard(chatId, parts[i], keyboard);
                } else {
                    await smartMessage(chatId, parts[i]);
                }
            }
        } else {
            await sendInlineKeyboard(chatId, msg, keyboard);
        }
        
    } catch (e) {
        console.error('materi_diff error:', e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
    }
    return true;
}

