// FASE 2 — /statistik_hierarki
// Statistik hierarchy dengan filter opsional: kategoriId, bidangId,
// programId, jenjangId, kelasId, semester.
// ============================================================
if (cmd === '/statistik_hierarki' || cmd === 'statistik_hierarki') {
    try {
        const filters = {};
        for (const arg of args) {
            const m = String(arg).match(/^([^=]+)=(.+)$/);
            if (m) filters[m[1].trim()] = m[2].trim();
        }
        const stats = await getHierarchyStatistics(db, filters);
        if (stats.error) {
            await smartMessage(chatId, `❌ Gagal membaca statistik hierarchy: ${stats.error}`);
            return true;
        }
        let msg = `📊 *STATISTIK HIERARKI*\n${DIVIDER}\n\n`;
        msg += `📂 Kategori: ${stats.kategori.length}\n`;
        msg += `📚 Bidang Studi: ${stats.bidang.length}\n`;
        msg += `🎓 Program Studi: ${stats.program.length}\n`;
        msg += `🏫 Jenjang: ${stats.jenjang.length}\n`;
        msg += `📖 Kelas: ${stats.kelas.length}\n`;
        msg += `📗 Mata Pelajaran: ${stats.mataPelajaran.length}\n`;
        msg += `📘 Mata Kuliah: ${stats.mataKuliah.length}\n`;
        msg += `📑 Topik: ${stats.topik.length}\n`;
        msg += `📝 Soal aktif: ${stats.soal}\n\n`;
        if (stats.mataPelajaran.length) {
            msg += `*Mata Pelajaran*\n`;
            for (const mp of stats.mataPelajaran.slice(0, 20)) {
                msg += `• ${mp.id} — ${mp.nama} | ${mp.jenjang_nama || mp.jenjang_id} | ${mp.total_topik} topik | ${mp.total_soal} soal\n`;
            }
            msg += `\n`;
        }
        if (stats.mataKuliah.length) {
            msg += `*Mata Kuliah*\n`;
            for (const mk of stats.mataKuliah.slice(0, 20)) {
                msg += `• ${mk.id} — ${mk.nama} | Smt ${mk.semester || '-'} | ${mk.total_topik} topik | ${mk.total_soal} soal\n`;
            }
        }
        msg += `\n💡 Filter: kategoriId=K001 bidangId=B001 programId=P001 jenjangId=J001 kelasId=KL001 mataPelajaranId=MP001 mataKuliahId=MK001 semester=3`;
        await smartMessage(chatId, msg);
    } catch (e) {
        logAppError('statistik_hierarki', e, { userId });
        await smartMessage(chatId, `❌ Gagal membaca statistik hierarchy: ${safeErrorMessage(e)}`);
    }
    return true;
}

