// 9. /test_math — Test math renderer
// ============================================================
if (cmd === '/test_math' || cmd === 'test_math') {
    if (!isAdmin(userId)) {
        await smartMessage(chatId, "⛔ Anda tidak memiliki akses admin.");
        return true;
    }
    
    await smartMessage(chatId, '🧪 *TEST MATH RENDERER*\n\nMemproses...');
    
    const testCases = [
        { latex: 'x^3', desc: 'Pangkat sederhana' },
        { latex: 'x^2 + y^2 = z^2', desc: 'Rumus Pythagoras' },
        { latex: 'H_2O', desc: 'Indeks kimia' },
        { latex: '\\sqrt{x}', desc: 'Akar' },
        { latex: '\\frac{a}{b}', desc: 'Pecahan (complex)' },
        { latex: '\\int_0^\\infty e^{-x^2} dx', desc: 'Integral (complex)' },
        { latex: '\\sum_{i=1}^{n} x_i', desc: 'Sigma (complex)' },
        { latex: '\\alpha + \\beta = \\gamma', desc: 'Simbol Yunani' },
        { latex: '\\Delta x \\to 0', desc: 'Limit delta' },
        { latex: 'x^{10}', desc: 'Pangkat multi-digit' }
    ];
    
    let msg = `🧪 *HASIL TEST MATH RENDERER*\n\n`;
    
    for (const test of testCases) {
        const unicode = latexToUnicode(test.latex);
        const isSimple = isSimpleFormula(test.latex);
        const type = isSimple ? '✅ Simple' : '🖼️ Complex';
        const render = isSimple ? unicode : '→ Gambar';
        
        msg += `📌 *${test.desc}*\n`;
        msg += `   Input: \`${test.latex}\`\n`;
        msg += `   ${type}\n`;
        msg += `   Output: ${render}\n\n`;
    }
    
    msg += `\n---\n\n`;
    msg += `📝 *TEST RENDER FULL:*\n\n`;
    msg += `Kirim pesan berikut sebagai test:\n`;
    msg += `\`Rumus Pythagoras: x^2 + y^2 = z^2\`\n\n`;
    msg += `\`Integral: \\int_0^\\infty e^{-x^2} dx = \\frac{\\sqrt{\\pi}}{2}\`\n\n`;
    
    await smartMessage(chatId, msg);
    
    // Test render pesan campuran
    await smartMessage(chatId, '🖼️ *Render Test - Complex Formula:*');
    
    const complexTest = `Integral Gauss: $\\int_{-\\infty}^{\\infty} e^{-x^2} dx = \\sqrt{\\pi}$`;
    await renderMath(chatId, complexTest);
    
    return true;
}

