// ============================================================
// 🆕 FIX CLASSIFICATION - PERBAIKI SOAL DENGAN KLASIFIKASI NULL
// ============================================================

if (cmd === '/fix_classification' || cmd === 'fix_classification') {
    if (!isAdmin(userId)) {
        await smartMessage(chatId, "⛔ Anda tidak memiliki akses admin.");
        return true;
    }
    
    await smartMessage(chatId, '⏳ Mencari soal dengan klasifikasi tidak lengkap...');
    
    let soals;
    try {
        soals = await db.prepare(`
            SELECT id, soal, pilihan_a, pilihan_b, pilihan_c, pilihan_d, pilihan_e,
                   kategori_id, bidang_studi_id, program_studi_id, topik_id,
                   cara_penyajian_id, tipe_isi_id, tahap_pembelajaran_id,
                   lapisan_pembelajaran_id, level_hots, tipe_hots,
                   kompleksitas, tingkat_kesulitan, status_keabsahan
            FROM soal 
            WHERE status = 'AKTIF'
            AND (
                kategori_id IS NULL 
                OR bidang_studi_id IS NULL 
                OR program_studi_id IS NULL 
                OR topik_id IS NULL
                OR cara_penyajian_id IS NULL
                OR tipe_isi_id IS NULL
                OR tahap_pembelajaran_id IS NULL
                OR lapisan_pembelajaran_id IS NULL
                OR level_hots IS NULL
                OR kompleksitas IS NULL
                OR tingkat_kesulitan IS NULL
                OR status_keabsahan IS NULL
            )
            ORDER BY id
            LIMIT 100
        `).all();
    } catch (e) {
        await smartMessage(chatId, `❌ Error query: ${e.message}`);
        return true;
    }
    
    if (!soals.results || soals.results.length === 0) {
        await smartMessage(chatId, 
            `✅ *SEMUA SOAL SUDAH LENGKAP!*\n\n` +
            `Tidak ada soal dengan klasifikasi NULL.`
        );
        return true;
    }
    
    const totalSoal = soals.results.length;
    await smartMessage(chatId, 
        `📊 Ditemukan *${totalSoal} soal* dengan klasifikasi tidak lengkap.\n\n` +
        `⏳ Memproses... (mohon tunggu)`
    );
    
    let fixedCount = 0;
    let failedCount = 0;
    let skippedCount = 0;
    const errors = [];
    const fixedDetails = [];
    
    // Progress notification setiap 10 soal
    let lastProgress = 0;
    
    for (let i = 0; i < soals.results.length; i++) {
        const soal = soals.results[i];
        
        try {
            const pilihanJawaban = 
                `A. ${soal.pilihan_a || ''}\n` +
                `B. ${soal.pilihan_b || ''}\n` +
                `C. ${soal.pilihan_c || ''}\n` +
                `D. ${soal.pilihan_d || ''}\n` +
                `E. ${soal.pilihan_e || ''}`;
            
            // Auto-classify
            const classification = await autoClassifyComplete(soal.soal, pilihanJawaban, db);
            const masterIds = classification.masterIds || {};
            
            // Skip jika tidak ada perubahan berarti
            const nothingToFix = 
                (!masterIds.kategoriId || soal.kategori_id) &&
                (!masterIds.penyajianId || soal.cara_penyajian_id) &&
                (!masterIds.tipeIsiId || soal.tipe_isi_id);
            
            if (nothingToFix && !masterIds.fallbackItems?.length && !masterIds.createdItems?.length) {
                skippedCount++;
                continue;
            }
            
            // Build UPDATE dengan COALESCE (hanya isi yang NULL)
            await db.prepare(`
                UPDATE soal SET
                    kategori_id = COALESCE(kategori_id, ?),
                    bidang_studi_id = COALESCE(bidang_studi_id, ?),
                    program_studi_id = COALESCE(program_studi_id, ?),
                    topik_id = COALESCE(topik_id, ?),
                    sub_topik_id = COALESCE(sub_topik_id, ?),
                    kisi_kisi_id = COALESCE(kisi_kisi_id, ?),
                    kemampuan_id = COALESCE(kemampuan_id, ?),
                    sub_kemampuan_id = COALESCE(sub_kemampuan_id, ?),
                    cara_penyajian_id = COALESCE(cara_penyajian_id, ?),
                    tipe_isi_id = COALESCE(tipe_isi_id, ?),
                    tahap_pembelajaran_id = COALESCE(tahap_pembelajaran_id, ?),
                    lapisan_pembelajaran_id = COALESCE(lapisan_pembelajaran_id, ?),
                    sumber_belajar_id = COALESCE(sumber_belajar_id, ?),
                    level_hots = NULL,
                    tipe_hots = COALESCE(tipe_hots, ?),
                    kompleksitas = COALESCE(kompleksitas, ?),
                    tingkat_kesulitan = COALESCE(tingkat_kesulitan, ?),
                    status_keabsahan = COALESCE(status_keabsahan, ?)
                WHERE id = ?
            `).bind(
                masterIds.kategoriId,
                masterIds.bidangId,
                masterIds.programId,
                masterIds.topikId,
                masterIds.subtopikId,
                masterIds.kisiId,
                masterIds.kemampuanId,
                masterIds.subKemampuanId,
                masterIds.penyajianId,
                masterIds.tipeIsiId,
                masterIds.tahapId,
                masterIds.lapisanId,
                masterIds.sumberId,
                classification.prosesKognitif || classification.tipeHots || getProsesKognitif(null, classification.levelHots) || 'LOTS',
                getKompleksitasFromTahap(classification.tahap || 'T1'),
                getDefaultDifficulty(classification.tingkatKesulitan),
                classification.keabsahan || 'mandiri',
                soal.id
            ).run();
            
            fixedCount++;
            fixedDetails.push(`${soal.id} → ${classification.kategori || '-'} | ${getStoredCognitive(classification)}`);
            
        } catch (e) {
            failedCount++;
            errors.push(`${soal.id}: ${e.message}`);
        }
        
        // Progress notification setiap 10 soal
        if (i + 1 - lastProgress >= 10) {
            lastProgress = i + 1;
            await smartMessage(chatId, 
                `⏳ Progress: ${i + 1}/${totalSoal}\n` +
                `✅ Berhasil: ${fixedCount} | ⏭️ Skip: ${skippedCount} | ❌ Gagal: ${failedCount}`
            );
        }
        
        // Delay kecil untuk menghindari rate limit AI
        if (i < soals.results.length - 1) {
            await new Promise(resolve => setTimeout(resolve, 200));
        }
    }
    
    // ============================================================
    // LAPORAN AKHIR
    // ============================================================
    let report = `✅ *PERBAIKAN KLASIFIKASI SELESAI*\n\n`;
    report += `📊 *Statistik:*\n`;
    report += `📋 Total diperiksa: ${totalSoal}\n`;
    report += `✅ Berhasil diperbaiki: ${fixedCount}\n`;
    report += `⏭️ Skip (tidak perlu): ${skippedCount}\n`;
    report += `❌ Gagal: ${failedCount}\n\n`;
    
    if (fixedDetails.length > 0) {
        report += `📋 *Detail perbaikan (10 pertama):*\n`;
        fixedDetails.slice(0, 10).forEach(d => {
            report += `   • ${d}\n`;
        });
        if (fixedDetails.length > 10) {
            report += `   ... dan ${fixedDetails.length - 10} lainnya\n`;
        }
        report += `\n`;
    }
    
    if (errors.length > 0) {
        report += `⚠️ *Error (5 pertama):*\n`;
        errors.slice(0, 5).forEach(e => {
            report += `   • ${e}\n`;
        });
        if (errors.length > 5) {
            report += `   ... dan ${errors.length - 5} error lainnya\n`;
        }
    }
    
    report += `\n💡 *Jalankan /fix_classification lagi jika masih ada soal yang belum lengkap.*`;
    
    await smartMessage(chatId, report);
    return true;
}

// ============================================================
// 🆕 STATISTIK FALLBACK - COMMAND
// ============================================================

if (cmd === '/fallback_stats' || cmd === 'fallback_stats') {
    if (!isAdmin(userId)) {
        await smartMessage(chatId, "⛔ Anda tidak memiliki akses admin.");
        return true;
    }
    
    // Ambil stats dari database
    let dbStats;
    try {
        dbStats = await db.prepare(`
            SELECT 
                COUNT(*) as total,
                SUM(CASE WHEN kategori_id IS NULL THEN 1 ELSE 0 END) as null_kategori,
                SUM(CASE WHEN cara_penyajian_id IS NULL THEN 1 ELSE 0 END) as null_penyajian,
                SUM(CASE WHEN tipe_isi_id IS NULL THEN 1 ELSE 0 END) as null_tipe_isi,
                SUM(CASE WHEN tahap_pembelajaran_id IS NULL THEN 1 ELSE 0 END) as null_tahap,
                SUM(CASE WHEN lapisan_pembelajaran_id IS NULL THEN 1 ELSE 0 END) as null_lapisan,
                SUM(CASE WHEN level_hots IS NULL THEN 1 ELSE 0 END) as null_level_hots,
                SUM(CASE WHEN status_keabsahan IS NULL THEN 1 ELSE 0 END) as null_keabsahan
            FROM soal WHERE status = 'AKTIF'
        `).first();
    } catch (e) {
        dbStats = null;
    }
    
    let msg = `📊 *STATISTIK FALLBACK & KLASIFIKASI*\n\n`;
    
    msg += `🔄 *Session Statistics:*\n`;
    msg += `📋 Total soal diproses: ${fallbackStats.totalSoal}\n`;
    msg += `🆕 Auto-created: ${fallbackStats.totalAutoCreated}\n`;
    msg += `⚠️ Fallback digunakan: ${fallbackStats.totalFallback}\n`;
    msg += `❌ Missing: ${fallbackStats.totalMissing}\n\n`;
    
    if (dbStats) {
        msg += `💾 *Database Statistics:*\n`;
        msg += `📋 Total soal aktif: ${dbStats.total || 0}\n\n`;
        msg += `⚠️ *Field NULL:*\n`;
        msg += `   • Kategori: ${dbStats.null_kategori || 0}\n`;
        msg += `   • Cara Penyajian: ${dbStats.null_penyajian || 0}\n`;
        msg += `   • Tipe Isi: ${dbStats.null_tipe_isi || 0}\n`;
        msg += `   • Tahap: ${dbStats.null_tahap || 0}\n`;
        msg += `   • Lapisan: ${dbStats.null_lapisan || 0}\n`;
        msg += `   • Proses Kognitif: ${dbStats.null_level_hots || 0}\n`;
        msg += `   • Keabsahan: ${dbStats.null_keabsahan || 0}\n\n`;
        
        const totalNull = 
            (dbStats.null_kategori || 0) + 
            (dbStats.null_penyajian || 0) + 
            (dbStats.null_tipe_isi || 0) + 
            (dbStats.null_tahap || 0) + 
            (dbStats.null_lapisan || 0);
        
        if (totalNull > 0) {
            msg += `💡 *Jalankan /fix_classification untuk memperbaiki ${totalNull} field NULL.*`;
        } else {
            msg += `✅ *Semua soal sudah memiliki klasifikasi lengkap!*`;
        }
    }
    
    await smartMessage(chatId, msg);
    return true;
}

