// ============================================================
if (cmd === '/test_parser' || cmd === 'test_parser') {
    if (!isAdmin(userId)) {
        await smartMessage(chatId, "⛔ Anda tidak memiliki akses admin.");
        return true;
    }
    
    // List test case
    const testCases = [
        { input: 'K001', opts: { mode: 'delete', prefix: 'K' }, expect: 'single' },
        { input: 'K001, K002, K003', opts: { mode: 'delete', prefix: 'K' }, expect: 'koma' },
        { input: 'K001; K002; K003', opts: { mode: 'delete', prefix: 'K' }, expect: 'semicolon' },
        { input: 'K001 | K002 | K003', opts: { mode: 'delete', prefix: 'K' }, expect: 'pipe' },
        { input: 'K001\nK002\nK003', opts: { mode: 'delete', prefix: 'K' }, expect: 'newline' },
        { input: 'K001-K005', opts: { mode: 'delete', prefix: 'K' }, expect: 'range' },
        { input: 'K001, K003-K005, K007', opts: { mode: 'delete', prefix: 'K' }, expect: 'campuran' },
        { input: '001', opts: { mode: 'delete', prefix: 'K' }, expect: 'auto-prefix' },
        { input: 'ID: K001\nID: K002', opts: { mode: 'delete', prefix: 'K' }, expect: 'keyvalue' },
        { input: 'K001\n---\nK002', opts: { mode: 'delete', prefix: 'K' }, expect: 'multi-arrow' },
        { input: 'K001; Nama Baru; Deskripsi', opts: { mode: 'edit', prefix: 'K' }, expect: 'edit-sep' },
        { input: 'K001\nNama Baru\nDeskripsi', opts: { mode: 'edit', prefix: 'K' }, expect: 'edit-line' },
        { input: 'ID: K001\nNama: Nama Baru\nDeskripsi: Isi', opts: { mode: 'edit', prefix: 'K' }, expect: 'edit-kv' },
        { input: 'Fisika; Ilmu alam', opts: { mode: 'add' }, expect: 'add-sep' },
        { input: 'Fisika\nIlmu alam', opts: { mode: 'add' }, expect: 'add-line' },
        { input: 'Nama: Fisika\nDeskripsi: Ilmu alam', opts: { mode: 'add' }, expect: 'add-kv' }
    ];
    
    let msg = `🧪 *TEST PARSER UNIVERSAL*\n${DIVIDER}\n\n`;
    msg += `📊 Total test: ${testCases.length}\n\n`;
    msg += `━━━━━━━━━━━━━━━━━━━\n\n`;
    
    let passCount = 0;
    let failCount = 0;
    
    for (let i = 0; i < testCases.length; i++) {
        const tc = testCases[i];
        const result = parseInputUniversal(tc.input, tc.opts);
        
        const status = result.success && result.items && result.items.length > 0 ? '✅' : '❌';
        if (status === '✅') passCount++;
        else failCount++;
        
        msg += `${status} *Test ${i + 1}* (${tc.expect})\n`;
        msg += `📝 Input: \`${tc.input.replace(/\n/g, '\\n')}\`\n`;
        msg += `🎯 Mode: ${tc.opts.mode}\n`;
        
        if (result.success && result.items) {
            msg += `✅ Items: ${result.items.length}\n`;
            result.items.slice(0, 3).forEach((item, j) => {
                msg += `   ${j + 1}. ${JSON.stringify(item)}\n`;
            });
            if (result.items.length > 3) {
                msg += `   ... dan ${result.items.length - 3} lainnya\n`;
            }
        } else {
            msg += `❌ Error: ${result.error}\n`;
        }
        
        if (result.warnings && result.warnings.length > 0) {
            msg += `⚠️ Warning: ${result.warnings[0]}\n`;
        }
        
        msg += `\n`;
    }
    
    msg += `━━━━━━━━━━━━━━━━━━━\n\n`;
    msg += `📊 *HASIL:*\n`;
    msg += `✅ Pass: ${passCount}/${testCases.length}\n`;
    msg += `❌ Fail: ${failCount}/${testCases.length}\n\n`;
    
    if (failCount === 0) {
        msg += `🎉 *SEMUA TEST PASS!*\n\nParser universal siap dipakai.`;
    } else {
        msg += `⚠️ Ada ${failCount} test yang fail.\nSilakan lapor ke saya.`;
    }
    
    // Split kalau terlalu panjang
    if (msg.length > 4000) {
        const parts = msg.match(/[\s\S]{1,4000}/g) || [];
        for (const part of parts) {
            await smartMessage(chatId, part);
        }
    } else {
        await smartMessage(chatId, msg);
    }
    
    return true;
}

// ============================================================
// RE-CLASSIFY SOAL - COMMAND (Patch #17)
// Fix BUG-112: Pakai parseInputUniversal
// ============================================================

if (cmd === '/reclassify' || cmd === '/reclassify_soal') {
    if (!isAdmin(userId)) {
        await smartMessage(chatId, "⛔ Anda tidak memiliki akses admin.");
        return true;
    }
    
    if (args.length === 0) {
        await smartMessage(chatId, 
            `🔄 *RE-CLASSIFY SOAL*\n\n` +
            `Gunakan: /reclassify [ID Soal]\n\n` +
            `Contoh:\n` +
            `/reclassify Q001\n` +
            `/reclassify Q001, Q003, Q005\n` +
            `/reclassify Q001-Q005\n\n` +
            `💡 Akan mengupdate klasifikasi berdasarkan master data`
        );
        return true;
    }
    
    const input = args.join(' ');
    
    // FIX BUG-112: Pakai parseInputUniversal
    const parsed = parseInputUniversal(input, { 
        mode: 'delete', 
        entity: 'soal',
        prefix: 'Q' 
    });
    
    if (!parsed.success || !parsed.items || parsed.items.length === 0) {
        await smartMessage(chatId, `❌ ${parsed.error || 'Tidak ada soal yang ditemukan.'}`);
        return true;
    }
    
    // Query manual untuk ambil data soal
    const items = [];
    for (const item of parsed.items) {
        try {
            const row = await db.prepare(`SELECT * FROM soal WHERE id = ?`).bind(item.id).first();
            if (row) items.push(row);
        } catch (e) {
            console.warn(`⚠️ Gagal ambil soal ${item.id}:`, e.message);
        }
    }
    
    if (items.length === 0) {
        await smartMessage(chatId, '❌ Tidak ada soal yang ditemukan.');
        return true;
    }
    
    await smartMessage(chatId, `⏳ Re-klasifikasi ${items.length} soal...`);
    
    let successCount = 0;
    let errorCount = 0;
    let errors = [];
    
    for (const item of items) {
        const result = await reclassifySoal(db, item.id, userId);
        if (result.success) {
            successCount++;
        } else {
            errorCount++;
            errors.push(`${item.id}: ${result.error}`);
        }
    }
    
    let response = `🔄 *RE-CLASSIFY SELESAI*\n\n`;
    response += `✅ Berhasil: ${successCount} soal\n`;
    response += `❌ Gagal: ${errorCount} soal\n`;
    if (errors.length > 0) {
        response += `\n⚠️ Error:\n${errors.slice(0, 5).map(e => `- ${e}`).join('\n')}`;
    }
    
    await smartMessage(chatId, response);
    return true;
}

