// 📍 TEMPAT 6: TAMBAHKAN DI DALAM FUNGSI handleCommand()
// Cari: async function handleCommand(env, chatId, userId, text) {
// Letakkan setelah command lain, sebelum return false
// ============================================================

// ============================================================
// FILTER BERDASARKAN KOMPLEKSITAS
// ============================================================
if (cmd === '/filter_kompleksitas' || cmd === 'filter_kompleksitas') {
    if (args.length === 0) {
        await smartMessage(chatId, 
            `🔍 *FILTER SOAL BERDASARKAN KOMPLEKSITAS*\n\n` +
            `Gunakan: /filter_kompleksitas [sederhana|menengah|kompleks]\n\n` +
            `Contoh:\n` +
            `/filter_kompleksitas sederhana\n` +
            `/filter_kompleksitas menengah\n` +
            `/filter_kompleksitas kompleks\n\n` +
            `📊 *Mapping Tahap:*\n` +
            `🟢 Sederhana: T1-T3 (Teori, Pemahaman, Rumus)\n` +
            `🟡 Menengah: T4-T6 (Penerapan, Kombinasi, Analisis)\n` +
            `🔴 Kompleks: T7-T9 (Studi Kasus, HOTS, Komprehensif)`
        );
        return true;
    }
    
    const kompleksitas = args[0].toLowerCase();
    if (!['sederhana', 'menengah', 'kompleks'].includes(kompleksitas)) {
        await smartMessage(chatId, '❌ Pilihan: sederhana, menengah, atau kompleks');
        return true;
    }
    
    await smartMessage(chatId, `⏳ Mencari soal dengan kompleksitas "${kompleksitas}"...`);
    const soals = await getSoalByKompleksitas(db, kompleksitas, 20);
    
    if (soals.length === 0) {
        await smartMessage(chatId, `❌ Tidak ada soal dengan kompleksitas "${kompleksitas}"`);
        return true;
    }
    
    let msg = `🔍 *SOAL KOMPLEKSITAS: ${kompleksitas.toUpperCase()}*\n\n`;
    msg += `📊 Total: ${soals.length} soal\n\n`;
    
    soals.slice(0, 10).forEach((s, i) => {
        msg += `${i+1}. ${formatSoalWithMetrics(s)}\n`;
        msg += `---\n`;
    });
    
    if (soals.length > 10) {
        msg += `\n... dan ${soals.length - 10} soal lainnya`;
    }
    
    if (msg.length > 4000) {
        const parts = msg.match(/.{1,4000}/g) || [];
        for (const part of parts) {
            await smartMessage(chatId, part);
        }
    } else {
        await smartMessage(chatId, msg);
    }
    return true;
}

// ============================================================
// FILTER BERDASARKAN TINGKAT KESULITAN
// ============================================================
if (cmd === '/filter_tingkat' || cmd === 'filter_tingkat') {
    if (args.length === 0) {
        await smartMessage(chatId, 
            `🎯 *FILTER SOAL BERDASARKAN TINGKAT KESULITAN*\n\n` +
            `Gunakan: /filter_tingkat [mudah|sedang|sulit]\n\n` +
            `Contoh:\n` +
            `/filter_tingkat mudah\n` +
            `/filter_tingkat sedang\n` +
            `/filter_tingkat sulit\n\n` +
            `📊 *Mapping HOTS:*\n` +
            `🟢 Mudah: L1-L2 (LOTS)\n` +
            `🟡 Sedang: L3-L4 (MOTS)\n` +
            `🔴 Sulit: L5-L6 (HOTS)`
        );
        return true;
    }
    
    const tingkat = args[0].toLowerCase();
    if (!['mudah', 'sedang', 'sulit'].includes(tingkat)) {
        await smartMessage(chatId, '❌ Pilihan: mudah, sedang, atau sulit');
        return true;
    }
    
    await smartMessage(chatId, `⏳ Mencari soal dengan tingkat "${tingkat}"...`);
    const soals = await getSoalByTingkatKesulitan(db, tingkat, 20);
    
    if (soals.length === 0) {
        await smartMessage(chatId, `❌ Tidak ada soal dengan tingkat "${tingkat}"`);
        return true;
    }
    
    let msg = `🎯 *SOAL TINGKAT: ${tingkat.toUpperCase()}*\n\n`;
    msg += `📊 Total: ${soals.length} soal\n\n`;
    
    soals.slice(0, 10).forEach((s, i) => {
        msg += `${i+1}. ${formatSoalWithMetrics(s)}\n`;
        msg += `---\n`;
    });
    
    if (soals.length > 10) {
        msg += `\n... dan ${soals.length - 10} soal lainnya`;
    }
    
    if (msg.length > 4000) {
        const parts = msg.match(/.{1,4000}/g) || [];
        for (const part of parts) {
            await smartMessage(chatId, part);
        }
    } else {
        await smartMessage(chatId, msg);
    }
    return true;
}

// ============================================================
