// ============================================================
// KATEGORI - LIST (Command Manual)
// ============================================================
if (cmd === '/kategori_list' || cmd === 'kategori_list') {
    const page = parseInt(args[0]) || 1;
    const perPage = 5;
    
    const count = await db.prepare(`SELECT COUNT(*) as total FROM kategori`).first();
    const totalItems = count?.total || 0;
    const totalPages = Math.ceil(totalItems / perPage);
    const currentPage = Math.min(Math.max(page, 1), totalPages || 1);
    const currentOffset = (currentPage - 1) * perPage;
    
    const r = await db.prepare(`
        SELECT * FROM kategori ORDER BY urutan ASC, id ASC LIMIT ? OFFSET ?
    `).bind(perPage, currentOffset).all();
    
    let msg = `📂 *DAFTAR KATEGORI*\n${DIVIDER}\n\n`;
    
    if (!r.results || r.results.length === 0) {
        msg += `_(Belum ada kategori)_\n`;
    } else {
        msg += `📊 Total : ${totalItems} item • Hal ${currentPage}/${totalPages}\n\n`;
        const items = r.results.map(k => ({
            nama: k.nama,
            id: k.id,
            deskripsi: k.deskripsi || 'Tidak ada deskripsi',
            extraLines: []
        }));
        msg += buildListView(items, { startNumber: currentOffset });
        msg += `\n`;
    }
    
    const keyboard = [];
    if (totalPages > 1) {
        const navButtons = [];
        if (currentPage > 1) navButtons.push({ text: "⬅️ Prev", callback_data: `kat_list_page_${currentPage-1}` });
        navButtons.push({ text: `📄 ${currentPage}/${totalPages}`, callback_data: "kat_list_page_jump" });
        if (currentPage < totalPages) navButtons.push({ text: "Next ➡️", callback_data: `kat_list_page_${currentPage+1}` });
        keyboard.push(navButtons);
    }
    keyboard.push([{ text: "🔙 Kembali ke Menu Kategori", callback_data: "menu_kategori" }]);
    
    await sendInlineKeyboard(chatId, msg, keyboard);
    return true;
}

