// ============================================================
// SOAL - LIST (Pagination 5 + Jump)
// ============================================================
if (cmd === '/soal_list' || cmd === 'soal_list') {
    const page = parseInt(args[0]) || 1;
    const perPage = 5;
    const offset = (page - 1) * perPage;
    
    try {
        // Cek kolom status
        const tableInfo = await db.prepare(`PRAGMA table_info(soal)`).all();
        const columns = (tableInfo.results || []).map(c => c.name);
        
        if (!columns.includes('status')) {
            await db.prepare(`ALTER TABLE soal ADD COLUMN status TEXT DEFAULT 'AKTIF'`).run();
            await db.prepare(`UPDATE soal SET status = 'AKTIF' WHERE status IS NULL`).run();
            console.log('✅ Kolom status berhasil ditambahkan');
        }
        
        // Query
        const r = await db.prepare(`
            SELECT 
                s.id, s.soal, s.status, s.tanggal_input,
                s.pilihan_a, s.pilihan_b, s.pilihan_c, s.pilihan_d, s.pilihan_e,
                s.jawaban_benar, s.sumber_link, s.tahun,  
                sk.nama as subkemampuan_nama,
                km.nama as kemampuan_nama,
                kk.judul as kisi_judul,
                sb.nama as sumber_belajar_nama,
                sb.sumber_link as sumber_belajar_link
            FROM soal s
            LEFT JOIN sub_kemampuan sk ON s.sub_kemampuan_id = sk.id
            LEFT JOIN kemampuan_diuji km ON sk.kemampuan_id = km.id
            LEFT JOIN kisi_kisi kk ON s.kisi_kisi_id = kk.id
            LEFT JOIN sumber_belajar sb ON s.sumber_belajar_id = sb.id
            WHERE s.status = 'AKTIF'
            ORDER BY s.id DESC 
            LIMIT ? OFFSET ?
        `).bind(perPage, offset).all();
        
        const count = await db.prepare(`
            SELECT COUNT(*) as total FROM soal WHERE status = 'AKTIF'
        `).first();
        
        const totalPages = Math.ceil((count?.total || 0) / perPage);
        
        let msg = formatSoalList(r.results || [], page, totalPages, offset);
        // Potong paksa kalau terlalu panjang
        if (msg.length > 3800) {
        msg = msg.substring(0, 3800) + '\n\n_... (pesan dipotong)_';
}
        
        const keyboard = [];
        
        // Navigasi halaman (di atas)
        if (totalPages > 1) {
            const navButtons = [];
            if (page > 1) {
                navButtons.push({ text: "⬅️ Prev", callback_data: `soal_page_${page-1}` });
            }
            // Tombol info halaman — BISA DIKLIK
            navButtons.push({ text: `📄 ${page}/${totalPages}`, callback_data: `soal_page_jump` });
            if (page < totalPages) {
                navButtons.push({ text: "Next ➡️", callback_data: `soal_page_${page+1}` });
            }
            keyboard.push(navButtons);
        }
        
        // Tombol aksi
        keyboard.push([{ text: "📝 Tambah Soal", callback_data: "cmd_soal_add" }]);
        keyboard.push([{ text: "📤 Upload Excel", callback_data: "cmd_upload_soal" }]);
        keyboard.push([{ text: "📦 Arsip", callback_data: "menu_arsip" }]);
        keyboard.push([{ text: "📚 Set Sumber", callback_data: "cmd_set_sumber" }]);
        keyboard.push([{ text: "🔙 Kembali", callback_data: "menu_soal" }]);
        
        await sendInlineKeyboard(chatId, msg, keyboard);
        return true;
        
    } catch (e) {
        console.error('Soal list error:', e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
        return true;
    }
}

// ============================================================
// SET SUMBER SOAL - /set_sumber    ← SEKARANG DI LUAR /soal_list
// ============================================================
if (cmd === '/set_sumber' || cmd === 'set_sumber') {
    if (args.length < 1) {
        await smartMessage(chatId, 
            `📚 *SET SUMBER SOAL*\n\n` +
            `Gunakan: /set_sumber [ID Soal] [Sumber Belajar ID] [Link]\n\n` +
            `Contoh:\n` +
            `/set_sumber Q001 SB003 https://books.google.com/...\n` +
            `/set_sumber Q001 SB003 (tanpa link)\n` +
            `/set_sumber Q001 "" https://custom.link.com (tanpa sumber ID)\n\n` +
            `📂 *Sumber Belajar yang tersedia:*\n` +
            `SB001 - Video & Multimedia\n` +
            `SB002 - Dokumen & Publikasi\n` +
            `SB003 - Buku Digital & E-book\n` +
            `SB004 - Website Edukasi & Kursus\n` +
            `SB005 - Website Interaktif & Simulasi\n` +
            `SB006 - Website Bahas Soal & Materi\n` +
            `SB007 - Gambar & Visual\n` +
            `SB008 - Open Educational Resources (OER)\n` +
            `SB009 - Portal Resmi & Pemerintah\n` +
            `SB010 - Campuran\n\n` +
            `💡 Gunakan "" untuk mengosongkan nilai`
        );
        return true;
    }
    
    const soalId = args[0];
    let sumberId = args.length > 1 ? args[1] : null;
    let sumberLink = args.length > 2 ? args.slice(2).join(' ') : null;
    
    // Handle empty string
    if (sumberId === '""' || sumberId === "''" || sumberId === 'null' || sumberId === 'NULL') {
        sumberId = null;
    }
    if (sumberLink === '""' || sumberLink === "''" || sumberLink === 'null' || sumberLink === 'NULL') {
        sumberLink = null;
    }
    
    // Validasi soal
    const soal = await db.prepare(`SELECT id FROM soal WHERE id = ?`).bind(soalId).first();
    if (!soal) {
        await smartMessage(chatId, `❌ Soal ${soalId} tidak ditemukan.`);
        return true;
    }
    
    // Validasi sumber
    if (sumberId) {
        const sumber = await db.prepare(`SELECT id, nama FROM sumber_belajar WHERE id = ?`).bind(sumberId).first();
        if (!sumber) {
            await smartMessage(chatId, `❌ Sumber ${sumberId} tidak ditemukan.`);
            return true;
        }
    }
    
    // Update
    await db.prepare(`
        UPDATE soal SET 
            sumber_belajar_id = ?,
            sumber_link = ?
        WHERE id = ?
    `).bind(sumberId, sumberLink, soalId).run();
    
    let response = `✅ *SUMBER SOAL ${soalId} BERHASIL DIUPDATE!*\n\n`;
    response += `📚 Sumber ID: ${sumberId || 'Tidak ada'}\n`;
    if (sumberId) {
        const sumber = await db.prepare(`SELECT nama FROM sumber_belajar WHERE id = ?`).bind(sumberId).first();
        if (sumber) response += `📚 Nama Sumber: ${sumber.nama}\n`;
    }
    response += `🔗 Link: ${sumberLink || 'Tidak ada'}`;
    
    await smartMessage(chatId, response);
    return true;
}

// ============================================================
// SET TAHUN SOAL (Patch #17)
// Fix BUG-112: Pakai parseInputUniversal
// ============================================================
if (cmd === '/set_tahun' || cmd === 'set_tahun') {
    if (args.length < 2) {
        await smartMessage(chatId, 
            `📅 *SET TAHUN SOAL*\n\n` +
            `Gunakan: /set_tahun [ID Soal] [Tahun]\n\n` +
            `Contoh:\n` +
            `/set_tahun Q001 2024\n` +
            `/set_tahun Q001, Q003 2025 (multiple)\n` +
            `/set_tahun Q001-Q005 2024 (range)\n\n` +
            `💡 Untuk menghapus tahun: /set_tahun Q001 ""`
        );
        return true;
    }
    
    const input = args.slice(0, -1).join(' ');
    const tahun = args[args.length - 1] === '""' || args[args.length - 1] === "''" ? null : args[args.length - 1];
    
    // FIX BUG-112: Pakai parseInputUniversal
    const parsed = parseInputUniversal(input, { 
        mode: 'delete', 
        entity: 'soal',
        prefix: 'Q' 
    });
    
    if (!parsed.success || !parsed.items || parsed.items.length === 0) {
        await smartMessage(chatId, `❌ ${parsed.error || 'Tidak ada soal yang ditemukan.'}`);
        return true;
    }
    
    // Query manual untuk ambil data soal
    const items = [];
    for (const item of parsed.items) {
        try {
            const row = await db.prepare(`SELECT * FROM soal WHERE id = ?`).bind(item.id).first();
            if (row) items.push(row);
        } catch (e) {
            console.warn(`⚠️ Gagal ambil soal ${item.id}:`, e.message);
        }
    }
    
    if (items.length === 0) {
        await smartMessage(chatId, '❌ Tidak ada soal yang ditemukan.');
        return true;
    }
    
    let successCount = 0;
    let errorCount = 0;
    
    for (const item of items) {
        try {
            await db.prepare(`UPDATE soal SET tahun = ? WHERE id = ?`)
                .bind(tahun, item.id).run();
            successCount++;
        } catch (e) {
            errorCount++;
        }
    }
    
    await smartMessage(chatId, 
        `✅ *TAHUN SOAL BERHASIL DIUPDATE!*\n\n` +
        `📊 Berhasil: ${successCount} soal\n` +
        `❌ Gagal: ${errorCount} soal\n` +
        `📅 Tahun: ${tahun || 'Tidak ada'}`
    );
    return true;
}

