    const stats = await db.prepare(`
        SELECT 
            kategori_arsip,
            COUNT(*) as total,
            MIN(tanggal_arsip) as pertama,
            MAX(tanggal_arsip) as terakhir
        FROM soal 
        WHERE status = 'ARSIP' OR status_ketersediaan = 'arsip'
        GROUP BY kategori_arsip
        ORDER BY total DESC
    `).all();
    
    let msg = `📊 *STATISTIK ARSIP PER KATEGORI*\n\n`;
    
    if (!stats.results || stats.results.length === 0) {
        msg += '❌ Belum ada soal yang diarsipkan.';
    } else {
        let totalAll = 0;
        stats.results.forEach((s, i) => {
            const namaKategori = s.kategori_arsip || 'TANPA_KATEGORI';
            msg += `${i+1}. 🏷️ *${namaKategori}*\n`;
            msg += `   📊 Total: ${s.total} soal\n`;
            msg += `   📅 Pertama: ${s.pertama ? new Date(s.pertama).toLocaleDateString('id-ID') : '-'}\n`;
            msg += `   📅 Terakhir: ${s.terakhir ? new Date(s.terakhir).toLocaleDateString('id-ID') : '-'}\n\n`;
            totalAll += s.total;
        });
        msg += `\n📦 *Total Soal Arsip:* ${totalAll} soal`;
    }
    
    await smartMessage(chatId, msg);
    return true;
