        if(cmd==='/admin_add'||cmd==='/admin_remove'){if(role!=='SUPER ADMIN')return await reply('⛔ Hanya SUPER ADMIN.');const id=arg(0);if(!id)return await reply(`Gunakan: ${cmd} [user_id]`);if(cmd==='/admin_add'){const u=await findUser(id);if(!u)return await reply('❌ User tidak ditemukan.');await db.prepare(`UPDATE users SET role='admin',updated_at=? WHERE id=? OR telegram_id=?`).bind(now,id,id).run();return await reply(`✅ ${id} diberi role ADMIN.`);}await db.prepare(`UPDATE users SET role='user',updated_at=? WHERE id=? OR telegram_id=?`).bind(now,id,id).run();return await reply(`✅ ${id} dikeluarkan dari admin.`);}

