        if(cmd==='/review_stats'){const r=await db.prepare(`SELECT COALESCE(status_soal,'DRAFT') status,COUNT(*) total FROM soal GROUP BY COALESCE(status_soal,'DRAFT')`).all();return await reply(formatRows('STATISTIK REVIEW',r.results||[]));}
