        if(cmd==='/jawab'){const id=arg(0),ans=args.slice(1).join(' ');if(!id||!ans)return await reply('Gunakan: /jawab [ID] [jawaban]');await db.prepare(`UPDATE user_questions SET admin_answer=?,answered_by=?,answered_at=?,status='ANSWERED',updated_at=? WHERE id=?`).bind(ans,userId,now,now,id).run();return await reply('✅ Pertanyaan dijawab.');}
