        if(cmd.startsWith('/report_')){const id=arg(0);if(!id)return await reply(`Gunakan: ${cmd} [ID]`);const r=await db.prepare(`SELECT COUNT(*) c FROM user_activity WHERE user_id=?`).bind(id).first();return await reply(`📑 ${cmd}\nUser: ${id}\nAktivitas: ${r?.c||0}`);}
        if(cmd==='/report_top_users'){const n=Math.min(100,Math.max(1,Number(arg(0))||10));const r=await db.prepare(`SELECT user_id,COUNT(*) total FROM user_activity GROUP BY user_id ORDER BY total DESC LIMIT ?`).bind(n).all();return await reply(formatRows('TOP USER',r.results||[]));}

        // G — statistik/dashboard
        if(cmd.startsWith('/dashboard')||cmd.startsWith('/stats_')){const [s,u,p]=await Promise.all([count('soal'),count('users'),count('user_questions','status=?',['PENDING'])]);let extra='';if(cmd.includes('status')){const r=await db.prepare(`SELECT COALESCE(status_soal,status,'-') status,COUNT(*) total FROM soal GROUP BY COALESCE(status_soal,status,'-')`).all();extra='\n'+(r.results||[]).map(x=>`${x.status}: ${x.total}`).join('\n');}if(cmd.includes('penyajian'))extra='\nPenyajian dihitung dari cara_penyajian_id.';if(cmd.includes('tipe'))extra='\nTipe dihitung dari tipe_isi_id/jenis_soal.';if(cmd.includes('hots'))extra='\nProses kognitif terisi: '+await count('soal',"tipe_hots IN ('LOTS','MOTS','HOTS')");return await reply(`📊 *${cmd.toUpperCase()}*\nSoal: ${s}\nUser: ${u}\nPertanyaan pending: ${p}${extra}`);}

