        if(cmd==='/backup_soal'||cmd==='/backup_user'){try{const tables=cmd==='/backup_soal'?['soal']:['users'];const r=await sendPortableD1Backup(chatId,db,tables,userId);return await reply(`✅ Backup ${cmd==='/backup_soal'?'soal':'user'} selesai: ${r.totalRows.toLocaleString('id-ID')} rows, ${r.totalParts} parts.`);}catch(e){return await reply(`❌ Backup gagal: ${e.message}`);}}
        if(cmd==='/backup_schedule'){const id=await generateId(db,'BKP','batch_jobs');await db.prepare(`INSERT INTO batch_jobs (id,job_type,payload,status,total,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)`).bind(id,'BACKUP_SCHEDULE',JSON.stringify({schedule:arg(0)||null}), 'SCHEDULED',0,userId,now,now).run();return await reply(`🗓️ Jadwal backup ${id} tercatat.`);}

        // I — broadcast/notifikasi
        if(cmd==='/broadcast'||cmd==='/broadcast_filter'||cmd==='/broadcast_schedule'){let msg='',filter=null,schedule=null;if(cmd==='/broadcast')msg=args.join(' ');else if(cmd==='/broadcast_filter'){filter=arg(0);msg=args.slice(1).join(' ');}else{schedule=arg(0);msg=args.slice(1).join(' ');}if(!msg)return await reply('Pesan broadcast wajib diisi.');const id=await generateId(db,'BRD','broadcasts');await db.prepare(`INSERT INTO broadcasts (id,message,filter_json,scheduled_at,status,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)`).bind(id,msg,filter,schedule,schedule?'SCHEDULED':'PENDING',userId,now,now).run();if(!schedule&&cmd==='/broadcast'){const users=(await db.prepare(`SELECT telegram_id FROM users WHERE status='AKTIF' AND telegram_id IS NOT NULL LIMIT 1000`).all()).results||[];let ok=0;for(const u of users){try{const r=await sendMessage(u.telegram_id,msg);if(r?.ok)ok++;}catch{}}await db.prepare(`UPDATE broadcasts SET status='SENT',sent_count=?,updated_at=? WHERE id=?`).bind(ok,now,id).run();return await reply(`📣 Broadcast selesai: ${ok}/${users.length}.`);}return await reply(`📣 Broadcast ${id} tersimpan.`);}
        if(cmd==='/broadcast_token'){const n=Math.abs(Number(arg(0))||0);if(!n)return await reply('Gunakan: /broadcast_token [jumlah]');const users=(await db.prepare(`SELECT telegram_id FROM users WHERE status='AKTIF' AND telegram_id IS NOT NULL LIMIT 1000`).all()).results||[];for(const u of users)try{await sendMessage(u.telegram_id,`🪙 Anda menerima ${n} token.`)}catch{}return await reply(`🪙 Notifikasi token dikirim ke ${users.length} user.`);}
        if(cmd==='/notif_on'||cmd==='/notif_off'||cmd==='/notif_setting'){const en=cmd==='/notif_off'?0:1;const settings=cmd==='/notif_setting'?args.slice(0).join(' '):null;await db.prepare(`INSERT INTO notifications (user_id,enabled,settings,updated_at) VALUES (?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET enabled=excluded.enabled,settings=excluded.settings,updated_at=excluded.updated_at`).bind(userId,en,settings,now).run();return await reply(`🔔 Notifikasi admin: ${en?'ON':'OFF'}`);}

        // J — system
        if(cmd==='/config_lihat'){const r=(await db.prepare(`SELECT key,value,value_type,description FROM system_config ORDER BY key`).all()).results||[];return await reply(r.map(x=>`${x.key} = ${x.value}`).join('\n')||'Belum ada config.');}
        if(cmd==='/config_ubah'){const key=arg(0),value=args.slice(1).join(' ');if(!key)return await reply('Gunakan: /config_ubah [key] [value]');await db.prepare(`INSERT INTO system_config (key,value,updated_by,created_at,updated_at) VALUES (?,?,?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_by=excluded.updated_by,updated_at=excluded.updated_at`).bind(key,value,userId,now,now).run();return await reply('✅ Config tersimpan.');}
