        if(cmd==='/maintenance_on'||cmd==='/maintenance_off'||cmd==='/maintenance_status'){if(cmd==='/maintenance_status'){const r=await db.prepare(`SELECT value FROM system_config WHERE key='maintenance'`).first();return await reply(`Maintenance: ${r?.value==='on'?'ON':'OFF'}`);}await db.prepare(`INSERT INTO system_config (key,value,updated_by,created_at,updated_at) VALUES ('maintenance',?,?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_by=excluded.updated_by,updated_at=excluded.updated_at`).bind(cmd.endsWith('on')?'on':'off',userId,now,now).run();return await reply(`🔧 Maintenance ${cmd.endsWith('on')?'ON':'OFF'}`);}
        if(cmd==='/log'||cmd==='/log_user'||cmd==='/log_tanggal'){let q='SELECT * FROM admin_log ORDER BY created_at DESC LIMIT 50',b=[];if(cmd==='/log_user'){q='SELECT * FROM admin_log WHERE actor_id=? ORDER BY created_at DESC LIMIT 50';b=[arg(0)]}if(cmd==='/log_tanggal'){q='SELECT * FROM admin_log WHERE created_at LIKE ? ORDER BY created_at DESC LIMIT 50';b=[arg(0)+'%']}return await reply(formatRows('ADMIN LOG',(await db.prepare(q).bind(...b).all()).results||[]));}
        if(cmd==='/log_clear'){const days=Math.max(1,Number(arg(0))||1);await db.prepare(`DELETE FROM admin_log WHERE created_at < ?`).bind(new Date(Date.now()-days*86400000).toISOString()).run();return await reply('🧹 Log lama dibersihkan.');}
