        if(cmd==='/ai_setting_model'||cmd==='/ai_setting_prompt'||cmd==='/ai_setting_temp'||cmd==='/ai_setting_token'){const provider=arg(0),value=args.slice(1).join(' ');if(!provider||!value)return await reply(`Gunakan: ${cmd} [provider/task] [nilai]`);const old=await db.prepare(`SELECT * FROM ai_settings WHERE provider=? ORDER BY updated_at DESC LIMIT 1`).bind(provider).first();const id=old?.id||await generateId(db,'AIS','ai_settings');const model=cmd==='/ai_setting_model'?value:old?.model||null,prompt=cmd==='/ai_setting_prompt'?value:old?.prompt||null,temp=cmd==='/ai_setting_temp'?Math.max(0,Math.min(2,Number(value))):Number(old?.temperature??0.7),tokens=cmd==='/ai_setting_token'?Math.max(1,Number(value)||4096):Number(old?.max_tokens||4096),task=old?.task||null;await db.prepare(`INSERT OR REPLACE INTO ai_settings (id,provider,model,task,prompt,temperature,max_tokens,enabled,updated_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).bind(id,provider,model,task,prompt,temp,tokens,1,userId,old?.created_at||now,now).run();return await reply('✅ AI setting tersimpan.');}

        // L/M/N/O — webhook/ujian/sertifikat/voucher
        if(cmd==='/webhook_set'){const url=arg(0);if(!/^https:\/\//i.test(url))return await reply('❌ Webhook wajib HTTPS.');const id=await generateId(db,'WH','webhooks');await db.prepare(`INSERT INTO webhooks (id,url,status,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?)`).bind(id,url,'ACTIVE',userId,now,now).run();return await reply(`✅ Webhook ${id} disimpan.`);}
        if(cmd==='/webhook_list'){return await reply(formatRows('WEBHOOK',(await db.prepare(`SELECT * FROM webhooks WHERE status!='DELETED' ORDER BY created_at DESC LIMIT 50`).all()).results||[]));}
        if(cmd==='/webhook_delete'){await db.prepare(`UPDATE webhooks SET status='DELETED',updated_at=? WHERE id=?`).bind(now,arg(0)).run();return await reply('✅ Webhook dihapus.');}
        if(cmd==='/webhook_test'){const w=await db.prepare(`SELECT * FROM webhooks WHERE status='ACTIVE' ORDER BY created_at DESC LIMIT 1`).first();if(!w)return await reply('❌ Tidak ada webhook aktif.');const ac=new AbortController();const timer=setTimeout(()=>ac.abort(),10000);let r;try{r=await fetch(w.url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event:'test',timestamp:now}),signal:ac.signal});}finally{clearTimeout(timer);}const tx=(await r.text()).slice(0,500);await db.prepare(`UPDATE webhooks SET last_status=?,last_response=?,last_tested_at=?,updated_at=? WHERE id=?`).bind(String(r.status),tx,now,now,w.id).run();return await reply(`Webhook HTTP ${r.status}\n${tx}`);}
        if(cmd==='/ujian_buat'){const name=arg(0),date=arg(1),dur=Math.max(1,Number(arg(2))||60),ids=args.slice(3).join(' ');if(!name||!ids)return await reply('Gunakan: /ujian_buat [nama] [tanggal] [durasi] [soal_ids]');const id=await generateId(db,'EX','exams');await db.prepare(`INSERT INTO exams (id,name,exam_date,duration_minutes,soal_ids,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)`).bind(id,name,date,dur,ids,userId,now,now).run();return await reply(`✅ Ujian ${id} dibuat.`);}
        if(cmd==='/ujian_list'){return await reply(formatRows('UJIAN',(await db.prepare(`SELECT * FROM exams ORDER BY created_at DESC LIMIT 50`).all()).results||[]));}
        if(cmd==='/ujian_edit'){const id=arg(0),field=arg(1),value=args.slice(2).join(' ');if(!id||!['name','exam_date','duration_minutes','soal_ids','status'].includes(field))return await reply('Gunakan: /ujian_edit [ID] [field] [nilai]');await db.prepare(`UPDATE exams SET ${field}=?,updated_at=? WHERE id=?`).bind(value,now,id).run();return await reply('✅ Ujian diperbarui.');}
        if(cmd==='/ujian_delete'){await db.prepare(`UPDATE exams SET status='DELETED',updated_at=? WHERE id=?`).bind(now,arg(0)).run();return await reply('🗑️ Ujian dihapus.');}
        if(cmd==='/ujian_hasil'){return await reply(formatRows('HASIL UJIAN',(await db.prepare(`SELECT * FROM exam_results WHERE exam_id=? ORDER BY score DESC LIMIT 100`).bind(arg(0)).all()).results||[]));}
        if(cmd==='/sertifikat_template'){return await reply(formatRows('TEMPLATE SERTIFIKAT',(await db.prepare(`SELECT * FROM certificate_templates ORDER BY created_at DESC LIMIT 50`).all()).results||[]));}
        if(cmd==='/sertifikat_design'){const id=arg(0),design=args.slice(1).join(' ');if(!design)return await reply('Gunakan: /sertifikat_design [nama] [design]');const x=await generateId(db,'CRT','certificate_templates');await db.prepare(`INSERT INTO certificate_templates (id,name,design,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?)`).bind(x,id||'Default',design,userId,now,now).run();return await reply(`✅ Template ${x} disimpan.`);}
        if(cmd==='/sertifikat_buat'){const uid=arg(0),topik=arg(1),score=Number(arg(2));if(!uid||!topik||!Number.isFinite(score))return await reply('Gunakan: /sertifikat_buat [user_id] [topik] [nilai]');const id=await generateId(db,'CERT','certificates'),no=`CERT-${Date.now()}-${crypto.randomUUID().slice(0,8).toUpperCase()}`;await db.prepare(`INSERT INTO certificates (id,user_id,topik,score,certificate_no,status,issued_at,created_by) VALUES (?,?,?,?,?,?,?,?)`).bind(id,uid,topik,score,no,'ISSUED',now,userId).run();return await reply(`🏅 Sertifikat ${no} diterbitkan.`);}
        if(cmd==='/sertifikat_batch'){const users=(await db.prepare(`SELECT DISTINCT user_id,AVG(score) score FROM exam_results GROUP BY user_id HAVING AVG(score)>=? LIMIT 100`).bind(Number(arg(0))||75).all()).results||[];let n=0;for(const u of users){const id=await generateId(db,'CERT','certificates'),no=`CERT-${Date.now()}-${crypto.randomUUID().slice(0,8).toUpperCase()}`;await db.prepare(`INSERT INTO certificates (id,user_id,topik,score,certificate_no,status,issued_at,created_by) VALUES (?,?,?,?,?,?,?,?)`).bind(id,u.user_id,'Evaluasi',Number(u.score||0),no,'ISSUED',now,userId).run();n++;}return await reply(`🏅 ${n} sertifikat batch diterbitkan.`);}
        if(cmd==='/voucher_buat'){const amount=Math.min(500,Math.max(1,Number(arg(0))||0)),tokens=Math.max(1,Number(arg(1))||0),exp=arg(2)||null;if(!amount||!tokens)return await reply('Gunakan: /voucher_buat [jumlah] [token] [expired]');const codes=[];for(let i=0;i<amount;i++){const code=`V-${crypto.randomUUID().replace(/-/g,'').slice(0,14).toUpperCase()}`;await db.prepare(`INSERT INTO vouchers (code,token_amount,expires_at,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?)`).bind(code,tokens,exp,userId,now,now).run();codes.push(code);}return await reply(`🎟️ ${codes.length} voucher dibuat.\n${codes.join('\n')}`);}
