        if(cmd==='/voucher_stats'){const r=await db.prepare(`SELECT COUNT(*) total,SUM(used_count) used,SUM(CASE WHEN status='ACTIVE' THEN 1 ELSE 0 END) active FROM vouchers`).first();return await reply(`🎟️ Total: ${r?.total||0}\nAktif: ${r?.active||0}\nPemakaian: ${r?.used||0}`);}
