          try{const c=getCredentialReadiness(env);checks.push(`🤖 Credential AI/API: ${Object.values(c).filter(Boolean).length}/${Object.keys(c).length} terkonfigurasi`);}catch(e){checks.push(`⚠️ Credential: ${e.message}`);}
          try{const r=await db.prepare(`SELECT COUNT(*) c FROM user_learning_reminders WHERE status='ACTIVE'`).first();checks.push(`🔔 Alarm: ${Number(r?.c||0).toLocaleString('id-ID')} aktif`);}catch(e){checks.push(`⚠️ Alarm: tabel belum siap — ${e.message}`);}
          try{const r=await db.prepare(`SELECT result,COUNT(*) c FROM admin_log WHERE created_at>=datetime('now','-24 hours') GROUP BY result ORDER BY c DESC`).all();checks.push(`📋 Log 24 jam: ${(r.results||[]).map(x=>`${x.result}:${x.c}`).join(' | ')||'belum ada'}`);}catch(e){checks.push(`⚠️ Log: ${e.message}`);}
          return await reply(`🩺 *CEK SEMUA SISTEM*\n${DIVIDER}\n\n${checks.join('\n')}`);
