if (session.action && session.action.startsWith('ent_edit_jump_')) {
    const entity = session.action.replace('ent_edit_jump_', '');
    const config = getEntityConfig(entity);
    
    if (!config) {
        await smartTextResponse('❌ Entitas tidak dikenal.');
        await clearSession(env, userId);
        return true;
    }
    
    const input = text.trim();
    if (userMessageId) await deleteMessage(chatId, userMessageId);
    
    if (input.toLowerCase() === 'batal' || input.toLowerCase() === 'skip') {
        const lastMessageId = session.lastMessageId;
        await clearSession(env, userId);
        
        const messageId = lastMessageId;
        let msg = `✏️ *UBAH ${config.labelPlural.toUpperCase()}*\n${DIVIDER}\n\n`;
        msg += `Ketik data yang ingin diubah:\n\n`;
        msg += `📌 *Format 1:*\nID : ${config.prefix}001\nNama : Nama Baru\n\n`;
        msg += `📌 *Format 2:*\n${config.prefix}001; Nama Baru\n\n`;
        msg += `📌 *Format 3:*\n${config.prefix}001\nNama Baru\n\n`;
        msg += `💡 Ketik "skip" untuk batal.`;
        
        const keyboard = [[{ 
            text: `🔙 Kembali ke Menu ${config.label}`, 
            callback_data: config.menuCallback 
        }]];
        if (messageId) await editInlineKeyboard(chatId, messageId, msg, keyboard);
        else await smartKeyboardResponse(msg, keyboard);
        return true;
    }
    
    const page = parseInt(input);
    if (!page || page < 1) {
        await smartTextResponse('❌ Nomor tidak valid. Kirim ulang atau "batal":');
        return true;
    }
    
    const lastMessageId = session.lastMessageId;
    await clearSession(env, userId);
    
    const sessionNew = await getSession(env, userId);
    sessionNew.action = `ent_edit_input_${entity}`;
    sessionNew.lastMessageId = lastMessageId;
    await saveSession(env, userId, sessionNew);
    
    // Halaman 1 = panduan
    if (page === 1) {
        const count = await db.prepare(`SELECT COUNT(*) AS total FROM ${config.table}`).first();
        const totalItems = count?.total || 0;
        const totalPages = Math.ceil(totalItems / 5) + 1;
        
        let msg = `✏️ *UBAH ${config.labelPlural.toUpperCase()}*\n${DIVIDER}\n\n`;
        msg += `📝 *Ketik data yang ingin diubah:*\n\n`;
        msg += `📌 *Format 1:*\nID : ${config.prefix}001\nNama : Nama Baru\nDeskripsi : Isi\n\n`;
        msg += `📌 *Format 2:*\n${config.prefix}001; Nama Baru; Isi\n\n`;
        msg += `📌 *Format 3:*\n${config.prefix}001\nNama Baru\nIsi\n\n`;
        msg += `💡 Ketik "skip" untuk batal.`;
        
        const keyboard = [];
        const navButtons = [{ text: `📄 1/${totalPages}`, callback_data: `ent_edit_page_jump_${entity}` }];
        if (totalPages > 1) {
            navButtons.push({ text: "Next ➡️", callback_data: `ent_edit_page_${entity}_2` });
        }
        keyboard.push(navButtons);
        keyboard.push([{ text: `🔙 Kembali`, callback_data: config.menuCallback }]);
        
        if (lastMessageId) await editInlineKeyboard(chatId, lastMessageId, msg, keyboard);
        else await smartKeyboardResponse(msg, keyboard);
        return true;
    }
    
    // Halaman 2+ = list existing
    const perPage = 5;
    const count = await db.prepare(`SELECT COUNT(*) AS total FROM ${config.table}`).first();
    const totalItems = count?.total || 0;
    const totalPages = Math.ceil(totalItems / perPage) + 1;
    
    const listPage = page - 1;
    const currentPage = Math.min(Math.max(listPage, 1), Math.ceil(totalItems / perPage) || 1);
    const currentOffset = (currentPage - 1) * perPage;
    
    const nameField = config.nameField || 'nama';
    const r = await db.prepare(`
        SELECT id, ${nameField} AS nama, deskripsi FROM ${config.table} 
        ORDER BY urutan ASC, id ASC 
        LIMIT ? OFFSET ?
    `).bind(perPage, currentOffset).all();
    
    let msg = `✏️ *UBAH ${config.labelPlural.toUpperCase()}*\n${DIVIDER}\n\n`;
    msg += `📊 Total : ${totalItems} item • Hal ${page}/${totalPages}\n\n`;
    msg += `Pilih ${config.label} (klik ID di bawah):\n\n`;
    
    const items = (r.results || []).map(k => ({
        nama: k.nama,
        id: k.id,
        deskripsi: k.deskripsi || 'Tidak ada deskripsi',
        extraLines: []
    }));
    
    if (typeof buildListView === 'function') {
        msg += buildListView(items, { startNumber: currentOffset });
    } else {
        items.forEach((k, i) => {
            msg += `${i + currentOffset + 1}. ${k.nama}\n`;
            msg += `   🆔 ID : ${k.id}\n`;
            msg += `   📝 Deskripsi : ${k.deskripsi}\n\n`;
        });
    }
    msg += `\n`;
    
    const keyboard = [];
    const idButtons = (r.results || []).map(k => ({
        text: k.id,
        callback_data: `ent_edit_form_${entity}_${k.id}`
    }));
    for (let i = 0; i < idButtons.length; i += 5) {
        keyboard.push(idButtons.slice(i, i + 5));
    }
    
    const navButtons = [];
    if (page > 2) {
        navButtons.push({ text: "⬅️ Prev", callback_data: `ent_edit_page_${entity}_${page - 1}` });
    } else {
        navButtons.push({ text: "⬅️ Prev", callback_data: `ent_edit_${entity}` });
    }
    navButtons.push({ text: `📄 ${page}/${totalPages}`, callback_data: `ent_edit_page_jump_${entity}` });
    if (page < totalPages) {
        navButtons.push({ text: "Next ➡️", callback_data: `ent_edit_page_${entity}_${page + 1}` });
    }
    keyboard.push(navButtons);
    keyboard.push([{ text: "🔙 Kembali", callback_data: config.menuCallback }]);
    
    if (lastMessageId) await editInlineKeyboard(chatId, lastMessageId, msg, keyboard);
    else await smartKeyboardResponse(msg, keyboard);
    return true;
}

