    // Simpan pesan di session
    session.broadcastMessage = input;
    await saveSession(env, userId, session);
    
    // Tampilkan preview
    let previewMsg = `📢 *PREVIEW BROADCAST*\n\n`;
    previewMsg += `📊 *Target:* ${targetLabels[target]}\n`;
    previewMsg += `👥 *Jumlah penerima:* ${targetCount?.c || 0} user\n\n`;
    previewMsg += `━━━━━━━━━━━━━━━━━━━\n`;
    previewMsg += `📝 *Isi Pesan:*\n\n`;
    previewMsg += input;
    previewMsg += `\n━━━━━━━━━━━━━━━━━━━\n\n`;
    previewMsg += `⚠️ *Yakin ingin kirim ke ${targetCount?.c || 0} user?*`;
    
    await smartKeyboardResponse(previewMsg, [
        [{ text: `📤 Ya, Kirim ke ${targetCount?.c || 0} user`, callback_data: "user_broadcast_send_yes" }],
        [{ text: "❌ Batal", callback_data: "user_broadcast_send_no" }]
    ]);
