// ============================================================
// JENJANG EDIT — Handler
// ============================================================
if (session.action === 'jenjang_edit') {
    const input = text.trim();
    
    if (input.toLowerCase() === 'skip' || input.toLowerCase() === 'batal') {
        await smartTextResponse('❌ Dibatalkan.');
        await clearSession(env, userId);
        return true;
    }
    
    // Parse input
    const lines = input.split('\n');
    const updateData = {};
    
    for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed) continue;
        
        const match = trimmed.match(/^([^:]+):\s*(.+)$/);
        if (!match) continue;
        
        const key = match[1].trim().toLowerCase();
        const value = match[2].trim();
        
        if (!value) continue;
        
        if (key === 'nama') updateData.nama = value;
        else if (key === 'jenis') updateData.jenis = value;
        else if (key === 'kategori') updateData.kategori = value;
        else if (key === 'icon') updateData.icon = value;
        else if (key === 'deskripsi' || key === 'desc') updateData.deskripsi = value;
        else if (key === 'urutan') updateData.urutan = parseInt(value) || 0;
    }
    
    if (Object.keys(updateData).length === 0) {
        await smartTextResponse(
            `❌ Format tidak valid.\n\n` +
            `Gunakan format:\n` +
            `nama: Nama Baru\n` +
            `jenis: pendidikan\n` +
            `icon: 🏫\n` +
            `desc: Deskripsi baru\n\n` +
            `Kirim ulang atau ketik "skip":`
        );
        return true;
    }
    
    // Update
    const fields = Object.keys(updateData).map(k => `${k} = ?`).join(', ');
    const values = Object.values(updateData);
    values.push(new Date().toISOString());
    values.push(session.editId);
    
    try {
        await db.prepare(`
            UPDATE jenjang SET ${fields}, updated_at = ?
            WHERE id = ?
        `).bind(...values).run();
        
        await smartTextResponse(
            `✅ *Jenjang berhasil diupdate!*\n\n` +
            `🆔 ID: \`${session.editId}\`\n` +
            `📝 Fields: ${Object.keys(updateData).join(', ')}`
        );
    } catch (e) {
        await smartTextResponse(`❌ Gagal update: ${e.message}`);
    }
    
    await clearSession(env, userId);
    return true;
}

// ============================================================
// FUNGSI BANTU: SIMPAN DATA JENJANG BARU
// ============================================================
async function saveJenjangData(env, userId, chatId, db, data) {
    try {
        // Cari urutan terakhir untuk jenis ini
        const lastOrder = await db.prepare(`
            SELECT MAX(urutan) as max_urut FROM jenjang WHERE jenis = ?
        `).bind(data.jenis || 'pendidikan').first();
        
        const urutan = (lastOrder?.max_urut || 0) + 1;
        
        await db.prepare(`
            INSERT INTO jenjang 
            (id, nama, jenis, kategori, urutan, icon, deskripsi, is_active, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?)
        `).bind(
            data.jenjangId,
            data.nama,
            data.jenis || 'pendidikan',
            data.kategori || 'umum',
            urutan,
            data.icon || '📌',
            data.deskripsi || null,
            new Date().toISOString()
        ).run();
        
        await smartTextResponse(chatId, 
            `✅ *JENJANG BERHASIL DITAMBAHKAN!*\n\n` +
            `🆔 ID: \`${data.jenjangId}\`\n` +
            `📝 Nama: ${data.nama}\n` +
            `🎯 Jenis: ${data.jenis || 'pendidikan'}\n` +
            `📄 Deskripsi: ${data.deskripsi || '-'}\n\n` +
            `💡 Cek: /jenjang_list`
        );
        
        await clearSession(env, userId);
        
        // Refresh list
        await handleCommand(env, chatId, userId, '/jenjang_list');
        
    } catch (e) {
        console.error('saveJenjangData error:', e);
        await smartTextResponse(chatId, `❌ Gagal simpan: ${e.message}`);
        await clearSession(env, userId);
    }
} 

