if (session.action === 'arsip_soal_multiple') {
  const input = text.trim();
  
  if (input.toLowerCase() === 'skip' || input.toLowerCase() === 'batal') {
    await smartTextResponse(chatId, '❌ Dibataikan.');
    await clearSession(env, userId);
    await smartKeyboardResponse(chatId, `📦 *Menu Arsip*`, [
      [{ text: "📋 Lihat Semua Arsip", callback_data: "arsip_list" }],
      [{ text: "📊 Statistik Kategori", callback_data: "arsip_statistik" }],
      [{ text: "📦 Arsipkan Soal", callback_data: "arsip_soal" }],
      [{ text: "✅ Aktifkan Kembali", callback_data: "arsip_aktifkan" }],
      [{ text: "🔙 Kembali ke Soal", callback_data: "menu_soal" }]
    ]);
    return true;
  }
  
  // FIX BUG-112: Pakai parseInputUniversal
  const parsed = parseInputUniversal(input, { 
    mode: 'delete', 
    entity: 'soal',
    prefix: 'Q' 
  });
  
  if (!parsed.success || !parsed.items || parsed.items.length === 0) {
    await smartTextResponse(chatId, `❌ ${parsed.error || 'Tidak ada soal yang ditemukan.'}`);
    return true;
  }
  
  // Query manual untuk ambil data soal
  const items = [];
  for (const item of parsed.items) {
    try {
      const row = await db.prepare(`SELECT * FROM soal WHERE id = ?`).bind(item.id).first();
      if (row) items.push(row);
    } catch (e) {
      console.warn(`⚠️ Gagal ambil soal ${item.id}:`, e.message);
    }
  }
  
  if (items.length === 0) {
    await smartTextResponse(chatId, '❌ Tidak ada soal yang ditemukan.');
    return true;
  }
  
  // Filter hanya yang status AKTIF
  const activeItems = [];
  for (const item of items) {
    const check = await db.prepare(`SELECT status FROM soal WHERE id = ?`).bind(item.id).first();
    if (check && check.status === 'AKTIF') {
      activeItems.push(item);
    }
  }
  
  if (activeItems.length === 0) {
    await smartTextResponse(chatId, '❌ Tidak ada soal aktif yang ditemukan.');
    await clearSession(env, userId);
    return true;
  }
  
  // Simpan di session
  session.arsipMultipleItems = activeItems;
  session.arsipStep = 'pilih_kategori_multiple';
  await saveSession(env, userId, session);
  
  let msg = `📦 *ARSIP ${activeItems.length} SOAL*\n\n`;
  msg += `Soal yang akan diarsipkan:\n`;
  activeItems.slice(0, 5).forEach(item => {
    const text = (item.soal || '').substring(0, 50) + (item.soal.length > 50 ? '...' : '');
    msg += `- ${item.id}: ${text}\n`;
  });
  if (activeItems.length > 5) msg += `- ... dan ${activeItems.length - 5} lainnya\n\n`;
  msg += `Pilih kategori:`;
  
  const keyboard = [
    [{ text: "📂 UJIAN_2024", callback_data: `arsip_multiple_UJIAN_2024` }],
    [{ text: "📂 UJIAN_2025", callback_data: `arsip_multiple_UJIAN_2025` }],
    [{ text: "📂 KADALUARSA", callback_data: `arsip_multiple_KADALUARSA` }],
    [{ text: "📂 SUDAH_PAKAI", callback_data: `arsip_multiple_SUDAH_PAKAI` }],
    [{ text: "📂 REVISI", callback_data: `arsip_multiple_REVISI` }],
    [{ text: "📂 LAINNYA", callback_data: `arsip_multiple_LAINNYA` }],
    [{ text: "🔙 Batal", callback_data: `arsip_soal` }]
  ];
  
  await smartKeyboardResponse(chatId, msg, keyboard);
  return true;
}

