if (session.action === 'add_kategori') {
    const input = text.trim();
    if (userMessageId) await deleteMessage(chatId, userMessageId);
    
    if (input.toLowerCase() === 'skip' || input.toLowerCase() === 'batal') {
        await clearSession(env, userId);
        let msg = `❌ *DIBATALKAN*\n${DIVIDER}\n\nPenambahan dibatalkan.`;
        const keyboard = [[{ text: "🔙 Kembali ke Menu Kategori", callback_data: "menu_kategori" }]];
        const messageId = session.lastMessageId;
        await smartResponseUniversal(chatId, msg, {
            keyboard,
            mode: 'auto',
            messageId
        });
        return true;
    }
    
    const parsed = parseMultiInput(input);
    if (parsed.error) {
        await smartTextResponse(chatId, `❌ ${parsed.error}\n\nKirim ulang atau "skip":`);
        return true;
    }
    
    const items = [];
    for (const part of parsed.parts) {
        const item = parseItemNamaDesc(part);
        if (!item.nama || item.nama.length < 2) continue;
        items.push(item);
    }
    
    if (items.length === 0) {
        await smartTextResponse(chatId, `❌ Tidak ada item valid. Kirim ulang atau "skip":`);
        return true;
    }
    
    session.tempData = { mode: 'add', items, page: 1 };
    await saveSession(env, userId, session);
    
    const perPage = 5;
    const totalPages = Math.ceil(items.length / perPage);
    const pageItems = items.slice(0, perPage);
    
    let msg = `⚠️ *KONFIRMASI TAMBAH*\n${DIVIDER}\n\n📊 Total : ${items.length} item • Hal 1/${totalPages}\n\n`;
    pageItems.forEach((item, i) => { msg += `${i+1}. 📂 ${item.nama}\n   📝 ${item.deskripsi || '-'}\n\n`; });
    msg += `\nYakin tambah?`;
    
    const keyboard = [];
    if (totalPages > 1) {
        keyboard.push([
            { text: `📄 1/${totalPages}`, callback_data: "noop" },
            { text: "Next ➡️", callback_data: `kat_confirm_page_2` }
        ]);
    }
    keyboard.push([
        { text: `➕ Ya, TAMBAH ${items.length}`, callback_data: "confirm_add_kategori_yes" },
        { text: "❌ Batal", callback_data: "confirm_add_kategori_no" }
    ]);
    
    const messageId = session.lastMessageId;
    await smartResponseUniversal(chatId, msg, {
        keyboard,
        mode: 'auto',
        messageId
    });
    return true;
}

