// ADD SOAL - SESUDAH (DENGAN AUTO-CLASSIFY)
// ============================================================

if (session.action === 'add_soal') {
    const lines = text.split('\n');
    let soalData = {
        soal: '',
        pilihan_a: '',
        pilihan_b: '',
        pilihan_c: '',
        pilihan_d: '',
        pilihan_e: '',
        jawaban_benar: ''
    };
    
    for (let line of lines) {
        line = line.trim();
        if (!line) continue;
        
        if (line.toLowerCase().startsWith('soal:')) {
            soalData.soal = line.substring(5).trim();
            continue;
        }
        
        if (line.match(/^[A-E]\.\s*/)) {
            const letter = line[0].toUpperCase();
            const textValue = line.substring(2).trim();
            if (letter === 'A') soalData.pilihan_a = textValue;
            else if (letter === 'B') soalData.pilihan_b = textValue;
            else if (letter === 'C') soalData.pilihan_c = textValue;
            else if (letter === 'D') soalData.pilihan_d = textValue;
            else if (letter === 'E') soalData.pilihan_e = textValue;
            continue;
        }
        
        if (line.toLowerCase().startsWith('jawaban:')) {
            const jawaban = line.substring(8).trim().toUpperCase();
            if (['A','B','C','D','E'].includes(jawaban)) {
                soalData.jawaban_benar = jawaban;
            }
            continue;
        }
    }
    
    // === VALIDASI ===
    const soalText = soalData.soal.trim();
    if (!soalText) {
        await smartTextResponse(chatId, 
            `❌ *Format tidak valid!*\n\n` +
            `Pastikan formatnya seperti ini:\n\n` +
            `Soal: [teks soal]\n` +
            `A. [pilihan A]\n` +
            `B. [pilihan B]\n` +
            `C. [pilihan C]\n` +
            `D. [pilihan D]\n` +
            `E. [pilihan E]\n` +
            `Jawaban: [A/B/C/D/E]\n\n` +
            `💡 Kirim ulang dengan format yang benar.`
        );
        return true;
    }
    
    const jawaban = soalData.jawaban_benar.toUpperCase().trim();
    if (!['A','B','C','D','E'].includes(jawaban)) {
        await smartTextResponse(chatId, 
            `❌ *Jawaban tidak valid!*\n\n` +
            `Jawaban harus: A, B, C, D, atau E\n\n` +
            `💡 Kirim ulang dengan jawaban yang benar.`
        );
        return true;
    }
    
    try {
        // === AUTO-CLASSIFY LENGKAP (TAPI BELUM DISIMPAN) ===
        const pilihanJawaban = `A. ${soalData.pilihan_a || ''}\nB. ${soalData.pilihan_b || ''}\nC. ${soalData.pilihan_c || ''}\nD. ${soalData.pilihan_d || ''}\nE. ${soalData.pilihan_e || ''}`;
        
        await smartTextResponse(chatId, '⏳ Menganalisis soal dengan AI...');
        
        const classification = await autoClassifyComplete(soalText, pilihanJawaban, db);
        const masterIds = classification.masterIds || {};
        
        // === SIMPAN DATA DI SESSION UNTUK KONFIRMASI ===
        session.action = 'confirm_add_soal';
        session.tempData = {
            soalData: soalData,
            classification: classification,
            masterIds: masterIds,
            originalSoal: soalText,
            step: 'confirm'
        };
        await saveSession(env, userId, session);

        // === TAMPILKAN HASIL KLASIFIKASI UNTUK KONFIRMASI ===
        await showConfirmAddSoal(chatId, session.tempData);
        
    } catch (e) {
        console.error('Add soal error:', e);
        await smartTextResponse(chatId, `❌ Gagal menganalisis soal: ${e.message}`);
        await clearSession(env, userId);
    }
    
    return true;
}

// ============================================================
// 🆕 SHOW CONFIRM ADD SOAL — VERSI FINAL (dengan Jenjang & Kelas)
// Format: ✅ [ KODE ] - Nama
// 10 field hierarki (Kategori s/d Sub-Kemampuan + Jenjang + Kelas)
// ============================================================
async function showConfirmAddSoal(chatId, tempData) {
    const { soalData, classification, masterIds } = tempData;
    const soalText = soalData.soal || '';
    const jawaban = soalData.jawaban_benar || '';
    
    // === VALIDASI ===
    const validation = validateClassificationComplete(classification, masterIds);
    
    // Status soal
    let statusEmoji, statusText;
    if (validation.status === 'AKTIF') {
        statusEmoji = '✅';
        statusText = 'AKTIF';
    } else if (validation.status === 'AKTIF_DENGAN_FALLBACK') {
        statusEmoji = '⚠️';
        statusText = 'AKTIF (dengan fallback)';
    } else {
        statusEmoji = '📝';
        statusText = 'DRAFT';
    }
    
    let confirmMsg = `📋 *KONFIRMASI SIMPAN SOAL*\n\n`;
    confirmMsg += `📝 *Soal:* ${soalText.substring(0, 200)}${soalText.length > 200 ? '...' : ''}\n`;
    confirmMsg += `⭐ *Jawaban:* ${jawaban}\n`;
    confirmMsg += `📌 *Status:* ${statusEmoji} ${statusText}\n\n`;
    
    // ============================================================
    // 🆕 DATA YANG DIBUAT OTOMATIS
    // ============================================================
    if (masterIds.createdItems && masterIds.createdItems.length > 0) {
        confirmMsg += `🆕 *Data baru yang dibuat otomatis:*\n`;
        masterIds.createdItems.slice(0, 8).forEach(item => {
            confirmMsg += `   ${item}\n`;
        });
        if (masterIds.createdItems.length > 8) {
            confirmMsg += `   ... dan ${masterIds.createdItems.length - 8} lainnya\n`;
        }
        confirmMsg += `\n`;
    }
    
    // ============================================================
    // ⚠️ FALLBACK YANG DIGUNAKAN
    // ============================================================
    if (masterIds.fallbackItems && masterIds.fallbackItems.length > 0) {
        confirmMsg += `⚠️ *Fallback yang digunakan:*\n`;
        masterIds.fallbackItems.slice(0, 8).forEach(item => {
            confirmMsg += `   ${item}\n`;
        });
        if (masterIds.fallbackItems.length > 8) {
            confirmMsg += `   ... dan ${masterIds.fallbackItems.length - 8} lainnya\n`;
        }
        confirmMsg += `\n`;
    }
    
    // ============================================================
    // ❌ FIELD YANG MASIH MISSING
    // ============================================================
    if (masterIds.missingItems && masterIds.missingItems.length > 0) {
        confirmMsg += `❌ *Field yang tidak terdeteksi:*\n`;
        masterIds.missingItems.slice(0, 5).forEach(item => {
            confirmMsg += `   ${item}\n`;
        });
        if (masterIds.missingItems.length > 5) {
            confirmMsg += `   ... dan ${masterIds.missingItems.length - 5} lainnya\n`;
        }
        confirmMsg += `\n💡 Field ini akan disimpan sebagai NULL.\n`;
        confirmMsg += `💡 Anda bisa edit klasifikasi setelah ini.\n\n`;
    }
    
    // ============================================================
    // 🆕 HIERARKI PEMBELAJARAN — 10 FIELD
    // (Tambah Jenjang & Kelas di antara Program dan Topik)
    // ============================================================
    confirmMsg += `🏷️ *HIERARKI PEMBELAJARAN:*\n`;
    
    const hierarkiFields = [
        { key: 'kategori',     label: 'Kategori',       id: masterIds.kategoriId,     optional: false },
        { key: 'bidang',       label: 'Bidang Studi',   id: masterIds.bidangId,       optional: false },
        { key: 'program',      label: 'Program Studi',  id: masterIds.programId,      optional: false },
        { key: 'jenjang',      label: 'Jenjang',        id: masterIds.jenjangId,      optional: true  }, // 🆕
        { key: 'kelas',        label: 'Kelas',          id: masterIds.kelas,          optional: true  }, // 🆕
        { key: 'topik',        label: 'Topik',          id: masterIds.topikId,        optional: false },
        { key: 'subtopik',     label: 'Sub-Topik',      id: masterIds.subtopikId,     optional: false },
        { key: 'kisi',         label: 'Kisi-Kisi',      id: masterIds.kisiId,         optional: false },
        { key: 'kemampuan',    label: 'Kemampuan',      id: masterIds.kemampuanId,    optional: false },
        { key: 'subKemampuan', label: 'Sub-Kemampuan',  id: masterIds.subKemampuanId, optional: false }
    ];
    
    for (let i = 0; i < hierarkiFields.length; i++) {
        const field = hierarkiFields[i];
        const value = classification[field.key];
        const isLast = (i === hierarkiFields.length - 1);
        const branch = isLast ? '└─' : '├─';
        
        let status, label;
        
        if (value && field.id) {
            status = '✅';
            label = formatMaster(field.id, value);
        } else if (value && !field.id) {
            status = '⚠️';
            label = `${value} (ID tidak ditemukan)`;
        } else if (field.optional) {
            status = '➖';
            label = '_opsional — belum diisi_';
        } else {
            status = '❌';
            label = 'Belum terdeteksi';
        }
        
        confirmMsg += `${branch} ${field.label}: ${status} ${label}\n`;
    }
    
    confirmMsg += `\n`;
    
    // ============================================================
    // MASTER DATA
    // ============================================================
    confirmMsg += `📋 *MASTER DATA:*\n`;
    
    const cpStatus = masterIds.penyajianId ? '✅' : '❌';
    confirmMsg += `├─ Cara Penyajian: ${cpStatus} ${formatMaster(masterIds.penyajianId, classification.caraPenyajian)}\n`;
    
    const tiStatus = masterIds.tipeIsiId ? '✅' : '❌';
    confirmMsg += `├─ Tipe Isi: ${tiStatus} ${formatMaster(masterIds.tipeIsiId, classification.tipeIsi)}\n`;
    
    const tahapStatus = masterIds.tahapId ? '✅' : '❌';
    confirmMsg += `├─ Tahap: ${tahapStatus} ${formatMaster(masterIds.tahapId, classification.tahap)}\n`;
    
    const prosesKognitif = getStoredCognitive(classification);
    confirmMsg += `├─ Proses Kognitif: ✅ ${prosesKognitif}\n`;
    
    const lapisanStatus = masterIds.lapisanId ? '✅' : '❌';
    confirmMsg += `├─ Lapisan: ${lapisanStatus} ${formatMaster(masterIds.lapisanId, classification.lapisan)}\n`;
    
    if (classification.sumber) {
        const sumberStatus = masterIds.sumberId ? '✅' : '❌';
        confirmMsg += `├─ Sumber: ${sumberStatus} ${formatMaster(masterIds.sumberId, classification.sumber)}\n`;
    } else {
        confirmMsg += `├─ Sumber: ➖ (opsional)\n`;
    }
    
    if (classification.namaSumber) {
        confirmMsg += `├─ Nama Sumber: ✅ ${classification.namaSumber}\n`;
    }
    
    if (classification.link) {
        confirmMsg += `├─ Link: ✅ ${classification.link}\n`;
    } else {
        confirmMsg += `├─ Link: ➖ (opsional)\n`;
    }
    
    const keabsahanLabel = {
        'resmi': '🏛️ Resmi',
        'adaptasi': '🔄 Adaptasi',
        'mandiri': '✏️ Mandiri'
    };
    const keabsahanValue = classification.keabsahan;
    confirmMsg += `└─ Keabsahan: ✅ ${keabsahanLabel[keabsahanValue] || keabsahanValue}\n\n`;
    
    confirmMsg += `📊 *Confidence: ${Math.round((classification.confidence || 0.7) * 100)}%*\n\n`;
    
    // ============================================================
    // RINGKASAN STATUS
    // ============================================================
    const totalCreated = (masterIds.createdItems || []).length;
    const totalFallback = (masterIds.fallbackItems || []).length;
    const totalMissing = (masterIds.missingItems || []).length;
    const totalFound = (masterIds.foundItems || []).length;
    
    if (totalCreated > 0 || totalFallback > 0 || totalMissing > 0) {
        confirmMsg += `📊 *RINGKASAN:*\n`;
        confirmMsg += `   ✅ Ditemukan: ${totalFound}\n`;
        if (totalCreated > 0) confirmMsg += `   🆕 Dibuat baru: ${totalCreated}\n`;
        if (totalFallback > 0) confirmMsg += `   ⚠️ Fallback: ${totalFallback}\n`;
        if (totalMissing > 0) confirmMsg += `   ❌ Missing: ${totalMissing}\n`;
        confirmMsg += `\n`;
    }
    
    confirmMsg += `⚠️ *Pilih tindakan di bawah:*`;
    
    const keyboard = [
        [{ text: "✅ Ya, Simpan", callback_data: "confirm_save_soal_yes" }],
        [{ text: "✏️ Edit Klasifikasi", callback_data: "confirm_save_soal_edit" }],
        [{ text: "📝 Edit Soal", callback_data: "confirm_save_soal_edit_soal" }],
        [{ text: "📖 Keterangan Master", callback_data: "konfirmasi_keterangan" }],
        [{ text: "❌ Batal", callback_data: "confirm_save_soal_no" }]
    ];
    
    await smartKeyboardResponse(chatId, confirmMsg, keyboard);
}

