if (session.action === 'edit_kategori') {
    const input = text.trim();
    if (input.toLowerCase() === 'skip') {
        await smartTextResponse(chatId, '❌ Perubahan dibatalkan.');
        await clearSession(env, userId);
        await smartKeyboardResponse(chatId, `📂 *Kategori*`, buildKategoriMenu());
        return true;
    }
    
    const idMatch = input.match(/^id\s*:\s*(.+)/i);
    const namaMatch = input.match(/^nama\s*:\s*(.+)/i);
    const descMatch = input.match(/^desc\s*:\s*(.+)/i);
    
    try {
        const current = await db.prepare(`SELECT * FROM kategori WHERE id = ?`).bind(session.editId).first();
        if (!current) {
            await smartTextResponse(chatId, '❌ Data tidak ditemukan.');
            await clearSession(env, userId);
            return true;
        }
        
        let newId = current.id, newNama = current.nama, newDesc = current.deskripsi;
        let changes = [];
        
        if (idMatch) {
            newId = idMatch[1].trim().toUpperCase();
            if (!/^[A-Za-z]+[0-9]+$/.test(newId)) {
                await smartTextResponse(chatId, `❌ Format ID tidak valid! Contoh: K001`);
                return true;
            }
            const existing = await db.prepare(`SELECT id FROM kategori WHERE id = ? AND id != ?`)
                .bind(newId, session.editId).first();
            if (existing) {
                await smartTextResponse(chatId, `❌ ID "${newId}" sudah digunakan!`);
                return true;
            }
            changes.push(`ID: ${current.id} → ${newId}`);
        }
        if (namaMatch) {
            newNama = namaMatch[1].trim();
            if (newNama) changes.push(`Nama: "${current.nama}" → "${newNama}"`);
        }
        if (descMatch) {
            newDesc = descMatch[1].trim() || null;
            changes.push(`Deskripsi diperbarui`);
        }
        if (changes.length === 0) {
            await smartTextResponse(chatId, `❌ Format tidak dikenali. Gunakan: id:XXX, nama:XXX, atau desc:XXX`);
            return true;
        }
        
        // ===== UPDATE ATOMIC: RELASI + INDUK =====
        if (newId !== current.id) {
            const result = await updateEntityIdWithRelationsAtomic(db, {
                table: 'kategori', oldId: session.editId, newId,
                relationUpdates: [{ table: 'bidang_studi', field: 'kategori_id' }],
                parentSql: `UPDATE kategori SET id = ?, nama = ?, deskripsi = ? WHERE id = ?`,
                parentParams: [newId, newNama, newDesc, session.editId]
            });
            if (!result.success) throw new Error(result.error);
        } else {
            await db.prepare(`UPDATE kategori SET id = ?, nama = ?, deskripsi = ? WHERE id = ?`)
                .bind(newId, newNama, newDesc, session.editId).run();
        }
        
        let response = `✅ *KATEGORI BERHASIL DIUBAH!*\n\n`;
        changes.forEach(c => response += `- ${c}\n`);
        if (newId !== current.id) {
            response += `\n✅ Relasi di Bidang Studi juga diperbarui.`;
        }
        await smartTextResponse(chatId, response);
    } catch (e) {
        await smartTextResponse(chatId, `❌ Gagal mengubah: ${e.message}`);
    }
    await clearSession(env, userId);
    await smartKeyboardResponse(chatId, `📂 *Kategori*`, buildKategoriMenu());
    return true;
}

