// ============================================================
// HELPER: GET NEXT ENTITY CALLBACK (di luar handler)
// ============================================================
function getNextEntityCallback(entity) {
    const nextMap = {
        kategori: 'bidang',
        bidang: 'program',
        program: 'jenjang',
        // Jenjang bercabang: sekolah -> Kelas, pendidikan tinggi -> Mata Kuliah.
        // Tanpa context cabang, jangan membuat tombol Next yang salah arah.
        jenjang: null,
        kelas: 'mata_pelajaran',
        mata_pelajaran: 'topik',
        mata_kuliah: 'topik',
        topik: 'subtopik',
        subtopik: 'kisi',
        kisi: 'kemampuan',
        kemampuan: 'subkemampuan',
        subkemampuan: null
    };
    const next = nextMap[String(entity || '').toLowerCase()];
    return next ? `menu_ent_${next}` : null;
}

