/**
 * Panduan Tambah — Format Perubahan + Penerapan
 */
function buildPanduanTambah(config) {
    const nameField = config.nameField === 'judul' ? 'Judul' : 'Nama';
    
    let msg = '';
    msg += `📌 *Format Perubahan:*\n\n`;
    msg += `🔹 *Format 1 (Key : Value):*\n`;
    msg += `${nameField} : Contoh\n`;
    msg += `Deskripsi : Isi deskripsi\n\n`;
    msg += `🔸 *Format 2 (Separator ; | ,):*\n`;
    msg += `Contoh; Isi deskripsi\n\n`;
    msg += `🔹 *Format 3 (Baris berurutan):*\n`;
    msg += `Contoh\n`;
    msg += `Isi deskripsi\n\n`;
    msg += `━━━━━━━━━━━━━━━━━━━\n\n`;
    msg += `📌 *Penerapan Single / Multiple:*\n\n`;
    msg += `1️⃣ *SINGLE (1 item):*\n`;
    msg += `${nameField} : Contoh\n`;
    msg += `Deskripsi : Isi deskripsi\n\n`;
    msg += `🔢 *MULTIPLE (2+ item):*\n`;
    msg += `${nameField} : Contoh 1\n`;
    msg += `Deskripsi : Isi 1\n`;
    msg += `---\n`;
    msg += `${nameField} : Contoh 2\n`;
    msg += `Deskripsi : Isi 2\n\n`;
    msg += `💡 Max 50 item per input.\n`;
    msg += `Ketik "skip" untuk batal.`;
    
    return msg;
}

