// ============================================================
// MULTI-SELECT GENERIC ENGINE — BOT ADMIN
// Selection is session-only; database mutation remains in existing handlers.
// ============================================================
const MS_PAGE_SIZE = 5;
const MS_ALLOWED_ACTIONS = new Set(['view','edit','delete','export','generate','move','relation','copy']);

function msState(session, entity) {
    if (!session.multiSelect) session.multiSelect = {};
    if (!session.multiSelect[entity]) session.multiSelect[entity] = { ids: [], page: 1, action: null };
    return session.multiSelect[entity];
}

function msEntityId(data, prefix) {
    return data.startsWith(prefix) ? data.slice(prefix.length) : '';
}

async function renderMultiSelect(env, userId, chatId, db, entity, messageId, page = 1) {
    const config = getEntityConfig(entity);
    if (!config) return false;
    const session = await getSession(env, userId);
    const st = msState(session, entity);
    const count = await db.prepare(`SELECT COUNT(*) AS total FROM ${config.table}`).first();
    const total = Number(count?.total || 0);
    const totalPages = Math.max(1, Math.ceil(total / MS_PAGE_SIZE));
    st.page = Math.min(Math.max(Number(page) || 1, 1), totalPages);
    const offset = (st.page - 1) * MS_PAGE_SIZE;
    const nameField = config.nameField || 'nama';
    const rows = await db.prepare(`SELECT id, ${nameField} AS nama FROM ${config.table} ORDER BY urutan ASC, id ASC LIMIT ? OFFSET ?`).bind(MS_PAGE_SIZE, offset).all();
    const selected = new Set((st.ids || []).map(String));
    let msg = `☑️ *PILIH ${config.labelPlural.toUpperCase()}*\n${DIVIDER}\n\n`;
    msg += `Terpilih: *${selected.size}*\nHalaman: *${st.page}/${totalPages}*\n\n`;
    if (!(rows.results || []).length) msg += 'ℹ️ Belum ada data.\n';
    const keyboard = [];
    for (const r of (rows.results || [])) {
        const mark = selected.has(String(r.id)) ? '☑️' : '☐';
        const label = String(r.nama || r.id).slice(0, 45);
        msg += `${mark} ${r.id} — ${label}\n`;
        keyboard.push([{ text: `${mark} ${String(r.id).slice(0,7)}`, callback_data: `ms:t:${entity}:${r.id}` }]);
    }
    const nav = [];
    if (st.page > 1) nav.push({ text:'⬅️ Prev', callback_data:`ms:p:${entity}:${st.page-1}` });
    nav.push({ text:`📄 ${st.page}/${totalPages}`, callback_data:'noop' });
    if (st.page < totalPages) nav.push({ text:'Next ➡️', callback_data:`ms:p:${entity}:${st.page+1}` });
    if (nav.length) keyboard.push(nav);
    keyboard.push([{ text:'➡️ Lanjut', callback_data:`ms:d:${entity}` }, { text:'🗑️ Reset', callback_data:`ms:c:${entity}` }]);
    keyboard.push([{ text:'🔙 Kembali', callback_data:config.menuCallback }]);
    await saveSession(env, userId, session);
    await smartResponseUniversal(chatId, msg, { keyboard, mode:'auto', messageId });
    return true;
}

async function renderMultiSelectActions(env, userId, chatId, entity, messageId) {
    const config = getEntityConfig(entity);
    if (!config) return false;
    const session = await getSession(env, userId);
    const st = msState(session, entity);
    if (!st.ids.length) {
        await smartResponseUniversal(chatId, '⚠️ Belum ada item yang dipilih.', { keyboard:[[ {text:'🔙 Kembali',callback_data:config.menuCallback} ]], mode:'auto', messageId });
        return true;
    }
    let msg = `📋 *PILIHAN ANDA*\n${DIVIDER}\n\n${config.icon} ${config.labelPlural}: *${st.ids.length}*\n\nPilih tindakan:`;
    const keyboard = [
        [{text:'📋 Lihat',callback_data:`ms:a:${entity}:view`},{text:'✏️ Ubah',callback_data:`ms:a:${entity}:edit`}],
        [{text:'🗑️ Hapus',callback_data:`ms:a:${entity}:delete`},{text:'📤 Ekspor',callback_data:`ms:a:${entity}:export`}],
        [{text:'⚙️ Generate',callback_data:`ms:a:${entity}:generate`},{text:'🔗 Relasi',callback_data:`ms:a:${entity}:relation`}],
        [{text:'🔄 Pindah',callback_data:`ms:a:${entity}:move`},{text:'📑 Salin',callback_data:`ms:a:${entity}:copy`}],
        [{text:'🔙 Kembali',callback_data:`ms:s:${entity}`}]
    ];
    await saveSession(env,userId,session);
    await smartResponseUniversal(chatId,msg,{keyboard,mode:'auto',messageId});
    return true;
}


async function msRenderMoveTargets(env,userId,chatId,db,entity,messageId){
    const config=getEntityConfig(entity);
    if(!config) return false;
    if(!config.parentTable||!config.parentField){
        await smartResponseUniversal(chatId,`⚠️ *${config.label}* tidak memiliki parent sehingga tidak dapat dipindahkan melalui aksi generik.`,{keyboard:[[{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]],mode:'auto',messageId});
        return true;
    }
    const parentEntry=Object.entries(ENTITY_CONFIG).find(([,c])=>c.table===config.parentTable);
    if(!parentEntry){
        await smartResponseUniversal(chatId,'❌ Konfigurasi parent tidak ditemukan.',{keyboard:[[{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]],mode:'auto',messageId});
        return true;
    }
    const parentEntity=parentEntry[0], pc=parentEntry[1];
    const rows=await db.prepare(`SELECT id, ${pc.nameField||'nama'} AS nama FROM ${pc.table} ORDER BY urutan ASC, id ASC LIMIT 50`).all();
    const keyboard=[];
    for(const r of (rows.results||[])) keyboard.push([{text:`↪️ ${String(r.id)}`.slice(0,10),callback_data:`ms:m:${entity}:${r.id}`}]);
    keyboard.push([{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]);
    await smartResponseUniversal(chatId,`🔄 *PINDAH ${getEntityLabel(entity).toUpperCase()}*\n\nPilih parent tujuan untuk ${msState(await getSession(env,userId),entity).ids.length} item.`,{keyboard,mode:'auto',messageId});
    return true;
}

async function msRenderRelationTypes(env,userId,chatId,entity,messageId){
    const types=['TERKAIT','PRASYARAT','LANJUTAN','PENDUKUNG','PENGAYAAN','REMEDIAL','LINTAS_JENJANG','LINTAS_MATA_PELAJARAN','LINTAS_MATA_KULIAH','REUSABLE_MATERIAL'];
    const keyboard=[];
    for(let i=0;i<types.length;i+=2){
        const row=[];
        for(const t of types.slice(i,i+2)) row.push({text:t.replaceAll('_',' ').slice(0,10),callback_data:`ms:r:${entity}:${t}`});
        keyboard.push(row);
    }
    keyboard.push([{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]);
    await smartResponseUniversal(chatId,'🔗 *PILIH JENIS RELASI*\n\nPilih jenis relasi sebelum memilih target.',{keyboard,mode:'auto',messageId});
    return true;
}

async function msRenderRelationTargets(env,userId,chatId,db,sourceEntity,relationType,messageId){
    const keyboard=[];
    for(const [entity,c] of Object.entries(ENTITY_CONFIG)){
        const valid=validateCurriculumRelationInput({sourceType:sourceEntity,sourceId:'__x__',targetType:entity,targetId:'__y__',relationType});
        if(valid.errors.some(e=>e.includes('target_type'))) continue;
        keyboard.push([{text:`${c.icon} ${c.label}`.slice(0,10),callback_data:`ms:e:${sourceEntity}:${relationType}:${entity}`}]);
    }
    keyboard.push([{text:'🔙 Kembali',callback_data:`ms:d:${sourceEntity}`}]);
    await smartResponseUniversal(chatId,`🔗 *TARGET RELASI*\n\nRelasi: *${relationType.replaceAll('_',' ')}*\nPilih jenis entitas target.`,{keyboard,mode:'auto',messageId});
    return true;
}

async function msRenderTargetItems(env,userId,chatId,db,sourceEntity,relationType,targetEntity,messageId){
    const c=getEntityConfig(targetEntity);
    if(!c) return false;
    const validation=validateCurriculumRelationInput({sourceType:sourceEntity,sourceId:'__x__',targetType:targetEntity,targetId:'__y__',relationType});
    if(validation.errors.some(e=>e.includes('target_type'))){
        await smartMessage(chatId,`❌ ${relationType} tidak mendukung target ${targetEntity}.`); return true;
    }
    const rows=await db.prepare(`SELECT id, ${c.nameField||'nama'} AS nama FROM ${c.table} ORDER BY urutan ASC, id ASC LIMIT 50`).all();
    const keyboard=[];
    for(const r of (rows.results||[])) keyboard.push([{text:`🎯 ${String(r.id)}`.slice(0,10),callback_data:`ms:q:${sourceEntity}:${r.id}`}]);
    const session=await getSession(env,userId);
    session.tempData={...(session.tempData||{}),msRelationTarget:{sourceEntity,relationType,targetEntity}};
    await saveSession(env,userId,session);
    keyboard.push([{text:'🔙 Kembali',callback_data:`ms:r:${sourceEntity}:${relationType}`}]);
    await smartResponseUniversal(chatId,`🔗 *PILIH TARGET*\n\n${c.icon} ${c.labelPlural}\nRelasi: ${relationType.replaceAll('_',' ')}`,{keyboard,mode:'auto',messageId});
    return true;
}

async function msRenderConfirm(env,userId,chatId,db,entity,kind,messageId,payload={}){
    const session=await getSession(env,userId), st=msState(session,entity);
    session.tempData={...(session.tempData||{}),msConfirm:{entity,kind,ids:[...st.ids],...payload}};
    await saveSession(env,userId,session);
    let detail='';
    if(kind==='move') detail=`Pindahkan *${st.ids.length} item* ke parent \`${payload.targetId}\`?`;
    else if(kind==='relation') detail=`Buat relasi *${payload.relationType}* dari *${st.ids.length} item* ke \`${payload.targetEntity}:${payload.targetId}\`?`;
    else if(kind==='copy') detail=`Salin *${st.ids.length} item* dengan ID baru?`;
    else if(kind==='generate') detail=`Generate *${payload.count} soal* untuk masing-masing dari *${st.ids.length} item* dengan level *${payload.level}*?`;
    const yes=kind==='generate'?`ms:y:${entity}:generate`:kind==='relation'?`ms:y:${entity}:relation`:kind==='copy'?`ms:y:${entity}:copy`:`ms:y:${entity}:move`;
    const no=`ms:n:${entity}`;
    await smartResponseUniversal(chatId,`⚠️ *KONFIRMASI*\n\n${detail}\n\nBelum ada perubahan sampai Anda menekan Ya.`,{keyboard:[[{text:'✅ Ya',callback_data:yes},{text:'❌ Batal',callback_data:no}],[{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]],mode:'auto',messageId});
    return true;
}

async function msExportSelected(chatId,db,entity,ids){
    const c=getEntityConfig(entity); if(!c) return {success:false,error:'entitas tidak valid'};
    const ph=ids.map(()=>'?').join(',');
    const rows=(await db.prepare(`SELECT * FROM ${c.table} WHERE id IN (${ph}) ORDER BY id ASC`).bind(...ids).all()).results||[];
    if(!rows.length) return {success:false,error:'data tidak ditemukan'};
    const payload=new TextEncoder().encode(JSON.stringify({entity,exported_at:new Date().toISOString(),ids,rows},null,2));
    return await sendFileToTelegram(chatId,payload,`multiselect_${entity}_${Date.now()}.json`,`📤 Export ${c.labelPlural} (${rows.length})`);
}

async function handleMultiSelect(env, userId, data, chatId, db, callbackQueryId) {
    if (!data.startsWith('ms:')) return false;
    await answerCallback(callbackQueryId, '⏳');
    const parts = data.split(':');
    const op = parts[1];
    const entity = (parts[2] || '').toLowerCase();
    const config = getEntityConfig(entity);
    if (!config) { await smartMessage(chatId, '❌ Entitas tidak valid.'); return true; }
    const messageId = getCallbackMessageId();
    const session = await getSession(env, userId);
    const st = msState(session, entity);
    if (op === 's') return await renderMultiSelect(env,userId,chatId,db,entity,messageId,st.page||1);
    if (op === 'p') return await renderMultiSelect(env,userId,chatId,db,entity,messageId,parseInt(parts[3])||1);
    if (op === 'c') { st.ids=[]; st.action=null; st.page=1; await saveSession(env,userId,session); return await renderMultiSelect(env,userId,chatId,db,entity,messageId,1); }
    if (op === 't') {
        const id = parts.slice(3).join(':');
        const exists = await db.prepare(`SELECT id FROM ${config.table} WHERE id = ? LIMIT 1`).bind(id).first();
        if (!exists) { await smartMessage(chatId, `❌ ${config.label} ${id} tidak ditemukan.`); return true; }
        const ids = new Set((st.ids||[]).map(String));
        if (!ids.has(String(id)) && ids.size >= 50) {
            await smartMessage(chatId, `⚠️ Maksimal 50 item dapat dipilih sekaligus.`);
            return true;
        }
        ids.has(String(id)) ? ids.delete(String(id)) : ids.add(String(id));
        st.ids = [...ids];
        await saveSession(env,userId,session);
        return await renderMultiSelect(env,userId,chatId,db,entity,messageId,st.page||1);
    }
    if (op === 'd') {
        if (st.ids?.length) {
            const ph = st.ids.map(()=>'?').join(',');
            const existing = (await db.prepare(`SELECT id FROM ${config.table} WHERE id IN (${ph})`).bind(...st.ids).all()).results || [];
            const validIds = new Set(existing.map(r=>String(r.id)));
            const cleaned = st.ids.filter(id=>validIds.has(String(id)));
            if (cleaned.length !== st.ids.length) { st.ids = cleaned; await saveSession(env,userId,session); }
        }
        return await renderMultiSelectActions(env,userId,chatId,entity,messageId);
    }
    if (op === 'b') return await renderMultiSelect(env,userId,chatId,db,entity,messageId,st.page||1);
    if (op === 'a') {
        const action = parts[3];
        if (!MS_ALLOWED_ACTIONS.has(action)) { await smartMessage(chatId,'❌ Aksi tidak valid.'); return true; }
        if (!st.ids.length) { await smartMessage(chatId,'⚠️ Belum ada item yang dipilih.'); return true; }
        st.action = action;
        // Reuse existing business logic where a compatible handler exists.
        if (action === 'delete') {
            const nameField = config.nameField || 'nama';
            const placeholders = st.ids.map(()=>'?').join(',');
            const q = await db.prepare(`SELECT id, ${nameField} AS nama FROM ${config.table} WHERE id IN (${placeholders})`).bind(...st.ids).all();
            st.ids = (q.results||[]).map(x=>String(x.id));
            session.tempData = { entity, items:(q.results||[]).map(x=>({id:x.id,nama:x.nama,notFound:false})), page:1 };
            session.action = `ent_delete_input_${entity}`;
            await saveSession(env,userId,session);
            return await handleCallback(env,userId,`ent_delete_confirm_page_${entity}_1`,chatId,callbackQueryId,null);
        }
        if (action === 'view') {
            const nameField = config.nameField || 'nama';
            const placeholders = st.ids.map(()=>'?').join(',');
            const q = await db.prepare(`SELECT * FROM ${config.table} WHERE id IN (${placeholders}) ORDER BY urutan ASC, id ASC`).bind(...st.ids).all();
            let msg = `📋 *DETAIL PILIHAN*\n${DIVIDER}\n\n`;
            for (const row of (q.results || [])) {
                msg += `${config.icon} *${row[nameField] || row.id}*\n`;
                msg += `🆔 ID: \`${row.id}\`\n`;
                if (row.deskripsi) msg += `📝 ${String(row.deskripsi).slice(0,180)}\n`;
                msg += `\n`;
            }
            await smartResponseUniversal(chatId,msg,{keyboard:[[ {text:'🔙 Kembali',callback_data:`ms:d:${entity}`} ]],mode:'auto',messageId});
            return true;
        }
        if (action === 'edit') {
            // Bridge ke parser/edit lama: ID yang dipilih disimpan sebagai konteks,
            // sehingga pengguna tidak perlu memilih ulang dari menu entitas.
            const selectedIds = [...st.ids];
            session.tempData = { entity, selectedIds, multiSelectEdit: true };
            session.action = `ent_edit_input_${entity}`;
            await saveSession(env,userId,session);
            const idList = selectedIds.map((id,i)=>`${i+1}. ${id}`).join('\n');
            await smartResponseUniversal(chatId,
                `✏️ *UBAH ${config.labelPlural.toUpperCase()}*\n${DIVIDER}\n\n`+
                `Item terpilih:\n${idList}\n\n`+
                `Kirim perubahan. Jika hanya berisi Nama/Deskripsi tanpa ID, perubahan akan diterapkan berurutan ke item terpilih.\n\n`+
                buildPanduanEdit(config),
                {keyboard:[[ {text:'🔙 Kembali',callback_data:`ms:d:${entity}`} ]],mode:'auto',messageId});
            return true;
        }
        if(action==='export') {
            const r=await msExportSelected(chatId,db,entity,st.ids);
            if(!r.success) await smartResponseUniversal(chatId,`❌ Export gagal: ${r.error}`,{keyboard:[[{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]],mode:'auto',messageId});
            else await smartResponseUniversal(chatId,`✅ *EXPORT SELESAI*\n\n${st.ids.length} item berhasil diekspor.`,{keyboard:[[{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]],mode:'auto',messageId});
            return true;
        }
        if(action==='move') return await msRenderMoveTargets(env,userId,chatId,db,entity,messageId);
        if(action==='relation') return await msRenderRelationTypes(env,userId,chatId,entity,messageId);
        if(action==='copy') return await msRenderConfirm(env,userId,chatId,db,entity,'copy',messageId);
        if(action==='generate') {
            if(!['topik','kisi','kemampuan','subkemampuan'].includes(entity)) {
                await smartResponseUniversal(chatId,`⚠️ Generate soal melalui Multi-Select saat ini hanya mendukung Topik, Kisi-Kisi, Kemampuan, dan Sub-Kemampuan.`,{keyboard:[[{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]],mode:'auto',messageId}); return true;
            }
            session.tempData={...(session.tempData||{}),msGenerate:{entity,ids:[...st.ids]}};
            await saveSession(env,userId,session);
            await smartResponseUniversal(chatId,'⚙️ *PARAMETER GENERATE*\n\nPilih level dan jumlah soal per item.',{keyboard:[[{text:'Mudah 3',callback_data:`ms:g:${entity}:mudah:3`},{text:'Sedang 3',callback_data:`ms:g:${entity}:sedang:3`}],[{text:'Sulit 3',callback_data:`ms:g:${entity}:sulit:3`},{text:'Sedang 5',callback_data:`ms:g:${entity}:sedang:5`}],[{text:'Sedang 10',callback_data:`ms:g:${entity}:sedang:10`}],[{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]],mode:'auto',messageId});
            return true;
        }
        await smartResponseUniversal(chatId,`❌ Aksi ${action} belum memiliki dispatcher aman.`,{keyboard:[[ {text:'🔙 Kembali',callback_data:`ms:d:${entity}`} ]],mode:'auto',messageId});
        return true;
    }

    if(op==='m'){
        const targetId=parts.slice(3).join(':');
        const c=getEntityConfig(entity);
        const exists=await db.prepare(`SELECT id FROM ${c.parentTable} WHERE id=? LIMIT 1`).bind(targetId).first();
        if(!exists){await smartMessage(chatId,`❌ Parent ${targetId} tidak ditemukan.`);return true;}
        return await msRenderConfirm(env,userId,chatId,db,entity,'move',messageId,{targetId});
    }
    if(op==='r'){
        const relationType=parts[3];
        if(parts.length===4) return await msRenderRelationTargets(env,userId,chatId,entity,relationType,messageId);
        const targetEntity=parts[4];
        return await msRenderTargetItems(env,userId,chatId,db,entity,relationType,targetEntity,messageId);
    }
    if(op==='e') return await msRenderTargetItems(env,userId,chatId,db,entity,parts[3],parts[4],messageId);
    if(op==='q'){
        const relationCtx=session.tempData?.msRelationTarget;
        const sourceEntityCtx=parts[2];
        const targetId=parts.slice(3).join(':');
        if(!relationCtx||relationCtx.sourceEntity!==sourceEntityCtx){await smartMessage(chatId,'❌ Konteks relasi sudah tidak valid.');return true;}
        const relationType=relationCtx.relationType, targetEntity=relationCtx.targetEntity;
        const tc=getEntityConfig(targetEntity);
        const exists=tc ? await db.prepare(`SELECT id FROM ${tc.table} WHERE id=? LIMIT 1`).bind(targetId).first() : null;
        if(!exists){await smartMessage(chatId,`❌ Target ${targetId} tidak ditemukan.`);return true;}
        return await msRenderConfirm(env,userId,chatId,db,entity,'relation',messageId,{relationType,targetEntity,targetId});
    }
    if(op==='g'){
        const level=parts[3]||'sedang', count=Math.min(10,Math.max(1,parseInt(parts[4])||3));
        return await msRenderConfirm(env,userId,chatId,db,entity,'generate',messageId,{level,count});
    }
    if(op==='y'){
        const confirm=session.tempData?.msConfirm;
        if(!confirm||confirm.entity!==entity){await smartMessage(chatId,'❌ Konfirmasi sudah tidak valid.');return true;}
        if(confirm.kind==='move'){
            const c=getEntityConfig(entity); if(!c?.parentField||!c.parentTable){await smartMessage(chatId,'❌ Entitas tidak dapat dipindahkan.');return true;}
            let changed=0;
            for(const id of confirm.ids){const r=await db.prepare(`UPDATE ${c.table} SET ${c.parentField}=? WHERE id=?`).bind(confirm.targetId,id).run(); changed+=Number(r.meta?.changes||0);}
            delete session.tempData.msConfirm; await saveSession(env,userId,session);
            await smartResponseUniversal(chatId,`✅ *PINDAH SELESAI*\\n\\n${changed} item dipindahkan ke parent \`${confirm.targetId}\`.`,{keyboard:[[{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]],mode:'auto',messageId}); return true;
        }
        if(confirm.kind==='relation'){
            let ok=0,fail=0;
            for(const id of confirm.ids){const r=await createCurriculumRelation(db,{sourceType:entity,sourceId:id,relationType:confirm.relationType,targetType:confirm.targetEntity,targetId:confirm.targetId,userId}); r.success?ok++:fail++;}
            delete session.tempData.msConfirm; await saveSession(env,userId,session);
            await smartResponseUniversal(chatId,`✅ *RELASI SELESAI*\\n\\nBerhasil: ${ok}\\nGagal: ${fail}`,{keyboard:[[{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]],mode:'auto',messageId}); return true;
        }
        if(confirm.kind==='copy'){
            const c=getEntityConfig(entity); const ph=confirm.ids.map(()=>'?').join(',');
            const rows=(await db.prepare(`SELECT * FROM ${c.table} WHERE id IN (${ph})`).bind(...confirm.ids).all()).results||[];
            const cols=(await db.prepare(`PRAGMA table_info(${c.table})`).all()).results||[]; const writable=cols.filter(x=>Number(x.pk)!==1).map(x=>x.name);
            let copied=0;
            for(const row of rows){
                const newId=await generateId(db,c.prefix,c.table);
                const vals=writable.map(col=>col===c.nameField?`${String(row[col]??'')} (Salinan)`:col==='normalized_nama'?String(row[c.nameField]||'').toLowerCase().trim()+' salinan':col==='created_at'||col==='updated_at'?new Date().toISOString():col==='created_by'||col==='updated_by'?userId:row[col]);
                const candidate={id:newId}; writable.forEach((col,i)=>candidate[col]=vals[i]);
                const constraintCheck=await validateImportConstraints(db,c.table,[candidate]);
                if(!constraintCheck.success) throw new Error(`Salin ${row.id} dibatalkan: ${constraintCheck.errors.slice(0,3).join(' | ')}`);
                await db.prepare(`INSERT INTO ${c.table} (id,${writable.join(',')}) VALUES (?,${writable.map(()=>'?').join(',')})`).bind(newId,...vals).run(); copied++;
            }
            delete session.tempData.msConfirm; await saveSession(env,userId,session);
            await smartResponseUniversal(chatId,`✅ *SALIN SELESAI*\\n\\n${copied} item berhasil disalin.`,{keyboard:[[{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]],mode:'auto',messageId}); return true;
        }
        if(confirm.kind==='generate'){
            let ok=0,fail=0;
            for(const id of confirm.ids){
                const payload={level:confirm.level,count:confirm.count};
                if(entity==='topik') payload.topicId=id; else if(entity==='kemampuan') payload.kemampuanId=id; else if(entity==='kisi') payload.kisiId=id; else if(entity==='subkemampuan') payload.subKemampuanId=id;
                try{await handleAIGenerateSoalFull(env,userId,chatId,db,payload);ok++;}catch(e){fail++;console.error('ms generate:',e);}
            }
            delete session.tempData.msConfirm; await saveSession(env,userId,session);
            await smartResponseUniversal(chatId,`✅ *GENERATE SELESAI*\\n\\nDiproses: ${ok}\\nGagal: ${fail}`,{keyboard:[[{text:'🔙 Kembali',callback_data:`ms:d:${entity}`}]],mode:'auto',messageId}); return true;
        }
    }
    if(op==='n'){ delete session.tempData?.msConfirm; delete session.tempData?.msGenerate; await saveSession(env,userId,session); return await renderMultiSelectActions(env,userId,chatId,entity,messageId); }
    return true;
}

// ============================================================
