if (data.startsWith('menu_ent_')) {
    const entity=data.replace('menu_ent_','').toLowerCase(),config=getEntityConfig(entity);
    if(!config){await smartMessage(chatId,`❌ Entitas "${entity}" tidak dikenal.`);return true;}
    callbackSession.uiBack='nav:h';await saveSession(env,userId,callbackSession);
    await smartResponseUniversal(chatId,`${config.icon} *${config.label.toUpperCase()}*\n\nMenu ini digunakan untuk melihat, menambah, mengubah, menghapus, dan mengatur urutan ${config.label}.`,{keyboard:buildEntityContextMenu(entity),mode:'auto',messageId:getCallbackMessageId()});return true;
}

if(data.startsWith('ent_view_')){
 const rest=data.slice(9),entity=Object.keys(ENTITY_CONFIG).sort((a,b)=>b.length-a.length).find(k=>rest===k||rest.startsWith(k+'_'));
 if(!entity){await smartMessage(chatId,'❌ Entitas tidak dikenali.');return true;} const id=rest.slice(entity.length+1),config=getEntityConfig(entity);
 if(!config||!id){await smartMessage(chatId,'❌ ID tidak valid.');return true;} const row=await db.prepare(`SELECT * FROM ${config.table} WHERE id=? LIMIT 1`).bind(id).first();
 if(!row){await smartMessage(chatId,`❌ ${config.label} dengan ID ${id} tidak ditemukan.`);return true;} const nf=config.nameField||'nama';
 let msg=`${config.icon} *DETAIL ${config.label.toUpperCase()}*\n${DIVIDER}\n\n🆔 ID: ${row.id}\n📌 ${config.label}: ${row[nf]??'-'}\n`; if(row.deskripsi!=null)msg+=`📝 Deskripsi: ${row.deskripsi||'-'}\n`;
 await smartResponseUniversal(chatId,msg,{keyboard:[[{text:'✏️ Ubah',callback_data:`ent_edit_form_${entity}_${id}`},{text:'🗑️ Hapus',callback_data:`ent_delete_confirm_${entity}_${id}`}],[{text:'🔙 Kembali',callback_data:`ent_list_${entity}`}]],mode:'auto',messageId:getCallbackMessageId()});return true;
}

// ============================================================
// HANDLER: LOMPAT KE ENTITAS (GENERIC)// ============================================================
// HANDLER: LOMPAT KE ENTITAS (GENERIC)
// ============================================================
if (data.startsWith('ent_jump_')) {
    const entity = data.replace('ent_jump_', '').toLowerCase();
    const config = getEntityConfig(entity);
    
    if (!config) {
        await smartMessage(chatId, `❌ Entitas "${entity}" tidak dikenal.`);
        return true;
    }
    
    const messageId = getCallbackMessageId();
    let msg = `🔷 *LOMPAT KE ENTITAS*\n${DIVIDER}\n\n`;
    msg += `Dari: ${config.icon} ${config.label}\n\n`;
    msg += `Pilih entitas tujuan:`;
    
    const keyboard = [];
    const allKeys = Object.keys(ENTITY_CONFIG);
    const buttons = [];
    
    for (const key of allKeys) {
        if (key === entity) continue;
        const c = ENTITY_CONFIG[key];
        buttons.push({
            text: `${c.icon} ${c.label}`,
            callback_data: `menu_ent_${key}`
        });
    }
    
    for (let i = 0; i < buttons.length; i += 2) {
        const row = [buttons[i]];
        if (buttons[i + 1]) row.push(buttons[i + 1]);
        keyboard.push(row);
    }
    
    keyboard.push([{ text: "🔙 Kembali", callback_data: config.menuCallback }]);
    
    await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId });
    return true;
}

// ============================================================
if(data.endsWith('_jump')&&data.startsWith('ent_list_')){const entity=data.slice(9,-5),config=getEntityConfig(entity);if(config){const session=await getSession(env,userId);session.action=`ent_list_jump_${entity}`;session.lastMessageId=getCallbackMessageId();await saveSession(env,userId,session);const count=await db.prepare(`SELECT COUNT(*) AS total FROM ${config.table}`).first(),totalPages=Math.max(1,Math.ceil((count?.total||0)/getEntityPageSize(entity)));await smartResponseUniversal(chatId,`📄 *LOMPAT KE HALAMAN*\n${DIVIDER}\n\nTotal halaman: *${totalPages}*\n\nKetik nomor halaman (1-${totalPages}) atau "batal".`,{keyboard:[[{text:'🔙 Batal',callback_data:config.menuCallback}]],mode:'auto',messageId:getCallbackMessageId()});return true;}}

// HANDLER: ENT_LIST — LIST
// ============================================================
if (data.startsWith('ent_list_') && !data.includes('_page_') && !data.endsWith('_jump')) {
    const entity = data.replace('ent_list_', '').toLowerCase();
    const config = getEntityConfig(entity);
    
    if (!config) {
        await smartMessage(chatId, `❌ Entitas "${entity}" tidak dikenal.`);
        return true;
    }
    
    try {
        await handleEntityList(env, userId, chatId, entity, 1, true);
    } catch (e) {
        console.error(`ent_list_${entity} error:`, e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
    }
    return true;
}

// ============================================================
// HANDLER: ENT_LIST — PAGINATION
// ============================================================
if (data.match(/^ent_list_[a-z]+_page_\d+$/)) {
    const match = data.match(/^ent_list_([a-z]+)_page_(\d+)$/);
    if (match) {
        const entity = match[1];
        const page = parseInt(match[2]) || 1;
        const config = getEntityConfig(entity);
        
        if (!config) {
            await smartMessage(chatId, `❌ Entitas "${entity}" tidak dikenal.`);
            return true;
        }
        
        try {
            await handleEntityList(env, userId, chatId, entity, page, true);
        } catch (e) {
            console.error(`ent_list pagination error:`, e);
            await smartMessage(chatId, `❌ Error: ${e.message}`);
        }
    }
    return true;
}

