if (data.startsWith('ent_add_mp_kelas_')) {
    const rest = data.replace('ent_add_mp_kelas_', '');
    const parts = rest.split('_');
    if (parts.length < 3) {
        await smartMessage(chatId, '❌ Konteks Mata Pelajaran tidak lengkap.');
        return true;
    }
    const [bidangId, jenjangId, ...kelasParts] = parts;
    const kelasId = kelasParts.join('_');
    const row = await db.prepare(`
        SELECT k.id, k.nama, j.id AS jenjang_id, j.nama AS jenjang_nama, j.jenis
        FROM kelas k JOIN jenjang j ON j.id = k.jenjang_id
        WHERE k.id = ? AND k.jenjang_id = ? LIMIT 1
    `).bind(kelasId, jenjangId).first();
    if (!row || !['SD','SMP','SMA','SMK'].includes(String(row.jenis || '').toUpperCase())) {
        await smartMessage(chatId, '❌ Kelas atau Jenjang sekolah tidak valid.');
        return true;
    }
    const bidang = await db.prepare(`SELECT nama FROM bidang_studi WHERE id = ? LIMIT 1`).bind(bidangId).first();
    const session = await getSession(env, userId);
    session.action = 'ent_add_input_mata_pelajaran';
    session.tempData = {
        entity: 'mata_pelajaran',
        parentId: kelasId,
        parentName: row.nama,
        bidangId,
        bidangName: bidang?.nama || bidangId,
        jenjangId,
        jenjangName: row.jenjang_nama
    };
    session.lastMessageId = getCallbackMessageId();
    await saveSession(env, userId, session);
    const msg = `➕ *TAMBAH MATA PELAJARAN*\n${DIVIDER}\n\n` +
        `📚 Bidang: *${bidang?.nama || bidangId}*\n` +
        `🏫 Jenjang: *${row.jenjang_nama}* (${row.jenis})\n` +
        `📖 Kelas: *${row.nama}*\n\n` +
        `Ketik data Mata Pelajaran:\n\n${buildPanduanTambah(ENTITY_CONFIG.mata_pelajaran)}`;
    await smartResponseUniversal(chatId, msg, {
        keyboard: [[{ text: '🔙 Kembali', callback_data: `ent_add_mp_jenjang_${bidangId}_${jenjangId}` }]],
        mode: 'auto', messageId: session.lastMessageId
    });
    return true;
}

// ============================================================
// SPECIAL ADMIN FLOW — MATA KULIAH
// Kategori → Bidang → Program Studi → Jenjang → Mata Kuliah
// Semester adalah atribut Mata Kuliah.
// ============================================================
if (data === 'ent_add_mata_kuliah') {
    const rows = await db.prepare(`
        SELECT id, nama FROM bidang_studi
        ORDER BY urutan ASC, nama ASC
    `).all();
    const items = rows.results || [];
    const keyboard = items.map(r => [{ text: `📚 ${r.id} - ${r.nama}`, callback_data: `ent_add_mk_bidang_${r.id}` }]);
    keyboard.push([{ text: '🔙 Kembali', callback_data: 'menu_ent_mata_kuliah' }]);
    await smartResponseUniversal(chatId, `➕ *TAMBAH MATA KULIAH*\n${DIVIDER}\n\nPilih *Bidang Studi*:`, {
        keyboard, mode: 'auto', messageId: getCallbackMessageId()
    });
    return true;
}

if (data.startsWith('ent_add_mk_bidang_')) {
    const bidangId = data.replace('ent_add_mk_bidang_', '');
    const bidang = await db.prepare(`SELECT id, nama FROM bidang_studi WHERE id = ? LIMIT 1`).bind(bidangId).first();
    if (!bidang) { await smartMessage(chatId, '❌ Bidang Studi tidak ditemukan.'); return true; }
    const rows = await db.prepare(`
        SELECT id, nama FROM program_studi
        WHERE bidang_studi_id = ?
        ORDER BY urutan ASC, nama ASC
    `).bind(bidangId).all();
    const items = rows.results || [];
    const keyboard = items.map(r => [{ text: `🎓 ${r.id} - ${r.nama}`, callback_data: `ent_add_mk_program_${bidangId}_${r.id}` }]);
    keyboard.push([{ text: '🔙 Kembali', callback_data: 'ent_add_mata_kuliah' }]);
    await smartResponseUniversal(chatId, `➕ *TAMBAH MATA KULIAH*\n${DIVIDER}\n\n📚 Bidang: *${bidang.nama}*\n\nPilih *Program Studi*:`, {
        keyboard, mode: 'auto', messageId: getCallbackMessageId()
    });
    return true;
}

if (data.startsWith('ent_add_mk_program_')) {
    const rest = data.replace('ent_add_mk_program_', '');
    const sep = rest.indexOf('_');
    const bidangId = sep >= 0 ? rest.slice(0, sep) : rest;
    const programId = sep >= 0 ? rest.slice(sep + 1) : '';
    const program = await db.prepare(`
        SELECT p.id, p.nama, p.bidang_studi_id, b.nama AS bidang_nama
        FROM program_studi p JOIN bidang_studi b ON b.id = p.bidang_studi_id
        WHERE p.id = ? AND p.bidang_studi_id = ? LIMIT 1
    `).bind(programId, bidangId).first();
    if (!program) { await smartMessage(chatId, '❌ Program Studi tidak valid.'); return true; }
    const rows = await db.prepare(`
        SELECT id, nama, jenis FROM jenjang
        WHERE is_active = 1 AND UPPER(jenis) IN ('D3','D4','S1','S2','S3')
        ORDER BY urutan ASC, id ASC
    `).all();
    const items = rows.results || [];
    const keyboard = items.map(r => [{ text: `🏫 ${r.id} - ${r.nama} (${r.jenis})`, callback_data: `ent_add_mk_jenjang_${bidangId}_${programId}_${r.id}` }]);
    keyboard.push([{ text: '🔙 Kembali', callback_data: `ent_add_mk_bidang_${bidangId}` }]);
    await smartResponseUniversal(chatId, `➕ *TAMBAH MATA KULIAH*\n${DIVIDER}\n\n📚 Bidang: *${program.bidang_nama}*\n🎓 Program: *${program.nama}*\n\nPilih *Jenjang Pendidikan Tinggi*:`, {
        keyboard, mode: 'auto', messageId: getCallbackMessageId()
    });
    return true;
}

if (data.startsWith('ent_add_mk_jenjang_')) {
    const rest = data.replace('ent_add_mk_jenjang_', '');
    const parts = rest.split('_');
    if (parts.length < 3) { await smartMessage(chatId, '❌ Konteks Mata Kuliah tidak lengkap.'); return true; }
    const [bidangId, programId, ...jenjangParts] = parts;
    const jenjangId = jenjangParts.join('_');
    const row = await db.prepare(`
        SELECT j.id, j.nama, j.jenis, p.id AS program_id, p.nama AS program_nama, b.nama AS bidang_nama
        FROM jenjang j
        JOIN program_studi p ON p.id = ?
        JOIN bidang_studi b ON b.id = p.bidang_studi_id
        WHERE j.id = ? AND p.bidang_studi_id = ?
          AND UPPER(j.jenis) IN ('D3','D4','S1','S2','S3') LIMIT 1
    `).bind(programId, jenjangId, bidangId).first();
    if (!row) { await smartMessage(chatId, '❌ Jenjang atau Program Studi tidak valid.'); return true; }
    const session = await getSession(env, userId);
    session.action = 'ent_add_input_mata_kuliah';
    session.tempData = {
        entity: 'mata_kuliah',
        parentId: programId,
        parentName: row.program_nama,
        bidangId,
        bidangName: row.bidang_nama,
        programId,
        programName: row.program_nama,
        jenjangId,
        jenjangName: row.nama
    };
    session.lastMessageId = getCallbackMessageId();
    await saveSession(env, userId, session);
    const msg = `➕ *TAMBAH MATA KULIAH*\n${DIVIDER}\n\n` +
        `📚 Bidang: *${row.bidang_nama}*\n` +
        `🎓 Program: *${row.program_nama}*\n` +
        `🏫 Jenjang: *${row.nama}* (${row.jenis})\n\n` +
        `Ketik dengan format:\n*Nama ; Semester ; Kode*\n\n` +
        `Contoh: *Fisika Dasar I ; 1 ; FIS101*\n` +
        `Semester wajib 1–14. Kode boleh dikosongkan.\nKetik "batal" untuk membatalkan.`;
    await smartResponseUniversal(chatId, msg, {
        keyboard: [[{ text: '🔙 Kembali', callback_data: `ent_add_mk_program_${bidangId}_${programId}` }]],
        mode: 'auto', messageId: session.lastMessageId
    });
    return true;
}

// HANDLER: ENT_ADD — PANDUAN + LIST PARENT
// ============================================================
if (data.startsWith('ent_add_') && 
    !data.startsWith('ent_add_parent_') && 
    !data.startsWith('ent_add_confirm_') && 
    !data.startsWith('ent_add_page_') && 
    !data.startsWith('ent_add_jump_')) {
    
    const entity = data.replace('ent_add_', '').toLowerCase();
    const config = getEntityConfig(entity);
    
    if (!config) {
        await smartMessage(chatId, `❌ Entitas "${entity}" tidak dikenal.`);
        return true;
    }
    
    if (!config.parentField) {
        const session = await getSession(env, userId);
        session.action = `ent_add_input_${entity}`;
        session.tempData = { entity };
        session.lastMessageId = getCallbackMessageId();
        await saveSession(env, userId, session);
        
        const nameField = config.nameField || 'nama';
        const count = await db.prepare(`SELECT COUNT(*) AS total FROM ${config.table}`).first();
        const totalItems = count?.total || 0;
        const totalPages = Math.ceil(totalItems / 5) + 1;
        
        const messageId = getCallbackMessageId();
        let msg = `➕ *TAMBAH ${config.label.toUpperCase()}*\n${DIVIDER}\n\n`;
        msg += `Ketik data ${config.label}:\n\n`;
        msg += buildPanduanTambah(config);
        
        const keyboard = [];
        const navButtons = [{ text: `📄 1/${totalPages}`, callback_data: `ent_add_page_jump_${entity}` }];
        if (totalPages > 1) {
            navButtons.push({ text: "Next ➡️", callback_data: `ent_add_page_${entity}_2` });
        }
        keyboard.push(navButtons);
        keyboard.push([{ text: `🔙 Kembali`, callback_data: config.menuCallback }]);
        
        await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId });
        return true;
    }
    
    try {
        const parentConfig = ENTITY_CONFIG[config.parentTable];
        const parentNameField = parentConfig.nameField || 'nama';
        
        const r = await db.prepare(`
            SELECT id, ${parentNameField} AS nama 
            FROM ${config.parentTable} 
            ORDER BY urutan ASC, id ASC LIMIT 30
        `).all();
        
        const hasil = (r && r.results) ? r.results : [];
        
        if (hasil.length === 0) {
            await smartMessage(chatId, 
                `❌ Belum ada ${parentConfig.label}.\n\n` +
                `💡 Buat ${parentConfig.label} dulu di menu ${parentConfig.label}.`
            );
            return true;
        }
        
        const messageId = getCallbackMessageId();
        let msg = `➕ *TAMBAH ${config.label.toUpperCase()}*\n${DIVIDER}\n\n`;
        msg += `Pilih ${config.parentLabel}:\n\n`;
        
        const keyboard = [];
        hasil.forEach(p => {
            keyboard.push([{
                text: `${p.id} - ${p.nama}`,
                callback_data: `ent_add_parent_${entity}_${p.id}`
            }]);
        });
        keyboard.push([{ text: "🔙 Kembali", callback_data: config.menuCallback }]);
        
        await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId });
    } catch (e) {
        console.error(`ent_add_${entity} error:`, e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
    }
    return true;
}

// ============================================================
// LEGACY COMPATIBILITY BRIDGE — PROGRAM_BIDANG
// program_bidang_<bidangId> -> canonical ent_add_parent_program_<bidangId>
// ============================================================
if (data.startsWith('program_bidang_')) {
    const bidangId = data.replace('program_bidang_', '');
    data = `ent_add_parent_program_${bidangId}`;
}

// ============================================================
// LEGACY COMPATIBILITY BRIDGE — TOPIK_PROGRAM
// topik_program_<programId> -> canonical ent_add_parent_topik_<programId>
// ============================================================
if (data.startsWith('topik_program_')) {
    const programId = data.replace('topik_program_', '');
    data = `ent_add_parent_topik_${programId}`;
}

// ============================================================
// HANDLER: ENT_ADD_PARENT — SETELAH PILIH PARENT
// ============================================================
if (data.startsWith('ent_add_parent_')) {
    const rest = data.replace('ent_add_parent_', '');
    const parts = rest.split('_');
    const entity = parts[0];
    const parentId = parts.slice(1).join('_');
    
    const config = getEntityConfig(entity);
    if (!config) {
        await smartMessage(chatId, `❌ Entitas "${entity}" tidak dikenal.`);
        return true;
    }
    
    const parentConfig = ENTITY_CONFIG[config.parentTable];
    const parentNameField = parentConfig.nameField || 'nama';
    let parentName = parentId;
    try {
        const p = await db.prepare(`SELECT ${parentNameField} AS nama FROM ${config.parentTable} WHERE id = ? LIMIT 1`).bind(parentId).first();
        if (p) parentName = p.nama;
    } catch (e) {}
    
    const session = await getSession(env, userId);
    session.action = `ent_add_input_${entity}`;
    session.tempData = { entity, parentId, parentName };
    session.lastMessageId = getCallbackMessageId();
    await saveSession(env, userId, session);
    
    const nameField = config.nameField || 'nama';
    const count = await db.prepare(`SELECT COUNT(*) AS total FROM ${config.table}`).first();
    const totalItems = count?.total || 0;
    const totalPages = Math.ceil(totalItems / 5) + 1;
    
    const messageId = getCallbackMessageId();
    let msg = `➕ *TAMBAH ${config.label.toUpperCase()}*\n${DIVIDER}\n\n`;
    msg += `📂 ${config.parentLabel}: *${parentName}*\n\n`;
    msg += `Ketik data ${config.label}:\n\n`;
    msg += buildPanduanTambah(config);
    
    const keyboard = [];
    const navButtons = [{ text: `📄 1/${totalPages}`, callback_data: `ent_add_page_jump_${entity}` }];
    if (totalPages > 1) {
        navButtons.push({ text: "Next ➡️", callback_data: `ent_add_page_${entity}_2` });
    }
    keyboard.push(navButtons);
    keyboard.push([{ text: `🔙 Kembali`, callback_data: config.menuCallback }]);
    
    await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId });
    return true;
}

// ============================================================
// HANDLER: ENT_ADD_PAGE_N — HALAMAN 2+ (LIST EXISTING)
// ============================================================
if (data.match(/^ent_add_page_[a-z]+_\d+$/)) {
    const match = data.match(/^ent_add_page_([a-z]+)_(\d+)$/);
    if (match) {
        const entity = match[1];
        const page = parseInt(match[2]) || 1;
        const config = getEntityConfig(entity);
        
        if (!config) {
            await smartMessage(chatId, `❌ Entitas "${entity}" tidak dikenal.`);
            return true;
        }
        
        if (page === 1) {
            await handleCallback(env, userId, `ent_add_${entity}`, chatId, '', null);
            return true;
        }
        
        const session = await getSession(env, userId);
        session.action = `ent_add_input_${entity}`;
        session.lastMessageId = getCallbackMessageId();
        await saveSession(env, userId, session);
        
        const perPage = 5;
        const count = await db.prepare(`SELECT COUNT(*) AS total FROM ${config.table}`).first();
        const totalItems = count?.total || 0;
        const totalPages = Math.ceil(totalItems / perPage) + 1;
        
        const listPage = page - 1;
        const currentPage = Math.min(Math.max(listPage, 1), Math.ceil(totalItems / perPage) || 1);
        const currentOffset = (currentPage - 1) * perPage;
        
        const nameField = config.nameField || 'nama';
        const r = await db.prepare(`
            SELECT id, ${nameField} AS nama, deskripsi FROM ${config.table} 
            ORDER BY urutan ASC, id ASC 
            LIMIT ? OFFSET ?
        `).bind(perPage, currentOffset).all();
        
        let msg = `➕ *TAMBAH ${config.label.toUpperCase()}*\n${DIVIDER}\n\n`;
        msg += `📊 Total : ${totalItems} item • Hal ${page}/${totalPages}\n\n`;
        msg += `${config.label} yang sudah ada:\n\n`;
        
        const items = (r.results || []).map(k => ({
            nama: k.nama,
            id: k.id,
            deskripsi: k.deskripsi || 'Tidak ada deskripsi',
            extraLines: []
        }));
        
        if (typeof buildListView === 'function') {
            msg += buildListView(items, { startNumber: currentOffset });
        } else {
            items.forEach((k, i) => {
                msg += `${i + currentOffset + 1}. ${k.nama}\n`;
                msg += `   🆔 ID : ${k.id}\n`;
                msg += `   📝 Deskripsi : ${k.deskripsi}\n\n`;
            });
        }
        msg += `\n💡 _Ketik data baru untuk ditambahkan._\n`;
        msg += `💡 Ketik "skip" untuk batal.`;
        
        const keyboard = [];
        const idButtons = (r.results || []).map(k => ({ 
            text: k.id, 
            callback_data: "noop" 
        }));
        for (let i = 0; i < idButtons.length; i += 5) {
            keyboard.push(idButtons.slice(i, i + 5));
        }
        
        const navButtons = [];
        if (page > 2) {
            navButtons.push({ text: "⬅️ Prev", callback_data: `ent_add_page_${entity}_${page - 1}` });
        } else {
            navButtons.push({ text: "⬅️ Prev", callback_data: `ent_add_${entity}` });
        }
        navButtons.push({ text: `📄 ${page}/${totalPages}`, callback_data: `ent_add_page_jump_${entity}` });
        if (page < totalPages) {
            navButtons.push({ text: "Next ➡️", callback_data: `ent_add_page_${entity}_${page + 1}` });
        }
        keyboard.push(navButtons);
        keyboard.push([{ text: "🔙 Kembali", callback_data: config.menuCallback }]);
        
        const messageId = getCallbackMessageId();
        await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId });
    }
    return true;
}

// ============================================================
// HANDLER: ENT_ADD_PAGE_JUMP — TOMBOL 📄 X/Y
// ============================================================
if (data.startsWith('ent_add_page_jump_')) {
    const entity = data.replace('ent_add_page_jump_', '').toLowerCase();
    const config = getEntityConfig(entity);
    
    if (!config) {
        await smartMessage(chatId, `❌ Entitas "${entity}" tidak dikenal.`);
        return true;
    }
    
    const session = await getSession(env, userId);
    session.action = `ent_add_jump_${entity}`;
    session.lastMessageId = getCallbackMessageId();
    await saveSession(env, userId, session);
    
    const count = await db.prepare(`SELECT COUNT(*) AS total FROM ${config.table}`).first();
    const totalItems = count?.total || 0;
    const totalPages = Math.ceil(totalItems / 5) + 1;
    
    const messageId = getCallbackMessageId();
    let msg = `📄 *LOMPAT KE HALAMAN*\n${DIVIDER}\n\n`;
    msg += `📊 Total halaman : *${totalPages}*\n\n`;
    msg += `Ketik nomor halaman (1-${totalPages}):\n`;
    msg += `💡 Hal 1 = Panduan\n`;
    msg += `💡 Hal 2+ = List existing\n\n`;
    msg += `Atau ketik "batal" untuk kembali.`;
    
    const keyboard = [[{ 
        text: "🔙 Batal", 
        callback_data: config.menuCallback 
    }]];
    
    await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId });
    return true;
}

// ============================================================
// HANDLER: ENT_ADD_CONFIRM_PAGE — PAGINATION KONFIRMASI
// ============================================================
if (data.match(/^ent_add_confirm_page_[a-z]+_\d+$/)) {
    const match = data.match(/^ent_add_confirm_page_([a-z]+)_(\d+)$/);
    if (match) {
        const entity = match[1];
        const page = parseInt(match[2]) || 1;
        const config = getEntityConfig(entity);
        
        if (!config) {
            await smartMessage(chatId, `❌ Entitas "${entity}" tidak dikenal.`);
            return true;
        }
        
        const session = await getSession(env, userId);
        if (!session.tempData || !session.tempData.items) {
            await smartResponse(chatId, '❌ Data tidak valid.', 'Markdown', { mode: 'auto', messageId: getCallbackMessageId() });
            return true;
        }
        
        const items = session.tempData.items;
        const perPage = 5;
        const totalPages = Math.ceil(items.length / perPage);
        const currentPage = Math.min(Math.max(page, 1), totalPages || 1);
        const start = (currentPage - 1) * perPage;
        const pageItems = items.slice(start, start + perPage);
        
        session.tempData.page = currentPage;
        await saveSession(env, userId, session);
        
        let msg = `⚠️ *KONFIRMASI TAMBAH*\n${DIVIDER}\n\n`;
        msg += `📊 Total : ${items.length} item • Hal ${currentPage}/${totalPages}\n\n`;
        pageItems.forEach((item, i) => {
            msg += `${start + i + 1}. ${config.icon} ${item.nama}\n`;
            msg += `   📝 ${item.deskripsi || '-'}\n\n`;
        });
        msg += `\nYakin tambah?`;
        
        const keyboard = [];
        
        if (totalPages > 1) {
            const navButtons = [];
            if (currentPage > 1) {
                navButtons.push({ 
                    text: "⬅️ Prev", 
                    callback_data: `ent_add_confirm_page_${entity}_${currentPage - 1}` 
                });
            }
            navButtons.push({ 
                text: `📄 ${currentPage}/${totalPages}`, 
                callback_data: "noop" 
            });
            if (currentPage < totalPages) {
                navButtons.push({ 
                    text: "Next ➡️", 
                    callback_data: `ent_add_confirm_page_${entity}_${currentPage + 1}` 
                });
            }
            keyboard.push(navButtons);
        }
        
        keyboard.push([
            { text: `➕ Ya, TAMBAH ${items.length}`, callback_data: `ent_add_confirm_yes_${entity}` },
            { text: "❌ Batal", callback_data: `ent_add_confirm_no_${entity}` }
        ]);
        
        const messageId = getCallbackMessageId();
        await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId });
    }
    return true;
}

// ============================================================
// HANDLER: ENT_ADD_CONFIRM_YES — SIMPAN MULTI-ITEM
// ✅ FIX: Pakai startsWith untuk match entity suffix
// ============================================================
if (data.startsWith('ent_add_confirm_yes')) {
    console.log('🔍 [ENT_ADD_CONFIRM_YES] data =', data);
    
    const session = await getSession(env, userId);
    
    if (!session.tempData || !session.tempData.items || !session.tempData.entity) {
        await smartResponse(chatId, '❌ Data tidak valid.', 'Markdown', { mode: 'auto', messageId: getCallbackMessageId() });
        await clearSession(env, userId);
        return true;
    }
    
    const { entity, items, parentId, parentName } = session.tempData;
    const config = getEntityConfig(entity);
    
    if (!config) {
        await smartMessage(chatId, `❌ Entitas tidak dikenal.`);
        await clearSession(env, userId);
        return true;
    }
    
    try {
        const nameField = config.nameField || 'nama';
        const now = new Date().toISOString();
        
        let urutanQuery = `SELECT MAX(urutan) AS max_urutan FROM ${config.table}`;
        let urutanBind = [];
        if (config.parentField && parentId) {
            urutanQuery += ` WHERE ${config.parentField} = ?`;
            urutanBind.push(parentId);
        }
        const maxRow = await db.prepare(urutanQuery).bind(...urutanBind).first();
        let nextUrutan = (maxRow?.max_urutan || 0) + 1;
        
        let success = [];
        let failed = [];
        
        for (const item of items) {
            try {
                const newId = await generateId(db, config.prefix, config.table);
                
                const fields = ['id', nameField, 'deskripsi', 'urutan', 'created_at', 'updated_at'];
                const values = [newId, item.nama, item.deskripsi || null, nextUrutan++, now, now];
                
                if (entity === 'mata_pelajaran') {
                    if (!session.tempData?.bidangId || !parentId) {
                        throw new Error('Konteks Bidang Studi dan Kelas Mata Pelajaran belum lengkap.');
                    }
                    const dup = await db.prepare(`
                        SELECT id FROM mata_pelajaran
                        WHERE bidang_studi_id = ? AND kelas_id = ?
                          AND LOWER(TRIM(nama)) = LOWER(TRIM(?)) LIMIT 1
                    `).bind(session.tempData.bidangId, parentId, item.nama).first();
                    if (dup) throw new Error(`Mata Pelajaran \"${item.nama}\" sudah ada pada Bidang/Kelas tersebut.`);
                    fields.push('bidang_studi_id', 'kelas_id', 'created_by', 'updated_by');
                    values.push(session.tempData.bidangId, parentId, userId, userId);
                } else {
                    if (config.parentField && parentId) {
                        fields.push(config.parentField);
                        values.push(parentId);
                    }
                    if (config.table === 'mata_kuliah') {
                        fields.push('created_by', 'updated_by');
                        values.push(userId, userId);
                    }
                }
                
                const placeholders = fields.map(() => '?').join(', ');
                await db.prepare(`
                    INSERT INTO ${config.table} (${fields.join(', ')})
                    VALUES (${placeholders})
                `).bind(...values).run();
                
                success.push(`${newId} - ${item.nama}`);
            } catch (e) {
                failed.push(`${item.nama} : ${e.message}`);
            }
        }
        
        await clearSession(env, userId);
        
        let msg = `✅ *BERHASIL DITAMBAHKAN*\n${DIVIDER}\n\n`;
        if (parentName) {
            msg += `📂 ${config.parentLabel}: ${parentName}\n\n`;
        }
        msg += `📊 ${success.length} item ditambahkan:\n\n`;
        success.forEach(s => msg += `✅ ${s}\n`);
        if (failed.length > 0) {
            msg += `\n❌ ${failed.length} gagal:\n`;
            failed.forEach(f => msg += `• ${f}\n`);
        }
        
        const keyboard = [[{ text: `🔙 Kembali ke Menu ${config.label}`, callback_data: config.menuCallback }]];
        
        const messageId = getCallbackMessageId();
        await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId });
    } catch (e) {
        console.error(`ent_add_confirm_yes error:`, e);
        await smartMessage(chatId, `❌ Gagal tambah: ${e.message}`);
        await clearSession(env, userId);
    }
    return true;
}

