// ============================================================
// 🆕 SOAL - PAGINATION (Prev/Next)
// ============================================================
if (data.startsWith('soal_page_') && data !== 'soal_page_jump') {
    const page = parseInt(data.replace('soal_page_', ''));
    if (!page || page < 1) {
        return true;
    }
    
    await handleCommand(env, chatId, userId, `/soal_list ${page}`);
    return true;
}



// ============================================================
// 🆕 FIX: TOGGLE TAHAP (GUNAKAN editMessageText)
// Lokasi: Ganti handler tahap_toggle_ lama
// ============================================================

if (data.startsWith('tahap_toggle_')) {
    const tahapKode = data.replace('tahap_toggle_', '');
    
    if (!TAHAP_PEMBELAJARAN[tahapKode]) {
        await answerCallback(callbackQueryId, '❌ Tahap tidak valid');
        return true;
    }
    
    const session = await getSession(env, userId);
    
    if (!session.materiContext?.topik) {
        await answerCallback(callbackQueryId, '❌ Pilih topik dulu!');
        await showMateriTopicSelection(chatId, db);
        return true;
    }
    
    let selected = session.selectedTahap || [];
    
    if (selected.includes(tahapKode)) {
        selected = selected.filter(t => t !== tahapKode);
        if (session.skippedReasons) delete session.skippedReasons[tahapKode];
        await answerCallback(callbackQueryId, `❌ ${tahapKode} dihapus`);
    } else {
        selected.push(tahapKode);
        if (session.skippedReasons) delete session.skippedReasons[tahapKode];
        await answerCallback(callbackQueryId, `✅ ${tahapKode} ditambahkan`);
    }
    
    session.selectedTahap = selected;
    await saveSession(env, userId, session);
    
    // ✅ GUNAKAN callbackQuery.message.message_id
    const messageId = callbackQuery?.message?.message_id;
    const headerMsg = `📖 *Topik:* ${session.materiContext.topik}\n\n`;
    
    if (messageId) {
        await editInlineKeyboard(
            chatId,
            messageId,
            headerMsg + buildTahapSelectionMessage(session.selectedTahap, session.skippedReasons || {}),
            buildTahapSelectionMenu(session.selectedTahap, session.skippedReasons || {})
        );
    } else {
        // Fallback
        await sendInlineKeyboard(
            chatId,
            headerMsg + buildTahapSelectionMessage(session.selectedTahap, session.skippedReasons || {}),
            buildTahapSelectionMenu(session.selectedTahap, session.skippedReasons || {})
        );
    }
    
    return true;
}

// ============================================================
// 3. PILIH SEMUA
// ============================================================
// ============================================================
// 🆕 FIX: PILIH SEMUA (editMessageText)
// ============================================================

if (data === 'tahap_select_all') {
    const session = await getSession(env, userId);
    
    if (!session.materiContext?.topik) {
        await answerCallback(callbackQueryId, '❌ Pilih topik dulu!');
        await showMateriTopicSelection(chatId, db);
        return true;
    }
    
    session.selectedTahap = ['T1', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'T8', 'T9'];
    session.skippedReasons = {};
    await saveSession(env, userId, session);
    
    await answerCallback(callbackQueryId, '✅ Semua 9 tahap dipilih');
    
    const messageId = callbackQuery.message?.message_id;
    const headerMsg = `📖 *Topik:* ${session.materiContext.topik}\n\n`;
    
    if (messageId) {
        await editInlineKeyboard(
            chatId,
            messageId,
            headerMsg + buildTahapSelectionMessage(session.selectedTahap, {}),
            buildTahapSelectionMenu(session.selectedTahap, {})
        );
    } else {
        await sendInlineKeyboard(
            chatId,
            headerMsg + buildTahapSelectionMessage(session.selectedTahap, {}),
            buildTahapSelectionMenu(session.selectedTahap, {})
        );
    }
    return true;
}

// ============================================================
// 4. KOSONGKAN
// ============================================================
// ============================================================
// 🆕 FIX: KOSONGKAN SEMUA (editMessageText)
// ============================================================

if (data === 'tahap_clear_all') {
    const session = await getSession(env, userId);
    session.selectedTahap = [];
    session.skippedReasons = {};
    await saveSession(env, userId, session);
    
    await answerCallback(callbackQueryId, '❌ Semua pilihan dikosongkan');
    
    const messageId = callbackQuery.message?.message_id;
    
    let headerMsg = '';
    if (session.materiContext?.topik) {
        headerMsg = `📖 *Topik:* ${session.materiContext.topik}\n\n`;
    }
    
    if (messageId) {
        await editInlineKeyboard(
            chatId,
            messageId,
            headerMsg + buildTahapSelectionMessage([], {}),
            buildTahapSelectionMenu([], {})
        );
    } else {
        await sendInlineKeyboard(
            chatId,
            headerMsg + buildTahapSelectionMessage([], {}),
            buildTahapSelectionMenu([], {})
        );
    }
    return true;
}

// ============================================================
// 5. SKIP REASON - MENU PILIH TAHAP
// ============================================================
if (data === 'tahap_skip_reason') {
    const session = await getSession(env, userId);
    const skipped = getSkippedTahap(session.selectedTahap || []);
    
    if (skipped.length === 0) {
        await answerCallback(callbackQueryId, 'ℹ️ Tidak ada tahap yang dilewati');
        return true;
    }
    
    let msg = `⏭️ *CATAT ALASAN SKIP*\n\n`;
    msg += `Pilih tahap yang ingin diberi alasan:\n\n`;
    
    const keyboard = skipped.map(k => {
        const t = TAHAP_PEMBELAJARAN[k];
        const reason = session.skippedReasons?.[k];
        return [{
            text: `${t.icon} ${k} — ${t.nama}${reason ? ` ✅` : ''}`,
            callback_data: `skip_reason_select_${k}`
        }];
    });
    
    keyboard.push([{ text: "🔙 Kembali", callback_data: "materi_pilih_tahap" }]);
    
    await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId: getCallbackMessageId() });
    return true;
}

// ============================================================
// 6. SKIP REASON - PILIH TAHAP
// ============================================================
if (data.startsWith('skip_reason_select_')) {
    const tahapKode = data.replace('skip_reason_select_', '');
    const t = TAHAP_PEMBELAJARAN[tahapKode];
    
    if (!t) {
        await answerCallback(callbackQueryId, '❌ Tahap tidak valid');
        return true;
    }
    
    let msg = `📝 *ALASAN SKIP: ${t.icon} ${tahapKode}*\n\n`;
    msg += `Tahap: *${t.nama}*\n`;
    msg += `Deskripsi: ${t.deskripsi}\n\n`;
    msg += `Mengapa tahap ini dilewati?`;
    
    await sendInlineKeyboard(chatId, msg, buildSkipReasonMenu(tahapKode));
    return true;
}

// ============================================================
// 7. SKIP REASON - SIMPAN ALASAN
// ============================================================
if (data.startsWith('skip_reason_') && !data.startsWith('skip_reason_select_')) {
    const parts = data.replace('skip_reason_', '').split('_');
    const tahapKode = parts[0];
    const reasonKey = parts.slice(1).join('_');
    
    const reasonLabels = {
        'tidak_relevan': 'Tidak relevan dengan topik',
        'sudah_dikuasai': 'Sudah dikuasai siswa',
        'buat_manual': 'Akan dibuat manual',
        'terlalu_panjang': 'Materi terlalu panjang',
        'lainnya': 'Alasan lainnya',
        'tanpa_alasan': null
    };
    
    const session = await getSession(env, userId);
    session.skippedReasons = session.skippedReasons || {};
    
    const reasonText = reasonLabels[reasonKey];
    if (reasonText) {
        session.skippedReasons[tahapKode] = reasonText;
    } else {
        delete session.skippedReasons[tahapKode];
    }
    
    await saveSession(env, userId, session);
    
    await answerCallback(callbackQueryId, reasonText ? `✅ Alasan dicatat` : '✅ Tanpa alasan');
    
    // ============================================================
    // FIX A2: Didefinisikan DULU sebelum dipakai
    // ============================================================
    const selectedTahap = session.selectedTahap || [];
    const skippedTahap = getSkippedTahap(selectedTahap);
    
    if (skippedTahap.length > 0) {
        // Tampilkan menu skip reason
        let msg = `⏭️ *CATAT ALASAN SKIP*\n\n`;
        msg += `Pilih tahap yang ingin diberi alasan:\n\n`;
        
        const keyboard = skippedTahap.map(k => {
            const t = TAHAP_PEMBELAJARAN[k];
            const reason = session.skippedReasons?.[k];
            return [{
                text: `${t.icon} ${k} — ${t.nama}${reason ? ` ✅` : ''}`,
                callback_data: `skip_reason_select_${k}`
            }];
        });
        
        keyboard.push([{ text: "🔙 Kembali", callback_data: "materi_pilih_tahap" }]);
        
        const messageId = callbackQuery?.message?.message_id;
        await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId });
    } else {
        // Tidak ada tahap yang dilewati → tampilkan pilihan tahap
        await sendInlineKeyboard(
            chatId,
            buildTahapSelectionMessage(selectedTahap, session.skippedReasons || {}),
            buildTahapSelectionMenu(selectedTahap, session.skippedReasons || {})
        );
    }
    return true;
}

// ============================================================
// 8. KONFIRMASI PILIHAN TAHAP
// ============================================================
if (data === 'tahap_confirm') {
    const session = await getSession(env, userId);
    const selected = session.selectedTahap || [];
    
    if (selected.length === 0) {
        await answerCallback(callbackQueryId, '❌ Pilih minimal 1 tahap!');
        return true;
    }
    
    // Urutkan
    selected.sort((a, b) => parseInt(a.replace('T', '')) - parseInt(b.replace('T', '')));
    session.selectedTahap = selected;
    await saveSession(env, userId, session);
    
    const dependencies = checkDependencies(selected);
    
    let confirmMsg = buildTahapConfirmMessage(
        selected, 
        session.skippedReasons || {},
        session.materiContext || {}
    );
    
    const keyboard = [];
    
    if (dependencies.length > 0) {
        const uniqueMissing = [...new Set(dependencies.map(d => d.required))];
        keyboard.push([
            { text: `➕ Tambah ${uniqueMissing.join('+')}`, callback_data: `tahap_add_missing` }
        ]);
    }
    
    keyboard.push([
        { text: "🚀 Generate Sekarang", callback_data: "tahap_generate" }
    ]);
    keyboard.push([
        { text: "✏️ Ubah Pilihan", callback_data: "materi_pilih_tahap" }
    ]);
    keyboard.push([
        { text: "🔙 Kembali", callback_data: "ai_menu" }
    ]);
    
    await sendInlineKeyboard(chatId, confirmMsg, keyboard);
    return true;
}

// ============================================================
// 9. TAMBAH TAHAP YANG MISSING (DARI VALIDASI DEPENDENSI)
// ============================================================
if (data === 'tahap_add_missing') {
    const session = await getSession(env, userId);
    const selected = session.selectedTahap || [];
    const dependencies = checkDependencies(selected);
    const missing = [...new Set(dependencies.map(d => d.required))];
    
    for (const m of missing) {
        if (!selected.includes(m)) selected.push(m);
    }
    
    selected.sort((a, b) => parseInt(a.replace('T', '')) - parseInt(b.replace('T', '')));
    session.selectedTahap = selected;
    await saveSession(env, userId, session);
    
    await answerCallback(callbackQueryId, `✅ Ditambahkan: ${missing.join(', ')}`);
    
    // Kembali ke konfirmasi
    await sendInlineKeyboard(
        chatId,
        buildTahapConfirmMessage(selected, session.skippedReasons || {}, session.materiContext || {}),
        [
            [{ text: "🚀 Generate Sekarang", callback_data: "tahap_generate" }],
            [{ text: "✏️ Ubah Pilihan", callback_data: "materi_pilih_tahap" }],
            [{ text: "🔙 Kembali", callback_data: "ai_menu" }]
        ]
    );
    return true;
}

// ============================================================
// 🆕 PATCH 4: UPDATE CALLBACK tahap_generate
// Ganti handler tahap_generate dari Patch 3
// ============================================================

// ============================================================
// 🆕 TAHAP GENERATE - VERSI FINAL (PATCH 8)
// Dengan Auto-Save Version + Auto-Merge
// ============================================================
if (data === 'tahap_generate') {
    console.log('📥 [DEBUG] tahap_generate dipanggil');
    
    // Step 0: Answer callback
    try {
        await answerCallback(callbackQueryId, '⏳ Memproses...');
    } catch (e) {}
    
    // ============================================================
    // Step 0.5: LOCK (auto-expire 2 menit)
    // ============================================================
    try {
        const lockSession = await getSession(env, userId);
        
        if (lockSession.materiProcessing) {
            const elapsed = Date.now() - lockSession.materiProcessing;
            if (elapsed < 2 * 60 * 1000) {
                await smartMessage(chatId, 
                    `⏳ *Sedang memproses...*\n\n` +
                    `📊 Sudah: ${Math.round(elapsed/1000)} detik\n` +
                    `💡 Tunggu sebentar, atau /reset_lock`
                );
                return true;
            }
            lockSession.materiProcessing = null;
            await saveSession(env, userId, lockSession);
        }
        
        lockSession.materiProcessing = Date.now();
        await saveSession(env, userId, lockSession);
    } catch (e) {
        console.error('Lock error:', e);
    }
    
    // ============================================================
    // MAIN LOGIC
    // ============================================================
    try {
        const session = await getSession(env, userId);
        const selected = session.selectedTahap || [];
        const skippedReasons = session.skippedReasons || {};
        const context = session.materiContext || {};
        
        // ============================================================
        // VALIDASI
        // ============================================================
        if (!context.topik) {
            await smartResponse(chatId, '❌ Pilih topik dulu!', 'Markdown', { mode: 'auto', messageId: getCallbackMessageId() });
            await showMateriTopicSelection(chatId, db);
            const s = await getSession(env, userId);
            s.materiProcessing = null;
            await saveSession(env, userId, s);
            return true;
        }
        
        if (selected.length === 0) {
            await smartResponse(chatId, '❌ Pilih tahap dulu!', 'Markdown', { mode: 'auto', messageId: getCallbackMessageId() });
            const s = await getSession(env, userId);
            s.materiProcessing = null;
            await saveSession(env, userId, s);
            return true;
        }
        
        // ============================================================
        // STEP 2: Tentukan currentIndex dari DB (anti-duplikat)
        // ============================================================
        let materiId = session.materiId;
        let currentIndex = 0;
        let isNewMateri = false;
        
        if (materiId) {
            const progressCheck = await db.prepare(`
                SELECT tahap_kode, status, word_count 
                FROM materi_progress 
                WHERE materi_id = ? 
                ORDER BY tahap_kode
            `).bind(materiId).all();
            
            const progress = progressCheck.results || [];
            
            let foundPending = false;
            for (let i = 0; i < selected.length; i++) {
                const tk = selected[i];
                const p = progress.find(x => x.tahap_kode === tk);
                
                if (!p || p.status !== 'done') {
                    currentIndex = i;
                    foundPending = true;
                    console.log(`📊 Tahap ${tk} belum selesai, currentIndex = ${i}`);
                    break;
                }
            }
            
            if (!foundPending) {
                currentIndex = selected.length;
                console.log(`✅ Semua tahap sudah done, currentIndex = ${selected.length}`);
            }
        } else {
            // ========== BUAT MATERI BARU ==========
            currentIndex = 0;
            isNewMateri = true;
            
            materiId = await generateId(db, 'M', 'materi');
            const masterIds = await findMasterIdsFromContext(db, context);
            
            await db.prepare(`
                INSERT INTO materi (
                    id, kategori_id, bidang_studi_id, program_studi_id, mata_pelajaran_id, mata_kuliah_id,
                    topik_id, sub_topik_id, kisi_kisi_id, kemampuan_id, sub_kemampuan_id,
                    judul, format, tahap_dipilih, tahap_dilewati, jumlah_tahap,
                    status, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            `).bind(
                materiId,
                masterIds.kategoriId, masterIds.bidangId, masterIds.programId,
                masterIds.mataPelajaranId, masterIds.mataKuliahId,
                masterIds.topikId, masterIds.subtopikId, masterIds.kisiId,
                masterIds.kemampuanId, masterIds.subKemampuanId,
                `Materi ${context.topik} - ${selected.length} Tahap`,
                session.materiFormat || 'penjelasan',
                JSON.stringify(selected),
                JSON.stringify(getSkippedTahap(selected)),
                selected.length,
                'DRAFT',
                new Date().toISOString()
            ).run();
            
            // Buat progress untuk setiap tahap
            for (const tk of selected) {
                const progressId = await generateId(db, 'MP', 'materi_progress');
                await db.prepare(`
                    INSERT INTO materi_progress (id, materi_id, tahap_kode, status, created_at)
                    VALUES (?, ?, ?, 'pending', ?)
                `).bind(progressId, materiId, tk, new Date().toISOString()).run();
            }
            
            console.log(`✅ Materi ${materiId} dibuat (per-tahap mode)`);
            
            session.materiId = materiId;
            session.materiCurrentTahapIndex = 0;
            await saveSession(env, userId, session);
        }
        
        // ============================================================
        // STEP 3: Cek apakah semua tahap sudah selesai
        // ============================================================
        if (currentIndex >= selected.length) {
            // ========== SEMUA TAHAP SELESAI ==========
            const sessionClean = await getSession(env, userId);
            const finalMateriId = sessionClean.materiId;
            
            // 🆕 PATCH 8: Auto-save version FINAL sebelum clear session
            try {
                await rebuildMateriContent(db, finalMateriId);
                
                const finalVersion = await createMateriVersion(db, finalMateriId, {
                    label: `Semua tahap selesai (${selected.length} tahap)`,
                    catatan: `Auto-save setelah semua tahap complete`,
                    createdBy: userId,
                    mergeStrategy: 'snapshot',
                    setActive: true
                });
                
                if (finalVersion.success) {
                    console.log(`✅ Final version v${finalVersion.versi} (aktif) untuk ${finalMateriId}`);
                }
            } catch (e) {
                console.warn('⚠️ Gagal buat final version:', e.message);
            }
            
            // Clear session
            sessionClean.materiCurrentTahapIndex = null;
            sessionClean.materiId = null;
            sessionClean.materiProcessing = null;
            sessionClean.selectedTahap = null;
            sessionClean.skippedReasons = null;
            sessionClean.materiContext = null;
            await saveSession(env, userId, sessionClean);
            
            await smartMessage(chatId, 
                `✅ *Semua ${selected.length} tahap selesai!*\n\n` +
                `🆔 Materi ID: \`${finalMateriId}\``
            );
            
            // Keyboard lengkap
            const keyboard = [
                [{ text: "👁️ Lihat Isi Materi", callback_data: `materi_content_${finalMateriId}` }],
                [
                    { text: "📖 Buat Glosarium", callback_data: `materi_glosarium_${finalMateriId}` },
                    { text: "🗺️ Buat Peta Konsep", callback_data: `materi_peta_${finalMateriId}` }
                ],
                [{ text: "📚 Riwayat Versi", callback_data: `materi_versions_${finalMateriId}` }],
                [{ text: "📝 Generate Soal", callback_data: `materi_to_soal_${finalMateriId}` }],
                [{ text: "📊 Lihat Progress", callback_data: `materi_progress_${finalMateriId}` }],
                [{ text: "📋 Daftar Materi", callback_data: "materi_list" }],
                [{ text: "🔙 Kembali ke Menu AI", callback_data: "ai_menu" }]
            ];
            
            await sendInlineKeyboard(chatId, 
                `📖 *Materi Selesai Digenerate*\n\n` +
                `🆔 Materi ID: \`${finalMateriId}\`\n\n` +
                `🏷️ *Aksi Lanjutan:*\n` +
                `📖 Glosarium - Ekstrak istilah penting\n` +
                `🗺️ Peta Konsep - Visualisasi hubungan konsep\n` +
                `📚 Riwayat Versi - Lihat & merge versi\n` +
                `📝 Generate Soal - Buat soal dari materi ini\n\n` +
                `Pilih aksi:`,
                keyboard
            );
            return true;
        }
        
        // ============================================================
        // STEP 4: Generate 1 tahap saja
        // ============================================================
        const currentTahap = selected[currentIndex];
        const t = TAHAP_PEMBELAJARAN[currentTahap];
        
        console.log(`🚀 Memproses tahap ${currentIndex + 1}/${selected.length}: ${currentTahap}`);
        
        await db.prepare(`
            UPDATE materi_progress 
            SET status = 'processing', started_at = ?
            WHERE materi_id = ? AND tahap_kode = ? AND status != 'done'
        `).bind(new Date().toISOString(), materiId, currentTahap).run();
        
        await smartMessage(chatId, 
            `📚 *Memproses Tahap ${currentIndex + 1}/${selected.length}*\n\n` +
            `${escapeMarkdown(t.icon)} *${escapeMarkdown(currentTahap)}* — *${escapeMarkdown(t.nama)}*\n\n` +
            `⏳ Mohon tunggu (5-10 detik)...`
        );
        
        const prompt = buildTahapMateriPrompt(
            currentTahap, 
            context.topik, 
            context, 
            session.materiFormat || 'penjelasan'
        );
        
        if (!prompt) {
            await smartMessage(chatId, `❌ Gagal build prompt untuk ${currentTahap}`);
            const s = await getSession(env, userId);
            s.materiProcessing = null;
            await saveSession(env, userId, s);
            return true;
        }
        
        const result = await callAIHybrid(prompt, 'generate_materi', env);
        
        if (!result.success) {
            await db.prepare(`
                UPDATE materi_progress 
                SET status = 'failed', error_message = ?, completed_at = ?
                WHERE materi_id = ? AND tahap_kode = ?
            `).bind(
                result.error || 'Unknown error', 
                new Date().toISOString(), 
                materiId, 
                currentTahap
            ).run();
            
            await smartMessage(chatId, 
                `❌ *Tahap ${currentTahap} gagal!*\n\n` +
                `Error: ${result.error || 'Unknown'}\n\n` +
                `💡 Coba: /reset_lock`
            );
            
            const s = await getSession(env, userId);
            s.materiProcessing = null;
            await saveSession(env, userId, s);
            return true;
        }
        
        // ============================================================
        // HITUNG WORD COUNT
        // ============================================================
        const wordCount = result.response.split(/\s+/).length;
        
        await db.prepare(`
            UPDATE materi_progress 
            SET status = 'done', konten = ?, provider = ?, 
                word_count = ?, completed_at = ?, error_message = NULL
            WHERE materi_id = ? AND tahap_kode = ?
        `).bind(
            result.response, 
            result.provider, 
            wordCount, 
            new Date().toISOString(), 
            materiId, 
            currentTahap
        ).run();
        
        console.log(`✅ Tahap ${currentTahap} selesai: ${wordCount} kata`);
        
        // ============================================================
        // 🆕 PATCH 8: REBUILD + AUTO-SAVE VERSION
        // ============================================================
        await rebuildMateriContent(db, materiId);
        
        // Auto-save version setiap tahap selesai
        try {
            const versionResult = await createMateriVersion(db, materiId, {
                label: `Auto-save setelah ${currentTahap} selesai`,
                catatan: `Tahap ${currentTahap}: ${wordCount} kata`,
                createdBy: userId,
                mergeStrategy: 'snapshot',
                setActive: false
            });
            
            if (versionResult.success) {
                console.log(`📸 Versi ${versionResult.versi} disimpan setelah ${currentTahap}`);
            }
        } catch (e) {
            console.warn('⚠️ Gagal auto-save version:', e.message);
        }
        
        // ============================================================
        // STEP 5: Tanya lanjut atau stop
        // ============================================================
        const nextIndex = currentIndex + 1;
        
        const sessionUpdate = await getSession(env, userId);
        sessionUpdate.materiCurrentTahapIndex = nextIndex;
        sessionUpdate.materiProcessing = null;
        await saveSession(env, userId, sessionUpdate);
        
        if (nextIndex < selected.length) {
            // ========== MASIH ADA TAHAP BERIKUTNYA ==========
            const nextTahap = selected[nextIndex];
            const nextT = TAHAP_PEMBELAJARAN[nextTahap];
            
            await smartMessage(chatId, 
                `✅ *Tahap ${currentIndex + 1}/${selected.length} selesai!*\n\n` +
                `${escapeMarkdown(t.icon)} ${escapeMarkdown(currentTahap)} — ${escapeMarkdown(t.nama)}\n` +
                `📊 ${wordCount.toLocaleString()} kata | 🤖 ${escapeMarkdown(result.provider)}\n\n` +
                `📊 *Progress:* ${nextIndex}/${selected.length} selesai`
            );
            
            const keyboard = [
                [{ 
                    text: `▶️ Lanjut: ${nextT.icon} ${nextTahap} — ${nextT.nama}`, 
                    callback_data: 'tahap_lanjut' 
                }],
                [{ text: "⏸️ Stop di sini", callback_data: 'tahap_stop' }],
                [
                    { text: "📖 Glosarium", callback_data: `materi_glosarium_${materiId}` },
                    { text: "🗺️ Peta Konsep", callback_data: `materi_peta_${materiId}` }
                ],
                [{ text: "📚 Riwayat Versi", callback_data: `materi_versions_${materiId}` }],
                [{ text: "📊 Lihat Progress", callback_data: `materi_progress_${materiId}` }]
            ];
            
            await sendInlineKeyboard(chatId, `Lanjut ke tahap berikutnya?`, keyboard);
        } else {
            // ========== SEMUA TAHAP SELESAI ==========
            await smartMessage(chatId, 
                `✅ *Tahap ${currentIndex + 1}/${selected.length} selesai!*\n\n` +
                `${escapeMarkdown(t.icon)} ${escapeMarkdown(currentTahap)} — ${escapeMarkdown(t.nama)}\n` +
                `📊 ${wordCount.toLocaleString()} kata | 🤖 ${escapeMarkdown(result.provider)}\n\n` +
                `🎉 *Semua ${selected.length} tahap selesai!*`
            );
            
            // 🆕 PATCH 8: Auto-save final version
            try {
                const finalVersion = await createMateriVersion(db, materiId, {
                    label: `Semua tahap selesai (${selected.length} tahap)`,
                    catatan: `Auto-save setelah semua tahap complete`,
                    createdBy: userId,
                    mergeStrategy: 'snapshot',
                    setActive: true
                });
                
                if (finalVersion.success) {
                    console.log(`✅ Final version v${finalVersion.versi} (aktif)`);
                }
            } catch (e) {
                console.warn('⚠️ Gagal buat final version:', e.message);
            }
            
            // Clear session
            const sessionClean = await getSession(env, userId);
            sessionClean.materiCurrentTahapIndex = null;
            sessionClean.materiId = null;
            sessionClean.materiProcessing = null;
            sessionClean.selectedTahap = null;
            sessionClean.skippedReasons = null;
            sessionClean.materiContext = null;
            await saveSession(env, userId, sessionClean);
            
            const keyboard = [
                [{ text: "👁️ Lihat Isi Materi", callback_data: `materi_content_${materiId}` }],
                [
                    { text: "📖 Buat Glosarium", callback_data: `materi_glosarium_${materiId}` },
                    { text: "🗺️ Buat Peta Konsep", callback_data: `materi_peta_${materiId}` }
                ],
                [{ text: "📚 Riwayat Versi", callback_data: `materi_versions_${materiId}` }],
                [{ text: "📝 Generate Soal", callback_data: `materi_to_soal_${materiId}` }],
                [{ text: "📊 Lihat Progress", callback_data: `materi_progress_${materiId}` }],
                [{ text: "📋 Daftar Materi", callback_data: "materi_list" }],
                [{ text: "🔙 Kembali ke Menu AI", callback_data: "ai_menu" }]
            ];
            
            await sendInlineKeyboard(chatId, 
                `📖 *Materi Selesai Digenerate*\n\n` +
                `🆔 Materi ID: \`${materiId}\`\n\n` +
                `🏷️ *Aksi Lanjutan:*\n` +
                `📖 Glosarium - Ekstrak istilah penting\n` +
                `🗺️ Peta Konsep - Visualisasi hubungan konsep\n` +
                `📚 Riwayat Versi - Lihat & merge versi\n` +
                `📝 Generate Soal - Buat soal dari materi ini\n\n` +
                `Pilih aksi:`,
                keyboard
            );
        }
        
    } catch (e) {
        console.error('❌ tahap_generate error:', e);
        
        try {
            const s = await getSession(env, userId);
            s.materiProcessing = null;
            await saveSession(env, userId, s);
        } catch (e2) {}
        
        await smartMessage(chatId, 
            `❌ *Error:*\n\n` +
            `${escapeMarkdown(e.message)}\n\n` +
            `💡 Coba: /reset_lock`
        );
    }
    
    return true;
}

