if (data === 'tahap_preset_menu') {
    let msg = `📦 *PILIH PAKET TAHAP*\n\n`;
    msg += `Gunakan preset untuk memilih tahap secara cepat:\n\n`;
    
    for (const [key, preset] of Object.entries(TAHAP_PRESETS)) {
        msg += `*${preset.label}*\n`;
        msg += `   ${preset.deskripsi}\n`;
        msg += `   Tahap: ${preset.tahap.join(', ')}\n\n`;
    }
    
    await sendInlineKeyboard(chatId, msg, buildPresetMenu());
    return true;
}

// ============================================================
// 12. PILIH PRESET
// ============================================================
// ============================================================
// 🆕 FIX: PILIH PRESET (editMessageText)
// ============================================================

if (data.startsWith('tahap_preset_')) {
    const presetKey = data.replace('tahap_preset_', '');
    const preset = TAHAP_PRESETS[presetKey];
    
    if (!preset) {
        await answerCallback(callbackQueryId, '❌ Preset tidak ditemukan');
        return true;
    }
    
    const session = await getSession(env, userId);
    
    if (!session.materiContext?.topik) {
        await answerCallback(callbackQueryId, '❌ Pilih topik dulu!');
        await showMateriTopicSelection(chatId, db);
        return true;
    }
    
    session.selectedTahap = [...preset.tahap];
    session.skippedReasons = session.skippedReasons || {};
    
    const skipped = getSkippedTahap(preset.tahap);
    for (const s of skipped) {
        if (!session.skippedReasons[s]) {
            session.skippedReasons[s] = `Tidak termasuk preset "${preset.label}"`;
        }
    }
    
    await saveSession(env, userId, session);
    await answerCallback(callbackQueryId, `✅ Preset "${preset.label}" diterapkan`);
    
    const messageId = callbackQuery.message?.message_id;
    const headerMsg = `📖 *Topik:* ${session.materiContext.topik}\n\n`;
    
    if (messageId) {
        await editInlineKeyboard(
            chatId,
            messageId,
            headerMsg + buildTahapSelectionMessage(session.selectedTahap, session.skippedReasons),
            buildTahapSelectionMenu(session.selectedTahap, session.skippedReasons)
        );
    } else {
        await sendInlineKeyboard(
            chatId,
            headerMsg + buildTahapSelectionMessage(session.selectedTahap, session.skippedReasons),
            buildTahapSelectionMenu(session.selectedTahap, session.skippedReasons)
        );
    }
    return true;
}

