if (data.startsWith('user_detail_')) {
    if (!isAdmin(userId)) {
        await answerCallback(callbackQueryId, '⛔ Akses ditolak');
        return true;
    }
    
    const targetId = data.replace('user_detail_', '');
    const target = await getUserById(db, targetId);
    
    if (!target) {
        await answerCallback(callbackQueryId, '❌ User tidak ditemukan');
        return true;
    }
    
    const roleIcon = target.role === 'admin' ? '👑' : 
                     target.role === 'teacher' ? '🎓' : '👤';
    const statusIcon = target.status === 'AKTIF' ? '✅' : '🚫';
    
    // Ambil statistik aktivitas
    let totalActivity = 0;
    try {
        const actCount = await db.prepare(`
            SELECT COUNT(*) as total FROM user_activity WHERE user_id = ?
        `).bind(targetId).first();
        totalActivity = actCount?.total || 0;
    } catch (e) {}
    
    // Ambil jumlah soal & materi (kalau ada kolom created_by)
    let totalSoal = target.total_soal || 0;
    let totalMateri = target.total_materi || 0;
    
    let msg = `👁️ *DETAIL USER*\n\n`;
    msg += `${roleIcon} *${target.nama_lengkap || 'Tanpa Nama'}*\n`;
    msg += `📱 @${target.username || '-'}\n\n`;
    msg += `━━━━━━━━━━━━━━━━━━━\n`;
    msg += `🆔 ID: \`${target.id}\`\n`;
    msg += `📱 Telegram: \`${target.telegram_id}\`\n`;
    msg += `🎭 Role: ${target.role}\n`;
    msg += `📊 Status: ${statusIcon} ${target.status}\n`;
    msg += `📧 Email: ${target.email || '-'}\n`;
    msg += `📞 No HP: ${target.no_hp || '-'}\n`;
    msg += `━━━━━━━━━━━━━━━━━━━\n\n`;
    
    msg += `📊 *Kontribusi:*\n`;
    msg += `├─ 📝 Soal dibuat: ${totalSoal}\n`;
    msg += `├─ 📖 Materi dibuat: ${totalMateri}\n`;
    msg += `└─ 📜 Aktivitas: ${totalActivity}\n\n`;
    
    msg += `📅 *Timeline:*\n`;
    msg += `├─ 📌 Daftar: ${target.created_at ? new Date(target.created_at).toLocaleString('id-ID') : '-'}\n`;
    msg += `├─ 🔓 Login terakhir: ${target.last_login ? new Date(target.last_login).toLocaleString('id-ID') : '-'}\n`;
    msg += `└─ 🔄 Update terakhir: ${target.updated_at ? new Date(target.updated_at).toLocaleString('id-ID') : '-'}`;
    
    // ============================================================
    // KEYBOARD AKSI
    // ============================================================
    const keyboard = [];
    
    // Baris 1: Edit Role
    keyboard.push([
        { text: "✏️ Edit Role", callback_data: `user_edit_role_${targetId}` }
    ]);
    
    // Baris 2: Blokir/Unblokir (tergantung status)
    if (target.status === 'AKTIF') {
        if (target.role !== 'admin') {
            keyboard.push([
                { text: "🚫 Blokir User", callback_data: `user_block_confirm_${targetId}` }
            ]);
        }
    } else {
        keyboard.push([
            { text: "🔓 Unblokir User", callback_data: `user_unblock_confirm_${targetId}` }
        ]);
    }
    
    // Baris 3: Riwayat Aktivitas
    keyboard.push([
        { text: "📜 Riwayat Aktivitas", callback_data: `user_detail_activity_${targetId}` }
    ]);
    
    // Baris 4: Hapus User (tidak bisa hapus admin)
    if (target.role !== 'admin') {
        keyboard.push([
            { text: "🗑️ Hapus User", callback_data: `user_delete_confirm_${targetId}` }
        ]);
    }
    
    // Baris 5: Kembali
    keyboard.push([
        { text: "🔙 Kembali ke Daftar", callback_data: "user_list" }
    ]);
    
    await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId: getCallbackMessageId() });
    return true;
}

// Riwayat aktivitas detail user
// ============================================================
// USER DELETE — SOFT DELETE DEFAULT
// ============================================================
if (data.startsWith('user_delete_confirm_')) {
    if(!isAdmin(userId)){await answerCallback(callbackQueryId,'⛔ Akses ditolak');return true;}
    const targetId=data.replace('user_delete_confirm_',''); const target=await getUserById(db,targetId);
    if(!target){await smartMessage(chatId,'❌ User tidak ditemukan.');return true;}
    if(String(target.role||'').toLowerCase()==='admin'){await smartMessage(chatId,'❌ User admin tidak dapat dihapus melalui menu User.');return true;}
    await smartResponseUniversal(chatId,`⚠️ *KONFIRMASI HAPUS USER*\n\n👤 ${target.nama_lengkap||targetId}\n🆔 ${targetId}\n\nPenghapusan standar adalah *soft delete* (status menjadi DIHAPUS).`,{keyboard:[[{text:'🗑️ Ya, Hapus',callback_data:`user_delete_yes_${targetId}`},{text:'❌ Batal',callback_data:`user_detail_${targetId}`}]],mode:'auto',messageId:getCallbackMessageId()});
    return true;
}
if (data.startsWith('user_delete_yes_')) {
    if(!isAdmin(userId)){await answerCallback(callbackQueryId,'⛔ Akses ditolak');return true;}
    const targetId=data.replace('user_delete_yes_',''); const target=await getUserById(db,targetId);
    if(!target){await smartMessage(chatId,'❌ User tidak ditemukan.');return true;}
    if(String(target.role||'').toLowerCase()==='admin'){await smartMessage(chatId,'❌ User admin tidak dapat dihapus.');return true;}
    try { const now=new Date().toISOString(); await db.prepare(`UPDATE users SET status='DIHAPUS',updated_at=? WHERE id=?`).bind(now,targetId).run(); await logUserActivity(db,userId,userId,'delete_user','user',targetId,JSON.stringify({mode:'soft_delete'})); await smartMessage(chatId,`✅ User ${targetId} berhasil dihapus secara soft delete.`); }
    catch(e){await smartMessage(chatId,`❌ Gagal menghapus user: ${e.message}`);} return true;
}

if (data.startsWith('user_detail_activity_')) {
    if (!isAdmin(userId)) {
        await answerCallback(callbackQueryId, '⛔ Akses ditolak');
        return true;
    }
    
    const targetId = data.replace('user_detail_activity_', '');
    const target = await getUserById(db, targetId);
    const activities = await getUserActivityLog(db, targetId, 30);
    
    let msg = `📜 *RIWAYAT AKTIVITAS*\n\n`;
    msg += `👤 ${target?.nama_lengkap || targetId}\n`;
    msg += `📊 Total: ${activities.length} aktivitas\n\n`;
    msg += `━━━━━━━━━━━━━━━━━━━\n\n`;
    
    if (activities.length === 0) {
        msg += `❌ Belum ada aktivitas.`;
    } else {
        const actionIcons = {
            'register': '🆕',
            'update_user': '✏️',
            'delete_user': '🗑️',
            'block_user': '🚫',
            'unblock_user': '🔓',
            'create_soal': '📝',
            'update_soal': '✏️',
            'delete_soal': '🗑️',
            'create_materi': '📖',
            'update_materi': '✏️',
            'delete_materi': '🗑️'
        };
        
        activities.forEach((a, i) => {
            const icon = actionIcons[a.action] || '📌';
            const date = new Date(a.created_at).toLocaleString('id-ID');
            
            msg += `${icon} *${a.action}*\n`;
            msg += `   📅 ${date}\n`;
            if (a.entity_type) {
                msg += `   🎯 ${a.entity_type}`;
                if (a.entity_id) msg += `: \`${a.entity_id}\``;
                msg += `\n`;
            }
            msg += `\n`;
        });
    }
    
    await sendInlineKeyboard(chatId, msg, [
        [{ text: "👁️ Kembali ke Detail", callback_data: `user_detail_${targetId}` }],
        [{ text: "📋 Daftar User", callback_data: "user_list" }]
    ]);
    return true;
}

