    msg += `🆔 ID: \`${target.id}\`\n`;
    msg += `👤 Nama: ${target.nama_lengkap || '-'}\n`;
    msg += `🎭 Role saat ini: ${roleIcons[target.role]} *${target.role}*\n\n`;
    msg += `━━━━━━━━━━━━━━━━━━━\n\n`;
    msg += `📌 *Pilih role baru:*\n\n`;
