// Eksekusi set role baru
if (data.startsWith('user_edit_role_set_')) {
    if (!isAdmin(userId)) {
        await answerCallback(callbackQueryId, '⛔ Akses ditolak');
        return true;
    }
    
    const rest = data.replace('user_edit_role_set_', '');
    const lastUnderscore = rest.lastIndexOf('_');
    
    if (lastUnderscore === -1) {
        await answerCallback(callbackQueryId, '❌ Format tidak valid');
        return true;
    }
    
    const targetId = rest.substring(0, lastUnderscore);
    const newRole = rest.substring(lastUnderscore + 1);
    
    // Validasi role
    if (!['admin', 'teacher', 'user'].includes(newRole)) {
        await answerCallback(callbackQueryId, '❌ Role tidak valid');
        return true;
    }
    
    const target = await getUserById(db, targetId);
    if (!target) {
        await answerCallback(callbackQueryId, '❌ User tidak ditemukan');
        return true;
    }
    
    // Cegah admin menurunkan dirinya sendiri
    if (target.telegram_id === String(userId) && target.role === 'admin' && newRole !== 'admin') {
        await answerCallback(callbackQueryId, '⚠️ Tidak bisa ubah role sendiri');
        await smartMessage(chatId, 
            `⚠️ *Tidak bisa menurunkan role sendiri!*\n\n` +
            `💡 Minta admin lain untuk ubah role Anda.`
        );
        return true;
    }
    
    const oldRole = target.role;
    
    try {
        await updateUser(db, targetId, { role: newRole }, userId);
        
        // Log aktivitas
        await logUserActivity(db, userId, 'admin', 
            'update_user', 'user', targetId, {
                field: 'role',
                old_value: oldRole,
                new_value: newRole
            });
        
        const roleIcons = { admin: '👑', teacher: '🎓', user: '👤' };
        
        await answerCallback(callbackQueryId, `✅ Role: ${newRole}`);
        
        await smartMessage(chatId, 
            `✅ *ROLE BERHASIL DIUBAH!*\n\n` +
            `👤 Nama: ${target.nama_lengkap}\n` +
            `🆔 ID: \`${target.id}\`\n\n` +
            `🎭 *Role Lama:* ${roleIcons[oldRole]} ${oldRole}\n` +
            `🎭 *Role Baru:* ${roleIcons[newRole]} ${newRole}\n\n` +
            `💡 User akan mendapat akses baru saat login berikutnya.`
        );
        
        // Notif ke user
        try {
            await smartMessage(target.telegram_id, 
                `🎭 *ROLE ANDA BERUBAH*\n\n` +
                `Role baru: ${roleIcons[newRole]} *${newRole.toUpperCase()}*\n\n` +
                `Kirim /start untuk mulai.`
            );
        } catch (e) {
            console.warn('Gagal kirim notif role:', e.message);
        }
        
        // Tampilkan detail user yang sudah diupdate
        await handleCallback(env, userId, `user_detail_${targetId}`, 
            chatId, callbackQueryId);
        
    } catch (e) {
        console.error('user_edit_role_set error:', e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
    }
    return true;
}

