// Menu broadcast
if (data === 'user_broadcast') {
    if (!isAdmin(userId)) {
        await answerCallback(callbackQueryId, '⛔ Akses ditolak');
        return true;
    }
    
    // Hitung total user per filter
    const totalAll = await db.prepare(`SELECT COUNT(*) as c FROM users WHERE status='AKTIF'`).first();
    const totalAdmin = await db.prepare(`SELECT COUNT(*) as c FROM users WHERE status='AKTIF' AND role='admin'`).first();
    const totalTeacher = await db.prepare(`SELECT COUNT(*) as c FROM users WHERE status='AKTIF' AND role='teacher'`).first();
    const totalUser = await db.prepare(`SELECT COUNT(*) as c FROM users WHERE status='AKTIF' AND role='user'`).first();
    
    let msg = `📢 *BROADCAST MESSAGE*\n\n`;
    msg += `Kirim pesan ke banyak user sekaligus.\n\n`;
    msg += `📊 *Target tersedia:*\n`;
    msg += `├─ 🌐 Semua: ${totalAll?.c || 0} user\n`;
    msg += `├─ 👑 Admin: ${totalAdmin?.c || 0} user\n`;
    msg += `├─ 🎓 Teacher: ${totalTeacher?.c || 0} user\n`;
    msg += `└─ 👤 User: ${totalUser?.c || 0} user\n\n`;
    msg += `⚠️ *Pesan akan dikirim langsung ke user.*`;
    
    const keyboard = [
        [{ text: `🌐 Semua User (${totalAll?.c || 0})`, callback_data: "user_broadcast_target_all" }],
        [{ text: `👑 Admin (${totalAdmin?.c || 0})`, callback_data: "user_broadcast_target_admin" },
         { text: `🎓 Teacher (${totalTeacher?.c || 0})`, callback_data: "user_broadcast_target_teacher" }],
        [{ text: `👤 User Biasa (${totalUser?.c || 0})`, callback_data: "user_broadcast_target_user" }],
        [{ text: "🔙 Kembali", callback_data: "menu_user" }]
    ];
    
    await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId: getCallbackMessageId() });
    return true;
}

// Pilih target broadcast
if (data.startsWith('user_broadcast_target_')) {
    if (!isAdmin(userId)) {
        await answerCallback(callbackQueryId, '⛔ Akses ditolak');
        return true;
    }
    
    const target = data.replace('user_broadcast_target_', '');
    
    if (!['all', 'admin', 'teacher', 'user'].includes(target)) {
        await answerCallback(callbackQueryId, '❌ Target tidak valid');
        return true;
    }
    
    const session = await getSession(env, userId);
    session.action = 'user_broadcast_input';
    session.broadcastTarget = target;
    session.step = 1;
    await saveSession(env, userId, session);
    
    const targetLabels = {
        'all': '🌐 Semua User',
        'admin': '👑 Admin',
        'teacher': '🎓 Teacher',
        'user': '👤 User Biasa'
    };
    
    await smartMessage(chatId, 
        `📢 *BROADCAST: ${targetLabels[target]}*\n\n` +
        `📝 Kirim pesan yang akan dibroadcast:\n\n` +
        `💡 Support format Markdown:\n` +
        `• *bold*\n` +
        `• _italic_\n` +
        `• \`code\`\n\n` +
        `⚠️ Maksimal 4000 karakter.\n\n` +
        `Ketik "batal" untuk membatalkan.`
    );
    return true;
}

// Konfirmasi broadcast
if (data === 'user_broadcast_send_yes') {
    if (!isAdmin(userId)) {
        await answerCallback(callbackQueryId, '⛔ Akses ditolak');
        return true;
    }
    
    const session = await getSession(env, userId);
    
    if (!session.broadcastMessage || !session.broadcastTarget) {
        await smartResponse(chatId, '❌ Data broadcast tidak ditemukan.', 'Markdown', { mode: 'auto', messageId: getCallbackMessageId() });
        await clearSession(env, userId);
        return true;
    }
    
    await answerCallback(callbackQueryId, '📤 Mengirim broadcast...');
    
    const { broadcastMessage, broadcastTarget } = session;
    
    // Ambil semua user sesuai target
    let query = `SELECT telegram_id, nama_lengkap, role FROM users WHERE status='AKTIF'`;
    const bind = [];
    
    if (broadcastTarget !== 'all') {
        query += ` AND role = ?`;
        bind.push(broadcastTarget);
    }
    
    const users = await db.prepare(query).bind(...bind).all();
    const userList = users.results || [];
    
    await smartMessage(chatId, 
        `📤 *BROADCAST SEDANG DIKIRIM...*\n\n` +
        `📊 Target: ${userList.length} user\n` +
        `⏳ Mohon tunggu, ini butuh beberapa saat.`
    );
    
    // Kirim pesan satu per satu (dengan delay untuk hindari rate limit)
    let successCount = 0;
    let failedCount = 0;
    const failedUsers = [];
    
    for (let i = 0; i < userList.length; i++) {
        const u = userList[i];
        
        try {
            // Delay 50ms antar pesan (20 pesan/detik max)
            if (i > 0) await new Promise(r => setTimeout(r, 50));
            
            const result = await smartMessage(u.telegram_id, broadcastMessage);
            
            if (result && !result.error) {
                successCount++;
            } else {
                failedCount++;
                failedUsers.push({
                    telegram_id: u.telegram_id,
                    nama: u.nama_lengkap
                });
            }
        } catch (e) {
            failedCount++;
            failedUsers.push({
                telegram_id: u.telegram_id,
                nama: u.nama_lengkap,
                error: e.message
            });
        }
        
        // Update progress setiap 10 user
        if ((i + 1) % 10 === 0) {
            try {
                await smartMessage(chatId, 
                    `⏳ Progress: ${i + 1}/${userList.length}\n` +
                    `✅ Sukses: ${successCount} | ❌ Gagal: ${failedCount}`
                );
            } catch (e) {}
        }
    }
    
    // Log aktivitas
    await logUserActivity(db, userId, 'admin', 
        'broadcast', 'user', null, {
            target: broadcastTarget,
            total: userList.length,
            success: successCount,
            failed: failedCount
        });
    
    // Laporan akhir
    let report = `✅ *BROADCAST SELESAI*\n\n`;
    report += `📊 *Statistik:*\n`;
    report += `├─ 📤 Total target: ${userList.length}\n`;
    report += `├─ ✅ Berhasil: ${successCount}\n`;
    report += `└─ ❌ Gagal: ${failedCount}\n\n`;
    
    if (failedUsers.length > 0 && failedUsers.length <= 5) {
        report += `⚠️ *Gagal kirim ke:*\n`;
        failedUsers.forEach(u => {
            report += `- ${u.nama || u.telegram_id}\n`;
        });
    } else if (failedUsers.length > 5) {
        report += `⚠️ ${failedUsers.length} user gagal menerima pesan.\n`;
    }
    
    await sendInlineKeyboard(chatId, report, [
        [{ text: "📢 Broadcast Lagi", callback_data: "user_broadcast" }],
        [{ text: "🔙 Kembali", callback_data: "menu_user" }]
    ]);
    
    await clearSession(env, userId);
    return true;
}

// Batal broadcast
if (data === 'user_broadcast_send_no') {
    await smartResponse(chatId, '❌ Broadcast dibatalkan.', 'Markdown', { mode: 'auto', messageId: getCallbackMessageId() });
    await clearSession(env, userId);
    await sendInlineKeyboard(chatId, `👥 *Menu User*`, buildUserMenu());
    return true;
}

