if (data === 'user_leaderboard') {
    if (!isAdmin(userId)) {
        await answerCallback(callbackQueryId, '⛔ Akses ditolak');
        return true;
    }
    
    await answerCallback(callbackQueryId, '📈 Memuat leaderboard...');
    
    // Top kontributor
    const topUsers = await db.prepare(`
        SELECT 
            id, telegram_id, nama_lengkap, username, role, status,
            COALESCE(total_soal, 0) as total_soal,
            COALESCE(total_materi, 0) as total_materi,
            COALESCE(total_soal, 0) + COALESCE(total_materi, 0) as total_kontribusi
        FROM users
        WHERE status = 'AKTIF'
        ORDER BY total_kontribusi DESC, total_soal DESC
        LIMIT 10
    `).all();
    
    // Statistik aktivitas
    const activityStats = await db.prepare(`
        SELECT 
            action,
            COUNT(*) as total
        FROM user_activity
        GROUP BY action
        ORDER BY total DESC
        LIMIT 10
    `).all();
    
    // Top soal mingguan (7 hari terakhir)
    let topSoalMingguan = [];
    try {
        const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
        const weekData = await db.prepare(`
            SELECT 
                u.id, u.nama_lengkap, u.username,
                COUNT(s.id) as total
            FROM users u
            LEFT JOIN soal s ON s.created_by = u.telegram_id
            WHERE s.created_at >= ? OR s.tanggal_input >= ?
            GROUP BY u.id
            HAVING total > 0
            ORDER BY total DESC
            LIMIT 5
        `).bind(weekAgo, weekAgo).all();
        topSoalMingguan = weekData.results || [];
    } catch (e) {
        // Skip kalau tidak ada kolom created_by
        console.warn('Leaderboard mingguan skip:', e.message);
    }
    
    // ============================================================
    // BUILD MESSAGE
    // ============================================================
    let msg = `📈 *LEADERBOARD KONTRIBUTOR*\n\n`;
    msg += `🏆 *Top 10 Kontributor:*\n\n`;
    
    const icons = ['🥇', '🥈', '🥉'];
    
    if (topUsers.results && topUsers.results.length > 0) {
        topUsers.results.forEach((u, i) => {
            const rankIcon = icons[i] || `${i + 1}.`;
            const roleIcon = u.role === 'admin' ? '👑' :
                            u.role === 'teacher' ? '🎓' : '👤';
            
            msg += `${rankIcon} ${roleIcon} *${escapeMarkdownText(u.nama_lengkap || u.username || u.id)}*\n`;
            msg += `   📊 Total: ${u.total_kontribusi} kontribusi\n`;
            msg += `   ├─ 📝 Soal: ${u.total_soal}\n`;
            msg += `   └─ 📖 Materi: ${u.total_materi}\n\n`;
        });
    } else {
        msg += `❌ Belum ada kontributor.`;
    }
    
    // ============================================================
    // AKTIVITAS TERBANYAK
    // ============================================================
    if (activityStats.results && activityStats.results.length > 0) {
        msg += `\n📊 *Aktivitas Terbanyak:*\n`;
        const actionLabels = {
            'register': '🆕 Register',
            'update_user': '✏️ Update User',
            'delete_user': '🗑️ Delete User',
            'block_user': '🚫 Block User',
            'unblock_user': '🔓 Unblock User',
            'broadcast': '📢 Broadcast',
            'create_soal': '📝 Buat Soal',
            'create_materi': '📖 Buat Materi'
        };
        
        activityStats.results.slice(0, 5).forEach(a => {
            const label = actionLabels[a.action] || a.action;
            msg += `   ${label}: ${a.total}x\n`;
        });
    }
    
    // ============================================================
    // TOP SOAL MINGGUAN
    // ============================================================
    if (topSoalMingguan.length > 0) {
        msg += `\n🔥 *Top Soal (7 hari terakhir):*\n`;
        topSoalMingguan.forEach((u, i) => {
            msg += `   ${i + 1}. ${u.nama_lengkap || u.username || u.id}: ${u.total} soal\n`;
        });
    }
    
    // ============================================================
    // KEYBOARD
    // ============================================================
    const keyboard = [
        [{ text: "🔄 Refresh", callback_data: "user_leaderboard" }],
        [{ text: "📊 Statistik User", callback_data: "user_stats" }],
        [{ text: "🔙 Kembali", callback_data: "menu_user" }]
    ];
    
    // Split kalau terlalu panjang
    if (msg.length > 4000) {
        const parts = msg.match(/[\s\S]{1,4000}/g) || [];
        for (let i = 0; i < parts.length; i++) {
            if (i === parts.length - 1) {
                await sendInlineKeyboard(chatId, parts[i], keyboard);
            } else {
                await smartMessage(chatId, parts[i]);
            }
        }
    } else {
        await smartResponseUniversal(chatId, msg, { keyboard, mode: 'auto', messageId: getCallbackMessageId() });
    }
    return true;
}

