// ============================================================
// AI SAVE ALL - SIMPAN SEMUA SOAL DENGAN SUMBER
// ============================================================
if (data === 'ai_save_all') {
    const session = await getSession(env, userId);
    const soalList = session.aiGeneratedSoal || [];
    
    if (soalList.length === 0) {
        await smartResponse(chatId, '❌ Tidak ada soal untuk disimpan.', 'Markdown', { mode: 'auto', messageId: getCallbackMessageId() });
        return true;
    }
    
    // Kisi-Kisi harus berasal dari konteks sesi; jangan mengambil baris pertama sebagai default.
    const kisiId = session.kisiId || session.kisiKisiId || null;
    const tanggalInput = new Date().toISOString();
    
    const sumberBelajarId = session.aiSumberBelajarId || null;
    const sumberLink = session.aiSumberLink || null;
    
    let successCount = 0;
    let errorCount = 0;
    let errors = [];
    
    await smartMessage(chatId, `⏳ Menyimpan ${soalList.length} soal dengan sumber...`);
    
    for (const soal of soalList) {
        try {
            const soalText = (soal.soal || '').trim();
            if (!soalText) {
                errorCount++;
                errors.push('Soal kosong');
                continue;
            }
            
            const jawaban = (soal.jawaban || '').toUpperCase().trim();
            if (!['A','B','C','D','E'].includes(jawaban)) {
                errorCount++;
                errors.push(`Jawaban tidak valid: "${soal.jawaban}"`);
                continue;
            }
            
            // ============================================================
            // FIX D1: Pakai autoClassifyComplete + getMasterIdsComplete
            // ============================================================
            const classification = await autoClassifyComplete(soalText, null, db);
            const masterIds = classification.masterIds || await getMasterIdsComplete(db, classification, false);
            
            const pilihanA = (soal.pilihan_a || '').trim() || '';
            const pilihanB = (soal.pilihan_b || '').trim() || '';
            const pilihanC = (soal.pilihan_c || '').trim() || '';
            const pilihanD = (soal.pilihan_d || '').trim() || '';
            const pilihanE = (soal.pilihan_e || '').trim() || '';
            const preValidation = validateQuestionFull({soal:soalText,pilihanA,pilihanB,pilihanC,pilihanD,pilihanE,jawabanBenar:jawaban,jenisSoal:soal.jenis_soal || 'PEMAHAMAN',tingkatKesulitan:soal.tingkat_kesulitan || 'SEDANG',statusKeabsahan:'MANDIRI'});
            if(!preValidation.valid) throw new Error(`Validasi soal gagal: ${preValidation.errors.join(' ')}`);
            const duplicateRows = await findDuplicateQuestions(db,{soal:soalText,pilihanA,pilihanB,pilihanC,pilihanD,pilihanE});
            if(duplicateRows.length) throw new Error(`Soal duplikat: ${duplicateRows.map(x=>x.id).join(', ')}`);
            const id = await generateId(db, 'Q', 'soal');
            
            
            await db.prepare(`
                INSERT INTO soal (
                    id, kisi_kisi_id, sub_kemampuan_id,
                    soal, pilihan_a, pilihan_b, pilihan_c, pilihan_d, pilihan_e,
                    jawaban_benar, pembahasan, alasan_a, alasan_b, alasan_c, alasan_d, alasan_e,
                    status, tipe_soal, tanggal_input,
                    cara_penyajian_id, tipe_isi_id, tahap_pembelajaran_id,
                    level_hots, tipe_hots, sumber_belajar_id, sumber_link
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            `).bind(
                id,
                kisiId,
                null,
                soalText,
                pilihanA,
                pilihanB,
                pilihanC,
                pilihanD,
                pilihanE,
                jawaban,
                soal.pembahasan || null,
                soal.alasan_a || soal.alasanA || null,
                soal.alasan_b || soal.alasanB || null,
                soal.alasan_c || soal.alasanC || null,
                soal.alasan_d || soal.alasanD || null,
                soal.alasan_e || soal.alasanE || null,
                'AKTIF',
                'PG',
                tanggalInput,
                masterIds.penyajianId,
                masterIds.tipeIsiId,
                masterIds.tahapId,
                null,
                classification.prosesKognitif || classification.tipeHots || 'LOTS',
                sumberBelajarId,
                sumberLink
            ).run();
            
            successCount++;
        } catch (e) {
            errorCount++;
            errors.push(e.message);
        }
    }
    
    let response = `✅ *SIMPAN SEMUA SOAL SELESAI*\n\n`;
    response += `📊 Berhasil: ${successCount} soal\n`;
    response += `❌ Gagal: ${errorCount} soal\n`;
    
    if (sumberBelajarId || sumberLink) {
        response += `\n📚 *Sumber:*\n`;
        if (sumberBelajarId) {
            const sumberInfo = await db.prepare(
                `SELECT nama FROM sumber_belajar WHERE id = ?`
            ).bind(sumberBelajarId).first();
            if (sumberInfo) {
                response += `   📌 Nama: ${sumberInfo.nama}\n`;
            }
            response += `   🆔 ID: ${sumberBelajarId}\n`;
        }
        if (sumberLink) {
            response += `   🔗 Link: ${sumberLink}\n`;
        }
    }
    
    if (errors.length > 0) {
        response += `\n⚠️ Error:\n${errors.slice(0, 5).map(e => `- ${e}`).join('\n')}`;
        if (errors.length > 5) {
            response += `\n- ... dan ${errors.length - 5} error lainnya`;
        }
    }
    
    await smartMessage(chatId, response);
    
    session.aiGeneratedSoal = [];
    session.aiSumberBelajarId = null;
    session.aiSumberLink = null;
    await saveSession(env, userId, session);
    return true;
}

