    if (lastUnderscore === -1) {
        await smartResponse(chatId, '❌ Format tidak valid.', 'Markdown', { mode: 'auto', messageId: getCallbackMessageId() });
        return true;
    }
    const topicId = rest.substring(0, lastUnderscore);
    const level = rest.substring(lastUnderscore + 1);
    
    // VALIDASI topicId
    if (!topicId || topicId === 'undefined' || topicId === 'null' || topicId === '') {
        await smartResponse(chatId, '❌ ID Topik tidak valid.', 'Markdown', { mode: 'auto', messageId: getCallbackMessageId() });
        return true;
    }
    
    const topicCheck = await db.prepare(`SELECT id, nama FROM topik WHERE id = ?`).bind(topicId).first();
    if (!topicCheck) {
        await smartMessage(chatId, `❌ Topik dengan ID ${topicId} tidak ditemukan.`);
        return true;
    }
    
    const session = await getSession(env, userId);
    session.aiTopicId = topicId;
    session.aiLevel = level;
    session.aiCustomStep = 'jumlah';
