// ============================================================
// SIMPAN SOAL DARI CALLBACK ai_save_all_* 
// ============================================================
if (data.startsWith('ai_save_all_')) {
    const topicId = data.replace('ai_save_all_', '');
    
    const session = await getSession(env, userId);
    const soalList = session.aiGeneratedSoal || [];
    
    if (soalList.length === 0) {
        await smartResponse(chatId, '❌ Tidak ada soal untuk disimpan.', 'Markdown', { mode: 'auto', messageId: getCallbackMessageId() });
        return true;
    }
    
    const kisiId = session.kisiId || session.kisiKisiId || null;
    
    let successCount = 0;
    let errors = [];
    const tanggalInput = new Date().toISOString();
    
    for (const soal of soalList) {
        try {
            const soalText = (soal.soal || '').trim();
            if (!soalText) {
                errors.push('Soal kosong');
                continue;
            }
            
            const jawaban = (soal.jawaban || '').toUpperCase().trim();
            if (!['A','B','C','D','E'].includes(jawaban)) {
                errors.push(`Jawaban tidak valid: "${soal.jawaban}"`);
                continue;
            }
            
            // ============================================================
            // FIX D1: Pakai autoClassifyComplete + getMasterIdsComplete
            // ============================================================
            const classification = await autoClassifyComplete(soalText, null, db);
            const masterIds = classification.masterIds || await getMasterIdsComplete(db, classification, false);
            
            
            
            const pilihanA = (soal.pilihan_a || '').trim() || '';
            const pilihanB = (soal.pilihan_b || '').trim() || '';
            const pilihanC = (soal.pilihan_c || '').trim() || '';
            const pilihanD = (soal.pilihan_d || '').trim() || '';
            const pilihanE = (soal.pilihan_e || '').trim() || '';
            const preValidation = validateQuestionFull({soal:soalText,pilihanA,pilihanB,pilihanC,pilihanD,pilihanE,jawabanBenar:jawaban,jenisSoal:soal.jenis_soal || 'PEMAHAMAN',tingkatKesulitan:soal.tingkat_kesulitan || 'SEDANG',statusKeabsahan:'MANDIRI'});
            if(!preValidation.valid) throw new Error(`Validasi soal gagal: ${preValidation.errors.join(' ')}`);
            const duplicateRows = await findDuplicateQuestions(db,{soal:soalText,pilihanA,pilihanB,pilihanC,pilihanD,pilihanE});
            if(duplicateRows.length) throw new Error(`Soal duplikat: ${duplicateRows.map(x=>x.id).join(', ')}`);
            const id = await generateId(db, 'Q', 'soal');
            
            await db.prepare(`
                INSERT INTO soal (
                    id, kisi_kisi_id, sub_kemampuan_id,
                    soal, pilihan_a, pilihan_b, pilihan_c, pilihan_d, pilihan_e,
                    jawaban_benar, pembahasan, alasan_a, alasan_b, alasan_c, alasan_d, alasan_e,
                    status, tipe_soal, tanggal_input,
                    cara_penyajian_id, tipe_isi_id, tahap_pembelajaran_id,
                    level_hots, tipe_hots, tingkat_kesulitan
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            `).bind(
                id,
                kisiId,
                null,
                soalText,
                pilihanA,
                pilihanB,
                pilihanC,
                pilihanD,
                pilihanE,
                jawaban,
                soal.pembahasan || null,
                soal.alasan_a || soal.alasanA || null,
                soal.alasan_b || soal.alasanB || null,
                soal.alasan_c || soal.alasanC || null,
                soal.alasan_d || soal.alasanD || null,
                soal.alasan_e || soal.alasanE || null,
                'AKTIF',
                'PG',
                tanggalInput,
                masterIds.penyajianId,
                masterIds.tipeIsiId,
                masterIds.tahapId,
                null,
                classification.prosesKognitif || classification.tipeHots || getProsesKognitif(null, classification.levelHots) || 'LOTS',
                getDefaultDifficulty(soal.tingkat_kesulitan || classification.tingkatKesulitan)
            ).run();
            
            successCount++;
        } catch (e) {
            errors.push(e.message);
        }
    }
    
    await smartMessage(chatId, 
        `✅ *${soalList.length} SOAL BERHASIL DISIMPAN!*\n\n` +
        `📊 *Berhasil:* ${successCount} soal\n` +
        `❌ *Gagal:* ${errors.length} soal\n\n` +
        `${errors.length > 0 ? `⚠️ Error: ${errors.slice(0, 3).join(', ')}` : ''}`
    );
    
    session.aiGeneratedSoal = [];
    await saveSession(env, userId, session);
    return true;
}

// ============================================================
// SIMPAN PEMBAHASAN BATCH - DENGAN AUTO-CLASSIFY
// ============================================================
if (data === 'ai_save_pembahasan_batch') {
    const session = await getSession(env, userId);
    const soalList = session.aiGeneratedSoal || [];
    
    if (soalList.length === 0) {
        await smartResponse(chatId, '❌ Tidak ada pembahasan untuk disimpan.', 'Markdown', { mode: 'auto', messageId: getCallbackMessageId() });
        return true;
    }
    
    let successCount = 0;
    let errors = [];
    
    await smartMessage(chatId, `⏳ Menyimpan pembahasan untuk ${soalList.length} soal...`);
    
    for (const soal of soalList) {
        try {
            if (!soal.pembahasan || soal.pembahasan === 'Pembahasan tidak tersedia') {
                errors.push(`Soal "${soal.soal.substring(0, 30)}..." - Tidak ada pembahasan`);
                continue;
            }
            
            const existing = await db.prepare(`
                SELECT cara_penyajian_id, tipe_isi_id, tahap_pembelajaran_id, level_hots
                FROM soal WHERE soal = ? AND status = 'AKTIF'
            `).bind(soal.soal).first();
            
            let updateFields = ['pembahasan = ?'];
            let bindParams = [soal.pembahasan];
            
            if (!existing || (!existing.cara_penyajian_id && !existing.tipe_isi_id)) {
                // ============================================================
                // FIX D1: Pakai autoClassifyComplete + getMasterIdsComplete
                // ============================================================
                const classification = await autoClassifyComplete(soal.soal, null, db);
                const masterIds = classification.masterIds || await getMasterIdsComplete(db, classification, false);
                
                if (masterIds.penyajianId) {
                    updateFields.push('cara_penyajian_id = ?');
                    bindParams.push(masterIds.penyajianId);
                }
                if (masterIds.tipeIsiId) {
                    updateFields.push('tipe_isi_id = ?');
                    bindParams.push(masterIds.tipeIsiId);
                }
                if (masterIds.tahapId) {
                    updateFields.push('tahap_pembelajaran_id = ?');
                    bindParams.push(masterIds.tahapId);
                }
                if (classification.prosesKognitif || classification.tipeHots || classification.levelHots) {
                    updateFields.push('level_hots = NULL');
                    updateFields.push('tipe_hots = ?');
                    bindParams.push(classification.prosesKognitif || classification.tipeHots || getProsesKognitif(null, classification.levelHots) || 'LOTS');
                }
            }
            
            bindParams.push(soal.soal);
            
            await db.prepare(`
                UPDATE soal SET ${updateFields.join(', ')} WHERE soal = ? AND status = 'AKTIF'
            `).bind(...bindParams).run();
            
            successCount++;
        } catch (e) {
            errors.push(e.message);
        }
    }
    
    await smartMessage(chatId, 
        `✅ *PEMBAHASAN BERHASIL DISIMPAN!*\n\n` +
        `📊 *Berhasil:* ${successCount} soal\n` +
        `❌ *Gagal:* ${errors.length} soal\n` +
        `🏷️ *Klasifikasi juga diperbarui*\n\n` +
        `${errors.length > 0 ? `⚠️ Error: ${errors.slice(0, 3).join(', ')}` : ''}`
    );
    
    return true;
}

