if (data.startsWith('ai_save_pembahasan_') && !data.includes('batch')) {
    const soalId = data.replace('ai_save_pembahasan_', '');
    
    const session = await getSession(env, userId);
    const pembahasan = session.aiGeneratedPembahasan || null;
    const soalIdSession = session.aiPembahasanSoalId || null;
    
    if (!pembahasan) {
        await smartMessage(chatId, 
            `❌ Tidak ada pembahasan untuk disimpan.\n\n` +
            `💡 Generate pembahasan terlebih dahulu.`
        );
        return true;
    }
    
    try {
        await smartMessage(chatId, `⏳ Menyimpan pembahasan untuk soal ${soalId}...`);
        
        // Cek soal ada
        const soal = await db.prepare(`
            SELECT id, cara_penyajian_id, tipe_isi_id, tahap_pembelajaran_id, level_hots
            FROM soal WHERE id = ? AND status = 'AKTIF'
        `).bind(soalId).first();
        
        if (!soal) {
            await smartMessage(chatId, `❌ Soal ${soalId} tidak ditemukan.`);
            return true;
        }
        
        // Update pembahasan
        let updateFields = ['pembahasan = ?'];
        let bindParams = [pembahasan];
        
        // Kalau klasifikasi belum ada, isi
        if (!soal.cara_penyajian_id && !soal.tipe_isi_id) {
            // Gunakan teks soal (bukan pembahasan) untuk klasifikasi
            const soalText = soal.soal || '';
            if (soalText) {
                const classification = await autoClassifyComplete(soalText, null, db);
                const masterIds = classification.masterIds || await getMasterIdsComplete(db, classification, false);
                
                if (masterIds.penyajianId) {
                    updateFields.push('cara_penyajian_id = ?');
                    bindParams.push(masterIds.penyajianId);
                }
                if (masterIds.tipeIsiId) {
                    updateFields.push('tipe_isi_id = ?');
                    bindParams.push(masterIds.tipeIsiId);
                }
                if (masterIds.tahapId) {
                    updateFields.push('tahap_pembelajaran_id = ?');
                    bindParams.push(masterIds.tahapId);
                }
                if (classification.prosesKognitif || classification.tipeHots || classification.levelHots) {
                    updateFields.push('level_hots = NULL');
                    updateFields.push('tipe_hots = ?');
                    bindParams.push(classification.prosesKognitif || classification.tipeHots || getProsesKognitif(null, classification.levelHots) || 'LOTS');
                }
            }
        }
        
        bindParams.push(soalId);
        
        await db.prepare(`
            UPDATE soal SET ${updateFields.join(', ')} WHERE id = ?
        `).bind(...bindParams).run();
        
        await smartMessage(chatId, 
            `✅ *PEMBAHASAN BERHASIL DISIMPAN!*\n\n` +
            `🆔 Soal: ${soalId}\n` +
            `📊 Jumlah kata: ${pembahasan.split(/\s+/).length}\n` +
            `🏷️ Klasifikasi juga diperbarui`
        );
        
        // Clear session pembahasan
        session.aiGeneratedPembahasan = null;
        session.aiPembahasanSoalId = null;
        await saveSession(env, userId, session);
        
    } catch (e) {
        console.error('Simpan pembahasan per soal error:', e);
        await smartMessage(chatId, `❌ Gagal menyimpan: ${e.message}`);
    }
    
    return true;
}

