// ============================================================
// HANDLER GENERATE MATERI - FLEKSIBEL BATCH
// ============================================================

async function handleGenerateMateri(env, userId, chatId, db, params) {
    const { topicId, topicName, format } = params;
    
    try {
        // ===== TENTUKAN ATURAN PER FORMAT =====
        let formatRules = {
            minWords: 0,
            maxWords: 0,
            batchSize: 0,
            description: ''
        };
        
        switch (format) {
            case 'ringkasan':
                formatRules = {
                    minWords: 100,
                    maxWords: 1000,
                    batchSize: 1000,
                    description: 'Ringkasan Padat (100-1.000 kata)'
                };
                break;
                
            case 'penjelasan':
                formatRules = {
                    minWords: 5000,
                    maxWords: 15000,
                    batchSize: 500,
                    description: 'Penjelasan Detail + 10 Contoh Soal (5.000-15.000 kata)'
                };
                break;
                
            case 'peta_konsep':
                formatRules = {
                    minWords: 0,
                    maxWords: 0,
                    batchSize: 0,
                    description: 'Peta Konsep'
                };
                break;
                
            case 'rangkuman':
                formatRules = {
                    minWords: 500,
                    maxWords: 2000,
                    batchSize: 2000,
                    description: 'Rangkuman Lengkap (500-2.000 kata)'
                };
                break;
                
            default:
                formatRules = {
                    minWords: 0,
                    maxWords: 0,
                    batchSize: 0,
                    description: 'Format Standar'
                };
        }
        
        // ===== INFORMASI PROSES =====
        let infoMsg = `📚 *MENGENERATE MATERI*\n\n`;
        infoMsg += `📖 Topik: ${topicName}\n`;
        infoMsg += `📋 Format: ${format}\n`;
        infoMsg += `📊 Target: ${formatRules.description}\n`;
        
        if (format === 'penjelasan') {
            infoMsg += `📦 Strategi: Kirim per ${formatRules.batchSize} kata\n`;
            infoMsg += `⏳ Estimasi: 5-15 menit (tergantung panjang materi)\n\n`;
            infoMsg += `📌 Materi akan dikirim secara bertahap.\n`;
            infoMsg += `📌 Anda akan mendapat notifikasi setiap selesai 500 kata.\n`;
            infoMsg += `📝 Di akhir materi, akan ada 10 contoh soal + pembahasan.\n`;
        } else {
            infoMsg += `⏳ Estimasi: 1-3 menit\n\n`;
            infoMsg += `📌 Materi akan dikirim dalam 1 kali kiriman.\n`;
        }
        
        infoMsg += `⏳ Memulai proses...`;
        
        await smartMessage(chatId, infoMsg);
        
        // ===== GENERATE MATERI =====
        let allResponses = [];
        let totalWords = 0;
        let provider = '';
        let method = '';
        let batchNumber = 1;
        let isLastBatch = false;
        let accumulatedResponse = '';
        let accumulatedWords = 0;
        let batchResponses = [];
        
        // ===== UNTUK FORMAT YANG TIDAK PERLU BATCH =====
        if (format !== 'penjelasan') {
            // Generate langsung 1 batch
            const prompt = buildGenerateMateriPrompt(
                topicName,
                params.subtopicName || 'Subtopik',
                params.kemampuanNama || 'Kemampuan',
                params.subKemampuanNama || 'Sub-Kemampuan',
                params.kisiJudul || 'Kisi-Kisi',
                format,
                1,
                true,
                0
            );
            
            const result = await callAIHybrid(prompt, 'generate_materi', env);
            
            if (!result.success) {
                await smartMessage(chatId, 
                    `❌ *Gagal generate materi!*\n\n` +
                    `Error: ${result.error || 'Unknown error'}`
                );
                return;
            }
            
            const wordCount = result.response.split(/\s+/).length;
            
            // Tampilkan hasil
            const formatLabels = {
                'ringkasan': '📄 Ringkasan Materi',
                'peta_konsep': '🗺️ Peta Konsep',
                'rangkuman': '📋 Rangkuman'
            };
            
            let output = `📚 *${formatLabels[format] || 'Materi'}*\n\n`;
            output += `📖 *Topik:* ${topicName}\n`;
            output += `🤖 *AI:* ${result.provider} (${result.method})\n`;
            output += `📊 *Jumlah Kata:* ${wordCount.toLocaleString()} kata\n`;
            if (result.time) output += `⏱️ *Waktu:* ${(result.time/1000).toFixed(1)} detik\n`;
            output += `\n---\n\n`;
            output += result.response;
            
            // Validasi untuk ringkasan dan rangkuman
            if (format === 'ringkasan' && wordCount < 100) {
                output += `\n\n⚠️ *Catatan:* Ringkasan hanya ${wordCount} kata (minimal 100 kata).\n`;
                output += `💡 Coba lagi dengan format "penjelasan" untuk materi lebih panjang.`;
            }
            
            if (format === 'rangkuman' && wordCount < 500) {
                output += `\n\n⚠️ *Catatan:* Rangkuman hanya ${wordCount} kata (minimal 500 kata).\n`;
                output += `💡 Coba lagi dengan format "penjelasan" untuk materi lebih panjang.`;
            }
            
            // Kirim output
            if (output.length > 4000) {
                const parts = output.match(/.{1,4000}/g) || [];
                for (const part of parts) {
                    await smartMessage(chatId, part);
                }
            } else {
                await smartMessage(chatId, output);
            }
            
            // Keyboard
            const keyboard = [
                [{ text: "📝 Generate Soal dari Materi", callback_data: `ai_soal_dari_materi_${topicId}` }],
                [{ text: "🔄 Regenerate", callback_data: `ai_materi_regen_${topicId}` }],
                [{ text: "🔙 Kembali", callback_data: "ai_menu" }]
            ];
            
            await sendInlineKeyboard(chatId, 
                `✅ *Materi selesai digenerate!*\n\n` +
                `📊 ${wordCount.toLocaleString()} kata\n` +
                `🤖 ${result.provider}`,
                keyboard
            );
            
            // Simpan session
            const session = await getSession(env, userId);
            session.aiMateriTopicId = topicId;
            session.aiMateriFormat = format;
            session.aiMateriContent = result.response;
            session.aiMateriWordCount = wordCount;
            session.aiMateriBatches = 1;
            await saveSession(env, userId, session);
            
            return;
        }
        
        // ===== UNTUK PENJELASAN DETAIL (BATCH PER 500 KATA) =====
        let maxAttempts = 10;
        let attempt = 0;
        
        while (totalWords < formatRules.maxWords && attempt < maxAttempts) {
            attempt++;
            isLastBatch = (totalWords >= formatRules.minWords && totalWords < formatRules.maxWords);
            
            if (totalWords >= formatRules.minWords && totalWords + 500 >= formatRules.maxWords) {
                isLastBatch = true;
            }
            
            // Kirim notifikasi batch
            if (attempt > 1) {
                await smartMessage(chatId, 
                    `📦 *Batch ${attempt} sedang diproses...*\n` +
                    `📊 Total kata saat ini: ${totalWords.toLocaleString()}\n` +
                    `⏳ Mohon tunggu...`
                );
            }
            
            // Build prompt untuk batch ini
            const prompt = buildGenerateMateriPrompt(
                topicName,
                params.subtopicName || 'Subtopik',
                params.kemampuanNama || 'Kemampuan',
                params.subKemampuanNama || 'Sub-Kemampuan',
                params.kisiJudul || 'Kisi-Kisi',
                format,
                attempt,
                isLastBatch || attempt >= maxAttempts - 1,
                totalWords
            );
            
            // Panggil AI
            const result = await callAIHybrid(prompt, 'generate_materi', env);
            
            if (!result.success) {
                await smartMessage(chatId, 
                    `⚠️ *Batch ${attempt} gagal!*\n\n` +
                    `Error: ${result.error || 'Unknown error'}\n\n` +
                    `💡 Melanjutkan ke batch berikutnya...`
                );
                continue;
            }
            
            // Hitung kata di response ini
            const responseText = result.response;
            const wordCount = responseText.split(/\s+/).length;
            
            // Simpan
            allResponses.push(responseText);
            totalWords += wordCount;
            accumulatedResponse += (accumulatedResponse ? '\n\n---\n\n' : '') + responseText;
            
            if (!provider) provider = result.provider;
            if (!method) method = result.method;
            
            // ===== TAMPILKAN BATCH INI (jika >= 500 kata) =====
            if (wordCount >= 500 || isLastBatch || attempt === maxAttempts - 1) {
                let batchOutput = `📚 *Penjelasan Detail - Batch ${attempt}*\n\n`;
                batchOutput += `📖 *Topik:* ${topicName}\n`;
                batchOutput += `📊 *Kata Batch Ini:* ${wordCount.toLocaleString()} kata\n`;
                batchOutput += `📊 *Total Kata:* ${totalWords.toLocaleString()} kata\n`;
                batchOutput += `🤖 *AI:* ${result.provider} (${result.method})\n`;
                if (result.time) batchOutput += `⏱️ *Waktu:* ${(result.time/1000).toFixed(1)} detik\n`;
                batchOutput += `\n---\n\n`;
                batchOutput += responseText;
                
                // Kirim batch output — DENGAN SANITIZE
const sanitizedBatch = sanitizeAIContent(batchOutput);

if (sanitizedBatch.length > 4000) {
    const parts = sanitizedBatch.match(/.{1,4000}/g) || [];
    for (const part of parts) {
        await smartMessage(chatId, part, null);
        await new Promise(r => setTimeout(r, 300));
    }
} else {
    await smartMessage(chatId, sanitizedBatch, null);
}
                
                // Reset accumulated untuk batch berikutnya
                accumulatedResponse = '';
                accumulatedWords = 0;
            } else {
                // Simpan sementara jika belum mencapai 500 kata
                accumulatedWords += wordCount;
                await smartMessage(chatId, 
                    `⏳ *Terkumpul ${totalWords.toLocaleString()} kata...*\n` +
                    `📦 Menunggu hingga 500 kata untuk dikirim.\n` +
                    `📌 Batch ${attempt} (${wordCount} kata) akan digabung dengan batch berikutnya.`
                );
            }
            
            // ===== CEK APAKAH SUDAH MENCAPAI TARGET =====
            if (totalWords >= formatRules.minWords && totalWords >= 5000) {
                const remaining = formatRules.maxWords - totalWords;
                if (remaining < 500) {
                    isLastBatch = true;
                }
                
                if (isLastBatch || attempt >= maxAttempts - 1) {
                    await smartMessage(chatId, 
                        `✅ *Materi mencapai target!*\n\n` +
                        `📊 Total: ${totalWords.toLocaleString()} kata\n` +
                        `📦 Batch: ${attempt} tahap\n\n` +
                        `🎉 Materi selesai digenerate!`
                    );
                    break;
                }
            }
            
            // ===== TUNGGU SEBENTAR ANTAR BATCH =====
            if (attempt < maxAttempts - 1 && totalWords < formatRules.maxWords) {
                await new Promise(resolve => setTimeout(resolve, 2000));
            }
        }
        
        // ===== RINGKASAN AKHIR =====
        if (totalWords < formatRules.minWords) {
            await smartMessage(chatId, 
                `⚠️ *Materi hanya ${totalWords.toLocaleString()} kata*\n\n` +
                `Target minimal: ${formatRules.minWords.toLocaleString()} kata\n` +
                `💡 Coba lagi atau gunakan prompt yang lebih spesifik.`
            );
        } else {
            let summary = `✅ *PENJELASAN DETAIL SELESAI!*\n\n`;
            summary += `📖 *Topik:* ${topicName}\n`;
            summary += `📊 *Total Kata:* ${totalWords.toLocaleString()} kata\n`;
            summary += `📦 *Total Batch:* ${attempt} tahap\n`;
            summary += `🤖 *AI:* ${provider} (${method})\n`;
            summary += `📝 *Bonus:* 10 contoh soal + pembahasan\n\n`;
            
            if (totalWords >= 15000) {
                summary += `🎉 *Luar biasa!* Materi mencapai 15.000+ kata!\n`;
            } else if (totalWords >= 5000) {
                summary += `✅ Materi sudah mencapai target minimal 5.000 kata.\n`;
                summary += `💡 Untuk materi lebih panjang, ulangi dengan prompt yang lebih detail.\n`;
            }
            
            const keyboard = [
                [{ text: "📝 Generate Soal dari Materi", callback_data: `ai_soal_dari_materi_${topicId}` }],
                [{ text: "🔄 Regenerate", callback_data: `ai_materi_regen_${topicId}` }],
                [{ text: "🔙 Kembali", callback_data: "ai_menu" }]
            ];
            
            await sendInlineKeyboard(chatId, summary, keyboard);
        }
        
        // Simpan session
        const session = await getSession(env, userId);
        session.aiMateriTopicId = topicId;
        session.aiMateriFormat = format;
        session.aiMateriContent = allResponses.join('\n\n---\n\n');
        session.aiMateriWordCount = totalWords;
        session.aiMateriBatches = attempt;
        await saveSession(env, userId, session);
        
    } catch (e) {
        console.error('Generate Materi Error:', e);
        await smartMessage(chatId, `❌ *Error:* ${e.message}`);
    }
}


