if (data === 'confirm_delete_kategori_yes') {
    const session = await getSession(env, userId);
    if (!session.tempData || !session.tempData.items) {
        await smartMessage(chatId, '❌ Data tidak valid.');
        await clearSession(env, userId);
        return true;
    }
    const items = session.tempData.items;
    let success = [], failed = [], totalDeleted = 0;
    for (const item of items) {
        try {
            const result = await deleteCascade(db, 'kategori', item.id, userId);
            if (result.success) { success.push(item.id); totalDeleted += result.deletedCount; }
            else failed.push(item.id);
        } catch (e) { failed.push(item.id); }
    }
    await clearSession(env, userId);
    let msg = `✅ *HAPUS SELESAI*\n${DIVIDER}\n\n`;
    msg += `📊 ${success.length} dihapus • ${totalDeleted} entitas terhapus\n`;
    if (failed.length > 0) msg += `❌ ${failed.length} gagal : ${failed.join(', ')}`;
    const keyboard = [[{ text: "🔙 Kembali ke Menu Kategori", callback_data: "menu_kategori" }]];
    const messageId = getCallbackMessageId();
    await smartResponseUniversal(chatId, msg, {
        keyboard,
        mode: 'auto',
        messageId
    });
    return true;
}

