if (data === 'confirm_sort_kategori_az_yes') {
    let sortLock = null;
    try {
        sortLock = await acquireReorderLock(db, 'kategori', 'id');
        if (!sortLock.acquired) {
            await smartMessage(chatId, `⚠️ Kategori sedang diproses oleh operasi urutan/perubahan ID lain. Silakan coba lagi setelah proses selesai.`);
            return true;
        }
        const allKategori = await db.prepare(`SELECT id FROM kategori ORDER BY nama ASC, id ASC`).all();
        let counter = 1;
        for (const k of (allKategori.results || [])) {
            await db.prepare(`UPDATE kategori SET urutan = ? WHERE id = ?`).bind(counter, k.id).run();
            counter++;
        }
        let msg = `✅ *SORT BERHASIL*\n${DIVIDER}\n\n📊 ${counter - 1} kategori diurutkan A-Z\n📌 ID TIDAK berubah`;
        const keyboard = [[{ text: "🔙 Kembali ke Menu Kategori", callback_data: "menu_kategori" }]];
        const messageId = getCallbackMessageId();
        await smartResponseUniversal(chatId, msg, {
            keyboard,
            mode: 'auto',
            messageId
        });
    } catch (e) {
        await smartMessage(chatId, `❌ Gagal sort : ${e.message}`);
    } finally {
        await releaseReorderLock(db, sortLock);
    }
    return true;
}

