        // CEK KOLOM YANG TERSEDIA
        const tableInfo = await db.prepare(`PRAGMA table_info(soal)`).all();
        const columns = (tableInfo.results || []).map(c => c.name);
        const hasKeabsahan = columns.includes('status_keabsahan');
        const hasKetersediaan = columns.includes('status_ketersediaan');
        
        let msg = `📁 *MANAJEMEN ARSIP SOAL*\n\n`;
        
        // AMBIL STATISTIK
        let stats = { results: [] };
