// ============================================================
// ARSIP - LIHAT SEMUA (DENGAN FALLBACK)
// ============================================================
if (data === 'arsip_list') {
    try {
        console.log("✅ Arsip list dipanggil");
        const page = parseInt(data.split('_')[2]) || 1;
        const offset = (page - 1) * 10;
        
        // Cek kolom yang tersedia
        const tableInfo = await db.prepare(`PRAGMA table_info(soal)`).all();
        const columns = (tableInfo.results || []).map(c => c.name);
        const hasKategoriArsip = columns.includes('kategori_arsip');
        const hasTanggalArsip = columns.includes('tanggal_arsip');
        
        // Build query dinamis
        let selectFields = 'id, soal, status';
        if (hasKategoriArsip) selectFields += ', kategori_arsip';
        if (hasTanggalArsip) selectFields += ', tanggal_arsip';
        
        const r = await db.prepare(`
            SELECT ${selectFields}
            FROM soal 
            WHERE status = 'ARSIP' 
            ORDER BY id DESC 
            LIMIT 10 OFFSET ?
        `).bind(offset).all();
        
        const count = await db.prepare(`
            SELECT COUNT(*) as total FROM soal WHERE status='ARSIP'
        `).first();
        
        const totalPages = Math.ceil((count?.total || 0) / 10);
        let msg = `📦 *DAFTAR SOAL ARSIP (Hal ${page}/${totalPages || 1})*\n\n`;
        
        if (!r.results || r.results.length === 0) {
            msg += 'Belum ada soal yang diarsipkan.';
        } else {
            r.results.forEach((s, i) => {
                const soalText = (s.soal || '').substring(0, 50);
                msg += `${i+1+offset}. *${s.id}* - ${soalText}${(s.soal||'').length > 50 ? '...' : ''}\n`;
                if (hasKategoriArsip && s.kategori_arsip) {
                    msg += `   🏷️ ${s.kategori_arsip}`;
                }
                if (hasTanggalArsip && s.tanggal_arsip) {
                    msg += ` | 📅 ${new Date(s.tanggal_arsip).toLocaleDateString('id-ID')}`;
                }
                msg += `\n\n`;
            });
        }
        
        const keyboard = [];
        if (totalPages > 1) {
            const navButtons = [];
            if (page > 1) {
                navButtons.push({ text: "⬅️ Sebelumnya", callback_data: `arsip_page_${page-1}` });
            }
            navButtons.push({ text: `📄 ${page}/${totalPages}`, callback_data: 'arsip_page_jump' });
            if (page < totalPages) {
                navButtons.push({ text: "➡️ Selanjutnya", callback_data: `arsip_page_${page+1}` });
            }
            if (navButtons.length > 0) keyboard.push(navButtons);
        }
        for (const s of (r.results || [])) {
            keyboard.push([{ text: `🆔 ${s.id}`, callback_data: `ent_view_soal_${s.id}` }]);
        }
        keyboard.push([{ text: "🔙 Kembali ke Menu Arsip", callback_data: "menu_arsip" }]);
        
        await sendInlineKeyboard(chatId, msg, keyboard);
        return true;
        
    } catch (e) {
        console.error('Arsip list error:', e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
        return true;
    }
}

// ============================================================
// FILTER ARSIP BERDASARKAN STATUS KEABSAHAN - PERBAIKAN
// ============================================================
if (data.startsWith('arsip_filter_')) {
    const keabsahan = data.replace('arsip_filter_', '');
    console.log(`✅ Arsip filter dipanggil untuk: ${keabsahan}`);
    
    const validKeabsahan = ['resmi', 'adaptasi', 'mandiri'];
    if (!validKeabsahan.includes(keabsahan)) {
        await smartMessage(chatId, '❌ Filter tidak valid.');
        return true;
    }
    
    try {
        const keabsahanLabel = {
            'resmi': '🏛️ Resmi',
            'adaptasi': '🔄 Adaptasi',
            'mandiri': '✏️ Mandiri'
        };
        
        // Cek kolom yang tersedia
        const tableInfo = await db.prepare(`PRAGMA table_info(soal)`).all();
        const columns = (tableInfo.results || []).map(c => c.name);
        const hasKategoriArsip = columns.includes('kategori_arsip');
        const hasTanggalArsip = columns.includes('tanggal_arsip');
        const hasStatusKeabsahan = columns.includes('status_keabsahan');
        const hasStatusKetersediaan = columns.includes('status_ketersediaan');
        
        // Build query dinamis
        let selectFields = 'id, soal, status';
        if (hasKategoriArsip) selectFields += ', kategori_arsip';
        if (hasTanggalArsip) selectFields += ', tanggal_arsip';
        if (hasStatusKeabsahan) selectFields += ', status_keabsahan';
        
        let whereClause = '';
        let bindParams = [];
        
        if (hasStatusKeabsahan && hasStatusKetersediaan) {
            whereClause = 'WHERE status_ketersediaan = ? AND status_keabsahan = ?';
            bindParams = ['arsip', keabsahan];
        } else {
            // Fallback: gunakan status biasa
            whereClause = 'WHERE status = ?';
            bindParams = ['ARSIP'];
        }
        
        const soals = await db.prepare(`
            SELECT ${selectFields}
            FROM soal 
            ${whereClause}
            ORDER BY id DESC 
            LIMIT 20
        `).bind(...bindParams).all();
        
        let msg = `📦 *ARSIP ${keabsahanLabel[keabsahan].toUpperCase()}*\n\n`;
        
        if (!soals.results || soals.results.length === 0) {
            msg += `❌ Tidak ada soal arsip dengan status ${keabsahanLabel[keabsahan]}.`;
        } else {
            soals.results.forEach((s, i) => {
                const soalText = (s.soal || '').substring(0, 60);
                msg += `${i+1}. *${s.id}* - ${soalText}${(s.soal||'').length > 60 ? '...' : ''}\n`;
                if (hasKategoriArsip && s.kategori_arsip) {
                    msg += `   🏷️ ${s.kategori_arsip}`;
                }
                if (hasStatusKeabsahan && s.status_keabsahan) {
                    msg += ` | 🏷️ ${s.status_keabsahan}`;
                }
                if (hasTanggalArsip && s.tanggal_arsip) {
                    msg += ` | 📅 ${new Date(s.tanggal_arsip).toLocaleDateString('id-ID')}`;
                }
                msg += `\n\n`;
            });
        }
        
        const keyboard = [
            [{ text: "🔙 Kembali ke Menu Arsip", callback_data: "menu_arsip" }]
        ];
        
        await sendInlineKeyboard(chatId, msg, keyboard);
        return true;
        
    } catch (e) {
        console.error('Arsip filter error:', e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
        return true;
    }
}

// ============================================================
// STATISTIK ARSIP LENGKAP - PERBAIKAN
// ============================================================
if (data === 'arsip_statistik') {
    console.log(`✅ Arsip statistik dipanggil`);
    
    try {
        if (!db) {
            await smartMessage(chatId, '❌ Database tidak tersedia.');
            return true;
        }
        
        // ============================================================
        // CEK KOLOM YANG TERSEDIA
        // ============================================================
        const tableInfo = await db.prepare(`PRAGMA table_info(soal)`).all();
        const columns = (tableInfo.results || []).map(c => c.name);
        const hasStatusKeabsahan = columns.includes('status_keabsahan');
        const hasStatusKetersediaan = columns.includes('status_ketersediaan');
        const hasKategoriArsip = columns.includes('kategori_arsip');
        const hasTanggalArsip = columns.includes('tanggal_arsip');
        
        console.log(`📊 Kolom status_keabsahan: ${hasStatusKeabsahan ? 'ADA' : 'TIDAK ADA'}`);
        console.log(`📊 Kolom status_ketersediaan: ${hasStatusKetersediaan ? 'ADA' : 'TIDAK ADA'}`);
        console.log(`📊 Kolom kategori_arsip: ${hasKategoriArsip ? 'ADA' : 'TIDAK ADA'}`);
        
        let msg = `📊 *STATISTIK ARSIP LENGKAP*\n\n`;
        let totalAll = 0;
        
        // ============================================================
        // 1. STATISTIK PER STATUS KEABSAHAN
        // ============================================================
        msg += `📌 *Per Status Keabsahan:*\n`;
        
        let stats = { results: [] };
        
        if (hasStatusKeabsahan && hasStatusKetersediaan) {
            // Gunakan query dengan status_keabsahan dan status_ketersediaan
            stats = await db.prepare(`
                SELECT 
                    status_keabsahan,
                    COUNT(*) as total
                FROM soal 
                WHERE status_ketersediaan = 'arsip'
                GROUP BY status_keabsahan
                ORDER BY total DESC
            `).all();
        } else {
            // Fallback: gunakan status biasa
            stats = await db.prepare(`
                SELECT 
                    status as status_keabsahan,
                    COUNT(*) as total
                FROM soal 
                WHERE status = 'ARSIP'
                GROUP BY status
                ORDER BY total DESC
            `).all();
        }
        
        const keabsahanIcons = {
            'resmi': '🏛️',
            'adaptasi': '🔄',
            'mandiri': '✏️',
            'draft_keabsahan': '📝',
            'ARSIP': '📦',
            'AKTIF': '✅',
            'DRAFT': '📝',
            'REVIEW': '🔍',
            'PUBLISH': '✅',
            'REVISI': '🔄'
        };
        
        const keabsahanLabels = {
            'resmi': 'Resmi',
            'adaptasi': 'Adaptasi',
            'mandiri': 'Mandiri',
            'draft_keabsahan': 'Draft',
            'ARSIP': 'Arsip',
            'AKTIF': 'Aktif',
            'DRAFT': 'Draft',
            'REVIEW': 'Review',
            'PUBLISH': 'Publish',
            'REVISI': 'Revisi'
        };
        
        if (stats.results && stats.results.length > 0) {
            stats.results.forEach((s, i) => {
                const status = s.status_keabsahan || 'ARSIP';
                const icon = keabsahanIcons[status] || '📌';
                const label = keabsahanLabels[status] || status;
                msg += `${i+1}. ${icon} *${label}*: ${s.total} soal\n`;
                totalAll += s.total;
            });
        } else {
            // Coba ambil total arsip dengan query sederhana
            const total = await db.prepare(`SELECT COUNT(*) as total FROM soal WHERE status = 'ARSIP'`).first();
            if (total && total.total > 0) {
                msg += `📦 Arsip: ${total.total} soal\n`;
                totalAll = total.total;
            } else {
                msg += `❌ Belum ada soal arsip\n`;
            }
        }
        
        msg += `\n📦 *Total Arsip:* ${totalAll} soal\n\n`;
        
        // ============================================================
        // 2. STATISTIK PER KATEGORI ARSIP
        // ============================================================
        if (hasKategoriArsip && totalAll > 0) {
            const kategoriStats = await db.prepare(`
                SELECT 
                    kategori_arsip,
                    COUNT(*) as total,
                    MIN(tanggal_arsip) as pertama,
                    MAX(tanggal_arsip) as terakhir
                FROM soal 
                WHERE status = 'ARSIP'
                GROUP BY kategori_arsip
                ORDER BY total DESC
            `).all();
            
            if (kategoriStats.results && kategoriStats.results.length > 0) {
                msg += `📂 *Per Kategori Arsip:*\n`;
                kategoriStats.results.forEach((s, i) => {
                    const kategori = s.kategori_arsip || 'TANPA_KATEGORI';
                    msg += `${i+1}. 🏷️ *${kategori}*: ${s.total} soal\n`;
                    if (s.pertama) msg += `   📅 Pertama: ${new Date(s.pertama).toLocaleDateString('id-ID')}\n`;
                    if (s.terakhir) msg += `   📅 Terakhir: ${new Date(s.terakhir).toLocaleDateString('id-ID')}\n`;
                });
                msg += `\n`;
            }
        }
        
        // ============================================================
        // 3. KEYBOARD
        // ============================================================
        const keyboard = [
            [{ text: "🔙 Kembali ke Menu Arsip", callback_data: "menu_arsip" }],
            [{ text: "📋 Lihat Semua Arsip", callback_data: "arsip_list" }]
        ];
        
        await sendInlineKeyboard(chatId, msg, keyboard);
        return true;
        
    } catch (e) {
        console.error('❌ Statistik arsip error:', e);
        
        // ============================================================
        // FALLBACK: Tampilkan statistik sederhana
        // ============================================================
        try {
            const total = await db.prepare(`SELECT COUNT(*) as total FROM soal WHERE status = 'ARSIP'`).first();
            
            let fallbackMsg = `📊 *STATISTIK ARSIP*\n\n`;
            fallbackMsg += `📦 Total Arsip: ${total?.total || 0} soal\n`;
            fallbackMsg += `\n⚠️ Error detail: ${e.message}`;
            
            const keyboard = [
                [{ text: "🔙 Kembali ke Menu Arsip", callback_data: "menu_arsip" }]
            ];
            
            await sendInlineKeyboard(chatId, fallbackMsg, keyboard);
        } catch (e2) {
            await smartMessage(chatId, `❌ Error: ${e.message}`);
        }
        return true;
    }
}

