// ARSIP - PILIH KATEGORI UNTUK ARSIP
if (data.startsWith('arsip_kategori_')) {
  const kategori = data.replace('arsip_kategori_', '');
  
  const session = await getSession(env, userId);
  const soalId = session.arsipSoalId;
  
  if (!soalId) {
    await smartMessage(chatId, '❌ Data tidak valid. Silakan pilih ulang.');
    await clearSession(env, userId);
    return true;
  }
  
  try {
    // Cek apakah soal masih aktif
    const check = await db.prepare(`SELECT status FROM soal WHERE id = ?`).bind(soalId).first();
    if (!check) {
      await smartMessage(chatId, '❌ Soal tidak ditemukan.');
      await clearSession(env, userId);
      return true;
    }
    if (check.status !== 'AKTIF') {
      await smartMessage(chatId, `⚠️ Soal sudah ${check.status}, tidak bisa diarsipkan.`);
      await clearSession(env, userId);
      return true;
    }
    
    const tanggalArsip = new Date().toISOString();
    
    // Arsipkan soal
    const archiveResult = await updateQuestionBankRecord(db,soalId,{status:'ARSIP',status_ketersediaan:'arsip',kategori_arsip:kategori,tanggal_arsip:tanggalArsip,updated_by:userId},userId,`ARCHIVE: ${kategori}`);
    if(!archiveResult.success) throw new Error(archiveResult.error || 'Gagal mengarsipkan');
    
    await smartMessage(chatId, 
      `✅ *SOAL BERHASIL DIARSIPKAN!*\n\n` +
      `🆔 ID: ${soalId}\n` +
      `📂 Kategori: ${kategori}\n` +
      `📅 Tanggal: ${new Date(tanggalArsip).toLocaleDateString('id-ID')}`
    );
    
  } catch (e) {
    console.error('Arsip kategori error:', e);
    await smartMessage(chatId, `❌ Error: ${e.message}`);
  }
  
  await clearSession(env, userId);
  await sendInlineKeyboard(chatId, `📦 *Menu Arsip*`, [
    [{ text: "📋 Lihat Semua Arsip", callback_data: "arsip_list" }],
    [{ text: "📊 Statistik Kategori", callback_data: "arsip_statistik" }],
    [{ text: "📦 Arsipkan Soal", callback_data: "arsip_soal" }],
    [{ text: "✅ Aktifkan Kembali", callback_data: "arsip_aktifkan" }],
    [{ text: "🔙 Kembali ke Soal", callback_data: "menu_soal" }]
  ]);
  return true;
}

// ARSIP - ARSIP MULTIPLE - PILIH KATEGORI
if (data.startsWith('arsip_multiple_')) {
  const kategori = data.replace('arsip_multiple_', '');
  
  const session = await getSession(env, userId);
  const items = session.arsipMultipleItems || [];
  
  if (items.length === 0) {
    await smartMessage(chatId, '❌ Tidak ada item untuk diarsipkan.');
    await clearSession(env, userId);
    return true;
  }
  
  let successCount = 0;
  let errorCount = 0;
  const errors = [];
  const tanggalArsip = new Date().toISOString();
  
  for (const item of items) {
    try {
      const check = await db.prepare(`SELECT status FROM soal WHERE id = ?`).bind(item.id).first();
      if (!check || check.status !== 'AKTIF') {
        errorCount++;
        continue;
      }
      
      const archiveResult = await updateQuestionBankRecord(db,item.id,{status:'ARSIP',status_ketersediaan:'arsip',kategori_arsip:kategori,tanggal_arsip:tanggalArsip,updated_by:userId},userId,`ARCHIVE_BULK: ${kategori}`);
      if(!archiveResult.success) throw new Error(archiveResult.error || 'Gagal mengarsipkan');
      
      successCount++;
    } catch (e) {
      errorCount++;
      errors.push(`${item.id}: ${e.message}`);
    }
  }
  
  let response = `✅ *ARSIP MULTIPLE SELESAI*\n\n`;
  response += `📊 Berhasil: ${successCount} soal\n`;
  response += `❌ Gagal: ${errorCount} soal\n`;
  response += `📂 Kategori: ${kategori}\n`;
  if (errors.length > 0) {
    response += `\n⚠️ Error:\n${errors.slice(0, 5).map(e => `- ${e}`).join('\n')}`;
  }
  
  await smartMessage(chatId, response);
  await clearSession(env, userId);
  
  await sendInlineKeyboard(chatId, `📦 *Menu Arsip*`, [
    [{ text: "📋 Lihat Semua Arsip", callback_data: "arsip_list" }],
    [{ text: "📊 Statistik Kategori", callback_data: "arsip_statistik" }],
    [{ text: "📦 Arsipkan Soal", callback_data: "arsip_soal" }],
    [{ text: "✅ Aktifkan Kembali", callback_data: "arsip_aktifkan" }],
    [{ text: "🔙 Kembali ke Soal", callback_data: "menu_soal" }]
  ]);
  return true;
}

