if (data.startsWith('arsip_page_')) {
    try {
        const page = parseInt(data.replace('arsip_page_', '')) || 1;
        console.log(`✅ Arsip page ${page} dipanggil`);
        
        if (isNaN(page) || page < 1) {
            await answerCallback(callbackQueryId, '❌ Halaman tidak valid');
            return true;
        }
        
        const offset = (page - 1) * 10;
        
        const r = await db.prepare(`
            SELECT id, soal, status, kategori_arsip, tanggal_arsip
            FROM soal 
            WHERE status = 'ARSIP' 
            ORDER BY tanggal_arsip DESC 
            LIMIT 10 OFFSET ?
        `).bind(offset).all();
        
        const count = await db.prepare(`
            SELECT COUNT(*) as total FROM soal WHERE status = 'ARSIP'
        `).first();
        
        const totalPages = Math.ceil((count?.total || 0) / 10);
        
        let msg = `📦 *DAFTAR SOAL ARSIP (Hal ${page}/${totalPages || 1})*\n\n`;
        
        if (!r.results || r.results.length === 0) {
            msg += 'Belum ada soal yang diarsipkan.';
        } else {
            r.results.forEach((s, i) => {
                const soalText = (s.soal || '').substring(0, 50);
                msg += `${i + 1 + offset}. *${s.id}* - ${soalText}${(s.soal || '').length > 50 ? '...' : ''}\n`;
                msg += `   🏷️ ${s.kategori_arsip || 'TANPA_KATEGORI'}`;
                msg += ` | 📅 ${s.tanggal_arsip ? new Date(s.tanggal_arsip).toLocaleDateString('id-ID') : '-'}\n\n`;
            });
        }
        
        const keyboard = [];
        
        const idButtons = (r.results || []).map(s => ({ text: `🆔 ${s.id}`, callback_data: `ent_view_soal_${s.id}` }));
        if (idButtons.length) keyboard.push(idButtons.slice(0, 5));
        if (totalPages > 1) {
            const navButtons = [];
            if (page > 1) navButtons.push({ text: "⬅️ Sebelumnya", callback_data: `arsip_page_${page - 1}` });
            navButtons.push({ text: `📄 ${page}/${totalPages}`, callback_data: 'arsip_page_jump' });
            if (page < totalPages) navButtons.push({ text: "➡️ Selanjutnya", callback_data: `arsip_page_${page + 1}` });
            keyboard.push(navButtons);
        }
        keyboard.push([{ text: "🔙 Kembali ke Menu Arsip", callback_data: "menu_arsip" }]);
        
        const messageId = getCallbackMessageId();
        if (messageId) {
            await editInlineKeyboard(chatId, messageId, msg, keyboard);
        } else {
            await sendInlineKeyboard(chatId, msg, keyboard);
        }
        
        return true;
        
    } catch (e) {
        console.error('Arsip page error:', e);
        await smartMessage(chatId, `❌ Error: ${e.message}`);
        return true;
    }
}

