        4: { table: 'sumber_belajar', title: '📖 SUMBER BELAJAR', idField: 'id', nameField: 'nama', categoryField: 'kategori' },
        5: { table: 'lapisan_pembelajaran', title: '🏗️ LAPISAN PEMBELAJARAN', idField: 'level', nameField: 'nama', categoryField: null }
