// Merge manual — tampilkan pilihan versi
if (data.startsWith('version_merge_manual_')) {
    const materiId = data.replace('version_merge_manual_', '');
    
    const versions = await getMateriVersions(db, materiId);
    
    // Tampilkan versi dengan checkbox toggle
    const keyboard = [];
    for (const v of versions) {
        const activeIcon = v.is_active === 1 ? '🟢' : '⚪';
        keyboard.push([{
            text: `${activeIcon} v${v.versi} — ${(v.total_kata || 0)} kata`,
            callback_data: `version_merge_toggle_${materiId}_${v.versi}`
        }]);
    }
    keyboard.push([
        { text: "✅ Merge Terpilih", callback_data: `version_merge_exec_${materiId}` }
    ]);
    keyboard.push([
        { text: "🔙 Kembali", callback_data: `materi_versions_${materiId}` }
    ]);
    
    // Simpan session untuk tracking pilihan
    const session = await getSession(env, userId);
    session.mergeSelection = [];
    session.mergeMateriId = materiId;
    await saveSession(env, userId, session);
    
    await sendInlineKeyboard(chatId, 
        `📝 *MERGE MANUAL*\n\n` +
        `Klik versi untuk toggle pilih/lepas.\n` +
        `Minimal 2 versi dipilih.\n\n` +
        `Pilih versi:`,
        keyboard
    );
    return true;
}

// Toggle versi untuk merge
if (data.startsWith('version_merge_toggle_')) {
    const rest = data.replace('version_merge_toggle_', '');
    const parts = rest.split('_');
    const materiId = parts[0];
    const versi = parseInt(parts[1]);
    
    const session = await getSession(env, userId);
    const selection = session.mergeSelection || [];
    
    const idx = selection.indexOf(versi);
    if (idx >= 0) {
        selection.splice(idx, 1);
        await answerCallback(callbackQueryId, `❌ v${versi} dilepas`);
    } else {
        selection.push(versi);
        await answerCallback(callbackQueryId, `✅ v${versi} dipilih`);
    }
    
    session.mergeSelection = selection;
    await saveSession(env, userId, session);
    
    // Refresh UI
    const versions = await getMateriVersions(db, materiId);
    const keyboard = [];
    for (const v of versions) {
        const isSelected = selection.includes(v.versi);
        const activeIcon = v.is_active === 1 ? '🟢' : '⚪';
        const checkIcon = isSelected ? '✅' : '⬜';
        keyboard.push([{
            text: `${checkIcon} ${activeIcon} v${v.versi} — ${(v.total_kata || 0)} kata`,
            callback_data: `version_merge_toggle_${materiId}_${v.versi}`
        }]);
    }
    keyboard.push([
        { text: `✅ Merge (${selection.length} terpilih)`, 
          callback_data: `version_merge_exec_${materiId}` }
    ]);
    keyboard.push([
        { text: "🔙 Kembali", callback_data: `materi_versions_${materiId}` }
    ]);
    
    const messageId = getCallbackMessageId();
    if (messageId) {
        await editInlineKeyboard(chatId, messageId, 
            `📝 *MERGE MANUAL*\n\n` +
            `Terpilih: ${selection.length} versi\n` +
            `${selection.length > 0 ? `v${selection.sort((a,b)=>a-b).join(', v')}` : 'Belum ada'}\n\n` +
            `Klik versi untuk toggle. Minimal 2.`,
            keyboard
        );
    }
    return true;
}

// Eksekusi merge manual
