// ADMIN FUNCTION GUIDES
if (data && data.startsWith('adm_guide_')) {
    const raw=data.slice('adm_guide_'.length);
    const m=raw.match(/^([a-z_]+?)(?:_p(\d+))?$/);
    const groupKey=m?.[1],page=Number(m?.[2]||0);
    if(groupKey&&ADMIN_MENU_GROUPS[groupKey]){
      const messageId=getCallbackMessageId(), keyboard=buildAdminGroupGuideMenu(groupKey,page);
      const total=Math.max(1,Math.ceil(ADMIN_MENU_GROUPS[groupKey].commands.length/8));
      const msg=`📖 *PANDUAN ${ADMIN_MENU_GROUPS[groupKey].title.replace(/^[^ ]+ /,'')}*\n${DIVIDER}\n\nPilih fungsi untuk melihat kegunaannya (halaman ${page+1}/${total}):`;
      if(messageId)await editInlineKeyboard(chatId,messageId,msg,keyboard); else await sendInlineKeyboard(chatId,msg,keyboard);
      return true;
    }
}
if (data && data.startsWith('adm_help_')) {
    const raw=data.slice('adm_help_'.length);
    const m=raw.match(/^([a-z_]+)_(\d+)_(\d+)$/);
    const groupKey=m?.[1],page=Number(m?.[2]||0),idx=Number(m?.[3]||0);
    const group=ADMIN_MENU_GROUPS[groupKey];
    const cmd=group?.commands?.[page*8+idx];
    if(cmd){
      const messageId=getCallbackMessageId();
      const kb=[[{text:'🔙 Kembali ke Panduan',callback_data:`adm_guide_${groupKey}_p${page}`}],[{text:'🏠 Menu Utama',callback_data:'menu_back'}]];
      if(messageId)await editInlineKeyboard(chatId,messageId,adminGuideForCommand(cmd),kb); else await sendInlineKeyboard(chatId,adminGuideForCommand(cmd),kb);
      return true;
    }
}

// ============================================================
// LEGACY ADD CONFIRMATION BRIDGE
// Semua tombol confirm_add_* legacy harus memiliki handler nyata.
// Bridge ini mempertahankan alur lama tetapi memakai validasi parent
// dan resolver Topik terpusat.
// ============================================================
const legacyAddMap = {
    bidang: { table:'bidang_studi', prefix:'B', parentField:'kategori_id', parentKey:'kategoriId', nameField:'nama', menu:'menu_bidang' },
    program: { table:'program_studi', prefix:'P', parentField:'bidang_studi_id', parentKey:'bidangId', nameField:'nama', menu:'menu_program' },
    subtopik: { table:'sub_topik', prefix:'S', parentField:'topik_id', parentKey:'topikId', nameField:'nama', menu:'menu_subtopik' },
    kisi: { table:'kisi_kisi', prefix:'I', parentField:'sub_topik_id', parentKey:'subtopikId', nameField:'judul', menu:'menu_kisi' },
    kemampuan: { table:'kemampuan_diuji', prefix:'KM', parentField:'kisi_kisi_id', parentKey:'kisiId', nameField:'nama', menu:'menu_kemampuan' },
    subkemampuan: { table:'sub_kemampuan', prefix:'SK', parentField:'kemampuan_id', parentKey:'kemampuanId', nameField:'nama', menu:'menu_subkemampuan' }
};
const legacyAddMatch = String(data||'').match(/^confirm_add_(bidang|program|jenjang|topik|subtopik|kisi|kemampuan|subkemampuan)_(yes|no)$/);
if (legacyAddMatch) {
    const [, kind, action] = legacyAddMatch;
    const session = await getSession(env, userId);
    const backMap = { bidang:'menu_bidang', program:'menu_program', jenjang:'menu_jenjang', topik:'menu_topik', subtopik:'menu_subtopik', kisi:'menu_kisi', kemampuan:'menu_kemampuan', subkemampuan:'menu_subkemampuan' };
    if (action === 'no') {
        await clearSession(env, userId);
        await sendInlineKeyboard(chatId, '❌ *DIBATALKAN*\n\nPenambahan dibatalkan.', [[{text:'🔙 Kembali',callback_data:backMap[kind]}]]);
        return true;
    }
    try {
        const d = session.tempData || {};
        if (kind === 'jenjang') {
            if (!d.id || !d.nama) throw new Error('Data Jenjang tidak lengkap.');
            const exists = await db.prepare(`SELECT id FROM jenjang WHERE id = ? OR LOWER(TRIM(nama)) = LOWER(TRIM(?)) LIMIT 1`).bind(d.id,d.nama).first();
            if (exists) throw new Error(`Jenjang sudah ada: ${exists.id}`);
            await db.prepare(`INSERT INTO jenjang (id,nama,jenis,kategori,created_at,updated_at) VALUES (?,?,?,?,?,?)`)
                .bind(d.id,d.nama,d.jenis||'pendidikan',d.kategori||'umum',new Date().toISOString(),new Date().toISOString()).run();
        } else if (kind === 'topik') {
            if (!d.programId || !d.nama) throw new Error('Data Topik tidak lengkap.');
            const created = await getOrCreateTopicStrict(db,{name:d.nama,programId:d.programId,autoCreate:true});
            if (!created.id) throw new Error(created.error||'Topik gagal dibuat.');
            if (d.deskripsi) await db.prepare(`UPDATE topik SET deskripsi=? WHERE id=?`).bind(d.deskripsi,created.id).run();
        } else {
            const cfg = legacyAddMap[kind];
            if (!cfg || !d[cfg.parentKey] || !d[cfg.nameField]) throw new Error(`Data ${kind} tidak lengkap.`);
            // Parent existence is checked against the referenced table directly.
            const parentTable = {kategori_id:'kategori',bidang_studi_id:'bidang_studi',topik_id:'topik',sub_topik_id:'sub_topik',kisi_kisi_id:'kisi_kisi',kemampuan_id:'kemampuan_diuji'}[cfg.parentField];
            if (!parentTable) throw new Error('Parent tidak dikenal.');
            const parentRow = await db.prepare(`SELECT id FROM ${parentTable} WHERE id=? LIMIT 1`).bind(d[cfg.parentKey]).first();
            if (!parentRow) throw new Error(`Parent ${d[cfg.parentKey]} tidak ditemukan.`);
            const duplicate = await db.prepare(`SELECT id FROM ${cfg.table} WHERE ${cfg.parentField}=? AND LOWER(TRIM(${cfg.nameField}))=LOWER(TRIM(?)) LIMIT 1`).bind(d[cfg.parentKey],d[cfg.nameField]).first();
            if (duplicate) throw new Error(`Data sudah ada: ${duplicate.id}`);
            const id = kind === 'kemampuan'
                ? await generateKemampuanId(db)
                : kind === 'subkemampuan'
                    ? await generateSubKemampuanId(db)
                    : await generateId(db,cfg.prefix,cfg.table);
            const now = new Date().toISOString();
            if (kind === 'kisi') {
                await db.prepare(`INSERT INTO kisi_kisi (id,sub_topik_id,judul,kode,deskripsi,status,created_at,updated_at) VALUES (?,?,?,?,?,'DRAFT',?,?)`).bind(id,d.subtopikId,d.judul,d.kode||null,d.deskripsi||null,now,now).run();
            } else {
                const desc = d.deskripsi||null;
                await db.prepare(`INSERT INTO ${cfg.table} (id,${cfg.parentField},${cfg.nameField},deskripsi,created_at,updated_at) VALUES (?,?,?,?,?,?)`).bind(id,d[cfg.parentKey],d[cfg.nameField],desc,now,now).run();
            }
        }
        await clearSession(env,userId);
        await sendInlineKeyboard(chatId, `✅ *BERHASIL DITAMBAHKAN*\n\nData ${kind} berhasil disimpan.`, [[{text:'🔙 Kembali',callback_data:backMap[kind]}]]);
    } catch(e) {
        await smartMessage(chatId, `❌ Gagal menambahkan ${kind}: ${e.message}`);
    }
    return true;
}

