/**
 * Ambil semua folder arsip yang tersedia (dari status_soal yang memiliki tipe 'arsip_folder')
 */
async function getArsipFolders(db) {
    try {
        const result = await db.prepare(`
            SELECT id, nama, deskripsi, warna, icon, urutan 
            FROM status_soal 
            WHERE tipe = 'arsip_folder' AND is_active = 1
            ORDER BY urutan ASC, nama ASC
        `).all();
        return result.results || [];
    } catch (e) {
        console.error('Error getArsipFolders:', e);
        // Fallback: ambil dari kategori_arsip yang ada di soal
        try {
            const fallback = await db.prepare(`
                SELECT DISTINCT kategori_arsip as nama, kategori_arsip as id
                FROM soal 
                WHERE status = 'ARSIP' AND kategori_arsip IS NOT NULL
                ORDER BY kategori_arsip
            `).all();
            return (fallback.results || []).map(f => ({
                id: f.nama,
                nama: f.nama,
                deskripsi: 'Folder arsip dari data existing',
                warna: '#gray',
                icon: '📁',
                urutan: 0
            }));
        } catch (e2) {
            return [];
        }
    }
}

/**
 * Tambah folder arsip baru
 */
async function addArsipFolder(db, nama, deskripsi = null, warna = '#gray', icon = '📁') {
    try {
        // Cek duplikat
        const existing = await db.prepare(`
            SELECT id FROM status_soal 
            WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND tipe = 'arsip_folder'
        `).bind(nama).first();
        
        if (existing) {
            return { success: false, error: `Folder "${nama}" sudah ada.` };
        }
        
        // Generate ID
        const result = await db.prepare(`
            SELECT id FROM status_soal WHERE id LIKE 'AF%' ORDER BY id DESC LIMIT 1
        `).first();
        
        let newId = 'AF001';
        if (result) {
            const num = parseInt(result.id.substring(2)) + 1;
            newId = `AF${String(num).padStart(3, '0')}`;
        }
        
        // Ambil urutan terakhir
        const lastOrder = await db.prepare(`
            SELECT MAX(urutan) as max FROM status_soal WHERE tipe = 'arsip_folder'
        `).first();
        const urutan = (lastOrder?.max || 0) + 1;
        
        await db.prepare(`
            INSERT INTO status_soal (id, nama, deskripsi, warna, icon, tipe, urutan, is_active, created_at)
            VALUES (?, ?, ?, ?, ?, 'arsip_folder', ?, 1, ?)
        `).bind(newId, nama.trim(), deskripsi, warna, icon, urutan, new Date().toISOString()).run();
        
        return { success: true, id: newId, nama: nama.trim() };
    } catch (e) {
        console.error('Error addArsipFolder:', e);
        return { success: false, error: e.message };
    }
}

/**
 * Ubah nama folder arsip
 */
async function renameArsipFolder(db, folderId, newNama) {
    try {
        // Cek apakah folder ada
        const existing = await db.prepare(`
            SELECT id, nama FROM status_soal 
            WHERE id = ? AND tipe = 'arsip_folder'
        `).bind(folderId).first();
        
        if (!existing) {
            return { success: false, error: `Folder dengan ID "${folderId}" tidak ditemukan.` };
        }
        
        // Cek duplikat nama
        const duplicate = await db.prepare(`
            SELECT id FROM status_soal 
            WHERE LOWER(TRIM(nama)) = LOWER(TRIM(?)) AND id != ? AND tipe = 'arsip_folder'
        `).bind(newNama, folderId).first();
        
        if (duplicate) {
            return { success: false, error: `Folder "${newNama}" sudah ada.` };
        }
        
        // Update nama di status_soal
        await db.prepare(`
            UPDATE status_soal SET 
                nama = ?, 
                updated_at = ?
            WHERE id = ? AND tipe = 'arsip_folder'
        `).bind(newNama.trim(), new Date().toISOString(), folderId).run();
        
        // Update juga di tabel soal (kategori_arsip) untuk semua soal yang menggunakan folder ini
        await db.prepare(`
            UPDATE soal SET kategori_arsip = ? WHERE kategori_arsip = ?
        `).bind(newNama.trim(), existing.nama).run();
        
        return { success: true, id: folderId, oldNama: existing.nama, newNama: newNama.trim() };
    } catch (e) {
        console.error('Error renameArsipFolder:', e);
        return { success: false, error: e.message };
    }
}

/**
 * Hapus folder arsip
 */
async function deleteArsipFolder(db, folderId) {
    try {
        // Cek apakah folder ada
        const existing = await db.prepare(`
            SELECT id, nama FROM status_soal 
            WHERE id = ? AND tipe = 'arsip_folder'
        `).bind(folderId).first();
        
        if (!existing) {
            return { success: false, error: `Folder dengan ID "${folderId}" tidak ditemukan.` };
        }
        
        // Cek apakah ada soal yang menggunakan folder ini
        const soalCount = await db.prepare(`
            SELECT COUNT(*) as total FROM soal WHERE kategori_arsip = ? AND status = 'ARSIP'
        `).bind(existing.nama).first();
        
        if (soalCount && soalCount.total > 0) {
            return { 
                success: false, 
                error: `Folder "${existing.nama}" masih memiliki ${soalCount.total} soal. Pindahkan atau hapus soal terlebih dahulu.` 
            };
        }
        
        // Hapus folder
        await db.prepare(`
            DELETE FROM status_soal WHERE id = ? AND tipe = 'arsip_folder'
        `).bind(folderId).run();
        
        return { success: true, id: folderId, nama: existing.nama };
    } catch (e) {
        console.error('Error deleteArsipFolder:', e);
        return { success: false, error: e.message };
    }
}




// ============================================================
// FASE 3: CURRICULUM RELATIONS ENGINE
// ============================================================
function normalizeRelationType(value) {
    const v = String(value || '').trim().toUpperCase().replace(/[\s-]+/g, '_');
    return CURRICULUM_RELATION_TYPES.includes(v) ? v : null;
}

async function cleanupCurriculumRelationsForEntity(db, entityType, entityId) {
    const type = String(entityType || '').trim().toLowerCase();
    const id = String(entityId || '').trim();
    if (!type || !id) return;
    try {
        await db.prepare(`DELETE FROM curriculum_relations WHERE (source_type=? AND source_id=?) OR (target_type=? AND target_id=?)`).bind(type,id,type,id).run();
    } catch (e) {
        console.warn(`⚠️ Gagal membersihkan relasi kurikulum ${type}:${id}:`, e.message);
    }
}

async function createCurriculumRelation(db, data = {}) {
    const sourceType = String(data.sourceType || '').trim().toLowerCase();
    const sourceId = String(data.sourceId || '').trim();
    const targetType = String(data.targetType || '').trim().toLowerCase();
    const targetId = String(data.targetId || '').trim();
    const relationType = normalizeRelationType(data.relationType);
    const inputValidation = validateCurriculumRelationInput({ sourceType, sourceId, targetType, targetId, relationType });
    if (!sourceType || !sourceId || !targetType || !targetId || !relationType || !inputValidation.valid) {
        return { success: false, error: inputValidation.errors?.join('; ') || 'source, target, dan relation_type wajib valid' };
    }
    try {
        const entityTable = {kategori:'kategori',bidang:'bidang_studi',program:'program_studi',jenjang:'jenjang',kelas:'kelas',mata_pelajaran:'mata_pelajaran',mata_kuliah:'mata_kuliah',topik:'topik',subtopik:'sub_topik',kisi:'kisi_kisi',kemampuan:'kemampuan_diuji',subkemampuan:'sub_kemampuan',materi:'materi',soal:'soal'};
        const sourceTable = entityTable[sourceType], targetTable = entityTable[targetType];
        if (!sourceTable || !targetTable) return {success:false,error:'Entity relation tidak memiliki tabel yang valid.'};
        const [sourceExists,targetExists] = await Promise.all([
            db.prepare(`SELECT 1 FROM ${sourceTable} WHERE id=? LIMIT 1`).bind(sourceId).first(),
            db.prepare(`SELECT 1 FROM ${targetTable} WHERE id=? LIMIT 1`).bind(targetId).first()
        ]);
        if (!sourceExists) return {success:false,error:`Source ${sourceType}:${sourceId} tidak ditemukan.`};
        if (!targetExists) return {success:false,error:`Target ${targetType}:${targetId} tidak ditemukan.`};
        const existing = await db.prepare(`SELECT id FROM curriculum_relations WHERE source_type=? AND source_id=? AND relation_type=? AND target_type=? AND target_id=? LIMIT 1`)
            .bind(sourceType, sourceId, relationType, targetType, targetId).first();
        if (existing) return { success: true, id: existing.id, existed: true };
        const id = await generateId(db, 'CR', 'curriculum_relations');
        const now = new Date().toISOString();
        await db.prepare(`INSERT INTO curriculum_relations (id,source_type,source_id,relation_type,target_type,target_id,metadata,is_active,created_at,updated_at,created_by,updated_by) VALUES (?,?,?,?,?,?,?,1,?,?,?,?)`)
            .bind(id, sourceType, sourceId, relationType, targetType, targetId, data.metadata ? JSON.stringify(data.metadata) : null, now, now, data.userId || null, data.userId || null).run();
        return { success: true, id, existed: false };
    } catch (e) { return { success: false, error: e.message }; }
}

async function getCurriculumRelations(db, sourceType, sourceId, options = {}) {
    try {
        let q = `SELECT * FROM curriculum_relations WHERE is_active=1 AND source_type=? AND source_id=?`;
        const b = [String(sourceType || '').toLowerCase(), String(sourceId || '')];
        if (options.relationType) { q += ` AND relation_type=?`; b.push(normalizeRelationType(options.relationType) || ''); }
        q += ` ORDER BY relation_type, created_at`;
        const r = await db.prepare(q).bind(...b).all();
        return r.results || [];
    } catch (e) { return []; }
}

const CURRICULUM_RELATION_ENTITY_TYPES = Object.freeze([
    'kategori','bidang','program','jenjang','kelas','mata_pelajaran','mata_kuliah',
    'topik','subtopik','kisi','kemampuan','subkemampuan','materi','soal'
]);

const CURRICULUM_RELATION_RULES = Object.freeze({
    PRASYARAT: ['mata_pelajaran','mata_kuliah','topik','subtopik','materi','soal'],
    LANJUTAN: ['mata_pelajaran','mata_kuliah','topik','subtopik','materi','soal'],
    TERKAIT: CURRICULUM_RELATION_ENTITY_TYPES,
    LINTAS_JENJANG: ['jenjang','kelas','mata_pelajaran','mata_kuliah','topik','materi','soal'],
    LINTAS_MATA_PELAJARAN: ['mata_pelajaran','topik','materi','soal'],
    LINTAS_MATA_KULIAH: ['mata_kuliah','topik','materi','soal'],
    REUSABLE_MATERIAL: ['materi','topik','mata_pelajaran','mata_kuliah'],
    PENDUKUNG: ['materi','soal','topik','subtopik','kisi','kemampuan','subkemampuan'],
    PENGAYAAN: ['materi','soal','topik','subtopik','kisi','kemampuan','subkemampuan'],
    REMEDIAL: ['materi','soal','topik','subtopik','kisi','kemampuan','subkemampuan']
});

function validateCurriculumRelationInput(data = {}) {
    const sourceType = String(data.sourceType || '').trim().toLowerCase();
    const targetType = String(data.targetType || '').trim().toLowerCase();
    const relationType = normalizeRelationType(data.relationType);
    const errors = [];
    if (!CURRICULUM_RELATION_ENTITY_TYPES.includes(sourceType)) errors.push('source_type tidak valid');
    if (!CURRICULUM_RELATION_ENTITY_TYPES.includes(targetType)) errors.push('target_type tidak valid');
    if (!relationType) errors.push('relation_type tidak valid');
    if (relationType && CURRICULUM_RELATION_RULES[relationType]) {
        const allowed = CURRICULUM_RELATION_RULES[relationType];
        if (!allowed.includes(sourceType)) errors.push(`${relationType}: source_type tidak didukung`);
        if (!allowed.includes(targetType)) errors.push(`${relationType}: target_type tidak didukung`);
    }
    if (sourceType === targetType && String(data.sourceId || '').trim() === String(data.targetId || '').trim()) {
        errors.push('Relasi tidak boleh menunjuk ke dirinya sendiri');
    }
    return { valid: errors.length === 0, errors, sourceType, targetType, relationType };
}

async function updateCurriculumRelation(db, relationId, data = {}) {
    if (!relationId) return { success:false, error:'relationId wajib' };
    const validation = validateCurriculumRelationInput(data);
    if (!validation.valid) return { success:false, error:validation.errors.join('; ') };
    try {
        const now = new Date().toISOString();
        const result = await db.prepare(`UPDATE curriculum_relations SET source_type=?,source_id=?,relation_type=?,target_type=?,target_id=?,metadata=?,is_active=?,updated_at=?,updated_by=? WHERE id=?`)
            .bind(validation.sourceType, String(data.sourceId||'').trim(), validation.relationType, validation.targetType, String(data.targetId||'').trim(), data.metadata ? JSON.stringify(data.metadata) : null, data.isActive === false ? 0 : 1, now, data.userId || null, relationId).run();
        return { success:true, changes:result.meta?.changes ?? 0, id:relationId };
    } catch(e) { return { success:false,error:e.message }; }
}

async function getCurriculumRelationsForTarget(db, targetType, targetId, options = {}) {
    try {
        let q=`SELECT * FROM curriculum_relations WHERE is_active=1 AND target_type=? AND target_id=?`;
        const b=[String(targetType||'').toLowerCase(),String(targetId||'')];
        if(options.relationType){q+=` AND relation_type=?`;b.push(normalizeRelationType(options.relationType)||'');}
        q+=` ORDER BY relation_type, created_at`;
        const r=await db.prepare(q).bind(...b).all(); return r.results||[];
    } catch(e){return [];} 
}

async function listCurriculumRelations(db, options = {}) {
    try {
        let q=`SELECT * FROM curriculum_relations WHERE is_active=?`;
        const b=[options.isActive === false ? 0 : 1];
        if(options.relationType){q+=` AND relation_type=?`;b.push(normalizeRelationType(options.relationType)||'');}
        if(options.sourceType){q+=` AND source_type=?`;b.push(String(options.sourceType).toLowerCase());}
        if(options.targetType){q+=` AND target_type=?`;b.push(String(options.targetType).toLowerCase());}
        q+=` ORDER BY updated_at DESC LIMIT ?`;b.push(Math.min(500,Math.max(1,Number(options.limit)||100)));
        const r=await db.prepare(q).bind(...b).all(); return r.results||[];
    } catch(e){return [];} 
}

async function deactivateCurriculumRelation(db, relationId, userId = null) {
    try {
        const r = await db.prepare(`UPDATE curriculum_relations SET is_active=0, updated_at=?, updated_by=? WHERE id=?`).bind(new Date().toISOString(), userId, relationId).run();
        return { success: true, changes: r.meta?.changes ?? 0 };
    } catch (e) { return { success: false, error: e.message }; }
}

// ============================================================
// FASE 4: MATERIAL CHUNK / RESUME ENGINE
// ============================================================
function splitMateriIntoChunks(konten, maxWords = 900) {
    const text = String(konten || '').trim();
    if (!text) return [];
    const limit = Math.max(100, Number(maxWords) || 900);
    const paragraphs = text.split(/\n\s*\n/).map(x => x.trim()).filter(Boolean);
    const chunks = []; let current = []; let count = 0;
    const flush = () => { if (current.length) { const c = current.join('\n\n').trim(); chunks.push({ konten:c, word_count:c.split(/\s+/).filter(Boolean).length }); current=[]; count=0; } };
    for (const para of paragraphs) {
        const words = para.split(/\s+/).filter(Boolean);
        if (count && count + words.length > limit) flush();
        if (words.length <= limit) { current.push(para); count += words.length; continue; }
        for (let i=0;i<words.length;i+=limit) { if (current.length) flush(); const c=words.slice(i,i+limit).join(' '); chunks.push({konten:c, word_count:c.split(/\s+/).filter(Boolean).length}); }
    }
    flush();
    return chunks.map((c,i)=>({ id:null, chunk_index:i, ...c, word_count:c.word_count ?? String(c.konten).split(/\s+/).filter(Boolean).length }));
}

async function rebuildMateriChunks(db, materiId, options = {}) {
    if (!materiId) return { success:false, error:'materiId wajib' };
    try {
        const materi = await db.prepare(`SELECT id,konten,versi_aktif FROM materi WHERE id=? LIMIT 1`).bind(materiId).first();
        if (!materi) return { success:false, error:'Materi tidak ditemukan' };
        const chunks = splitMateriIntoChunks(materi.konten, options.maxWords || 900);
        await db.prepare(`DELETE FROM materi_chunks WHERE materi_id=? AND versi=?`).bind(materiId, materi.versi_aktif || 1).run();
        for (const c of chunks) {
            const id = await generateId(db, 'MC', 'materi_chunks');
            await db.prepare(`INSERT INTO materi_chunks (id,materi_id,versi,tahap_kode,chunk_index,judul,konten,word_count,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)`)
                .bind(id,materiId,materi.versi_aktif||1,options.tahapKode||null,c.chunk_index,options.judulPrefix?`${options.judulPrefix} ${c.chunk_index+1}`:null,c.konten,c.word_count,'pending',new Date().toISOString(),new Date().toISOString()).run();
        }
        return { success:true, total:chunks.length, versi:materi.versi_aktif||1 };
    } catch(e) { return { success:false,error:e.message }; }
}

async function getMateriChunks(db, materiId, versi = null) {
    try { const q=versi===null?`SELECT * FROM materi_chunks WHERE materi_id=? ORDER BY chunk_index`:`SELECT * FROM materi_chunks WHERE materi_id=? AND versi=? ORDER BY chunk_index`; const r=versi===null?await db.prepare(q).bind(materiId).all():await db.prepare(q).bind(materiId,versi).all(); return r.results||[]; } catch(e){return [];} }

async function deleteMateriArtifacts(db, materiId) {
    if (!materiId) return;
    const statements = [
        `DELETE FROM materi_chunks WHERE materi_id=?`,
        `DELETE FROM user_materi_sessions WHERE materi_id=?`,
        `DELETE FROM materi_progress WHERE materi_id=?`,
        `DELETE FROM materi_rumus WHERE materi_id=?`,
        `DELETE FROM materi_media WHERE materi_id=?`
    ];
    for (const sql of statements) {
        try { await db.prepare(sql).bind(materiId).run(); } catch (e) { console.warn('⚠️ Cleanup artefak materi:', e.message); }
    }
}

async function saveUserMateriSession(db, data = {}) {
    const userId=String(data.userId||'').trim(), materiId=String(data.materiId||'').trim();
    if(!userId||!materiId) return {success:false,error:'userId dan materiId wajib'};
    try {
        const existing=await db.prepare(`SELECT id FROM user_materi_sessions WHERE user_id=? AND materi_id=? LIMIT 1`).bind(userId,materiId).first();
        const now=new Date().toISOString(); const id=existing?.id || await generateId(db,'UMS','user_materi_sessions');
        const vals=[data.versi||1,Number.isFinite(Number(data.currentChunk))?Number(data.currentChunk):0,Math.max(0,Math.min(100,Number(data.progressPercent)||0)),data.status||'active',data.startedAt||now,now,data.completedAt||null,data.extra?JSON.stringify(data.extra):null,now];
        if(existing) await db.prepare(`UPDATE user_materi_sessions SET versi=?,current_chunk=?,progress_percent=?,status=?,started_at=?,last_activity=?,completed_at=?,data=?,updated_at=? WHERE id=?`).bind(...vals,id).run();
        else await db.prepare(`INSERT INTO user_materi_sessions (id,user_id,materi_id,versi,current_chunk,progress_percent,status,started_at,last_activity,completed_at,data,created_at,updated_at) VALUES (?,?,?, ?,?,?,?,?,?,?,?, ?,?)`).bind(id,userId,materiId,...vals).run();
        return {success:true,id};
    } catch(e){return {success:false,error:e.message};}
}

async function getUserMateriSession(db,userId,materiId,versi=null){try{
    const q=versi===null?`SELECT * FROM user_materi_sessions WHERE user_id=? AND materi_id=? ORDER BY updated_at DESC LIMIT 1`:`SELECT * FROM user_materi_sessions WHERE user_id=? AND materi_id=? AND versi=? ORDER BY updated_at DESC LIMIT 1`;
    const r=versi===null?await db.prepare(q).bind(userId,materiId).first():await db.prepare(q).bind(userId,materiId,versi).first();
    return r||null;
}catch(e){return null;}}
async function setMateriChunkStatus(db, chunkId, status, userId = null) {
    const allowed=['pending','active','paused','completed','skipped','error'];
    const normalized=String(status||'').trim().toLowerCase();
    if(!chunkId||!allowed.includes(normalized)) return {success:false,error:'Status chunk tidak valid'};
    try {
        const now=new Date().toISOString();
        const started=normalized==='active'?now:null;
        const completed=normalized==='completed'?now:null;
        const r=await db.prepare(`UPDATE materi_chunks SET status=?,started_at=COALESCE(?,started_at),completed_at=CASE WHEN ?='completed' THEN ? ELSE completed_at END,updated_at=? WHERE id=?`)
            .bind(normalized,started,normalized,completed,now,chunkId).run();
        return {success:true,changes:r.meta?.changes??0};
    } catch(e){return {success:false,error:e.message};}
}
async function pauseMateriSession(db,userId,materiId){
    const existing=await getUserMateriSession(db,userId,materiId);
    if(!existing) return saveUserMateriSession(db,{userId,materiId,status:'paused'});
    try { const now=new Date().toISOString(); const r=await db.prepare(`UPDATE user_materi_sessions SET status='paused',last_activity=?,updated_at=? WHERE id=?`).bind(now,now,existing.id).run(); return {success:true,id:existing.id,changes:r.meta?.changes??0}; } catch(e){return {success:false,error:e.message};}
}
async function resumeMateriSession(db,userId,materiId){
    const existing=await getUserMateriSession(db,userId,materiId);
    if(!existing) return saveUserMateriSession(db,{userId,materiId,status:'active'});
    try { const now=new Date().toISOString(); const r=await db.prepare(`UPDATE user_materi_sessions SET status='active',last_activity=?,completed_at=NULL,updated_at=? WHERE id=?`).bind(now,now,existing.id).run(); return {success:true,id:existing.id,changes:r.meta?.changes??0}; } catch(e){return {success:false,error:e.message};}
}
async function completeMateriSession(db,userId,materiId){
    const existing=await getUserMateriSession(db,userId,materiId);
    if(!existing) return saveUserMateriSession(db,{userId,materiId,status:'completed',progressPercent:100,completedAt:new Date().toISOString()});
    try { const now=new Date().toISOString(); const r=await db.prepare(`UPDATE user_materi_sessions SET status='completed',progress_percent=100,last_activity=?,completed_at=?,updated_at=? WHERE id=?`).bind(now,now,now,existing.id).run(); return {success:true,id:existing.id,changes:r.meta?.changes??0}; } catch(e){return {success:false,error:e.message};}
}

// ============================================================
// FASE 5: QUESTION ENGINE CONTRACT + VALIDATOR
// ============================================================
function normalizeQuestionType(value){
    const v=String(value||'').trim().toUpperCase().replace(/[\s-]+/g,'_');
    const aliases={HAFAL:'HAFALAN',MEMORY:'HAFALAN',CASE:'STUDI_KASUS','STUDI_KASUS':'STUDI_KASUS','COMPREHENSIVE':'KOMPREHENSIF'};
    return QUESTION_TYPES.includes(v)?v:(aliases[v]||null);
}
function normalizeQuestionDifficulty(value){
    const v=String(value||'').trim().toUpperCase().replace(/[\s-]+/g,'_');
    const aliases={HOTS:'SULIT',SESUAI_TAHAP:'SEDANG',ADAPTIF:'SEDANG'};
    return QUESTION_DIFFICULTIES.includes(v)?v:(aliases[v]||null);
}
function normalizeCognitiveProcess(value, legacyLevel=null){
    const v=String(value||'').trim().toUpperCase().replace(/[\s-]+/g,'_');
    if(COGNITIVE_PROCESSES.includes(v)) return v;
    const n=Number(legacyLevel);
    if(Number.isInteger(n)){ if(n<=2) return 'LOTS'; if(n<=4) return 'MOTS'; if(n<=6) return 'HOTS'; }
    return null;
}
function getDefaultDifficulty(value=null){ return normalizeQuestionDifficulty(value)||'SEDANG'; }
function validateQuestionContract(data={}){
    const errors=[]; const answer=String(data.jawabanBenar||data.jawaban_benar||'').trim().toUpperCase();
    if(!String(data.soal || data.soalText || '').trim()) errors.push('Teks soal wajib diisi');
    const opts=['A','B','C','D','E'].map(k=>String(data[`pilihan${k}`]??data[`pilihan_${k.toLowerCase()}`]??'').trim());
    if(opts.some(x=>!x)) errors.push('Semua pilihan A-E wajib diisi');
    if(!['A','B','C','D','E'].includes(answer)) errors.push('Jawaban benar harus A-E');
    const reasons=['A','B','C','D','E'].map(k=>String(data[`alasan${k}`]??data[`alasan_${k.toLowerCase()}`]??'').trim());
    if(reasons.some(x=>!x)) errors.push('Alasan A-E wajib diisi untuk kontrak soal pilihan ganda');
    const normalized=opts.map(x=>x.toLowerCase().replace(/\s+/g,' ')); if(new Set(normalized).size!==normalized.length) errors.push('Pilihan jawaban tidak boleh duplikat');
    const jenis=normalizeQuestionType(data.jenisSoal||data.jenis_soal||data.questionType||'PEMAHAMAN'); if(!jenis) errors.push('Jenis soal tidak valid');
    const diff=normalizeQuestionDifficulty(data.tingkatKesulitan||data.tingkat_kesulitan||'SEDANG'); if(!diff) errors.push('Tingkat kesulitan harus Mudah, Sedang, Sulit, atau Kompleks');
    const cognitive=normalizeCognitiveProcess(data.prosesKognitif||data.proses_kognitif||data.tipeHots||data.tipe_hots, data.levelHots ?? data.level_hots) || 'LOTS';
    const statusKeabsahan=String(data.statusKeabsahan||data.status_keabsahan||'').trim().toUpperCase();
    if(statusKeabsahan && !['RESMI','ADAPTASI','MANDIRI'].includes(statusKeabsahan)) errors.push('Status keabsahan harus RESMI, ADAPTASI, atau MANDIRI');
    const tahun=data.tahun; if(tahun!==undefined && tahun!==null && String(tahun).trim() && !/^\d{4}$/.test(String(tahun).trim())) errors.push('Tahun harus 4 digit');
    return {valid:errors.length===0,errors,jenis_soal:jenis,tingkat_kesulitan:diff,proses_kognitif:cognitive};
}


// ============================================================
// TAHAP 6 — VALIDATOR SOAL TERINTEGRASI
// ============================================================
function validateQuestionFull(data = {}) {
    const base = validateQuestionContract(data);
    const errors = [...base.errors], warnings = [];
    const sourceStatus = String(data.statusKeabsahan || data.status_keabsahan || '').trim().toUpperCase();
    const sourceLink = String(data.sumberLink || data.sumber_link || '').trim();
    const sourceName = String(data.namaSumber || data.nama_sumber || '').trim();
    const sourceId = String(data.sumberBelajarId || data.sumber_belajar_id || '').trim();
    if (sourceStatus && !QUESTION_SOURCE_STATUSES.includes(sourceStatus)) errors.push('Status sumber tidak valid');
    if (sourceStatus === 'RESMI' && !sourceLink && !sourceId && !sourceName) errors.push('Soal RESMI wajib memiliki sumber/link yang dapat ditelusuri');
    if (sourceStatus === 'ADAPTASI' && !sourceLink && !sourceId && !sourceName) warnings.push('Soal ADAPTASI belum memiliki referensi sumber');
    if (sourceStatus === 'MANDIRI' && sourceLink) warnings.push('Soal MANDIRI memiliki link sumber; pastikan link hanya referensi, bukan klaim sumber resmi');
    const answer = String(data.jawabanBenar || data.jawaban_benar || '').trim().toUpperCase();
    const options = ['A','B','C','D','E'].map(k => String(data[`pilihan${k}`] ?? data[`pilihan_${k.toLowerCase()}`] ?? '').trim());
    const multipleCorrect = data.multipleCorrect === true || data.multiple_correct === true;
    if (multipleCorrect) errors.push('Soal pilihan ganda harus memiliki satu jawaban benar');
    const ambiguous = /\b(mungkin|tergantung|kadang-kadang|paling tepat)\b/i.test(String(data.soal || data.soalText || '')) && !data.ambiguityAllowed;
    if (ambiguous) warnings.push('Periksa potensi ambiguitas pada redaksi soal');
    const formatValid = Boolean(String(data.soal || data.soalText || '').trim()) && options.every(Boolean);
    const optionsValid = new Set(options.map(x => x.toLowerCase().replace(/\s+/g,' '))).size === 5;
    const answerValid = ['A','B','C','D','E'].includes(answer);
    const metadataValid = Boolean(base.jenis_soal && base.tingkat_kesulitan);
    const sourceValid = !sourceStatus || QUESTION_SOURCE_STATUSES.includes(sourceStatus);
    const status = errors.length ? 'INVALID' : (warnings.length ? 'REVIEW' : 'VALID');
    return { valid: errors.length === 0, status, errors, warnings, flags: { formatValid, optionsValid, answerValid, metadataValid, sourceValid, ambiguity: ambiguous, duplicate: !optionsValid, multipleCorrect }, jenis_soal: base.jenis_soal, tingkat_kesulitan: base.tingkat_kesulitan };
}

async function recordQuestionValidation(db, soalId, validation, userId = null) {
    if (!soalId || !validation) return { success:false, error:'soalId dan validation wajib' };
    try {
        const id = await generateId(db, 'QV', 'question_validations');
        const now = new Date().toISOString();
        const f = validation.flags || {};
        await db.prepare(`INSERT INTO question_validations (id,soal_id,status,format_valid,options_valid,answer_valid,metadata_valid,source_valid,ambiguity_flag,duplicate_flag,multiple_correct_flag,errors,warnings,validated_by,validated_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)
            .bind(id,soalId,validation.status||'REVIEW',f.formatValid?1:0,f.optionsValid?1:0,f.answerValid?1:0,f.metadataValid?1:0,f.sourceValid?1:0,f.ambiguity?1:0,f.duplicate?1:0,f.multipleCorrect?1:0,JSON.stringify(validation.errors||[]),JSON.stringify(validation.warnings||[]),userId,now,now,now).run();
        return {success:true,id};
    } catch(e) { return {success:false,error:e.message}; }
}

// ============================================================
// TAHAP 7 — SUMBER, KEABSAHAN, PROVENANCE
// ============================================================
function validateQuestionProvenance(data = {}) {
    const status = String(data.statusKeabsahan || data.status_keabsahan || '').trim().toUpperCase();
    if (!QUESTION_SOURCE_STATUSES.includes(status)) return {valid:false,error:'Status keabsahan harus RESMI, ADAPTASI, atau MANDIRI'};
    const link = String(data.sumberLink || data.sumber_link || '').trim();
    if (link && !/^https?:\/\//i.test(link)) return {valid:false,error:'sumber_link harus URL http/https atau dikosongkan'};
    if (status === 'RESMI' && !link && !data.sumberBelajarId && !data.sumber_belajar_id && !data.namaSumber && !data.nama_sumber) return {valid:false,error:'Sumber RESMI wajib dapat ditelusuri'};
    return {valid:true,status,source_id:data.sumberBelajarId||data.sumber_belajar_id||null,source_name:data.namaSumber||data.nama_sumber||null,source_link:link||null,tahun:data.tahun||null};
}
async function saveQuestionProvenance(db, soalId, data = {}, userId = null) {
    const v = validateQuestionProvenance(data); if(!v.valid) return {success:false,error:v.error};
    try {
        await db.prepare(`UPDATE question_sources SET is_current=0,updated_at=? WHERE soal_id=? AND is_current=1`).bind(new Date().toISOString(),soalId).run();
        const id=await generateId(db,'QS','question_sources'), now=new Date().toISOString();
        await db.prepare(`INSERT INTO question_sources (id,soal_id,status_keabsahan,source_id,source_name,source_link,tahun,origin_note,validation_note,validated_by,validated_at,is_current,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)
          .bind(id,soalId,v.status,v.source_id,v.source_name,v.source_link,v.tahun,data.originNote||data.origin_note||null,data.validationNote||data.validation_note||null,userId,now,1,now,now).run();
        return {success:true,id};
    } catch(e){return {success:false,error:e.message};}
}

// ============================================================
// TAHAP 8 — QUESTION ARTIFACT CLEANUP / HARD DELETE GUARD
// ============================================================
async function deleteQuestionWithArtifacts(db, soalId, userId=null, reason='HARD_DELETE') {
    if(!soalId) return {success:false,error:'soalId wajib'};
    try {
        const row=await db.prepare(`SELECT id FROM soal WHERE id=? LIMIT 1`).bind(soalId).first();
        if(!row) return {success:false,error:'Soal tidak ditemukan'};
        // Artifact tables tied directly to soal_id must not become orphaned.
        const artifactTables=['question_validations','question_sources','question_revisions','admin_review','feedback_admin'];
        for(const table of artifactTables){
            try{await db.prepare(`DELETE FROM ${table} WHERE soal_id=?`).bind(soalId).run();}catch(e){console.warn(`cleanup ${table} ${soalId}:`,e.message);}
        }
        const result=await db.prepare(`DELETE FROM soal WHERE id=?`).bind(soalId).run();
        return {success:true,changes:result.meta?.changes||0,soalId,reason};
    } catch(e){return {success:false,error:e.message,soalId};}
}
async function auditQuestionArtifactOrphans(db) {
    const tables=['question_validations','question_sources','question_revisions','admin_review','feedback_admin'];
    const report={orphaned:{},errors:{}};
    for(const table of tables){
        try{
            const r=await db.prepare(`SELECT COUNT(*) AS total FROM ${table} a LEFT JOIN soal s ON s.id=a.soal_id WHERE s.id IS NULL`).first();
            report.orphaned[table]=Number(r?.total||0);
        }catch(e){report.errors[table]=e.message;}
    }
    return report;
}

// ============================================================
// TAHAP 8 — QUESTION BANK / REVISI / DUPLIKAT / ARCHIVE
// ============================================================
function normalizeQuestionBankStatus(value) { const v=String(value||'').trim().toUpperCase(); return QUESTION_BANK_STATUSES.includes(v)?v:null; }
function normalizeDuplicateText(x){return String(x??'').trim().toLowerCase().replace(/\s+/g,' ');}
function questionFingerprint(data={}) { return [data.soal,data.pilihan_a||data.pilihanA,data.pilihan_b||data.pilihanB,data.pilihan_c||data.pilihanC,data.pilihan_d||data.pilihanD,data.pilihan_e||data.pilihanE,data.jawaban_benar||data.jawabanBenar||data.jawaban].map(normalizeDuplicateText).join('|'); }
function substantiveQuestionFingerprint(data={}) {
    const choices={A:data.pilihan_a||data.pilihanA||'',B:data.pilihan_b||data.pilihanB||'',C:data.pilihan_c||data.pilihanC||'',D:data.pilihan_d||data.pilihanD||'',E:data.pilihan_e||data.pilihanE||''};
    const key=String(data.jawaban_benar||data.jawabanBenar||data.jawaban||'').trim().toUpperCase();
    const answerContent=choices[key]!==undefined?choices[key]:key;
    return `${normalizeDuplicateText(data.soal)}|${normalizeDuplicateText(answerContent)}`;
}
async function findDuplicateQuestions(db, data={}, excludeId=null) {
    if(!normalizeDuplicateText(data.soal)) return [];
    try {
        const q=`SELECT id,soal,pilihan_a,pilihan_b,pilihan_c,pilihan_d,pilihan_e,jawaban_benar,status,jenis_soal,tingkat_kesulitan FROM soal WHERE status <> 'ARSIP' AND id <> ? ORDER BY id LIMIT 200`;
        const rows=(await db.prepare(q).bind(excludeId||'').all()).results||[];
        const exact=questionFingerprint(data); const substantive=substantiveQuestionFingerprint(data);
        return rows.map(r=>{
            const ef=questionFingerprint(r), sf=substantiveQuestionFingerprint(r);
            const type=ef===exact?'EXACT':(sf===substantive?'SUBSTANTIVE':null);
            return type?{...r,duplicate_type:type}:null;
        }).filter(Boolean);
    } catch(e){return [];}
}
function duplicateSummary(duplicates=[]){return duplicates.map(x=>`${x.id} (${x.duplicate_type||'UNKNOWN'})`).join(', ');}
async function createQuestionRevision(db, soalId, changeType='UPDATE', changeNote='', userId=null) {
    if(!soalId) return {success:false,error:'soalId wajib'};
    try {
        const row=await db.prepare(`SELECT * FROM soal WHERE id=? LIMIT 1`).bind(soalId).first(); if(!row) return {success:false,error:'Soal tidak ditemukan'};
        const last=await db.prepare(`SELECT COALESCE(MAX(version_no),0) AS v FROM question_revisions WHERE soal_id=?`).bind(soalId).first();
        const version=Number(last?.v||0)+1, now=new Date().toISOString(), id=await generateId(db,'QR','question_revisions');
        await db.prepare(`UPDATE question_revisions SET is_current=0 WHERE soal_id=?`).bind(soalId).run();
        await db.prepare(`INSERT INTO question_revisions (id,soal_id,version_no,snapshot,change_type,change_note,created_by,created_at,is_current) VALUES (?,?,?,?,?,?,?,?,1)`).bind(id,soalId,version,JSON.stringify(row),changeType,changeNote,userId,now).run();
        return {success:true,id,version};
    } catch(e){return {success:false,error:e.message};}
}
async function setQuestionBankStatus(db, soalId, status, userId=null, note='') {
    const s=normalizeQuestionBankStatus(status); if(!s) return {success:false,error:'Status question bank tidak valid'};
    try {
        const now=new Date().toISOString();
        const patch={status:s==='ARSIP'?'ARSIP':(s==='PUBLISH'?'AKTIF':'AKTIF'),status_ketersediaan:s.toLowerCase(),updated_by:userId};
        if(s==='ARSIP'){patch.kategori_arsip='LAINNYA';patch.tanggal_arsip=now;}
        else {patch.kategori_arsip=null;patch.tanggal_arsip=null;}
        const r=await updateQuestionBankRecord(db,soalId,patch,userId,note||`STATUS: ${s}`);
        return {...r,status:s};
    } catch(e){return {success:false,error:e.message};}
}
async function getQuestionBank(db, filters={}) {
    const where=[],params=[]; const add=(sql,v)=>{if(v!==undefined&&v!==null&&v!==''){where.push(sql);params.push(v)}};
    add('s.jenis_soal = ?',filters.jenis_soal||filters.jenisSoal);
    add('s.tingkat_kesulitan = ?',filters.tingkat_kesulitan||filters.tingkatKesulitan);
    add('s.kategori_id = ?',filters.kategori_id||filters.kategoriId);
    add('s.bidang_studi_id = ?',filters.bidang_studi_id||filters.bidangStudiId);
    add('s.program_studi_id = ?',filters.program_studi_id||filters.programStudiId);
    add('s.mata_pelajaran_id = ?',filters.mata_pelajaran_id||filters.mataPelajaranId);
    add('s.mata_kuliah_id = ?',filters.mata_kuliah_id||filters.mataKuliahId);
    add('s.jenjang_id = ?',filters.jenjang_id||filters.jenjangId);
    add('s.kelas = ?',filters.kelas||filters.kelasId);
    add('s.topik_id = ?',filters.topik_id||filters.topikId);
    add('s.sub_topik_id = ?',filters.sub_topik_id||filters.subTopikId);
    add('s.kisi_kisi_id = ?',filters.kisi_kisi_id||filters.kisiKisiId);
    add('s.kemampuan_id = ?',filters.kemampuan_id||filters.kemampuanId);
    add('s.sub_kemampuan_id = ?',filters.sub_kemampuan_id||filters.subKemampuanId);
    add('s.sumber_belajar_id = ?',filters.sumber_belajar_id||filters.sumberBelajarId);
    add('s.tahun = ?',filters.tahun);
    add('s.status_keabsahan = ?',filters.status_keabsahan||filters.statusKeabsahan);
    add('s.status_ketersediaan = ?',filters.status_ketersediaan||filters.statusKetersediaan);
    add('s.status = ?',filters.status);
    add('s.kompleksitas = ?',filters.kompleksitas);
    add('s.tahap_pembelajaran_id = ?',filters.tahapId||filters.tahap_pembelajaran_id);
    // LEGACY level_hots is intentionally not a source-of-truth filter.
    // Use LOTS/MOTS/HOTS through tipe_hots/prosesKognitif.
    add('s.tipe_hots = ?',filters.prosesKognitif||filters.proses_kognitif||filters.tipeHots||filters.tipe_hots);
    if(!filters.status) where.push("s.status <> 'ARSIP'");
    if(filters.keyword){where.push('(LOWER(s.soal) LIKE ? OR LOWER(COALESCE(s.pembahasan,\'\')) LIKE ?)');const k='%'+String(filters.keyword).toLowerCase()+'%';params.push(k,k)}
    const sortMap={terbaru:'s.updated_at DESC,s.id DESC',terlama:'s.updated_at ASC,s.id ASC',id:'s.id ASC',acak:'RANDOM()'};
    const order=sortMap[String(filters.sort||'terbaru').toLowerCase()]||sortMap.terbaru;
    const limit=Math.min(100,Math.max(1,Number(filters.limit)||20)),offset=Math.max(0,Number(filters.offset)||0); params.push(limit,offset);
    try { const r=await db.prepare(`SELECT s.*,tp.nama AS tahap_nama,lp.nama AS lapisan_nama,sb.nama AS sumber_nama FROM soal s LEFT JOIN tahap_pembelajaran tp ON s.tahap_pembelajaran_id=tp.id LEFT JOIN lapisan_pembelajaran lp ON s.lapisan_pembelajaran_id=lp.id LEFT JOIN sumber_belajar sb ON s.sumber_belajar_id=sb.id WHERE ${where.join(' AND ')} ORDER BY ${order} LIMIT ? OFFSET ?`).bind(...params).all(); return r.results||[]; } catch(e){console.error('getQuestionBank:',e.message);return [];}
}


// ============================================================
// TAHAP 8 — REVISION RESTORE / BANK HELPERS
// ============================================================
async function restoreQuestionRevision(db, soalId, versionNo, userId=null) {
    try {
        const rev=await db.prepare(`SELECT * FROM question_revisions WHERE soal_id=? AND version_no=? LIMIT 1`).bind(soalId,Number(versionNo)).first();
        if(!rev) return {success:false,error:'Versi revisi tidak ditemukan'};
        const snapshot=JSON.parse(rev.snapshot||'{}'); const allowed=['soal','pilihan_a','pilihan_b','pilihan_c','pilihan_d','pilihan_e','jawaban_benar','pembahasan','alasan_a','alasan_b','alasan_c','alasan_d','alasan_e','jenis_soal','tingkat_kesulitan','kompleksitas','tahap_pembelajaran_id','tipe_hots','lapisan_pembelajaran_id','status_keabsahan','sumber_belajar_id','nama_sumber','sumber_link','tahun'];
        const fields=allowed.filter(k=>Object.prototype.hasOwnProperty.call(snapshot,k)); if(!fields.length)return{success:false,error:'Snapshot tidak memiliki field yang dapat dipulihkan'};
        const vals=fields.map(k=>snapshot[k]); const set=fields.map(k=>`${k}=?`).join(', '); vals.push(new Date().toISOString(),soalId);
        await db.prepare(`UPDATE soal SET ${set},updated_at=? WHERE id=?`).bind(...vals).run();
        await createQuestionRevision(db,soalId,'RESTORE',`Pulihkan versi ${versionNo}`,userId);
        return {success:true,version:Number(versionNo)};
    } catch(e){return{success:false,error:e.message};}
}

// ============================================================
// TAHAP 8 — QUESTION BANK SERVICE LENGKAP
// ============================================================
async function getQuestionById(db, soalId) {
    if (!soalId) return null;
    try {
        return await db.prepare(`SELECT s.*, qs.status_keabsahan AS source_status, qs.source_name, qs.source_link, qs.tahun AS source_tahun FROM soal s LEFT JOIN question_sources qs ON qs.soal_id=s.id AND qs.is_current=1 WHERE s.id=? LIMIT 1`).bind(soalId).first();
    } catch (e) { return null; }
}
async function getQuestionBankStats(db, filters = {}) {
    const rows = await getQuestionBank(db, {...filters, limit:100});
    const countBy = key => rows.reduce((m,r)=>{const k=String(r[key]??'KOSONG');m[k]=(m[k]||0)+1;return m;},{});
    return {total:rows.length, byJenisSoal:countBy('jenis_soal'), byDifficulty:countBy('tingkat_kesulitan'), byStatus:countBy('status'), byAvailability:countBy('status_ketersediaan'), byValidity:countBy('status_keabsahan')};
}
async function duplicateQuestionRecord(db, soalId, userId=null) {
    const source=await getQuestionById(db,soalId);
    if(!source) return {success:false,error:'Soal sumber tidak ditemukan'};
    const dup=await findDuplicateQuestions(db,source,soalId);
    if(dup.length) return {success:false,error:`Duplikat sudah ada: ${dup.map(x=>x.id).join(', ')}`,duplicates:dup};
    const id=await generateId(db,'Q','soal'), now=new Date().toISOString();
    const fields=['soal','pilihan_a','pilihan_b','pilihan_c','pilihan_d','pilihan_e','jawaban_benar','pembahasan','alasan_a','alasan_b','alasan_c','alasan_d','alasan_e','kategori_id','bidang_studi_id','program_studi_id','mata_pelajaran_id','mata_kuliah_id','topik_id','sub_topik_id','jenjang_id','kelas','kisi_kisi_id','kemampuan_id','sub_kemampuan_id','cara_penyajian_id','tipe_isi_id','kompleksitas','tahap_pembelajaran_id','tipe_hots','tingkat_kesulitan','lapisan_pembelajaran_id','sumber_belajar_id','nama_sumber','sumber_link','tahun','status_keabsahan','status_ketersediaan','status','tipe_soal','jenis_soal','tanggal_input','created_by','updated_by'];
    const values=fields.map(f=>source[f]??null); values[fields.indexOf('status')]='AKTIF'; values[fields.indexOf('status_ketersediaan')]='draft_ketersediaan'; values[fields.indexOf('tanggal_input')]=now; values[fields.indexOf('created_by')]=userId; values[fields.indexOf('updated_by')]=userId;
    try {
        const validation=validateQuestionFull(source);
        if(!validation.valid)return {success:false,error:`Validasi duplikat gagal: ${validation.errors.join(' ')}`};
        await db.prepare(`INSERT INTO soal (${fields.join(',')}) VALUES (${fields.map(()=>'?').join(',')})`).bind(id,...values).run();
        await recordQuestionValidation(db,id,validation,userId);
        await createQuestionRevision(db,id,'CREATE',`Duplikat dari ${soalId}`,userId);
        return {success:true,id,sourceId:soalId};
    } catch(e){return {success:false,error:e.message};}
}
async function updateQuestionBankRecord(db, soalId, patch={}, userId=null, note='') {
    const current=await getQuestionById(db,soalId); if(!current)return{success:false,error:'Soal tidak ditemukan'};
    const allowed=['soal','pilihan_a','pilihan_b','pilihan_c','pilihan_d','pilihan_e','jawaban_benar','pembahasan','alasan_a','alasan_b','alasan_c','alasan_d','alasan_e','jenis_soal','tingkat_kesulitan','kompleksitas','tahap_pembelajaran_id','tipe_hots','lapisan_pembelajaran_id','status_keabsahan','sumber_belajar_id','nama_sumber','sumber_link','tahun','kategori_id','bidang_studi_id','program_studi_id','mata_pelajaran_id','mata_kuliah_id','topik_id','sub_topik_id','jenjang_id','kelas','kisi_kisi_id','kemampuan_id','sub_kemampuan_id','cara_penyajian_id','tipe_isi_id','status','status_ketersediaan','kategori_arsip','tanggal_arsip','catatan_revisi','status_soal','validasi_oleh','tanggal_validasi','updated_by','image_file_id','video_file_id','audio_file_id'];
    const fields=allowed.filter(k=>Object.prototype.hasOwnProperty.call(patch,k)); if(!fields.length)return{success:false,error:'Tidak ada field yang dapat diperbarui'};
    const meaningfulFields=fields.filter(k=>k!=='updated_by');
    const sameValue=(a,b)=>a===b;
    const changedFields=meaningfulFields.filter(k=>!sameValue(current[k],patch[k]));
    if(!changedFields.length){
        return {success:true,id:soalId,noOp:true,changedFields:[],changes:0,version:null};
    }
    const merged={...current};
    for(const k of meaningfulFields) merged[k]=patch[k];
    const validation=validateQuestionFull(merged);
    if(!validation.valid)return{success:false,error:`Validasi gagal: ${validation.errors.join(' ')}`};
    const dup=await findDuplicateQuestions(db,merged,soalId); if(dup.length)return{success:false,error:`Perubahan menghasilkan duplikat: ${duplicateSummary(dup)}.`,duplicates:dup};
    const updateFields=[...changedFields];
    const vals=updateFields.map(k=>patch[k]);
    const nextUpdatedBy=Object.prototype.hasOwnProperty.call(patch,'updated_by') ? patch.updated_by : userId;
    updateFields.push('updated_by'); vals.push(nextUpdatedBy);
    vals.push(new Date().toISOString(),soalId);
    try {
        const rev=await createQuestionRevision(db,soalId,'UPDATE',note||'Perubahan question bank',userId); if(!rev.success)return rev;
        const result=await db.prepare(`UPDATE soal SET ${updateFields.map(k=>`${k}=?`).join(', ')},updated_at=? WHERE id=?`).bind(...vals).run();
        if(!(result.meta?.changes)) return {success:false,error:'Tidak ada perubahan pada soal',version:rev.version,changedFields};
        const qv=await recordQuestionValidation(db,soalId,validation,userId); if(!qv.success)return qv;
        return {success:true,id:soalId,version:rev.version,changes:result.meta?.changes||0,changedFields,noOp:false};
    } catch(e){return{success:false,error:e.message};}
}

function getAssessmentMethodPolicy(method) {
    const m=String(method||'POLA_TERPADU').toUpperCase();
    if(!ASSESSMENT_METHODS.includes(m)) return null;
    const policies={
        BERBASIS_MATERI:{showMaterialBeforeQuestions:true,showMaterialPerQuestion:false,showSecondStartPrompt:true,finalTimeUnderstanding:true},
        POLA_TERPADU:{showMaterialBeforeQuestions:false,showMaterialPerQuestion:true,showSecondStartPrompt:false,finalTimeUnderstanding:false},
        BERBASIS_EVALUASI:{showMaterialBeforeQuestions:false,showMaterialPerQuestion:false,showSecondStartPrompt:false,finalTimeUnderstanding:false,materialFromEvaluation:true}
    };
    return policies[m] ? {method:m,...policies[m]} : null;
}

// ============================================================
// TAHAP 9 — SKILL/MASTERY + ADAPTIVE + EVALUATION
// ============================================================

// ============================================================
async function getSkillMastery(db,userId,filters={}) {
    if(!userId)return[]; const where=['user_id=?'],params=[userId];
    if(filters.kemampuanId||filters.kemampuan_id){where.push('kemampuan_id=?');params.push(filters.kemampuanId||filters.kemampuan_id)}
    if(filters.subKemampuanId||filters.sub_kemampuan_id){where.push('sub_kemampuan_id=?');params.push(filters.subKemampuanId||filters.sub_kemampuan_id)}
    try{return (await db.prepare(`SELECT * FROM skill_mastery WHERE ${where.join(' AND ')} ORDER BY score DESC,updated_at DESC`).bind(...params).all()).results||[]}catch(e){return[];}
}
async function getWeakSkills(db,userId,limit=10){try{return(await getSkillMastery(db,userId)).filter(x=>Number(x.score||0)<75).sort((a,b)=>Number(a.score||0)-Number(b.score||0)).slice(0,Math.max(1,Number(limit)||10));}catch(e){return[];}}
function selectNextAdaptiveParameters(current={}, outcome={}) {
    const difficultyOrder=['MUDAH','SEDANG','SULIT','KOMPLEKS'];
    const stageOrder=['T1','T2','T3','T4','T5','T6','T7','T8','T9'];
    let d=normalizeQuestionDifficulty(current.difficulty||'SEDANG')||'SEDANG';
    const idx=difficultyOrder.indexOf(d);
    const score=Number(outcome.masteryScore??outcome.score??0);
    const time=Number(outcome.answerTimeSeconds??outcome.answer_time_seconds??0);
    const expected=Number(outcome.expectedTimeSeconds??90);
    const tooSlow=time>0 && time>expected*1.75;
    const fast=time>0 && time<=expected*0.75;
    if(outcome.isCorrect && score>=75 && !tooSlow && idx<difficultyOrder.length-1) d=difficultyOrder[idx+1];
    else if((outcome.isCorrect===false || tooSlow) && idx>0) d=difficultyOrder[idx-1];
    let stage=String(current.stage||outcome.stage||'T1').toUpperCase();
    if(!stageOrder.includes(stage)) stage='T1';
    const si=stageOrder.indexOf(stage);
    if(outcome.isCorrect && score>=85 && !tooSlow && si<stageOrder.length-1) stage=stageOrder[si+1];
    else if(outcome.isCorrect===false && si>0 && score<50) stage=stageOrder[si-1];
    const action=outcome.isCorrect
        ? (score>=90 && !tooSlow ? 'PENGAYAAN' : (fast && score>=75 ? 'LATIHAN' : 'EVALUASI'))
        : 'REMEDIAL';
    return {difficulty:d,stage,action,answerTimeSeconds:time,reason:tooSlow?'waktu terlalu lama':(fast?'waktu cepat':'hasil penguasaan')};
}
function buildEvaluationSummary(session, answers=[]) {
    const total=Number(session?.total_questions||answers.length||0),benar=answers.filter(a=>a.is_correct===1||a.isCorrect===true).length,salah=answers.filter(a=>a.is_correct===0||a.isCorrect===false).length,kosong=Math.max(0,total-benar-salah),nilai=total?Math.round(benar/total*10000)/100:0;
    const weak=[...new Set(answers.filter(a=>a.is_correct===0||a.isCorrect===false).map(a=>a.sub_kemampuan_id||a.subKemampuanId||a.kemampuan_id||a.kemampuanId).filter(Boolean))]; const learned=[...new Set(answers.filter(a=>a.is_correct===1||a.isCorrect===true).map(a=>a.sub_kemampuan_id||a.subKemampuanId||a.kemampuan_id||a.kemampuanId).filter(Boolean))];
    return {total,benar,salah,kosong,nilai,weak_concepts:weak,learned_concepts:learned};
}

function calculateMasteryScore(current=0, isCorrect=false, difficulty='SEDANG', answerTimeSeconds=0) {
    const weights={MUDAH:0.7,SEDANG:1,SULIT:1.2,KOMPLEKS:1.4}; const w=weights[normalizeQuestionDifficulty(difficulty)||'SEDANG']||1;
    const timePenalty=answerTimeSeconds>0?Math.min(0.15,answerTimeSeconds/6000):0; const delta=isCorrect?(8*w):( -6*w); return Math.max(0,Math.min(100,Number(current||0)+delta-timePenalty));
}
function masteryStatusFromScore(score){const n=Number(score)||0; return n>=90?'SANGAT_MENGUASAI':n>=75?'MENGUASAI':n>=50?'BERKEMBANG':'BELUM_DIKUASAI';}
async function recordSkillOutcome(db,data={}) {
    const userId=String(data.userId||'').trim(), kemampuanId=data.kemampuanId||data.kemampuan_id||null, subId=data.subKemampuanId||data.sub_kemampuan_id||null;
    if(!userId || (!kemampuanId&&!subId)) return {success:false,error:'userId dan kemampuan/sub-kemampuan wajib'};
    try {
      const keyField=subId?'sub_kemampuan_id':'kemampuan_id', key=subId||kemampuanId;
      const existing=await db.prepare(`SELECT * FROM skill_mastery WHERE user_id=? AND ${keyField}=? LIMIT 1`).bind(userId,key).first();
      const before=Number(existing?.score||0), beforeStatus=existing?.mastery_status||'BELUM_DIKUASAI'; const after=calculateMasteryScore(before,Boolean(data.isCorrect),data.difficulty,data.answerTimeSeconds); const afterStatus=masteryStatusFromScore(after); const now=new Date().toISOString();
      const id=existing?.id||await generateId(db,'SM','skill_mastery');
      const attempts=Number(existing?.attempts||0)+1, correct=Number(existing?.correct_count||0)+(data.isCorrect?1:0), wrong=Number(existing?.wrong_count||0)+(data.isCorrect?0:1); const avg=((Number(existing?.avg_time_seconds||0)*Number(existing?.attempts||0))+Number(data.answerTimeSeconds||0))/attempts;
      if(existing) await db.prepare(`UPDATE skill_mastery SET score=?,attempts=?,correct_count=?,wrong_count=?,avg_time_seconds=?,mastery_status=?,last_difficulty=?,last_stage=?,last_answer_at=?,updated_at=? WHERE id=?`).bind(after,attempts,correct,wrong,avg,afterStatus,data.difficulty||null,data.stage||null,now,now,id).run();
      else await db.prepare(`INSERT INTO skill_mastery (id,user_id,kemampuan_id,sub_kemampuan_id,score,attempts,correct_count,wrong_count,avg_time_seconds,mastery_status,last_difficulty,last_stage,last_answer_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,userId,kemampuanId,subId,after,attempts,correct,wrong,avg,afterStatus,data.difficulty||null,data.stage||null,now,now,now).run();
      const hid=await generateId(db,'SMH','skill_mastery_history'); await db.prepare(`INSERT INTO skill_mastery_history (id,user_id,kemampuan_id,sub_kemampuan_id,soal_id,session_id,is_correct,answer_time_seconds,difficulty,stage,score_before,score_after,mastery_before,mastery_after,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(hid,userId,kemampuanId,subId,data.soalId||null,data.sessionId||null,data.isCorrect?1:0,Number(data.answerTimeSeconds||0),data.difficulty||null,data.stage||null,before,after,beforeStatus,afterStatus,now).run();
      return {success:true,scoreBefore:before,scoreAfter:after,masteryBefore:beforeStatus,masteryAfter:afterStatus};
    } catch(e){return {success:false,error:e.message};}
}
async function upsertAdaptiveSession(db, data = {}) {
    const userId = String(data.userId || '').trim();
    if (!userId) return { success:false, error:'userId wajib' };
    const now = new Date().toISOString();
    const fields = [
        'mode','assessment_method','status','current_difficulty','current_stage','current_kemampuan_id',
        'current_sub_kemampuan_id','questions_answered','correct_count','wrong_count','weaknesses','mastered',
        'next_action','started_at','last_activity','completed_at','data'
    ];
    try {
        const existing = data.id ? await db.prepare(`SELECT id,user_id FROM adaptive_sessions WHERE id=? LIMIT 1`).bind(data.id).first() : null;
        if(existing && String(existing.user_id) !== userId) return {success:false,error:'Adaptive session bukan milik pengguna'};
        const id = existing?.id || await generateId(db,'ALS','adaptive_sessions');
        const values = [
            data.mode || 'LATIHAN', String(data.assessmentMethod || 'POLA_TERPADU').toUpperCase(), data.status || 'active',
            normalizeQuestionDifficulty(data.currentDifficulty || 'SEDANG') || 'SEDANG', data.currentStage || null,
            data.currentKemampuanId || null, data.currentSubKemampuanId || null,
            Math.max(0,Number(data.questionsAnswered||0)), Math.max(0,Number(data.correctCount||0)), Math.max(0,Number(data.wrongCount||0)),
            JSON.stringify(Array.isArray(data.weaknesses)?data.weaknesses:[]), JSON.stringify(Array.isArray(data.mastered)?data.mastered:[]),
            data.nextAction || 'LATIHAN', data.startedAt || now, now, data.completedAt || null,
            data.extra ? JSON.stringify(data.extra) : null
        ];
        if (existing) {
            await db.prepare(`UPDATE adaptive_sessions SET ${fields.map(f=>`${f}=?`).join(',')} WHERE id=?`).bind(...values,id).run();
        } else {
            await db.prepare(`INSERT INTO adaptive_sessions (id,user_id,${fields.join(',')}) VALUES (?, ?, ${fields.map(()=>'?').join(',')})`).bind(id,userId,...values).run();
        }
        return {success:true,id};
    } catch(e) { return {success:false,error:e.message}; }
}
async function recordAdaptiveEvent(db,data={}) { try { const id=await generateId(db,'ALE','adaptive_events'); await db.prepare(`INSERT INTO adaptive_events (id,session_id,user_id,event_type,soal_id,kemampuan_id,sub_kemampuan_id,difficulty_before,difficulty_after,stage_before,stage_after,action,reason,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,data.sessionId,data.userId,data.eventType||'ANSWER',data.soalId||null,data.kemampuanId||null,data.subKemampuanId||null,data.difficultyBefore||null,data.difficultyAfter||null,data.stageBefore||null,data.stageAfter||null,data.action||null,data.reason||null,new Date().toISOString()).run(); return {success:true,id}; } catch(e){return {success:false,error:e.message};} }
async function createEvaluationSession(db,data={}) {
    const userId=String(data.userId||'').trim();
    const type=String(data.type||'LATIHAN').toUpperCase(), method=String(data.assessmentMethod||'POLA_TERPADU').toUpperCase();
    const policy=getAssessmentMethodPolicy(method);
    if(!userId)return{success:false,error:'userId wajib'};
    if(!EVALUATION_TYPES.includes(type)||!policy)return{success:false,error:'Tipe evaluasi/metode tidak valid'};
    try{
        const id=await generateId(db,'ES','evaluation_sessions'),now=new Date().toISOString();
        const sessionData={...data,policy};
        await db.prepare(`INSERT INTO evaluation_sessions (id,user_id,type,assessment_method,status,total_questions,started_at,last_activity,data) VALUES (?,?,?,?,?,?,?,?,?)`).bind(id,userId,type,method,'active',Math.max(0,Number(data.totalQuestions||0)),now,now,JSON.stringify(sessionData)).run();
        await upsertAdaptiveSession(db,{id:data.adaptiveSessionId||null,userId,mode:type,assessmentMethod:method,status:'active',currentDifficulty:data.currentDifficulty||'SEDANG',currentStage:data.currentStage||null,currentKemampuanId:data.kemampuanId||null,currentSubKemampuanId:data.subKemampuanId||null,nextAction:'LATIHAN'});
        return{success:true,id,policy};
    }catch(e){return{success:false,error:e.message};}
}
function normalizeAnswerBoolean(value) {
    if (value === true || value === 1 || String(value).trim().toLowerCase() === 'true' || String(value).trim().toLowerCase() === 'ya') return true;
    if (value === false || value === 0 || String(value).trim().toLowerCase() === 'false' || String(value).trim().toLowerCase() === 'tidak') return false;
    return null;
}

async function recordEvaluationAnswer(db, data = {}) {
    const userId=String(data.userId||'').trim(), sessionId=String(data.sessionId||'').trim(), soalId=String(data.soalId||'').trim();
    if(!userId||!sessionId||!soalId) return {success:false,error:'userId, sessionId, dan soalId wajib'};
    const isCorrect = normalizeAnswerBoolean(data.isCorrect);
    if (data.isCorrect !== null && data.isCorrect !== undefined && isCorrect === null) return {success:false,error:'Nilai isCorrect tidak valid'};
    try {
        const session = await db.prepare(`SELECT * FROM evaluation_sessions WHERE id=? AND user_id=? LIMIT 1`).bind(sessionId,userId).first();
        if(!session) return {success:false,error:'Sesi evaluasi tidak ditemukan atau bukan milik pengguna'};
        if(String(session.status||'').toLowerCase() !== 'active') return {success:false,error:'Sesi evaluasi sudah tidak aktif'};
        const question = await db.prepare(`SELECT id FROM soal WHERE id=? LIMIT 1`).bind(soalId).first();
        if(!question) return {success:false,error:'Soal tidak ditemukan'};
        const existing = await db.prepare(`SELECT id FROM evaluation_answers WHERE session_id=? AND soal_id=? LIMIT 1`).bind(sessionId,soalId).first();
        if(existing) return {success:false,error:'Jawaban untuk soal ini sudah tercatat',id:existing.id};
        const id=await generateId(db,'EA','evaluation_answers'), now=new Date().toISOString();
        await db.prepare(`INSERT INTO evaluation_answers (id,session_id,user_id,soal_id,answer,is_correct,answer_time_seconds,difficulty,stage,kemampuan_id,sub_kemampuan_id,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`)
            .bind(id,sessionId,userId,data.answer||null,isCorrect===null?null:(isCorrect?1:0),Math.max(0,Number(data.answerTimeSeconds||0)),data.difficulty||null,data.stage||null,data.kemampuanId||null,data.subKemampuanId||null,now).run();
        const mastery = isCorrect === null ? {success:true,skipped:true} : await recordSkillOutcome(db,{...data,isCorrect,sessionId});
        const adaptive = selectNextAdaptiveParameters({difficulty:data.difficulty,stage:data.stage},{isCorrect,masteryScore:mastery.scoreAfter,answerTimeSeconds:data.answerTimeSeconds,stage:data.stage});
        if(isCorrect !== null) {
            const s=await db.prepare(`SELECT * FROM evaluation_sessions WHERE id=? LIMIT 1`).bind(sessionId).first();
            if(s){
                const answered=Number(s.answered_count||0)+1, correct=Number(s.correct_count||0)+(isCorrect?1:0), wrong=Number(s.wrong_count||0)+(!isCorrect?1:0);
                await db.prepare(`UPDATE evaluation_sessions SET answered_count=?,correct_count=?,wrong_count=?,last_activity=? WHERE id=?`).bind(answered,correct,wrong,now,sessionId).run();
            }
            await recordAdaptiveEvent(db,{sessionId,userId,eventType:'ANSWER',soalId,kemampuanId:data.kemampuanId,subKemampuanId:data.subKemampuanId,difficultyBefore:data.difficulty,difficultyAfter:adaptive.difficulty,stageBefore:data.stage,stageAfter:adaptive.stage,action:adaptive.action,reason:adaptive.reason});
            const adaptiveSession=await getAdaptiveSession(db,userId);
            if(adaptiveSession){
                await upsertAdaptiveSession(db,{...adaptiveSession,id:adaptiveSession.id,userId,status:'active',currentDifficulty:adaptive.difficulty,currentStage:adaptive.stage,currentKemampuanId:data.kemampuanId||adaptiveSession.current_kemampuan_id,currentSubKemampuanId:data.subKemampuanId||adaptiveSession.current_sub_kemampuan_id,questionsAnswered:Number(adaptiveSession.questions_answered||0)+1,correctCount:Number(adaptiveSession.correct_count||0)+(isCorrect?1:0),wrongCount:Number(adaptiveSession.wrong_count||0)+(!isCorrect?1:0),nextAction:adaptive.action});
            }
            const entityId=data.subKemampuanId||data.kemampuanId;
            if(entityId){await upsertUserProgress(db,{userId,entityType:data.subKemampuanId?'subkemampuan':'kemampuan',entityId,status:'BERJALAN',completedCount:0,totalCount:Number(data.totalCount||0),lastPosition:Number(data.position||0),lastScore:Number(mastery.scoreAfter||0),totalTimeSeconds:Number(data.answerTimeSeconds||0),progressPercent:Number(data.progressPercent||0)});}
        }
        return {success:true,id,mastery,adaptive};
    }catch(e){return{success:false,error:e.message};}
}
async function finalizeEvaluationSession(db, sessionId) {
    try {
        const s=await db.prepare(`SELECT * FROM evaluation_sessions WHERE id=? LIMIT 1`).bind(sessionId).first();
        if(!s) return {success:false,error:'Sesi tidak ditemukan'};
        if(String(s.status||'').toLowerCase() === 'completed') return {success:false,error:'Sesi sudah selesai'};
        const a=(await db.prepare(`SELECT COUNT(*) total,SUM(CASE WHEN is_correct=1 THEN 1 ELSE 0 END) benar,SUM(CASE WHEN is_correct=0 THEN 1 ELSE 0 END) salah,SUM(CASE WHEN is_correct IS NULL THEN 1 ELSE 0 END) kosong,COALESCE(SUM(answer_time_seconds),0) waktu FROM evaluation_answers WHERE session_id=?`).bind(sessionId).first())||{};
        const total=Number(s.total_questions||a.total||0), benar=Number(a.benar||0), salah=Number(a.salah||0), kosong=Math.max(0,total-benar-salah), waktu=Number(a.waktu||0);
        const nilai=total?Math.round((benar/total)*10000)/100:0, avg=total?Math.round((waktu/total)*100)/100:0;
        const answers=(await db.prepare(`SELECT * FROM evaluation_answers WHERE session_id=? ORDER BY created_at`).bind(sessionId).all()).results||[];
        const summary=buildEvaluationSummary({...s,total_questions:total},answers);
        const now=new Date().toISOString();
        await db.prepare(`UPDATE evaluation_sessions SET status='completed',answered_count=?,correct_count=?,wrong_count=?,unanswered_count=?,score=?,mastery_points=?,total_time_seconds=?,average_time_seconds=?,weak_concepts=?,learned_concepts=?,completed_at=?,last_activity=? WHERE id=?`)
            .bind(benar+salah,benar,salah,kosong,nilai,Math.round((summary.mastery_points||nilai)*100)/100,waktu,avg,JSON.stringify(summary.weak_concepts),JSON.stringify(summary.learned_concepts),now,now,sessionId).run();
        const adaptive=await getAdaptiveSession(db,s.user_id);
        if(adaptive)await upsertAdaptiveSession(db,{...adaptive,id:adaptive.id,userId:s.user_id,status:'completed',questionsAnswered:benar+salah,correctCount:benar,wrongCount:salah,nextAction:benar>=salah?'PENGAYAAN':'REMEDIAL',completedAt:now});
        return {success:true,...summary,total,benar,salah,kosong,nilai,waktu,avg};
    }catch(e){return{success:false,error:e.message};}
}

