async function getAdaptiveSession(db,userId,sessionId=null){
    try{const q=sessionId?`SELECT * FROM adaptive_sessions WHERE user_id=? AND id=? LIMIT 1`:`SELECT * FROM adaptive_sessions WHERE user_id=? AND status='active' ORDER BY last_activity DESC LIMIT 1`; const r=sessionId?await db.prepare(q).bind(userId,sessionId).first():await db.prepare(q).bind(userId).first(); if(!r)return null; for(const k of ['weaknesses','mastered','data']){if(r[k]){try{r[k]=JSON.parse(r[k]);}catch{}}} return r;}catch(e){return null;}
}
function classifyAdaptiveOutcome({isCorrect,score=0,answerTimeSeconds=0,expectedTimeSeconds=90}={}){
    const n=Number(score)||0,t=Number(answerTimeSeconds)||0,e=Math.max(1,Number(expectedTimeSeconds)||90);
    if(isCorrect===null||isCorrect===undefined)return 'SKIP';
    if(!isCorrect)return 'WRONG';
    if(n>=90&&t<=e*1.25)return 'MASTERED';
    if(n>=75)return 'PROGRESS';
    return 'PRACTICE';
}
async function recommendNextQuestion(db, data={}){
    const userId=String(data.userId||'').trim(); if(!userId)return{success:false,error:'userId wajib'};
    try{
        const weak=await getWeakSkills(db,userId,10), preferred=String(data.preferredDifficulty||data.difficulty||'').toUpperCase();
        const difficulty=normalizeQuestionDifficulty(preferred)||null;
        const where=['COALESCE(soal.status,\'\') NOT IN (\'ARSIP\',\'INACTIVE\')','COALESCE(soal.status_ketersediaan,\'\') != \'ARSIP\'']; const params=[];
        if(data.kemampuanId){where.push('soal.kemampuan_id=?');params.push(data.kemampuanId);} else if(data.subKemampuanId){where.push('soal.sub_kemampuan_id=?');params.push(data.subKemampuanId);} else if(weak.length){
            const weakSub=weak.filter(x=>x.sub_kemampuan_id), weakKem=weak.filter(x=>x.kemampuan_id), parts=[];
            if(weakSub.length){parts.push('soal.sub_kemampuan_id IN ('+weakSub.map(()=>'?').join(',')+')');params.push(...weakSub.map(x=>x.sub_kemampuan_id));}
            if(weakKem.length){parts.push('soal.kemampuan_id IN ('+weakKem.map(()=>'?').join(',')+')');params.push(...weakKem.map(x=>x.kemampuan_id));}
            if(parts.length)where.push('('+parts.join(' OR ')+')');
        }
        if(difficulty){where.push('UPPER(COALESCE(soal.tingkat_kesulitan,\'\'))=?');params.push(difficulty);}
        const limit=Math.min(20,Math.max(1,Number(data.limit)||1));
        const q=`SELECT soal.* FROM soal WHERE ${where.join(' AND ')} ORDER BY RANDOM() LIMIT ?`; params.push(limit);
        const r=await db.prepare(q).bind(...params).all(); return{success:true,items:r.results||[],strategy:weak.length?'WEAKNESS_FIRST':'GENERAL',difficulty};
    }catch(e){return{success:false,error:e.message};}
}

