function buildEvaluationReport(session, answers=[]){
    const summary=buildEvaluationSummary(session,answers);
    const times=answers.map(a=>Number(a.answer_time_seconds??a.answerTimeSeconds??0)).filter(n=>n>0);
    return {...summary,total_time_seconds:times.reduce((a,b)=>a+b,0),average_time_seconds:times.length?Math.round(times.reduce((a,b)=>a+b,0)/times.length*100)/100:0,mastery_points:summary.mastery_points??summary.nilai};
}
function buildMethodPresentation(method, context={}){
    const policy=getAssessmentMethodPolicy(method); if(!policy)return null;
    return {method:policy.method,showMaterialBeforeQuestions:policy.showMaterialBeforeQuestions,showMaterialPerQuestion:policy.showMaterialPerQuestion,showSecondStartPrompt:policy.showSecondStartPrompt,finalTimeUnderstanding:policy.finalTimeUnderstanding,materialFromEvaluation:Boolean(policy.materialFromEvaluation),timeUnderstandingSeconds:policy.finalTimeUnderstanding?Number(context.timeUnderstandingSeconds||0):null};
}
function buildEvaluationDerivedMaterial(answers=[]){
    const weak=[...new Set(answers.filter(a=>a.is_correct===0||a.isCorrect===false).map(a=>a.sub_kemampuan_id||a.subKemampuanId||a.kemampuan_id||a.kemampuanId).filter(Boolean))];
    const learned=[...new Set(answers.filter(a=>a.is_correct===1||a.isCorrect===true).map(a=>a.sub_kemampuan_id||a.subKemampuanId||a.kemampuan_id||a.kemampuanId).filter(Boolean))];
    return {focus:'REMEDIAL',weakConceptIds:weak,learnedConceptIds:learned,reason:weak.length?'Materi difokuskan pada konsep yang belum dikuasai.':'Materi penguatan dan pengayaan berdasarkan hasil evaluasi.'};
}

