// TAHAP 12 — USER PROFILE / PREFERENCES / PROGRESS / RECOVERY
// ============================================================
function normalizeUserPreferencePatch(patch={}){
    const out={};
    const mode=patch.learningMode||patch.learning_mode;if(mode){const mv=String(mode).toUpperCase();if(!LEARNING_MODES.includes(mv))return{valid:false,error:'Mode belajar tidak valid'};out.learning_mode=mv;}
    const method=patch.assessmentMethod||patch.assessment_method;if(method)out.assessment_method=String(method).toUpperCase();
    const stage=patch.defaultStage||patch.default_stage;if(stage){const sv=String(stage).toUpperCase();if(!Object.prototype.hasOwnProperty.call(TAHAP_PEMBELAJARAN,sv))return{valid:false,error:'Tahap pembelajaran tidak valid'};out.default_stage=sv;}
    const diff=patch.defaultDifficulty||patch.default_difficulty;if(diff){const dv=normalizeQuestionDifficulty(diff);if(!dv)return{valid:false,error:'Tingkat kesulitan tidak valid'};out.default_difficulty=dv;}
    for(const [a,b] of [['preferredCategoryId','preferred_category_id'],['preferredBidangId','preferred_bidang_id'],['preferredJenjangId','preferred_jenjang_id'],['preferredKelas','preferred_kelas'],['preferredMataPelajaranId','preferred_mata_pelajaran_id'],['preferredProgramStudiId','preferred_program_studi_id'],['preferredMataKuliahId','preferred_mata_kuliah_id']])if(patch[a]!==undefined)out[b]=patch[a]||null;
    if(patch.preferredSemester!==undefined||patch.preferred_semester!==undefined){const n=Number(patch.preferredSemester??patch.preferred_semester);if(!Number.isInteger(n)||n<1||n>14)return{valid:false,error:'Semester harus 1-14'};out.preferred_semester=n;}
    if(patch.settings!==undefined)out.settings=JSON.stringify(patch.settings||{});
    if(out.assessment_method&&!ASSESSMENT_METHODS.includes(out.assessment_method))return{valid:false,error:'Metode asesmen tidak valid'};
    return{valid:true,values:out};
}
async function getUserPreferences(db,userId){try{return await db.prepare(`SELECT * FROM user_preferences WHERE user_id=? LIMIT 1`).bind(userId).first()||null;}catch(e){return null;}}
async function updateUserPreferences(db,userId,patch={}){
    if(!userId)return{success:false,error:'userId wajib'};const v=normalizeUserPreferencePatch(patch);if(!v.valid)return{success:false,error:v.error};
    try{const now=new Date().toISOString(),existing=await getUserPreferences(db,userId),id=existing?.id||await generateId(db,'UP','user_preferences');
        const fields=Object.keys(v.values);if(!fields.length)return{success:true,id,changed:false};
        if(existing){fields.push('updated_at');const vals=[...Object.keys(v.values).map(k=>v.values[k]),now];await db.prepare(`UPDATE user_preferences SET ${fields.map(f=>`${f}=?`).join(',')} WHERE user_id=?`).bind(...vals,userId).run();}
        else{const fs=['id','user_id',...fields,'created_at','updated_at'];const vals=[id,userId,...fields.filter(f=>f!=='updated_at').map(f=>v.values[f]),now,now];await db.prepare(`INSERT INTO user_preferences (${fs.join(',')}) VALUES (${fs.map(()=>'?').join(',')})`).bind(...vals).run();}
        return{success:true,id,changed:true};
    }catch(e){return{success:false,error:e.message};}
}
async function upsertUserProgress(db,data={}){
    const userId=String(data.userId||'').trim(),entityType=String(data.entityType||'').trim().toLowerCase(),entityId=String(data.entityId||'').trim();if(!userId||!entityType||!entityId)return{success:false,error:'userId, entityType, entityId wajib'};
    const statuses=['BELUM_DIMULAI','BERJALAN','PAUSED','SELESAI'];let status=String(data.status||'BERJALAN').toUpperCase();if(!statuses.includes(status))return{success:false,error:'Status progress tidak valid'};
    try{const existing=await db.prepare(`SELECT id FROM user_learning_progress WHERE user_id=? AND entity_type=? AND entity_id=? LIMIT 1`).bind(userId,entityType,entityId).first();const id=existing?.id||await generateId(db,'ULP','user_learning_progress'),now=new Date().toISOString();const vals=[status,Math.max(0,Math.min(100,Number(data.progressPercent||0))),Math.max(0,Number(data.completedCount||0)),Math.max(0,Number(data.totalCount||0)),Math.max(0,Number(data.lastPosition||0)),Number(data.lastScore||0),Math.max(0,Number(data.totalTimeSeconds||0)),now,now,now];
        if(existing)await db.prepare(`UPDATE user_learning_progress SET status=?,progress_percent=?,completed_count=?,total_count=?,last_position=?,last_score=?,total_time_seconds=?,last_activity=?,updated_at=? WHERE id=?`).bind(...vals.slice(0,7),vals[7],vals[9],id).run();
        else await db.prepare(`INSERT INTO user_learning_progress (id,user_id,entity_type,entity_id,status,progress_percent,completed_count,total_count,last_position,last_score,total_time_seconds,last_activity,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,userId,entityType,entityId,...vals).run();
        return{success:true,id};
    }catch(e){return{success:false,error:e.message};}
}
async function getUserProgressSummary(db,userId,entityType=null){try{let q=`SELECT * FROM user_learning_progress WHERE user_id=?`,b=[userId];if(entityType){q+=' AND entity_type=?';b.push(String(entityType).toLowerCase());}q+=' ORDER BY updated_at DESC LIMIT 500';return(await db.prepare(q).bind(...b).all()).results||[];}catch(e){return[];}}
async function saveUserSessionSnapshot(db,data={}){
    if(!data.userId)return{success:false,error:'userId wajib'};try{const id=await generateId(db,'US','user_sessions'),now=new Date().toISOString(),ttl=Math.max(60,Number(data.ttlSeconds||3600));await db.prepare(`INSERT INTO user_sessions (id,user_id,telegram_id,action,data,started_at,last_activity,expires_at,created_at) VALUES (?,?,?,?,?,?,?,?,?)`).bind(id,data.userId,data.telegramId||null,data.action||null,JSON.stringify(data.session||data.data||{}),data.startedAt||now,now,new Date(Date.now()+ttl*1000).toISOString(),now).run();return{success:true,id};}catch(e){return{success:false,error:e.message};}}
async function updateUserSessionSnapshot(db,sessionId,data={}){
    if(!sessionId)return{success:false,error:'sessionId wajib'};try{const now=new Date().toISOString(),ttl=Math.max(60,Number(data.ttlSeconds||3600));const r=await db.prepare(`UPDATE user_sessions SET action=?,data=?,last_activity=?,expires_at=? WHERE id=?`).bind(data.action||null,JSON.stringify(data.session||data.data||{}),now,new Date(Date.now()+ttl*1000).toISOString(),sessionId).run();return{success:true,id:sessionId,changes:r.meta?.changes??0};}catch(e){return{success:false,error:e.message};}}
async function completeUserSession(db,sessionId){try{if(!sessionId)return{success:false,error:'sessionId wajib'};const existing=await db.prepare(`SELECT data FROM user_sessions WHERE id=? LIMIT 1`).bind(sessionId).first();if(!existing)return{success:false,error:'Session tidak ditemukan'};let payload={};try{payload=JSON.parse(existing.data||'{}')}catch{}payload.status='completed';const now=new Date().toISOString();const r=await db.prepare(`UPDATE user_sessions SET data=?,last_activity=?,expires_at=? WHERE id=?`).bind(JSON.stringify(payload),now,now,sessionId).run();return{success:true,changes:r.meta?.changes??0};}catch(e){return{success:false,error:e.message};}}
async function recoverUserSession(db,userId){try{const now=new Date().toISOString(),r=await db.prepare(`SELECT * FROM user_sessions WHERE user_id=? AND (expires_at IS NULL OR expires_at>?) ORDER BY last_activity DESC LIMIT 1`).bind(userId,now).first();if(!r)return null;let data={};try{data=JSON.parse(r.data||'{}')}catch{}return{...r,data};}catch(e){return null;}}
async function pauseUserLearning(db,userId,entityType,entityId,position=0){return upsertUserProgress(db,{userId,entityType,entityId,status:'PAUSED',lastPosition:position});}
async function resumeUserLearning(db,userId,entityType,entityId){const rows=await getUserProgressSummary(db,userId,entityType);const r=rows.find(x=>x.entity_id===entityId);return r?{success:true,resumeFrom:Number(r.last_position||0),progressPercent:Number(r.progress_percent||0),status:r.status}:{success:false,error:'Progress tidak ditemukan'};}


// ============================================================
// TAHAP 10-12 — ORCHESTRATOR & RECOVERY CONTRACT
// Satu pintu untuk alur belajar: start → answer → next → finish.
// ============================================================
async function startLearningSession(db, data = {}) {
    const userId = String(data.userId || '').trim();
    if (!userId) return { success:false, error:'userId wajib' };
    const type = String(data.type || data.mode || 'LATIHAN').toUpperCase();
    const method = String(data.assessmentMethod || 'POLA_TERPADU').toUpperCase();
    const policy = getAssessmentMethodPolicy(method);
    if (!EVALUATION_TYPES.includes(type)) return { success:false, error:'Tipe sesi tidak valid' };
    if (!policy) return { success:false, error:'Metode asesmen tidak valid' };
    const evaluation = await createEvaluationSession(db, {
        ...data, userId, type, assessmentMethod:method,
        totalQuestions:Math.max(0, Number(data.totalQuestions || 0)),
        currentDifficulty:data.currentDifficulty || data.difficulty || 'SEDANG',
        currentStage:data.currentStage || data.stage || 'T1'
    });
    if (!evaluation.success) return evaluation;
    const snapshot = await saveUserSessionSnapshot(db, {
        userId, telegramId:data.telegramId || null,
        action:'LEARNING_SESSION',
        session:{evaluationSessionId:evaluation.id,type,assessmentMethod:method,policy,status:'active'},
        ttlSeconds:data.ttlSeconds || 3600
    });
    if (!snapshot.success) return {success:false,error:snapshot.error,evaluation};
    return {...evaluation, userSessionId:snapshot.id};
}

async function submitLearningAnswer(db, data = {}) {
    const result = await recordEvaluationAnswer(db, data);
    if (!result.success) return result;
    const next = result.adaptive || selectNextAdaptiveParameters(
        {difficulty:data.difficulty || 'SEDANG',stage:data.stage || 'T1'},
        {isCorrect:data.isCorrect,masteryScore:result.mastery?.scoreAfter || 0,answerTimeSeconds:data.answerTimeSeconds}
    );
    return {...result,next};
}

async function finishLearningSession(db, sessionId, userId = null) {
    const result = await finalizeEvaluationSession(db, sessionId);
    if (!result.success) return result;
    if (userId) {
        const progressEntityId = result.learned_concepts?.[0] || result.weak_concepts?.[0];
        if (progressEntityId) {
            await upsertUserProgress(db, {
                userId, entityType:'kemampuan', entityId:progressEntityId,
                status:'SELESAI', progressPercent:100,
                completedCount:Number(result.benar || 0), totalCount:Number(result.total || 0),
                lastScore:Number(result.nilai || 0), totalTimeSeconds:Number(result.waktu || 0)
            });
        }
    }
    return result;
}

async function getLearningRecoveryState(db, userId) {
    if (!userId) return {success:false,error:'userId wajib'};
    const session = await recoverUserSession(db, userId);
    const progress = await getUserProgressSummary(db, userId);
    const adaptive = await getAdaptiveSession(db, userId);
    return {success:true,session,progress,adaptive};
}


