async function ensureLearningIndexes(db) {
    const statements = [
        `CREATE UNIQUE INDEX IF NOT EXISTS idx_user_learning_progress_unique ON user_learning_progress(user_id,entity_type,entity_id)`,
        `CREATE INDEX IF NOT EXISTS idx_skill_mastery_user_score ON skill_mastery(user_id,score)`,
        `CREATE INDEX IF NOT EXISTS idx_skill_mastery_user_sub ON skill_mastery(user_id,sub_kemampuan_id)`,
        `CREATE INDEX IF NOT EXISTS idx_adaptive_sessions_user_status ON adaptive_sessions(user_id,status,last_activity)`,
        `CREATE INDEX IF NOT EXISTS idx_adaptive_events_session ON adaptive_events(session_id,created_at)`,
        `CREATE INDEX IF NOT EXISTS idx_evaluation_answers_session ON evaluation_answers(session_id,created_at)`,
        `CREATE INDEX IF NOT EXISTS idx_evaluation_sessions_user_status ON evaluation_sessions(user_id,status,last_activity)`,
        `CREATE INDEX IF NOT EXISTS idx_user_sessions_user_activity ON user_sessions(user_id,last_activity)`
    ];
    const errors=[];
    for (const sql of statements) { try { await db.prepare(sql).run(); } catch(e) { errors.push(e.message); } }
    return {success:errors.length===0,errors};
}


