// ============================================================
// FIX B6: Flag global untuk menandai database sudah di-init
// ============================================================
let DB_INITIALIZED = false;

async function ensureDatabaseInitialized(db) {
    // Kalau sudah di-init di warm start ini, skip
    if (DB_INITIALIZED) return;
    
    try {
        // Cek tabel penanda (untuk cold start)
        const check = await db.prepare(
            `SELECT name FROM sqlite_master WHERE type='table' AND name='_db_init'`
        ).first();
        
        if (check) {
            // Tabel penanda ada → database sudah pernah di-init
            DB_INITIALIZED = true;
            return;
        }
        
        // Tabel penanda belum ada → init database
        console.log('🔧 Inisialisasi database (pertama kali)...');
        await initDatabase(db);
        
        // Buat tabel penanda
        await db.prepare(`
            CREATE TABLE IF NOT EXISTS _db_init (
                id INTEGER PRIMARY KEY,
                initialized_at TEXT
            )
        `).run();
        
        await db.prepare(`
            INSERT OR REPLACE INTO _db_init (id, initialized_at)
            VALUES (1, ?)
        `).bind(new Date().toISOString()).run();
        
        DB_INITIALIZED = true;
        console.log('✅ Database siap');
        
    } catch (e) {
        console.error('❌ Gagal init database:', e);
        DB_INITIALIZED = false;
        throw e;
    }
}



// ============================================================
// 🚀 HANDLER FETCH
// ============================================================

export default {
  async scheduled(event, env, ctx) {
    try {
      setRuntimeTelegramToken(env);
      const db=await getDatabase(env);
      if(db){
        await ensureDatabaseInitialized(db);
        await processDueAdminSchedules(env,db);
        await processDueUserLearningReminders(env,db);
      }
    }catch(e){console.error('scheduled handler:',e);}
  },
  async fetch(request, env) {
    setRuntimeTelegramToken(env);
    const configContract = validateConfigurationContract(env);
    if (!configContract.valid) console.error('❌ [CONFIG CONTRACT]', configContract.errors);
    else if (configContract.warnings.length) console.warn('⚠️ [CONFIG CONTRACT]', configContract.warnings);

    const corsHeaders = {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type'
    };

    if (request.method === 'OPTIONS') {
      return new Response(null, { headers: corsHeaders, status: 204 });
    }

    if (request.method === "POST") {
      try {
        const body = await request.json();
        const db = await getDatabase(env);
        
        // ============================================================
        // FIX B6: Pakai ensureDatabaseInitialized
        // (hanya jalan sekali saat cold start)
        // ============================================================
        if (db) {
            await ensureDatabaseInitialized(db);
            await processDueAdminSchedules(env, db);
            await processDueUserLearningReminders(env, db);
        }
            
        const message = body.message;
        const callbackQuery = body.callback_query;

        // ============================================================
        // TRIPAY WEBHOOK — signature wajib sebelum settlement
        // ============================================================
        const webhookPath = new URL(request.url).pathname;
        if (webhookPath === '/webhook/tripay' || webhookPath === '/api/webhook/tripay') {
            const rawBody = await request.clone().text();
            const secretCfg = resolveExternalCredential(env,'TRIPAY_WEBHOOK_SECRET','YOUR_TRIPAY_WEBHOOK_SECRET');
            const signature = request.headers.get('X-Callback-Signature') || body.signature || '';
            if (!secretCfg.configured) return new Response(JSON.stringify({ok:false,error:'TRIPAY_WEBHOOK_SECRET belum dikonfigurasi'}),{status:503,headers:{...corsHeaders,'Content-Type':'application/json'}});
            if (!(await verifyWebhookHmac(rawBody,signature,secretCfg.value))) return new Response(JSON.stringify({ok:false,error:'Signature webhook tidak valid'}),{status:401,headers:{...corsHeaders,'Content-Type':'application/json'}});
            const valid=validatePaymentWebhook(body,secretCfg.value);
            if(!valid.valid)return new Response(JSON.stringify({ok:false,error:valid.error}),{status:400,headers:{...corsHeaders,'Content-Type':'application/json'}});
            const ref=String(body.merchant_ref||body.reference||'').trim();
            const existing=await db.prepare(`SELECT * FROM system_payments WHERE merchant_ref=? LIMIT 1`).bind(ref).first();
            const webhookPayload={...body,token_amount:Number(body.token_amount||body.tokenAmount||body.token||0)||undefined};
            const up=await upsertPayment(db,{merchantRef:ref,userId:body.user_id||existing?.user_id||null,provider:'TRIPAY',amount:Number(body.amount||existing?.amount||0),status:valid.status,signature,payload:webhookPayload,paidAt:valid.status==='PAID'?new Date().toISOString():null,expiredAt:valid.status==='EXPIRED'?new Date().toISOString():null});
            if(!up.success)return new Response(JSON.stringify({ok:false,error:up.error}),{status:500,headers:{...corsHeaders,'Content-Type':'application/json'}});
            if(valid.status==='PAID'){
                const settled=await settlePaidPayment(db,{merchantRef:ref,tokenAmount:Number(body.token_amount||body.tokenAmount||0)});
                if(!settled.success)return new Response(JSON.stringify({ok:false,error:settled.error}),{status:500,headers:{...corsHeaders,'Content-Type':'application/json'}});
            }
            return new Response(JSON.stringify({ok:true,status:valid.status,merchant_ref:ref}),{status:200,headers:{...corsHeaders,'Content-Type':'application/json'}});
        }

        // ============================================================
        // HANDLE CALLBACK QUERY
        // ============================================================
        if (callbackQuery) {
            const chatId = callbackQuery.message?.chat?.id;
            const userId = callbackQuery.from.id;
            const data = callbackQuery.data;
            const callbackQueryId = callbackQuery.id;

            if (chatId) {
                setCallbackContext(callbackQuery);
                try {
                    await handleCallback(env, userId, data, chatId, callbackQueryId, callbackQuery);
                } catch (e) {
                    console.error('❌ handleCallback error:', e);
                    await smartMessage(chatId, `❌ Error: ${e.message}`);
                }
                setCallbackContext(null);
            }
            return new Response("OK", { status: 200, headers: corsHeaders });
        }

        // ============================================================
        // HANDLE MEDIA UPLOAD (photo, video, audio, voice, document)
        // ============================================================
        if (message && (message.photo || message.video || message.audio || message.voice || message.document)) {
            const chatId = message.chat.id;
            const userId = message.from.id;
            
            const session = await getSession(env, userId);
            const db = await getDatabase(env);
            
            // ============================================================
            // HELPER: Deteksi media dari message
            // ============================================================
            const detectMedia = () => {
                if (message.photo && message.photo.length > 0) {
                    return { 
                        fileId: message.photo[message.photo.length - 1].file_id, 
                        mediaType: 'image' 
                    };
                }
                if (message.video) {
                    return { fileId: message.video.file_id, mediaType: 'video' };
                }
                if (message.audio) {
                    return { fileId: message.audio.file_id, mediaType: 'audio' };
                }
                if (message.voice) {
                    return { fileId: message.voice.file_id, mediaType: 'audio' };
                }
                return { fileId: null, mediaType: null };
            };
            
            const { fileId, mediaType } = detectMedia();
            const caption = message.caption || null;
            
            // ============================================================
            // CASE 1: Upload media untuk SOAL
            // ============================================================
            if (session.action === 'upload_media' && session.soalId && db) {
                if (!fileId || !mediaType) {
                    return new Response("OK", { status: 200, headers: corsHeaders });
                }
                
                try {
                    const columnName = `${mediaType}_file_id`;
                    const mediaPatch = {[columnName]: fileId, updated_by: session.userId || userId};
                    const mediaResult = await updateQuestionBankRecord(db, session.soalId, mediaPatch, session.userId || userId, `UPLOAD_MEDIA: ${mediaType}`);
                    if (!mediaResult.success) throw new Error(mediaResult.error || 'Gagal memperbarui media soal');
                    
                    await smartMessage(chatId, 
                        `✅ *MEDIA BERHASIL DISIMPAN!*\n\n` +
                        `🆔 Soal: \`${session.soalId}\`\n` +
                        `📁 Jenis: ${mediaType.toUpperCase()}\n` +
                        `🔑 File ID: \`${fileId.substring(0, 30)}...\`\n` +
                        (caption ? `📝 Caption: ${caption}\n` : '') +
                        `\n💡 File ID Telegram sudah disimpan.\n` +
                        `💡 Saat soal ditampilkan, media akan otomatis terkirim.\n\n` +
                        `📤 Kirim media lain atau \`/upload_media\` untuk soal lain.`
                    );
                } catch (e) {
                    console.error('Upload media soal error:', e);
                    await smartMessage(chatId, `❌ Gagal simpan media: ${e.message}`);
                }
                
                return new Response("OK", { status: 200, headers: corsHeaders });
            }
            
            // ============================================================
            // CASE 2: Upload media untuk MATERI
            // ============================================================
            if (session.action === 'upload_media_materi' && session.materiId && db) {
                if (!fileId || !mediaType) {
                    return new Response("OK", { status: 200, headers: corsHeaders });
                }
                
                try {
                    const result = await saveMateriMedia(db, session.materiId, {
                        tahapKode: session.tahapKode || null,
                        mediaType: mediaType,
                        fileId: fileId,
                        caption: caption
                    });
                    
                    if (result.success) {
                        const tahapInfo = session.tahapKode 
                            ? `📖 Tahap: *${session.tahapKode}*`
                            : `🌐 Mode: *Global*`;
                        
                        await smartMessage(chatId, 
                            `✅ *MEDIA TERSIMPAN!*\n\n` +
                            `🆔 Media ID: \`${result.id}\`\n` +
                            `📁 Tipe: ${mediaType.toUpperCase()}\n` +
                            `📖 Materi: \`${session.materiId}\`\n` +
                            `${tahapInfo}\n` +
                            (caption ? `📝 Caption: ${caption}\n` : '') +
                            `\n📤 Kirim media lain atau ketik "skip" untuk selesai.`
                        );
                    } else {
                        await smartMessage(chatId, `❌ Gagal simpan media materi: ${result.error}`);
                    }
                } catch (e) {
                    console.error('Upload media materi error:', e);
                    await smartMessage(chatId, `❌ Error: ${e.message}`);
                }
                
                return new Response("OK", { status: 200, headers: corsHeaders });
            }
            
            // ============================================================
            // BATCH 3: UNIVERSAL DATA IMPORT CSV/XLSX
            // ============================================================
            if (session.action === 'universal_import_upload' && message.document) {
                try {
                    await previewUniversalImportUpload(env,userId,chatId,db,message.document.file_name,message.document.file_id);
                } catch(e) {
                    console.error('Universal import upload:',e);
                    await smartMessage(chatId,`❌ Import tidak dapat dipreview: ${e.message}`);
                }
                return new Response("OK", { status: 200, headers: corsHeaders });
            }

            // ============================================================
            // CASE 3: Upload CSV soal (document)
            // ============================================================
            if (session.uploadingSoal && message.document) {
                await handleFileUpload(env, userId, chatId, message.document);
                return new Response("OK", { status: 200, headers: corsHeaders });
            }

                        // ============================================================
            // D1 PORTABLE RESTORE — menerima *.jsonl.gz yang dibuat /backup_db
            // ============================================================
            if (message.document && message.document.file_name && /\.jsonl\.gz$/i.test(message.document.file_name)) {
                const restoreSession = await getSession(env,userId);
                if (!restoreSession.portableRestore?.armed) {
                    await smartMessage(chatId,'❌ Mode restore belum aktif. Jalankan /restore_db terlebih dahulu.');
                    return new Response("OK", { status: 200, headers: corsHeaders });
                }
                try {
                    const fileId=message.document.file_id, fileName=message.document.file_name;
                    const fr=await fetch(`https://api.telegram.org/bot${getTelegramToken(env)}/getFile?file_id=${fileId}`);
                    const fd=await fr.json();
                    if(!fd.ok) throw new Error(fd.description||'Gagal mengambil file dari Telegram.');
                    const dr=await fetch(`https://api.telegram.org/file/bot${getTelegramToken(env)}/${fd.result.file_path}`);
                    if(!dr.ok) throw new Error(`Download file gagal HTTP ${dr.status}`);
                    const bytes=new Uint8Array(await dr.arrayBuffer());
                    const raw=await gunzipBytes(bytes);
                    const firstLine=new TextDecoder().decode(raw).split(/\r?\n/).find(Boolean);
                    const manifest=firstLine?JSON.parse(firstLine):null;
                    if(!manifest || manifest.record_type!=='manifest' || manifest.format!==D1_PORTABLE_BACKUP_VERSION) throw new Error('Format D1 portable backup tidak valid.');
                    if(restoreSession.portableRestore.backupId && restoreSession.portableRestore.backupId!==manifest.backup_id) throw new Error(`Backup ID berbeda. Diharapkan ${restoreSession.portableRestore.backupId}, file ${manifest.backup_id}.`);
                    if(Number(manifest.chunk_rows||0) > FILE_ROW_LIMIT) throw new Error(`File backup melebihi batas ${FILE_ROW_LIMIT.toLocaleString('id-ID')} baris per file.`);
                    restoreSession.pendingPortableRestore={fileId,fileName,backupId:manifest.backup_id,manifest};
                    await saveSession(env,userId,restoreSession);
                    const table=manifest.table;
                    const cleared=restoreSession.portableRestore.restoredTables||[];
                    const action=cleared.includes(table)?'menambahkan part ke tabel':'MENGGANTI isi tabel sebelum memasukkan part pertama';
                    await sendInlineKeyboard(chatId,
                        `📥 *D1 BACKUP PART TERVALIDASI*\n\n`+
                        `🆔 Backup: ${manifest.backup_id}\n`+
                        `📦 Part: ${manifest.part}\n`+
                        `📋 Tabel: ${table}\n`+
                        `📊 Rows: ${manifest.chunk_rows||0}\n`+
                        `🔧 Aksi: ${action}\n\n`+
                        `⚠️ Pastikan file berasal dari /backup_db sebelum melanjutkan.`,
                        [[{text:'✅ RESTORE PART',callback_data:'portable_restore_yes'}],[{text:'❌ BATAL PART',callback_data:'portable_restore_no'}]]
                    );
                } catch(e) { console.error('portable restore upload:',e); await smartMessage(chatId,`❌ File backup tidak dapat divalidasi: ${e.message}`); }
                return new Response("OK", { status: 200, headers: corsHeaders });
            }

            // ============================================================
            // 🆕 FASE 3: UPLOAD FILE BACKUP JSON
            // Lokasi: fetch(), setelah CASE 3 upload CSV
            // ============================================================
            
            if (message.document && message.document.file_name && 
                message.document.file_name.endsWith('.json')) {
                
                try {
                    // Ambil info file
                    const fileId = message.document.file_id;
                    const fileName = message.document.file_name;
                    
                    await smartMessage(chatId, 
                        `📥 *Menerima file backup...*\n\n` +
                        `📁 File: ${fileName}\n` +
                        `⏳ Memproses...`
                    );
                    
                    // Download file
                    const fileResponse = await fetch(
                        `https://api.telegram.org/bot${getTelegramToken(env)}/getFile?file_id=${fileId}`
                    );
                    const fileData = await fileResponse.json();
                    
                    if (!fileData.ok) {
                        await smartMessage(chatId, `❌ Gagal download: ${fileData.description}`);
                        return new Response("OK", { status: 200, headers: corsHeaders });
                    }
                    
                    const filePath = fileData.result.file_path;
                    const downloadUrl = `https://api.telegram.org/file/bot${getTelegramToken(env)}/${filePath}`;
                    
                    const downloadResponse = await fetch(downloadUrl);
                    const jsonText = await downloadResponse.text();
                    
                    // Parse JSON
                    let backup;
                    try {
                        backup = JSON.parse(jsonText);
                    } catch (e) {
                        await smartMessage(chatId, `❌ File bukan JSON yang valid.`);
                        return new Response("OK", { status: 200, headers: corsHeaders });
                    }
                    
                    // Validasi struktur
                    if (!backup.data || !backup.metadata) {
                        await smartMessage(chatId, 
                            `❌ File backup tidak valid.\n\n` +
                            `💡 Pastikan file dibuat dari \`/backup_db\`.`
                        );
                        return new Response("OK", { status: 200, headers: corsHeaders });
                    }
                    
                    // Simpan di session
                    const session = await getSession(env, userId);
                    session.pendingRollback = {
                        backup: backup,
                        fileName: fileName,
                        uploadedAt: new Date().toISOString()
                    };
                    await saveSession(env, userId, session);
                    
                    // Tampilkan ringkasan
                    let msg = `✅ *FILE BACKUP DITERIMA!*\n`;
                    msg += `${DIVIDER}\n\n`;                    // ← PAKAI const DIVIDER
                    msg += `📁 File: ${fileName}\n`;
                    msg += `📅 Dibuat: ${backup.metadata.created_at ? new Date(backup.metadata.created_at).toLocaleString('id-ID') : '-'}\n`;
                    msg += `📊 Total baris: ${backup.metadata.total_rows || 0}\n`;
                    msg += `📋 Total tabel: ${backup.metadata.tables?.length || 0}\n\n`;
                    msg += `📊 *Detail tabel:*\n`;
                    
                    for (const t of (backup.metadata.tables || []).slice(0, 10)) {
                        msg += `   📁 ${t.name}: ${t.row_count} baris\n`;
                    }
                    if ((backup.metadata.tables || []).length > 10) {
                        msg += `   ... dan ${backup.metadata.tables.length - 10} lainnya\n`;
                    }
                    
                    msg += `\n⚠️ *PERHATIAN:*\n`;
                    msg += `Rollback akan MENGGANTI semua data saat ini.\n\n`;
                    msg += `💡 Backup otomatis akan dibuat sebelum rollback.\n\n`;
                    msg += `Yakin ingin rollback?`;
                    
                    const keyboard = [
                        [{ text: "🔄 YA, ROLLBACK", callback_data: "rollback_confirm_yes" }],
                        [{ text: "❌ BATAL", callback_data: "rollback_confirm_no" }]
                    ];
                    
                    await sendInlineKeyboard(chatId, msg, keyboard);
                    
                } catch (e) {
                    console.error('Upload backup error:', e);
                    await smartMessage(chatId, `❌ Error: ${e.message}`);
                }
                
                return new Response("OK", { status: 200, headers: corsHeaders });
            }
            
            // ============================================================
            // CASE 4: Document tanpa context — abaikan
            // ============================================================
            return new Response("OK", { status: 200, headers: corsHeaders });
        }

        // ============================================================
        // HANDLE TEXT MESSAGE
        // ============================================================
        if (message && message.text) {
          const chatId = message.chat.id;
          const userId = message.from.id;
          const text = message.text;

          // ============================================================
          // ENRICH USER DATA KE DATABASE
          // ============================================================
          const db = await getDatabase(env);
          if (db) {
              try {
                  const existingUser = await db.prepare(
                      `SELECT id, username, nama_lengkap FROM users WHERE telegram_id = ?`
                  ).bind(String(userId)).first();
                  
                  const username = message.from.username || null;
                  const namaLengkap = `${message.from.first_name || ''} ${message.from.last_name || ''}`.trim() || null;
                  
                  if (!existingUser) {
                      await registerUser(db, userId, {
                          username: username,
                          nama_lengkap: namaLengkap
                      });
                  } else {
                      if ((username && existingUser.username !== username) || 
                          (namaLengkap && existingUser.nama_lengkap !== namaLengkap)) {
                          await db.prepare(`
                              UPDATE users SET 
                                  username = COALESCE(?, username),
                                  nama_lengkap = COALESCE(?, nama_lengkap),
                                  updated_at = ?
                              WHERE telegram_id = ?
                          `).bind(username, namaLengkap, new Date().toISOString(), String(userId)).run();
                      }
                      await db.prepare(`
                          UPDATE users SET last_login = ? WHERE telegram_id = ?
                      `).bind(new Date().toISOString(), String(userId)).run();
                  }
              } catch (e) {
                  console.error('Enrich user error:', e);
              }
          }

                    // ============================================================
          // 🆕 FASE 6.19: PRIORITASKAN COMMAND (Fix: command dimakan input)
          // Lokasi: fetch(), sebelum // CHECK FOR MULTIPLE DELETE INPUT
          // ============================================================
          
          // Kalau text berawalan '/', SELALU proses sebagai command
          // (kecuali sedang menunggu input spesifik)
          const isSlashCommand = text.trim().startsWith('/');
          
          const session = await getSession(env, userId);
          const actionButuhInput = [
              'add_kategori', 'add_bidang', 'add_program', 'add_topik',
              'add_subtopik', 'add_kisi', 'add_kemampuan', 'add_subkemampuan',
              'edit_kategori', 'edit_bidang', 'edit_program', 'edit_topik',
              'edit_subtopik', 'edit_kisi', 'edit_kemampuan', 'edit_subkemampuan',
              'edit_soal', 'admin_edit_soal', 'admin_reject_reason',
              'upload_media', 'upload_media_materi', 'arsip_soal_multiple',
              'jenjang_add', 'jenjang_edit', 'save_soal_by_number',
              'ctx_add_topik', 'ctx_add_subtopik', 'ctx_add_kisi',
              'user_search', 'user_add', 'user_broadcast_input',
              'search_materi_topic', 'reorder_kategori', 'reorder_bidang',
              'reorder_program', 'reorder_topik', 'reorder_subtopik',
              'reorder_kisi', 'reorder_kemampuan', 'reorder_subkemampuan',
              'reorder_soal','ujian_add_form'
          ];
          
          // Kalau ini command slash DAN action TIDAK butuh input → proses command
          if (isSlashCommand && (!session.action || !actionButuhInput.includes(session.action))) {
              // Proses sebagai command
              const isCmd = await handleCommand(env, chatId, userId, text);
              if (isCmd) return new Response("OK", { status: 200, headers: corsHeaders });
          }
          
          // Kalau command slash TAPI action butuh input → ada 2 opsi:
          // (a) Kalau user ketik "skip" atau "batal" → lanjut ke input handler
          // (b) Kalau user ketik command lain → bisa jadi mereka mau batal
          if (isSlashCommand && session.action && actionButuhInput.includes(session.action)) {
              const lowerText = text.trim().toLowerCase();
              
              // Kalau bukan skip/batal, proses sebagai command (user mau ganti aktivitas)
              if (lowerText !== 'skip' && lowerText !== 'batal' && 
                  lowerText !== 'cancel') {
                  // Clear action lama & proses command baru
                  session.action = null;
                  session.tempData = null;
                  await saveSession(env, userId, session);
                  
                  const isCmd = await handleCommand(env, chatId, userId, text);
                  if (isCmd) return new Response("OK", { status: 200, headers: corsHeaders });
              }
          }

          // ============================================================
          // CHECK FOR MULTIPLE DELETE INPUT
          // ============================================================
          if (session.action && session.action.startsWith('delete_')) {
            if (!db) {
              await smartMessage(chatId, '❌ Database tidak tersedia.');
              await clearSession(env, userId);
              return new Response("OK", { status: 200, headers: corsHeaders });
            }

            const actionMap = {
              'delete_kategori_multiple': { table: 'kategori', idField: 'id', nameField: 'nama', prefix: 'K' },
              'delete_bidang_multiple': { table: 'bidang_studi', idField: 'id', nameField: 'nama', prefix: 'B' },
              'delete_program_multiple': { table: 'program_studi', idField: 'id', nameField: 'nama', prefix: 'P' },
              'delete_topik_multiple': { table: 'topik', idField: 'id', nameField: 'nama', prefix: 'T' },
              'delete_subtopik_multiple': { table: 'sub_topik', idField: 'id', nameField: 'nama', prefix: 'S' },
              'delete_kisi_multiple': { table: 'kisi_kisi', idField: 'id', nameField: 'judul', prefix: 'I' },
              'delete_soal_multiple': { table: 'soal', idField: 'id', nameField: 'soal', prefix: 'Q' }
            };

            const config = actionMap[session.action];
            if (config) {
              const items = await parseDeleteInput(db, text, config.table, config.idField, config.nameField);
              
              if (items.length === 0) {
                await smartMessage(chatId, '❌ Tidak ada item yang ditemukan.');
                await clearSession(env, userId);
                return new Response("OK", { status: 200, headers: corsHeaders });
              }

              let confirmMsg = `⚠️ *KONFIRMASI HAPUS*\n\nAnda akan menghapus ${items.length} item:\n\n`;
              items.slice(0, 10).forEach(item => {
                confirmMsg += `- ${item.id}: ${item[config.nameField]}\n`;
              });
              if (items.length > 10) {
                confirmMsg += `- ... dan ${items.length - 10} item lainnya\n`;
              }
              confirmMsg += `\nYakin? [✅ Ya] [❌ Batal]`;

              session.deleteItems = items;
              session.deleteConfig = config;
              session.step = 'confirm_delete';
              await saveSession(env, userId, session);

              const keyboard = [
                [{ text: "✅ Ya, Hapus", callback_data: "confirm_delete_yes" }],
                [{ text: "❌ Batal", callback_data: "confirm_delete_no" }]
              ];
              await sendInlineKeyboard(chatId, confirmMsg, keyboard);
              return new Response("OK", { status: 200, headers: corsHeaders });
            }
          }

          // ============================================================
          // HANDLE COMMAND
          // ============================================================
          const isCmd = await handleCommand(env, chatId, userId, text);
          if (isCmd) return new Response("OK", { status: 200, headers: corsHeaders });

          // ============================================================
          // HANDLE TEXT INPUT
          // ============================================================
          const userMessageId = message.message_id;
          const isInput = await handleTextInput(env, userId, text, chatId, userMessageId);
          if (isInput) return new Response("OK", { status: 200, headers: corsHeaders });

          return new Response("OK", { status: 200, headers: corsHeaders });
        }

        return new Response("OK", { status: 200, headers: corsHeaders });

      } catch (error) {
        const appError = error?.code ? error : createAppError(error?.message || 'Worker Error', 'WORKER_ERROR', error);
        logAppError('worker.fetch', appError);
        return new Response("Error: " + safeErrorMessage(appError), { status: 500, headers: corsHeaders });
      }
    }

    return new Response("🤖 Bot Admin Pembelajaran Aktif!\nKirim /start untuk menu", { status: 200, headers: corsHeaders });
  }
};
